      return {
        [6101703] = {
          Content = "“嗨，亲爱的旅人！请问你掉的是这个黄金提灯，还是这个木头提灯，又或者是这个普通提灯呢？”",
          DialogueId = 6101703,
          GUID = "0F4664A6",
          NextOptions = {
