          DialogueId = 6101807,
          GUID = "0F4675B6",
          IsKeyOption = true,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101808] = {
          Content = "我真的没空。",
          DialogueId = 6101808,
          GUID = "0F4675E0",
          IsKeyOption = true,
          NextDialogue = 6101809,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101809] = {
          Content = "“好吧，好吧，我也不是什么强人所难的坏家伙嘛。”\n“那我们下次再见！”",
