          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room319_Char01"
        },
        [6101909] = {
          Content = "从老人左手边的武器中挑选。",
          DialogueId = 6101909,
          GUID = "0F468672",
          IsKeyOption = true,
          NextDialogue = 6101911,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101910] = {
          Content = "从老人右手边的武器中挑选。",
          DialogueId = 6101910,
          GUID = "0F46869C",
          IsKeyOption = true,
          NextDialogue = 6101911,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101911] = {
          Content = "你将挑选的武器收入囊中。\n老人似乎已经忘了你的存在，只是一言不发地注视着手中的铁锤，似是陷入了思考。",
          DialogueId = 6101911,
          GUID = "0F4686C6",
          RougeTalkActorType = 3
        },
        [6102001] = {
          Content = "你听见金属撞击的声音。火花飞溅，融化在篝火的光明中。\n你循着声音的方向看去，老人在简陋的锻造台边用力挥动着铁锤，汗珠从他的额前滴落。",
          DialogueId = 6102001,
          GUID = "0F46958A",
          NextDialogue = 6102002,
          RougeTalkActorType = 3
        },
        [6102002] = {
          Content = "“年轻人，你好啊！”\n见到你，老人热情地打招呼。",
          DialogueId = 6102002,
          GUID = "0F4695B4",
          NextOptions = {
            [1] = 6102003
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room318_Char01"
        },
        [6102003] = {
          Content = "您好。",
          DialogueId = 6102003,
          GUID = "0F4695DE",
          NextDialogue = 6102004,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102004] = {
          Content = "“看样子，你也被困在这地方了吧？”老人指了指自己，“我也是。”",
          DialogueId = 6102004,
          GUID = "0F469608",
          NextOptions = {
            [1] = 6102005
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room318_Char01"
        },
        [6102005] = {
          Content = "我们又见面了。",
          DialogueId = 6102005,
          GUID = "0F469632",
          NextDialogue = 6102006,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102006] = {
          Content = "“我们见过面吗？”老人有些困惑，“我倒是不记得了，最近记性越来越差……”",
          DialogueId = 6102006,
          GUID = "0F46965C",
          NextDialogue = 6102007,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room318_Char01"
        },
        [6102007] = {
          Content = "“这地方危险，我造了些武器，你挑一件带走吧。”\n老人爽朗地向你展示他的作品。\n“我想着，横竖都找不到出去的路，不如做回老本行。说不定哪天，我造的武器能帮到某位了不得的骑士大人，把我们带出这个鬼地方。”",
          DialogueId = 6102007,
          GUID = "0F469686",
          NextOptions = {
            [1] = 6102008,
            [2] = 6102009,
            [3] = 6102010
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room318_Char01"
        },
        [6102008] = {
          Content = "从刚铸成的新武器中挑选。",
          DialogueId = 6102008,
          GUID = "0F4696B0",
          IsKeyOption = true,
          NextDialogue = 6102011,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102009] = {
          Content = "从排列整齐的成品中挑选。",
          DialogueId = 6102009,
          GUID = "0F4696DA",
          IsKeyOption = true,
          NextDialogue = 6102011,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102010] = {
          Content = "从蒙尘的储藏角落中挑选。",
          DialogueId = 6102010,
          GUID = "0F469704",
          IsKeyOption = true,
          NextDialogue = 6102011,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102011] = {
          Content = "带着挑选的武器，你在老人亲切的道别声中继续前进。",
          DialogueId = 6102011,
          GUID = "0F46972E",
          RougeTalkActorType = 3
        },
        [6102101] = {
          Content = "篝火明灭，勾勒出诗人低垂的侧脸。\n她半跪在篝火旁，伸出手指，在烟灰中缓缓勾勒出蜿蜒的纹路。",
          DialogueId = 6102101,
          GUID = "0F46A5F2",
          NextDialogue = 6102102,
          RougeTalkActorType = 3
        },
        [6102102] = {
          Content = "“若无处可逃，那便接受命运吧；”\n“若文字无法成为刺破谎言的利刃，那便让它成为砌筑美梦的砖瓦吧——”\n诗人停顿了一下，微微抬起指尖。\n“唔……”",
          DialogueId = 6102102,
          GUID = "0F46A61C",
          NextDialogue = 6102103,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room320_Char01"
        },
        [6102103] = {
          Content = "脑海中的回忆忽然被唤醒，你确信自己曾经听过这首诗。\n一缕烟灰拂过脸颊，几乎是下意识地，你轻声念出了那空缺的最后一句——",
          DialogueId = 6102103,
          GUID = "0F46A646",
          NextOptions = {
            [1] = 6102104
          },
          RougeTalkActorType = 3
        },
        [6102104] = {
          Content = "“书写一个谎言，点燃一束不熄的火光。”",
          DialogueId = 6102104,
          GUID = "0F46A670",
          NextDialogue = 6102105,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102105] = {
          Content = "“嗯……？！”\n诗人抬起头来，惊喜地看着你。\n“多么美妙的词句啊，这正是我想要的结尾！没想到竟能在这里遇上一位知己，真是幸运。”",
          DialogueId = 6102105,
          GUID = "0F46A69A",
          NextOptions = {
            [1] = 6102106
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room320_Char01"
        },
        [6102106] = {
          Content = "“其实这是另一个时间的你写下的。”",
          DialogueId = 6102106,
          GUID = "0F46A6C4",
          NextDialogue = 6102107,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102107] = {
          Content = "“‘另一个时间’……？”\n诗人先是露出讶异的神情，然后目光很快变得明亮，像是被那篝火点燃了一般。\n“原来如此……您是特别的——是这首叙事诗的主角，是我将在时间的其他方向再度遇见的人，对吗？”",
          DialogueId = 6102107,
          GUID = "0F46A6EE",
          NextOptions = {
            [1] = 6102108
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room320_Char01"
        },
        [6102108] = {
          Content = "点头。",
          DialogueId = 6102108,
          GUID = "0F46A718",
          NextDialogue = 6102109,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102109] = {
          Content = "“那么这句诗究竟算是您写的，还是我写的呢？呵呵……真是个迷人的疑问，我想圣树学院的学者们也会为您的故事倾倒。”\n诗人咯咯地笑起来。\n“下次见面的时候，还请允许我为您作一首诗。现在，请伸出手来，收下我的祝福吧。”",
          DialogueId = 6102109,
          GUID = "0F46A742",
          NextOptions = {
            [1] = 6102110,
            [2] = 6102111
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room320_Char01"
        },
        [6102110] = {
          Content = "伸出左手。",
          DialogueId = 6102110,
          GUID = "0F46A76C",
          IsKeyOption = true,
          NextDialogue = 6102112,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102111] = {
          Content = "伸出右手。",
          DialogueId = 6102111,
          GUID = "0F46A796",
          IsKeyOption = true,
          NextDialogue = 6102112,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102112] = {
          Content = "诗人用指尖残留的烟灰在你的手心写下了什么。\n你依旧无法理解这些文字的含义，但你能感觉到它鲜明的温度，热烈却不至于将人灼伤。\n当你再次抬头，诗人已经不知所踪。",
          DialogueId = 6102112,
          GUID = "0F46A7C0",
          RougeTalkActorType = 3
        },
        [6102201] = {
          Content = "“那无常的命运之神啊，时而令我们欢喜，时而令我们苦痛……”\n“常怀虔诚之心……祂洁白的纺线终会将我们与那众天之天的乐土连缀……”\n少年认真而虔诚地朗读着书本上的词句，对你的出现浑然不觉。",
          DialogueId = 6102201,
          GUID = "0F46B65A",
          NextDialogue = 6102202,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room321_Char01"
        },
        [6102202] = {
          Content = "你悄然走到少年身边，飞快地瞥了一眼他手中的书。\n如你记忆中那般，书页上的圣歌被充满恶意的漆黑文字覆盖。\n那文字扭动着，似要挣脱出纸面。",
          DialogueId = 6102202,
          GUID = "0F46B684",
          NextDialogue = 6102203,
          RougeTalkActorType = 3
        },
        [6102203] = {
          Content = "“您好……您也想看书吗？”\n少年终于注意到你，好奇地抬起了头。",
          DialogueId = 6102203,
          GUID = "0F46B6AE",
          NextOptions = {
            [1] = 6102204,
            [2] = 6102208
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room321_Char01"
        },
        [6102204] = {
          Content = "阻止他继续读下去。",
          DialogueId = 6102204,
          GUID = "0F46B6D8",
          IsKeyOption = true,
          NextDialogue = 6102205,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102205] = {
          Content = "你将那本书从少年的手中抽出，用力地合上。",
          DialogueId = 6102205,
          GUID = "0F46B702",
          NextDialogue = 6102206,
          RougeTalkActorType = 3
        },
        [6102206] = {
          Content = "“您没事吧？！”\n少年担忧地站起来，随机又茫然地看向自己空无一物的双手。\n“咦？我……不用再读书了吗？我……自由了吗？”",
          DialogueId = 6102206,
          GUID = "0F46B72C",
          NextDialogue = 6102207,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room321_Char01"
        },
        [6102207] = {
          Content = "你忍住指尖的痛楚，微笑着向他点了点头，然后将那本书扔进篝火里。\n火焰猛然升起，黑色的荆棘席卷着火舌一起向你袭来——",
          DialogueId = 6102207,
          GUID = "0F46B756",
          RougeTalkActorType = 3
        },
        [6102208] = {
          Content = "沉默。",
          DialogueId = 6102208,
          GUID = "0F46B780",
          IsKeyOption = true,
          NextDialogue = 6102209,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102209] = {
          Content = "你知道，无论你在此刻做出怎样的行动，都无法真正改变少年的命运。\n你还有更重要的事去做——收集琉璃，彻底结束这个漫长的噩梦。",
          DialogueId = 6102209,
          GUID = "0F46B7AA",
          NextDialogue = 6102210,
          RougeTalkActorType = 3
        },
        [6102210] = {
          Content = "顷刻间，黑色的荆棘蔓延，吞噬了少年的身影。\n你轻轻地叹息一声，继续前进。",
          DialogueId = 6102210,
          GUID = "0F46B7D4",
          RougeTalkActorType = 3
        },
        [6102301] = {
          Content = "“孩子……快看，这里有一堆篝火。”\n火光的对面，孑然一身的女人微笑着抬起头，火光映出她憔悴的容颜。\n“真暖和呀，谢谢您，好心的陌生人。”",
          DialogueId = 6102301,
          GUID = "0F46C6C2",
          NextOptions = {
            [1] = 6102302
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room322_Char01"
        },
        [6102302] = {
          Content = "询问她所说的孩子在哪里。",
          DialogueId = 6102302,
          GUID = "0F46C6EC",
          NextDialogue = 6102303,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102303] = {
          Content = "“我的孩子就在这里呀，您看。”",
          DialogueId = 6102303,
          GUID = "0F46C716",
          NextDialogue = 6102304,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room322_Char01"
        },
        [6102304] = {
          Content = "顺着女人示意的方向，你看到了一块半人高的、覆满青苔的岩石。\n在岩石中央偏上的部分，一枚亮闪闪的胸针被镶嵌在石缝间，四周爬满了细密的青苔围绕，如同一颗被埋葬的心。\n女人温柔地爱抚着岩石的表面，对手上沾染的泥土浑然不觉。",
          DialogueId = 6102304,
          GUID = "0F46C740",
          NextOptions = {
            [1] = 6102305,
            [2] = 6102308
          },
          RougeTalkActorType = 3
        },
        [6102305] = {
          Content = "指出真相。",
          DialogueId = 6102305,
          GUID = "0F46C76A",
          IsKeyOption = true,
          NextDialogue = 6102306,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102306] = {
          Content = "“您在胡说什么？！”\n女人的眼中瞬间升起尖锐的敌意，她紧紧地将那块岩石护在身后，歇斯底里地大叫起来。\n“这就是我的孩子……她就在这里，我再也不会让任何人带走她……不会……”",
          DialogueId = 6102306,
          GUID = "0F46C794",
          NextDialogue = 6102307,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room322_Char01"
        },
        [6102307] = {
          Content = "你一时哑然。\n或许不该戳破这个美梦的，你早知这毫无意义。\n于是你起身离开，将篝火留给了女人和她的“孩子”。与此同时，潜伏在黑暗中的幽影伺机向你袭来——",
          DialogueId = 6102307,
          GUID = "0F46C7BE",
          RougeTalkActorType = 3
        },
        [6102308] = {
          Content = "附和她。",
          DialogueId = 6102308,
          GUID = "0F46C7E8",
          IsKeyOption = true,
          NextDialogue = 6102309,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102309] = {
          Content = "“谢谢您。这孩子从小就怕生，但她好像很喜欢您呢。”\n女人语气和蔼，双手仍时不时轻抚那块岩石。\n“您是一个人出门的吗？这可不行，您的家人会担心的……快回家去吧。”",
          DialogueId = 6102309,
          GUID = "0F46C812",
          NextDialogue = 6102310,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room322_Char01"
        },
        [6102310] = {
          Content = "你礼貌地向她道谢，随后便起身继续前进。\n女人和她的“孩子”的身影，渐渐模糊在篝火的阴影中。",
          DialogueId = 6102310,
          GUID = "0F46C83C",
          RougeTalkActorType = 3
        },
        [6102401] = {
          Content = "“不见了……不见了……”\n少女睁着空洞的双眼，匍匐在地上摸索着，指甲几乎要嵌入地面。",
          DialogueId = 6102401,
          GUID = "0F46D72A",
          NextOptions = {
            [1] = 6102402
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room323_Char01"
        },
        [6102402] = {
          Content = "询问她在找什么。",
          DialogueId = 6102402,
          GUID = "0F46D754",
          NextDialogue = 6102403,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102403] = {
          Content = "“我的石头……石头……之前明明就在这里的……”\n她喃喃说着，几乎是绝望地注视着你脚下的篝火。\n“我的火焰……要熄灭了……怎么办……怎么办……”",
          DialogueId = 6102403,
          GUID = "0F46D77E",
          NextOptions = {
            [1] = 6102404,
            [2] = 6102408
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room323_Char01"
        },
        [6102404] = {
          Content = "帮助她。",
          DialogueId = 6102404,
          GUID = "0F46D7A8",
          IsKeyOption = true,
          NextDialogue = 6102405,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102405] = {
          Content = "你试着回忆她喜欢的那些石子的模样。虽然不确定它们的来历，但你判断用火焰魔法应该能制造出相似的东西。\n于是你试着利用篝火，凝聚力量——\n顷刻间，金黄色亮闪闪的小石头如同流星一般坠落，互相碰撞发出清脆悦耳的声响。",
          DialogueId = 6102405,
          GUID = "0F46D7D2",
          NextDialogue = 6102406,
          RougeTalkActorType = 3
        },
        [6102406] = {
          Content = "“啊……！我的石头——这就是我的石头！谢谢您，神明的使者！”\n少女如获至宝地一颗颗捡起那些石头，小心翼翼地用裙摆兜起来。",
          DialogueId = 6102406,
          GUID = "0F46D7FC",
          NextDialogue = 6102407,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room323_Char01"
        },
        [6102407] = {
          Content = "那些结晶确实和你此前在少女怀中见到的石子一模一样，你不禁开始怀疑它们是否从一开始就是你在某次旅途中不经意间留下的痕迹。\n无论如何，少女已经再次找回了她的“确定”，而你，也必须继续踏上旅途。",
          DialogueId = 6102407,
          GUID = "0F46D826",
          RougeTalkActorType = 3
        },
        [6102408] = {
          Content = "告诉她世事本就不可能一直如我们所愿。",
          DialogueId = 6102408,
          GUID = "0F46D850",
          IsKeyOption = true,
          NextDialogue = 6102409,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102409] = {
          Content = "“我知道……我知道。”\n“所以我已经放弃了……我不再看那些书，不再思考魔法的起源，也不再追问那座塔里有什么了……”\n“现在我想要的只是一片火光而已，连这也不可以吗？”",
          DialogueId = 6102409,
          GUID = "0F46D87A",
          NextDialogue = 6102410,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room323_Char01"
        },
        [6102410] = {
          Content = "你无言以对。\n少女忽然站了起来，在你来得及做出反应之前，毅然踏进了火焰之中。\n慢慢地，少女的身影与火光融为一体，消失不见。\n你转过身，继续踏上旅途。",
          DialogueId = 6102410,
          GUID = "0F46D8A4",
          RougeTalkActorType = 3
        },
        [6102501] = {
          Content = "篝火安静地燃烧着，这一次你并未看到任何幻象。\n就在你打算离去的时候，地面上一些闪闪发光的东西引起了你的注意——\n那是一些金黄色的小石子，一颗一颗散落在地，仿若坠入凡尘的星星。",
          DialogueId = 6102501,
          GUID = "0F46E792",
          NextOptions = {
            [1] = 6102502,
            [2] = 6102506
          },
          RougeTalkActorType = 3
        },
        [6102502] = {
          Content = "捡起石子扔进火焰中。",
          DialogueId = 6102502,
          GUID = "0F46E7BC",
          IsKeyOption = true,
          NextDialogue = 6102503,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102503] = {
          Content = "火焰越烧越旺，然后开始反常地向侧面延伸。\n你谨慎地退后了一步，忽然间，一个身影从火焰中显现出来，你这才看清楚，那向侧面延伸的光芒并非火焰，而是少女的发丝。",
          DialogueId = 6102503,
          GUID = "0F46E7E6",
          NextDialogue = 6102504,
          RougeTalkActorType = 3
        },
        [6102504] = {
          Content = "“您好！您发现了我的小石子，是吗？”\n少女从篝火中跳出来，晃了晃脑袋，金色的石子噼里啪啦地坠落在地。\n“我再也不用去外面找了——您看，只要走进这火里，我就可以自己制造小石子了！”",
          DialogueId = 6102504,
          GUID = "0F46E810",
          NextDialogue = 6102505,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room324_Char01"
        },
        [6102505] = {
          Content = "“请原谅我没有时间与您多作寒暄——我还没有收集满一百四十六颗呢。”\n“不过我倒是发现了一些或许对您有用的东西或许，请收下吧，祝您旅途顺利！”\n少女将什么东西塞到你的手中，然后转身消失在了火焰里。",
          DialogueId = 6102505,
          GUID = "0F46E83A",
          NextDialogue = 6102510,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room324_Char01"
        },
        [6102506] = {
          Content = "安静地观察。",
          DialogueId = 6102506,
          GUID = "0F46E864",
          IsKeyOption = true,
          NextDialogue = 6102507,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102507] = {
          Content = "火焰仍在静静燃烧，恍惚间，你似乎从中听到了一个声音。",
          DialogueId = 6102507,
          GUID = "0F46E88E",
          NextDialogue = 6102508,
          RougeTalkActorType = 3
        },
        [6102508] = {
          Content = "“是的……是的。我记住了。”\n少女平静而幸福的声音透过火焰传来。\n“疑问要适可而止。火是神明的馈赠，不是物质的反应。就像这些小石子，它们是神明赐予我的宝物，让我能够安然入睡……”",
          DialogueId = 6102508,
          GUID = "0F46E8B8",
          NextDialogue = 6102509,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room324_Char01"
        },
        [6102509] = {
          Content = "你沉默地转身离开，一颗石子恰巧滚落在道路前方，你无意间将它踩碎成了粉末。\n神明赐予的宝物，原来如此脆弱。",
          DialogueId = 6102509,
          GUID = "0F46E8E2",
          NextDialogue = 6102510,
          RougeTalkActorType = 3
        },
        [6102510] = {
          Content = "你忽然想，那片火焰到底是为少女带来幸福的“确定”，还是将她永远困在这里的“枷锁”呢？\n或许，这二者本来就没什么区别。",
          DialogueId = 6102510,
          GUID = "0F46E90C",
          RougeTalkActorType = 3
        },
        [6102601] = {
          Content = "“对不起，都是我的错……我太笨了，记不全圣歌……我太懒了，没有坚持听完布道……”\n“神明大人，请原谅我……”",
          DialogueId = 6102601,
          GUID = "0F46F7FA",
          NextDialogue = 6102602,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room325_Char01"
        },
        [6102602] = {
          Content = "女孩旁若无人地忏悔着——又或许，是她已经看不见旁人了。\n她的病情看上去比上次更加糟糕，连双眼都变得黯淡无光。",
          DialogueId = 6102602,
          GUID = "0F46F824",
          NextDialogue = 6102603,
          RougeTalkActorType = 3
        },
        [6102603] = {
          Content = "“您是……那位旅人……已经……过去很久了吗？”\n女孩终于注意到你，慢慢地转过头来。\n“旅人……请您告诉我……为什么，我日夜不停地向神明祈祷，神明却从来不回应我？”",
          DialogueId = 6102603,
          GUID = "0F46F84E",
          NextOptions = {
            [1] = 6102604,
            [2] = 6102608
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room325_Char01"
        },
        [6102604] = {
          Content = "鼓励她继续祈祷。",
          DialogueId = 6102604,
          GUID = "0F46F878",
          IsKeyOption = true,
          NextDialogue = 6102605,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102605] = {
          Content = "既然还没到改写结局的时刻，那么将谎言延续下去也无妨……至少，那也是一种“希望”。\n你告诉她，只要继续祈祷，总有一天你们都能得到拯救。\n这不完全是谎话——你相信深渊终会被战胜，只不过她的祈祷无关紧要，真正的答案在于你手中的这盏提灯。",
          DialogueId = 6102605,
          GUID = "0F46F8A2",
          NextDialogue = 6102606,
          RougeTalkActorType = 3
        },
        [6102606] = {
          Content = "“我明白了……我相信您。”\n女孩双手交握，继续低声祈祷，声音中多出了几分坚定。",
          DialogueId = 6102606,
          GUID = "0F46F8CC",
          NextDialogue = 6102607,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room325_Char01"
        },
        [6102607] = {
          Content = "你轻叹了一口气，握紧手中的提灯，继续前行。",
          DialogueId = 6102607,
          GUID = "0F46F8F6",
          RougeTalkActorType = 3
        },
        [6102608] = {
          Content = "告诉她神明不会回应。",
          DialogueId = 6102608,
          GUID = "0F46F920",
          IsKeyOption = true,
          NextDialogue = 6102609,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102609] = {
          Content = "“神明……不会回应我吗？”\n“是因为我的罪孽太深，已经不值得拯救了吗？”\n女孩绝望地看着你，泪水顺着她布满脓疮的脸颊滑落。",
          DialogueId = 6102609,
          GUID = "0F46F94A",
          NextOptions = {
            [1] = 6102610
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room325_Char01"
        },
        [6102610] = {
          Content = "“是因为你本来就没有罪。”",
          DialogueId = 6102610,
          GUID = "0F46F974",
          NextDialogue = 6102611,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102611] = {
          Content = "“咦……？”\n女孩愣住了，眼中浮现出深深的困惑。",
          DialogueId = 6102611,
          GUID = "0F46F99E",
          NextDialogue = 6102612,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room325_Char01"
        },
        [6102612] = {
          Content = "你对她露出一个坚定的微笑，告诉她，你一定会找到办法结束她的痛苦。\n女孩看着你，似懂非懂地点了点头。这时你注意到，她的伤口不再流血了。\n于是，你向她挥手作别，握紧手中的提灯，继续前行。",
          DialogueId = 6102612,
          GUID = "0F46F9C8",
          RougeTalkActorType = 3
        },
        [6102701] = {
          Content = "“芙萨，满月女神——\n“辉光足迹的主宰，命运丝线的编织者……\n“穹顶与月华为证，虔信颂歌向你献上……”",
          DialogueId = 6102701,
          GUID = "0F470862",
          NextDialogue = 6102702,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room326_Char01"
        },
        [6102702] = {
          Content = "人们的身形自火中浮现，他们齐声念着献给神明的祷言。",
          DialogueId = 6102702,
          GUID = "0F47088C",
          NextDialogue = 6102703,
          RougeTalkActorType = 3
        },
        [6102703] = {
          Content = "“你是谁？一位迷路的旅人？”\n一位祈祷者看见了你，她笑着向你伸出手。\n“与我们一起向满月女神祈祷吧，祂定会为你的前路赐福！”",
          DialogueId = 6102703,
          GUID = "0F4708B6",
          NextDialogue = 6102704,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room326_Char01"
        },
        [6102704] = {
          Content = "他们的颂歌献给<H>第九位神明</>，命运之神<H>芙萨</>。\n祂是满月的主宰，祂抽引月华，织成命运之线。",
          DialogueId = 6102704,
          GUID = "0F4708E0",
          NextOptions = {
            [1] = 6102705,
            [2] = 6102709
          },
          RougeTalkActorType = 3
        },
        [6102705] = {
          Content = "加入他们的祈祷。",
          DialogueId = 6102705,
          GUID = "0F47090A",
          IsKeyOption = true,
          NextDialogue = 6102706,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102706] = {
          Content = "这是幼时的你最不喜欢的场合。你不喜欢那些空洞的溢美之词，背下来转头就忘记。但如今，你却生出一丝怀念。\n你加入了他们的祈祷。",
          DialogueId = 6102706,
          GUID = "0F470934",
          NextDialogue = 6102707,
          RougeTalkActorType = 3
        },
        [6102707] = {
          Content = "“芙萨，命运无序乱流中恒常划过天幕的满月之神。\n“向你致敬，愿你护佑你的信徒，\n“赐予我们无可挑剔的…………幸运与幸福。”",
          DialogueId = 6102707,
          GUID = "0F47095E",
          NextDialogue = 6102708,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102708] = {
          Content = "你闭上双眼，跟着虔诚的信众默念。\n最后一句念完，你睁开眼，他们的身影已经消失不见。",
          DialogueId = 6102708,
          GUID = "0F470988",
          RougeTalkActorType = 3
        },
        [6102709] = {
          Content = "不愿加入他们的祈祷。",
          DialogueId = 6102709,
          GUID = "0F4709B2",
          IsKeyOption = true,
          NextDialogue = 6102710,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102710] = {
          Content = "“拒绝？你——为什么？”\n祈祷者尖利地叫出声。\n“异端者——莫非你是暗月派的信徒？涅法的追随者？”",
          DialogueId = 6102710,
          GUID = "0F4709DC",
          NextDialogue = 6102711,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room326_Char01"
        },
        [6102711] = {
          Content = "听到那个禁忌的名字，信徒们齐齐转过脸来，他们的面孔变得扭曲而狰狞。\n你叹了口气——你得想办法从他们的团团包围中抽身了。",
          DialogueId = 6102711,
          GUID = "0F470A06",
          RougeTalkActorType = 3
        },
        [6102801] = {
          Content = "“命运纺线之剪，永恒寂静的主宰者……\n“深渊与长夜为证，请聆听我卑微的祷言……”",
          DialogueId = 6102801,
          GUID = "0F4718CA",
          NextDialogue = 6102802,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room327_Char01"
        },
        [6102802] = {
          Content = "人们的身形自火中浮现，他们齐声念着献给神明的祷言。\n你静静聆听着。那是你并不熟悉的祷文。",
          DialogueId = 6102802,
          GUID = "0F4718F4",
          NextDialogue = 6102803,
          RougeTalkActorType = 3
        },
        [6102803] = {
          Content = "“你是谁？一位迷路的旅人？”\n一位祈祷者看见了你，她笑着向你伸出手。\n“还是说，你也同样窥破了天机，想要同我们一起投入真正的救主——涅法的怀抱？”",
          DialogueId = 6102803,
          GUID = "0F47191E",
          NextDialogue = 6102804,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room327_Char01"
        },
        [6102804] = {
          Content = "<H>涅法</>——你记得这个名字。\n它不常出现在艾利西安正教信众的笔下，你只在尘封的古老尺牍间见过这个名字。这是一个禁忌的名字，早已被遗忘的<H>第十位神明</>。",
          DialogueId = 6102804,
          GUID = "0F471948",
          NextDialogue = 6102805,
          RougeTalkActorType = 3
        },
        [6102805] = {
          Content = "祂是满月与命运之神芙萨的姊妹，暗月与死亡之神。\n她的同胞姐姐纺织命运丝线，她则剪断命运。\n两位神明无休止的争斗带来月相盈虚，卷动潮汐。\n那么，祂的信徒，便应该是……",
          DialogueId = 6102805,
          GUID = "0F471972",
          NextOptions = {
            [1] = 6102806
          },
          RougeTalkActorType = 3
        },
        [6102806] = {
          Content = "询问他们的信仰。",
          DialogueId = 6102806,
          GUID = "0F47199C",
          NextDialogue = 6102807,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102807] = {
          Content = "“既然出现在这儿，你应该已经知晓，这片深渊不是死物。它活着，不断生长，不断延伸。\n“骑士团的黄金圣剑无法击退黑暗的浪潮，满月的光辉不能穿透幽邃的寂静。\n“正如一切光芒都向着熄灭飞驰，一切活物都终有一死——消亡是唯一可以确定的东西。我们的深渊，才是世界本真的模样。\n“欢迎加入<H>暗月教派</>，亲爱的旅人。”",
          DialogueId = 6102807,
          GUID = "0F4719C6",
          NextOptions = {
            [1] = 6102808,
            [2] = 6102811
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room327_Char02"
        },
        [6102808] = {
          Content = "回应他们的邀请。",
          DialogueId = 6102808,
          GUID = "0F4719F0",
          IsKeyOption = true,
          NextDialogue = 6102809,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102809] = {
          Content = "即使只是虚影，你也不想触怒他们，增加无谓的纠缠。\n于是你开始煞有介事地复述起你听过的那些关于暗月教派的传言——“死亡的本能”啦，“涅法的救赎”啦，“深渊即永恒”啦……人们的脸上露出微笑，他们不住地点头，附和起你的高谈阔论。",
          DialogueId = 6102809,
          GUID = "0F471A1A",
          NextDialogue = 6102810,
          RougeTalkActorType = 3
        },
        [6102810] = {
          Content = "“你的博学令我们感叹，你的智慧令我们折服。请收下这些礼物吧，陌生的朋友！”\n你蒙混过关了。还好，你并非少时的每一场布道和论辩都在走神。",
          DialogueId = 6102810,
          GUID = "0F471A44",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room327_Char02"
        },
        [6102811] = {
          Content = "拒绝他们的邀请。",
          DialogueId = 6102811,
          GUID = "0F471A6E",
          IsKeyOption = true,
          NextDialogue = 6102812,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102812] = {
          Content = "在这场漫长的苦旅中，你也曾多次思考过生的意义，死的意义。你也曾相信死亡便是唯一的解。\n但<H>那几次意外的相逢</>让你坚定了你无数次行走在黑暗中的意义——\n你要驱散这片黑暗，以自己的躯壳为薪柴。即使只是短暂的光，你也将灼烧这片凝滞的不朽。",
          DialogueId = 6102812,
          GUID = "0F471A98",
          NextDialogue = 6102813,
          RougeTalkActorType = 3
        },
        [6102813] = {
          Content = "“深渊并非永恒，你们只是生者留下的虚影。\n你举起武器。\n“回到你该去的地方吧，亡者们——”",
          DialogueId = 6102813,
          GUID = "0F471AC2",
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102901] = {
          Content = "你在篝火旁坐下休息。\n忽然间，你注意到了一种奇怪的响声。一开始它好像就在你耳畔，然后渐渐远了一点，移到了头顶。\n声音越来越响，窸窸窣窣，似乎是某种柔软的东西在互相摩擦。",
          DialogueId = 6102901,
          GUID = "0F472932",
          NextDialogue = 6102902,
          RougeTalkActorType = 3
        },
        [6102902] = {
          Content = "“嗨！幸运的旅人！”",
          DialogueId = 6102902,
          GUID = "0F47295C",
          NextDialogue = 6102903,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room381_Char01"
        },
        [6102903] = {
          Content = "色彩斑斓的羽毛从头顶落下来。你从来没有一次在深渊里同时看到这么多颜色。\n现在，你被包围在一地羽毛中间，好像被街头玩整蛊游戏的小家伙们偶然选中的倒霉路人，尴尬中还透着一丝微妙的可悲。",
          DialogueId = 6102903,
          GUID = "0F472986",
          NextDialogue = 6102904,
          RougeTalkActorType = 3
        },
        [6102904] = {
          Content = "“我说，你怎么一点反应也没有？你在深渊里待这么久了，不觉得无聊吗？”\n戴着滑稽的鸟头面具的人从上方倒立着缓缓降落下来，让自己的视线与你齐平。\n你不知道他是怎么保持这个动作的，但这不重要，重要的是他面具上的尖嘴快要戳到你的脸了。",
          DialogueId = 6102904,
          GUID = "0F4729B0",
          NextOptions = {
            [1] = 6102905
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room381_Char01"
        },
        [6102905] = {
          Content = "我没空陪你胡闹。",
          DialogueId = 6102905,
          GUID = "0F4729DA",
          NextDialogue = 6102906,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102906] = {
          Content = "“别这么冷淡嘛，传颂会的老家伙们应该教过你吧，日行一善会有好报的。”\n“跟我<H>玩个游戏</>，赢了就给你奖励，输了也没有惩罚。稳赚不赔，怎么样？”",
          DialogueId = 6102906,
          GUID = "0F472A04",
          NextOptions = {
            [1] = 6102907
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room381_Char01"
        },
        [6102907] = {
          Content = "好吧。",
          DialogueId = 6102907,
          GUID = "0F472A2E",
          IsKeyOption = true,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6103001] = {
          Content = "“哦，让我们唱一首歌儿给<H>沙利叶</>吧！\n“他是艾利西安的圣者。\n“他聆听芙萨的启示，教给世人慈悲、宽恕与爱，\n“让那朱红的艾利西安大地，重绽和平的新枝。”",
          DialogueId = 6103001,
          GUID = "0F47399A",
          NextDialogue = 6103002,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room328_Char01"
        },
        [6103002] = {
          Content = "你看到一位吟游诗人打扮的老者正摩挲着一截断壁。\n这处断壁相对完整，借着微弱的灯光，你看到了一幅巨大的壁画，画的正是诗人口中的<H>沙利叶</>。\n两千年的圣者，最初的<H>七美德</>之一，“节制”席。\n诗人径自唱着歌，对你的到来充耳不闻。",
          DialogueId = 6103002,
          GUID = "0F4739C4",
          NextOptions = {
            [1] = 6103003
          },
          RougeTalkActorType = 3
        },
        [6103003] = {
          Content = "继续听下去。",
          DialogueId = 6103003,
          GUID = "0F4739EE",
          NextDialogue = 6103004,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6103004] = {
          Content = "“但圣者的心却始终因一事而痛楚，\n“那便是芙萨给世人的应许，那众天之天。\n“终于有一天，他在碧波之畔静坐七十又七日后，\n“他于满月之下洞悉真理，于湖中抵达永恒。”",
          DialogueId = 6103004,
          GUID = "0F473A18",
          NextDialogue = 6103005,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room328_Char01"
        },
        [6103005] = {
          Content = "你知道他在唱什么。\n沙利叶在湖畔得到满月与命运女神芙萨的启示，他的灵魂从此前往众天之天，得到了“永恒”。他也成为第一位“神选者”。\n自他之后，又陆续有人身上显现出圣痕，那是被神选中的徽记。他们陆续经由圣湖，抵达应许之地。\n这些早期传颂会历史你并不陌生。",
          DialogueId = 6103005,
          GUID = "0F473A42",
          NextOptions = {
            [1] = 6103006
          },
          RougeTalkActorType = 3
        },
        [6103006] = {
          Content = "继续听下去。",
          DialogueId = 6103006,
          GUID = "0F473A6C",
          NextDialogue = 6103007,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6103007] = {
          Content = "“可两千年后，当我站在起伏的山峦凝望圣湖，\n“为何那里只剩下漆黑的漩涡？\n“沙利叶啊，我们智慧的圣者——\n“告诉我，女神应许的乐园究竟在何处？”",
          DialogueId = 6103007,
          GUID = "0F473A96",
          NextDialogue = 6103008,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room328_Char01"
        },
        [6103008] = {
          Content = "诗人边唱着，边落下泪来。他终于从遥远的历史，唱到了眼前的现在——这片幽暗的深渊。\n不知从何时起，传颂会两千年来最神圣洁净的圣湖，一夜之间突然为这污浊的混沌所取代。\n就像一千年前那些弃教的堕落者所言的那样——“九神已死！”\n要继续听下去吗？",
          DialogueId = 6103008,
          GUID = "0F473AC0",
          NextOptions = {
            [1] = 6103009,
            [2] = 6103013
          },
          RougeTalkActorType = 3
        },
        [6103009] = {
          Content = "继续听下去。",
          DialogueId = 6103009,
          GUID = "0F473AEA",
          IsKeyOption = true,
          NextDialogue = 6103010,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6103010] = {
          Content = "“为何那秽浊的深渊没有言语？\n“那满月的银辉遍照我身，为何女神不曾回答？\n“沙利叶啊，难道真的如暗月派的信徒所言——\n“你从未前往众天之天，而是背向着明月，成为了魔鬼？”",
          DialogueId = 6103010,
          GUID = "0F473B14",
          NextDialogue = 6103011,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room328_Char01"
        },
        [6103011] = {
          Content = "“请等一下——你说什么？”\n诗人唱出了你始料未及的词句，那是流传于异端者中最隐秘的流言——圣湖从不曾神圣，所谓的由沙利叶而始的神选从一开始就是一场盛大的献祭。\n从<H>某个人</>口中，你听过相同的推测。",
          DialogueId = 6103011,
          GUID = "0F473B3E",
          NextDialogue = 6103012,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6103012] = {
          Content = "可诗人只是继续旁若无人地拨弄着他的七弦琴，开始唱下一首歌谣，仿佛你并不存在于他的时空。\n他的声音越来越远，直到身影消失不见。",
          DialogueId = 6103012,
          GUID = "0F473B68",
          RougeTalkActorType = 3
        },
        [6103013] = {
          Content = "离开此地。",
          DialogueId = 6103013,
          GUID = "0F473B92",
          IsKeyOption = true,
          NextDialogue = 6103014,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6103014] = {
          Content = "你打了几声招呼，尝试吸引诗人的注意。你想和他聊聊，但他只是兀自唱着那首古老的歌谣。\n大概无法从他口中得到什么有价值的情报了，于是你转身离开。",
          DialogueId = 6103014,
          GUID = "0F473BBC",
          RougeTalkActorType = 3
        },
        [6200101] = {
          Content = "数位年轻人的交谈声从不远处传来，你已经很久没在深渊中听到这样的声音了——热烈的、鲜活的、尚未被深渊的黑暗侵染的声音。\n你很确信这声音的来源并非亡灵，也不是幻影，而是活生生的人类。而且，从谈话的气氛可以推断出，他们一定才刚来到这里不久。",
          DialogueId = 6200101,
          GUID = "0F857412",
          NextDialogue = 6200102,
          RougeTalkActorType = 3
        },
        [6200102] = {
          Content = "你忍不住循着声音所在的方向走去。环绕四周的迷雾逐渐散开，你见到了四位年轻的骑士。\n他们的衣着和装备各自有别，但身上都佩戴着象征艾利西安的圣鸢尾徽章。",
          DialogueId = 6200102,
          GUID = "0F85743C",
          NextDialogue = 6200103,
          RougeTalkActorType = 3
        },
        [6200103] = {
          Content = "“是这个方向没错吗，队长？”\n年轻的金发女骑士三步并作两步跨上古旧的台阶，又一口气跳了下来。\n“这看起来只是一座废墟而已。”",
          DialogueId = 6200103,
          GUID = "0F857466",
          NextDialogue = 6200104,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01"
        },
        [6200104] = {
          Content = "“至少我确定我们没来过这里。”\n被称作队长的青年骑士迈着沉稳的步伐从她身边走过。\n“在圣湖里很难辨别方向，现在也只能走一步算一步了。”",
          DialogueId = 6200104,
          GUID = "0F857490",
          NextDialogue = 6200105,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200105] = {
          Content = "“还有——你这么上蹿下跳的不累吗，凯希？”\n看着自己那位活泼的同伴，青年无奈地叹了一口气。\n“这里的环境凶险，还是谨慎为好，别在战斗之外的事情上消耗体力。”",
          DialogueId = 6200105,
          GUID = "0F8574BA",
          NextDialogue = 6200106,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200106] = {
          Content = "“一点也不累！我又不像你，拿着那么重的长剑和盾牌。”\n女孩轻巧地用食指勾住手枪，在空中转了个圈。\n“说起来，这里为什么叫‘圣湖’？我看这里到处都是秽兽和诡异的幻象，实在不怎么神圣呀。”",
          DialogueId = 6200106,
          GUID = "0F8574E4",
          NextDialogue = 6200107,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01"
        },
        [6200107] = {
          Content = "“凯希，注意你的言辞。”\n手执长杖的男性卡戎司祭一脸严肃地开口。\n“圣湖是受神选召之人蒙受神恩的圣地，如今虽被黑暗侵染，可我们身为艾利西安的一羽，仍应心怀敬畏。”",
          DialogueId = 6200107,
          GUID = "0F85750E",
          NextDialogue = 6200108,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char03"
        },
        [6200108] = {
          Content = "四人之中的最后一位——身披斗篷、背着一张长弓的女术士听到他的话，不以为然地轻笑了一声。黑色的兜帽遮住了她的面庞，你看不清她的表情。",
          DialogueId = 6200108,
          GUID = "0F857538",
          NextDialogue = 6200109,
          RougeTalkActorType = 3
        },
        [6200109] = {
          Content = "似是想要缓解尴尬，身为队长的青年张了张嘴，却什么也说不出来。正当他左右为难的时候，他注意到了你。",
          DialogueId = 6200109,
          GUID = "0F857562",
          NextDialogue = 6200110,
          RougeTalkActorType = 3
        },
        [6200110] = {
          Content = "“阁下看起来不像是骑士团的人，莫非是误入此地的平民？”",
          DialogueId = 6200110,
          GUID = "0F85758C",
          NextOptions = {
            [1] = 6200111
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200111] = {
          Content = "我是一位旅人。",
          DialogueId = 6200111,
          GUID = "0F8575B6",
          NextDialogue = 6200112,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200112] = {
          Content = "“旅人……？”青年的脸上掠过一瞬的困惑，又旋即恢复温和的劝诫，“那么，或许您有所不知，此处是艾利西安的圣地，目前由于一些原因变得非常危险，并不适宜旅行。”",
          DialogueId = 6200112,
          GUID = "0F8575E0",
          NextDialogue = 6200113,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200113] = {
          Content = "“我叫弗林，是艾利西安传颂会下属飞羽骑士团的骑士，这几位都是我的同伴。如果您不介意的话，我们可以护送您离开此地。”",
          DialogueId = 6200113,
          GUID = "0F85760A",
          NextOptions = {
            [1] = 6200114
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200114] = {
          Content = "不必了，我还有未完成的目标。",
          DialogueId = 6200114,
          GUID = "0F857634",
          NextDialogue = 6200115,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200115] = {
          Content = "“我必须提醒您，这里不止是圣地，也是禁地。作为骑士，我们有义务驱逐外来者。”",
          DialogueId = 6200115,
          GUID = "0F85765E",
          NextDialogue = 6200116,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char03"
        },
        [6200116] = {
          Content = "“……怎么驱逐？”伴随一声不屑的冷笑，身披斗篷的女术士终于开口，“难道不是连我们自己都不知道该怎么出去吗？”\n她的话语冰凉，如寒冬的雪粒擦过脸颊。",
          DialogueId = 6200116,
          GUID = "0F857688",
          NextDialogue = 6200117,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char04"
        },
        [6200117] = {
          Content = "“呃……好啦好啦。”金发的女骑士打起了圆场，“我看这位‘客人’身手还不错，也不像是渎神者。反正不影响我们的任务，就当做没看见吧？”",
          DialogueId = 6200117,
          GUID = "0F8576B2",
          NextDialogue = 6200118,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01"
        },
        [6200118] = {
          Content = "“对了对了，旅人阁下。”她推开弗林，挤到你面前，“您有没有见过一位大约十三四岁，粉色长发，手持一柄巨剑的女剑士？”",
          DialogueId = 6200118,
          GUID = "0F8576DC",
          NextOptions = {
            [1] = 6200119
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01"
        },
        [6200119] = {
          Content = "……没有。",
          DialogueId = 6200119,
          GUID = "0F857706",
          NextDialogue = 6200120,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200120] = {
          Content = "“是吗……那么，如果您之后遇见了她，请帮忙转告一声——就说<H>静默黄昏</>小队正在找她，好吗？拜托您了！”",
          DialogueId = 6200120,
          GUID = "0F857730",
          NextOptions = {
            [1] = 6200121
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01"
        },
        [6200121] = {
          Content = "你们为什么要找她？",
          DialogueId = 6200121,
          GUID = "0F85775A",
          NextDialogue = 6200122,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200122] = {
          Content = "“虽然有些难以启齿，但她算是我们的……指挥官。呃，我也不能说得太多，否则米尔顿又该数落我了。”",
          DialogueId = 6200122,
          GUID = "0F857784",
          NextDialogue = 6200123,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01"
        },
        [6200123] = {
          Content = "“既然知道就别多嘴。”司祭皱起了眉头。“别再横生枝节了，任务要紧，我们走吧。”",
          DialogueId = 6200123,
          GUID = "0F8577AE",
          NextDialogue = 6200124,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char03"
        },
        [6200124] = {
          Content = "“您真的不需要帮助吗？”青年再次担忧地看向你，“这里真的非常危险，或许您可以和我们同路前行。”",
          DialogueId = 6200124,
          GUID = "0F8577D8",
          NextOptions = {
            [1] = 6200125
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200125] = {
          Content = "真的不需要。",
          DialogueId = 6200125,
          GUID = "0F857802",
          NextDialogue = 6200126,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200126] = {
          Content = "“好吧。既然您坚定如此……”",
          DialogueId = 6200126,
          GUID = "0F85782C",
          NextOptions = {
            [1] = 6200127
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200127] = {
          Content = "既然这么危险，你们不害怕吗？",
          DialogueId = 6200127,
          GUID = "0F857856",
          IsKeyOption = true,
          NextDialogue = 6200128,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200128] = {
          Content = "“心怀信仰，自然不会畏惧。”青年露出了笃定的笑容，“有缘再会，阁下，愿满月之神护佑您的旅途。”",
          DialogueId = 6200128,
          GUID = "0F857880",
          NextDialogue = 6200129,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200129] = {
          Content = "骑士们结伴离开了，你的眼前又只剩下延绵不绝的迷雾。",
          DialogueId = 6200129,
          GUID = "0F8578AA",
          RougeTalkActorType = 3
        },
        [6200201] = {
          Content = "年轻的女骑士从黑暗中现身，金色发丝如同一道流泻的灯光照亮了混沌。\n她和上一次见面时不太一样了——她的衣摆多了几道破损之处，沾上了一些暗红色的痕迹。",
          DialogueId = 6200201,
          GUID = "0F85847A",
          NextDialogue = 6200202,
          RougeTalkActorType = 3
        },
        [6200202] = {
          Content = "“是你呀，旅人阁下，又见面了！”她似是有些疲惫，却依旧打起精神向你用力挥手。",
          DialogueId = 6200202,
          GUID = "0F8584A4",
          NextOptions = {
            [1] = 6200203
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200203] = {
          Content = "你的同伴们呢？",
          DialogueId = 6200203,
          GUID = "0F8584CE",
          NextDialogue = 6200204,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200204] = {
          Content = "“唔……刚才我们遇到了好些秽兽，还有很多幽灵——我是说，那些黑暗里的影子……”",
          DialogueId = 6200204,
          GUID = "0F8584F8",
          NextDialogue = 6200205,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200205] = {
          Content = "“我拼命驱逐了它们，回过神来，大家就都不见了。你见到他们了吗？”",
          DialogueId = 6200205,
          GUID = "0F858522",
          NextOptions = {
            [1] = 6200206
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200206] = {
          Content = "没有。",
          DialogueId = 6200206,
          GUID = "0F85854C",
          NextDialogue = 6200207,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200207] = {
          Content = "凯希垂下了眼眸，像一朵浮云飘过，遮住了太阳。",
          DialogueId = 6200207,
          GUID = "0F858576",
          NextDialogue = 6200208,
          RougeTalkActorType = 3
        },
        [6200208] = {
          Content = "“弗林总是念叨说，战斗的时候要注意队形，要互相照应……唉，如果我听他的话，不那么随性就好了。”",
          DialogueId = 6200208,
          GUID = "0F8585A0",
          NextDialogue = 6200209,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200209] = {
          Content = "“我根本不知道圣湖是这样的地方。平时我就算不小心掉队，也很快就能找到他们。可是这里……明明是刚才走过的地方，回头一看已经完全不一样了。就像是……”\n她攥紧了拳头。\n“就像是那些影子把大家带走了……连他们留下的痕迹也一并抹除了。”",
          DialogueId = 6200209,
          GUID = "0F8585CA",
          NextOptions = {
            [1] = 6200210
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200210] = {
          Content = "别担心，你们一定会再次相遇的，就像你遇见我一样。",
          DialogueId = 6200210,
          GUID = "0F8585F4",
          NextDialogue = 6200211,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200211] = {
          Content = "凯希有些惊讶地眨了眨眼，盯着你看了一会儿。",
          DialogueId = 6200211,
          GUID = "0F85861E",
          NextDialogue = 6200212,
          RougeTalkActorType = 3
        },
        [6200212] = {
          Content = "“我们以前见过吗？”\n她明亮的双眸中倒映出你的容颜。那容颜让你觉得陌生。",
          DialogueId = 6200212,
          GUID = "0F858648",
          NextDialogue = 6200213,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200213] = {
          Content = "“我总觉得，你身上有种似曾相识的感觉——我不是说上次见面，而是更早之前，在我们还没进入圣湖的时候……”",
          DialogueId = 6200213,
          GUID = "0F858672",
          NextOptions = {
            [1] = 6200214
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200214] = {
          Content = "只是错觉吧。",
          DialogueId = 6200214,
          GUID = "0F85869C",
          NextDialogue = 6200215,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200215] = {
          Content = "“嗯，也对。”\n她勾起嘴角笑了笑，像被遮蔽的阳光努力穿越云层透出了一丝光亮。",
          DialogueId = 6200215,
          GUID = "0F8586C6",
          NextDialogue = 6200216,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200216] = {
          Content = "“和他们失散以后，我已经一个人走了很久、很久。如果不是遇到了你，我都要怀疑自己是受到神罚，掉进什么地狱了呢。”",
          DialogueId = 6200216,
          GUID = "0F8586F0",
          NextDialogue = 6200217,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200217] = {
          Content = "“也许我只是对<H>活着的生命</>的气息产生了怀念吧。”",
          DialogueId = 6200217,
          GUID = "0F85871A",
          NextOptions = {
            [1] = 6200218
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200218] = {
          Content = "希望你能早日和同伴会合。",
          DialogueId = 6200218,
          GUID = "0F858744",
          IsKeyOption = true,
          NextDialogue = 6200219,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200219] = {
          Content = "“嗯，谢谢！没关系啦，他们都是非常厉害的骑士。就算没有我在，也一定没问题的。是我必须要找到他们才行……”",
          DialogueId = 6200219,
          GUID = "0F85876E",
          NextDialogue = 6200220,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200220] = {
          Content = "“再见，旅人阁下。祝你也能实现自己的目标。”",
          DialogueId = 6200220,
          GUID = "0F858798",
          NextDialogue = 6200221,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        }
      }
    end
  },
  {
    MinKey = 6200221,
    MaxKey = 6201602,
    Loader = function()
      return {
        [6200221] = {
          Content = "凯希向你挥了挥手，转身离开了。\n四周又昏暗下去，仿佛长夜从未迎来过天明。",
          DialogueId = 6200221,
          GUID = "0F8587C2",
          RougeTalkActorType = 3
        },
        [6200301] = {
          Content = "断瓦颓垣，又一片废墟。\n这并没有什么特别的，你在深渊中无数次见过这样的光景——",
          DialogueId = 6200301,
          GUID = "0F8594E2",
          NextDialogue = 6200302,
          RougeTalkActorType = 3
        },
        [6200302] = {
          Content = "不仅仅是指那些碎裂的建筑残片，还包括那些散落其中不会再被人执起的武器、若隐若现地横躺在废墟之下停止了呼吸的身体。血腥味，烟尘味。\n你见得太多了。又是一些自愿或不得已被献祭给“圣湖”的灵魂，仅此而已。",
          DialogueId = 6200302,
          GUID = "0F85950C",
          NextDialogue = 6200303,
          RougeTalkActorType = 3
        },
        [6200303] = {
          Content = "忽然，一枚染血的徽章引起了你的注意——那鸢尾是你再熟悉不过的纹样。你不久前见过这枚徽章。",
          DialogueId = 6200303,
          GUID = "0F859536",
          NextDialogue = 6200304,
          RougeTalkActorType = 3
        },
        [6200304] = {
          Content = "你拨开碎落的石块，看到一把血迹斑斑的长剑。它直直地插在地上，或许是因为握着剑的那个人直到最后也不愿就此倒下，仍在徒劳地试图支起身体。",
          DialogueId = 6200304,
          GUID = "0F859560",
          NextDialogue = 6200305,
          RougeTalkActorType = 3
        },
        [6200305] = {
          Content = "然后，你看到了碎裂的法杖、凌乱的断箭、损毁的手枪。\n现在你知道这些灵魂的名字了。",
          DialogueId = 6200305,
          GUID = "0F85958A",
          NextDialogue = 6200306,
          RougeTalkActorType = 3
        },
        [6200306] = {
          Content = "“心怀信仰，自然不会畏惧”——也不知道，在最后一刻，他们所坚持的信仰是否为他们免除了死亡的苦痛？\n你无从知晓，也不必知晓。",
          DialogueId = 6200306,
          GUID = "0F8595B4",
          NextDialogue = 6200307,
          RougeTalkActorType = 3
        },
        [6200307] = {
          Content = "因为当你下一次拨转表盘，这一切都会烟消云散。\n悼念和祈祷并无意义，你也不打算多花费时间。你为逝者阖上双眼，然后便转身准备离开。",
          DialogueId = 6200307,
          GUID = "0F8595DE",
          NextDialogue = 6200308,
          RougeTalkActorType = 3
        },
        [6200308] = {
          Content = "“是我必须要找到他们才行……”\n女孩的话语蓦然在你脑海中响起，就像是在呼唤你，在提醒你什么。",
          DialogueId = 6200308,
          GUID = "0F859608",
          NextDialogue = 6200309,
          RougeTalkActorType = 3
        },
        [6200309] = {
          Content = "于是你再次将目光投向那片废墟，这次你终于察觉到了一丝异样——尽管那四位年轻骑士的身体都已变得冰冷，但唯有凯希的衣物上没有沾上黑色的灰烬。\n她的身上只有层层叠叠，干透了或半干的秽兽的血迹。",
          DialogueId = 6200309,
          GUID = "0F859632",
          NextOptions = {
            [1] = 6200310
          },
          RougeTalkActorType = 3
        },
        [6200310] = {
          Content = "于是你明白了：她和你一样来晚了。",
          DialogueId = 6200310,
          GUID = "0F85965C",
          IsKeyOption = true,
          NextDialogue = 6200311,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200311] = {
          Content = "当她找到同伴的时候，他们已然是废墟中难辨身形的残骸。",
          DialogueId = 6200311,
          GUID = "0F859686",
          NextDialogue = 6200312,
          RougeTalkActorType = 3
        },
        [6200312] = {
          Content = "所以她留在这里，不再前进，守着这些一度与她失散的同伴，战斗到了最后一刻。\n是为了保护同伴的尸骸吗？是为了向被她“抛弃”的同伴赎罪吗？是为了捍卫一位骑士的信条吗？\n还是漫长的黑暗终于摧毁了她最后的希冀，让她只能乞求死亡的怜悯？",
          DialogueId = 6200312,
          GUID = "0F8596B0",
          NextDialogue = 6200313,
          RougeTalkActorType = 3
        },
        [6200313] = {
          Content = "她已经不能回答你了。",
          DialogueId = 6200313,
          GUID = "0F8596DA",
          RougeTalkActorType = 3
        },
        [6200401] = {
          Content = "数位年轻人的交谈声从不远处传来，你已经很久没在深渊中听到这样的声音了——热烈的、鲜活的、尚未被深渊的黑暗侵染的声音。\n你很确信这声音的来源并非亡灵，也不是幻影，而是活生生的人类。",
          DialogueId = 6200401,
          GUID = "0F85A54A",
          NextDialogue = 6200402,
          RougeTalkActorType = 3
        },
        [6200402] = {
          Content = "你知道他们是谁。",
          DialogueId = 6200402,
          GUID = "0F85A574",
          NextDialogue = 6200403,
          RougeTalkActorType = 3
        },
        [6200403] = {
          Content = "你循着声音所在的方向走去。环绕四周的迷雾逐渐散开，你见到了那四位年轻的骑士。\n他们的衣着和装备尚且未染纤尘，身上的圣鸢尾徽章也光洁锃亮，反射着不知从哪里投下的金光。",
          DialogueId = 6200403,
          GUID = "0F85A59E",
          NextDialogue = 6200404,
          RougeTalkActorType = 3
        },
        [6200404] = {
          Content = "“是这个方向没错吗，队长？”\n年轻的金发女骑士三步并作两步跨上古旧的台阶，又一口气跳了下来。\n“这看起来只是一座废墟而已。”",
          DialogueId = 6200404,
          GUID = "0F85A5C8",
          NextDialogue = 6200405,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char01"
        },
        [6200405] = {
          Content = "“至少我确定我们没来过这里。”\n被称作队长的青年骑士迈着沉稳的步伐从她身边走过。\n“在圣湖里很难辨别方向，现在也只能走一步算一步了。”",
          DialogueId = 6200405,
          GUID = "0F85A5F2",
          NextDialogue = 6200406,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char02"
        },
        [6200406] = {
          Content = "“还有——你这么上蹿下跳的不累吗，凯希？”\n看着自己那位活泼的同伴，青年无奈地叹了一口气。\n“这里的环境凶险，还是谨慎为好，别在战斗之外的事情上消耗体力。”",
          DialogueId = 6200406,
          GUID = "0F85A61C",
          NextDialogue = 6200407,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char02"
        },
        [6200407] = {
          Content = "“一点也不累！我又不像你——”",
          DialogueId = 6200407,
          GUID = "0F85A646",
          NextOptions = {
            [1] = 6200408
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char01"
        },
        [6200408] = {
          Content = "他说得没错。",
          DialogueId = 6200408,
          GUID = "0F85A670",
          NextDialogue = 6200409,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200409] = {
          Content = "女孩被你打断了话头，怔怔地转过头来。",
          DialogueId = 6200409,
          GUID = "0F85A69A",
          NextDialogue = 6200410,
          RougeTalkActorType = 3
        },
        [6200410] = {
          Content = "“您是……？”",
          DialogueId = 6200410,
          GUID = "0F85A6C4",
          NextOptions = {
            [1] = 6200411
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char01"
        },
        [6200411] = {
          Content = "一位旅人。我在这里待过比你们长的时间，所以，请相信我，这里远比你们想象得更可怕。",
          DialogueId = 6200411,
          GUID = "0F85A6EE",
          NextDialogue = 6200412,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200412] = {
          Content = "“旅人……？”青年的脸上掠过一瞬的困惑，和上一次见面时一模一样。“可此处是艾利西安的圣地……您是怎么进来的？”",
          DialogueId = 6200412,
          GUID = "0F85A718",
          NextOptions = {
            [1] = 6200413
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char02"
        },
        [6200413] = {
          Content = "我有自己的理由，以及必须要完成的目标。想必你们也一样。",
          DialogueId = 6200413,
          GUID = "0F85A742",
          NextDialogue = 6200414,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200414] = {
          Content = "“嗯……？”",
          DialogueId = 6200414,
          GUID = "0F85A76C",
          NextDialogue = 6200415,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char03"
        },
        [6200415] = {
          Content = "这一次，身披斗篷的女术士似乎对你产生了些许兴趣。\n她抬起头来，你终于看见了她的眼睛，那幽邃、怀疑、寻觅的目光，如同幽暗湖水浮起的气泡。",
          DialogueId = 6200415,
          GUID = "0F85A796",
          NextDialogue = 6200416,
          RougeTalkActorType = 3
        },
        [6200416] = {
          Content = "“听起来，您似乎知道一些我们不了解的真相——我是指，关于这片深渊的真相。”",
          DialogueId = 6200416,
          GUID = "0F85A7C0",
          NextDialogue = 6200417,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char03"
        },
        [6200417] = {
          Content = "“卡莉斯塔……！那是异端者才会使用的不敬之辞！这里是圣湖——圣湖。”",
          DialogueId = 6200417,
          GUID = "0F85A7EA",
          NextDialogue = 6200418,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char04"
        },
        [6200418] = {
          Content = "卡莉斯塔没有理会他的斥责，依旧直直地看着你，期待着你的答案。",
          DialogueId = 6200418,
          GUID = "0F85A814",
          NextDialogue = 6200419,
          RougeTalkActorType = 3
        },
        [6200419] = {
          Content = "你该回答什么——你能回答什么？",
          DialogueId = 6200419,
          GUID = "0F85A83E",
          NextDialogue = 6200420,
          RougeTalkActorType = 3
        },
        [6200420] = {
          Content = "告诉他们立刻回头？可你明知他们的信仰不会允许他们回头。\n信仰，一个多么沉重的词。它远比一个陌生的旅人，或者一个面目全非的故人的一句劝告来得有分量。",
          DialogueId = 6200420,
          GUID = "0F85A868",
          NextDialogue = 6200421,
          RougeTalkActorType = 3
        },
        [6200421] = {
          Content = "对沐浴在信仰的光辉里长大的人来说，得知多余的真相无异于被光灼伤，只留下白昼的刺青——永久的心灵折磨。",
          DialogueId = 6200421,
          GUID = "0F85A892",
          NextDialogue = 6200422,
          RougeTalkActorType = 3
        },
        [6200422] = {
          Content = "你摇了摇头，避开了她的目光。",
          DialogueId = 6200422,
          GUID = "0F85A8BC",
          NextOptions = {
            [1] = 6200423
          },
          RougeTalkActorType = 3
        },
        [6200423] = {
          Content = "深渊之中容易迷路，要注意别掉队，凯希。",
          DialogueId = 6200423,
          GUID = "0F85A8E6",
          NextDialogue = 6200424,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200424] = {
          Content = "“嗯？为什么要特地点我的名字呀？”",
          DialogueId = 6200424,
          GUID = "0F85A910",
          NextDialogue = 6200425,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char01"
        },
        [6200425] = {
          Content = "“说明你该好好反省一下。连陌生人都能看出来你是最喜欢到处乱窜的那个。”",
          DialogueId = 6200425,
          GUID = "0F85A93A",
          NextDialogue = 6200426,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char02"
        },
        [6200426] = {
          Content = "“哪有——而且就算走散了，我也会很快找到你们的。”女孩撇了撇嘴。",
          DialogueId = 6200426,
          GUID = "0F85A964",
          NextOptions = {
            [1] = 6200427
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char01"
        },
        [6200427] = {
          Content = "可未必每次都来得及。",
          DialogueId = 6200427,
          GUID = "0F85A98E",
          IsKeyOption = true,
          NextDialogue = 6200428,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200428] = {
          Content = "凯希愣住了，也许是被你过分认真的语气吓到了。",
          DialogueId = 6200428,
          GUID = "0F85A9B8",
          NextDialogue = 6200429,
          RougeTalkActorType = 3
        },
        [6200429] = {
          Content = "这时弗林适时地站了出来，很显然，他是个合格的艾利西安骑士。对一名优秀的骑士来说，除了纯洁的信仰，谨慎也是必要的美德——他知道自己需要把好奇心恰如其分地维持在一个可以获取情报又不至于招致灾祸的尺度。就像当你在圣堂里发现一扇向来紧锁的门对你露出了一条诱人的缝隙时，最好的选择是停下脚步、转过身、假装你什么也没看见。",
          DialogueId = 6200429,
          GUID = "0F85A9E2",
          NextDialogue = 6200430,
          RougeTalkActorType = 3
        },
        [6200430] = {
          Content = "“虽然不知道阁下的真实身份，但听起来，您有自己的路要走。我们还有任务在身，就先告辞了。”他郑重地向你行礼，“愿满月之神护佑您的旅途。”",
          DialogueId = 6200430,
          GUID = "0F85AA0C",
          NextDialogue = 6200431,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char02"
        },
        [6200431] = {
          Content = "骑士们结伴离开了，你的眼前又只剩下延绵不绝的迷雾。",
          DialogueId = 6200431,
          GUID = "0F85AA36",
          RougeTalkActorType = 3
        },
        [6200501] = {
          Content = "持续不断的战斗耗尽了你的力气。\n最后一缕余烬也从手中流散而去，你彻底迷失了方向。",
          DialogueId = 6200501,
          GUID = "0F85B5B2",
          NextDialogue = 6200502,
          RougeTalkActorType = 3
        },
        [6200502] = {
          Content = "提灯坠落在地，琉璃破碎的声响如同利刃划破寂静的黑暗。\n被切割成碎片的黑暗从四面八方向你涌来，侵蚀你的身体，啃咬你的神经。",
          DialogueId = 6200502,
          GUID = "0F85B5DC",
          NextDialogue = 6200503,
          RougeTalkActorType = 3
        },
        [6200503] = {
          Content = "当所有的感官都与黑暗融为一体，你忽然不再抗拒，你能感受到它温柔地包裹着你，接纳了你的伤口，抚平了你的疲惫。",
          DialogueId = 6200503,
          GUID = "0F85B606",
          NextDialogue = 6200504,
          RougeTalkActorType = 3
        },
        [6200504] = {
          Content = "也许这才是正确的结局。你似乎听见那黑暗在对你耳语——\n“坚持到现在，已经足够了。”",
          DialogueId = 6200504,
          GUID = "0F85B630",
          NextDialogue = 6200505,
          RougeTalkActorType = 3
        },
        [6200505] = {
          Content = "是的……你已经足够努力了。在一次又一次孤独的轮回中，你拼命战斗过、挣扎过，你品味着无边无际的痛苦，将绝望当作美酒欣然饮下，却依旧无法触及希望的曙光。",
          DialogueId = 6200505,
          GUID = "0F85B65A",
          NextDialogue = 6200506,
          RougeTalkActorType = 3
        },
        [6200506] = {
          Content = "你累了。就到此为止吧。",
          DialogueId = 6200506,
          GUID = "0F85B684",
          NextDialogue = 6200507,
          RougeTalkActorType = 3
        },
        [6200507] = {
          Content = "你觉得自己要在黑暗的摇篮里沉沉睡去了。可意识中突然浮起一个遥远的身影——事实上你已经无法记起身影主人确切的样子，但这缕模糊的思绪却如同刀锋切开你逐渐变得迟钝的血肉，令你清醒。它不断搅动着思绪的海，卷起潮汐。",
          DialogueId = 6200507,
          GUID = "0F85B6AE",
          NextDialogue = 6200508,
          RougeTalkActorType = 3
        },
        [6200508] = {
          Content = "那是和你约定过一起战胜黑暗、走出深渊的人，也是，造成你一切痛苦的罪魁祸首。",
          DialogueId = 6200508,
          GUID = "0F85B6D8",
          NextDialogue = 6200509,
          RougeTalkActorType = 3
        },
        [6200509] = {
          Content = "你还没有找到那个人——没错，你想起来了。\n你不能在这里沉睡。无论黑暗给出的邀约有多么诱人，那都不是你想要的结局。\n你必须坚持下去，为了抵达终点，为了完成约定——为了斩断荒谬的轮回。",
          DialogueId = 6200509,
          GUID = "0F85B702",
          NextOptions = {
            [1] = 6200510
          },
          RougeTalkActorType = 3
        },
        [6200510] = {
          Content = "拨动表盘",
          DialogueId = 6200510,
          GUID = "0F85B72C",
          IsKeyOption = true,
          NextDialogue = 6200511,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200511] = {
          Content = "于是你再一次拨动提灯上的表盘，朝向故事的起点。",
          DialogueId = 6200511,
          GUID = "0F85B756",
          RougeTalkActorType = 3
        },
        [6200601] = {
          Content = "深渊中的方向无时无刻不在发生变化，你时常无法分辨自己在前进还是倒退。\n有时你甚至觉得自己被囚禁在首尾相接的螺旋中徒劳地打转，永远不可能抵达尽头。",
          DialogueId = 6200601,
          GUID = "0F85C61A",
          NextDialogue = 6200602,
          RougeTalkActorType = 3
        },
        [6200602] = {
          Content = "但当眼前这个庞然大物出现在视野中的瞬间，你本能地意识到，祂便是这个深渊的“中心”。",
          DialogueId = 6200602,
          GUID = "0F85C644",
          NextDialogue = 6200603,
          RougeTalkActorType = 3
        },
        [6200603] = {
          Content = "你举起提灯，试图照亮祂的面庞，但那点可怜的光亮才刚刚触到祂的边界便被毫不留情地淹没。\n四面八方混沌的黑暗如同浑浊的墨水般翻腾流动，涌向同一个目的地。",
          DialogueId = 6200603,
          GUID = "0F85C66E",
          NextDialogue = 6200604,
          RougeTalkActorType = 3
        },
        [6200604] = {
          Content = "地面轰隆隆地震动起来，你失去支撑，跌进了黑暗中。\n恍惚间，你觉得自己的身体似乎也成为了那浊流的一部分，正在溃散、融化，流向那个吞噬一切的存在。",
          DialogueId = 6200604,
          GUID = "0F85C698",
          NextDialogue = 6200605,
          RougeTalkActorType = 3
        },
        [6200605] = {
          Content = "刺耳的寂静碾压着鼓膜，求生的本能告诉你现在必须回头。",
          DialogueId = 6200605,
          GUID = "0F85C6C2",
          NextOptions = {
            [1] = 6200606,
            [2] = 6200615
          },
          RougeTalkActorType = 3
        },
        [6200606] = {
          Content = "继续直视混沌",
          DialogueId = 6200606,
          GUID = "0F85C6EC",
          IsKeyOption = true,
          NextDialogue = 6200607,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200607] = {
          Content = "你没有退缩。\n你从黑暗中支起身体，抬高头颅，紧握着手中的提灯，向那不可名状的存在宣示：你并不畏惧它。",
          DialogueId = 6200607,
          GUID = "0F85C716",
          NextDialogue = 6200608,
          RougeTalkActorType = 3
        },
        [6200608] = {
          Content = "慢慢地，你感觉到有什么东西撬动了四周的混沌，漏出一丝缝隙，自深不可测的黑暗中，有一些东西反过来钻进了你的心脏——不可思议的是，你竟然能够理解它们。",
          DialogueId = 6200608,
          GUID = "0F85C740",
          NextDialogue = 6200609,
          RougeTalkActorType = 3
        },
        [6200609] = {
          Content = "那是属于人类的感情：疑惑、愤怒、痛苦、绝望，还有……悲伤。压倒一切的悲伤。\n——仿佛这片深渊本身也在期待着一种终结。",
          DialogueId = 6200609,
          GUID = "0F85C76A",
          NextDialogue = 6200610,
          RougeTalkActorType = 3
        },
        [6200610] = {
          Content = "“我该怎么帮助你呢？”你不禁在心中问道。",
          DialogueId = 6200610,
          GUID = "0F85C794",
          NextDialogue = 6200611,
          RougeTalkActorType = 3
        },
        [6200611] = {
          Content = "这盏提灯还不够明亮。继续你的旅途吧。祂说。在轮回的终点，你将会得到答案。",
          DialogueId = 6200611,
          GUID = "0F85C7BE",
          NextDialogue = 6200612,
          RougeTalkActorType = 3
        },
        [6200612] = {
          Content = "“终点在哪里？”你又问。",
          DialogueId = 6200612,
          GUID = "0F85C7E8",
          NextDialogue = 6200613,
          RougeTalkActorType = 3
        },
        [6200613] = {
          Content = "祂没有回答这个问题，只是用黑暗温柔地包围了你，你的视野中只剩下提灯的光芒。",
          DialogueId = 6200613,
          GUID = "0F85C812",
          NextDialogue = 6200614,
          RougeTalkActorType = 3
        },
        [6200614] = {
          Content = "于是你拨动提灯上的表盘，让时间再次倒转。",
          DialogueId = 6200614,
          GUID = "0F85C83C",
          RougeTalkActorType = 3
        },
        [6200615] = {
          Content = "回头",
          DialogueId = 6200615,
          GUID = "0F85C866",
          IsKeyOption = true,
          NextDialogue = 6200616,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200616] = {
          Content = "明智的选择。\n回头，转身，迈出步伐。本能驱使你逃离——尽管你知道，你已无法寻回行过的路。",
          DialogueId = 6200616,
          GUID = "0F85C890",
          NextDialogue = 6200617,
          RougeTalkActorType = 3
        },
        [6200617] = {
          Content = "忽然，你感觉到了一道来自背后的视线——祂正无言地注视着你，似是为你的离去感到悲伤。",
          DialogueId = 6200617,
          GUID = "0F85C8BA",
          NextDialogue = 6200618,
          RougeTalkActorType = 3
        },
        [6200618] = {
          Content = "“你希望我回头吗？”你不禁在心中问道。",
          DialogueId = 6200618,
          GUID = "0F85C8E4",
          NextDialogue = 6200619,
          RougeTalkActorType = 3
        },
        [6200619] = {
          Content = "不，你要沿着自己的道路前进。祂说。在轮回的终点，我们自会重逢。",
          DialogueId = 6200619,
          GUID = "0F85C90E",
          NextDialogue = 6200620,
          RougeTalkActorType = 3
        },
        [6200620] = {
          Content = "“终点在哪里？”你又问。",
          DialogueId = 6200620,
          GUID = "0F85C938",
          NextDialogue = 6200621,
          RougeTalkActorType = 3
        },
        [6200621] = {
          Content = "祂没有回答这个问题，黑暗越过你的肩头，温柔地填满了四周的空间，你的视野中只剩下提灯的光芒。",
          DialogueId = 6200621,
          GUID = "0F85C962",
          NextDialogue = 6200622,
          RougeTalkActorType = 3
        },
        [6200622] = {
          Content = "于是你拨动提灯上的表盘，让时间再次倒转。",
          DialogueId = 6200622,
          GUID = "0F85C98C",
          RougeTalkActorType = 3
        },
        [6200701] = {
          Content = "神秘的青年站在篝火边。事实上你并不确定他的年岁，只是通过声音如此推断。\n这不是你第一次见到他。",
          DialogueId = 6200701,
          GUID = "0F85D682",
          NextDialogue = 6200702,
          RougeTalkActorType = 3
        },
        [6200702] = {
          Content = "“又见面了，勇敢的旅人。”",
          DialogueId = 6200702,
          GUID = "0F85D6AC",
          NextDialogue = 6200703,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200703] = {
          Content = "青年礼貌地向你致候。\n你看不到他的眼睛——他戴着一张尖锐的金属面具，完全覆盖了脸庞的上半部分。",
          DialogueId = 6200703,
          GUID = "0F85D6D6",
          NextDialogue = 6200704,
          RougeTalkActorType = 3
        },
        [6200704] = {
          Content = "“在深渊中行走太久的人大多会迷失前路，最终成为那些幽影的一部分。”\n“这些物事散发的<H>光</>将会为你指引道路，使你不至于前路尽失。”他说，“你可以将它们放置于提灯之中，作为烛芯。”\n代替他的目光闪烁着的，是金属反射篝火的光泽。",
          DialogueId = 6200704,
          GUID = "0F85D700",
          NextDialogue = 6200705,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200705] = {
          Content = "“不过，我想你从未遗忘这些。因为你<H>总是</>会抵达这儿。”\n“我照旧准备了补给，就在那从篝火旁，请随时取用。”",
          DialogueId = 6200705,
          GUID = "0F85D72A",
          NextOptions = {
            [1] = 6200706
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200706] = {
          Content = "你是谁？",
          DialogueId = 6200706,
          GUID = "0F85D754",
          NextDialogue = 6200707,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200707] = {
          Content = "“你又问了这个问题。你问过很多很多次。但是请宽恕现在的我无法做出回答。”\n“我并非有意向你隐瞒，只是连我自己也不确定，此时此刻存在于此处的我究竟该以何种身份自居。”\n青年发出了一声轻笑。",
          DialogueId = 6200707,
          GUID = "0F85D77E",
          NextDialogue = 6200708,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200708] = {
          Content = "“所以，就让我们轻松一些吧——你只要将我当做一介普通的<H>商人</>就好。”\n“正如你总说，你只是一位普通的旅人。”",
          DialogueId = 6200708,
          GUID = "0F85D7A8",
          NextOptions = {
            [1] = 6200709
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200709] = {
          Content = "我该出发了。",
          DialogueId = 6200709,
          GUID = "0F85D7D2",
          IsKeyOption = true,
          NextDialogue = 6200710,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200710] = {
          Content = "“再见，勇敢的旅人。”他说，“愿你的旅途灯火长明。”\n你依旧看不见他的表情。或许面具之下的瞳孔中，也有摇曳的灯火倒映。",
          DialogueId = 6200710,
          GUID = "0F85D7FC",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200801] = {
          Content = "深渊行商伫立在篝火旁，如此前的每一次。\n这里没有幽影的啸叫，只有寂静环绕。",
          DialogueId = 6200801,
          GUID = "0F85E6EA",
          NextDialogue = 6200802,
          RougeTalkActorType = 3
        },
        [6200802] = {
          Content = "“又见面了，彷徨的旅人。”\n“你为这些微弱的<H>光</>而来。”\n深渊行商的声音一如既往沉静，如无波的湖水。\n“而我静候于此，为这盏提灯添上一枚新的烛芯。”",
          DialogueId = 6200802,
          GUID = "0F85E714",
          NextOptions = {
            [1] = 6200803
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200803] = {
          Content = "为什么不能直接送给我呢？",
          DialogueId = 6200803,
          GUID = "0F85E73E",
          NextDialogue = 6200804,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200804] = {
          Content = "“如你所见，我已经不再拥有那般力量。”\n商人摇了摇头。\n“如今的我能做的，便只有以微末魔法，将你那些小小的余烬化为微光的烛芯。”",
          DialogueId = 6200804,
          GUID = "0F85E768",
          NextDialogue = 6200805,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200805] = {
          Content = "深渊行商接过提灯。\n在他的手中，余烬渐渐亮起，如纷飞的萤火，最终凝成明亮的烛芯。",
          DialogueId = 6200805,
          GUID = "0F85E792",
          NextOptions = {
            [1] = 6200806
          },
          RougeTalkActorType = 3
        },
        [6200806] = {
          Content = "那么，谢谢你。",
          DialogueId = 6200806,
          GUID = "0F85E7BC",
          NextDialogue = 6200807,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200807] = {
          Content = "你晃了晃手中的提灯——注入了烛芯，原本微茫的灯光似乎明亮了几分。\n这盏灯是你唯一的陪伴。在这晦暗、幽邃的深渊中，只有它保护着你不至迷失。",
          DialogueId = 6200807,
          GUID = "0F85E7E6",
          NextOptions = {
            [1] = 6200808
          },
          RougeTalkActorType = 3
        },
        [6200808] = {
          Content = "我该出发了。",
          DialogueId = 6200808,
          GUID = "0F85E810",
          IsKeyOption = true,
          NextDialogue = 6200809,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200809] = {
          Content = "“再见，彷徨的旅人。”他说，“愿你的旅途灯火长明。”",
          DialogueId = 6200809,
          GUID = "0F85E83A",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200901] = {
          Content = "又一次地，你来到了这里。\n如果说这片黑暗还有什么地方能让你感到短暂的安心，那便是这里。",
          DialogueId = 6200901,
          GUID = "0F85F752",
          NextOptions = {
            [1] = 6200902
          },
          RougeTalkActorType = 3
        },
        [6200902] = {
          Content = "你还在这儿。",
          DialogueId = 6200902,
          GUID = "0F85F77C",
          NextDialogue = 6200903,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200903] = {
          Content = "“是的。”\n商人依旧沉静而温和。\n“在协助你终结这里的黑暗之前，我会一直在这里。”",
          DialogueId = 6200903,
          GUID = "0F85F7A6",
          NextOptions = {
            [1] = 6200904
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200904] = {
          Content = "可是除了你之外，没有人会记得我。",
          DialogueId = 6200904,
          GUID = "0F85F7D0",
          NextDialogue = 6200905,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200905] = {
          Content = "“深渊中的那些……幽灵，还有少数人类——当我拨动表盘回到过去，他们便不会再记得我。仿佛我们从未见过、从未说过话。”\n“即使我救下活着的人，下一次他们中的很多人依旧会死去。”\n“即使我遇到很多人，最终还是孑然一身。”",
          DialogueId = 6200905,
          GUID = "0F85F7FA",
          NextDialogue = 6200906,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200906] = {
          Content = "“是的。深渊的一切如潮水般往复，一遍又一遍被推回往昔岁月。”\n“但你是特别的——作为那面表盘现在的主人，你已经立于时间之外。”\n他叹了口气。",
          DialogueId = 6200906,
          GUID = "0F85F824",
          NextDialogue = 6200907,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200907] = {
          Content = "“在这片深渊里，你主宰着时间。只有你是<H>永恒的</>。这是神的权柄。”\n“但正是它让你成为一个神座上的囚徒。它意味着你必须亲眼看着一切从你身边无可避免地失去。”\n行商平静的声音中有一丝不易察觉的波动。\n“但它也是你能与深渊本身对抗的唯一方式。”",
          DialogueId = 6200907,
          GUID = "0F85F84E",
          NextOptions = {
            [1] = 6200908
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200908] = {
          Content = "我该出发了。",
          DialogueId = 6200908,
          GUID = "0F85F878",
          IsKeyOption = true,
          NextDialogue = 6200909,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200909] = {
          Content = "“再见，孤独的旅人。”他说，“愿你的旅途灯火长明。”",
          DialogueId = 6200909,
          GUID = "0F85F8A2",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201001] = {
          Content = "你再度得到了短暂的喘息。\n没有幽影的纠缠，没有灵魂的哀鸣。这里是安全的。\n你靠着一截断墙缓缓滑坐下去。",
          DialogueId = 6201001,
          GUID = "0F8607BA",
          NextOptions = {
            [1] = 6201002
          },
          RougeTalkActorType = 3
        },
        [6201002] = {
          Content = "我累了。",
          DialogueId = 6201002,
          GUID = "0F8607E4",
          NextDialogue = 6201003,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201003] = {
          Content = "“一遍又一遍地前进，一遍又一遍地重来。”\n“我知道这是我的战斗，但我不知道它还会持续多久。”",
          DialogueId = 6201003,
          GUID = "0F86080E",
          NextDialogue = 6201004,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201004] = {
          Content = "“当神的赐福——<H>纯净琉璃</>再度汇聚，提灯被修复，奇迹便会从中显露。”\n“你将获得足以撕裂这片黑暗的光。”",
          DialogueId = 6201004,
          GUID = "0F860838",
          NextOptions = {
            [1] = 6201005
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201005] = {
          Content = "不，我想知道的不是这个。",
          DialogueId = 6201005,
          GUID = "0F860862",
          NextDialogue = 6201006,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201006] = {
          Content = "“我甚至不知道我在这里度过了多久——十年？二十年？还是更长时间？我唯一知道的就是我拨动了多少次表盘。”\n“可这盏灯的光芒还是如此微弱，仿佛我所做的一切都毫无意义。”\n“会不会直到我死，我还是无法修复它——那么我经历的这些又算什么？”\n“一出愚蠢而荒诞的悲剧？”",
          DialogueId = 6201006,
          GUID = "0F86088C",
          NextDialogue = 6201007,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201007] = {
          Content = "“是的。”\n他没有否认，这让你有些惊讶。",
          DialogueId = 6201007,
          GUID = "0F8608B6",
          NextDialogue = 6201008,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201008] = {
          Content = "“我看到你一遍又一遍地挥动兵刃，驱散幽影，正如我看到万个工匠日复一日地打磨巨石为神殿筑基。”\n“我看到一个女孩周而复始地向火焰里投下石子，正如我看到万个农人年复一年地在田地里播撒种子。”\n“一切辛劳，都只是为了下一次重复同样的辛劳。不只是你与我，深渊里的灵魂，以及地上的生者，所有人都在重复着这场悲剧。”\n“若你为此感到痛苦，你随时可以停下来，这样便可以结束这一切。”",
          DialogueId = 6201008,
          GUID = "0F8608E0",
          NextOptions = {
            [1] = 6201009
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201009] = {
          Content = "拒绝。",
          DialogueId = 6201009,
          GUID = "0F86090A",
          NextDialogue = 6201010,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201010] = {
          Content = "结束这一切——意味着你将成为和它们一样的一缕幽魂。\n你将不再有柔软而敏感的心。你不再惧怕孤独，也不再因周而复始的荒诞而痛苦。\n但是——这样，就是幸福么？",
          DialogueId = 6201010,
          GUID = "0F860934",
          NextDialogue = 6201011,
          RougeTalkActorType = 3
        },
        [6201011] = {
          Content = "“不。”你重新捡起兵刃。\n“我会继续战斗下去。继续去寻找那些该死的琉璃。”",
          DialogueId = 6201011,
          GUID = "0F86095E",
          NextOptions = {
            [1] = 6201012
          },
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201012] = {
          Content = "我该出发了。",
          DialogueId = 6201012,
          GUID = "0F860988",
          IsKeyOption = true,
          NextDialogue = 6201013,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201013] = {
          Content = "“再见，志坚的旅人。”他说，“愿你的旅途灯火长明。”",
          DialogueId = 6201013,
          GUID = "0F8609B2",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201101] = {
          Content = "深渊行商从你手中接过提灯。未曾言语，你们默契地交换着余烬与烛芯。\n这一次，你并没有打算在这里逗留。",
          DialogueId = 6201101,
          GUID = "0F861822",
          NextOptions = {
            [1] = 6201102
          },
          RougeTalkActorType = 3
        },
        [6201102] = {
          Content = "我该出发了。",
          DialogueId = 6201102,
          GUID = "0F86184C",
          IsKeyOption = true,
          NextDialogue = 6201103,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201103] = {
          Content = "“请收下这个。”\n青年的声音在身后响起。他将一件物事交到你手上。\n“它不会发光，所以它不需余烬交换。”\n那是一枚糖果，晶莹而透明，静静地躺在你沾满血污和灰烬的手心里。",
          DialogueId = 6201103,
          GUID = "0F861876",
          NextDialogue = 6201104,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201104] = {
          Content = "你将它缓缓吞入口中，是野薄荷的味道。它让你前所未有地清醒，你终于找回了一些人的知觉。\n你的脑海里不再只有幽影。你开始想起耸入云端的高塔，想起总是忍不住攀爬的橡子树，想起餐盘上冰凉的奶油，想起庭院里摆荡的秋千。\n那是你活过的证明。",
          DialogueId = 6201104,
          GUID = "0F8618A0",
          NextDialogue = 6201105,
          RougeTalkActorType = 3
        },
        [6201105] = {
          Content = "那么，这位神秘的深渊行商呢？你甚至不知道他是一个人，还是一个幽灵——他也会喜欢甜味吗？他会因困在深渊的囚笼里痛苦吗？他也曾在深渊之上——在太阳能照射到的世界真切地活过吗？\n但你没有时间思考这些了。\n你必须战斗下去，永不停息。",
          DialogueId = 6201105,
          GUID = "0F8618CA",
          NextDialogue = 6201106,
          RougeTalkActorType = 3
        },
        [6201106] = {
          Content = "“再见，清醒的旅人。”他说，“愿你的旅途灯火长明。”",
          DialogueId = 6201106,
          GUID = "0F8618F4",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201201] = {
          Content = "最近你已经开始不那么疲惫了，甚至可以轻松地和那些幽影攀谈。\n你不知道是你的心真的开始变得坚硬，麻木，还是这只是一次崩毁的前兆。\n但至少此刻，你心情尚可。",
          DialogueId = 6201201,
          GUID = "0F86288A",
          NextDialogue = 6201202,
          RougeTalkActorType = 3
        },
        [6201202] = {
          Content = "“我在一天同时遇到了满月的信徒和暗月的信徒。”\n“一个说自己信仰光明，一个说自己侍奉黑暗。但好笑的是，当你说你对他们的神不感兴趣的时候，他们口中却吐出同样的粗鄙之言。”\n“那么，你呢？你有信奉的神吗？”",
          DialogueId = 6201202,
          GUID = "0F8628B4",
          NextDialogue = 6201203,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201203] = {
          Content = "“我是芙萨的侍者。”\n这是行商头一次回答关于他自己的问题。\n“我尊祂的名，赞颂祂的慈爱，敬奉满月的光辉。”",
          DialogueId = 6201203,
          GUID = "0F8628DE",
          NextDialogue = 6201204,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201204] = {
          Content = "深渊行商的话让你感到有些意外——你以为他会做出些更有趣的回答。",
          DialogueId = 6201204,
          GUID = "0F862908",
          NextDialogue = 6201205,
          RougeTalkActorType = 3
        },
        [6201205] = {
          Content = "“所以，你相信艾利西安正教的那些教义喽？”\n“只要向满月女神虔诚祈祷，祂就会织造幸福的丝线，将我们拯救。”",
          DialogueId = 6201205,
          GUID = "0F862932",
          NextDialogue = 6201206,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201206] = {
          Content = "“不。我<H>追随</>芙萨，但我并不<H>相信</>芙萨。”\n“我只是需要一个确定的理由，让我走上我认为正确的道路。”",
          DialogueId = 6201206,
          GUID = "0F86295C",
          NextOptions = {
            [1] = 6201207
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201207] = {
          Content = "我不明白你的意思。",
          DialogueId = 6201207,
          GUID = "0F862986",
          NextDialogue = 6201208,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201208] = {
          Content = "“我们应施与，不应掠夺。”\n“我们应友爱，不应憎恨。”\n“我们应拥抱他人，不应割伤他人。”\n“这是我所认为的‘正确’——但如果我相信人是自由的，那我便找不到什么来证明它们正确。”",
          DialogueId = 6201208,
          GUID = "0F8629B0",
          NextDialogue = 6201209,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201209] = {
          Content = "“所以我抛弃了‘自由’，选择超越一切的芙萨。这样，我所认为的正确就成为了确凿无瑕、无需证明的真理。”\n他叹了口气。\n“某种意义上，也许我才是对芙萨最不敬的那个。”",
          DialogueId = 6201209,
          GUID = "0F8629DA",
          NextDialogue = 6201210,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201210] = {
          Content = "“所以你的意思是……”\n你在脑海中组织着语言。\n“我想说服自己在这片深渊继续走下去，我就信奉一个……呃，行走之神，来说服自己必须走下去？”",
          DialogueId = 6201210,
          GUID = "0F862A04",
          NextDialogue = 6201211,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201211] = {
          Content = "“嗯……你可以这样理解。”\n他轻笑了一下。",
          DialogueId = 6201211,
          GUID = "0F862A2E",
          NextOptions = {
            [1] = 6201212
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201212] = {
          Content = "真是个怪家伙。不过我该走了，我已经逗留了太久。",
          DialogueId = 6201212,
          GUID = "0F862A58",
          IsKeyOption = true,
          NextDialogue = 6201213,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201213] = {
          Content = "“再见，聪慧的旅人。”他说，“愿你的旅途灯火长明。”",
          DialogueId = 6201213,
          GUID = "0F862A82",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201301] = {
          Content = "“我已经很久没有休息过了。”\n在来到这儿之前，你便在盘算这一次的交易。\n“我能向你买一样东西么——买一场梦？”\n“如果你能做到。”",
          DialogueId = 6201301,
          GUID = "0F8638F2",
          NextDialogue = 6201302,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201302] = {
          Content = "“我不是筑梦师，无法保证提供你想要的东西。”\n他缓缓摇了摇头。\n“但或许我可以尝试。\n“很久很久之前，当我给我的同胞姊妹讲故事时，她总是睡得很香甜。”",
          DialogueId = 6201302,
          GUID = "0F86391C",
          NextDialogue = 6201303,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201303] = {
          Content = "你找了一叠草垛，尽量把它铺得松软一些。\n你又一次感到疲惫了。你渴望一场梦，一场短暂的休憩。",
          DialogueId = 6201303,
          GUID = "0F863946",
          NextDialogue = 6201304,
          RougeTalkActorType = 3
        },
        [6201304] = {
          Content = "“很久很久以前，有一个少年，他是一名雕金匠；他爱上了月亮。”\n“他悄悄测量了月亮的尺寸，打算用世间最璀璨的宝石，打造一条最美的项链送给弯弯的月亮作为礼物。”\n“可当他终于打造出那条项链时，却发现月亮长胖了一些，已经戴不上那条漂亮的项链了。”\n“于是他决定重新打造一条项链。这一次他把自己收集的所有宝石都镶上去了。可当他再度见到月亮时，月亮已经更胖了，像一只圆滚滚的盘子。”",
          DialogueId = 6201304,
          GUID = "0F863970",
          NextDialogue = 6201305,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201305] = {
          Content = "这是一个古老的童话。你依稀记得你的母亲也曾讲过这个故事。\n你脑中泛起稀薄的睡意。",
          DialogueId = 6201305,
          GUID = "0F86399A",
          NextDialogue = 6201306,
          RougeTalkActorType = 3
        },
        [6201306] = {
          Content = "“……那就打造三条不同尺寸的吧，总有一条月亮能戴上。年轻的雕金匠想。”\n“但当他向心爱的月亮奉上三条项链时，月亮却消失了——漆黑的天幕只有点点繁星，仿佛月亮从不曾来过。”",
          DialogueId = 6201306,
          GUID = "0F8639C4",
          NextDialogue = 6201307,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201307] = {
          Content = "你缓缓沉入银辉的梦乡。",
          DialogueId = 6201307,
          GUID = "0F8639EE",
          NextDialogue = 6201308,
          RougeTalkActorType = 3
        },
        [6201308] = {
          Content = "“……于是，弄丢了月亮的雕金匠日复一日地敲着铁锤，徒劳无功地做着项链。”\n“他的眼泪落在大地上，长出透亮的树木，结出晶莹的果实，像他挚爱的月亮一样。”\n“后来的人们称它们为‘天之树’和‘月石’……”\n“疲惫的旅人，你已经睡了吗？那就做个好梦吧。”",
          DialogueId = 6201308,
          GUID = "0F863A18",
          NextDialogue = 6201309,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201309] = {
          Content = "第一个梦里，你看见秋千在庭院的花园里摆荡。\n你变得那么小。年迈的管家站在秋千旁，向你伸出双臂，等着你扑进他的怀抱。\n“欢迎回来，我的▇▇。”\n……",
          DialogueId = 6201309,
          GUID = "0F863A42",
          NextDialogue = 6201310,
          RougeTalkActorType = 3
        },
        [6201310] = {
          Content = "第二个梦里，你看见年轻的骑士们站在百里香盛放的山坡上。\n他们高举着金色鸢尾的旗帜，发丝在风中飞扬。他们笑着，呼喊着你的名字。\n“出发吧，我的▇▇大人。”\n……",
          DialogueId = 6201310,
          GUID = "0F863A6C",
          NextDialogue = 6201311,
          RougeTalkActorType = 3
        },
        [6201311] = {
          Content = "第三个梦里，你看见那个和你提着同样提灯的旅人。你曾见过{性别：他|她}三次。\n{性别：他|她}的身影越来越远，就要没入幽邃的黑暗。\n你跑过去，三步并作两步。",
          DialogueId = 6201311,
          GUID = "0F863A96",
          NextDialogue = 6201312,
          RougeTalkActorType = 3
        },
        [6201312] = {
          Content = "“你可以留下来吗？”\n你喊出声，嗓音嘶哑，这比任何一次战斗都要令你狼狈。",
          DialogueId = 6201312,
          GUID = "0F863AC0",
          NextDialogue = 6201313,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201313] = {
          Content = "“对不起，▇▇。”\n{性别：他|她}回过头，摇曳的灯火照亮了{性别：他|她}的脸，你却看不真切。\n“我们走在<H>反方向的路</>上。所以，我必须离开了。”",
          DialogueId = 6201313,
          GUID = "0F863AEA",
          NextDialogue = 6201314,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char02"
        },
        [6201314] = {
          Content = "“但是——我已经不想再一个人了！”\n你试图拉住那个人的衣角——像顽劣的孩童索要最后一粒糖果——但你什么也没有抓到。\n你流下眼泪——你已经多久没有流过泪了？",
          DialogueId = 6201314,
          GUID = "0F863B14",
          NextDialogue = 6201315,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201315] = {
          Content = "“别哭，▇▇。”\n{性别：他|她}抚摸着你的脸颊，拭去泪水，温柔而慈悲。你感受到{性别：他|她}的呼吸，感受到人类的体温。\n“我们的路是<H>一个圆环</>。所以就算向着反方向行走，我们也一定会再度重逢。”",
          DialogueId = 6201315,
          GUID = "0F863B3E",
          NextDialogue = 6201316,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char02"
        },
        [6201316] = {
          Content = "你看到{性别：他|她}手中的提灯渐渐亮起来，发出银白色的光辉，越来越亮，像一轮正在倾洒银缕的满月——\n{性别：他|她}步入了那灼目的银白中。\n……\n……\n你在野薄荷的气息中醒来。",
          DialogueId = 6201316,
          GUID = "0F863B68",
          NextDialogue = 6201317,
          RougeTalkActorType = 3
        },
        [6201317] = {
          Content = "“是个好梦吗？”",
          DialogueId = 6201317,
          GUID = "0F863B92",
          NextDialogue = 6201318,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201318] = {
          Content = "“是的……它很长、很长。像过了很多很多年那样长。”",
          DialogueId = 6201318,
          GUID = "0F863BBC",
          NextDialogue = 6201319,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201319] = {
          Content = "“这很好。很幸运，你还可以做梦。”",
          DialogueId = 6201319,
          GUID = "0F863BE6",
          NextDialogue = 6201320,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201320] = {
          Content = "你站起身，握紧提灯。你将继续奔赴你的战争——\n一场看不见尽头的孤旅。",
          DialogueId = 6201320,
          GUID = "0F863C10",
          NextOptions = {
            [1] = 6201321
          },
          RougeTalkActorType = 3
        },
        [6201321] = {
          Content = "谢谢你，我该走了。",
          DialogueId = 6201321,
          GUID = "0F863C3A",
          IsKeyOption = true,
          NextDialogue = 6201322,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201322] = {
          Content = "“再见，坚忍的旅人。”他说。\n“愿某个未来里，你的旅途不再是孤身一人。”",
          DialogueId = 6201322,
          GUID = "0F863C64",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201401] = {
          Content = "黑暗、黑暗、以及更深的黑暗——\n你感到自己正在寂静的水底漂游。\n沿着幽深的河流，一路向下。",
          DialogueId = 6201401,
          GUID = "0F86495A",
          NextDialogue = 6201402,
          RougeTalkActorType = 3
        },
        [6201402] = {
          Content = "——而后，由远及近地，你看到了光。\n那是一盏<H>灯</>。",
          DialogueId = 6201402,
          GUID = "0F864984",
          NextDialogue = 6201403,
          RougeTalkActorType = 3
        },
        [6201403] = {
          Content = "“你回来了。我知道，你会回来。”\n摇曳的灯火照亮了执灯人的面庞，那是一位苍老的妇人。",
          DialogueId = 6201403,
          GUID = "0F8649AE",
          NextOptions = {
            [1] = 6201404
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01"
        },
        [6201404] = {
          Content = "你认识我？",
          DialogueId = 6201404,
          GUID = "0F8649D8",
          NextDialogue = 6201405,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201405] = {
          Content = "“是的。”\n她苍老的眼睛泛起光亮，像枯死的朽木绽放出花。\n“我已经等了你很久很久。”",
          DialogueId = 6201405,
          GUID = "0F864A02",
          NextOptions = {
            [1] = 6201406
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01"
        },
        [6201406] = {
          Content = "我好像记不起我是谁。",
          DialogueId = 6201406,
          GUID = "0F864A2C",
          NextDialogue = 6201407,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201407] = {
          Content = "“我们走过的路是<H>一个圆环</>。”\n她笑了起来。\n“当你再度回到这里，你便已然记起一切。”",
          DialogueId = 6201407,
          GUID = "0F864A56",
          NextOptions = {
            [1] = 6201408
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01"
        },
        [6201408] = {
          Content = "我接下来应当做什么？",
          DialogueId = 6201408,
          GUID = "0F864A80",
          NextDialogue = 6201409,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201409] = {
          Content = "“离开这儿，离开这片<H>深渊</>。这是<H>每一个你</>的夙愿。”\n老妇人把提灯交到你手上。她的手指冰凉，像一个幽灵。那盏提灯却散发着金黄的光，炽烈的，温暖的。\n你留意到，灯上镶嵌着一个有<H>刻度</>的表盘。",
          DialogueId = 6201409,
          GUID = "0F864AAA",
          NextOptions = {
            [1] = 6201410
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01"
        },
        [6201410] = {
          Content = "我如何才能离开这儿？",
          DialogueId = 6201410,
          GUID = "0F864AD4",
          IsKeyOption = true,
          NextDialogue = 6201411,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201411] = {
          Content = "“这是一盏被神赐福的灯。”\n“当你用足够多的<H>纯净琉璃</>最终修复它，它便会在这片深渊的海中分开道路。”\n“若你遇到致命的危险，便<H>倒转</>那个表盘。”",
          DialogueId = 6201411,
          GUID = "0F864AFE",
          NextDialogue = 6201412,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01"
        },
        [6201412] = {
          Content = "“踏上旅途前，也许你会想听些关于这片深渊的故事。”\n她依旧静默而温和地微笑着。\n“这些故事是时间河流中漂浮的木片——我说过，我们走过的路是一个圆环——它们于你而言可能是‘过去’的故事，也可能是‘未来’的故事。”\n“但毫无疑问，<H>它们是关于你的故事</>。”",
          DialogueId = 6201412,
          GUID = "0F864B28",
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01"
        },
        [6201501] = {
          Content = "你听见一阵脚步声自黑暗中传来，沉闷而拖沓，带着沙沙的尾音。\n你朝着脚步声所在的方向前进，四个年轻的身影出现在你的眼前——是静默黄昏小队的骑士们，你的道路再次与他们交汇了。他们看起来还平安无事，只是神情已与上一次相遇时天差地别。",
          DialogueId = 6201501,
          GUID = "0F8659C2",
          NextDialogue = 6201502,
          RougeTalkActorType = 3
        },
        [6201502] = {
          Content = "“还要继续走吗？我们已经走了多久了？”\n术士的嗓音被疲惫填满，仿佛她背上披着的并非一件斗篷，而是一块厚重的石板。",
          DialogueId = 6201502,
          GUID = "0F8659EC",
          NextDialogue = 6201503,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201503] = {
          Content = "“大概……四天？五天……？也可能更久。我的怀表已经失灵了。”\n司祭的声音像刀片刮过纸张的毛边；即便虔诚如他，也无法再维持平素那种恭谨的语气了。",
          DialogueId = 6201503,
          GUID = "0F865A16",
          NextDialogue = 6201504,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201504] = {
          Content = "“既然大家都累了，就在这里停下休整吧。你们可以睡一会儿，我会留意周围的动静。”\n青年体贴地说道，尽管他自己的声音也透露出分明的倦意。",
          DialogueId = 6201504,
          GUID = "0F865A40",
          NextDialogue = 6201505,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201505] = {
          Content = "“我和你一起吧，这样万一我们两个中有谁不小心睡着了，还能互相叫醒一下！”\n她尽可能地以轻松的口吻说出了这个提议，并在弗林一脸自责地想要开口说“抱歉”之前用眼神制止了他。",
          DialogueId = 6201505,
          GUID = "0F865A6A",
          NextDialogue = 6201506,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201506] = {
          Content = "于是，四人找到一片还算平整的地面，将身上的行囊放下，搭建了起简陋的临时营地。\n在卡莉斯塔和米尔顿开始休息之后，弗林和凯希稍微走远了一些。沉默笼罩着他们的背影，画面仿佛定格了。\n忽然，弗林低下头，用只有自己和凯希能听到的音量轻轻地叹了一口气。",
          DialogueId = 6201506,
          GUID = "0F865A94",
          NextDialogue = 6201507,
          RougeTalkActorType = 3
        },
        [6201507] = {
          Content = "“哎呀，难得听到你叹气哦。”女孩笑眯眯地从口袋里掏出一个小纸包，“要不要吃颗糖？我偷偷带进来的。只剩两颗了，我们分掉吧。”",
          DialogueId = 6201507,
          GUID = "0F865ABE",
          NextDialogue = 6201508,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201508] = {
          Content = "“……不用了，谢谢。既然你爱吃，还是自己留着吧。”",
          DialogueId = 6201508,
          GUID = "0F865AE8",
          NextDialogue = 6201509,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201509] = {
          Content = "“糖果要和朋友一起分享才更甜喔。”",
          DialogueId = 6201509,
          GUID = "0F865B12",
          NextDialogue = 6201510,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201510] = {
          Content = "凯希将一颗糖丢进嘴里，然后执意把剩下的最后一颗连着糖纸一起塞到了弗林手中。然而弗林只是沉默地低着头，没有任何反应。\n凯希没有再说什么，一边抿着糖果，一边静静地等待——等待她的友人整理好思绪，再次开启这段对话。",
          DialogueId = 6201510,
          GUID = "0F865B3C",
          NextDialogue = 6201511,
          RougeTalkActorType = 3
        },
        [6201511] = {
          Content = "“刚才那个……拿着剑的幽影……你看见了吗？”\n终于，青年低声开口道。",
          DialogueId = 6201511,
          GUID = "0F865B66",
          NextDialogue = 6201512,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201512] = {
          Content = "“你是指那个敌我不分、连幽影都砍的家伙吗？我当然看见了，他那把银剑发出的白光亮得晃眼，简直就和传说中你那位偶像用的武器一样……呢……”\n说到这里，女孩似乎意识到了什么，转头看向弗林。\n“难道……他就是那位<H>月升时</>的骑士吗？”",
          DialogueId = 6201512,
          GUID = "0F865B90",
          NextDialogue = 6201513,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201513] = {
          Content = "“……是的。就是他。我看过无数遍与他有关的影像和画册，不会认错。”\n青年叹了一口气，用双手捂住了自己的脸。\n“我……说真的，认出他的那一刻，我感到很害怕。如果连他都输给了深渊，我们又要怎么赢呢？我忍不住想，我最后是不是也会变成那样？我……也会变成向着同胞挥剑的人吗？”",
          DialogueId = 6201513,
          GUID = "0F865BBA",
          NextDialogue = 6201514,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201514] = {
          Content = "“确实，在进入深渊之前，我们都没想到这个地方会如此可怕……但我还是相信，即便如此，人类的意志也一定能够赢过它。”\n女孩轻轻地拍了拍友人的后背。\n“你想啊，那位骑士会攻击其他幽影，不正说明他没有认输吗？即便变成这副模样，他也还记得最初的目标，不是吗？”",
          DialogueId = 6201514,
          GUID = "0F865BE4",
          NextDialogue = 6201515,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201515] = {
          Content = "“嗯……”",
          DialogueId = 6201515,
          GUID = "0F865C0E",
          NextDialogue = 6201516,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201516] = {
          Content = "这似乎不是一个适合加入谈话的时机，你也无意打扰这些年轻人的休息。\n但正当你打算离开时，凯希发现了你。",
          DialogueId = 6201516,
          GUID = "0F865C38",
          NextDialogue = 6201517,
          RougeTalkActorType = 3
        },
        [6201517] = {
          Content = "“咦？”女孩激动地向你走过来，“您是之前那位旅人！太好了，您还平安无事呀！”",
          DialogueId = 6201517,
          GUID = "0F865C62",
          NextDialogue = 6201518,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201518] = {
          Content = "青年也跟着走过来，神色颇有些惊讶。\n“阁下果然并非一般人物。您比我们更早进入深渊，究竟是如何做到保持意志坚定的？”",
          DialogueId = 6201518,
          GUID = "0F865C8C",
          NextOptions = {
            [1] = 6201519
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201519] = {
          Content = "我……只是习惯了而已。我也曾经迷茫过、后悔过、绝望过，但现在，我已经接受了。",
          DialogueId = 6201519,
          GUID = "0F865CB6",
          NextDialogue = 6201520,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201520] = {
          Content = "青年脸上的惊讶慢慢转变为钦佩。\n“那么……您是如何看待深渊的呢？您认为，人类会战胜它吗？”",
          DialogueId = 6201520,
          GUID = "0F865CE0",
          NextOptions = {
            [1] = 6201521,
            [2] = 6201524
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201521] = {
          Content = "一定会的。",
          DialogueId = 6201521,
          GUID = "0F865D0A",
          IsKeyOption = true,
          NextDialogue = 6201522,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201522] = {
          Content = "“你看，旅人阁下也这么说。我们一定能完成任务的，要打起精神来呀！”",
          DialogueId = 6201522,
          GUID = "0F865D34",
          NextDialogue = 6201523,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201523] = {
          Content = "她似乎误解了你的意思。你所相信的“胜利”，与传颂会下达给这些骑士的目标截然不同。\n你很清楚，前方等待着他们的只有痛苦和绝望。他们注定会一遍遍地经历死亡，却对自己身处的地狱一无所知。\n但你没有再开口。如果未来无法改变，那么无知也是一种幸福。",
          DialogueId = 6201523,
          GUID = "0F865D5E",
          RougeTalkActorType = 3
        },
        [6201524] = {
          Content = "我不知道。",
          DialogueId = 6201524,
          GUID = "0F865D88",
          IsKeyOption = true,
          NextDialogue = 6201525,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201525] = {
          Content = "“连您也没有信心吗……”\n青年的目光黯淡下去。但很快，他又重新抬起头，以一种异常坚定的声音开口——你不知道他到底是在鼓励自己，还是在欺骗自己。\n“无论如何，作为艾利西安的骑士，我们不能退缩。哪怕真的没有希望，我们也一定会战斗到最后一刻。”",
          DialogueId = 6201525,
          GUID = "0F865DB2",
          NextDialogue = 6201526,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201526] = {
          Content = "你很清楚，前方等待着他们的只有痛苦和绝望。他们注定会一遍遍地经历死亡，却对自己身处的地狱一无所知。\n但看着骑士坚定的目光，你终究不忍心再开口。",
          DialogueId = 6201526,
          GUID = "0F865DDC",
          RougeTalkActorType = 3
        },
        [6201601] = {
          Content = "钢铁碰撞的激鸣声自黑暗中传来，前方显然正在发生一场恶战。\n你看到年轻的骑士奋力举起长剑，给予面前的幽影最后一击。",
          DialogueId = 6201601,
          GUID = "0F866A2A",
          NextDialogue = 6201602,
          RougeTalkActorType = 3
        },
        [6201602] = {
          Content = "忽然间，一道纤细的黑影划过。骑士迅速地举起盾牌，防住了这次偷袭。但当他看清楚那支插在盾牌裂口里的细箭时，他愣住了。\n箭羽上装饰着象征艾利西安的金色圣鸢尾纹，但底色却被涂成了黑色。只有一个人会这么",
          DialogueId = 6201602,
          GUID = "0F866A54",
          NextDialogue = 6201603,
          RougeTalkActorType = 3
        }
      }
    end
  },
  {
    MinKey = 6201603,
    MaxKey = 10011708,
    Loader = function()
      return {
        [6201603] = {
          Content = "“卡莉斯塔……？”",
          DialogueId = 6201603,
          GUID = "0F866A7E",
          NextDialogue = 6201604,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201604] = {
          Content = "幽影步步逼近，被黑暗侵蚀的肢体几乎与身上的斗篷融为一体。“她”对弗林的呼唤置若罔闻，只是沉默着再一次搭箭引弓。",
          DialogueId = 6201604,
          GUID = "0F866AA8",
          NextDialogue = 6201605,
          RougeTalkActorType = 3
        },
        [6201605] = {
          Content = "早在最初进入深渊的时候，他们四人就惊讶地发现，那些具有攻击性的人形幽影中有相当一部分是熟识的身影。那些人都是艾利西安的骑士，为了讨伐深渊而来，却在死后被同化为深渊的一部分，对曾经的同伴拔刀相向。",
          DialogueId = 6201605,
          GUID = "0F866AD2",
          NextDialogue = 6201606,
          RougeTalkActorType = 3
        },
        [6201606] = {
          Content = "这便是深渊最可怖的诅咒——“活着”本身即是诅咒。若一个人进入深渊没多久便死去，他尚且可以成为一个最普通不过的亡灵，像他生前的样子。",
          DialogueId = 6201606,
          GUID = "0F866AFC",
          NextDialogue = 6201607,
          RougeTalkActorType = 3
        },
        [6201607] = {
          Content = "但倘若他不愿轻易死去，而是选择前进，那么在深渊中度过的每一分、每一秒，混沌的黑暗都将不断侵蚀他的意志。到最后，每一场战斗都变成一次豪赌：但凡有一个瞬间他动摇了意志，便会被黑暗吞噬思绪，化作没有理智、只会攻击的怪物。",
          DialogueId = 6201607,
          GUID = "0F866B26",
          NextDialogue = 6201608,
          RougeTalkActorType = 3
        },
        [6201608] = {
          Content = "就像如今站在弗林面前的“她”一样。",
          DialogueId = 6201608,
          GUID = "0F866B50",
          NextDialogue = 6201609,
          RougeTalkActorType = 3
        },
        [6201609] = {
          Content = "“不……不要这样……我不想伤害你……拜托……”青年握着长剑的手开始颤抖，“米尔顿已经牺牲了，如果连你也……”",
          DialogueId = 6201609,
          GUID = "0F866B7A",
          NextDialogue = 6201610,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201610] = {
          Content = "可箭还是向他飞了出来，精准地朝着他心脏的方向。他举起盾牌，挡下这一击。又一支箭飞过来，在他的脸颊上擦出一道血痕。",
          DialogueId = 6201610,
          GUID = "0F866BA4",
          NextDialogue = 6201611,
          RougeTalkActorType = 3
        },
        [6201611] = {
          Content = "“啊啊啊……！”",
          DialogueId = 6201611,
          GUID = "0F866BCE",
          NextDialogue = 6201612,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201612] = {
          Content = "伴随着痛苦的叫喊声，青年举起了手中的长剑。一剑、一剑、又一剑，直到那幽影终于消散。\n面对已经化为灰烬的同伴，他用长剑撑着摇摇欲坠的身体，失声痛哭。",
          DialogueId = 6201612,
          GUID = "0F866BF8",
          NextDialogue = 6201613,
          RougeTalkActorType = 3
        },
        [6201613] = {
          Content = "当哭声终于停下，四周陷入了异样的寂静。战斗分明已经结束，可是与他并肩作战的友人，那个喜欢上蹿下跳、永远吵吵闹闹的女孩，却没有像往常那样笑着回到他身边。",
          DialogueId = 6201613,
          GUID = "0F866C22",
          NextDialogue = 6201614,
          RougeTalkActorType = 3
        },
        [6201614] = {
          Content = "“凯希……凯希？你还好吗？”\n他拖着满是伤痕的身体，朝着友人所在的方向挪动。",
          DialogueId = 6201614,
          GUID = "0F866C4C",
          NextDialogue = 6201615,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201615] = {
          Content = "女孩似乎没有听到他的呼唤。她站在原地，双手无力地低垂。她的呼吸声很急促，就像是快要窒息那般徒劳地试图留住空气。\n不祥的黑色阴影从她的伤口处涌出来，缠绕上她的四肢，染黑了那漂亮的金发，最后终于将她的身影完全吞噬。",
          DialogueId = 6201615,
          GUID = "0F866C76",
          NextDialogue = 6201616,
          RougeTalkActorType = 3
        },
        [6201616] = {
          Content = "长剑坠落在血与泪调和的泥浆中，青年无力地跪倒在地。",
          DialogueId = 6201616,
          GUID = "0F866CA0",
          NextDialogue = 6201617,
          RougeTalkActorType = 3
        },
        [6201617] = {
          Content = "“我……投降了。你听到了吗？”\n他闭上眼睛，仰头朝向天空——如果那深邃的黑暗能够被称为天空的话——声音平静得像一潭死水。\n“无论你是什么……无论你为什么要这样折磨我们，我已经受够了。我累了。到此为止吧，把我也带走吧……”",
          DialogueId = 6201617,
          GUID = "0F866CCA",
          NextDialogue = 6201618,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201618] = {
          Content = "前方传来窸窸窣窣的声响，有什么东西慢慢地靠近了他。他没有睁开眼睛，只是以一种决绝的姿态等待着死亡。\n一双手拾起了他的长剑，重新将它交到他的手中。",
          DialogueId = 6201618,
          GUID = "0F866CF4",
          NextDialogue = 6201619,
          RougeTalkActorType = 3
        },
        [6201619] = {
          Content = "“原来你对我这么没有信心啊？”\n女孩的声音透过黑暗传出来。那温柔的阴影擦去了青年的泪水，温柔地拥抱他低垂的头颅，遮住了他身上的血污。\n“放心吧，无论发生什么……我向你保证，至少，我一定不会改变。”",
          DialogueId = 6201619,
          GUID = "0F866D1E",
          NextDialogue = 6201620,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201620] = {
          Content = "“……嗯。我相信你。”\n青年伸出了双臂，迎接那片黑暗。",
          DialogueId = 6201620,
          GUID = "0F866D48",
          NextDialogue = 6201621,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201621] = {
          Content = "明知这只是无谓的希望，明知这样做只会让他们承受更多的痛苦，你终究还是没有忍住——\n你举起提灯，快步走到两人身边。在琉璃的光辉之下，笼罩他们的黑暗散去了，女孩的长发再次泛起美丽的金色光泽。\n得救的骑士们怔怔地抬起头，望向你。",
          DialogueId = 6201621,
          GUID = "0F866D72",
          NextDialogue = 6201622,
          RougeTalkActorType = 3
        },
        [6201622] = {
          Content = "“旅人阁下……？您救了我们吗？”\n女孩检视着自己恢复正常的双手，露出不可思议的神情。\n“多谢您……！虽然早就知道您不是一般人，但还是没想到，您竟然拥有如此强大的力量。”",
          DialogueId = 6201622,
          GUID = "0F866D9C",
          NextDialogue = 6201623,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201623] = {
          Content = "“哈……”\n青年恍惚地舒了一口气，似乎还没有反应过来。",
          DialogueId = 6201623,
          GUID = "0F866DC6",
          NextOptions = {
            [1] = 6201624
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201624] = {
          Content = "不用谢。你们……接下来有什么打算？",
          DialogueId = 6201624,
          GUID = "0F866DF0",
          IsKeyOption = true,
          NextDialogue = 6201625,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201625] = {
          Content = "“既然得救了，当然是要继续前进啦。啊，不过，得先休整一下，给弗林处理伤口才行。”",
          DialogueId = 6201625,
          GUID = "0F866E1A",
          NextDialogue = 6201626,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201626] = {
          Content = "似是察觉到你的忧虑，女孩对你露出了一个灿烂的笑容。",
          DialogueId = 6201626,
          GUID = "0F866E44",
          NextDialogue = 6201627,
          RougeTalkActorType = 3
        },
        [6201627] = {
          Content = "“阁下，还记得上次见面时弗林问你的那个问题吗？现在，我终于想明白了。”她用从容而笃定的语气缓缓说道。“我想啊，真正能战胜深渊的，不会是某一次战斗，或是某一个人，而是我们所有人付出过的、所有的努力。只要一直积累下去，总有一天……总有一天，它一定能改变什么。所以，我们没有必要太在意自己的结局如何，只要继续前进，就算是为那个最后的胜利做出了一点贡献。”",
          DialogueId = 6201627,
          GUID = "0F866E6E",
          NextDialogue = 6201628,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201628] = {
          Content = "“呵……凯希，没想到……你还能说出这么有道理的话。对比之下，倒是显得我这个队长太软弱了。”\n青年终于恢复了意识，在友人的帮助下站起来，挺直了脊背。\n“深渊每分每秒都在扩张，如果放任不管，艾利西安全境都会被它吞噬。哪怕只是为了拖延时间，我们也必须战斗到最后一刻。况且，我们还没找到莉兹贝尔大人。”",
          DialogueId = 6201628,
          GUID = "0F866E98",
          NextDialogue = 6201629,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201629] = {
          Content = "“对呀，我们还要和她一起回去呢！所以，旅人阁下，您也只管沿着自己道路前进就好。不必顾虑我们，也不必代替我们背负什么，请仅仅带走我们的祝福吧。”\n女孩认真地注视着你，将手掌覆在心口位置。\n“<H>愿命运之神为您洒下千缕月光，使您的羽翼永远如满月一般洁白无瑕。</>”",
          DialogueId = 6201629,
          GUID = "0F866EC2",
          NextDialogue = 6201630,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201630] = {
          Content = "这是一句十分庄重的祝福语。在艾利西安，人们往往只会对一个很可能再也无法相见的人送上这句祝福。\n但，它绝不意味着消极的道别，它所代表的真意，是对命运的坦然——\n“我真诚地祝愿你前路顺遂，却也愿意接受或许要与你从此生死永别。”",
          DialogueId = 6201630,
          GUID = "0F866EEC",
          NextDialogue = 6201631,
          RougeTalkActorType = 3
        },
        [6201631] = {
          Content = "你向凯希点了点头，执起提灯，继续踏上了旅途。",
          DialogueId = 6201631,
          GUID = "0F866F16",
          RougeTalkActorType = 3
        },
        [6201701] = {
          Content = "数位年轻人的交谈声从不远处传来，你已经很久没在深渊中听到这样的声音了——热烈的、鲜活的、尚未被深渊的黑暗侵染的声音。\n你很确信这声音的来源并非亡灵，也不是幻影，而是活生生的人类。",
          DialogueId = 6201701,
          GUID = "0F867A92",
          NextDialogue = 6201702,
          RougeTalkActorType = 3
        },
        [6201702] = {
          Content = "你又一次和他们相遇了。",
          DialogueId = 6201702,
          GUID = "0F867ABC",
          NextDialogue = 6201703,
          RougeTalkActorType = 3
        },
        [6201703] = {
          Content = "和此前的每一次一样，四位年轻的骑士结伴从迷雾中出现。\n可他们染血的身影仍然历历在目。你一时分不清楚这样的重逢到底对谁而言更残酷一些——是不得不一次又一次在绝望中死去的他们，还是不得不一次又一次看着他们死去的你？",
          DialogueId = 6201703,
          GUID = "0F867AE6",
          NextDialogue = 6201704,
          RougeTalkActorType = 3
        },
        [6201704] = {
          Content = "“是这个方向没错吗，队长？”\n年轻的金发女骑士三步并作两步跨上古旧的台阶，又一口气跳了下来。\n“这看起来只是一座废墟而已。”",
          DialogueId = 6201704,
          GUID = "0F867B10",
          NextDialogue = 6201705,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201705] = {
          Content = "“至少我确定我们没来过这里。”\n被称作队长的青年骑士迈着沉稳的步伐从她身边走过。\n“在圣湖里很难辨别方向，现在也只能走一步算一步了。”",
          DialogueId = 6201705,
          GUID = "0F867B3A",
          NextOptions = {
            [1] = 6201706,
            [2] = 6201716
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201706] = {
          Content = "回头吧……趁还来得及。",
          DialogueId = 6201706,
          GUID = "0F867B64",
          IsKeyOption = true,
          NextDialogue = 6201707,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201707] = {
          Content = "“嗯？请问您是……？”",
          DialogueId = 6201707,
          GUID = "0F867B8E",
          NextDialogue = 6201708,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201708] = {
          Content = "“你们是莉兹贝尔的朋友，对吧？这是她让我转告你们的——深渊的危险程度远远超出我们的想象，绝非一个骑士团小队所能应对。回去吧，不要增加无谓的牺牲。”\n你已经顾不得其他。就算满口谎言也好，至少，<W>这一次</>，他们能活下去就好。",
          DialogueId = 6201708,
          GUID = "0F867BB8",
          NextDialogue = 6201709,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201709] = {
          Content = "“咦？！您知道莉兹贝尔大人的下落？她还好吗？她在哪里？”",
          DialogueId = 6201709,
          GUID = "0F867BE2",
          NextDialogue = 6201710,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201710] = {
          Content = "“等等，凯希。”\n司祭拦住激动的同伴，怀疑地看向你。\n“莉兹贝尔大人绝非懦弱之辈，请您不要借她之名行骗。再者，深渊讨伐行动乃是教皇陛下亲自下达的谕令，即便前方是地狱，我们也不会退缩。”",
          DialogueId = 6201710,
          GUID = "0F867C0C",
          NextDialogue = 6201711,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201711] = {
          Content = "你在心中发出一声叹息。\n有时，当人们念出“地狱”这个词语的时候，他们并不真的知晓它的意义。",
          DialogueId = 6201711,
          GUID = "0F867C36",
          NextDialogue = 6201712,
          RougeTalkActorType = 3
        },
        [6201712] = {
          Content = "“你说让我们回头……”\n身着斗篷的女术士用那幽邃的眼眸注视着你，声音一如既往地冰凉。\n“其实……就算我们回头，也毫无意义，不是吗？”",
          DialogueId = 6201712,
          GUID = "0F867C60",
          NextDialogue = 6201713,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201713] = {
          Content = "你无言以对。\n是啊，她说得没错。即使现在立刻回头，他们也无法找到来时的方向。在这深渊里，区分“前进”与“后退”的差异只是一种自我欺骗而已。\n要真正救下他们，只有一个办法。那就是，彻底结束这个绝望的轮回。",
          DialogueId = 6201713,
          GUID = "0F867C8A",
          NextDialogue = 6201714,
          RougeTalkActorType = 3
        },
        [6201714] = {
          Content = "“各位……”\n你注视着年轻的骑士们，郑重地将手掌覆在心口位置。\n“<H>愿命运之神为你们洒下千缕月光，使你们的羽翼永远如满月一般洁白无瑕。</>”",
          DialogueId = 6201714,
          GUID = "0F867CB4",
          NextDialogue = 6201715,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201715] = {
          Content = "听到你的祝福，卡莉斯塔的脸上浮现一抹哀伤的微笑。\n这时你忽然意识到，也许她其实是希望你能反驳她的，即便，是谎言也好。",
          DialogueId = 6201715,
          GUID = "0F867CDE",
          RougeTalkActorType = 3
        },
        [6201716] = {
          Content = "勇敢的骑士们，愿满月之神护佑你们的旅途。",
          DialogueId = 6201716,
          GUID = "0F867D08",
          IsKeyOption = true,
          NextDialogue = 6201717,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201717] = {
          Content = "“嗯？”\n面对你这句唐突的祝福，青年显得有些不知所措。\n“请问您是……？”",
          DialogueId = 6201717,
          GUID = "0F867D32",
          NextDialogue = 6201718,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201718] = {
          Content = "“你们是莉兹贝尔的朋友，对吧？这是她让我转告你们的——深渊的危险程度远远超出我们的想象，你们将会面临前所未有的困难与挑战，请做好觉悟。”",
          DialogueId = 6201718,
          GUID = "0F867D5C",
          NextDialogue = 6201719,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201719] = {
          Content = "“咦？！您知道莉兹贝尔大人的下落？她还好吗？她在哪里？”",
          DialogueId = 6201719,
          GUID = "0F867D86",
          NextDialogue = 6201720,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201720] = {
          Content = "“等等，凯希，不要轻易相信来路不明之人。”\n司祭拦住激动的同伴，怀疑地看向你。\n“莉兹贝尔大人的性格并不成熟，我很难想象她会说出如此严肃的话。再者，深渊讨伐行动乃是教皇陛下亲自下达的谕令，我们自会竭尽全力，不需要您特意提醒。”",
          DialogueId = 6201720,
          GUID = "0F867DB0",
          NextDialogue = 6201721,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201721] = {
          Content = "“我倒觉得这位旅人说的是真话。在这个地方待久了，就算发疯也不奇怪，区区性格变化又算什么呢……”\n女术士抬起头，用那幽邃的眼眸直直地盯着你，像是在尝试解开一道谜题。\n“阁下，您究竟是什么人？我总觉得……我曾见过您。”",
          DialogueId = 6201721,
          GUID = "0F867DDA",
          NextDialogue = 6201722,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201722] = {
          Content = "“……我是谁并不重要。”\n你注视着年轻的骑士们，露出坦然的微笑。\n“你们只需要知道，我的祝福是真心的。就算结局已经注定……希望你们仍然能找到旅途的意义。”",
          DialogueId = 6201722,
          GUID = "0F867E04",
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201801] = {
          Content = "你远远地看到，两个熟悉的年轻身影被层层叠叠的幽影围困在中间——是米尔顿和卡莉斯塔。\n尽管他们互相配合着击退了一波又一波的攻击，但幽影依旧源源不断地涌上前。\n于是你举起提灯，向他们走去。在琉璃的明亮光辉照耀下，那些幽影终于暂时退却。",
          DialogueId = 6201801,
          GUID = "0F868AFA",
          NextDialogue = 6201802,
          RougeTalkActorType = 3
        },
        [6201802] = {
          Content = "“您是之前的……”\n看到你出现，司祭先是很惊讶，随即露出些许愧色。\n“先前我对您多有猜忌，您却还愿意不计前嫌伸出援手……请接受我的歉意与感谢，神秘的旅人。”",
          DialogueId = 6201802,
          GUID = "0F868B24",
          NextDialogue = 6201803,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201803] = {
          Content = "“您果然不是一般人。多谢相助。”\n术士掀开了她的兜帽向你致意，只是兜帽下露出的发丝也还是相同的漆黑色。\n“您持有的那盏提灯……难道是某种神器吗？为何它能够驱散幽影？”",
          DialogueId = 6201803,
          GUID = "0F868B4E",
          NextOptions = {
            [1] = 6201804
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201804] = {
          Content = "这是别人托付给我的东西。",
          DialogueId = 6201804,
          GUID = "0F868B78",
          NextDialogue = 6201805,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201805] = {
          Content = "“既然是这样，我就不多问了。但，有这盏提灯，在深渊中的行动会方便许多。或许，您能允许我们与您同行吗？”",
          DialogueId = 6201805,
          GUID = "0F868BA2",
          NextDialogue = 6201806,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201806] = {
          Content = "“我不介意，只是，我的目标与你们并不相同。我只是为了修复这盏提灯，在收集琉璃碎片而已。”",
          DialogueId = 6201806,
          GUID = "0F868BCC",
          NextDialogue = 6201807,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201807] = {
          Content = "“事到如今，我们的目标已经不重要了……直觉告诉我，与您同行更有机会触及深渊的真相。”",
          DialogueId = 6201807,
          GUID = "0F868BF6",
          NextDialogue = 6201808,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201808] = {
          Content = "“你在说什么胡话，卡莉斯塔？”\n没等你做出回应，司祭便急切地开口斥责他的同伴。\n“虽说我们确实和小队的其他成员走散了……但我们仍然是艾利西安的骑士。即便只剩一人，也不能放弃使命！”",
          DialogueId = 6201808,
          GUID = "0F868C20",
          NextDialogue = 6201809,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201809] = {
          Content = "“呵……使命、使命，你的脑子里除了这些冠冕堂皇的东西就什么都不剩了吗？”\n术士也激动起来，箭囊里装着的数支细箭随着她的动作簌簌作响。\n“你想想我们在这里遇到的都是什么？秽兽、幻象、孤魂野鬼。如果真的像上面那些人说的那样，进入圣湖的人是蒙受选召升入了众天之天了，我们见到的这些幽影又是什么？你不觉得这个地方比起圣湖，更像暗月教派所说的魔王的巢穴——”",
          DialogueId = 6201809,
          GUID = "0F868C4A",
          NextDialogue = 6201810,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201810] = {
          Content = "“你——你疯了！你现在说话的口气就像个异端者！”\n他努力维持着体面，可你也能明显地听出来，他的声音中掺杂着一丝犹疑。\n“我们见到的那些幽影……他们可能是信仰不够坚定，没有通过最后试炼的人。把这些多余的阻碍清理干净，圣湖也许就会恢复正常。也许这是九神给予我们的考验，只要我们保持虔诚，九神自会庇护我们不受侵袭……”",
          DialogueId = 6201810,
          GUID = "0F868C74",
          NextDialogue = 6201811,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201811] = {
          Content = "“你嘴里的那些神明如果真的在乎我们，就应该亲自过来解决这个地狱。”\n她轻笑了一声，又长叹了一口气。\n“也许我们就是被派来送死的吧。讨伐什么的根本就不重要，重要的是把一批又一批的新鲜祭品送进来，填塞深渊的欲望。我们看到的那些幽影之中，有许多都是先前被派来讨伐深渊的骑士……”",
          DialogueId = 6201811,
          GUID = "0F868C9E",
          NextDialogue = 6201812,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201812] = {
          Content = "“他们比我们年长，也比我们经历过更多的战争，无论能力还是心智都比我们强上数百倍，最后却还是变成了那副阴魂不散的模样。我们根本不可能走出去，发疯或死亡就是我们的结局，或早或晚。”",
          DialogueId = 6201812,
          GUID = "0F868CC8",
          NextDialogue = 6201813,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201813] = {
          Content = "司祭抿着嘴唇，面色紧绷。他用力地握紧了手中的长杖，以掩盖自己身躯的颤抖。\n片刻之后，他重新以平静的语气开口。\n“……鉴于情况特殊，刚才你这些话，我就当做没有听过。眼下弗林不在，按照等阶顺序，你应该听从我的决断。我要求你立刻停止对教义和圣者的污蔑，继续履行骑士的职责。”",
          DialogueId = 6201813,
          GUID = "0F868CF2",
          NextDialogue = 6201814,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201814] = {
          Content = "“……好吧。早些解脱也不是坏事。”\n她认命似的低下头，又将兜帽拉过头顶。\n“但作为朋友，我还是想说……如果你所信仰的一切本身就是谎言，还要为它送死，实在太可惜了，不是吗？”",
          DialogueId = 6201814,
          GUID = "0F868D1C",
          NextDialogue = 6201815,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201815] = {
          Content = "“……”\n司祭微微摇了摇头，然后向前一步，对你行礼。\n“抱歉，让您见笑了。我们已经没事了，稍作休整便会继续前进。就此别过吧，善良的旅人，愿满月之神护佑您的旅途。”",
          DialogueId = 6201815,
          GUID = "0F868D46",
          NextOptions = {
            [1] = 6201816,
            [2] = 6201818,
            [3] = 6201820
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201816] = {
          Content = "也愿满月之神护佑你们的旅途。",
          DialogueId = 6201816,
          GUID = "0F868D70",
          IsKeyOption = true,
          NextDialogue = 6201817,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201817] = {
          Content = "听到你的回应，米尔顿露出了满足的微笑。卡莉斯塔也并未再作反驳，只是沉默地别过头去，你看不清她的表情。\n你向他们点头致意，然后便转身离开了。",
          DialogueId = 6201817,
          GUID = "0F868D9A",
          RougeTalkActorType = 3
        },
        [6201818] = {
          Content = "我想满月之神可能帮不了我。",
          DialogueId = 6201818,
          GUID = "0F868DC4",
          IsKeyOption = true,
          NextDialogue = 6201819,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201819] = {
          Content = "听到你的回应，米尔顿有些局促地移开了目光，但没有多说什么。卡莉斯塔向你露出一个哀伤的微笑，随后又疲惫地低下了头。\n你向他们点头致意，然后便转身离开了。",
          DialogueId = 6201819,
          GUID = "0F868DEE",
          RougeTalkActorType = 3
        },
        [6201820] = {
          Content = "我想……也许真正重要的不是信仰，而是我们自身的勇气。",
          DialogueId = 6201820,
          GUID = "0F868E18",
          IsKeyOption = true,
          NextDialogue = 6201821,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201821] = {
          Content = "听到你的回应，米尔顿和卡莉斯塔先是有些惊讶，随后又一同陷入了沉思。\n你没有再多说什么，毕竟，这句话其实是别人告诉你的，就连你自己也仍在摸索它真正的含义。\n你向二人点头致意，然后便转身离开了。",
          DialogueId = 6201821,
          GUID = "0F868E42",
          RougeTalkActorType = 3
        },
        [6201901] = {
          Content = "前方传来不祥的、浓烈的血腥味。\n那深邃的黑暗和沉重的寂静让你确信前方并没有你所求之物，可是你又感到一种奇妙的预兆，似乎有谁正希冀你踏入那片黑暗。于是你试探着迈出了脚步——",
          DialogueId = 6201901,
          GUID = "0F869B62",
          NextDialogue = 6201902,
          RougeTalkActorType = 3
        },
        [6201902] = {
          Content = "忽然间，四周出现了白色的亮光——不，不是亮光。你定睛细看，才发觉那只是秽兽煞白的外壳，一块连着一块，堆叠在一起像是某位异端艺术家醉后泼洒出的作品。\n你本能地后退一步，两个熟悉的身影出现在你身边。",
          DialogueId = 6201902,
          GUID = "0F869B8C",
          NextDialogue = 6201903,
          RougeTalkActorType = 3
        },
        [6201903] = {
          Content = "“咳、咳……没完没了……”\n术士抹去嘴角的血迹，将手中的长弓丢弃在地。\n“我的箭都用完了……接下来就只能靠魔法了。呵，我这也算是为你们的神明大人鞠躬尽瘁了吧？拜托死后别把我丢在乱葬岗，好歹留个全尸吧。”",
          DialogueId = 6201903,
          GUID = "0F869BB6",
          NextDialogue = 6201904,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201904] = {
          Content = "“别再胡说——小心身后！”\n司祭猛然挥动长杖，魔法的光芒亮起。\n“啧……又有幽影出现了。”",
          DialogueId = 6201904,
          GUID = "0F869BE0",
          NextDialogue = 6201905,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201905] = {
          Content = "你随卡莉斯塔一同转过身，发现大片的幽影朝你们涌了过来，越过地上的秽兽尸体，像是那位艺术家又在画作上打翻了一桶黑色的颜料。\n你连忙举起提灯，可幽影的动作却没有收敛分毫。你忽然注意到，你的提灯穿过了米尔顿的长杖。",
          DialogueId = 6201905,
          GUID = "0F869C0A",
          NextDialogue = 6201906,
          RougeTalkActorType = 3
        },
        [6201906] = {
          Content = "这时你明白了——眼前的一切只是一段记忆的残像。你明明就站在他们身边，可你什么也做不了，除了眼睁睁地看着他们在战斗中不断消耗、负伤累累、力竭倒地。",
          DialogueId = 6201906,
          GUID = "0F869C34",
          NextDialogue = 6201907,
          RougeTalkActorType = 3
        },
        [6201907] = {
          Content = "幽影已经逐渐散去，只剩下最后的四个……三个……两个……一个。但凡两位年轻的骑士中还有一个人留有反击的力气，但凡他们的队友能及时出现支援，但凡这里掉落了一小块琉璃碎片，他们就能赢得这场战斗，活下去。\n可是……没有。除了你这个迟来的旁观者，什么都没有。",
          DialogueId = 6201907,
          GUID = "0F869C5E",
          NextDialogue = 6201908,
          RougeTalkActorType = 3
        },
        [6201908] = {
          Content = "那个人形的幽影逼近了，那个或许曾是他们的前辈、同伴或是朋友的人，将一柄漆黑的长枪刺向卡莉斯塔的心脏。\n你闭上了眼睛，不愿目睹这残忍的一幕。",
          DialogueId = 6201908,
          GUID = "0F869C88",
          NextDialogue = 6201909,
          RougeTalkActorType = 3
        },
        [6201909] = {
          Content = "“米尔顿……？！你……为什么……？”",
          DialogueId = 6201909,
          GUID = "0F869CB2",
          NextDialogue = 6201910,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201910] = {
          Content = "你惊讶地睁开眼，发现那长枪最终刺穿的是米尔顿的胸膛。幽影散去，他无力地坠向地面，溅起的鲜血染红了他那永远整理得一丝不苟的衣襟。",
          DialogueId = 6201910,
          GUID = "0F869CDC",
          NextDialogue = 6201911,
          RougeTalkActorType = 3
        },
        [6201911] = {
          Content = "“你做了什么……？你……”\n术士错愕地跪在队友身边，无措地伸手试图使用治愈魔法，却只是徒劳。\n“你不是说……你不是说我是异端者吗？你为什么要为了救一个异端者搭上自己的性命啊？！你不是还要证明你的信仰吗……”",
          DialogueId = 6201911,
          GUID = "0F869D06",
          NextDialogue = 6201912,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201912] = {
          Content = "“因为我的信仰告诉我……要保护同伴……无论你再怎么质疑它……至少这一点，我笃定它是对的。”\n在这个即将迎来死亡的时刻，司祭那永远正颜厉色的脸上终于露出了一丝活着的人才会拥有的、生动的笑容。\n“我想，我已经为神奉献了足够多……那么，最后，就让我说一句自己的心里话吧。卡莉斯塔……忘了那些使命和职责吧。离开这里，活下去。”",
          DialogueId = 6201912,
          GUID = "0F869D30",
          NextDialogue = 6201913,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201913] = {
          Content = "“哎……？”",
          DialogueId = 6201913,
          GUID = "0F869D5A",
          NextDialogue = 6201914,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201914] = {
          Content = "“我不在之后，你就是自己的指挥官，可以凭自己的意愿行动了。就像你一直说的那样，逃走吧……离开这片深渊，或者，去找那位旅人……只要能活下去，怎样都好。”",
          DialogueId = 6201914,
          GUID = "0F869D84",
          NextDialogue = 6201915,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201915] = {
          Content = "一滴又一滴的眼泪顺着她白皙的脸颊滑落，落在在米尔顿的衣襟，让那已经开始凝固的血块再度融化。\n“可我一个人……又能走到哪里去呢……”",
          DialogueId = 6201915,
          GUID = "0F869DAE",
          NextDialogue = 6201916,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201916] = {
          Content = "“又在……说胡话了。”\n司祭用他那曾经紧握着长杖的手，吃力地将胸前的徽章摘下，放到卡莉斯塔的手中。\n“你的考核成绩一直都是我们之中最优秀的。你也是来到这里之后，第一个看清事实、有勇气质疑现状的……你……一定可以……活下去……”",
          DialogueId = 6201916,
          GUID = "0F869DD8",
          NextDialogue = 6201917,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201917] = {
          Content = "幻象散去了，你没有听到卡莉斯塔的回答。\n在寂静的黑暗中，你发现了司祭冰冷的身体。黑色的阴影从他的伤口中涌出，很快，他将会和你看到的许多人一样，化作无法安息的幽影。",
          DialogueId = 6201917,
          GUID = "0F869E02",
          NextOptions = {
            [1] = 6201918,
            [2] = 6201920
          },
          RougeTalkActorType = 3
        },
        [6201918] = {
          Content = "（替他结束痛苦。）",
          DialogueId = 6201918,
          GUID = "0F869E2C",
          IsKeyOption = true,
          NextDialogue = 6201919,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201919] = {
          Content = "在他彻底异化为幽影之前，你发动提灯的力量，结束了他的生命。\n“谢谢……”\n你似乎听到了这样的声音，又或者，那只是你用来安慰自己的幻觉。",
          DialogueId = 6201919,
          GUID = "0F869E56",
          RougeTalkActorType = 3
        },
        [6201920] = {
          Content = "（你不忍心动手。）",
          DialogueId = 6201920,
          GUID = "0F869E80",
          IsKeyOption = true,
          NextDialogue = 6201921,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201921] = {
          Content = "你退后一步，打算就此离开。\n可幽影站了起来。他那曾从友人手中无力滑落的苍白的手又一次握紧了长杖，向你发起攻击。\n你叹息一声，举起武器，将那幽影打倒了，一如既往。",
          DialogueId = 6201921,
          GUID = "0F869EAA",
          RougeTalkActorType = 3
        },
        [6202001] = {
          Content = "又一次，你走到了轮回的尽头。\n你收集的琉璃仍不足以与深渊的核心对抗，你必须再一次倒转时间。",
          DialogueId = 6202001,
          GUID = "0F86ABCA",
          NextDialogue = 6202002,
          RougeTalkActorType = 3
        },
        [6202002] = {
          Content = "你在混沌的洪流中漫无目的地踱着步子——你已经无数次直面过祂的注视，不再心生恐惧，只是平静地感受这一轮回最后的几分钟。\n忽然，你见到了一个熟悉的身影。",
          DialogueId = 6202002,
          GUID = "0F86ABF4",
          NextDialogue = 6202003,
          RougeTalkActorType = 3
        },
        [6202003] = {
          Content = "“哈……是您……您果然还活着。”\n她斜倚着一面断墙，残破的斗篷遮盖不住那遍体鳞伤的身躯。\n“您到底是什么人……？为什么，看到了那样的东西，您的眼中却毫无惧色？”",
          DialogueId = 6202003,
          GUID = "0F86AC1E",
          NextOptions = {
            [1] = 6202004,
            [2] = 6202006
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6202004] = {
          Content = "我已经见过祂很多次，在轮回的时间里。",
          DialogueId = 6202004,
          GUID = "0F86AC48",
          IsKeyOption = true,
          NextDialogue = 6202005,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6202005] = {
          Content = "“轮回？”\n她的眼中闪过一瞬的光亮，如同解开了难题的学者。\n“啊……原来如此。我终于明白了。怪不得您看向我们的眼神是那样的……慈悲……您早就已经无数次见证过我们的结局了，对吗？轮回……呵呵……也就是说，很快，我和他们就能重新团聚了……？这么一想，死亡似乎也不那么可怕了。”",
          DialogueId = 6202005,
          GUID = "0F86AC72",
          NextDialogue = 6202008,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6202006] = {
          Content = "有些真相也许不知道更好。",
          DialogueId = 6202006,
          GUID = "0F86AC9C",
          IsKeyOption = true,
          NextDialogue = 6202007,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6202007] = {
          Content = "“呵呵……您说得对。我无法想象您究竟是经历了什么，才能拥有这般强大而可怖的……平静。”\n她那黑色的眼眸此刻温和地注视着你，如同一位亲切的友人。\n“我总觉得，您还有很多话没有告诉我们。但我想，您一定有自己的理由，就像他们所坚持的信仰一样。”",
          DialogueId = 6202007,
          GUID = "0F86ACC6",
          NextDialogue = 6202008,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6202008] = {
          Content = "“请收下这个……如果可以，希望您能将它带在身边。就当是，我最后的请求吧……”\n她费力地伸出手，将一本笔记递给你。\n“米尔顿让我逃走，可我知道，我已经回不去了。那么至少……让我最后的生命发挥一些价值吧。”",
          DialogueId = 6202008,
          GUID = "0F86ACF0",
          NextDialogue = 6202009,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6202009] = {
          Content = "“在这深渊里……我花了很多时间去想，到底哪一种信仰才是对的？满月之神和暗月之神，哪一位才是真的？我一直找不到答案，还为此屡屡和同伴们争吵。”\n她感慨地叹了一口气，似是自嘲。\n“到现在我才终于明白…其实信仰本身的真伪根本不重要。真正重要的是，信仰它的人做了什么。我的同伴们用实际行动贯彻和证明了自己的信仰。我认为他们的所作所为是正确的，所以，在最后，我也愿意用他们的信仰——无论它本身到底真实与否——为您送上我的祝福。”",
          DialogueId = 6202009,
          GUID = "0F86AD1A",
          NextDialogue = 6202010,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6202010] = {
          Content = "“那么……旅人啊……”\n她颤抖着将苍白的右手放在心口，用那已然开始涣散的双眸努力捕捉你所在的方向。\n“<H>愿命运之神为您洒下千缕月光，使您的羽翼永远如满月一般洁白无瑕。</>”",
          DialogueId = 6202010,
          GUID = "0F86AD44",
          NextDialogue = 6202011,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6202011] = {
          Content = "她停止了呼吸。\n你替她合上了双眼。她的脸上仍然带着平和的笑容，仿佛只是睡着了一般。",
          DialogueId = 6202011,
          GUID = "0F86AD6E",
          NextDialogue = 6202012,
          RougeTalkActorType = 3
        },
        [6202012] = {
          Content = "你翻开了她托付给你的那本笔记。笔记的纸张虽然沾上了不少灰尘和血污，但字迹还算清晰。\n“我，艾利西安传颂会下属飞羽骑士团‘静默黄昏’小队成员卡莉斯塔，于此处记录下我所观测到的、关于圣湖的一切。若有人寻得这本笔记，希望这些记录能为你走出这里提供微薄助力。”",
          DialogueId = 6202012,
          GUID = "0F86AD98",
          NextDialogue = 6202013,
          RougeTalkActorType = 3
        },
        [6202013] = {
          Content = "借着着提灯的光辉，你翻阅着她的笔记。凌乱的文字似是在昏暗中匆忙写就，记录着大量幽影和幻象，从每种幽影的弱点到每个幻象的驱散方式不一而足。\n你翻阅到笔记的其中一页。\n“可以确定，<H>暗月教派</>的典籍所言之物并非完全虚假……至少，圣湖与神话中的众天之天毫无关联，所谓的选召更像是一种献祭。这是一个满盈着死者留下的恶意与邪念的场所。”\n“我的家族是暗月教派的信奉者。他们以深渊和暗月女神为信仰，并坚信初代七美德之一的<H>沙利叶</>在两千年前并未前往众天之天，而是在这圣湖底成为<H>魔王</>，也就是深渊的核心。他不断吞噬着灵魂，作为献给涅法的祭品。”",
          DialogueId = 6202013,
          GUID = "0F86ADC2",
          NextDialogue = 6202014,
          RougeTalkActorType = 3
        },
        [6202014] = {
          Content = "“在过去的生命里，我不断以正教的训导自醒——我不愿相信那些可怖的传说。但是这片深渊的一切无时无刻不在诘问我：如果暗月派的教义才是真相……如果我们世界的尽头真的是黑暗与虚无——”\n“那么，深渊是否是不可战胜的？”\n“只可惜，我残存的身体已经不可能支撑自己找到答案。”",
          DialogueId = 6202014,
          GUID = "0F86ADEC",
          NextDialogue = 6202015,
          RougeTalkActorType = 3
        },
        [6202015] = {
          Content = "“米尔顿告诉过我，昔日有一柄叫做<H>柯罗涅</>的<H>圣剑</>于圣湖意外损毁。那是传颂会的圣物，拥有非同寻常的力量……另外，我曾在这片深渊中见过一位旅人，那位旅人持有的提灯似乎也拥有驱散幽影的特殊力量。”\n“如果真的有什么能战胜深渊，我想，这二者或许会成为关键。”",
          DialogueId = 6202015,
          GUID = "0F86AE16",
          NextDialogue = 6202016,
          RougeTalkActorType = 3
        },
        [6202016] = {
          Content = "你注意到笔记还有很多页。你迫不及待地往下翻——她到底还知道多少真相？\n但很快你便发现，笔记后面记录的内容，与深渊无关。",
          DialogueId = 6202016,
          GUID = "0F86AE40",
          NextDialogue = 6202017,
          RougeTalkActorType = 3
        },
        [6202017] = {
          Content = "“正在翻阅这本笔记的人啊，谢谢你看到这里。希望你能替我记住他们。”",
          DialogueId = 6202017,
          GUID = "0F86AE6A",
          NextDialogue = 6202018,
          RougeTalkActorType = 3
        },
        [6202018] = {
          Content = "在这个短暂的瞬间，你的思绪离开了深渊，被这些文字带去了另一个世界。\n艾利西安骑士团的营地，一间小小的宿舍，温暖的黄色灯光下，你翻开一个年轻骑士的日记本，看到她和她的三位朋友的故事。",
          DialogueId = 6202018,
          GUID = "0F86AE94",
          NextDialogue = 6202019,
          RougeTalkActorType = 3
        },
        [6202019] = {
          Content = "他们一同参与训练——\n“‘你们简直像一个小队啊’——被教官这么说了几次之后，弗林还真的起劲了，说要给我们这个四人小队起个名字，凯希也跟着附和——这倒是没什么，他们俩本来就总在一块闹腾。但我没想到米尔顿也会赞成，难不成这家伙心里也有什么英雄梦吗？”\n“‘静默黄昏’和‘英勇土豆’，是弗林和凯希分别给出的候选队名。我和米尔顿都毫不犹豫地投票给了第一个。考虑到那天的午饭是土豆炖肉，我充分怀疑凯希是在吃午饭时随口胡诌了一个名字拿来凑数。”\n“至于弗林起的这个名字，‘黄昏’……呵呵，别人也许发觉不了，但我们几个一眼就能看出来，这是在偷偷致敬他最喜欢的那位‘月升时’的骑士呢。”",
          DialogueId = 6202019,
          GUID = "0F86AEBE",
          NextDialogue = 6202020,
          RougeTalkActorType = 3
        },
        [6202020] = {
          Content = "他们一同踏上战场——\n“行军的时候，凯希总是在不知不觉间就跑得没影了。刚开始我们还很担心，但每一次她都会在意想不到的时候忽然出现吓我们一跳，再后来我们就见怪不怪了。不过，她到底是怎么做到的呢？她那个脑子，也不可能学得会瞬移之类的高难度魔法啊……”\n“米尔顿那个书呆子，居然把书带上战场，说空闲时可以看？！简直不知道说他什么好……”\n“后来，米尔顿的书被帝国一支火箭给烧了个精光。他一整天都耷拉着脸……我看他应该感谢那个帝国兵才对，他行囊的重量至少因此减轻了三分之二。”",
          DialogueId = 6202020,
          GUID = "0F86AEE8",
          NextDialogue = 6202021,
          RougeTalkActorType = 3
        },
        [6202021] = {
          Content = "他们一同接受使命——\n“为了避免麻烦，我没把报名参与深渊讨伐的事告诉父母，只告诉了哥哥……没想到他也和他们一样，对着我唠叨个不停，说什么深渊是传颂会的阴谋，魔王会把大家都变成祭品……真是烦死了。”\n“其实我对讨伐深渊什么的并没有兴趣，但弗林对此特别积极，我也不好意思反对。在之前参与的那些战役里，我们从没当过主力，总是输多赢少，他一定很想要一个证明自己的机会……所以，就当是帮他圆这个骑士梦吧。反正，只要大家在一起，去哪里都差不多。”",
          DialogueId = 6202021,
          GUID = "0F86AF12",
          NextDialogue = 6202022,
          RougeTalkActorType = 3
        },
        [6202022] = {
          Content = "……",
          DialogueId = 6202022,
          GUID = "0F86AF3C",
          NextDialogue = 6202023,
          RougeTalkActorType = 3
        },
        [6202023] = {
          Content = "你翻到了笔记的最后一页。",
          DialogueId = 6202023,
          GUID = "0F86AF66",
          NextDialogue = 6202024,
          RougeTalkActorType = 3
        },
        [6202024] = {
          Content = "“沉默的神明啊，若你真如米尔顿所说，在时刻注视着我们……我请求你，为我实现最后的愿望。”\n“请让我的灵魂与他们团聚吧。”\n“那样，我便原谅你的冷漠，原谅你的残忍；原谅你施加的诸多苦难，原谅你编织的一切谎言。”",
          DialogueId = 6202024,
          GUID = "0F86AF90",
          NextDialogue = 6202025,
          RougeTalkActorType = 3
        },
        [6202025] = {
          Content = "<H>“我的羽翼已不再需要满月的照耀，只希望有一道清风，带我飞往同伴们所在的方向。”</>",
          DialogueId = 6202025,
          GUID = "0F86AFBA",
          NextDialogue = 6202026,
          RougeDialogueMainIcon = "Texture2D'/Game/UI/Texture/Dynamic/Image/RougeLike/T_Rouge_Story13.T_Rouge_Story13'",
          RougeTalkActorType = 3
        },
        [6202026] = {
          Content = "合上笔记，你的指尖依然能感受到纸页上的余温。",
          DialogueId = 6202026,
          GUID = "0F86AFE4",
          NextDialogue = 6202027,
          RougeTalkActorType = 3
        },
        [6202027] = {
          Content = "“我……一定会终结轮回，让你们在明亮的满月下重逢。”",
          DialogueId = 6202027,
          GUID = "0F86B00E",
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [7002001] = {
          Content = "慰问品七七八八地堆放着，似乎是这几天很多人陆续送来的。\n仔细一看，里面有不知名的野花，虽然冷掉但依旧闻起来美味的肉汤，带划痕但精美的八音盒，画着小鸟的一罐棉花糖……\n除了这些以外，还有一份没有署名，系着歪扭蝴蝶结的朴素礼盒，打开以后发现里面是一瓶帝国最顶尖的止痛剂。这份关怀的心虽是好的，但送给一名昏迷人士止痛剂，实在是没什么意义了。",
          DialogueId = 7002001,
          GUID = "11875DCA"
        },
        [7003001] = {
          Content = "冰湖城外城近日发生多起恶性伤人事件，手段极其残忍，现场极为混乱，请广大市民减少深夜外出，锁好门窗。\n持有武器许可证的市民如果遭遇行凶者，不要试图反击（这很危险！！！），优先保全自身性命。\n如有凶手线索，请立即联系卫戍部队，黎瑟·费西尔。\n皇帝会庇护他忠诚的子民度过难关，荣耀尽归吾皇。",
          DialogueId = 7003001,
          GUID = "118801DA"
        },
        [10010101] = {
          Camera = "67.539062,-1123.730225,550.733276,0.000081,-22.799314,91.999741,35.0,1000.0,false,Manual,2.8",
          Content = "贝蕾，我……",
          DefaultLookAt = "KeepState",
          DialogueId = 10010101,
          DisableMouth = 1,
          Duration = 1.5,
          ExStoryInfo = "Player",
          GUID = "190F2A32",
          RelatedWikiId = {
            [1] = 304001,
            [2] = 204001,
            [3] = 408001,
            [4] = 201001
          },
          SpeakNpcId = 100001,
          Subtitle = "Berry, I...",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2A32"
        },
        [10010102] = {
          Content = "嘘。",
          DialogueId = 10010102,
          DisableMouth = 1,
          Duration = 3,
          GUID = "190F2A5C",
          SpeakNpcId = 100003,
          Subtitle = "Ssh...",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2A5C"
        },
        [10010103] = {
          Content = "还好吗？",
          DialogueId = 10010103,
          DisableMouth = 1,
          Duration = 2,
          GUID = "190F2A86",
          SpeakNpcId = 100003,
          Subtitle = "Are you all right?",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2A86"
        },
        [10010104] = {
          Content = "嗯。",
          DialogueId = 10010104,
          DisableMouth = 1,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "190F2AB0",
          SpeakNpcId = 100001,
          Subtitle = "Yeah.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2AB0"
        },
        [10010105] = {
          Content = "再歇息一会儿吧。我就在这里，哪儿都不去。",
          DialogueId = 10010105,
          DisableMouth = 1,
          Duration = 5,
          GUID = "190F2ADA",
          SpeakNpcId = 100003,
          Subtitle = "Get some more sleep. I won't leave — I'll be right here when you wake up.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2ADA"
        },
        [10010106] = {
          Content = "不用了。我们回去吧，下山。",
          DialogueId = 10010106,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "190F2B04",
          SpeakNpcId = 100001,
          Subtitle = "It's okay. We should get down the mountain and head to the village.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2B04"
        },
        [10010107] = {
          Content = "现在就回村子吗？可这两天那边一直传来吼声……",
          DialogueId = 10010107,
          DisableMouth = 1,
          Duration = 4,
          GUID = "190F2B2E",
          SpeakNpcId = 100003,
          Subtitle = "You wanna go back? There've been roars coming from there for days...",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2B2E"
        },
        [10010108] = {
          Content = "我是想，如果能回家拿到武器——",
          DialogueId = 10010108,
          DisableMouth = 1,
          Duration = 4.5,
          ExStoryInfo = "Player",
          GUID = "190F2B58",
          SpeakNpcId = 100001,
          Subtitle = "I was thinking, if we could make it home and grab our weapons—",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2B58"
        },
        [10010109] = {
          Content = "凭你的力量，一定能找到生路。",
          DialogueId = 10010109,
          DisableMouth = 1,
          Duration = 2.5,
          ExStoryInfo = "Player",
          GUID = "190F2B82",
          SpeakNpcId = 100001,
          Subtitle = "And with your strength, you'll find a way out. ",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2B82"
        },
        [10010110] = {
          Content = "留在这里……也不会有人来救我们的，不是么？",
          DialogueId = 10010110,
          DisableMouth = 1,
          Duration = 5,
          ExStoryInfo = "Player",
          GUID = "190F2B83",
          SpeakNpcId = 100001,
          Subtitle = "No one's gonna save us no matter how long we stay here anyway.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2B83"
        },
        [10010111] = {
          Content = "……走吧。",
          DialogueId = 10010111,
          DisableMouth = 1,
          Duration = 3,
          GUID = "190F2BAC",
          SpeakNpcId = 100003,
          Subtitle = "...Let's go then.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BAC"
        },
        [10010112] = {
          Content = "慢慢来。",
          DialogueId = 10010112,
          GUID = "190F2BAD",
          SpeakNpcId = 100003,
          Subtitle = "Take it easy.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BAD"
        },
        [10010113] = {
          Content = "当心脚下，不要踩空。",
          DialogueId = 10010113,
          GUID = "190F2BAE",
          SpeakNpcId = 100003,
          Subtitle = "Watch your step.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BAE"
        },
        [10010114] = {
          Content = "你的伤还没好吧，要不要紧？",
          DialogueId = 10010114,
          GUID = "190F2BAF",
          NextDialogue = 10010115,
          SpeakNpcId = 100003,
          Subtitle = "You're not fully recovered. Are you sure you can do this?",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BAF"
        },
        [10010115] = {
          Content = "早就没事了，区区几道沟而已。",
          DialogueId = 10010115,
          ExStoryInfo = "Player",
          GUID = "190F2BB1",
          NextDialogue = 10010116,
          SpeakNpcId = 100001,
          Subtitle = "I'm okay. It's just a few scratches.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BB1"
        },
        [10010116] = {
          Content = "别逞强。不要还没遇到秽兽，先用光了力气。",
          DialogueId = 10010116,
          GUID = "190F2BB2",
          SpeakNpcId = 100003,
          Subtitle = "Don't push yourself too hard. We still have to save some strength for those Filthoids.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BB2"
        },
        [10010201] = {
          Content = "想活命，就如实交代清楚。",
          DialogueId = 10010201,
          Duration = 4,
          GUID = "190F3A9A",
          SpeakNpcId = 100005,
          Subtitle = "Tell me the truth if you want to live.",
          VoiceName = "voice/$Locale$/story/1001/100102/190F3A9A"
        },
        [10010202] = {
          Content = "为什么在这里，你的同伴是什么人。",
          DialogueId = 10010202,
          Duration = 5,
          GUID = "190F3AC4",
          SpeakNpcId = 100005,
          Subtitle = "Why are you here, who's with you,",
          VoiceName = "voice/$Locale$/story/1001/100102/190F3AC4"
        },
        [10010203] = {
          Content = "——以及，你又是谁。",
          DialogueId = 10010203,
          Duration = 3.5,
          GUID = "190F3AEE",
          SpeakNpcId = 100005,
          Subtitle = "and who on earth are you?",
          VoiceName = "voice/$Locale$/story/1001/100102/190F3AEE"
        },
        [10010204] = {
          Camera = "10000,11000,2000,0.000046,-4.799929,73.987312,35.0,150.0,false,Manual,2.8",
          Content = "……",
          DialogueId = 10010204,
          Duration = 2,
          GUID = "190F3AEF",
          NextDialogue = 10010205
        },
        [10010205] = {
          Camera = "10000,11000,2000,0.000046,-4.799929,73.987312,35.0,150.0,false,Manual,2.8",
          Content = "……",
          DialogueId = 10010205,
          Duration = 2,
          GUID = "190F3AF0",
          NextDialogue = 10010206
        },
        [10010206] = {
          Camera = "10000,11000,2000,0.000046,-4.799929,73.987312,35.0,150.0,false,Manual,2.8",
          Content = "……",
          DialogueId = 10010206,
          Duration = 2,
          GUID = "190F3AF1"
        },
        [10010301] = {
          Content = "我们现在赤手空拳，尽可能避开它们吧。",
          DialogueId = 10010301,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "190F4B02",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100103/190F4B02"
        },
        [10010401] = {
          Content = "拿好你手里那把剑，兴许会派上用场。",
          DialogueId = 10010401,
          DisableMouth = 1,
          Duration = 3,
          GUID = "190F5B6A",
          RelatedWikiId = {
            [1] = 408001,
            [2] = 201001
          },
          SpeakNpcId = 100003,
          Subtitle = "Take that sword with you. It might be helpful one day.",
          TalkActionId = {
            [1] = "100001:FuXiong_Start"
          },
          VoiceName = "voice/$Locale$/story/1001/100104/190F5B6A"
        },
        [10010402] = {
