          GUID = "190FBE07",
          NextDialogue = 10011006,
          SpeakNpcId = 100003,
          Subtitle = "Alright, a quick check — Two pats on the right shoulder means...?",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE07"
        },
        [10011006] = {
          Content = "“留意身后。”",
          DialogueId = 10011006,
          ExStoryInfo = "Player",
          GUID = "190FBE08",
          NextDialogue = 10011007,
          SpeakNpcId = 100001,
          Subtitle = "\"Watch your back.\"",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE08"
        },
        [10011007] = {
          Content = "轻敲心口两次的意思是？",
          DialogueId = 10011007,
          GUID = "190FBE09",
          NextDialogue = 10011008,
          SpeakNpcId = 100003,
          Subtitle = "And two taps on the chest?",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE09"
        },
        [10011008] = {
