          GUID = "190FEF12",
          NextDialogue = 10011302,
          SpeakNpcId = 100001,
          Subtitle = "So the key is... this sword?",
          VoiceName = "voice/$Locale$/story/1001/100113/190FEF12"
        },
        [10011302] = {
          Content = "嗯，你的剑从来不是伤人用的。",
          DialogueId = 10011302,
          GUID = "190FEF13",
          SpeakNpcId = 100003,
          Subtitle = "Yes. Your sword was not made for slashing.",
          VoiceName = "voice/$Locale$/story/1001/100113/190FEF13"
        },
        [10011401] = {
          Content = "一路向上走到山顶，那里以前有一架飞艇。如果它还在，我们就有机会离开这里。",
          DialogueId = 10011401,
          Duration = 4.5,
          GUID = "190FFFA4",
          SpeakNpcId = 100003,
          Subtitle = "Let's head towards the top of the mountain. There used to be an airship there. If it's still around, we might be able to make it out.",
          VoiceName = "voice/$Locale$/story/1001/100114/190FFFA4"
        },
        [10011501] = {
          Content = "那就是……你说的飞艇？",
          DialogueId = 10011501,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "19100FE2",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100115/19100FE2"
        },
        [10011502] = {
          Content = "还有人在那里……我们得救了吗？",
