          ExStoryInfo = "Player",
          GUID = "1910100C",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100115/1910100C"
        },
        [10011601] = {
          Content = "找了这么多年，军团长该死心了吧。",
          DialogueId = 10011601,
          Duration = 3.5,
          GUID = "1910204A",
          RelatedWikiId = {
            [1] = 408001,
            [2] = 201001
          },
          SpeakNpcName = "UI_Npc_Name_Man_3",
          Subtitle = "We've been searching for years. When will our chief give up this pointless hunt?",
          VoiceName = "voice/$Locale$/story/1001/100116/1910204A"
        },
        [10011602] = {
          Content = "谁？！",
          DialogueId = 10011602,
          Duration = 1.5,
          GUID = "19102074",
          SpeakNpcName = "UI_Npc_Name_Man_3",
          Subtitle = "Who's there?!",
          VoiceName = "voice/$Locale$/story/1001/100116/19102074"
        },
        [10011603] = {
          Content = "放下武器——",
          DialogueId = 10011603,
          Duration = 0.9,
          GUID = "19102075",
          SpeakNpcName = "UI_Npc_Name_Man_3",
          Subtitle = "Lay down your arms—",
