            [2] = 201001,
            [3] = 201003
          },
          SpeakNpcId = 100005,
          Subtitle = "Is this your idea of \"accurate intel\", Randy? You gave me your word.",
          VoiceName = "voice/$Locale$/story/1001/100117/191030B2"
        },
