        },
        [10011902] = {
          Camera = "-14.427734,54.794922,163.906128,0.000261,-4.995177,46.37698,35.0,150.0,false,Manual,2.8",
          Content = "你们只是“无端”遭遇秽兽袭击，“一无所知”地来到这座遗迹，又“凑巧”打开遗迹通道的“普通”村民——对吗？",
          DefaultLookAt = "KeepState",
          DialogueId = 10011902,
          DisableMouth = 1,
          Duration = 13.4,
          GUID = "191051AC",
          SpeakNpcId = 100005,
          Subtitle = "The Filthoids attacked you \"for no reason\" after you came here, and you managed to open the hidden path \"by chance\"... Is that really your story?",
          VoiceName = "voice/$Locale$/story/1001/100119/191051AC"
        },
        [10011903] = {
