          GUID = "191052D2",
          LookAt = {
            [1] = "100005:n(100001)"
          },
          SpeakNpcId = 100005,
          Subtitle = "As for Phoxhunter...",
          VoiceName = "voice/$Locale$/story/1001/100119/191052D2"
        },
        [10011911] = {
          Content = "想起来……{nickname}，你必须想起来……",
          DialogueId = 10011911,
          Duration = 4.5,
          ExStoryInfo = "EXPlayer",
          GUID = "191052D3",
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          SpeakNpcName = "???",
          Subtitle = "Remember... Phoxhunter, you must remember...",
          VoiceName = "voice/$Locale$/story/1001/100119/191052D3"
        },
        [10011912] = {
          Content = "你的力量……和鸣之力……",
          DialogueId = 10011912,
          Duration = 4,
          ExStoryInfo = "EXPlayer",
          GUID = "191052D4",
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          SpeakNpcName = "???",
          Subtitle = "Your power... the power of Resonance...",
          VoiceName = "voice/$Locale$/story/1001/100119/191052D4"
        },
        [10011913] = {
          Content = "如果你渴望拯救这一切……",
          DialogueId = 10011913,
          Duration = 4,
          ExStoryInfo = "EXPlayer",
          GUID = "191052D5",
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          SpeakNpcName = "???",
          Subtitle = "If you wish to save all this...",
          VoiceName = "voice/$Locale$/story/1001/100119/191052D5"
        },
        [10012001] = {
          Content = "再坚持一下！马上就……",
          DefaultLookAt = "Self",
          DialogueId = 10012001,
          DisableMouth = 1,
          Duration = 3,
          GUID = "191061EA",
          LookAt = {
            [1] = "100005:n(100003)"
          },
          RelatedWikiId = {
            [1] = 408001,
            [2] = 201001,
            [3] = 201002
          },
          SpeakNpcId = 100003,
          Subtitle = "Hang in there! I got you...",
          VoiceName = "voice/$Locale$/story/1001/100120/191061EA"
        },
        [10012002] = {
          Content = "贝蕾！",
          DialogueId = 10012002,
          DisableMouth = 1,
          Duration = 1,
          ExStoryInfo = "Player",
          GUID = "191061EB",
          SpeakNpcId = 100001,
          Subtitle = "Berry!",
          VoiceName = "voice/$Locale$/story/1001/100120/191061EB"
        },
        [10012003] = {
          Content = "停手吧，零号。再坚硬的兵刃，也会有折断的一刻。",
          DefaultLookAt = "KeepState",
          DialogueId = 10012003,
          DisableMouth = 1,
          Duration = 4.5,
          GUID = "19106214",
          LookAt = {
            [1] = "100005:n(100003)"
          },
          SpeakNpcId = 100005,
          Subtitle = "Give it up, No. 0. Even the toughest blade has its breaking point.",
          VoiceName = "voice/$Locale$/story/1001/100120/19106214"
        },
        [10012004] = {
          Content = "跟我回去。你会活着——你在乎的那个{性别：少年|小姑娘}也一样。",
          DialogueId = 10012004,
          DisableMouth = 1,
          Duration = 5.5,
          GUID = "19106218",
          SpeakNpcId = 100005,
          Subtitle = "Come back with me, and you'll live — so will this kid you care so much about.",
          VoiceName = "voice/$Locale$/story/1001/100120/19106218"
        },
        [10012005] = {
          Content = "否则，{性别：他|她}的性命就——",
          DialogueId = 10012005,
          DisableMouth = 1,
          Duration = 3.5,
          GUID = "19106219",
          SpeakNpcId = 100005,
          Subtitle = "Otherwise, Phoxhunter will—",
          VoiceName = "voice/$Locale$/story/1001/100120/19106219"
        },
        [10012006] = {
          Content = "……给我承诺。",
          DefaultLookAt = "KeepState",
          DialogueId = 10012006,
          DisableMouth = 1,
          Duration = 1.7,
          GUID = "1910623E",
          SpeakNpcId = 100003,
          Subtitle = "...Give me your word.",
          VoiceName = "voice/$Locale$/story/1001/100120/1910623E"
        },
        [10012007] = {
          Content = "嗯？",
          DialogueId = 10012007,
          DisableMouth = 1,
          Duration = 1,
          GUID = "1910623F",
          SpeakNpcId = 100005,
          Subtitle = "Hmm?",
          VoiceName = "voice/$Locale$/story/1001/100120/1910623F"
        },
        [10012008] = {
          Content = "我跟你回去，你放{性别：他|她}走。",
          DefaultLookAt = "KeepState",
          DialogueId = 10012008,
          DisableMouth = 1,
          Duration = 4,
          GUID = "19106268",
          LookAt = {
            [1] = "100007:n(100005)"
          },
          SpeakNpcId = 100003,
          Subtitle = "I'll go back with you, but you have to promise to let Phoxhunter go.",
          VoiceName = "voice/$Locale$/story/1001/100120/19106268"
        },
        [10012009] = {
          Content = "说啊！否则你就带着我们两个的尸骸回去！",
          DefaultLookAt = "KeepState",
          DialogueId = 10012009,
          DisableMouth = 1,
          Duration = 3.5,
          GUID = "19106292",
          SpeakNpcId = 100003,
          Subtitle = "Give me your word! Or, you can take two corpses back!",
          VoiceName = "voice/$Locale$/story/1001/100120/19106292"
        },
        [10012010] = {
          Content = "你误会了。这不是谈判，是命令。",
          DefaultLookAt = "Self",
          DialogueId = 10012010,
          DisableMouth = 1,
          Duration = 5.5,
          GUID = "190F7C64",
          LookAt = {
            [1] = "100005:n(100005)"
          },
          SpeakNpcId = 100005,
          Subtitle = "Perhaps I wasn't clear — This is not a negotiation, it's an order.",
          VoiceName = "voice/$Locale$/story/1001/100106/190F7C64"
        },
        [10012011] = {
          Content = "……贝蕾。",
          DefaultLookAt = "KeepState",
          DialogueId = 10012011,
          DisableMouth = 1,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "191062E6",
          LookAt = {
            [1] = "100005:n(100003)"
          },
          SpeakNpcId = 100001,
          Subtitle = "...Berry.",
          VoiceName = "voice/$Locale$/story/1001/100120/191062E6"
        },
        [10012012] = {
          Content = "……？！你……！",
          DialogueId = 10012012,
          DisableMouth = 1,
          Duration = 1,
          GUID = "191062E7",
          SpeakNpcId = 100003,
          Subtitle = "...?! No...!",
          VoiceName = "voice/$Locale$/story/1001/100120/191062E7"
        },
        [10012013] = {
          Content = "要逃出去。",
          DialogueId = 10012013,
          DisableMouth = 1,
          Duration = 1.5,
          ExStoryInfo = "Player",
          GUID = "191062E8",
          SpeakNpcId = 100001,
          Subtitle = "Get out of here, and live.",
          VoiceName = "voice/$Locale$/story/1001/100120/191062E8"
        },
        [10012014] = {
          Content = "不——！！",
          DialogueId = 10012014,
          DisableMouth = 1,
          Duration = 1.5,
          GUID = "191062E9",
          SpeakNpcId = 100003,
          Subtitle = "No—!!",
          VoiceName = "voice/$Locale$/story/1001/100120/191062E9"
        },
        [10012015] = {
          Content = "{nickname}，我来考考你。“眨眼三次”这个暗号——",
          DialogueId = 10012015,
          Duration = 5,
          GUID = "191062F0",
          SpeakNpcId = 100003,
          Subtitle = "Quick question, Phoxhunter. The \"three quick blinks\" means—",
          VoiceName = "voice/$Locale$/story/1001/100120/191062F0"
        },
        [10012016] = {
          Content = "用不着贝蕾提醒，我早记住啦！眨眼三次的意思是……",
          DialogueId = 10012016,
          Duration = 6,
          ExStoryInfo = "Player",
          GUID = "191062F1",
          SpeakNpcId = 100001,
          Subtitle = "I've got this, Berry. Three quick blinks means...",
          VoiceName = "voice/$Locale$/story/1001/100120/191062F1"
        },
        [10012017] = {
          Content = "“即使只剩一个人，你也要坚强地活下去。”",
          DialogueId = 10012017,
          DialoguePanelType = "None",
          Duration = 5,
          ExStoryInfo = "Player",
          GUID = "191062F2",
          SpeakNpcId = 100001,
          Subtitle = "\"Even if left all alone, you should be brave and live on.\"",
          VoiceName = "voice/$Locale$/story/1001/100120/191062F2"
        },
        [10012018] = {
          Content = "“直到我们再次相逢。”",
          DialogueId = 10012018,
          DialoguePanelType = "None",
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "191062F3",
          SpeakNpcId = 100001,
          Subtitle = "\"Until the day we meet again.\"",
          VoiceName = "voice/$Locale$/story/1001/100120/191062F3"
        },
        [10012101] = {
          Content = "那是……",
          DialogueId = 10012101,
          Duration = 1.5,
          GUID = "19107252",
          NextDialogue = 10012102,
          SpeakNpcId = 100005,
          Subtitle = "What the...",
          VoiceName = "voice/$Locale$/story/1001/100121/19107252"
        },
        [10012102] = {
          Content = "零号的力量明明还未解放，为什么……",
          DialogueId = 10012102,
          Duration = 2.5,
          GUID = "1910727C",
          NextDialogue = 10012103,
          SpeakNpcId = 100005,
          Subtitle = "No. 0 isn't supposed to release all her powers yet. Why is she...?",
          VoiceName = "voice/$Locale$/story/1001/100121/1910727C"
        },
        [10012103] = {
          Content = "不……这不是零号自身的力量，而是他人赋予的“和鸣之力”。",
          DialogueId = 10012103,
          Duration = 3,
          GUID = "1910727D",
          NextDialogue = 10012104,
          SpeakNpcId = 100005,
          Subtitle = "No, that's not her power, it's Resonance.",
          VoiceName = "voice/$Locale$/story/1001/100121/1910727D"
        },
        [10012104] = {
          Content = "……她护着的小鬼……是“和鸣之力”新的宿体？",
          DialogueId = 10012104,
          Duration = 2.5,
          GUID = "191072A6",
          NextDialogue = 10012110,
          SpeakNpcId = 100005,
          Subtitle = "...That brat she's protecting... that's the new receptacle for Resonance?",
          VoiceName = "voice/$Locale$/story/1001/100121/191072A6"
        },
        [10012105] = {
          Content = "“和鸣之力”和“零号”一起重现……到底意味着什么……",
          DialogueId = 10012105,
          Duration = 3,
          GUID = "191072D0",
          SpeakNpcId = 100005,
          Subtitle = "It made its appearance again here... What does this truly implies...",
          VoiceName = "voice/$Locale$/story/1001/100121/191072D0"
        },
        [10012110] = {
          Content = "这么说来，那小鬼的相貌也……",
          DialogueId = 10012110,
          GUID = "191072D1",
          NextDialogue = 10012105,
          SpeakNpcId = 100005,
          VoiceName = "voice/$Locale$/story/1001/100121/191072D1"
        },
        [10012201] = {
          Content = "快走！",
          DialogueId = 10012201,
          Duration = 2,
          GUID = "191082BA",
          RelatedWikiId = {
            [1] = 408001,
            [2] = 201001,
            [3] = 201003
          },
          SpeakNpcId = 100003,
          Subtitle = "Run!",
          VoiceName = "voice/$Locale$/story/1001/100122/191082BA"
        },
        [10012202] = {
          Content = "别想逃！",
          DialogueId = 10012202,
          Duration = 2,
          GUID = "191082BB",
          SpeakNpcId = 100006,
          Subtitle = "You can't get away!",
          VoiceName = "voice/$Locale$/story/1001/100122/191082BB"
        },
        [10012301] = {
          Content = "你的伤……好些没有？",
          DialogueId = 10012301,
          Duration = 2,
          GUID = "19109322",
          NextDialogue = 10012302,
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100123/19109322"
        },
        [10012302] = {
          Content = "好多了，只是还有些头晕……",
          DialogueId = 10012302,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "1910934C",
          NextDialogue = 10012303,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100123/1910934C"
        },
        [10012303] = {
          Content = "那就好，不要勉强自己。",
          DialogueId = 10012303,
          Duration = 2,
          GUID = "1910934D",
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100123/1910934D"
        },
        [10012401] = {
          Content = "这里好像有什么人生活过。",
          DialogueId = 10012401,
          ExStoryInfo = "Player",
          GUID = "1910A38A",
          NextDialogue = 10012402,
          SpeakNpcId = 100001,
          Subtitle = "It seems someone used to live here.",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A38A"
        },
        [10012402] = {
          Content = "我猜，这是贝蕾曾经的家，对吗？",
          DialogueId = 10012402,
          ExStoryInfo = "Player",
          GUID = "1910A3B4",
          NextDialogue = 10012403,
          SpeakNpcId = 100001,
          Subtitle = "This was your home, am I right, Berry?",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A3B4"
        },
        [10012403] = {
          Content = "……我……",
          DialogueId = 10012403,
          GUID = "1910A3DE",
          NextDialogue = 10012404,
          SpeakNpcId = 100003,
          Subtitle = "...I...",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A3DE"
        },
        [10012404] = {
          Content = "……是的，不止是我。这里是“我们”曾经的家。",
          DialogueId = 10012404,
          GUID = "1910A408",
          NextDialogue = 10012405,
          SpeakNpcId = 100003,
          Subtitle = "...Yes, and no. It was OUR home.",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A408"
        },
        [10012405] = {
          Content = "我们？可我什么都想不起来。",
          DialogueId = 10012405,
          ExStoryInfo = "Player",
          GUID = "1910A432",
          NextDialogue = 10012406,
          SpeakNpcId = 100001,
          Subtitle = "Our home? But I don't remember a thing.",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A432"
        },
        [10012406] = {
          Content = "……没关系，这样更好。等逃出去，我们会建起新的家。",
          DialogueId = 10012406,
          GUID = "1910A433",
          SpeakNpcId = 100003,
          Subtitle = "...It's okay. Maybe it's all for the best. After we make it out, we'll build a new home.",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A433"
        },
