        },
        [10019103] = {
          Content = "▇▇▇渴望▇▇……这一切……",
          DialogueId = 10019103,
          DisableMouth = 1,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1914EF16",
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          SpeakNpcName = "???",
