        [10030412] = {
          Content = "我是第六军团下属，科赛托斯行省卫戍部队准尉，黎瑟·费西尔。",
          DialogueId = 10030412,
          GUID = "191C2E78",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030412.T_Story_Recall_10030412'",
          NextDialogue = 10030413,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100304/191C2E78"
        },
        [10030413] = {
          Content = "她托我带个话，说有事想找你聊聊。",
          DialogueId = 10030413,
          GUID = "191C2EA2",
          NextOptions = {
            [1] = 10030414,
            [2] = 10030415
          },
          SpeakNpcId = 200003,
          VoiceName = "voice/$Locale$/story/1003/100304/191C2EA2"
        },
        [10030414] = {
          Content = "…………",
          DialogueId = 10030414,
          GUID = "191C2ECC",
          NextDialogue = 10030416
        },
        [10030415] = {
          Content = "我跟她没什么好谈的。",
          DialogueId = 10030415,
          GUID = "191C2EF6",
          NextDialogue = 10030416
        },
        [10030416] = {
          Camera = "17.873657,-44.469727,169.63678,-0.001312,-19.399799,94.826927,35.000008,39.151329,false,Manual,3.0",
          Content = "那晚泪湖边上的事，我听说了，我知道你多半不想见她。",
          DialogueId = 10030416,
          GUID = "191C2F20",
          NextDialogue = 10030417,
          SpeakNpcId = 200003,
          VoiceName = "voice/$Locale$/story/1003/100304/191C2F20"
        },
        [10030417] = {
          Camera = "406.211243,-635.881592,325.041443,-0.001344,-16.600023,119.224098,35.0,240.900818,false,Manual,22.0",
          Content = "但你是那夜<H>袭击事件</>中唯一活下来的，我想她不会轻易放弃。",
          DialogueId = 10030417,
          FinalCamera = "391.624817,-609.80957,316.13501,-0.001344,-16.600023,119.224098,35.0,240.900818,false,Manual,22.0",
          GUID = "191C2F4A",
          NextDialogue = 10030418,
          SpeakNpcId = 200003,
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100304/191C2F4A"
        },
        [10030418] = {
          Camera = "18.131149,48.323242,139.37941,-0.001343,2.797912,103.41497,35.000011,171.651077,false,Manual,22",
          Content = "唯一活下来的？",
          DialogueId = 10030418,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "191C2F74",
          NextDialogue = 10030419,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100304/191C2F74"
        },
        [10030419] = {
          Camera = "80.631256,-105.42334,178.525864,0.000194,-7.403289,115.154785,35.000011,142.834564,false,Manual,22.0",
          Content = "时间差不多了。",
          DialogueId = 10030419,
          GUID = "191C2F9E",
          NextDialogue = 10030422,
          SpeakNpcId = 200003,
          VoiceName = "voice/$Locale$/story/1003/100304/191C2F9E"
        },
        [10030420] = {
          Camera = "80.631256,-105.42334,178.525864,0.000194,-7.403289,115.154785,35.000011,142.834564,false,Manual,22.0",
          DialogueId = 10030420,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "80.631256,-105.42334,178.525864,0.000194,-10.20336,110.953819,35.000015,142.834564,false,Manual,22.0",
          GUID = "191C2FC9",
          Scripts = "MoveTo{ActorId{200003},TargetPoint{\"kami_01_leave\"},MoveSpeed{90},Visibility{\"Show\"}}",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          ToFinalCameraBlendTime = 3
        },
        [10030421] = {
          Content = "慰问品七七八八地堆放着，似乎是这几天很多人陆续送来的。\n仔细一看，里面有不知名的野花，虽然冷掉但依旧闻起来美味的肉汤，带划痕但精美的八音盒，画着小鸟的一罐棉花糖……\n除了这些以外，还有一份没有署名，系着歪扭蝴蝶结的朴素礼盒，打开以后发现里面是一瓶帝国最顶尖的止痛剂。这份关怀的心虽是好的，但送给一名昏迷人士止痛剂，实在是没什么意义了。",
          DialogueId = 10030421,
          GUID = "191C2FF2",
          VoiceName = "voice/$Locale$/story/1003/100304/191C2FF2"
        },
        [10030422] = {
          Camera = "80.631256,-105.42334,178.525864,0.000194,-7.403289,115.154785,35.000011,142.834564,false,Manual,22.0",
          Content = "还想知道什么，就去水仙平原问你的朋友吧。这几天他们也很挂念你。",
          DialogueId = 10030422,
          GUID = "191C2FC8",
          NextDialogue = 10030420,
          SpeakNpcId = 200003,
          VoiceName = "voice/$Locale$/story/1003/100304/191C2FC8"
        },
        [10030501] = {
          Content = "（咦，冰湖城多了好多气球……最近是什么节日吗？）",
          DialogueId = 10030501,
          DisableMouth = 1,
          GUID = "191C3D12",
          NextDialogue = 10030502,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100305/191C3D12"
        },
        [10030502] = {
          Content = "（但这么热闹的装饰，也盖不住空气里的冷清……）",
          DialogueId = 10030502,
          DisableMouth = 1,
          GUID = "191C3D3C",
          NextDialogue = 10030503,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100305/191C3D3C"
        },
        [10030503] = {
          Content = "（去找奥特赛德和白了解下昏迷这几天的情况吧。）",
          DialogueId = 10030503,
          DisableMouth = 1,
          GUID = "191C3D66",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100305/191C3D66"
        },
        [10030504] = {
          Content = "13个人，13个人！一夜之间！",
          DialogueId = 10030504,
          Duration = 5,
          GUID = "191C3D90",
          SpeakNpcId = 700036,
          VoiceName = "voice/$Locale$/story/1003/100305/191C3D90"
        },
        [10030505] = {
          Content = "躲在家里也不安全，我们到底该怎么办……",
          DialogueId = 10030505,
          Duration = 7,
          GUID = "191C3DBA",
          SpeakNpcId = 700038,
          VoiceName = "voice/$Locale$/story/1003/100305/191C3DBA"
        },
        [10030506] = {
          Content = "唉，一把老骨头了，总不能为这事搬家吧……",
          DialogueId = 10030506,
          Duration = 7,
          GUID = "191C3DE4",
          SpeakNpcId = 700246,
          VoiceName = "voice/$Locale$/story/1003/100305/191C3DE4"
        },
        [10030507] = {
          Content = "演员在八音盒内旋转，我们在冰湖城中徘徊！转折将要发生，雾海欢迎来客！",
          DialogueId = 10030507,
          Duration = 12,
          GUID = "191C3E0E",
          SpeakNpcId = 700015,
          VoiceName = "voice/$Locale$/story/1003/100305/191C3E0E"
        },
        [10030508] = {
          Content = "别，别过来，不要杀我……卫戍部队，卫戍部队在哪里？！",
          DialogueId = 10030508,
          Duration = 9,
          GUID = "191C3E38",
          SpeakNpcId = 700035,
          VoiceName = "voice/$Locale$/story/1003/100305/191C3E38"
        },
        [10030509] = {
          Content = "怪物，绝对是怪物干的……",
          DialogueId = 10030509,
          Duration = 4,
          GUID = "191C3E62",
          SpeakNpcId = 700034,
          VoiceName = "voice/$Locale$/story/1003/100305/191C3E62"
        },
        [10030510] = {
          Content = "冰湖城外城近日发生多起恶性伤人事件，手段极其残忍，现场极为混乱，请广大市民减少深夜外出，锁好门窗。\n持有武器许可证的市民如果遭遇行凶者，不要试图反击（这很危险！！！），优先保全自身性命。\n如有凶手线索，请立即联系卫戍部队，黎瑟·费西尔。\n皇帝会庇护他忠诚的子民度过难关，荣耀尽归吾皇。",
          DialogueId = 10030510,
          GUID = "191C3E8C",
          VoiceName = "voice/$Locale$/story/1003/100305/191C3E8C"
        },
        [10030601] = {
          Content = "挥手打个招呼。",
          DialogueId = 10030601,
          GUID = "191C4D7A",
          NextDialogue = 10030603
        },
        [10030602] = {
          Content = "吹个口哨。",
          DialogueId = 10030602,
          GUID = "191C4DA4",
          NextDialogue = 10030603
        },
        [10030603] = {
          Camera = "78.226898,5.710938,147.152344,0.000109,-17.401026,138.984924,35.000011,249.345123,false,Manual,3.0",
          Content = "呜呜呜……是你，{nickname}，真的是你！！",
