          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:Shock_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA24C"
        },
        [10031119] = {
          Content = "要是把军团这身行头脱下来，便装去贫民窟转一圈，我看恐怕不等太阳下山，您就得赔得连鞋子都不剩了。",
