          VoiceName = "voice/$Locale$/story/1003/100321/191D4536"
        },
        [10032112] = {
          Content = "诶，钉子呢，怎么偏偏在加固舞台架子的时候找不到了。",
          DialogueId = 10032112,
          Duration = 9,
          GUID = "191D450D",
          VoiceName = "voice/$Locale$/story/1003/100321/191D450D"
        },
        [10032113] = {
          Content = "丹尼斯呢？还有几天就正式上台了，就差他没试妆拍定妆照了。",
