          Duration = 10,
          GUID = "191D450E",
          VoiceName = "voice/$Locale$/story/1003/100321/191D450E"
        },
        [10032114] = {
          Content = "“秉烛起舞，放声歌唱在这个雪夜。”",
          DialogueId = 10032114,
          Duration = 6,
          GUID = "191D450F",
          SpeakNpcId = 100370,
          VoiceName = "voice/$Locale$/story/1003/100321/191D450F"
        },
        [10032115] = {
          Content = "第三幕的灯光设计得改一下。我们要模拟的是蜡烛被逐个点亮的光线变化，明白吗？逐、个、点、亮！",
          DialogueId = 10032115,
          Duration = 15,
          GUID = "191D4510",
          VoiceName = "voice/$Locale$/story/1003/100321/191D4510"
        },
        [10032116] = {
