          NextDialogue = 10034406,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100344/191EBDBC"
        },
        [10034406] = {
          Content = "琳恩长官为什么独自向着<H>内城</>走了？",
          DialogueId = 10034406,
          GUID = "191EBDE6",
          NextDialogue = 10034407,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100344/191EBDE6"
        },
        [10034407] = {
          Content = "炼金院、执政厅、第六军团驻扎地都在内城，过去无非就是调遣、应酬、问责、叙旧之类的吧。",
          DialogueId = 10034407,
          GUID = "191EBE10",
          NextDialogue = 10034408,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE10"
        },
        [10034408] = {
          Content = "反正与我们无关，我的人生准则之一就是，少问多做，才能活得更久。",
          DialogueId = 10034408,
          GUID = "191EBE3A",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE3A"
        },
        [10034410] = {
          Content = "就是在这里接货吧！哇啊——怎么有雪狼！",
          DialogueId = 10034410,
          GUID = "191EBE64",
          NextDialogue = 10034411,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE64"
        },
        [10034411] = {
          Content = "你们就是琳恩长官说的本地人小队吧，货物还没来，跟我把这片区域清理出来。",
          DialogueId = 10034411,
          GUID = "191EBE8E",
          NextDialogue = 10034412,
          SpeakNpcId = 100310,
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE8E"
        },
        [10034412] = {
          Content = "唉，又要多干一份活喽。",
          DialogueId = 10034412,
          GUID = "191EBEB8",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100344/191EBEB8"
        },
        [10034413] = {
          Content = "警戒线都拉起来，动作快！",
          DialogueId = 10034413,
          GUID = "191EBE3B",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE3B"
        },
        [10034414] = {
          Content = "冰湖城这几日宵禁，没有许可禁止随意走动。",
          DialogueId = 10034414,
          GUID = "191EBE3C",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE3C"
        },
        [10034415] = {
          Content = "银烛狂欢之前肯定能结案，这些花花绿绿的装饰就放着吧。",
          DialogueId = 10034415,
          GUID = "191EBE3D",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE3D"
        },
        [10034416] = {
          Content = "通讯测试，一二三一二三，通讯测试，一二三，能听到吗？好，我这儿听着也没问题。",
          DialogueId = 10034416,
          GUID = "191EBE3E",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE3E"
        },
        [10034417] = {
          Content = "说是宵禁，怎么白天也不让出去啊？",
          DialogueId = 10034417,
          GUID = "191EBE40",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE40"
        },
        [10034418] = {
          Content = "该死，这批新鲜霜脊鱼卖不出去了。",
          DialogueId = 10034418,
          GUID = "191EBE41",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE41"
        },
        [10034419] = {
          Content = "噢，我心爱的女士，这个夜晚我孤枕难眠，明明我们只隔着两条街的距离却无法相见……",
          DialogueId = 10034419,
          GUID = "191EBE42",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE42"
        },
        [10034420] = {
          Content = "长官行行好啊，我不过去干活，全家都要饿死了……",
          DialogueId = 10034420,
          GUID = "191EBE43",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE43"
        },
        [10034421] = {
          Content = "怎么老是你？当心长官送你全家吃牢饭！",
          DialogueId = 10034421,
          GUID = "191EBE44",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE44"
        },
