        [10035308] = {
          Camera = "70.957031,207.253906,117.710938,0.000085,4.599012,-117.169922,25.000006,100000.0,false,Manual,22.0",
          Content = "黎瑟呢？",
          DialogueId = 10035308,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "191F51B8",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10035309,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100353/191F51B8"
        },
        [10035309] = {
          Content = "透气去了。",
          DialogueId = 10035309,
          GUID = "191F51E2",
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F51E2"
        },
        [10035310] = {
          Camera = "27.261719,-48.188965,98.787598,0.000046,5.787246,58.397362,35.000008,100000.0,false,Manual,22.0",
          Content = "“……无言的白雪啊，苍穹的女儿……为那无名的孩子献上祝福……他和雪花跳起轻快的舞……”",
          DialogueId = 10035310,
          FinalCamera = "42.640625,-23.193359,101.764648,0.000046,5.787246,58.397282,35.000008,100000.0,false,Manual,22.0",
          GUID = "191F520C",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "200002:n(100304)",
            [3] = "100001:n(100304)"
          },
          NextDialogue = 10035311,
          RelatedWikiId = {
            [1] = 408003,
            [2] = 405005,
            [3] = 201011,
            [4] = 201024
          },
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:Lise_Sing_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100353/191F520C"
        },
        [10035311] = {
          Camera = "106.324219,18.061035,129.950195,0.000045,-7.413487,-143.597916,35.000008,100000.0,false,Manual,22.0",
          Content = "……就是这个！就是这个旋律。它叫什么，唱的什么意思？",
          DialogueId = 10035311,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "191F5236",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "200002:n(100001)",
            [3] = "100001:n(100304)"
          },
          NextDialogue = 10035312,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F5236"
        },
        [10035312] = {
          Camera = "-158.65625,-332.602051,130.729492,0.000072,-4.813562,57.80043,35.000008,100000.0,false,Manual,22.0",
          Content = "咦？这个吗……我没留意，下意识就哼出来了。我想一下……",
          DialogueId = 10035312,
          FacialId = {
            [1] = "100001:None",
            [2] = "100304:Shock01"
          },
          GUID = "191F5260",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "200002:n(100304)",
            [3] = "100001:n(100304)",
            [4] = "100304:n(100001)"
          },
          NextDialogue = 10035313,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:Lise_Sing_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F5260"
        },
        [10035313] = {
          Content = "这首是布鲁斯教给我的，叫《致无名者的安魂曲》，是歌剧《雪国的孩子》里的唱段。不过我唱的歌词不太对，真正的歌词应该会更悲伤一点。",
          DialogueId = 10035313,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191F528A",
          NextDialogue = 10035314,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100001:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F528A"
        },
        [10035314] = {
          Content = "那首歌本来好像讲的是……一只无名的妖精，为了救它的朋友而牺牲，但朋友直到最后都不知道这件事，只有白雪记住了一切。",
          DialogueId = 10035314,
          GUID = "191F52B4",
          LookAt = {
            [1] = "100304:n(100304)"
          },
          NextDialogue = 10035315,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F52B4"
        },
        [10035315] = {
          Camera = "43.828125,-22.387695,88.140137,0.000079,8.586326,60.000477,35.0,100000.0,false,Manual,22.0",
          Content = "不过布鲁斯不喜欢这个结局，所以自作主张把歌词改成了一个快乐的版本。他熟到能把这首歌倒着演奏，所以没录过这首……",
          DialogueId = 10035315,
          FacialId = {
            [1] = "100304:Think01"
          },
          GUID = "191F52DE",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "200002:n(100304)",
            [3] = "100001:n(100304)"
          },
          NextDialogue = 10035316,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100353/191F52DE"
        },
        [10035316] = {
          Content = "你是说，你听到的就是它……？",
          DialogueId = 10035316,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191F5308",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10035317,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F5308"
        },
        [10035317] = {
          Camera = "138.671875,16.285156,67.811523,7.200567,11.981702,-152.809799,35.000008,100000.0,false,Manual,22.0",
          Content = "对，我遇袭当晚听到的就是这个旋律！",
          DialogueId = 10035317,
          GUID = "191F5332",
          NextDialogue = 10035318,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Agree"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F5332"
        },
        [10035318] = {
          Camera = "43.828125,-22.387695,88.140137,0.000081,6.1863,60.000423,35.0,100000.0,false,Manual,22.0",
          Content = "…………",
          DialogueId = 10035318,
          FacialId = {
            [1] = "100304:Think01"
          },
          FinalCamera = "43.828125,-22.387695,88.140137,0.000079,8.586326,60.000477,35.0,100000.0,false,Manual,22.0",
          GUID = "191F535C",
          LookAt = {
            [1] = "100304:p(lise_50_ditou)"
          },
          NextDialogue = 10035319,
          SpeakNpcId = 100304,
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100353/191F535C"
        },
        [10035319] = {
          Content = "虽然是新的线索，但很遗憾，这条线索指向的范围太广了。《雪国的孩子》在盖雷亚剧院已经上演了几十年，曾经是非常热门的剧，所以这里很多人都会唱。",
          DialogueId = 10035319,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191F5386",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10035320,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt03/0071_lise_secret\"},RelatedRegionId{101103}}",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100353/191F5386"
        },
        [10035320] = {
          Camera = "-47.433594,-302.833496,184.461426,0.000141,-15.616298,71.198349,25.000002,100000.0,false,Manual,22.0",
          Content = "有一次，我和布鲁斯攒了大半年的钱，好不容易才买到那场剧的门票，却在现场被冤枉成偷了别人的票，被赶了出来。",
          DialogueId = 10035320,
          FacialId = {
            [1] = "100304:Sad01"
          },
          FinalCamera = "-43.898438,-292.427002,181.38916,0.000141,-15.616298,71.198349,25.000002,100000.0,false,Manual,22.0",
          GUID = "191F53B0",
          NextDialogue = 10035321,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:Talk02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100353/191F53B0"
        },
        [10035321] = {
          Content = "那夜我靠着剧院的墙坐了很久，心情糟透了。布鲁斯却像变魔术一样掏出口琴，吹起了那首歌的旋律。原来，他自己早就练会了这首曲子……",
          DialogueId = 10035321,
          GUID = "191F53DA",
          NextDialogue = 10035322,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100353/191F53DA"
        },
        [10035322] = {
          Camera = "69.078125,-79.48877,262.419922,0.000194,-37.617821,73.187332,35.000008,100000.0,false,Manual,22.0",
          Content = "他吹着吹着，在墙的另一边，突然就有个男孩子跟着唱起来了。他的歌喉好动听，像云雀一样。",
          DialogueId = 10035322,
          FinalCamera = "75.945312,-56.791992,244.148438,0.000194,-37.617821,73.187332,35.000008,100000.0,false,Manual,22.0",
          GUID = "191F5404",
          NextDialogue = 10035323,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:Talk02_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100353/191F5404"
        },
        [10035323] = {
          Camera = "292.566406,182.274902,118.647949,0.000237,-2.417996,-149.207611,35.000008,100000.0,false,Manual,22.0",
          Content = "那一晚，因为有布鲁斯的口琴，还有那个陌生人的跟唱，我好开心，都快忘了自己被赶出来的事。",
          DialogueId = 10035323,
          GUID = "191F542E",
          NextDialogue = 10035324,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100353/191F542E"
        },
        [10035324] = {
          Camera = "72.292969,-58.250488,84.757324,0.000228,9.781732,71.391068,35.000008,100000.0,false,Manual,22.0",
          Content = "抱歉，不好意思，自顾自地说起来了。我的意思是，这首歌会的人太多了，无法成为指向性的证据。",
          DialogueId = 10035324,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191F5458",
          NextDialogue = 10035325,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:ScratchHead_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F5458"
        },
        [10035325] = {
          Camera = "35.425781,210.5625,76.637207,0.000075,18.182783,-57.792496,35.000011,100000.0,false,Manual,22.0",
          Content = "那，这出戏近期会上演吗？没准我们可以蹲点试试。",
          DialogueId = 10035325,
          FinalCamera = "35.425781,210.5625,76.637207,0.000069,11.982678,-57.391754,35.000011,100000.0,false,Manual,22.0",
          GUID = "191F5482",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "200002:n(200021)",
            [3] = "100001:n(200021)"
          },
          NextDialogue = 10035326,
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100353/191F5482"
        },
        [10035326] = {
          Camera = "46.15625,-202.915527,167.463867,0.000052,-11.016801,66.199203,35.000011,100000.0,false,Manual,22.0",
          Content = "近期吗……我不太清楚。不过据我所知，这出剧这两年已经停演了，因为一起发生在盖雷亚剧院的<H>事故</>。",
          DialogueId = 10035326,
          GUID = "191F54AC",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "200002:n(100304)",
            [3] = "100001:n(100304)",
            [4] = "100304:n(200021)"
          },
          NextDialogue = 10035327,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:ScratchHead_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F54AC"
        },
        [10035327] = {
          Camera = "109.480469,38.969727,114.763672,0.000073,-0.616664,-141.401657,35.0,100000.0,false,Manual,22.0",
          Content = "事故？",
          DialogueId = 10035327,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "191F54D6",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "200002:n(100001)",
            [3] = "100001:n(100304)"
          },
          NextDialogue = 10035328,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F54D6"
        },
        [10035328] = {
          Camera = "-151.640625,-339.61792,161.115723,0.000086,-9.217005,58.195625,35.000008,100000.0,false,Manual,22.0",
          Content = "嗯，之前整理案卷的时候，在笔录里看到的。倒不是什么大事，只是两年前演出现场的一起斗殴。",
          DialogueId = 10035328,
          GUID = "191F5500",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10035329,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100353/191F5500"
        },
        [10035329] = {
          Camera = "24.625,-15.047363,93.071777,0.000097,8.781772,53.395985,35.000008,100000.0,false,Manual,22.0",
          Content = "但普奇剧团长说，因为这起事故中主演受了伤，“魔笛”剧团将暂停《雪国的孩子》的后续演出。",
          DialogueId = 10035329,
          GUID = "191F552A",
          NextDialogue = 10035330,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100353/191F552A"
        },
        [10035330] = {
          Content = "我翻翻本子——嗯，还有当时抄的笔记。",
          DialogueId = 10035330,
          GUID = "191F5554",
          NextDialogue = 10035331,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100353/191F5554"
        },
        [10035331] = {
          Content = "盖雷亚剧院斗殴事件\n\n时间：10月9日晚8:30\n\n报案人：莱蒂齐娅·普奇（“魔笛”剧团团长）\n\n参与斗殴双方：帕西法尔·斯诺菲尔德（主演）、苏珊娜·罗西（主演）……\n马修·伯纳德（观众）、菲利·弗兰西斯科（观众）……\n\n事件：疑似剧团成员与前排观众就剧目发生冲突？疑似观众殴打演员？（部分笔录内页被撕掉了）\n\n结论：证据不足，不予立案\n\n备注：《雪国的孩子》暂时停演，演出时间不定。\n很想和布鲁斯弥补一下当年看不成剧的遗憾，但似乎短时间内没有机会了。",
          DialogueId = 10035331,
          DialoguePanelType = "{type:showtext;topic:READ_NAME_2000049;content:READ_TEXT_2000049}",
          GUID = "191F557E",
          NextDialogue = 10035332,
          VoiceName = "voice/$Locale$/story/1003/100353/191F557E"
        },
        [10035332] = {
          Camera = "-175.097656,-375.326904,138.394531,0.000041,-5.200041,58.387745,35.000011,100000.0,false,Manual,22.0",
          Content = "不过，除了继续调查下水道之外，眼下也只有这一条新线索了……",
          DialogueId = 10035332,
          FacialId = {
            [1] = "100304:Think01"
          },
          FinalCamera = "-159.128906,-349.168457,135.712402,0.000042,-5.000033,59.587662,35.000011,100000.0,false,Manual,22.0",
          GUID = "191F55A8",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "200002:n(100304)",
            [3] = "100001:n(100304)"
          },
          NextDialogue = 10035333,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:Think_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100353/191F55A8"
        },
        [10035333] = {
          Content = "你刚才提醒了我，如果《雪国的孩子》对凶手的确有特殊意义，那的确可以考虑引蛇出洞。",
          DialogueId = 10035333,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191F55D2",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10035334,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F55D2"
        },
        [10035334] = {
          Content = "对喽。咱们去剧院问问普奇剧团长，看看她老人家能不能帮个忙，放个假消息吧。",
          DialogueId = 10035334,
          GUID = "191F55FC",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "200002:n(200021)",
            [3] = "100001:n(200021)",
            [4] = "100304:n(200021)"
          },
          NextDialogue = 10035335,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100353/191F55FC"
        },
        [10035335] = {
          Content = "愚蠢。",
          DialogueId = 10035335,
          GUID = "191F5626",
          NextDialogue = 10035337,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"},RelatedRegionId{101103}}",
          SpeakNpcId = 100327,
