          Duration = 7,
          GUID = "191FF4CC",
          SpeakNpcId = 100368,
          VoiceName = "voice/$Locale$/story/1003/100363/191FF4CC"
        },
        [10036303] = {
          Content = "哈哈哈哈你看那边，还有人装扮成神弃者和秽兽呢，不要命啦。",
