          Duration = 10,
          GUID = "191FF4F6",
          SpeakNpcId = 100367,
          VoiceName = "voice/$Locale$/story/1003/100363/191FF4F6"
        },
        [10036304] = {
          Content = "怕什么，在这里我们没有身份，没有名字，没有种族！只有狂欢，彻夜狂欢！",
          DialogueId = 10036304,
          Duration = 12,
          GUID = "191FF520",
