          NextDialogue = 10036309,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"},RelatedRegionId{101901}}",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
