          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF646"
        },
        [10036312] = {
          Content = "你……怎么……唔……呃——！",
          DialogueId = 10036312,
          GUID = "191FF670",
          NextDialogue = 10036313,
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF670"
        },
        [10036313] = {
          Content = "协助你，借此引来，十三军团，目的，达到。",
          DialogueId = 10036313,
          GUID = "191FF69A",
          NextDialogue = 10036314,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF69A"
        },
        [10036314] = {
          Content = "但十三军团，拒绝，揭露真相。",
          DialogueId = 10036314,
          GUID = "191FF6C4",
          NextDialogue = 10036315,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF6C4"
        },
        [10036315] = {
          Content = "那么你，就没有，利用价值。",
          DialogueId = 10036315,
          GUID = "191FF6EE",
          NextDialogue = 10036316,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF6EE"
        },
        [10036316] = {
          Content = "神弃者，也是，祸患。",
          DialogueId = 10036316,
          GUID = "191FF718",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF718"
        },
        [10036317] = {
          Content = "酷啊！这次的演出比往年还逼真！",
          DialogueId = 10036317,
          GUID = "191FF742",
          NextDialogue = 10036318,
          SpeakNpcName = "Cp2CharacterName33",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF742"
        },
        [10036318] = {
          Content = "喂，怎么还有人装扮成军团士兵的模样啊？看手里那家伙，跟真的一样啊！",
          DialogueId = 10036318,
          GUID = "191FF76C",
          NextDialogue = 10036319,
          SpeakNpcName = "Cp2CharacterName33",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF76C"
        },
        [10036319] = {
          Content = "他们是在演什么战争戏吗？打起来，打起来！",
