        },
        [10037630] = {
          Camera = "-117.756836,88.672852,108.013672,0.000201,6.600804,-84.378052,35.0,938.158691,false,DoNotOverride,1.2",
          Content = "行吧，我看看……“无言的白雪啊，苍穹的女儿”……",
          DialogueId = 10037630,
