          VoiceName = "voice/$Locale$/story/1003/100383/1920CA16"
        },
        [10038401] = {
          Content = "那之后，卡戎之民更是在整个海伯利亚燃起战火，四处杀戮，直到帝国的缔造者——仁慈的迪斯·盖雷亚陛下结束了战争，带来了和平。",
          DialogueId = 10038401,
          GUID = "191E6E2B",
          NextDialogue = 10033922,
          SpeakNpcId = 100357,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6E2B"
        },
        [10100101] = {
          Content = "……喂……喂——",
          DialogueId = 10100101,
          Duration = 3.5,
          GUID = "1948D7D2",
          SpeakNpcId = 200002,
          Subtitle = "...Hello? ...Hello—",
          VoiceName = "voice/$Locale$/story/1002/101001/1948D7D2"
