        },
        [10100206] = {
          Camera = "-113.203125,-295.231201,144.942871,0.001206,-5.299714,67.000038,35.0,256.035278,false,Manual,4.0",
          CameraBlendCurve = "easeInQuad",
          Content = "哎，你在发什么呆？<H>白</>和卡米拉可是专门跑了大老远来救你的！先乖乖跟我们进城，不然就要被闲逛的秽兽啪嚓啪嚓吃掉了！",
          DialogueId = 10100206,
          ExStoryInfo = "Player",
          FacialId = {
