          },
          FinalCamera = "-115.261719,-294.439941,138.69043,0.001206,-5.299714,69.000008,35.0,256.035278,false,Manual,4.0",
          GUID = "1948E8E2",
          NextDialogue = 10100207,
          RelatedWikiId = {
            [1] = 201004,
            [2] = 201005
          },
          Scripts = [[
PARA{
CameraMoveTo{_delay{5},TargetPosition{"-60.582031,-61.83252,90.654297,0.001224,-6.29949,77.795509,39.952579,138.086899,false,Manual,4.0"},duration{0}},
SEQ{
