          SpeakNpcId = 200002,
          Subtitle = "Well, yeah... What's the big deal?",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101002/1948E98A"
        },
        [10100211] = {
          Camera = "321.105469,367.106934,155.726562,0.001201,-4.999698,-131.971817,50.0,545.258301,false,Manual,3.0",
          Content = "那你们知道一个叫西比尔的女人吗？其他人叫她“军团长”，她应该就在这个国家……我想去找她。",
          DialogueId = 10100211,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "1948E9B4",
          LookAt = {
            [1] = "100001:n(200003)",
            [2] = "200002:n(100001)"
          },
          NextDialogue = 10100212,
          SpeakNpcId = 100001,
          Subtitle = "Do you know this woman called Sibylle? Others refer to her as the \"Chief,\" and she's supposed to be in this country... I need to find her.",
          TalkActionId = {
            [1] = "200002:Talk03_End",
            [2] = [[

100001:Talk02_Start]]
          },
          VoiceName = "voice/$Locale$/story/1002/101002/1948E9B4"
        },
        [10100212] = {
          Camera = "109.613281,-278.998535,123.344238,0.001196,-0.900663,111.229919,35.0,322.557617,false,Manual,3.0",
          Content = "叫西比尔的人遍地都是，但是被称作“军团长”的只能是那一位。找她？卡戎之民无惧严寒，你是怎么把脑子冻坏的？",
          DialogueId = 10100212,
          FacialId = {
            [1] = "200003:Uninterested01"
          },
          GUID = "1948E9DE",
          NextDialogue = 10100213,
          RelatedWikiId = {
            [1] = 303003
          },
          Scripts = [[
SEQ{
PlayAnimation{_delay{4},ActorId{200003},AnimationId{"Talk03_End"},Duration{1}},
PlayAnimation{_delay{1},ActorId{200003},AnimationId{"Think_Start"},Duration{1}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "Sibylle is a common name, but there's only one that's linked with the title \"Chief.\" You want to find her? How did you lose your mind to the blizzard? I thought Charons are supposed to be resistant to cold temperatures.",
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "200002:SpecialConfident_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101002/1948E9DE"
        },
        [10100213] = {
          Camera = "94.464844,26.425293,178.743652,0.001218,-19.900541,-128.170197,36.276737,164.815262,false,Manual,2.909652",
          Content = "我没在开玩笑。我有一个重要的……东西，可能落在了她手上，所以我一定要搞清楚。",
          DialogueId = 10100213,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Angry01",
            [2] = "200003:None",
            [3] = "200002:None"
          },
          GUID = "1948EA08",
          NextDialogue = 10100214,
          Scripts = [[
PARA{
PlayAnimation{ActorId{100001},AnimationId{"DisagreeHead"},Duration{1.5}},
PlayAnimation{_delay{5},ActorId{100001},AnimationId{"Angry01_Start"},Duration{5}},
LookAt{_delay{5},LookAtDescription{"100001:n(200003)"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "I'm serious. She might've taken some...thing that's very important to me, so I must find her and get to the bottom of it.",
          VoiceName = "voice/$Locale$/story/1002/101002/1948EA08"
        },
        [10100214] = {
          Camera = "67.046875,-72.922852,121.009277,0.001219,8.898916,104.827866,36.0,149.916138,false,Manual,2.8",
          Content = "间谍，刺客，反抗者——单是凭你刚刚这句话，帝国士兵就能找出三种由头逮捕你。如果真的想要找大军团长，我奉劝你先不要这么着急。",
          DialogueId = 10100214,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "61.769531,-52.95752,124.242676,0.001221,8.898916,104.827972,36.0,149.916138,false,Manual,2.8",
          GUID = "1948EA32",
          NextDialogue = 10100215,
          Scripts = [[
SEQ{
PlayAnimation{_delay{6},ActorId{200003},AnimationId{"Think_End"},Duration{2}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "Espionage, assassination, defiance... With what you've just said, the Imperial soldiers could just arrest you for these three reasons alone. If you really want to find the Chief, I'd advise you not to rush into it.",
          ToFinalCameraBlendTime = 16,
          VoiceName = "voice/$Locale$/story/1002/101002/1948EA32"
        },
        [10100215] = {
          Camera = "90.78125,-235.538574,124.035156,0.001194,-0.900574,106.602898,35.000008,299.733246,false,Manual,2.8",
          Content = "最后一遍，不想留在这儿给秽兽当口粮，就跟上来。",
          DialogueId = 10100215,
          GUID = "1948EA5C",
          LookAt = {
            [1] = "200003:n(200003)"
          },
          NextOptions = {
            [1] = 101002151,
            [2] = 101002152
          },
          Scripts = [[
PARA{
CameraMoveTo{_delay{3.8},TargetPosition{"92.84375,-269.014404,124.547852,0.001194,-0.900574,106.602898,35.000008,299.733246,false,Manual,2.8"},duration{4.5}},
TurnTo{_delay{3.5},TurnToDescription{"200003:p(180)"}},
PlayAnimation{_delay{3},ActorId{100001},AnimationId{"Angry01_End"},Duration{2}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "For the last time, if you don't want to end up as Filthoid fodder, come with us.",
          TalkActionId = {
            [1] = "200002:SpecialConfident_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101002/1948EA5C"
        },
        [10100216] = {
          Camera = "-22.671875,234.560547,176.765625,0.00112,-9.999943,-80.167923,40.0,330.076355,false,Manual,2.602004",
          Content = "谢谢搭救。但是——",
          DialogueId = 10100216,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01",
            [2] = "200003:Uninterested01"
          },
          GUID = "1948EA86",
          NextDialogue = 10100217,
          Scripts = "SetRotation{SetRotationDescription{\"200003:p(25)\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Thanks for saving my life. But—",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101002/1948EA86"
        },
        [10100217] = {
          Camera = "-22.671875,234.560547,176.765625,0.00112,-9.999943,-80.167923,40.0,330.076355,false,Manual,2.602004",
          CameraBlendCurve = "easeInQuad",
          Content = "你在担忧，在犹疑，“这两个陌生人非亲非故，一定对我别有所图”。",
          DialogueId = 10100217,
          FinalCamera = "-15.765625,235.758301,176.765625,0.001125,-9.999943,-80.167831,40.0,173.539764,false,Manual,4.0",
          GUID = "1948EAB0",
          NextDialogue = 10100218,
          SpeakNpcId = 200003,
          Subtitle = "You're worried, and suspicious — \"These two strangers must be up to something.\"",
          TalkActionId = {
            [1] = "200003:SpecialUnInterested_Start"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101002/1948EAB0"
        },
        [10100218] = {
