}]],
          SpeakNpcId = 200002,
          Subtitle = "I'd say you are normally an honest kid. Look, your hands are still shaking.",
          VoiceName = "voice/$Locale$/story/1002/101008/19494AD4"
        },
        [10100803] = {
          Camera = "558.880859,-1181.942383,616.315918,0.000001,8.100494,27.304859,20.0,971.015747,false,DoNotOverride,1.2",
          CameraBlendCurve = "easeInOutQuad",
          Content = "没关系，在这种地方待久了，这种生活伎俩，很快就会变得熟练的。",
          DialogueId = 10100803,
          FacialId = {
            [1] = "200002:Happy01"
          },
          FinalCamera = "558.880859,-1181.942383,665.315918,0.000001,8.100494,27.304859,20.0,971.015747,false,DoNotOverride,1.2",
          GUID = "19494AFE",
          NextDialogue = 10100804,
          SpeakNpcId = 200003,
          Subtitle = "It's alright. You'll get used to these tricks of survival in no time in a place like this.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/101008/19494AFE"
        },
        [10100804] = {
          Camera = "-248.898438,-755.938965,492.554199,0.000024,-25.400085,73.454407,40.000011,873.135193,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          Content = "好了，带你进来，<H>交易</>就已经达成，我也该回去做我的生意了。你不会给我惹什么麻烦的——对吧？",
          DialogueId = 10100804,
          FacialId = {
            [1] = "200003:Uninterested01"
          },
          FinalCamera = "-238.40332,-759.057129,492.554199,0.000021,-25.400085,74.854248,40.000011,873.135193,false,Manual,1.2",
          GUID = "19494B28",
          LookAt = {
