PlayAnimation{ActorId{200003},AnimationId{"SpecialUnInterested_Start"},Duration{1.5}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "Alright, now that I've brought you in, the deal is fulfilled — I should go back to my tavern. Stay out of trouble for me, alright?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101008/19494B28"
        },
        [10100805] = {
          Camera = "243.654297,-17.984863,184.813477,0.00001,-12.0,-177.54332,40.0,144.905365,false,Manual,5.0",
          Content = "请等一下！我还没太搞明白。",
          DialogueId = 10100805,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01"
          },
          FinalCamera = "243.380859,-13.443848,184.813477,0.00001,-12.0,-176.54332,40.0,315.1875,false,Manual,5.0",
          GUID = "19494B52",
          NextDialogue = 10100806,
          Scripts = "LookAt{_delay{3},LookAtDescription{\"200003:p(P10100801)\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Wait a minute! I'm still quite confused.",
          TalkActionId = {
