            [2] = "200003:SpecialUnInterested_End"
          },
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1002/101008/19494B52"
        },
        [10100806] = {
          Camera = "243.380859,-13.443848,184.813477,0.00001,-12.0,-176.54332,40.0,315.1875,false,Manual,5.0",
          Content = "那就问快些。生意人的时间很宝贵。",
          DialogueId = 10100806,
          FacialId = {
            [1] = "200003:None",
            [2] = "100001:None"
          },
          GUID = "19494B7C",
          LookAt = {
            [1] = "200003:n(200003)"
          },
          NextDialogue = 101008062,
          Scripts = [[
PARA{
CameraMoveTo{_delay{1},TargetPosition{"-196.237305,-18.549316,146.658691,0.001187,-2.999962,0.843019,35.000008,264.133331,false,Manual,6.0"},duration{0}},
TurnTo{_delay{2.5},TurnToDescription{"200003:p(160)"}},
PlayAnimation{_delay{3},ActorId{100001},AnimationId{"Explain02_End"},Duration{1}},
PlayAnimation{_delay{4.5},ActorId{200003},AnimationId{"Confident_Start"},Duration{1}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "Then make it quick. Time is money for a merchant.",
          TalkActionId = {
            [1] = "200002:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101008/19494B7C"
        },
        [10100807] = {
          Camera = "-41.894531,-35.158691,105.682129,0.001197,-6.101988,37.254318,35.000008,182.792282,false,Manual,4.0",
          Content = "没错！就在昨天这个月黑风高的夜晚，有只一身白光的恶魔，潜入了卡米拉的酒馆，威胁她——",
          DialogueId = 10100807,
          FacialId = {
            [1] = "200002:Happy01",
            [2] = "100001:Doubt01"
          },
          GUID = "19494BA6",
          LookAt = {
            [1] = "100001:n(200002)"
          },
          NextDialogue = 10100808,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200002},AnimationId{"Agree"},Duration{1.2}},
PlayAnimation{ActorId{200002},AnimationId{"Confident_Start"},Duration{4.8}},
PlayAnimation{ActorId{200002},AnimationId{"Talk01_Start"},Duration{3.6}},
PlayAnimation{ActorId{200002},AnimationId{"Shock_Start"},Duration{1}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Yep! Just yesterday, in a pitch-black windy evening, a fiend cloaked in white light infiltrated Camilla's tavern and threatened her—",
          VoiceName = "voice/$Locale$/story/1002/101008/19494BA6"
        },
        [10100808] = {
          Camera = "-487.870117,-383.416016,136.682617,0.001181,-3.199342,37.251434,50.0,695.608887,false,Manual,2.8",
          Content = "嗯？",
          DialogueId = 10100808,
          FacialId = {
            [1] = "200002:Happy02"
          },
          GUID = "19494BD0",
          NextDialogue = 10100809,
          Scripts = [[
PARA{
LookAt{_delay{0.2},LookAtDescription{"200003:n(200002)"}},
LookAt{_delay{1.2},LookAtDescription{"200002:n(200003)"}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "Hmm?",
          VoiceName = "voice/$Locale$/story/1002/101008/19494BD0"
        },
        [10100809] = {
          Camera = "-226.311523,-113.507812,192.955566,0.001224,-17.302214,34.000774,50.0,381.876587,false,Manual,6.0",
          Content = "好吧……有个穿白斗篷的家伙和卡米拉谈了一笔交易，要她找到你，带你进城。",
          DialogueId = 10100809,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200002:None"
          },
          GUID = "19494BFA",
          LookAt = {
            [1] = "200003:n(200002)",
            [2] = "200002:n(200003)"
          },
          NextDialogue = 10100810,
          RelatedWikiId = {
            [1] = 204002
          },
          Scripts = [[
