PlayAnimation{_delay{2},ActorId{200002},AnimationId{"Shock_End"},Duration{1.8}}
},
PlayAnimation{ActorId{200002},AnimationId{"Explain02_Start"},Duration{4.2}},
PlayAnimation{ActorId{200002},AnimationId{"Explain02_End"},Duration{0.5}},
PlayAnimation{ActorId{200002},AnimationId{"Explain01_Start"},Duration{0.5}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Fine... a hooded man in a white cloak struck a deal with Camilla to find you and bring you into town.",
          VoiceName = "voice/$Locale$/story/1002/101008/19494BFA"
        },
        [10100810] = {
          Camera = "311.154297,29.604004,51.351074,0.001201,7.799625,177.456207,40.0,405.292908,false,Manual,5.0",
          Content = "你还记得那个人的长相吗？",
          DialogueId = 10100810,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "19494C24",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200003:n(100001)",
            [3] = "200002:n(100001)"
          },
          NextDialogue = 10100811,
          SpeakNpcId = 100001,
          Subtitle = "Do you remember what this man looked like?",
          TalkActionId = {
            [1] = "100001:Angry01_Start",
            [2] = "200003:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101008/19494C24"
        },
        [10100811] = {
          Camera = "-196.237305,-18.549316,146.658691,0.001187,-2.999962,0.843019,35.000008,264.133331,false,Manual,6.0",
          Content = "他裹得严严实实，神秘得很——你也不知道？",
          DialogueId = 10100811,
          GUID = "19494C4E",
          LookAt = {
            [1] = "100001:n(200003)"
          },
          NextDialogue = 10100812,
          Scripts = [[
SEQ{
PlayAnimation{_delay{1.5},ActorId{200003},AnimationId{"Talk03_End"},Duration{1.5}},
PlayAnimation{ActorId{200003},AnimationId{"Talk01_Start"},Duration{1}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "He was covered head to toe, quite a mysterious figure — you don't know him either?",
          TalkActionId = {
            [1] = "100001:Angry01_End",
            [2] = "200002:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101008/19494C4E"
        },
        [10100812] = {
          Camera = "83.771484,24.930664,132.914062,0.001205,-0.600285,-172.544907,35.0,163.694717,false,Manual,5.0",
          Content = "我没有印象。",
          DialogueId = 10100812,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "19494C78",
          NextDialogue = 10100813,
          Scripts = "PlayAnimation{_delay{1.5},ActorId{100001},AnimationId{\"DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 100001,
          Subtitle = "I have no clue.",
          TalkActionId = {
            [1] = "200003:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101008/19494C78"
        },
        [10100813] = {
          Camera = "-495.370117,-373.561523,136.682617,0.001181,-3.199342,37.251434,50.0,754.408386,false,Manual,4.0",
          Content = "真是稀奇。不知哪儿冒出来的大慈善家花一笔巨款雇人救一个陌生人，却不愿露面，也没有说救了你之后要做什么。",
          DialogueId = 10100813,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "-487.870117,-383.416016,136.682617,0.001181,-3.199342,37.251339,50.0,793.406921,false,DoNotOverride,4.0",
          GUID = "19494CA2",
          LookAt = {
            [1] = "200002:n(200003)"
          },
          NextDialogue = 10100814,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200003},AnimationId{"Disagree"},Duration{2}},
PlayAnimation{ActorId{200003},AnimationId{"Talk03_Start"},Duration{1}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "How curious. Some enigmatic benefactor from nowhere is willing to spend a fortune to save a stranger but doesn't want to reveal his identity or intention.",
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/story/1002/101008/19494CA2"
        },
        [10100814] = {
          Content = "会有人将你从苦涩的海水中打捞出来，带向一片苦寒的荒原，命运将在那里降下真正的淬炼。",
          DialogueId = 10100814,
          ExStoryInfo = "EXPlayer",
          GUID = "19494CA3",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10100814.T_Story_Recall_10100814'",
          NextDialogue = 10100815,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Fate has arranged for a pair of hands to pluck you from the brinish water and guide you to the next desolate land. There, you shall awaken anew.",
          TalkActionId = {
            [1] = "200002:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/100127/1910D56B"
        },
        [10100815] = {
          Camera = "46.295898,-14.689941,134.97168,0.001182,0.698551,169.273804,35.000008,134.419968,false,Manual,4.0",
          Content = "（……是梦中的那个人派人救了我吗？但是，送我来这里，究竟是为什么？）",
          DialogueId = 10100815,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "19494CF6",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          NextDialogue = 101008062,
          Scripts = [[
PARA{
PlayAnimation{_delay{0.5},ActorId{100001},AnimationId{"Sigh_Start"},Duration{1}},
PlayAnimation{_delay{4.5},ActorId{100001},AnimationId{"Sigh_End"},Duration{1}}
}]],
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(...Could it have been the person from my dreams who orchestrated my rescue? But to what end have I been brought here?)",
          TalkActionId = {
            [1] = "200003:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101008/19494CF6"
        },
        [10100816] = {
          Camera = "-114.868164,-51.003906,147.164062,0.00115,-1.499991,2.259865,35.000008,204.629532,false,Manual,6.0",
          Content = "白刚才告诉过你吧？那个地方远在几千里之外。你的话……去南方的列车票价不菲，加上旅费，少说也得攒上几千银币吧。",
          DialogueId = 10100816,
          FinalCamera = "-114.868164,-51.003906,150.164062,0.00115,-1.499991,2.259865,35.000008,204.629532,false,Manual,6.0",
          GUID = "19494D20",
          NextDialogue = 10100817,
          Scripts = [[
SEQ{
PlayAnimation{_delay{3.6},ActorId{200003},AnimationId{"Talk02_End"},Duration{5.9}},
PlayAnimation{ActorId{200003},AnimationId{"Think_Start"},Duration{1}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "Snow just told you, didn't she? It's leagues away. The southbound train comes with a hefty fare, not to mention the travel expenses... You'd need at least a few thousand silver coins.",
          TalkActionId = {
            [1] = "200003:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101008/19494D20"
        },
        [10100817] = {
          Camera = "-2534.498047,882.487305,128.315918,0.001157,0.000109,-69.548653,30.0,1183.44812,false,Manual,2.8",
          CameraBlendCurve = "easeInOutQuad",
          Content = "就算你宁愿一路乞讨穿越海伯利亚大平原，也要想方设法应付沿途各城镇的盘查。下一次，可就不一定这么好运——",
          DialogueId = 10100817,
          FinalCamera = "-2516.917969,889.322266,133.45166,0.001157,0.400112,-68.748718,30.0,1183.44812,false,Manual,2.8",
          GUID = "19494D4A",
          NextDialogue = 10100818,
          SpeakNpcId = 200003,
          Subtitle = "Even if you'd rather beg your way across the Hyperborean plains, you'd still need to somehow deal with the inspections in every town you pass. Next time, you might not be so lucky—",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101008/19494D4A"
        },
        [10100818] = {
          Camera = "-196.237305,-18.549316,146.658691,0.001187,-2.999962,0.843019,35.000008,264.133331,false,Manual,6.0",
          Content = "说不定，你就要在不知道哪个城市的牢狱里度过一大把好时光了。",
          DialogueId = 10100818,
          GUID = "19494D74",
          NextDialogue = 10100819,
          SpeakNpcId = 200003,
          Subtitle = "For all you know, you might well find yourself languishing in a prison of some city.",
          VoiceName = "voice/$Locale$/story/1002/101008/19494D74"
        },
        [10100819] = {
          Camera = "-3.067383,-50.891113,144.484375,0.00118,-1.90149,144.27504,35.000008,98.568146,false,Manual,2.8",
          Content = "（嗯……果然，回去并不是件容易事。要先想办法准备一笔钱，以及，刚才那位士兵提到的“通行证”。）",
          DialogueId = 10100819,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "19494D9E",
          NextDialogue = 101008062,
          Scripts = "PlayAnimation{_delay{1.5},ActorId{100001},AnimationId{\"DisagreeHead\"},Duration{1}}",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Hmm... right, going all the way back is no picnic. I must first get some money and, as that soldier mentioned, a \"travel permit.\")",
          TalkActionId = {
            [1] = "200003:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101008/19494D9E"
        },
        [10100820] = {
          Camera = "-196.237305,-18.549316,146.658691,0.001187,-2.999962,0.843019,35.000008,264.133331,false,Manual,6.0",
          Content = "十三军团直属于皇帝陛下，每个行省都有他们的踪迹。西比尔可能在海伯利亚任何一座要塞现身。",
          DialogueId = 10100820,
          GUID = "19494DC8",
          NextDialogue = 10100821,
          RelatedWikiId = {
            [1] = 101005
          },
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200003},AnimationId{"Talk02_Start"},Duration{2.3}},
PlayAnimation{ActorId{200003},AnimationId{"Talk02_End"},Duration{4.1}},
PlayAnimation{ActorId{200003},AnimationId{"Talk03_Start"},Duration{1}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "The 13th Legion is directly under the Emperor's command, with bases in every province, so Sibylle could be in any part of Hyperborea.",
          VoiceName = "voice/$Locale$/story/1002/101008/19494DC8"
        },
        [10100821] = {
          Camera = "-389.902344,-245.504395,22.587891,0.001195,10.30069,31.257433,35.000015,178.504257,false,DoNotOverride,4.0",
          Content = "而其中可能性最大的是，皇都迪斯玛尼亚那座巨大钢铁堡垒。全帝国最训练有素的士兵、一切你想象得到和想象不到的武器，都汇聚在那里。",
          DialogueId = 10100821,
          FinalCamera = "-373.101562,-274.45459,22.588379,0.001195,10.30069,35.05777,35.000015,178.504257,false,DoNotOverride,4.0",
          GUID = "19494DF2",
          NextDialogue = 10100822,
          RelatedWikiId = {
            [1] = 408004
          },
          Scripts = "PlayAnimation{_delay{2.2},ActorId{200003},AnimationId{\"Think_Start\"},Duration{1}}",
          SpeakNpcId = 200003,
          Subtitle = "The most likely place, though, is the colossal steel bastion in the imperial capital, aka Dismania, where you can find the Empire's finest soldiers and an arsenal of every type of conceivable and inconceivable armaments.",
          TalkActionId = {
            [1] = "100001:Sigh_End",
            [2] = "200003:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101008/19494DF2"
        },
        [10100822] = {
          Camera = "-2070.686523,-3294.441406,2337.578125,0.001209,26.398127,22.05953,11.0,10000.0,false,Manual,1.2",
          CameraBlendCurve = "easeInQuad",
          Content = "海伯利亚是一座轰鸣的战车，那里就是它的引擎，它的炉芯——如果你想去试试，那就尽管去吧。我见过很多疯子，你不是第一个，也不是最后一个。",
          DialogueId = 10100822,
          FinalCamera = "-1849.558594,-2787.050781,2533.88208,0.001209,26.398127,22.05953,12.0,10000.0,false,Manual,1.2",
          GUID = "19494E1C",
          NextDialogue = 10100823,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/talk_engine_roaring\"},EventKey{\"talk_engine_roaring\"},PlayAs2D{false}}",
          SpeakNpcId = 200003,
          Subtitle = "Hyperborea is a roaring chariot, and that place is its engine, its fiery core — if you want to give it a try, go ahead. You're neither the first nor the last madcap I've seen.",
          TalkActionId = {
            [1] = "200003:Think_End"
          },
          ToFinalCameraBlendTime = 17,
          VoiceName = "voice/$Locale$/story/1002/101008/19494E1C"
        },
        [10100823] = {
          Camera = "13.978516,-54.12793,140.199707,0.001178,0.098546,147.47438,35.000011,112.923691,false,Manual,2.8",
          Content = "（所以说，我要面对的并非只是西比尔，而是她背后的帝国。有胜算吗？至少现在没有……需要想想其他办法。）",
          DialogueId = 10100823,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Think01"
          },
