PlayAnimation{ActorId{200002},AnimationId{"Confident_Start"},Duration{3.6}},
PlayAnimation{ActorId{200002},AnimationId{"SpecialConfident_Start"},Duration{2.5}},
PlayAnimation{ActorId{200002},AnimationId{"Explain01_Start"},Duration{1}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Umm... Alright! Seeing you so lonely and lost, I'll take you to this Hypnos' House to see what's what!",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101008/19494FC0"
        },
        [10100901] = {
          Content = "你刚才说的“鬼宅”，是什么意思？",
          DialogueId = 10100901,
          ExStoryInfo = "Player",
          GUID = "19495B12",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10100902,
          SpeakNpcId = 100001,
          Subtitle = "What exactly did you mean by \"haunted house\"?",
          VoiceName = "voice/$Locale$/story/1002/101009/19495B12"
        },
        [10100902] = {
          Content = "是水仙平原的客人说的，时不时就会有人抱怨——",
          DialogueId = 10100902,
          GUID = "19495B3C",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10100903,
          SpeakNpcId = 200002,
          Subtitle = "I heard about it from the guests at The Asphodel. There's always someone complaining—",
          VoiceName = "voice/$Locale$/story/1002/101009/19495B3C"
        },
        [10100903] = {
          Content = "比如说明明那么大的旅馆，但是门每天都关得紧紧的，所有去投宿的外乡旅客都被赶走……",
          DialogueId = 10100903,
          GUID = "19495B66",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10100904,
          SpeakNpcId = 200002,
          Subtitle = "Like, even though it's such a big inn, the doors are always shut tight every day, turning away any travellers from outside the town...",
          VoiceName = "voice/$Locale$/story/1002/101009/19495B66"
        },
        [10100904] = {
          Content = "比如说旅馆的住客从不出门，里面还偶尔会飘出奇奇怪怪、说不上来的味道……",
          DialogueId = 10100904,
          GUID = "19495B90",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10100905,
          SpeakNpcId = 200002,
          Subtitle = "Or how the lodgers seem to never ever leave, and sometimes, there's this really weird smell drifting from the inside of the house...",
          VoiceName = "voice/$Locale$/story/1002/101009/19495B90"
        },
        [10100905] = {
          Content = "比如说那个店主的脸比泪湖的水还要冰，好像他开的不是旅馆，是棺材店！",
          DialogueId = 10100905,
          GUID = "19495BBA",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10100906,
          SpeakNpcId = 200002,
          Subtitle = "And how the innkeeper's face is colder than the waters of Lamenting Lake... It's as if he's not running an inn, but a coffin shop!",
          VoiceName = "voice/$Locale$/story/1002/101009/19495BBA"
        },
        [10100906] = {
          Content = "听起来也算不上太坏。我还以为里面塞满了秽兽和西比尔。",
          DialogueId = 10100906,
          ExStoryInfo = "Player",
          GUID = "19495BE4",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10100907,
          SpeakNpcId = 100001,
          Subtitle = "Oh, it doesn't sound too bad. I thought it was crammed with Filthoids and Sibylles.",
          VoiceName = "voice/$Locale$/story/1002/101009/19495BE4"
        },
        [10100907] = {
          Content = "但是，既然他们不接待外乡人，那我恐怕也……",
          DialogueId = 10100907,
          ExStoryInfo = "Player",
          GUID = "19495C0E",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10100908,
          SpeakNpcId = 100001,
          Subtitle = "But, if they don't welcome outsiders, I doubt if I can...",
          VoiceName = "voice/$Locale$/story/1002/101009/19495C0E"
        },
        [10100908] = {
          Content = "不过，看起来卡米拉·斯卡雷特女士在这里颇有些声望。嗯……或许可以借一下她的名头。",
          DialogueId = 10100908,
          ExStoryInfo = "Player",
          GUID = "19495C38",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10100909,
          SpeakNpcId = 100001,
          Subtitle = "Still, it seems Ms Camilla Scarlet holds some sway here. Hmm... perhaps I could leverage her influence a little bit.",
          VoiceName = "voice/$Locale$/story/1002/101009/19495C38"
        },
        [10100909] = {
          Content = "不用不用，白的名头借给你用就好了。从今以后你就是我关照的人了，小仆从！",
          DialogueId = 10100909,
          GUID = "19495C62",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10100910,
          SpeakNpcId = 200002,
          Subtitle = "Nah, you can use Snow's name. From now on, you're under my wing, my little minion!",
          VoiceName = "voice/$Locale$/story/1002/101009/19495C62"
        },
        [10100910] = {
          Content = "谢谢你，但是，“仆从”是什么？",
          DialogueId = 10100910,
          ExStoryInfo = "Player",
          GUID = "19495C8C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10100911,
          SpeakNpcId = 100001,
          Subtitle = "Thank you, but what's a \"minion\"?",
          VoiceName = "voice/$Locale$/story/1002/101009/19495C8C"
        },
        [10100911] = {
          Content = "是流行小说中受魔王大人眷顾的跟班！",
          DialogueId = 10100911,
          GUID = "19495CB6",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10100912,
          SpeakNpcId = 200002,
          Subtitle = "It's what they call someone in those stories who's the favourite lackey of the awesome Demon King!",
          VoiceName = "voice/$Locale$/story/1002/101009/19495CB6"
        },
        [10100912] = {
          Content = "世界上有那么多皎皎之民，为什么偏偏是白长了角呢？显然我命中注定会成为魔王大人！",
          DialogueId = 10100912,
          GUID = "19495CE0",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10100913,
          SpeakNpcId = 200002,
          Subtitle = "Among all the Luno in the world, why else would little ol' Snow have these nifty horns, if not to be a Demon King one day? It's totally my destiny!",
          VoiceName = "voice/$Locale$/story/1002/101009/19495CE0"
        },
        [10100913] = {
          Content = "而我是听到了神秘声音的指引找到了你，所以你一定是上天安排给我的仆从！",
          DialogueId = 10100913,
          ExStoryInfo = "Player",
          GUID = "19495D0A",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10100914,
          SpeakNpcId = 200002,
          Subtitle = "And it was those mysterious voices that brought me to you, so you must be the minion sent by destiny!",
          VoiceName = "voice/$Locale$/story/1002/101009/19495D0A"
        },
        [10100914] = {
          Content = "所以所以，我决定了——要以我的智慧，指引你走上正确的道路！",
          DialogueId = 10100914,
          GUID = "19495D34",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10100915,
          SpeakNpcId = 200002,
          Subtitle = "Soooo~ I've made up my mind — with all my wisdom, I'm gonna guide you down the right path!",
          VoiceName = "voice/$Locale$/story/1002/101009/19495D34"
        },
        [10100915] = {
          Content = "…………",
          DialogueId = 10100915,
          ExStoryInfo = "Player",
          GUID = "19495D5E",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10100916,
          SpeakNpcId = 100001,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1002/101009/19495D5E"
        },
        [10100916] = {
          Content = "（“<H>皎皎之民</>大多对人抱有亲近感”……书本没有骗我。）",
          DialogueId = 10100916,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          GUID = "19495D88",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10100917,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(\"The Lunarians are generally friendly towards humans\"... the books weren't lying.)",
          VoiceName = "voice/$Locale$/story/1002/101009/19495D88"
        },
        [10100917] = {
          Content = "那间旅馆就在北边！不要发呆啦，快~跟~上！",
          DialogueId = 10100917,
          GUID = "19495DB2",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10100918,
          SpeakNpcId = 200002,
          Subtitle = "The inn's just up north! C'mon, fol—low—me!",
          VoiceName = "voice/$Locale$/story/1002/101009/19495DB2"
        },
        [10100918] = {
          Content = "（……就、就是这位似乎有点亲近过头了。）",
          DialogueId = 10100918,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          GUID = "19495DDC",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(...It's just that this one seems a tad too friendly.)",
          VoiceName = "voice/$Locale$/story/1002/101009/19495DDC"
        },
        [10101001] = {
          Content = "到啦！站在这儿等着！",
          DialogueId = 10101001,
          GUID = "19496B7A",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Here we are! You wait here!",
