        },
        [10102104] = {
          Content = "啊，找到了，给您！",
          DialogueId = 10102104,
          GUID = "194A2070",
          NextDialogue = 10102105,
          SpeakNpcId = 200009,
          Subtitle = "Ah, here it is!",
          TalkActionId = {
            [1] = "200009:Give"
