          Content = "哦……？哦，照片上……是你这老东西？",
          DialogueId = 10102105,
          FinalCamera = "-25.373291,-199.524673,190.776367,-5.000002,-19.596331,152.183594,35.000008,145.457977,false,Manual,3.557573",
          GUID = "194A209A",
          NextDialogue = 10102106,
          SpeakNpcId = 200008,
          Subtitle = "Huh...? Oh, is this you in the photo... you old codger?",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101021/194A209A"
        },
        [10102106] = {
          Content = "是，长官……",
          DialogueId = 10102106,
          GUID = "194A20C4",
          NextDialogue = 10102107,
          SpeakNpcId = 200009,
          Subtitle = "Yes, sir...",
          TalkActionId = {
            [1] = "200009:Agree"
          },
          VoiceName = "voice/$Locale$/story/1002/101021/194A20C4"
        },
        [10102107] = {
          Camera = "-324.333984,818.858521,893.822021,-5.000005,-35.792892,-76.391212,40.168049,228.342102,false,DoNotOverride,6.685584",
          CameraBlendCurve = "easeInOutQuad",
          Content = "我怎么看怎么像条狗呢，哈哈，哈哈哈哈哈！",
          DialogueId = 10102107,
          FinalCamera = "-324.333984,818.858521,836.514404,-5.000005,-35.792892,-76.391212,40.168049,228.342102,false,DoNotOverride,6.685584",
          GUID = "194A20EE",
          NextDialogue = 10102108,
          SpeakNpcId = 200008,
          Subtitle = "How come it looks more like a mongrel to me, haha, hahaha!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101021/194A20EE"
        },
        [10102108] = {
          Camera = "-119.224854,-52.406082,82.172852,0.000047,14.206512,-47.991478,45.857548,255.974915,false,Manual,2.325034",
          Content = "哎，要不你学几声狗叫，给咱们听听？",
          DialogueId = 10102108,
          GUID = "194A2118",
          SpeakNpcId = 200010,
          Subtitle = "Oi, why don't you give us a bark, huh?",
          VoiceName = "voice/$Locale$/story/1002/101021/194A2118"
        },
        [10102201] = {
          Content = "不，不行……",
          DialogueId = 10102201,
          Duration = 2,
          GUID = "194A305A",
          SpeakNpcId = 200006,
          Subtitle = "Don't...",
          VoiceName = "voice/$Locale$/story/1002/101022/194A305A"
        },
        [10102202] = {
          Content = "嗯？看什么看，小崽子。",
          DialogueId = 10102202,
          Duration = 1.5,
          GUID = "194A3084",
          SpeakNpcName = "UI_Npc_Name_Man_5",
          Subtitle = "What are you looking at, you little twerp?",
          VoiceName = "voice/$Locale$/story/1002/101022/194A3084"
        },
        [10102203] = {
          Content = "你不会给我惹什么麻烦的——对吧？",
          DialogueId = 10102203,
          Duration = 4,
          GUID = "194A30AE",
          SpeakNpcId = 200003,
          Subtitle = "Stay out of trouble for me, alright?",
          VoiceName = "voice/$Locale$/story/1002/101022/194A30AE"
        },
        [10102204] = {
          Content = "父、父亲……",
          DialogueId = 10102204,
          Duration = 1.8,
          GUID = "194A3102",
          SpeakNpcName = "UI_Npc_Name_Man_13",
          Subtitle = "Father...",
          VoiceName = "voice/$Locale$/story/1002/101022/194A3102"
        },
        [10102205] = {
          Content = "你们这群混蛋！",
          DialogueId = 10102205,
          Duration = 1.5,
          GUID = "194A312C",
          SpeakNpcName = "UI_Npc_Name_Man_13",
          Subtitle = "You bastards!",
          VoiceName = "voice/$Locale$/story/1002/101022/194A312C"
        },
        [10102206] = {
          Content = "你想干什么？！",
          DialogueId = 10102206,
          Duration = 1,
          GUID = "194A3156",
          SpeakNpcName = "UI_Npc_Name_Man_5",
          Subtitle = "What do you think you're doing?!",
          VoiceName = "voice/$Locale$/story/1002/101022/194A3156"
        },
        [10102401] = {
          Content = "……快走。",
          DialogueId = 10102401,
          GUID = "194A40C2",
          IsBlack = 1,
          NextDialogue = 10102402,
          SpeakNpcId = 200006,
          Subtitle = "...Let's leave.",
          VoiceName = "voice/$Locale$/story/1002/101023/194A40C2"
        },
        [10102402] = {
          Camera = "251.952225,-256.3125,116.767578,0.000169,-3.598622,135.988266,30.0,441.320343,false,Manual,3.0",
          CameraBlendCurve = "easeOutQuad",
          Content = "有一件重要的事，我不知道你是否清楚。",
          DialogueId = 10102402,
          FacialId = {
            [1] = "200006:Unhappy01"
          },
          FinalCamera = "238.238632,-270.507812,116.767578,0.000169,-3.598622,135.988266,30.0,441.320343,false,Manual,3.0",
          GUID = "194A512A",
          LookAt = {
            [1] = "200006:n(100001)",
            [2] = "100001:n(200006)",
            [3] = "200002:n(200006)"
          },
          NextDialogue = 10102403,
          RelatedWikiId = {
            [1] = 101003,
            [2] = 408003,
            [3] = 201007,
            [4] = 201005
          },
          SpeakNpcId = 200006,
          Subtitle = "There's something important you should know.",
          TalkActionId = {
            [1] = "200006:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101024/194A512A"
        },
        [10102403] = {
          Camera = "125.824219,-225.558105,135.956543,0.000172,-1.798553,120.789757,50.0,356.306458,false,Manual,6.0",
          Content = "如果你们是从海伯利亚以外的地方来的，请记住，千万不要触怒“<H>索拉之民</>”。",
          DialogueId = 10102403,
          GUID = "194A5154",
          NextDialogue = 10102404,
          RelatedWikiId = {
            [1] = 303007
          },
          Scripts = [[
