          SpeakNpcId = 200003,
          Subtitle = "Oh, it's you. And you're... the little girl from the Frey's? Psyche, isn't it?",
          ToFinalCameraBlendTime = 3.5,
          VoiceName = "voice/$Locale$/story/1002/101026/194A71FA"
        },
        [10102602] = {
          Content = "是的，卡米拉女士。我现在借住在修普诺斯之家。",
          DialogueId = 10102602,
          FacialId = {
            [1] = "200006:Happy02"
