}]],
          SpeakNpcId = 200006,
          Subtitle = "...I'm here with a friend. {性别:He|She} is looking for a job and wants to become a Phoxhunter.",
          TalkActionId = {
            [1] = "200006:Talk02_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101026/194A7278"
        },
        [10102605] = {
          Camera = "-333.986206,-132.207031,145.634766,0.001253,-3.999936,19.037998,50.000008,264.189575,false,Manual,4.109556",
          Content = "狩月人！那你们是找对地方了，正巧，现在这里就有一份委托——",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10102605,
          FacialId = {
            [1] = "200011:Happy01"
          },
          GUID = "194A72A2",
          LookAt = {
