}]],
          SpeakNpcId = 200011,
          SpeakNpcName = "UI_Npc_Name_NervouseMaer",
          Subtitle = "Then you came to the right place! There's a commission for Phoxhunters right now—",
          VoiceName = "voice/$Locale$/story/1002/101026/194A72A2"
        },
        [10102606] = {
          Camera = "-333.986206,-132.207031,145.634766,0.001253,-3.999936,19.037998,50.000008,264.189575,false,Manual,4.109556",
          CameraBlendCurve = "easeInOutQuad",
          Content = "先别插嘴，玛尔洁。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10102606,
          Duration = 1,
          FinalCamera = "-328.773987,-167.959961,134.214844,0.001226,0.0,28.499939,50.0,499.398407,false,Manual,10.0",
          GUID = "194A72CC",
          LookAt = {
