          },
          SpeakNpcId = 200003,
          Subtitle = "Not now, Margie.",
          TalkActionId = {
            [1] = "200006:Talk02_End"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101026/194A72CC"
