          CameraBlendCurve = "easeInQuad",
          Content = "别过来！",
          DialogueId = 10103406,
          FinalCamera = "-149.193359,55.460938,152.14772,0.000171,-7.199832,-9.000023,30.0,119.391449,false,Manual,2.291237",
          GUID = "194AF564",
