}]],
          SpeakNpcId = 200003,
          Subtitle = "Are you playing dumb or you really don't know? If you're not pretending, I almost envy such ignorance.",
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1002/101034/194AF564"
        },
        [10103407] = {
          Camera = "246.730469,-195.367188,140.170639,0.000167,-3.39987,126.987076,35.0,388.101501,false,Manual,5.0",
          Content = "他很危险，比你们想象中更危险。",
