          SpeakNpcId = 200003,
          Subtitle = "I don't quite follow.",
          VoiceName = "voice/$Locale$/story/1002/101034/194AF566"
        },
        [10103409] = {
          Camera = "137.916016,-192.882812,140.053055,0.000187,1.800206,88.388634,35.000008,417.684204,false,DoNotOverride,5.0",
          Content = "如果你依旧决意成为狩月人，就回“水仙平原”找我吧。",
          DialogueId = 10103409,
          GUID = "194AF567",
          NextDialogue = 10103410,
          Scripts = "LookAt{LookAtDescription{\"200003:n(100001)\"}}",
          SpeakNpcId = 200003,
          Subtitle = "I'll hand the money bag over to the client. If you're still set on becoming a Phoxhunter, find me in The Asphodel.",
          TurnTo = {
            [1] = "200014:n(200053)"
          },
          VoiceName = "voice/$Locale$/story/1002/101034/194AF567"
        },
        [10103410] = {
          Camera = "-277.953125,-284.5,540.433228,-0.000672,-57.389881,62.197701,35.000019,417.684204,false,DoNotOverride,5.0",
          Content = "放了我吧！求求你——",
