}]],
          SpeakNpcId = 200002,
          Subtitle = "Snow knows the way! But... it's nice to have some company, especially when we're heading out of town.",
          TalkActionId = {
            [1] = "200006:Explain02_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101044/194B99C8"
        },
        [10104405] = {
          Camera = "-80.464844,-28.455566,146.255371,0.000019,-2.199915,8.608652,35.000008,213.527512,false,Manual,4.0",
          Content = "是啊，外乡人在城外很容易迷路的。我看到你接了恩里克叔叔……我们的委托，所以我想我还是帮下忙为好。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104405,
          FacialId = {
            [1] = "200006:Smile02"
          },
          GUID = "194B99F2",
          LookAt = {
            [1] = "200006:n(100001)"
          },
          NextOptions = {
            [1] = 101044051,
            [2] = 101044052
          },
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200006},AnimationId{"AgreeHead"},Duration{2}},
PlayAnimation{ActorId{200006},AnimationId{"SpecialThink_Start"},Duration{2}}
}]],
          SpeakNpcId = 200006,
          Subtitle = "Yeah, outsiders can easily lose their way out there. I saw you accepted Mr Henrik's... our request, so I thought I should help out.",
          VoiceName = "voice/$Locale$/story/1002/101044/194B99F2"
        },
        [10104406] = {
          Camera = "618.545898,-425.736328,165.672852,0.000053,-5.400419,148.00415,25.0,705.171997,false,DoNotOverride,5.0",
          CameraBlendCurve = "easeInQuad",
          Content = "刚好，我也想出来走走。我们出发吧？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104406,
          FacialId = {
            [1] = "200006:Smile01"
          },
          FinalCamera = "608.34375,-442.196289,165.672852,0.000051,-5.400419,149.999954,25.000002,715.606018,false,DoNotOverride,5.0",
          GUID = "194B9A1C",
          SpeakNpcId = 200006,
          Subtitle = "Actually, I was looking forward to a little walk myself, too. Shall we get going?",
          TalkActionId = {
            [1] = "200006:SpecialThink_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101044/194B9A1C"
        },
        [10104501] = {
          Content = "呼……好久没来城外了。",
          DialogueId = 10104501,
          Duration = 3,
          GUID = "194BA9B2",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104502,
          SpeakNpcId = 200006,
          Subtitle = "Whoo... It's been a while since I've stepped out of the city.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BA9B2"
        },
        [10104502] = {
          Content = "落满雪的针叶林，望不到边的冰湖……高个子山峰被天空按住了脑袋……很喜欢。",
          DialogueId = 10104502,
          Duration = 3,
          GUID = "194BA9DC",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10104503,
          SpeakNpcId = 200006,
          Subtitle = "The snow-draped conifers, the boundless lake... mountains with their peaks in the clouds... I love all this.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BA9DC"
        },
        [10104503] = {
          Content = "白还是更喜欢城里面！如果郊外没有那些到处巡逻的秽兽就好啦。",
          DialogueId = 10104503,
          Duration = 3,
          GUID = "194BAA06",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10104504,
          SpeakNpcId = 200002,
          Subtitle = "Snow's more a city soul! If only the outskirts were free of those roaming Filthoids.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAA06"
        },
        [10104504] = {
          Content = "里面更安全些。但是，我喜欢这里的……空气。",
          DialogueId = 10104504,
          Duration = 3,
          GUID = "194BAA30",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104505,
          SpeakNpcId = 200006,
          Subtitle = "It's safer inside, indeed. But there's something about the... air out here.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAA30"
        },
        [10104505] = {
          Content = "有区别吗？我闻起来都差不多耶……",
          DialogueId = 10104505,
          Duration = 3,
          GUID = "194BAA5A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10104506,
          SpeakNpcId = 200002,
          Subtitle = "Is there a difference? All smells the same to me...",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAA5A"
        },
        [10104506] = {
          Content = "嗯……冰湖城的空气总是带着腥味，带着哭声。",
          DialogueId = 10104506,
          Duration = 3,
          GUID = "194BAA84",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104507,
          SpeakNpcId = 200006,
          Subtitle = "Mmm... The air in Icelake is always tinged with a scent of blood and echoes of weeping.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAA84"
        },
        [10104507] = {
          Content = "而这里是森林的味道，浮冰的味道，还有驶向远方的汽笛。这里偶尔能看到雪白的鹿从林间窜出——",
          DialogueId = 10104507,
          Duration = 3,
          GUID = "194BAAAE",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104508,
          SpeakNpcId = 200006,
          Subtitle = "Out here, it's the scent of the forest and drifting ice, and the distant sound of steam whistles. Occasionally, you might catch a glimpse of snow-white deer darting through the trees—",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAAAE"
        },
        [10104508] = {
          Content = "而冰湖城街道的角落窜出来的，是小偷、强盗……或者呜咽的乞丐。",
          DialogueId = 10104508,
          Duration = 3,
          GUID = "194BAAD8",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10104509,
          SpeakNpcId = 200006,
          Subtitle = "While around Icelake's alleys, what darts out are thieves, bandits... or whimpering beggars.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAAD8"
        },
        [10104509] = {
          Content = "{nickname}，你呢？讲讲你的故乡吧！那座海岛是怎样的？",
          DialogueId = 10104509,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BAB02",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10104510,
          SpeakNpcId = 200006,
          Subtitle = "What about your hometown, ? Tell us about it! What's that island like?",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAB02"
        },
        [10104510] = {
          Content = "那里的“空气”是金色的砂砾，海岸的迷迭香……",
          DialogueId = 10104510,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BAB2C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104511,
          SpeakNpcId = 100001,
          Subtitle = "The \"air\" there is golden gravel and white rue flowers...",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAB2C"
        },
        [10104511] = {
          Content = "是深夜朦胧的海雾，是我和贝……和家人每天眺望的巨大天之树。",
          DialogueId = 10104511,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BAB56",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104512,
          SpeakNpcId = 100001,
          Subtitle = "It's misty sea fogs at midnight, and the massive Heaventree that Ber... my family and I used to gaze upon every day.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAB56"
        },
        [10104512] = {
          Content = "嗯……那如果你什么时候回去故乡，请代我向它们问候~",
          DialogueId = 10104512,
          Duration = 3,
          GUID = "194BAB80",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10104513,
          SpeakNpcId = 200006,
          Subtitle = "Mmm... if you ever make it back to your homeland, please send them my regards.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAB80"
        },
        [10104513] = {
          Content = "……唔唔，你们两个的话好难懂哦……",
          DialogueId = 10104513,
          Duration = 3,
          GUID = "194BABAA",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10104514,
          SpeakNpcId = 200002,
          Subtitle = "...Umm, you two are talking over my head...",
          VoiceName = "voice/$Locale$/story/1002/101045/194BABAA"
        },
        [10104514] = {
          Content = "等你再长大一些就明白啦。",
          DialogueId = 10104514,
          Duration = 3,
          GUID = "194BABD4",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104515,
          SpeakNpcId = 200006,
          Subtitle = "You'll get it when you're older.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BABD4"
        },
        [10104515] = {
          Content = "……不过，皎皎之民似乎是长不大的？",
          DialogueId = 10104515,
          Duration = 3,
          GUID = "194BABFE",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "...But then again, Lunos never really grow older, do you?",
          VoiceName = "voice/$Locale$/story/1002/101045/194BABFE"
        },
        [10104601] = {
          Camera = "-114.347656,1810.079102,572.782715,0.00006,-15.999997,-93.351616,25.0,482.997925,false,DoNotOverride,1.2",
          Content = "前面就是格雷姆废矿的入口了，你们一定要小心。",
          DialogueId = 10104601,
          FinalCamera = "-114.347656,1810.079102,540.30127,0.00006,-13.999989,-93.351624,25.0,482.997925,false,DoNotOverride,1.2",
          GUID = "194BBA1A",
          NextDialogue = 10104602,
          RelatedWikiId = {
            [1] = 408003,
            [2] = 405004,
            [3] = 201007,
            [4] = 201005,
            [5] = 301004,
            [6] = 406001
          },
          Scripts = [[
PARA{
SEQ{
MoveTo{ActorId{200006},TargetPoint{"P10104603"},MoveSpeed{50}},
TurnTo{_delay{0.5},TurnToDescription{"200006:p(180)"}}
