]],
          SpeakNpcId = 200006,
          Subtitle = "The entrance to Glevum Pit is up ahead. Please be extra careful.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101046/194BBA1A"
        },
        [10104602] = {
          Camera = "-4.705078,-275.623535,148.607422,0.000054,-3.999943,59.446644,35.000008,204.586716,false,Manual,7.37621",
          Content = "多谢，帮大忙了。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104602,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Smile02"
          },
          GUID = "194BBA44",
          NextDialogue = 10104603,
          Scripts = "PlayAnimation{_delay{1.2},ActorId{100001},AnimationId{\"Explain02_Start\"},Duration{1}}",
          SpeakNpcId = 100001,
          Subtitle = "Thanks, you've been a tremendous help.",
          TalkActionId = {
            [1] = "100001:AgreeHead",
            [2] = "200002:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101046/194BBA44"
        },
        [10104603] = {
          Content = "你们俩回去吧。接下来，我一个人就好。",
          DialogueId = 10104603,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "194BBA6E",
          NextDialogue = 10104604,
          Scripts = [[
PARA{
LookAt{LookAtDescription{"100001:n(200006)"}},
LookAt{_delay{0.5},LookAtDescription{"100001:n(200002)"}},
SEQ{
CameraMoveTo{_delay{0.8},TargetPosition{"-4.705078,-275.623535,148.607422,0.000054,-3.999943,59.446644,35.000008,204.586716,false,Manual,7.37621"},duration{0}},
CameraMoveTo{TargetPosition{"25.423828,-300.893066,153.260254,0.000032,-17.799767,100.245705,35.000008,204.586716,false,Manual,7.37621"},Blend{"easeInOutQuad"},duration{8}}
}
}]],
          SpeakNpcId = 100001,
          Subtitle = "You two should head back now. I can take it from here on my own.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101046/194BBA6E"
        },
        [10104604] = {
          Content = "……唔唔……不行！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104604,
          FacialId = {
            [1] = "200002:Confident01"
          },
          GUID = "194BBA98",
          NextDialogue = 10104605,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200002},AnimationId{"SpecialConfident_Start"},Duration{1}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "...Umm... no way!",
          VoiceName = "voice/$Locale$/story/1002/101046/194BBA98"
        },
        [10104605] = {
          Content = "魔王大人才不能临阵脱逃，让小仆从看扁。赛琪，你也跟上！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104605,
          FacialId = {
            [1] = "200002:Confident02"
          },
          GUID = "194BBAC2",
          LookAt = {
            [1] = "200006:n(200002)"
          },
          NextDialogue = 10104606,
          Scripts = [[
PARA{
LookAt{LookAtDescription{"200002:n(100001)"}},
PlayAnimation{_delay{4.8},ActorId{200002},AnimationId{"SpecialConfident_End"},Duration{1}},
PlayFacial{_delay{3},ActorId{200002},FacialId{"Unhappy02"}},
PlayFacial{_delay{5},ActorId{200002},FacialId{"Smile01"}},
LookAt{delay{8},LookAtDescription{"200002:n(200006)"}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "This Demon King can't just scarper from the battle and let the little minion think less of her. Psyche, you should also come with us!",
          VoiceName = "voice/$Locale$/story/1002/101046/194BBAC2"
        },
        [10104606] = {
          Camera = "-28.857422,-67.701172,111.056641,0.000052,9.799764,-64.964821,40.000031,141.186768,false,Manual,8.987392",
          CameraBlendCurve = "easeInQuad",
          Content = "我……？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104606,
          FacialId = {
            [1] = "200006:Shock01"
          },
          FinalCamera = "-16.4375,-94.304688,116.129395,0.000052,9.999759,-64.964989,40.000027,141.186768,false,Manual,8.987392",
          GUID = "194BBAEC",
          NextDialogue = 10104607,
          Scripts = "PlayAnimation{_delay{0.8},ActorId{200002},AnimationId{\"Explain01_End\"},Duration{0.1}}",
          SpeakNpcId = 200006,
          Subtitle = "Me...?",
          TalkActionId = {
            [1] = "200006:Think_Start"
          },
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1002/101046/194BBAEC"
        },
        [10104607] = {
          Camera = "1137.132812,2278.000977,1126.149414,0.000085,-21.600649,-103.932426,25.0,168.419693,false,DoNotOverride,5.0",
          Content = "对呀——和本魔王一起扫清这个怪物巢穴！赛琪，我猜你长这么大还没探险过吧？真可惜，你的人生一定是不完整的！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104607,
          FacialId = {
            [1] = "200002:Smile02"
          },
          FinalCamera = "1278.716797,2242.87793,1126.149414,0.000085,-21.600649,-103.932632,25.0,168.419693,false,DoNotOverride,5.0",
          GUID = "194BBB16",
          NextDialogue = 10104608,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{8.5},TargetPosition{"-44.302734,13.918945,72.365723,0.000042,12.799815,-75.562065,40.000027,260.261597,false,Manual,8.987392"},duration{0}},
CameraMoveTo{TargetPosition{"-31.933594,-11.705078,78.753418,0.000044,13.599787,-73.361298,40.000031,260.261597,false,Manual,8.987392"},duration{15}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Yup — come with the Demon King to clear out this monster's den!\nI bet you've never been on such an adventure, right? What a pity! Your life is certainly incomplete!",
          ToFinalCameraBlendTime = 17,
          VoiceName = "voice/$Locale$/story/1002/101046/194BBB16"
        },
        [10104608] = {
          Content = "……啊……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104608,
          Duration = 2,
          GUID = "194BBB40",
          LookAt = {
