          Content = "……好，算我一个。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104609,
          FacialId = {
            [1] = "200006:Smile01",
            [2] = "100001:Unhappy01"
          },
          GUID = "194BBB6A",
