PlayAnimation{ActorId{200021},AnimationId{"Talk01_Start"},Duration{1}},
},
}]],
          SpeakNpcId = 200021,
          Subtitle = "Wait a sec! I'm telling you, I'm really strong. No Phoxhunter around Icelake can best me. Ever heard of Chief Sibylle? I'm a match for her.",
          TalkActionId = {
            [1] = "200021:Talk02_End",
            [2] = "200006:Explain02_End"
          },
          ToFinalCameraBlendTime = 11.4,
          VoiceName = "voice/$Locale$/story/1002/101054/194C3FA6"
        },
        [10105416] = {
          Camera = "-79.367188,24.777344,166.03418,0.001305,-3.799443,-67.881172,52.000004,159.299744,false,Manual,10.0",
          Content = "你这人怎么比我还能吹牛啊！",
          DialogueId = 10105416,
          FacialId = {
