}]],
          SpeakNpcId = 200021,
          Subtitle = "Alright, alright, I was joking around, trying to lighten the mood, you know.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101054/194C3FD1"
        },
        [10105418] = {
          Camera = "-593.443359,672.542969,154.693359,0.001276,-4.200347,-48.992504,45.000011,464.479492,false,DoNotOverride,2.8",
          Content = "啊，狗耳朵角的坏东西又在耍人！",
          DialogueId = 10105418,
          GUID = "194C3FD2",
          LookAt = {
            [1] = "200021:n(200002)"
          },
          NextDialogue = 10105419,
          SpeakNpcId = 200002,
          Subtitle = "Hmph, this crafty Mutt Ears is trying to pull more tricks!",
          TalkActionId = {
            [1] = "200002:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101054/194C3FD2"
        },
        [10105419] = {
          Camera = "-130.791016,-352.570312,194.443359,0.00153,-12.09778,72.174423,35.000008,369.332916,false,DoNotOverride,8.0",
          Content = "你们几个……是你说了算吧？你们费这么大功夫找这绮晶，是为什么？",
          DialogueId = 10105419,
          ExStoryInfo = "Player",
          FinalCamera = "-144.837891,-348.058594,193.59375,0.00153,-12.09778,72.174423,35.000011,369.332916,false,DoNotOverride,8.0",
          GUID = "194C3FD3",
          LookAt = {
            [1] = "200002:n(200021)",
            [2] = "200021:n(200061)"
          },
          NextOptions = {
            [1] = 101054191
          },
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"200021:n(200006)"}},
LookAt{LookAtDescription{"200021:n(200061)"}},
PlayAnimation{ActorId{200021},AnimationId{"Talk02_Start"},Duration{1}},
}]],
          SpeakNpcId = 200021,
          Subtitle = "You call the shots in your little crew, right? Tell me — why did you guys go to all this trouble for this Crystallo?",
          TalkActionId = {
            [1] = "200002:Angry01_End"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/101054/194C3FD3"
        },
        [10105420] = {
          Camera = "-133.171875,185.023438,129.78125,0.001317,2.399193,-66.600601,45.000011,335.117126,false,Manual,8.0",
          Content = "果然。那就好办多了。虽然因为某些缘由，这枚绮晶我现在必须带走，但如果你的目的是赏金，我可以还你同样的数目。",
          DialogueId = 10105420,
          FinalCamera = "-136.361328,183.650391,129.78125,0.001317,2.199164,-65.600883,45.000011,335.117126,false,Manual,8.0",
          GUID = "194C4078",
          LookAt = {
            [1] = "200021:n(200061)"
          },
          NextDialogue = 10105421,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200021},AnimationId{"Talk02_End"},Duration{4}},
PlayAnimation{ActorId{200021},AnimationId{"Talk03_Start"},Duration{4}},
}]],
          SpeakNpcId = 200021,
          Subtitle = "That's false, everyone might hide away, but Outsider certainly can't.",
          TalkActionId = {
            [1] = "200021:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101054/194C4078"
        },
        [10105421] = {
          Camera = "-45.742188,-32.140625,140.254883,0.001334,-1.201505,104.203934,45.000023,134.353271,false,Manual,8.0",
          Content = "如果可以，我想请你听一听我的理由——今晚有空的话。",
          DialogueId = 10105421,
          FinalCamera = "-45.742188,-32.140625,140.254883,0.001334,-1.201505,104.003983,47.0,134.353271,false,Manual,8.0",
          GUID = "194C4079",
          NextOptions = {
            [1] = 101054211,
            [2] = 101054212
          },
          SpeakNpcId = 200021,
          Subtitle = "If you've got a moment, I'd like to explain — Are you free tonight?",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101054/194C4079"
        },
        [10105422] = {
          Camera = "-56.242188,-98.783203,85.512695,0.000091,-2.001614,108.598442,35.000011,124.888115,false,Manual,2.8",
          Content = "啊，这倒是很简单，有白当证人，他赖不掉！还有，卡米拉说过，奥特赛德家里有个凶神恶煞的亲戚，他怕得要命。",
          DialogueId = 10105422,
          FinalCamera = "-45.761719,-99.34375,85.657227,0.000093,-1.001545,114.597237,35.000015,124.888115,false,Manual,2.8",
          GUID = "194C4080",
          LookAt = {
            [1] = "200002:n(200021)",
            [2] = "200021:n(200002)"
          },
          NextDialogue = 10105423,
          Scripts = "PlayAnimation{_delay{6.5},ActorId{200002},AnimationId{\"Think_End\"},Duration{1}},\n",
          SpeakNpcId = 200002,
          Subtitle = "Oh, that's easy. With Snow as a witness, he won't be able to weasel out! Besides, Camilla mentioned he's got a terrifying relative at home he's really scared of.",
          TalkActionId = {
            [1] = "200002:Think_Start",
            [2] = [[

200021:Explain01_Start]]
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101054/194C4080"
        },
        [10105423] = {
          Camera = "-2.09375,155.646484,180.238281,0.000153,-33.400742,-131.193481,35.000008,188.968185,false,Manual,5.0",
          Content = "只要你用“去他家门口大声宣读罪状”来威胁奥特赛德，他就会向你拼命求饶的。",
          DialogueId = 10105423,
          FinalCamera = "-0.138672,153.929688,180.238281,0.000153,-33.400742,-131.193481,35.000008,188.968185,false,Manual,5.0",
          GUID = "194C4081",
          LookAt = {
            [1] = "200021:n(200021)"
          },
          NextDialogue = 10105424,
          Scripts = [[
SEQ{
TurnTo{TurnToDescription{"200002:n(200061)"}},
PlayAnimation{ActorId{200002},AnimationId{"SpecialConfident_Start"},Duration{1}},
}]],
          SpeakNpcId = 200002,
          Subtitle = "Just threaten to air his dirty laundry right on his doorstep, and he'll be begging for mercy in no time.",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/101054/194C4081"
        },
        [10105424] = {
          Camera = "-192.289062,-117.390625,137.607422,0.001453,5.699383,-0.388946,50.0,162.415543,false,DoNotOverride,1.2",
          Content = "……饶了我吧，我的魔王祖宗。",
          DialogueId = 10105424,
          FacialId = {
            [1] = "200021:Unhappy02"
          },
          GUID = "194C4082",
          NextDialogue = 10105425,
          Scripts = [[
