          },
          TurnTo = {
            [1] = "200002:n(200021)"
          },
          VoiceName = "voice/$Locale$/story/1002/101054/194C4082"
        },
        [10105425] = {
          Camera = "-1043.257812,-1602.347656,78.117188,0.001387,-0.599458,57.977047,50.0,1941.626953,false,Manual,10.0",
          Content = "“水仙平原”所有人都认识我奥特赛德，跑不了的。你们先回去吧，我还得留在这里忙上一阵。",
          DialogueId = 10105425,
          FacialId = {
            [1] = "200021:None"
          },
          FinalCamera = "-1020.1875,-1634.185547,78.268555,0.001395,-0.599458,57.97691,50.000008,1941.626953,false,Manual,10.0",
          GUID = "194C4083",
          LookAt = {
            [1] = "200021:n(200021)"
          },
          NextDialogue = 10105426,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200021},AnimationId{"Sigh_End"},Duration{1}},
TurnTo{TurnToDescription{"200021:p(180)"}},
}]],
          SpeakNpcId = 200021,
          Subtitle = "You can rest assured — everyone at The Asphodel knows me. Well, I've still got things to take care of here. You kids can go ahead without me.",
          TalkActionId = {
            [1] = "200061:Angry01_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101054/194C4083"
        },
        [10105426] = {
          Camera = "-24.691406,-252.042969,170.015625,0.001425,-5.800073,93.189316,60.000027,375.978333,false,Manual,8.0",
          Content = "你是打算……",
          DialogueId = 10105426,
          ExStoryInfo = "Player",
          GUID = "194C40A2",
          NextDialogue = 10105427,
          Scripts = "SetLocation{ActorId{200002},TargetPoint{\"P101054_BaiMove1\"},Visibility{\"Hide\"}},",
          SpeakNpcId = 200061,
          Subtitle = "Er, how come you are as clueless as a newly hatched quail? I bet even that white little button mushroom beside you is even more informed.",
          VoiceName = "voice/$Locale$/story/1002/101054/194C40A2"
        },
        [10105427] = {
          Camera = "-24.691406,-252.042969,170.015625,0.001425,-5.800073,93.189316,60.000027,375.978333,false,Manual,8.0",
          Content = "喏，这些包袱。",
          DialogueId = 10105427,
          GUID = "194C40CC",
          NextDialogue = 10105428,
          Scripts = [[
