          SpeakNpcId = 200021,
          Subtitle = "I'll be back a bit late, might miss The Asphodel's closing time. Come and find me at my place — it's among those shabby houses south of the city, the one with a little bird drawn on the door.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101054/194C43EA"
        },
        [10105447] = {
          Camera = "-9.882812,4.484375,146.6875,0.000026,1.206198,-92.395676,50.0,241.293564,false,Manual,4.0",
          Content = "还有，一个人来——别带无关的家伙。",
          DialogueId = 10105447,
          FinalCamera = "-9.882812,4.484375,146.6875,0.000026,1.406199,-92.39563,52.0,241.293564,false,Manual,4.0",
