          Content = "{性别：大哥哥|大姐姐}，怎么了？",
          DialogueId = 10106202,
          ExStoryInfo = "Player",
          FinalCamera = "-14.872528,-148.162109,141.300781,0.000156,-3.591819,17.001348,30.000002,555.360596,false,DoNotOverride,4.01182",
