          GUID = "194D442E",
          NextDialogue = 10107005,
          SpeakNpcId = 200006,
          Subtitle = "Really? I wouldn't have pegged Mr Outsider as someone so sensitive.",
          VoiceName = "voice/$Locale$/story/1002/101070/194D442E"
        },
        [10107005] = {
          Camera = "-239.527344,-76.267822,140.667969,0.000016,-1.799365,15.204763,35.000008,357.107239,false,Manual,1.688559",
          Content = "他本人……和他那副不着调的样子确实有那么一丁点区别。说起来……",
