}]],
          SpeakNpcId = 200019,
          Subtitle = "Like how I clean here daily, or how Psyche waters her flowers twice a day. Habit fills the void inside.",
          TalkActionId = {
            [1] = "200019:Explain01_End"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101071/194D5568"
        },
        [10107109] = {
