          Scripts = "PlayAnimation{_delay{2},ActorId{100001},AnimationId{\"Explain02_End\"},Duration{1}}",
          SpeakNpcId = 100001,
          Subtitle = "Couldn't get to the bottom of his story, but I did make some discoveries:",
