        [10108316] = {
          Camera = "246.869141,-113.95459,93.220703,0.000112,9.199985,148.006638,50.0,100000.0,false,Disable,2.8",
          Content = "<H>“和鸣之力”</>……你也会和鸣之力吧？你当心，这力量得谨慎着用。尤其是在军团的家伙面前。",
          DialogueId = 10108316,
          FacialId = {
            [1] = "200021:Unhappy02"
          },
          FinalCamera = "242.654297,-120.710449,93.220703,0.000112,9.199985,148.006638,50.0,100000.0,false,Disable,2.8",
          GUID = "194E1A9C",
          NextDialogue = 10108317,
          SpeakNpcId = 200021,
          Subtitle = "Resonance... You can wield the power of Resonance, right? Be careful, try to keep it under wraps in public.",
          TalkActionId = {
            [1] = "200021:Think_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1A9C"
        },
        [10108317] = {
          Camera = "-93.328125,262.184082,195.200195,0.000062,-13.600217,-67.771736,40.0,263.908203,false,Manual,4.0",
          Content = "“和鸣之力”是什么？没听说过。",
          DialogueId = 10108317,
          ExStoryInfo = "Player",
          GUID = "194E1A9D",
          NextDialogue = 10108318,
          SpeakNpcId = 100001,
          Subtitle = "How did you know about Resonance?",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101083/194E1A9D"
        },
        [10108318] = {
          Camera = "137.707031,-41.043945,135.595703,0.00014,3.398955,147.20549,35.0,100000.0,false,Disable,2.8",
          Content = "别装傻。",
          DialogueId = 10108318,
          GUID = "194E1B44",
          NextDialogue = 10108319,
          SpeakNpcId = 200021,
          Subtitle = "What is Resonance? I'm not following.",
          TalkActionId = {
            [1] = "200021:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101083/194E1B44"
        },
        [10108319] = {
          Camera = "635.107422,652.389893,188.712891,0.000178,-5.600987,-134.588898,50.0,100000.0,false,Disable,2.8",
          Content = "在废矿的时候，我就感到有什么在试图“引导”我的行动，这和传说中的“和鸣之力”很像……只是那股力量细微很多，没那么容易察觉。",
          DialogueId = 10108319,
          Duration = 1.5,
          FinalCamera = "755.806641,504.501465,188.712891,0.000165,-5.600953,-146.790039,50.0,100000.0,false,Disable,2.8",
          GUID = "194E1B6E",
          NextDialogue = 10108320,
          Scripts = "PlayAnimation{_delay{4},ActorId{200021},AnimationId{\"Talk01_End\"},Duration{1}}",
          SpeakNpcId = 200021,
          Subtitle = "...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1B6E"
        },
        [10108320] = {
