          DialogueId = 10108327,
          FacialId = {
            [1] = "200021:None"
          },
          GUID = "194E1B9D",
          NextDialogue = 10108328,
          SpeakNpcId = 200021,
          Subtitle = "Just some rumours I've heard. They say the last person with that power wreaked havoc across the Empire. Your power, though much weaker, is very similar to that legendary power of Resonance.",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101083/194E1B9D"
        },
        [10108328] = {
          Camera = "32.6875,29.662109,128.611328,0.000209,-4.201447,-62.396164,25.0,65.99147,false,Manual,5.0",
          CameraBlendCurve = "easeInQuad",
          Content = "（……操控？该不会是那个时候，和贝蕾——）",
          DialogueId = 10108328,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FinalCamera = "18.273438,57.231689,130.894531,0.000209,-4.201447,-62.396164,35.0,130.879471,false,Manual,5.0",
          GUID = "194E1B9E",
          NextOptions = {
