          VoiceName = "voice/$Locale$/story/1002/101094/194ECE6D"
        },
        [10109410] = {
          Camera = "60.910156,-67.048828,109.011719,0.000257,-3.799709,132.574326,35.0,339.966736,false,DoNotOverride,2.608581",
          Content = "不说这个了。我有一个想去的地方，你可以陪我一起吗？",
          DialogueId = 10109410,
          FacialId = {
