          VoiceName = "voice/$Locale$/story/1002/101097/194F00CA"
        },
        [10109801] = {
          Content = "在我很小的时候，爸爸偶尔会带我来湖边散步。",
          DialogueId = 10109801,
          GUID = "194F0F3A",
          NextDialogue = 10109802,
          SpeakNpcId = 200006,
          Subtitle = "When I was little, Dad would sometimes bring me here for walks.",
          VoiceName = "voice/$Locale$/story/1002/101098/194F0F3A"
        },
        [10109802] = {
          Content = "虽然时不时要和秽兽捉迷藏，但我总是很期待来这里。",
          DialogueId = 10109802,
          GUID = "194F0F64",
          NextDialogue = 10109803,
          SpeakNpcId = 200006,
          Subtitle = "Despite the occasional hide-and-seek with the Filthoids, I always looked forward to coming here.",
          VoiceName = "voice/$Locale$/story/1002/101098/194F0F64"
        },
        [10109803] = {
          Content = "因为我喜欢这里的浮冰和山峰，更因为，我喜欢看列车呼啸而过。",
          DialogueId = 10109803,
          GUID = "194F0F8E",
          NextDialogue = 10109804,
          SpeakNpcId = 200006,
          Subtitle = "Because I loved the floating ice and mountains here, and more so, I loved watching the trains roar by.",
          VoiceName = "voice/$Locale$/story/1002/101098/194F0F8E"
        }
      }
    end
