        },
        [10110520] = {
          Camera = "-96.555542,225.161621,183.296875,3.000299,-15.400382,-44.843758,35.0,247.466965,false,Manual,22.0",
          Content = "……！！你听到了吗？",
          DialogueId = 10110520,
          FacialId = {
            [1] = "200021:Shock01",
            [2] = "100001:Shock02"
          },
          GUID = "194F84B2",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "100001:n(200021)"
          },
          NextDialogue = 10110521,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0051_story_danger\"},RelatedRegionId{101101},bStoreToServer{false}}",
          SpeakNpcId = 200021,
          Subtitle = "...!! Did you hear that?",
          VoiceName = "voice/$Locale$/story/1002/101105/194F84B2"
        },
        [10110521] = {
          Camera = "67.095459,-243.466309,147.307129,0.00015,0.999987,94.153214,20.0,580.704468,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          Content = "尖叫声——修普诺斯之家的方向！",
          DialogueId = 10110521,
          FinalCamera = "62.456299,-179.568848,96.763916,0.00015,6.0,94.153214,25.0,580.704468,false,Manual,1.2",
          GUID = "194F84DC",
          LookAt = {
            [1] = "200021:p(P_1190910)",
            [2] = "100001:p(P_1190910)"
          },
          NextDialogue = 10110522,
          SpeakNpcId = 200021,
          Subtitle = "Screams — from the direction of the Hypnos' House!",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101105/194F84DC"
        },
        [10110522] = {
          Camera = "62.456299,-179.568848,96.763916,0.00015,6.0,94.153214,25.0,580.704468,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          Content = "快去看看！",
          DialogueId = 10110522,
          ExStoryInfo = "Player",
          FinalCamera = "44.078735,73.518066,447.49585,0.00015,7.500012,94.153214,30.0,728.291565,false,Manual,1.2",
          GUID = "194F8506",
          LookAt = {
