MoveTo{_click{true},ActorId{200021},TargetPoint{"P101105Aote3"},MoveSpeed{300},Visibility{"Show"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Let's go!",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101105/194F8506"
        },
        [10110601] = {
          Camera = "-24.092529,-443.466797,251.954834,0.000135,-4.199583,87.351624,25.0,1.5,false,DoNotOverride,22.0",
          CameraBlendCurve = "easeInOutQuad",
          Content = "你们终于来了！！吓死白了！",
          DialogueId = 10110601,
          FacialId = {
            [1] = "200002:Shock02"
          },
          FinalCamera = "-19.506348,-348.400391,223.084106,0.000123,-22.200073,87.351807,25.0,1.5,false,DoNotOverride,22.0",
          GUID = "194F927A",
          LookAt = {
            [1] = "200021:n(200002)",
            [2] = "100001:n(200002)"
          },
          NextDialogue = 10110602,
          RelatedWikiId = {
            [1] = 201006,
            [2] = 201007,
            [3] = 405002,
            [4] = 303006
          },
          Scripts = [[
PARA{
