}
,SEQ{
MoveTo{ActorId{200021},MoveSpeed{90},TargetPoint{"P10110601"}},PlayAnimation{_delay{0.3},ActorId{200021},AnimationId{"Confident_Start"},Duration{1}}
},
PlayAnimation{_delay{0.7},ActorId{200002},AnimationId{"Sigh_Start"},Duration{1}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "You're finally here!! You've no idea how scary it was!",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101106/194F927A"
        },
        [10110602] = {
          Camera = "-58.66626,184.545898,58.416016,0.000013,9.599646,-71.385262,25.000002,245.13945,false,Manual,22.0",
          Content = "刚才不会是你在鬼叫吧？出什么事了？",
          DialogueId = 10110602,
          FacialId = {
            [1] = "200002:None"
          },
          GUID = "194F92A4",
          LookAt = {
            [1] = "200002:n(200021)"
          },
          NextDialogue = 10110603,
          Scripts = [[
PARA{
SetLocation{ActorId{200021},TargetPoint{"P10110603"},Visibility{"Show"}},
PlayAnimation{ActorId{200021},AnimationId{"Explain01_Start"},Duration{1}},
PlayAnimation{_delay{3},ActorId{200002},AnimationId{"Sigh_End"},Duration{1}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "Was that you shrieking just now? What happened?",
          VoiceName = "voice/$Locale$/story/1002/101106/194F92A4"
        },
        [10110603] = {
          Camera = "3.640381,-208.794922,183.625,0.000191,-20.999163,86.982307,50.000008,334.161133,false,Manual,3.0",
          Content = "我不是按你们说的一直在这里观察情况嘛……然后，真的像你们说的那样，赛琪出来了！我就上去拉住她，准备带她去找你们。",
          DialogueId = 10110603,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200002:Doubt01"
          },
          GUID = "194F92CE",
          NextDialogue = 10110604,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200002},AnimationId{"Angry01_Start"},Duration{3.8}},PlayAnimation{ActorId{200002},AnimationId{"Angry01_End"},Duration{4.2}},PlayAnimation{ActorId{200002},AnimationId{"Talk02_Start"},Duration{1}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "I was just keeping watch here as you asked me to... And just like you expected, Psyche came out! I ran to her, ready to take her to you.",
          VoiceName = "voice/$Locale$/story/1002/101106/194F92CE"
        },
        [10110604] = {
          Camera = "5.263672,-60.99707,136.059082,0.000133,-20.999565,92.985939,35.000008,170.151947,false,Manual,22.0",
          Content = "可她突然扑了过来，狠狠地抓向我……还好本大人闪得快！但是……那真的是赛琪吗？那个人一点都不像平时的她，就像是……一头野兽！",
          DialogueId = 10110604,
          FacialId = {
            [1] = "200002:Shock01"
          },
          FinalCamera = "2.735596,-5.030273,114.464722,0.000139,-19.799591,92.585823,35.000008,170.151947,false,Manual,22.0",
          GUID = "194F92F8",
          NextDialogue = 10110605,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200002},AnimationId{"Shock_Start"},Duration{3.7}},
PlayAnimation{ActorId{200002},AnimationId{"Shock_End"},Duration{6.3}},
PlayAnimation{ActorId{200002},AnimationId{"Disagree"},Duration{3}},
PlayAnimation{ActorId{200002},AnimationId{"Think_Start"},Duration{1}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "But she suddenly lunged at me, looking all scary... Lucky I was quick on my feet! But... was that really Psyche? She was nothing like her usual self, more like... a wild beast!",
          TalkActionId = {
            [1] = "200021:Talk03_End"
