          Content = "请你们带上这个。",
          DialogueId = 10110902,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter01_Flower_1.T_Guide_Chapter01_Flower_1'}",
