          VoiceName = "voice/$Locale$/story/1002/101109/194FC3DC"
        },
        [10110903] = {
          Camera = "64.572266,91.821472,278.037109,0.0,0.0,89.999992,30.0,100000.0,false,DoNotOverride,22",
          Content = "赛琪会经常送花给我们，即使我们有的人已经不太闻得出花的香味，不太看得清花的轮廓，她还是会说，花可以给人带来好运，坚持这么做。",
          DialogueId = 10110903,
          FinalCamera = "64.572266,141.821472,278.037109,0.0,0.0,89.999992,30.0,100000.0,false,DoNotOverride,22",
          GUID = "194FC406",
          LookAt = {
            [1] = "200045:p(P10106801)"
          },
          NextDialogue = 10110904,
          SpeakNpcId = 200045,
          Subtitle = "Psyche often gave us flowers. Even though some of us can barely smell or see them clearly anymore, she kept doing it, saying flowers bring good luck.",
          TalkActionId = {
            [1] = "200045:Talk02_End"
          },
          ToFinalCameraBlendTime = 7.5,
          VoiceName = "voice/$Locale$/story/1002/101109/194FC406"
        },
        [10110904] = {
          Camera = "-64.513672,-54.797607,154.447266,0.000147,-5.19662,21.383118,35.000008,170.88736,false,Manual,3.0",
          Content = "……但当我想要回应的时候，已经来不及了。",
          DialogueId = 10110904,
          GUID = "194FC430",
          NextDialogue = 10110905,
          SpeakNpcId = 200045,
          Subtitle = "...But by the time I wanted to return her kindness, it was already too late.",
          TalkActionId = {
            [1] = "200045:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101109/194FC430"
        },
        [10110905] = {
          Camera = "-230.103516,-78.412262,153.914062,0.000093,-5.797054,21.191561,35.000008,351.556366,false,Manual,4.0",
          Content = "请你们把这朵花带给她吧，这是她最喜欢的花。",
          DialogueId = 10110905,
          GUID = "194FC45A",
          LookAt = {
            [1] = "200045:n(100001)"
          },
          NextDialogue = 10110906,
          SpeakNpcId = 200045,
          Subtitle = "Please bring this flower to her. It's her favourite.",
          TalkActionId = {
            [1] = "200045:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101109/194FC45A"
        },
        [10110906] = {
          Camera = "-7.181641,-249.865479,233.710938,0.000057,-29.099882,93.194183,15.000005,100000.0,false,DoNotOverride,22.0",
          CameraBlendCurve = "easeInOutQuad",
          Content = "请告诉她，修普诺斯之家的每个人，都在等着她……",
          DialogueId = 10110906,
          FinalCamera = "-4.027344,-306.261597,265.148438,0.000057,-29.099882,93.194183,15.000005,100000.0,false,DoNotOverride,22.0",
          GUID = "194FC484",
          NextDialogue = 10110907,
          SpeakNpcId = 200045,
          Subtitle = "And let her know that everyone at the Hypnos' House is waiting for her...",
          TalkActionId = {
            [1] = "200045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101109/194FC484"
        },
        [10110907] = {
          Camera = "262.748047,-120.47818,147.644531,0.000102,-4.196898,153.589691,35.000008,434.590698,false,Manual,3.0",
          Content = "我会的。我一定会救下她。",
          DialogueId = 10110907,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "194FC4AE",
          NextDialogue = 10110908,
          SpeakNpcId = 100001,
          Subtitle = "I will. I'm gonna do everything I can to save her.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101109/194FC4AE"
        },
        [10110908] = {
          Camera = "51.148438,0.197876,149.753906,0.000102,-4.600037,179.58815,35.000011,140.0,false,Manual,1.2",
          Content = "或者至少……阻止她做出违背自己心愿的事。",
