          GUID = "194FC4D8",
          Scripts = [[
PARA{
CameraMoveTo{_delay{2.1},TargetPosition{"-22.845703,1.761353,150.835938,0.000102,-4.600037,179.58815,35.000011,65.552429,false,Manual,4.0"},duration{0}},
CameraMoveTo{_delay{2.2},TargetPosition{"-27.648438,1.795654,150.466797,0.000102,-4.600037,179.58815,35.000011,65.552429,false,Manual,4.0"},duration{2}}
