        },
        [10111701] = {
          Content = "不是的长官，我的女儿一向懂事，她绝不会偷窃顾客的项链，更没有藏在花盆里！",
          DialogueId = 10111701,
          GUID = "191BCA3A",
          NextDialogue = 10111702,
          SpeakNpcId = 200039,
          Subtitle = "So what if he hit your daughter? It was all because your daughter's stuff was an eyesore, wasn't it?",
          VoiceName = "voice/$Locale$/story/1002/101117/191BCA3A"
        },
        [10111702] = {
          Content = "狡辩什么，卡戎崽子有几个手脚干净的？",
          DialogueId = 10111702,
          GUID = "191BCA64",
          NextDialogue = 10111703,
          SpeakNpcId = 200043,
          Subtitle = "Exactly. And it was just a pot of flowers, so cut the whimper, you little twerp. Don't get your filthy tears on my uniform.",
