        [10112809] = {
          Camera = "8.78125,264.457031,83.086914,0.00015,-10.402186,77.949188,20.0,269.900269,false,Manual,3.0",
          Content = "……不、不是{nickname}，是我自己……杀了……自己……因为，这幅样子，并不能算……活着……",
