          Camera = "75.344727,-95.773438,67.208008,0.000134,10.399467,-165.347519,35.0,416.263275,false,Manual,3.0",
          CameraBlendCurve = "easeInOutQuad",
          Content = "什么叫“处理掉”……！你们怎么能——",
          DialogueId = 10113021,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Angry01"
          },
          FinalCamera = "76.850586,-100.21875,67.208008,0.000135,5.599389,-163.545654,35.000008,416.263275,false,Manual,3.0",
          GUID = "19511F58",
          LookAt = {
            [1] = "100001:n(100304)",
            [2] = "200002:n(100001)",
            [3] = "100304:n(100001)"
          },
          NextDialogue = 10113022,
          Scripts = [[
SEQ{
