PlayAnimation{ActorId{100001},AnimationId{"Explain02_End"},Duration{1}},
PlayAnimation{ActorId{200002},AnimationId{"Angry01_Start"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "\"Dispose of\"... How could you even—",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101130/19511F58"
        },
        [10113022] = {
          Camera = "-119.96582,-148.324219,144.583984,0.000557,-3.000359,-150.749786,50.000008,307.707306,false,DoNotOverride,22.0",
          CameraBlendCurve = "easeInOutQuad",
          Content = "你说什么？",
          DialogueId = 10113022,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "-189.724609,-187.386719,140.395508,0.000557,-1.600341,-150.749786,50.000008,307.707306,false,DoNotOverride,22.0",
          GUID = "19511F82",
          NextDialogue = 10113023,
          Scripts = "SetLocation{ActorId{700065},TargetPoint{\"P101130soldier2\"},Visibility{\"Hide\"}}",
          SpeakNpcId = 100304,
          Subtitle = "What did you say?",
          ToFinalCameraBlendTime = 1,
          TurnTo = {
            [1] = "100304:p(50)"
          },
          VoiceName = "voice/$Locale$/story/1002/101130/19511F82"
        },
        [10113023] = {
          Camera = "-318.40918,-288.792969,134.553711,0.000583,-3.50069,42.051529,35.000008,361.092285,false,Manual,4.0",
          Content = "你怎么了？受伤了吗？",
          DialogueId = 10113023,
          GUID = "19511FAC",
          NextDialogue = 10113024,
          SpeakNpcId = 100304,
          Subtitle = "Are you alright? Injured perhaps? Should I arrange a military medic for you?",
          VoiceName = "voice/$Locale$/story/1002/101130/19511FAC"
        },
        [10113024] = {
          Camera = "-43.249023,-230.039062,139.522461,0.000592,5.699356,27.05097,35.000008,145.830688,false,Manual,4.0",
          Content = "没有没有没有。我的朋友只是受了小小的惊吓，我们等下去“水仙平原”喝点热饮就好。",
          DialogueId = 10113024,
          FacialId = {
            [1] = "200021:None"
          },
          GUID = "19511FD6",
          LookAt = {
            [1] = "100304:n(200021)",
            [2] = "200021:n(100304)"
          },
          NextDialogue = 10113025,
          Scripts = "SetLocation{ActorId{700065},TargetPoint{\"P101130soldier2\"},Visibility{\"Show\"}}",
          SpeakNpcId = 200021,
          Subtitle = "Not at all, ma'am. My friend is just a bit shaken, we'll be fine after a few warm drinks at the Asphodel.",
          TalkActionId = {
            [1] = "200021:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101130/19511FD6"
        },
        [10113025] = {
          Camera = "159.128906,-260.046875,192.414062,0.000568,-16.500391,136.848602,35.000011,145.830688,false,Manual,22.0",
          Content = "报酬下次再说啦。下一份委托快到时限了，得赶时间，我们先走一步啊。",
          DialogueId = 10113025,
          FacialId = {
            [1] = "200021:Ahaha01"
          },
          GUID = "1951202A",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextOptions = {
            [1] = 10113026,
            [2] = 10113028
          },
          SpeakNpcId = 200021,
          Subtitle = "We'll talk about the reward another time. We're pressed for time with an upcoming task, we'll take our leave now.",
          TalkActionId = {
            [1] = "200021:Talk02_Start",
            [2] = "100304:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101130/1951202A"
        },
        [10113026] = {
          Content = "（冷静下来，保持沉默——你不能继续引起军团怀疑了。） ",
          DialogueId = 10113026,
          DisableMouth = 1,
          GUID = "10113026",
          ImprPlusId = 1006,
          NextDialogue = 10113027,
          Subtitle = "(Calm down and remain silent — it's unwise to draw more attention from the Legion.)"
        },
        [10113027] = {
          Camera = "-139.688477,-91.050781,121.101562,-4.000003,8.402478,-13.154885,35.0,104.579765,false,Manual,4.0",
          Content = "……我们走吧。",
          DialogueId = 10113027,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "1951202B",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          SpeakNpcId = 100001,
          Subtitle = "...Let's leave.",
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "2000581:BossSaiqi_Story_Die"
          },
          VoiceName = "voice/$Locale$/story/1002/101130/1951202B"
        },
        [10113028] = {
          Content = "（继续说下去——即使面临风险，你也决意为赛琪正名。）",
          DialogueId = 10113028,
          DisableMouth = 1,
          GUID = "10113028",
          ImprPlusId = 1007,
          NextDialogue = 10113029,
          Subtitle = "(Continue the speech despite the risk — you've made up your mind to set the record straight for Psyche.)"
        },
        [10113029] = {
          Camera = "-341.749023,-589.355469,7.225586,-5.000006,4.199118,65.395798,25.000002,854.098511,false,DoNotOverride,22.0",
          CameraBlendCurve = "easeInQuad",
          Content = "她不是什么秽兽，不是什么让你们随意收拾的垃圾。",
          DialogueId = 10113029,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Unhappy02",
            [2] = "200021:None"
          },
          FinalCamera = "-360.44043,-630.929688,4.519531,-5.000006,8.999204,66.594841,25.000002,854.098511,false,DoNotOverride,22.0",
          GUID = "1951202C",
          LookAt = {
            [1] = "100304:n(100001)",
            [2] = "100001:n(100304)"
          },
          NextDialogue = 10113030,
          SpeakNpcId = 100001,
          Subtitle = "She was not a Filthoid or some trash for you to dispose of.",
          TalkActionId = {
            [1] = "200021:Talk02_End",
            [2] = "100304:Think_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101130/1951202C"
        },
        [10113030] = {
          Camera = "-313.24707,-289.5,102.341797,0.000199,0.897494,42.804501,30.0,516.200134,false,Manual,3.5",
          Content = "她的名字叫赛琪，她曾是冰湖城的市民。就在今夜，她从“秽蚀”中保护了冰湖城的所有人。",
          DialogueId = 10113030,
          ExStoryInfo = "Player",
          GUID = "1951202D",
          NextDialogue = 10113031,
          SpeakNpcId = 100001,
          Subtitle = "Her name was Psyche. She was a citizen of Icelake. Tonight, she protected everyone in the city from Deterioration.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101130/1951202D"
        },
        [10113031] = {
          Camera = "-71.211914,-137.410156,141.410156,5.00005,-0.600189,43.438988,35.0,54.652218,false,Manual,8.0",
          Content = "我要亲手把她好好埋葬。谁都别过来。",
          DialogueId = 10113031,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Angry01"
          },
          FinalCamera = "-73.801758,-139.859375,141.443359,5.000083,-0.600189,43.438965,35.0,58.003056,false,Manual,8.0",
          GUID = "1951202E",
          NextDialogue = 10113032,
          Scripts = [[
PARA{
LookAt{_delay{1},LookAtDescription{"100001:n(700065)"}},
CameraMoveTo{_delay{2.6},TargetPosition{"-508.9375,-469.679688,177.929688,5.001051,-9.600404,36.039646,25.0,376.025848,false,Manual,2.5"},duration{0}},
CameraMoveTo{_delay{2.7},TargetPosition{"-516.53125,-475.191406,179.519531,5.001068,-9.600404,36.039593,25.0,376.025848,false,Manual,2.5"},blend{"easeOutQuad"},duration{2.5}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "I will make sure she receives a proper send-off. Stay away from us.",
          ToFinalCameraBlendTime = 2.5,
          VoiceName = "voice/$Locale$/story/1002/101130/1951202E"
        },
        [10113032] = {
          Camera = "-238.606445,-234.828125,126.856445,0.000532,0.099973,-152.555771,16.0,165.460846,false,Manual,1.90943",
          Content = "你在说什么鬼话，你护着秽兽？黎瑟长官，这独眼龙真的有问题，得抓回去好好审审——",
          DialogueId = 10113032,
          ExStoryInfo = "Player",
          GUID = "1951202F",
          LookAt = {
            [1] = "100001:n(700065)"
          },
          NextDialogue = 10113033,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{700108},AnimationId{"Explain01_Start"},Duration{1}},
LookAt{LookAtDescription{"700108:n(100001)"}},
LookAt{_delay{1},LookAtDescription{"700108:n(100304)"}}
}]],
          SpeakNpcId = 700108,
          Subtitle = "What are you talking about? You're defending a Filthoid? Ma'am, this one-eyed brat is highly suspicious — might need a thorough interrogation...",
          VoiceName = "voice/$Locale$/story/1002/101130/1951202F"
        },
        [10113033] = {
          Camera = "-238.606445,-234.828125,126.856445,0.000532,0.099973,-152.555771,16.0,165.460846,false,Manual,1.90943",
          CameraBlendCurve = "easeInOutQuad",
          Content = "不必。",
          DialogueId = 10113033,
          FinalCamera = "-238.606445,-234.828125,126.856445,0.000533,-1.900234,-169.95401,16.0,58.362331,false,Manual,4.0",
          GUID = "19512030",
          LookAt = {
            [1] = "700108:n(100304)",
            [2] = "100304:n(100001)"
          },
          NextDialogue = 10113034,
          SpeakNpcId = 100304,
          Subtitle = "That's unnecessary.",
          TalkActionId = {
            [1] = "700108:Explain01_End"
          },
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1002/101130/19512030"
        },
        [10113034] = {
          Camera = "-1891.500977,2693.113281,454.838867,0.000539,2.599713,134.995483,16.000004,229.756851,false,Manual,22.0",
          CameraBlendCurve = "easeInOutQuad",
          Content = "卡戎之民安葬同胞的方式，不是埋葬，是将他们的遗体置于水中，漂向远方。他们相信水域将载着同胞的灵魂，去向永恒的雾海。",
          DialogueId = 10113034,
          FinalCamera = "-2414.716797,3210.023438,486.790039,0.000538,0.399675,135.795761,16.000004,229.756851,false,Manual,22.0",
          GUID = "19512031",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10113035,
          SpeakNpcId = 100304,
          Subtitle = "In Charon tradition, we don't bury the deceased. Instead, we set them adrift on water, believing it carries their souls to the eternal Misty Sea.",
          TalkActionId = {
            [1] = "100304:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101130/19512031"
        },
        [10113035] = {
          Camera = "20.90332,-103.425781,136.911133,0.000598,-5.3977,-161.513031,25.000002,305.823792,false,Manual,3.0",
          Content = "走吧。这边的事情，我来向长官解释。",
          DialogueId = 10113035,
          FacialId = {
            [1] = "100304:Unhappy01"
          },
          GUID = "19512032",
          LookAt = {
            [1] = "100304:n(700108)"
          },
          NextDialogue = 10113036,
          Scripts = [[
