        [10113039] = {
          Camera = "-195.787109,-176.09375,124.895508,0.00054,1.402545,-144.774109,25.0,115.146286,false,Manual,22.0",
          Content = "“已经解决”？",
          DialogueId = 10113039,
          FacialId = {
            [1] = "100304:None"
          },
          FinalCamera = "-201.873047,-180.394531,124.880859,0.00054,2.802508,-144.973618,25.0,115.146286,false,Manual,22.0",
