          VoiceName = "voice/$Locale$/story/1002/101130/19511D0C"
        },
        [10113101] = {
          Camera = "-1547.606445,-736.984497,-24.818359,0.000068,-5.399838,25.828234,20.0,147.856339,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          Content = "……",
