        [10113116] = {
          Camera = "-163.218521,132.791336,42.427734,-5.000002,15.199219,2.797176,35.000008,419.357452,false,Manual,3.5",
          Content = "风这么大，我什么都听不到。就算我听到什么声音，也只是山雀在乱叫而已。",
          DialogueId = 10113116,
          GUID = "19512E1C",
          LookAt = {
            [1] = "200021:n(200021)",
            [2] = "100001:n(100001)"
          },
          NextDialogue = 10113117,
          Scripts = "LookAt{_delay{2},LookAtDescription{\"200021:p(Psky)\"}}",
          SpeakNpcId = 200021,
          Subtitle = "The wind here is so strong, I can't hear a thing. Even if I do hear some noise, it's just the sparrows chirping.",
          VoiceName = "voice/$Locale$/story/1002/101131/19512E1C"
        },
        [10113117] = {
          Camera = "63.788624,80.274666,117.046875,0.000101,-0.000061,28.195601,35.0,46.83934,false,Manual,22.0",
          CameraBlendCurve = "easeInOutQuad",
          Content = "……这种事情啊，我已经见过很多次了。但我告诉自己，”你只有一个晚上可以流泪。”",
          DialogueId = 10113117,
          FacialId = {
            [1] = "200021:Ahaha01"
          },
          FinalCamera = "63.788624,80.274666,117.046875,0.000101,-0.20007,39.394825,35.0,46.83934,false,Manual,22.0",
          GUID = "19512E46",
          NextOptions = {
            [1] = 101131171,
            [2] = 101131172,
            [3] = 101131173
          },
          SpeakNpcId = 200021,
          Subtitle = "...I've seen this kind of thing countless times. But I tell myself, you've only got one night for tears.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101131/19512E46"
        },
        [10113118] = {
          Camera = "-335.797272,127.216934,-109.182617,0.000001,25.397947,-1.404929,18.0,177.065216,false,DoNotOverride,4.0",
          Content = "无论如何，好好活下去。那孩子一定也希望你能笑着迎接明天。",
          DialogueId = 10113118,
          FacialId = {
            [1] = "200021:Smile01",
            [2] = "100001:Sad01"
          },
          FinalCamera = "-335.797272,127.216934,-109.182617,-0.0,27.198065,-11.406103,18.0,177.065216,false,DoNotOverride,4.0",
          GUID = "19512E70",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10113119,
          Scripts = "LookAt{_delay{1},LookAtDescription{\"100001:n(200021)\"}}",
          SpeakNpcId = 200021,
          Subtitle = "Anyway, pull yourself together. That girl would surely wish for you to face tomorrow with a smile.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101131/19512E70"
        },
        [10113119] = {
