          VoiceName = "voice/$Locale$/story/1002/101132/19513E30"
        },
        [10113209] = {
          Camera = "-25.691406,13.0,-93.536926,0.000405,30.593058,-169.17392,35.0,572.451843,false,Manual,22.0",
          CameraBlendCurve = "easeInOutQuad",
          Content = "时间，还有生命……都是如此。",
