        [10113301] = {
          Content = "再一次崩塌的梦里，那个声音从风中传来。",
          DialogueId = 10113301,
          Duration = 3.5,
          GUID = "19514D72",
          NextDialogue = 10113302,
          Subtitle = "Once again in the collapsing dream, that voice whispered through the wind.",
