        },
        [10113302] = {
          Content = "这一次，我终于可以听清。",
          DialogueId = 10113302,
          Duration = 3.5,
          GUID = "19514D9C",
          NextDialogue = 10113303,
          Subtitle = "Only this time, I finally made it out.",
          VoiceName = "voice/$Locale$/story/1002/101133/19514D9C"
        },
        [10113303] = {
          Content = "像树木的根须汲取着每一滴水，我竭尽全力试图记住那个名字。",
          DialogueId = 10113303,
          Duration = 4,
          GUID = "19514DC6",
          NextDialogue = 10113304,
          Subtitle = "Like tree roots absorbing every drop of water, I tried my best to engrave that name in my mind.",
          VoiceName = "voice/$Locale$/story/1002/101133/19514DC6"
        },
        [10113304] = {
          Content = "……那个名字……",
          DialogueId = 10113304,
          Duration = 3,
          GUID = "19514DF0",
          Subtitle = "{性别:Her|His} name was—",
          VoiceName = "voice/$Locale$/story/1002/101133/19514DF0"
        },
        [10113401] = {
          Camera = "-1818.244629,451.75,65.15918,0.0,3.799989,1.999787,35.0,269.181396,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          Content = "我承受过痛苦，体会过憎恨。我曾为之疲惫，也曾为之悲叹——",
          DialogueId = 10113401,
          FacialId = {
            [1] = "2000591:Happy02"
          },
          FinalCamera = "-1818.244629,451.75,77.947998,0.0,6.0,1.999786,35.0,921.225525,false,Manual,1.2",
          GUID = "19515DDA",
          NextDialogue = 10113402,
          Scripts = [[
