          VoiceName = "voice/$Locale$/story/1002/101182/19547184"
        },
        [10118203] = {
          Camera = "-845.377014,-25.232204,629.145264,0.000027,-33.600269,4.611965,28.874323,1077.120361,false,Manual,4.2",
          Content = "你有困难我可以帮你，但直接上手抢，那就吃我一铲！",
          DialogueId = 10118203,
          FacialId = {
            [1] = "200011:Angry01"
          },
          GUID = "195471AE",
          SpeakNpcId = 200011,
          Subtitle = "If you're hard up, I can help you. But you can't just grab money of people — that'll earn you a whack on the head with my shovel!",
          TalkActionId = {
            [1] = "200011:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101182/195471AE"
        },
        [10118204] = {
          Content = "（青年似乎找不到反驳的话，气急败坏地跳下了墙。）",
          DialogueId = 10118204,
          DisableMouth = 1,
          GUID = "195471D8",
          VoiceName = "voice/$Locale$/story/1002/101182/195471D8"
        },
        [10118301] = {
