          Duration = 3,
          GUID = "195481C2",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10118303,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101183/195481C2"
        },
        [10118302] = {
          Content = "不……你们看，这面井盖有被挪动过的痕迹。",
          DialogueId = 10118302,
          Duration = 3,
          GUID = "195481EC",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 10118303,
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101183/195481EC"
        },
        [10118303] = {
          Content = "以我的推测，他一定钻进了下水道！",
