          DialogueId = 10118502,
          Duration = 3,
          GUID = "1954A2BC",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10118503,
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101185/1954A2BC"
        },
        [10118503] = {
