          Duration = 3,
          GUID = "1954B324",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101186/1954B324"
        },
        [10118603] = {
          Content = "虽然这些秽兽是体格最弱小的那种，快跟猫猫狗狗差不多了，但如果成群结队行动，还是会有点危险……",
          DialogueId = 10118603,
          Duration = 3,
          GUID = "1954B34E",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10118604,
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101186/1954B34E"
        },
