          Duration = 3,
          GUID = "1954C362",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 10118702,
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101187/1954C362"
        },
        [10118702] = {
