          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955A93C",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10120103,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A93C"
        },
        [10120103] = {
