          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101239/195818D6"
        },
        [10123904] = {
          Camera = "56.511719,-167.835693,119.327148,0.000756,2.594707,118.379005,35.0,218.031204,false,Manual,3.0",
          Content = "什么太阳月亮的，我要修屋顶，麻烦让一让。",
          DialogueId = 10123904,
          GUID = "19581900",
          NextDialogue = 10123905,
          SpeakNpcName = "UI_Npc_Name_AlertWoker",
          TalkActionId = {
            [1] = "200019:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101239/19581900"
        },
        [10123905] = {
          Camera = "-161.023438,20.044434,118.390259,0.000759,-2.805302,-37.617157,35.0,267.49585,false,Manual,3.0",
          Content = "走吧。",
          DialogueId = 10123905,
          GUID = "1958192A",
          LookAt = {
            [1] = "100001:n(200002)"
          },
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101239/1958192A"
        },
        [10123906] = {
          Content = "呜呜，我们好像跟丢了……",
          DialogueId = 10123906,
          GUID = "19581954",
          NextDialogue = 10123907,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101239/19581954"
        },
        [10123907] = {
          Content = "去问问花店的店主碰碰运气吧。",
          DialogueId = 10123907,
          GUID = "19581955",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101239/19581955"
        },
        [10124000] = {
          Content = "十分钟后。",
          DialogueId = 10124000,
          GUID = "10124000.0",
          IsBlack = 1
        },
        [10124001] = {
          Content = "你好你好！我们捡到一枚银币，是刚才那位叔叔掉的！我想还给他……",
          DialogueId = 10124001,
          GUID = "195828EA",
          NextDialogue = 10124002,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101240/195828EA"
        },
        [10124002] = {
          Content = "咦，阿姨你怎么在哭？不会是那家伙说了什么难听话吧！",
          DialogueId = 10124002,
          GUID = "19582914",
          NextDialogue = 10124003,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101240/19582914"
        },
        [10124003] = {
          Content = "啊……没有没有。眼睛里进了紫露花的花粉而已。",
          DialogueId = 10124003,
          GUID = "1958293E",
          NextDialogue = 10124004,
          SpeakNpcName = "UI_Npc_Name_FlowerShoper",
          VoiceName = "voice/$Locale$/story/1002/101240/1958293E"
        },
        [10124004] = {
          Content = "如果您说的是那位白衣服的先生，他现在……可能会在东北方向侧门的水潭那儿。",
          DialogueId = 10124004,
          GUID = "19582968",
          NextDialogue = 10124005,
          SpeakNpcName = "UI_Npc_Name_FlowerShoper",
          VoiceName = "voice/$Locale$/story/1002/101240/19582968"
        },
        [10124005] = {
          Content = "知道了，谢谢。",
          DialogueId = 10124005,
          GUID = "19582992",
          NextDialogue = 10124006,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101240/19582992"
        },
        [10124006] = {
          Content = "等一下，您……",
          DialogueId = 10124006,
          GUID = "195829BC",
          NextDialogue = 10124007,
          SpeakNpcName = "UI_Npc_Name_FlowerShoper",
          VoiceName = "voice/$Locale$/story/1002/101240/195829BC"
        },
        [10124007] = {
          Content = "嗯？您叫我吗？",
          DialogueId = 10124007,
          GUID = "195829E6",
          NextDialogue = 10124008,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101240/195829E6"
        },
        [10124008] = {
          Content = "……不，我也许认错人了。抱歉……您收下这个吧。",
          DialogueId = 10124008,
          GUID = "19582A10",
          NextDialogue = 10124101,
          SpeakNpcName = "UI_Npc_Name_FlowerShoper",
          VoiceName = "voice/$Locale$/story/1002/101240/19582A10"
        },
        [10124101] = {
          Content = "这是……白送的？",
          DialogueId = 10124101,
          GUID = "19583952",
          NextDialogue = 10124102,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101241/19583952"
        },
        [10124102] = {
          Content = "嗯。您也有着红宝石一样的漂亮眼睛，与这朵紫露花很相称……愿您度过快乐的一天。",
          DialogueId = 10124102,
          GUID = "1958397C",
          NextDialogue = 10124103,
          SpeakNpcName = "UI_Npc_Name_FlowerShoper",
          VoiceName = "voice/$Locale$/story/1002/101241/1958397C"
        },
        [10124103] = {
          Content = "谢谢，那我就收下了。",
          DialogueId = 10124103,
          GUID = "195839A6",
          NextDialogue = 10124104,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101241/195839A6"
        },
        [10124104] = {
          Content = "竟然有意外收获，小仆从真是魅力非凡！",
          DialogueId = 10124104,
          GUID = "195839D0",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101241/195839D0"
        },
        [10124201] = {
          Content = "应该就是这个水潭了……他果然在！",
          DialogueId = 10124201,
          GUID = "195849BA",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101242/195849BA"
        },
        [10124301] = {
          Content = "这一定就是他的惊天大秘密！只是，这么冷的水，就算是卡戎之民，下去捞也会着凉吧？",
          DialogueId = 10124301,
          GUID = "19585A22",
          NextDialogue = 10124302,
          VoiceName = "voice/$Locale$/story/1002/101243/19585A22"
        },
        [10124302] = {
          Content = "那就只能交给万能的皎皎了！白豁出去了——诶，小仆从你这是在……",
          DialogueId = 10124302,
          GUID = "19585A4C",
          NextDialogue = 10124303,
          VoiceName = "voice/$Locale$/story/1002/101243/19585A4C"
        },
        [10124303] = {
          Content = "只要这样改装一下钓竿……嗯，好了。",
          DialogueId = 10124303,
          GUID = "19585A76",
          NextDialogue = 10124304,
          VoiceName = "voice/$Locale$/story/1002/101243/19585A76"
        },
        [10124304] = {
          Content = "交给我吧。只要是水里的东西，就算是鲨鱼，我也能钓上来。",
          DialogueId = 10124304,
          GUID = "19585AA0",
          VoiceName = "voice/$Locale$/story/1002/101243/19585AA0"
        },
        [10124401] = {
          Content = "天啊，小仆从，莫非你就是艾利西安掌管水产的神？",
          DialogueId = 10124401,
          GUID = "19586A8A",
          NextDialogue = 10124402,
          VoiceName = "voice/$Locale$/story/1002/101244/19586A8A"
        },
        [10124402] = {
          Content = "用石块垒起的石堆，旁边放着一束白花。看起来似乎有某种纪念意义。",
          DialogueId = 10124402,
          GUID = "19586AB4",
          NextDialogue = 10124403,
          VoiceName = "voice/$Locale$/story/1002/101244/19586AB4"
        },
        [10124403] = {
          Content = "你看你看，这花像不像恩里克从花店买的那束？",
          DialogueId = 10124403,
          GUID = "19586ADE",
          VoiceName = "voice/$Locale$/story/1002/101244/19586ADE"
        },
