        [10125910] = {
          Camera = "110.996094,65.115234,147.691406,0.000015,-10.00217,80.202942,50.000011,464.774139,false,DoNotOverride,3.5",
          Content = "方才，在引导她归去之时，我看到了她牵念的一切，其中便有你的身影。",
          DialogueId = 10125910,
          GUID = "1959621C",
          NextDialogue = 10125911,
          Scripts = "SetLocation{ActorId{100001},TargetPoint{\"P_101259Nvzhu2\"},Visibility{\"Show\"}}",
