        },
        [10125926] = {
          Camera = "710.461914,-429.099609,211.467773,-5.000003,-8.998446,134.579147,18.0,1651574.625,false,Manual,22.0",
          CameraBlendCurve = "easeInOutQuad",
          Content = "有朝一日，当你获得了足够强大的力量——当你能够直面世界的真相，甚至打破构筑它的法则本身……",
          DialogueId = 10125926,
          FinalCamera = "710.461914,-429.099609,211.467773,-5.000003,-7.198329,122.178879,18.0,1651574.625,false,Manual,22.0",
