          SpeakNpcId = 110022,
          Subtitle = "Who are they?",
          TalkActionId = {
            [1] = "110022:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B9121BC"
        },
        [11011815] = {
          Camera = "-390.272461,434.320312,127.012085,0.000103,-3.799839,-81.401024,35.000015,100000.0,false,DoNotOverride,2.8",
          Content = "同盟的人，路上抓到的俘虏。",
          DialogueId = 11011815,
          GUID = "1B9121E6",
          LookAt = {
            [1] = "110034:n(110022)",
            [2] = "110017:n(110022)"
          },
          NextDialogue = 11011816,
          SpeakNpcId = 110016,
          Subtitle = "The Forsakens. We captured them on the way.",
          TurnTo = {
            [1] = "110016:n(110022)"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B9121E6"
        },
        [11011816] = {
          Camera = "-321.081055,224.484375,96.840698,0.000115,5.19998,-80.196815,35.000008,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          Content = "……我的好兄弟被你们豢养的怪物害死了。既然你提醒，那就在你身上开几个洞，给他抵命吧。",
          DialogueId = 11011816,
          FinalCamera = "-314.964844,189.072266,100.109863,0.000115,5.19998,-80.196815,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1B912210",
          LookAt = {
            [1] = "110016:n(110017)",
            [2] = "110017:n(110016)"
          },
          NextDialogue = 11011817,
          Scripts = [[
SEQ{
TurnTo{TurnToDescription{"110016:p(30)"}},
LookAt{_delay{0.7},LookAtDescription{"110016:n(110017)"}}
}]],
          SpeakNpcId = 110016,
          Subtitle = "...Your pet Filthoids killed a close buddy of mine. Reminded me just now — I ought to carve a few holes in you to honour his memory.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/110118/1B912210"
        },
        [11011817] = {
          Camera = "-422.004883,397.472656,125.112305,0.000134,-3.599892,-71.590111,35.000015,100000.0,false,DoNotOverride,2.8",
          Content = "住手。",
          DialogueId = 11011817,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91223A",
          LookAt = {
            [1] = "110016:n(110022)",
            [2] = "110017:n(110022)"
          },
          NextDialogue = 11011818,
          SpeakNpcId = 110022,
          Subtitle = "Stop it.",
          TalkActionId = {
            [1] = "110022:Talk03_End"
          },
          TurnTo = {
            [1] = "110016:n(110022)"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B91223A"
        },
        [11011818] = {
          Camera = "-141.424805,-386.271484,135.318604,0.000095,-5.799746,109.587715,35.000008,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          Content = "俘虏要活着带回去，交由帝国监狱审问。",
          DialogueId = 11011818,
          Duration = 1,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-177.341797,-399.052734,135.318604,0.000095,-5.799746,109.587715,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1B912264",
          LookAt = {
            [1] = "110022:n(110016)"
          },
          NextDialogue = 11011819,
          SpeakNpcId = 110022,
          Subtitle = "We should keep the captives alive. We need to take them back for interrogation in the Imperial Prison.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110118/1B912264"
        },
        [11011819] = {
          Camera = "-258.050781,293.537109,120.742798,0.000141,-2.800692,-89.800079,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "……这位长官……",
          DialogueId = 11011819,
          Duration = 1,
          FinalCamera = "-226.648438,293.638672,120.742798,0.000141,-2.800692,-89.800079,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1B91228E",
          NextDialogue = 11011820,
          SpeakNpcId = 110034,
          SpeakNpcName = "UI_Npc_KarongGirl",
          Subtitle = "...Sir.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/110118/1B91228E"
        },
        [11011820] = {
          Camera = "-159.664062,-158.019531,125.479492,0.000141,0.999134,-63.800842,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "如果只有一个卡戎之民的性命才能平息您的愤怒，就对我开枪吧。但在此之前，恳请您听一下我的解释……",
          DialogueId = 11011820,
          FinalCamera = "-149.302734,-179.078125,125.887695,0.000141,0.999134,-63.800903,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1B9122B8",
          NextDialogue = 11011821,
          Scripts = "SetLocation{ActorId{110043},TargetPoint{\"fix1101\"},Visibility{\"Show\"}}",
          SpeakNpcId = 110034,
          SpeakNpcName = "UI_Npc_KarongGirl",
          Subtitle = "If sacrificing one Charon can quell your anger, then take me. But first, please, let me explain...",
          ToFinalCameraBlendTime = 14,
          VoiceName = "voice/$Locale$/story/1002/110118/1B9122B8"
        },
        [11011821] = {
          Camera = "-591.692383,40.896484,136.615845,0.000137,-4.400848,-20.596607,35.000011,100000.0,false,DoNotOverride,2.8",
          Content = "卡嘉，回来，别犯傻！",
          DialogueId = 11011821,
          FinalCamera = "-591.692383,40.896484,136.615845,0.000137,-4.600863,-17.99663,35.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "1B9122E2",
          LookAt = {
            [1] = "110043:n(110017)",
            [2] = "110016:n(110017)"
          },
          NextDialogue = 11011822,
          Scripts = [[
PARA{
MoveTo{_delay{0},ActorId{110034},TargetPoint{"pKajiamove11"},MoveSpeed{70},Visibility{"Show"}},
LookAt{LookAtDescription{"110017:n(110034)"},Root{true}}
}]],
          SpeakNpcId = 110017,
          SpeakNpcName = "UI_Npc_OldKarong",
          Subtitle = "Come back, Katya! Don't be silly!",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/110118/1B9122E2"
        },
        [11011822] = {
          Camera = "-372.461914,137.933594,112.566528,0.000149,-3.400143,-71.792755,30.000008,100000.0,false,DoNotOverride,2.8",
          Content = "长官，我们虽然是卡戎之民，但我们不是神弃者同盟的成员。我们只是附近小镇再本分不过的普通人。",
          DialogueId = 11011822,
          FinalCamera = "-372.461914,137.933594,121.304565,0.000149,-3.400143,-71.792755,30.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1B91230C",
          LookAt = {
            [1] = "110034:n(110022)"
          },
          NextDialogue = 11018302,
          Scripts = "SetLocation{ActorId{110017},TargetPoint{\"Fix11_Set\"},Visibility{\"Show\"}}",
          SpeakNpcId = 110034,
          Subtitle = "Sir, we may be Charons but we are not part of The Forsakens. We're just ordinary folk living in a town nearby.",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "110016:n(110034)"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B91230C"
        },
        [11011824] = {
          Camera = "-474.881836,186.248047,147.918213,0.00014,-7.60077,-47.196186,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "开什么玩笑——同盟对自己的同胞下手？",
          DialogueId = 11011824,
          GUID = "1B912360",
          NextDialogue = 11018401,
          SpeakNpcId = 110016,
          Subtitle = "You can't be serious — The Forsakens are enslaving their own people?",
          VoiceName = "voice/$Locale$/story/1002/110118/1B912360"
        },
        [11011826] = {
          Camera = "-203.332031,-139.333984,134.157104,0.00013,-4.800441,125.003876,35.000008,391.636871,false,Manual,2.8",
          Content = "…………",
          DialogueId = 11011826,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9123B4",
          LookAt = {
            [1] = "110022:n(110034)"
          },
          NextDialogue = 11011827,
          SpeakNpcId = 110022,
          Subtitle = "...",
          TalkActionId = {
            [1] = "110022:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B9123B4"
        },
        [11011827] = {
          Camera = "-397.019531,164.720703,139.713013,0.000156,-7.600183,-69.580688,35.000011,100000.0,false,DoNotOverride,2.8",
          Content = "弗兰克爷爷是我的恩人。",
          DialogueId = 11011827,
          GUID = "1B9123DE",
          LookAt = {
            [1] = "110034:n(110022)"
          },
          NextDialogue = 11011828,
          SpeakNpcId = 110034,
          Subtitle = "Mr Frank saved my life.",
          VoiceName = "voice/$Locale$/story/1002/110118/1B9123DE"
        },
        [11011828] = {
          Content = "几天前，我只是肚子痛歇息了一会儿，就被同盟的畜生毒打了几十鞭子。奄奄一息的时候，是爷爷给了我水和食物，还有这条破袍子。",
          DialogueId = 11011828,
          FacialId = {
            [1] = "110034:Sad01"
          },
          GUID = "1B912408",
          NextDialogue = 11011829,
          SpeakNpcId = 110034,
          Subtitle = "Just a few days ago, I had to take a break because my stomach was acting up, but those Forsaken rotters whipped me dozens of times and left me for dead. It was Mr Frank who gave me water, food, and this ragged robe to cover me up.",
          TalkActionId = {
            [1] = "110022:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B912408"
        },
        [11011829] = {
          Camera = "-180.152344,-181.611328,153.236694,0.000139,-8.80102,119.82122,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "如果不是他好心，我那个时候就已经断气了。所以，我愿意替他抵命——请对我开枪吧。但是爷爷他是真心想帮您的，因为我们同您一样无法原谅同盟的恶行。",
          DialogueId = 11011829,
          FacialId = {
            [1] = "110034:None"
          },
          FinalCamera = "-188.547852,-186.429688,153.236694,0.000147,-8.80102,119.82122,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1B912432",
          LookAt = {
            [1] = "110034:n(110022)",
            [2] = "110022:n(110034)"
          },
          NextDialogue = 11011830,
          Scripts = "CameraMoveTo{_delay{8},TargetPosition{\"-334.542969,94.224609,124.2948,0.000144,-1.4012,-78.373749,35.000011,142.471191,false,Manual,2.8\"},duration{0}}",
          SpeakNpcId = 110034,
          Subtitle = "I would have died if not for Mr Frank. So if you must shoot him, could you please shoot me instead? He just wants to help, because none of us can forgive what The Forsakens did to us.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110118/1B912432"
        },
        [11011830] = {
          Camera = "-340.931641,528.488281,131.870483,0.000145,-6.201326,-90.573792,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "地下水道四通八达，你们自己一定会迷路。爷爷经常被使唤去修理水阀，他对那边很熟悉。如果您放他一条生路，他就可以带你们去你们要去的地方。",
          DialogueId = 11011830,
          FinalCamera = "-326.59082,528.347656,131.870483,0.000145,-6.201326,-90.573792,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1B91245C",
          NextDialogue = 11011831,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"110034:n(110043)"}},
LookAt{_delay{2},LookAtDescription{"110034:n(110022)"}}
}]],
          SpeakNpcId = 110034,
          Subtitle = "The sewer tunnels are like a maze. You'd easily get lost without help. The Forsakens always get Mr Frank to fix the sewer valves, so he knows the place like the back of his hand. Let him live and he'll get you where you need to go.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110118/1B91245C"
        },
        [11011831] = {
          Camera = "-181.973633,-155.728516,141.303955,0.000168,-6.001311,124.018631,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "行了。马尔科，放下枪——放下，这是命令。",
          DialogueId = 11011831,
          ExStoryInfo = "EXPlayer",
          GUID = "1B912486",
          LookAt = {
            [1] = "110022:n(110016)",
            [2] = "110043:n(110022)"
          },
          NextDialogue = 11011832,
          Scripts = "SetLocation{ActorId{110034},TargetPoint{\"pKajiaset\"},Visibility{\"Show\"}}",
          SpeakNpcId = 110022,
          Subtitle = "Alright. Marco, lower your gun — Holster it, this is an order.",
          TurnTo = {
            [1] = "110016:n(110022)"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B912486"
        },
        [11011832] = {
          Content = "莱昂，搜身。",
          DialogueId = 11011832,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9124B0",
          LookAt = {
            [1] = "110022:n(110043)"
          },
          NextDialogue = 11011833,
          SpeakNpcId = 110022,
          Subtitle = "Leon, frisk him.",
          VoiceName = "voice/$Locale$/story/1002/110118/1B9124B0"
        },
        [11011833] = {
          Camera = "-335.610352,446.109375,125.748901,0.000156,-4.80109,-91.97982,35.000011,100000.0,false,DoNotOverride,2.8",
          Content = "来了！",
          DialogueId = 11011833,
          FacialId = {
            [1] = "110034:Sad01"
          },
          GUID = "1B9124DA",
          LookAt = {
            [1] = "110043:n(110034)"
          },
          NextDialogue = 11011834,
          Scripts = "SetLocation{ActorId{110034},TargetPoint{\"pKajiamove11\"},Visibility{\"Show\"}}",
          SpeakNpcId = 110043,
          Subtitle = "Yes, sir!",
          TalkActionId = {
            [1] = "110043:Agree"
          },
          TurnTo = {
            [1] = "110016:n(110034)"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B9124DA"
        },
