          SpeakNpcId = 110010,
          Subtitle = "Excellent. That should be enough to move this cannon near the central control room.",
          TalkActionId = {
            [1] = "110010:AgreeHead"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110119/1B91327D"
        },
        [11012001] = {
          Content = "干得好，出发吧。把炮台开到轰击中央控制室的最佳位置。",
          DialogueId = 11012001,
          Duration = 3,
          GUID = "1B91406A",
          SpeakNpcId = 110010,
          Subtitle = "Well done. Now let's move the cannon to an optimal spot to bombard the central control room.",
          VoiceName = "voice/$Locale$/story/1002/110120/1B91406A"
        },
        [11012002] = {
          Content = "嗯，多亏了这两位难民的帮助。",
          DialogueId = 11012002,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B914094",
          SpeakNpcId = 110022,
          Subtitle = "Thanks to the help of these two refugees.",
          VoiceName = "voice/$Locale$/story/1002/110120/1B914094"
        },
        [11012003] = {
          Content = "留意炮台，别让秽兽把它弄坏了。",
          DialogueId = 11012003,
          Duration = 3,
          GUID = "1B9140BE",
          SpeakNpcId = 110010,
          Subtitle = "Keep the cannon from the Filthoids.",
          VoiceName = "voice/$Locale$/story/1002/110120/1B9140BE"
        },
        [11012004] = {
          Content = "我们找个轰击中心区屏障的最佳位置。你盯着点，别让秽兽把炮台弄坏了。",
          DialogueId = 11012004,
          Duration = 3,
          GUID = "1B9140E8",
          SpeakNpcId = 110010,
          Subtitle = "Let's find an optimal spot to bombard the barrier of the central area. Stay vigilant and protect the turret from the Filthoids.",
          VoiceName = "voice/$Locale$/story/1002/110120/1B9140E8"
        },
        [11012005] = {
          Content = "当心秽兽！",
          DialogueId = 11012005,
          Duration = 3,
          GUID = "1B914112",
          SpeakNpcId = 110010,
          Subtitle = "Heads up! Filthoids approaching!",
          VoiceName = "voice/$Locale$/story/1002/110120/1B914112"
        },
        [11012006] = {
          Content = "又来了，保护炮台！",
          DialogueId = 11012006,
          Duration = 3,
          GUID = "1B91413C",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 110010,
          Subtitle = "Another wave! Defend the turret!",
          VoiceName = "voice/$Locale$/story/1002/110120/1B91413C"
        },
        [11012101] = {
          Content = "这里视野不错，停下吧。",
          DialogueId = 11012101,
          Duration = 3,
          GUID = "1B9150D2",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 11012102,
          SpeakNpcId = 110010,
          Subtitle = "We have a clear view from here. This is our stop.",
          VoiceName = "voice/$Locale$/story/1002/110121/1B9150D2"
        },
        [11012102] = {
          Content = "接下来，我们就用这门月髓炮轰击前面的屏障。",
          DialogueId = 11012102,
          Duration = 3,
          GUID = "1B9150FC",
          SpeakNpcId = 110010,
          Subtitle = "Next, we'll use the Phoxichor cannon to blow apart the barrier ahead.",
          VoiceName = "voice/$Locale$/story/1002/110121/1B9150FC"
        },
        [11012103] = {
          Content = "有秽兽被吸引过来了，直接开炮吧。",
          DialogueId = 11012103,
          Duration = 3,
          GUID = "1B915126",
          SpeakNpcId = 110010,
          Subtitle = "Some Filthoids picked up the scent. Just fire away.",
          VoiceName = "voice/$Locale$/story/1002/110121/1B915126"
        },
        [11012104] = {
          Content = "好硬的屏障。",
          DialogueId = 11012104,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B915150",
          NextDialogue = 11012105,
          SpeakNpcId = 110022,
          Subtitle = "What a tough barrier...",
          VoiceName = "voice/$Locale$/story/1002/110121/1B915150"
        },
        [11012105] = {
          Content = "连月髓炮都能抗住，工程炼金院那帮人的技术还真是有两下子……",
          DialogueId = 11012105,
          Duration = 3,
          GUID = "1B91517A",
          NextDialogue = 11012106,
          SpeakNpcId = 110010,
          Subtitle = "Took a Phoxichor cannon shot with barely a dent. Those guys at the Aeolipile have some real skills...",
          VoiceName = "voice/$Locale$/story/1002/110121/1B91517A"
        },
        [11012106] = {
          Content = "不要停，继续轰击，记得换高爆弹。",
          DialogueId = 11012106,
          Duration = 3,
          GUID = "1B9151A4",
          NextDialogue = 11012107,
          SpeakNpcId = 110010,
          Subtitle = "Don't stop, keep firing! Use the high explosive shells!",
          VoiceName = "voice/$Locale$/story/1002/110121/1B9151A4"
        },
        [11012107] = {
          Content = "就算轰不破这面屏障，我们也能让里面的家伙自己把门打开。",
          DialogueId = 11012107,
          Duration = 3,
          GUID = "1B9151CE",
          SpeakNpcId = 110010,
          Subtitle = "Even if we fail to tear down the barrier, continious fire can force the enemies from the inside to open the gate themselves.",
          VoiceName = "voice/$Locale$/story/1002/110121/1B9151CE"
        },
        [11012108] = {
          Content = "有什么人从侧边跑出来了——是同盟的家伙！",
          DialogueId = 11012108,
          Duration = 3,
          GUID = "1B9151F8",
          NextDialogue = 11012109,
          SpeakNpcId = 110015,
          Subtitle = "Someone's running out from the side gate — it's the Forsakens!",
          VoiceName = "voice/$Locale$/story/1002/110121/1B9151F8"
        },
        [11012109] = {
          Content = "差不多了，过去看看吧。",
          DialogueId = 11012109,
          Duration = 3,
          GUID = "1B915222",
          SpeakNpcId = 110010,
          Subtitle = "That should do it. Let's go check it out.",
          VoiceName = "voice/$Locale$/story/1002/110121/1B915222"
        },
        [11012110] = {
          Content = "喂，别玩儿了，快来这边！",
          DialogueId = 11012110,
          Duration = 3,
          GUID = "1B91524C",
          SpeakNpcId = 110010,
          Subtitle = "Hey, quit fooling around. Get over here!",
          VoiceName = "voice/$Locale$/story/1002/110121/1B91524C"
        },
        [11012201] = {
          Camera = "-507.54541,-397.79126,-135.757874,0.000019,-8.799681,31.148724,35.0,100000.0,false,Manual,22.0",
          Content = "他们真的自己打开了门……",
          DialogueId = 11012201,
          Duration = 3,
          FinalCamera = "-65.992188,-135.824219,-212.646179,0.000021,-7.799652,29.548767,35.0,100000.0,false,Manual,22.0",
          GUID = "1B91618C",
          NextDialogue = 11012202,
          SpeakNpcId = 110010,
          Subtitle = "They've actually opened the gate from the inside...",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110122/1B91618C"
        },
        [11012202] = {
          Content = "留在里面受到的冲击更大，他们多半撑不住的。",
          DialogueId = 11012202,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91618D",
          NextDialogue = 11012203,
          SpeakNpcId = 110022,
          Subtitle = "The blast impact was far stronger inside. They would've perished had they not opened it.",
          TurnTo = {
            [1] = "110010:n(110022)"
          },
          VoiceName = "voice/$Locale$/story/1002/110122/1B91618D"
        },
        [11012203] = {
          Content = "我和{nickname2}走前面，其他人小心跟上！",
          DialogueId = 11012203,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91618E",
          SpeakNpcId = 110010,
          Subtitle = "Captain  and I are taking the lead. Everyone else, fall in behind us!",
          VoiceName = "voice/$Locale$/story/1002/110122/1B91618E"
        },
        [11012301] = {
          Content = "蹲下干什么？怎么不走了？",
          DialogueId = 11012301,
          Duration = 3,
          GUID = "1B9171F4",
          IsBlack = 1,
          NextDialogue = 11012302,
          SpeakNpcId = 110015,
          Subtitle = "What's wrong? Why squatting down?",
          VoiceName = "voice/$Locale$/story/1002/110123/1B9171F4"
        },
        [11012302] = {
          Content = "卡嘉？",
          DialogueId = 11012302,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9171F5",
          IsBlack = 1,
          SpeakNpcId = 110022,
          Subtitle = "Katya?",
          VoiceName = "voice/$Locale$/story/1002/110123/1B9171F5"
        },
        [11012303] = {
          Content = "我亲爱的长官，别急，请让我稍微准备一下——",
          DialogueId = 11012303,
          Duration = 3,
          GUID = "1B9171F6",
          IsBlack = 1,
          NextDialogue = 11012304,
          SpeakNpcId = 110034,
          Subtitle = "Easy, sir. I'm just doing some preparation—",
          VoiceName = "voice/$Locale$/story/1002/110123/1B9171F6"
        },
        [11012304] = {
          Content = "嗯，准备好啦！",
          DialogueId = 11012304,
          Duration = 3,
          GUID = "1B917220",
          IsBlack = 1,
          SpeakNpcId = 110034,
          Subtitle = "Now, I'm ready.",
          VoiceName = "voice/$Locale$/story/1002/110123/1B917220"
        },
