          GUID = "1B918C60",
          NextDialogue = 11012466,
          Scripts = "PostProcess{MaterailInstance{\"None\"}}",
          SpeakNpcId = 110022,
          Subtitle = "What did you say?",
          TalkActionId = {
            [1] = "110022:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110124/1B918C60"
        },
        [11012466] = {
          Camera = "-270.096924,-220.964355,332.621887,0.000151,-35.795891,35.78912,15.610332,100000.0,false,Manual,22.0",
          Content = "我说了，悄悄话只有一句。呵呵……一路顺风，我的长官。",
          DialogueId = 11012466,
          Duration = 3,
          FacialId = {
            [1] = "110009:Happy02"
          },
          FinalCamera = "-291.60144,-236.469727,351.73877,0.000151,-35.795891,35.78912,15.610332,100000.0,false,Manual,22.0",
          GUID = "1B918C8A",
          LookAt = {
            [1] = "110022:n(110009)",
            [2] = "110009:n(110022)"
          },
          SpeakNpcId = 110009,
          Subtitle = "Secrets are meant to be whispered once. Take care, sir.",
          TalkActionId = {
            [1] = "110009:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110124/1B918C8A"
        },
        [11012467] = {
          Content = "亲爱的，你回来了？该不会是突然反悔，想听悄悄话了？",
          DialogueId = 11012467,
          Duration = 3,
          GUID = "1B918CB4",
          NextDialogue = 11012468,
          SpeakNpcId = 110009,
          Subtitle = "You're back, honey. Changed your mind already? Desperate to hear out the secret?",
          VoiceName = "voice/$Locale$/story/1002/110124/1B918CB4"
        },
        [11012468] = {
          Content = "但是很遗憾，我现在心情不太好，不想说了。",
          DialogueId = 11012468,
          Duration = 3,
          GUID = "1B918CDE",
          SpeakNpcId = 110009,
          Subtitle = "Sorry to disappoint, but I'm no longer in the mood for sharing.",
          VoiceName = "voice/$Locale$/story/1002/110124/1B918CDE"
        },
        [11012469] = {
          Content = "亲爱的，我知道你想问什么。",
          DialogueId = 11012469,
          Duration = 3,
          GUID = "1B918D08",
          NextDialogue = 11012470,
          SpeakNpcId = 110009,
          Subtitle = "I know what you want, honey.",
          VoiceName = "voice/$Locale$/story/1002/110124/1B918D08"
        },
        [11012470] = {
          Content = "但是很遗憾，我这个可怜的阶下囚，现在已经没心情说话了~",
          DialogueId = 11012470,
          Duration = 3,
          GUID = "1B918D32",
          SpeakNpcId = 110009,
          Subtitle = "But I'm just a poor little captive now, not in the mood to talk.",
          VoiceName = "voice/$Locale$/story/1002/110124/1B918D32"
        },
        [11012501] = {
          Content = "<W>没错，就是这样……把剑柄握得紧紧的。是的，你做得很好。你只需要对准它的喉咙——</>",
          DialogueId = 11012501,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B919272",
          Scripts = [[
PARA{PlayNormalSound{EventPath{"event:/sfx/common/story/ex01/evilvo"},PlayAs2D{true}},PostProcess{MaterailInstance{"MaterialInstanceConstant'/Game/Asset/Effect/Material/Post/m_blur_003.m_blur_003'"}}
}]],
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "That's right — you've made the right choice. Grip the hilt tightly. Yes, just like that. Now aim at the creature's throat...",
          VoiceName = "voice/$Locale$/story/1002/110125/1B919272"
        },
        [11012502] = {
          Content = "你……你疯了？",
          DialogueId = 11012502,
          Duration = 3,
          GUID = "1B91929C",
          SpeakNpcId = 110009,
          Subtitle = "Are... Are you insane?",
          VoiceName = "voice/$Locale$/story/1002/110125/1B91929C"
        },
        [11012503] = {
          Content = "<W>对。刺下去，不要犹豫。</>",
          DialogueId = 11012503,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9192C6",
          Scripts = [[
PARA{PlayNormalSound{EventPath{"event:/sfx/common/story/ex01/evilvo"},PlayAs2D{true}},PostProcess{MaterailInstance{"MaterialInstanceConstant'/Game/Asset/Effect/Material/Post/m_blur_003.m_blur_003'"}}
}]],
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Yes, do it. Do not hesitate.",
          VoiceName = "voice/$Locale$/story/1002/110125/1B9192C6"
        },
        [11012504] = {
          Content = "啊……啊啊啊啊啊！！",
          DialogueId = 11012504,
          Duration = 3,
          GUID = "1B9192F0",
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/kill\"},PlayAs2D{true}}",
          SpeakNpcId = 110009,
          Subtitle = "Ahhh... Ahhhhhh!!",
          VoiceName = "voice/$Locale$/story/1002/110125/1B9192F0"
        },
        [11012505] = {
          Content = "{nickname2}……天啊，你做了什么！",
          DialogueId = 11012505,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91931A",
          SpeakNpcId = 110010,
          Subtitle = "...My god, what have you done!?",
          VoiceName = "voice/$Locale$/story/1002/110125/1B91931A"
        },
        [11012506] = {
          Content = "<W>这个人也一起。它是你无用的羁绊。</>",
          DialogueId = 11012506,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B919344",
          Scripts = [[
PARA{PlayNormalSound{EventPath{"event:/sfx/common/story/ex01/evilvo"},PlayAs2D{true}},PostProcess{MaterailInstance{"MaterialInstanceConstant'/Game/Asset/Effect/Material/Post/m_blur_003.m_blur_003'"}}
}]],
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "This one too. The old fool is just dead weight.",
