          },
          VoiceName = "voice/$Locale$/story/1002/110158/1B93AFDA"
        },
        [11015802] = {
          Content = "如审判长大人所见，我是龙莎战役先遣小队的指挥官阿瓦尔·赫德兰……",
          DialogueId = 11015802,
