        },
        [11016602] = {
          Content = "我长话短说。我们没有多少时间了，如果接下来还是联络不上外面，我就用这把枪向你射击，而你要做的是——装死。",
          DialogueId = 11016602,
          GUID = "1B943344",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016602.T_Story_Recall_11016602'",
          NextDialogue = 11016603,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "I'll make this short. Later, I'll shoot you with this gun, and you'll have to play dead.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943344"
        },
        [11016603] = {
          Content = "为了把戏做足，我会打得更真一点。虽然不是要害，但可能会很疼。你一定要忍住，别出声。",
          DialogueId = 11016603,
          GUID = "1B94336E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016602.T_Story_Recall_11016602'",
          NextDialogue = 11016604,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "To make it convincing enough, the shot will have to hit. It will miss your vitals but will really hurt. You must endure the pain silently.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B94336E"
        },
        [11016604] = {
          Content = "您要做什么？",
          DialogueId = 11016604,
          ExStoryInfo = "EXPlayer",
          GUID = "1B943398",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016604.T_Story_Recall_11016604'",
          NextDialogue = 11016605,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          Subtitle = "What are you going to do?",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943398"
        },
        [11016605] = {
          Content = "我们被困在这道门里，和外面的通讯全被切断了。富尔维斯就在路上……算算时间，这会儿他应该已经把持了整座要塞。",
          DialogueId = 11016605,
          GUID = "1B9433C2",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016605.T_Story_Recall_11016605'",
          NextDialogue = 11016606,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "We're trapped in here, with all contact to the outside world cut off. Fulvis is already on his way. We are running out of time.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B9433C2"
        },
        [11016606] = {
          Content = "死人才不会辩解，富尔维斯一定会要我的命。你和我一起行动，又目睹了他构陷的经过，他想必也不会让你活着回去。",
          DialogueId = 11016606,
          GUID = "1B9433EC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016605.T_Story_Recall_11016605'",
          NextDialogue = 11016607,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "Only the dead keep silent forever. Fulvis will definitely kill me. We're both on this mission, and you've seen his fabricated evidence, so he surely won't spare you either.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B9433EC"
        },
        [11016607] = {
          Content = "…………！！",
          DialogueId = 11016607,
          ExStoryInfo = "EXPlayer",
          GUID = "1B943416",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016607.T_Story_Recall_11016607'",
          NextDialogue = 11016608,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          Subtitle = "...!!",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943416"
        },
        [11016608] = {
          Content = "没关系，有我呢。",
          DialogueId = 11016608,
          GUID = "1B943440",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016608.T_Story_Recall_11016608'",
          NextDialogue = 11016609,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "It's okay, I got you.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943440"
        },
        [11016609] = {
          Content = "……如果我“杀了你”，假借内讧向他投诚，他就有可能放松警惕，放过你……这是能让你活下去的唯一方式了。",
          DialogueId = 11016609,
          GUID = "1B94346A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016608.T_Story_Recall_11016608'",
          NextDialogue = 11016610,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "...If I \"kill\" you and feign allegiance to him, it'll lower his guard, allowing you to go unnoticed... It's the only way to ensure your survival.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B94346A"
        },
        [11016610] = {
          Content = "不……老师，等他们打开门，我们就一起杀出去！",
          DialogueId = 11016610,
          ExStoryInfo = "EXPlayer",
          GUID = "1B943494",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016610.T_Story_Recall_11016610'",
          NextDialogue = 11016622,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          Subtitle = "No, Sir Avar... Let's just fight our way out... There's got to be a way out!",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943494"
        },
        [11016612] = {
          Content = "等会儿我会试着先和富尔维斯谈判。当然，多半是谈不拢的，所以别抱希望。我去和他谈判，只是为了一个重要的东西——",
          DialogueId = 11016612,
          GUID = "1B9434E8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016611.T_Story_Recall_11016611'",
          NextDialogue = 11016613,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "I'll try to negotiate with Fulvis, though I believe it's going to fail in the end, so don't get your hopes up. The negotiation is for a more important purpose—",
          VoiceName = "voice/$Locale$/story/1002/110166/1B9434E8"
        },
        [11016613] = {
          Content = "“证据”。",
          DialogueId = 11016613,
          Duration = 3,
          GUID = "1B943512",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016613.T_Story_Recall_11016613'",
          NextDialogue = 11016614,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "To collect evidence.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943512"
        },
        [11016614] = {
          Content = "这是录音设备，你贴身带着。它会成为你日后扳倒富尔维斯的铁证。",
          DialogueId = 11016614,
          GUID = "1B94353C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016614.T_Story_Recall_11016614'",
          NextDialogue = 11016615,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "Take this recording device. It'll provide the evidence needed to expose and destroy Fulvis.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B94353C"
        },
        [11016615] = {
          Content = "决不能让士兵们冤屈的哭号，永远在龙莎要塞上空徘徊。",
          DialogueId = 11016615,
          GUID = "1B943566",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016614.T_Story_Recall_11016614'",
          NextDialogue = 11016616,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "Without it, all you have is your word, which happens to be the most unconvincing evidence. The cries of our fallen comrades will be lost to the winds of Lonza Fortress.",
          VoiceName = "voice/$Locale$/story/1002/110191/1B95CD42"
        },
        [11016616] = {
          Content = "……老师……",
          DialogueId = 11016616,
          Duration = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B943590",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016616.T_Story_Recall_11016616'",
          NextDialogue = 11016617,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          Subtitle = "...Sir Avar...",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943590"
        },
        [11016617] = {
          Content = "别苦着脸，笑一个！战士哪怕面对千万发炮弹，也要笑着一步步向前啊。",
          DialogueId = 11016617,
          GUID = "1B9435BA",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016617.T_Story_Recall_11016617'",
          NextDialogue = 11016618,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "Why the long face? Cheer up, kid! A true soldier laughs at adversity.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B9435BA"
        }
      }
    end
  },
  {
    MinKey = 11016618,
    MaxKey = 11018101,
    Loader = function()
      return {
        [11016618] = {
          Content = "…………",
          DialogueId = 11016618,
          Duration = 2,
          GUID = "1B9435E4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016617.T_Story_Recall_11016617'",
          NextDialogue = 11016619,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1002/110166/1B9435E4"
        },
        [11016619] = {
          Content = "……{nickname2}，我引以为傲的学生啊……抱歉，连累你卷进了这种事。",
          DialogueId = 11016619,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94360E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016619.T_Story_Recall_11016619'",
          NextDialogue = 11016620,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "I'm proud to have been your instructor, ... And I'm sorry for dragging you into this mess.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B94360E"
        },
        [11016620] = {
          Content = "但你一定要活下去，原原本本地将这里的真相带给军团长，带给陛下。你要让全帝国的人知道，这里的每一个士兵，都为了他们的信条与使命，战至最后一刻。",
          DialogueId = 11016620,
          GUID = "1B943638",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016620.T_Story_Recall_11016620'",
          NextDialogue = 11016621,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "You must survive. Bring the truth to Chief Sibylle and His Majesty. Let the entire Empire know that every soldier here held true to their creed and duty, and everyone fought till their very last breath.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943638"
        },
        [11016621] = {
          Content = "……荣耀尽归吾皇。",
          DialogueId = 11016621,
          GUID = "1B943662",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016621.T_Story_Recall_11016621'",
          NextDialogue = 11016701,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "...All glory to our Emperor.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943662"
        },
        [11016622] = {
          Content = "那以你估计，经过这一路的消耗，再加上坐困在此的形势，你我现在和富尔维斯的亲兵硬碰硬，有几成胜算？",
          DialogueId = 11016622,
          GUID = "1B943495",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016611.T_Story_Recall_11016611'",
          NextDialogue = 11016623,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110166/1B943495"
        },
        [11016623] = {
          Content = "对方合围的话……胜算接近于零。但大不了就是一死——",
          DialogueId = 11016623,
          ExStoryInfo = "EXPlayer",
          GUID = "1B943496",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016611.T_Story_Recall_11016611'",
          NextDialogue = 11016624,
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110166/1B943496"
        },
        [11016624] = {
          Content = "死很容易，带着使命活下去却很难。但，{nickname2}，我命令你这么做，这个任务也只有你能完成。",
          DialogueId = 11016624,
          GUID = "1B943497",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016611.T_Story_Recall_11016611'",
          NextDialogue = 11016625,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110166/1B943497"
        },
        [11016625] = {
          Content = "至于我……呵，我这条命比你想象中宝贵，还有别的用呢。",
          DialogueId = 11016625,
          GUID = "1B943498",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016611.T_Story_Recall_11016611'",
          NextDialogue = 11016612,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110166/1B943498"
        },
        [11016701] = {
          Camera = "-5.238281,-133.301758,125.070312,0.001531,-4.805598,92.405151,36.903526,100000.0,false,Manual,22.0",
          Content = "……这就是那天在中央控制室发生的事。",
          DialogueId = 11016701,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-3.560547,-173.319336,128.433594,0.001531,-4.805598,92.405151,36.903526,100000.0,false,Manual,22.0",
          GUID = "1B944382",
          NextDialogue = 11016702,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"},RelatedRegionId{102104}}",
          SpeakNpcId = 110022,
          Subtitle = "...That's exactly what happened in the central control room that day.",
          TalkActionId = {
            [1] = "110039:Sit_Talk03_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/110167/1B944382"
        },
        [11016702] = {
          Camera = "570.384766,-248.601562,159.607712,0.001551,-7.005765,175.00383,19.596729,100000.0,false,Manual,22.0",
          Content = "阿瓦尔老师在最后一刻，面对比他强大千万倍的阴谋和子弹，用自己的生命留下了决定性的证据——这便是他坚守正义的方式。",
          DialogueId = 11016702,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "566.180664,-300.931641,159.606354,0.001551,-7.005704,175.403824,19.596729,100000.0,false,Manual,22.0",
          GUID = "1B9443AC",
          NextDialogue = 11016703,
          SpeakNpcId = 110022,
          Subtitle = "Sir Avar fought valiantly, confronting a conspiracy far greater than any individual could withstand alone. He sacrificed his life to secure crucial evidence — his final act in defence of justice.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/110167/1B9443AC"
        },
        [11016703] = {
          Camera = "-3.560547,-173.319336,123.261719,0.001521,-4.805598,92.405113,36.90353,100000.0,false,Manual,22.0",
          Content = "只可惜他还是低估了敌人的缜密。我半昏迷时，隐约感觉到，富尔维斯的副官法露茜带走了那支录音设备。",
          DialogueId = 11016703,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9443D6",
          NextDialogue = 11016704,
          SpeakNpcId = 110022,
          Subtitle = "But, we underestimated the enemy's meticulousness. As I drifted in and out of consciousness, I sensed Fulvis's adjutant, Falsi, removing the recording device from me.",
          VoiceName = "voice/$Locale$/story/1002/110167/1B9443D6"
        },
        [11016704] = {
          Camera = "299.907227,-246.0,95.800987,-0.000854,42.006584,-179.996628,36.931984,100000.0,false,Manual,22.0",
          Content = "醒来后，富尔维斯已经接管了整座要塞，此时和他们硬拼只会让我和达芙涅送命……真相也将石沉大海。",
          DialogueId = 11016704,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "299.907227,-268.0,95.800987,-0.000854,42.006584,-179.996628,36.931984,100000.0,false,Manual,22.0",
          GUID = "1B944400",
          NextDialogue = 11019102,
          SpeakNpcId = 110022,
          Subtitle = "By the time I fully regained consciousness, Fulvis had seized control of the fortress. Confronting him would have led to our deaths, and the truth would have been buried with us.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/110167/1B944400"
        },
        [11016705] = {
          Camera = "76.907227,-660.533203,98.932999,-0.000916,-2.393981,100.607307,48.616428,100000.0,false,Manual,22.0",
          Content = "所以，我们选择用这种方式来见你。我相信，以你的手段，一定能得到那份证据，或者至少，得到法露茜的供词。",
          DialogueId = 11016705,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94442A",
          SpeakNpcId = 110022,
          Subtitle = "That's why we decided to come to you like this. I believe that you have the authority to recover that evidence, or at least secure a testimony from Falsi.",
          VoiceName = "voice/$Locale$/story/1002/110167/1B94442A"
        },
        [11016706] = {
          Camera = "101.0,-126.956055,72.582031,-0.000917,13.404778,137.606186,36.480843,100000.0,false,Manual,22.0",
          Content = "海尔法典狱长，你言必称正义，我想你应该明白应当怎么坚守你的正义了。去抓捕法露茜吧，你想要的真相就在那里。",
          DialogueId = 11016706,
          ExStoryInfo = "EXPlayer",
          GUID = "1B944454",
          NextDialogue = 11019104,
          Scripts = "CameraMoveTo{_delay{8},TargetPosition{\"84.478516,223.710938,83.84375,-0.000915,3.004334,-104.392136,52.299129,100000.0,false,Manual,22.0\"},duration{0}}",
          SpeakNpcId = 110022,
          Subtitle = "Warden Hellfire, I know you hold justice above all else, and I believe you possess the means to defend it. Please, go get Falsi. She holds the truth you want.",
          TalkActionId = {
            [1] = "110022:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110167/1B944454"
        },
        [11016707] = {
          Camera = "15.709961,-308.188477,107.445312,-0.000916,-1.595662,-98.792236,35.182564,100000.0,false,Manual,22.0",
          Content = "海伯利亚是一架巨大的机器，它需要能让每颗螺钉都正确运转的规律。",
          DialogueId = 11016707,
          GUID = "1B94447E",
          NextDialogue = 11016708,
          SpeakNpcId = 110039,
          Subtitle = "Hyperborea functions like a vast machine, requiring every component to operate flawlessly.",
          TalkActionId = {
            [1] = "110022:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110167/1B94447E"
        },
        [11016708] = {
          Camera = "-23.03125,453.560547,337.066406,-0.000917,-19.995569,-87.991684,27.483999,100000.0,false,Manual,22.0",
          Content = "我的职责便是保护这条规律，保护海伯利亚订下的“正义”。如果有人想要利用我的手摧毁这条规律，我便会让他付出应有的代价。",
          DialogueId = 11016708,
          FinalCamera = "-17.12207,284.929688,275.703125,-0.000917,-19.995569,-87.991684,27.483999,100000.0,false,Manual,22.0",
          GUID = "1B9444A8",
          NextDialogue = 11016709,
          SpeakNpcId = 110039,
          Subtitle = "My role is to uphold the law and protect the justice defined by Hyperborea. If anyone attempts to manipulate me to subvert this law, they will face severe consequences.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/110167/1B9444A8"
        },
        [11016709] = {
          Camera = "-5.833984,-339.387695,101.292969,-0.000916,-0.200104,-90.570984,21.509014,135.908142,false,Manual,22.0",
          Content = "我会去调查法露茜。但如果你在用谎言拖延时间，想必你清楚后果。",
          DialogueId = 11016709,
          FinalCamera = "-6.027344,-359.292969,101.292969,-0.000916,-0.200104,-90.570984,21.509014,119.777908,false,Manual,22.0",
          GUID = "1B9444D2",
          NextDialogue = 11016710,
          Scripts = "PlayAnimation{ActorId{110039},AnimationId{\"Sit_Talk02_Start\"},Duration{8}}",
          SpeakNpcId = 110039,
          Subtitle = "I will investigate Falsi. Be aware of the consequences if what you said proves to be false and a waste of my time.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110167/1B9444D2"
        },
        [11016710] = {
