MoveTo{ActorId{110021},TargetPoint{"fix27jt"},MoveSpeed{150},Visibility{"Show"}},
SitOrStand{ActorId{110040},State{"Sit"}}
}]],
          SpeakNpcId = 110021,
          Subtitle = ", Warden Hellfire has instructed me to bring Miss Theodore here.",
          VoiceName = "voice/$Locale$/story/1002/110168/1B9453EA"
        },
        [11016802] = {
          Camera = "164.65332,366.744141,129.46875,0.000159,-1.392819,123.993523,35.0,150.488785,false,DoNotOverride,22.0",
          Content = "审讯的时候，她一直请求见你。",
          DialogueId = 11016802,
          FacialId = {
            [1] = "110041:Iyada01"
          },
          FinalCamera = "151.226562,386.651367,128.910156,0.000159,-1.392819,123.993523,35.0,150.488785,false,DoNotOverride,22.0",
          GUID = "1B945414",
          LookAt = {
            [1] = "110041:n(110021)"
          },
          NextDialogue = 11016803,
          Scripts = [[
SEQ{
SetLocation{ActorId{110005},TargetPoint{"fix27jt"},Visibility{"Hide"}},
}]],
          SpeakNpcId = 110021,
          Subtitle = "During her interrogation, she repeatedly requested to see you.",
          TalkActionId = {
            [1] = "110041:Sit_Idle_Loop"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110168/1B945414"
        },
        [11016803] = {
          DialogueId = 11016803,
          DialoguePanelType = "None",
          Duration = 3,
          FinalCamera = "57.932617,221.332031,127.285156,0.000213,-1.992188,-91.39418,35.0,150.488785,false,DoNotOverride,22.0",
          GUID = "1B94543E",
          IsBlack = 1,
          NextDialogue = 11016804,
          VoiceName = "voice/$Locale$/story/1002/110168/1B94543E"
        },
        [11016804] = {
          Camera = "58.552734,246.993164,128.183594,0.000213,-1.992202,-91.39418,35.0,150.488785,false,DoNotOverride,22.0",
          Content = "…………",
          DialogueId = 11016804,
          Duration = 1,
          FinalCamera = "57.932617,221.332031,127.285156,0.000213,-1.992188,-91.39418,35.0,150.488785,false,DoNotOverride,22.0",
          GUID = "1B945468",
          NextDialogue = 11016805,
          Scripts = "PlayAnimation{ActorId{110041},AnimationId{\"Sit_Talk03_Start\"},Duration{1}}",
          SpeakNpcId = 110041,
          Subtitle = "...",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110168/1B945468"
        },
        [11016805] = {
          Content = "……怎么直接当面说出来了……",
          DialogueId = 11016805,
          GUID = "1B945492",
          LookAt = {
            [1] = "110040:n(110041)"
          },
          NextDialogue = 11016806,
          SpeakNpcId = 110041,
          Subtitle = "...You weren't supposed to know that part...",
          VoiceName = "voice/$Locale$/story/1002/110168/1B945492"
        },
        [11016806] = {
          Content = "那、那个，我也不知道为什么，从今天下午开始，审问官突然变温和了许多，甚至还主动问我有什么特别想实现的心愿。",
          DialogueId = 11016806,
          GUID = "1B9454BC",
          LookAt = {
            [1] = "110041:n(110040)"
          },
          NextDialogue = 11016807,
          SpeakNpcId = 110041,
          Subtitle = "Well, I don't know what happened, but the interrogator seemed much more accommodating this afternoon. She even asked if I wanted anything.",
          TalkActionId = {
            [1] = "110041:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110168/1B9454BC"
        },
        [11016807] = {
          Content = "但我的供词一直都是那些……是您说了什么，打动了典狱长吗？",
          DialogueId = 11016807,
          FacialId = {
            [1] = "110041:Smile01"
          },
          GUID = "1B9454E6",
          NextDialogue = 11016808,
          Scripts = "CameraMoveTo{_delay{4},TargetPosition{\"97.759766,656.613281,129.179688,0.000218,-0.592225,-99.797882,40.0,150.488785,false,DoNotOverride,22.0\"},duration{0}}",
          SpeakNpcId = 110041,
          Subtitle = "My testimony hasn't changed... Did you say something that swayed the Warden?",
          VoiceName = "voice/$Locale$/story/1002/110168/1B9454E6"
        },
        [11016808] = {
          Camera = "208.457031,192.4375,122.078125,0.00018,1.007186,-146.99411,35.0,150.488785,false,DoNotOverride,22.0",
          Content = "……还是说——难道，这是死刑之前最后的怜悯？！",
          DialogueId = 11016808,
          FacialId = {
            [1] = "110041:Iyada01"
          },
          FinalCamera = "175.138672,170.794922,122.734375,0.00018,1.007186,-146.99411,35.0,150.488785,false,DoNotOverride,22.0",
          GUID = "1B945510",
          NextOptions = {
            [1] = 11016809,
            [2] = 11016815
          },
          SpeakNpcId = 110041,
          Subtitle = "...Or is this some sort of final kindness before our execution!?",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110168/1B945510"
        },
        [11016809] = {
          Content = "没错，我认罪了，我们就要被处决了。",
          DialogueId = 11016809,
          GUID = "1B94553A",
          ImprPlusId = 1010,
          NextDialogue = 11016810,
          Subtitle = "You're right. I pleaded guilty. We'll be executed soon."
        },
        [11016810] = {
          Camera = "63.871094,234.428711,141.222656,0.000184,-7.192995,-92.993393,35.0,150.488785,false,DoNotOverride,22.0",
          Content = "……是吗……我明白了。这也是没办法的事，毕竟他们的拷问真的很疼。",
          DialogueId = 11016810,
          GUID = "1B945564",
          NextDialogue = 11016811,
          SpeakNpcId = 110041,
          Subtitle = "...Really...? I see. I suppose you had no other choice. No one can withstand such intense interrogation.",
          VoiceName = "voice/$Locale$/story/1002/110168/1B945564"
        },
        [11016811] = {
          Camera = "143.042969,124.328125,135.328125,0.000179,-4.592988,-161.391342,35.0,150.488785,false,DoNotOverride,22.0",
          Content = "没关系的，您已经保护我够久了。所以，没关系的。",
          DialogueId = 11016811,
          FacialId = {
            [1] = "110041:Pain01"
          },
          GUID = "1B94558E",
          LookAt = {
            [1] = "110041:n(110040)",
            [2] = "110040:n(110041)"
          },
          NextDialogue = 11016812,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{110041},AnimationId{"Sit_Talk03_Start"},Duration{1}}
}]],
          SpeakNpcId = 110041,
          Subtitle = "It's alright. You've done so much to protect me already...",
          VoiceName = "voice/$Locale$/story/1002/110168/1B94558E"
        },
        [11016812] = {
          Camera = "69.114258,343.46875,128.84375,0.000188,-1.793054,97.209267,35.0,150.488785,false,DoNotOverride,22.0",
          Content = "不要真信，我开个玩笑……",
          DialogueId = 11016812,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110041:Sad01",
            [2] = "110040:Sad01"
          },
          GUID = "1B9455B8",
          NextDialogue = 11016813,
          SpeakNpcId = 110040,
          Subtitle = "It's not true. I was just messing with you...",
          TalkActionId = {
            [1] = "110040:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110168/1B9455B8"
        },
        [11016813] = {
          Camera = "79.359375,250.193359,124.222656,0.000161,0.407284,-99.607933,35.0,150.488785,false,DoNotOverride,22.0",
          Content = "你这个人真是的——吓死我了……你、你要给我道歉的……",
          DialogueId = 11016813,
          FacialId = {
            [1] = "110040:Unhappy01"
          },
          FinalCamera = "73.981445,218.426758,124.433594,0.000161,0.407284,-99.607933,35.0,150.488785,false,DoNotOverride,22.0",
          GUID = "1B9455E2",
          NextDialogue = 11016814,
          Scripts = [[
PARA{
CameraMoveTo{_delay{0.3},TargetPosition{"72.458008,209.397461,124.488281,0.000158,0.407284,-99.607986,35.0,150.488785,false,DoNotOverride,22.0"},duration{3}},
SEQ{
PlayAnimation{_delay{4},ActorId{110041},AnimationId{"Sit_Talk03_End"},Duration{1}}}
}]],
          SpeakNpcId = 110041,
          Subtitle = "Wha... You really scared me... Y—You owe me an apology...",
          TalkActionId = {
            [1] = "110040:Sit_Talk02_End"
          },
          ToFinalCameraBlendTime = 0.3,
          VoiceName = "voice/$Locale$/story/1002/110168/1B9455E2"
        },
        [11016814] = {
          Camera = "85.217773,355.307617,126.359375,0.000139,-0.195576,100.594894,35.0,298.040161,false,Manual,15.739686",
          Content = "如果海尔法的调查顺利，我想过不了多久我们就能出去了。到时候，请你看场歌剧作为赔礼吧。",
          DialogueId = 11016814,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110040:None"
          },
          GUID = "1B94560C",
          NextDialogue = 11016820,
          Scripts = "PlayAnimation{_delay{6},ActorId{110040},AnimationId{\"Sit_Talk02_Start\"},Duration{1}}",
          SpeakNpcId = 110040,
          Subtitle = "If Warden Hellfire's investigation goes well, we'll be free soon. I'll make it up to you by taking you to the opera house.",
          VoiceName = "voice/$Locale$/story/1002/110168/1B94560C"
        },
        [11016815] = {
          Content = "典狱长相信了我的证词，她去调查法露茜了。",
          DialogueId = 11016815,
          GUID = "1B945636",
          ImprPlusId = 1009,
          NextDialogue = 11016816,
          Subtitle = "The Warden believed what I said and went to investigating Falsi."
        },
        [11016816] = {
          Camera = "77.791992,275.038086,116.648438,0.000166,0.404306,-96.204185,35.0,298.040161,false,Manual,15.739686",
          Content = "太好了。",
          DialogueId = 11016816,
          FacialId = {
            [1] = "110041:Smile01"
          },
          GUID = "1B945660",
          NextDialogue = 11016817,
          SpeakNpcId = 110041,
          Subtitle = "Oh, that's great.",
          VoiceName = "voice/$Locale$/story/1002/110168/1B945660"
        },
        [11016817] = {
          Camera = "140.551758,369.635742,116.640625,0.000213,2.207462,117.81002,35.0,150.488785,false,DoNotOverride,22.0",
          Content = "……你身上又多了好多伤，很痛吧……我、我去求他们把医药箱还给我……",
          DialogueId = 11016817,
          GUID = "1B94568A",
          NextDialogue = 11016818,
          SpeakNpcId = 110041,
          Subtitle = "...You've got a lot more injuries. They must hurt... I... I'll beg them to give me back my first-aid kit...",
          VoiceName = "voice/$Locale$/story/1002/110168/1B94568A"
        },
        [11016818] = {
          Content = "我还好，你先给自己治疗一下吧……",
          DialogueId = 11016818,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110040:Smile02"
          },
          GUID = "1B9456B4",
          NextDialogue = 11016819,
          SpeakNpcId = 110040,
          Subtitle = "I'm fine. You should take care of your own injuries though...",
          TalkActionId = {
            [1] = "110040:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110168/1B9456B4"
        },
        [11016819] = {
          Camera = "70.556641,275.821289,116.648438,0.000166,0.404306,-96.204208,35.0,298.040161,false,Manual,15.739686",
          Content = "……如果海尔法典狱长的调查顺利，我想过不了多久我们就能出去了。",
          DialogueId = 11016819,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110041:Smile01"
          },
          GUID = "1B9456DE",
          NextDialogue = 11016820,
          SpeakNpcId = 110040,
          Subtitle = "...If Warden Hellfire's investigation goes well, we'll be free soon.",
          VoiceName = "voice/$Locale$/story/1002/110168/1B9456DE"
        },
        [11016820] = {
          Camera = "70.556641,275.821289,116.648438,0.000166,0.404306,-96.204208,35.0,298.040161,false,Manual,15.739686",
          Content = "嗯……",
          DialogueId = 11016820,
          FacialId = {
            [1] = "110041:Smile01"
          },
          GUID = "1B945708",
          NextDialogue = 11016821,
          SpeakNpcId = 110041,
          Subtitle = "I hope so...",
          TalkActionId = {
            [1] = "110040:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110168/1B945708"
        },
        [11016821] = {
          Camera = "575.697266,-116.007812,144.9375,0.000189,-2.195585,142.396973,35.0,298.040161,false,Manual,15.739686",
          Content = "……还有一件事。抱歉，虽然可能会让您想起不快的回忆，但我很怕以后再也没有机会问了。",
          DialogueId = 11016821,
          FacialId = {
            [1] = "110041:Sad01"
          },
          FinalCamera = "656.711914,-178.397461,148.828125,0.000189,-2.195585,142.396973,35.0,298.040161,false,Manual,15.739686",
          GUID = "1B945732",
          NextDialogue = 11016822,
          Scripts = [[
PARA{
CameraMoveTo{_delay{6},TargetPosition{"130.480469,196.420898,116.089844,0.000191,3.395519,-130.203705,35.000011,150.488785,false,Manual,22.0"},duration{0}},
PlayAnimation{ActorId{110041},AnimationId{"Sit_Talk03_Start"},Duration{1}}
}]],
          SpeakNpcId = 110041,
          Subtitle = "...And one more thing. I'm sorry, this might bring back painful memories, but I must ask while I can.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/110168/1B945732"
        },
        [11016822] = {
          Camera = "319.923828,100.185547,570.714844,0.000388,-57.783604,139.785599,14.723656,298.040161,false,Manual,16.645706",
          Content = "上次在要塞里，情况危急，您没有告诉我父亲的事。现在我已经整理好了心情，可以请您讲给我听吗？父亲他最后……有没有留下什么？",
          DialogueId = 11016822,
          FacialId = {
            [1] = "110040:None"
          },
          FinalCamera = "388.981445,216.772461,570.714844,0.00043,-57.782646,164.184372,14.723656,298.040161,false,Manual,16.645706",
          GUID = "1B94575C",
          NextDialogue = 11016823,
          SpeakNpcId = 110041,
          Subtitle = "Back at the fortress, the situation was so desperate that you didn't have time to tell me about my father's death. But I've sorted out my mood. Can you tell me about it now? Did my father... leave anything behind?",
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/story/1002/110168/1B94575C"
        },
        [11016823] = {
          Camera = "155.694336,479.422852,136.015625,0.000339,-1.994654,152.595154,35.000008,116.258575,false,Manual,9.707766",
          Content = "…………",
          DialogueId = 11016823,
          Duration = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B945786",
          NextDialogue = 11016824,
          SpeakNpcId = 110040,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1002/110168/1B945786"
        },
        [11016824] = {
          Camera = "153.564453,378.640625,135.929688,0.000189,-3.592713,124.006393,35.0,150.488785,false,DoNotOverride,22.0",
          Content = "他留下了这个。这张照片被他藏在贴身口袋里，最靠近心脏的位置。",
          DialogueId = 11016824,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9457B0",
          SpeakNpcId = 110040,
          Subtitle = "Sir Avar kept this with him at all times, in the pocket closest to his heart.",
          TalkActionId = {
            [1] = "110040:Sit_Talk02_Start",
            [2] = "110041:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110168/1B9457B0"
        },
        [11016825] = {
          Camera = "159.3125,228.97168,103.3125,0.000155,7.203923,-128.800171,35.000008,150.488785,false,Manual,22.0",
          Content = "还有一句话，是他最后对我说的——",
          DialogueId = 11016825,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110041:Sad01"
          },
          GUID = "1B9457DA",
          NextDialogue = 11016826,
          Scripts = "PlayAnimation{ActorId{110041},AnimationId{\"Sit_Talk03_Start\"},Duration{1}}",
          SpeakNpcId = 110040,
          Subtitle = "He wanted you to have this message—",
          TalkActionId = {
            [1] = "110041:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110168/1B9457DA"
        },
        [11016826] = {
          Camera = "92.726562,649.960938,135.03125,0.000137,-2.595936,-96.005997,35.000008,150.488785,false,Manual,22.0",
          Content = "“有机会的话，请你找到达芙涅。如果她还活着，带她一起……逃出去。等安全了，告诉她——”",
          DialogueId = 11016826,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "88.107422,606.015625,133.039062,0.000137,-2.595936,-96.005997,35.000008,150.488785,false,Manual,22.0",
          GUID = "1B945804",
          NextDialogue = 11016827,
          SpeakNpcId = 110040,
          SpeakNpcName = "UI_Npc_AwaAndMe",
          Subtitle = "\"Find Daphne if possible. If she's alive, get her out of here... Once you're both safe, tell her—\"",
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/story/1002/110168/1B945804"
        },
        [11016827] = {
          Camera = "244.314453,274.294922,106.882812,0.000178,2.404472,-134.798203,35.000008,298.040161,false,Manual,15.739686",
          Content = "“对不起，我的女儿。其实我一直等着，你再叫我一声‘爸爸’，像小时候一样。”",
          DialogueId = 11016827,
          FacialId = {
            [1] = "110041:Sad01"
          },
          FinalCamera = "195.5,309.150391,106.882812,0.000179,2.804441,-121.197876,35.000008,298.040161,false,Manual,15.739686",
          GUID = "1B94582E",
          NextDialogue = 11016828,
          Scripts = [[
SEQ{
PlayAnimation{_delay{6},ActorId{110041},AnimationId{"Sit_Talk03_End"},Duration{1}}
}]],
          SpeakNpcId = 110010,
          Subtitle = "\"I'm sorry, my baby girl. I've always wanted to hear you call me Dad again, just like when you were little.\"",
          TalkActionId = {
            [1] = "110040:Sit_Talk02_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110168/1B94582E"
        },
        [11016828] = {
          Camera = "112.149414,184.543945,122.972656,0.000185,1.604425,-123.80542,44.331501,298.040161,false,Manual,15.739686",
          Content = "……他……怎么还留着这张呢……",
          DialogueId = 11016828,
          FacialId = {
            [1] = "110041:Sad02"
          },
          GUID = "1B945858",
          NextDialogue = 11016829,
          SpeakNpcId = 110041,
          Subtitle = "...He... kept this photo all along...",
          VoiceName = "voice/$Locale$/story/1002/110168/1B945858"
        },
        [11016829] = {
          Camera = "350.745117,705.481445,547.363281,0.000123,-42.805061,-126.604477,20.017895,150.488785,false,Manual,22.0",
          Content = "明明……我都已经长这么大了……",
          DialogueId = 11016829,
          GUID = "1B945882",
          NextDialogue = 11016830,
          SpeakNpcId = 110041,
          Subtitle = "So long that... I'm not the little girl in the photo anymore...",
          VoiceName = "voice/$Locale$/story/1002/110168/1B945882"
        },
        [11016830] = {
          Camera = "-163.704102,790.329102,151.175781,0.000172,-2.604426,-61.00597,35.0,150.488785,false,Manual,22.0",
          Content = "好了，达芙涅小姐，你们通过了典狱长的又一次考验，可以请你先离开了。",
          DialogueId = 11016830,
          GUID = "1B9458AC",
          LookAt = {
            [1] = "110040:n(110021)",
            [2] = "110041:n(110021)"
          },
          NextDialogue = 11016831,
          SpeakNpcId = 110021,
          Subtitle = "Alright. Both of you have again passed the Warden's test. Miss Daphne, you may leave now.",
          TalkActionId = {
            [1] = "110021:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110168/1B9458AC"
        },
        [11016831] = {
          Content = "你在偷听？",
          DialogueId = 11016831,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9458D6",
          NextDialogue = 11016832,
          SpeakNpcId = 110040,
          Subtitle = "Were you eavesdropping on us?",
          TalkActionId = {
            [1] = "110021:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110168/1B9458D6"
        },
        [11016832] = {
          Camera = "622.149414,9.680664,136.84375,0.000179,1.395483,-140.405182,35.000008,150.488785,false,Manual,22.0",
          Content = "是典狱长的命令。把你们单独关在一起，监听你们到底在谈些什么。",
          DialogueId = 11016832,
          GUID = "1B945900",
          LookAt = {
            [1] = "110041:p(fix27floor2)"
          },
          NextDialogue = 11016833,
          SpeakNpcId = 110021,
          Subtitle = "Per the Warden's orders. I was to confine you both here and monitor your interactions.",
          VoiceName = "voice/$Locale$/story/1002/110168/1B945900"
        },
        [11016833] = {
          Camera = "148.842773,223.691406,110.460938,0.000203,3.804395,-124.205971,35.000015,150.488785,false,Manual,22.0",
          Content = "“如果是犯人的话，现在很可能在串通口供”……我明白了，谢谢海尔法大人给我们这个自证的机会。",
          DialogueId = 11016833,
          FacialId = {
            [1] = "110041:None"
          },
          GUID = "1B94592A",
          LookAt = {
            [1] = "110040:n(110041)"
          },
          NextDialogue = 11016834,
          Scripts = [[
PARA{
LookAt{_delay{6},LookAtDescription{"110041:n(110040)"}}
}]],
          SpeakNpcId = 110041,
          Subtitle = "Right, if we were guilty, we'd make use of every opportunity to collude in our testimonies... I understand. Thank you for giving us a chance to prove our innocence.",
          VoiceName = "voice/$Locale$/story/1002/110168/1B94592A"
        },
        [11016834] = {
          Content = "也许……我们很快就能走出这里了。",
          DialogueId = 11016834,
          FacialId = {
            [1] = "110041:Smile01"
          },
          GUID = "1B945954",
          SpeakNpcId = 110041,
          Subtitle = "Perhaps... we'll leave this place soon.",
          VoiceName = "voice/$Locale$/story/1002/110168/1B945954"
        },
        [11016901] = {
          Camera = "-10.047852,143.882812,126.195312,0.000104,2.803007,-30.809227,35.000015,100000.0,false,Manual,22.0",
          Content = "你们走不出这里了。",
          DialogueId = 11016901,
          GUID = "1B946452",
          NextDialogue = 11016902,
          Scripts = [[
PARA{
MoveTo{ActorId{110032},TargetPoint{"28Point1"},MoveSpeed{150},Visibility{"Show"}},
PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/mute"},RelatedRegionId{102104}},
LookAt{_delay{1},LookAtDescription{"110041:n(110032)"}},
LookAt{_delay{1},LookAtDescription{"110032:n(110041)"}}
}]],
          SpeakNpcId = 110032,
          Subtitle = "Neither of you are leaving.",
          TalkActionId = {
            [1] = "110041:Sit_Talk03_Start",
            [2] = "110040:Sit_Idle_Loop"
          },
          VoiceName = "voice/$Locale$/story/1002/110169/1B946452"
        },
        [11016902] = {
          Camera = "-208.583008,316.085938,130.757812,0.000093,-1.996942,-93.205887,35.000008,100000.0,false,Manual,22.0",
          Content = "…………？！",
          DialogueId = 11016902,
          Duration = 2,
          FacialId = {
            [1] = "110041:Angry01"
          },
          GUID = "1B94647C",
          NextDialogue = 11016903,
          Scripts = [[
SEQ{
MoveTo{ActorId{110032},TargetPoint{"28Point2"},MoveSpeed{180},Visibility{"Show"}},
SetRotation{SetRotationDescription{"110032:n(110041)"}}
}]],
          SpeakNpcId = 110041,
          Subtitle = "...?!",
          VoiceName = "voice/$Locale$/story/1002/110169/1B94647C"
        },
        [11016903] = {
          Camera = "-342.746094,140.6875,121.378906,0.000104,2.002775,27.177742,35.000011,530.09375,false,Manual,22.0",
          Content = "上头加急走完了所有审核流程，到我手里的，只有一张要你们命的纸。",
          DialogueId = 11016903,
          FacialId = {
            [1] = "110032:Angry01"
          },
          GUID = "1B9464A6",
          LookAt = {
            [1] = "110041:n(110032)",
            [2] = "110040:n(110032)"
          },
          NextDialogue = 11016904,
          Scripts = [[
SEQ{
SetLocation{ActorId{110032},TargetPoint{"28Point2"},Visibility{"Show"}}
}]],
          SpeakNpcId = 110032,
          Subtitle = "A directive to expedite all procedural reviews has been issued from above. The only document I received is a writ demanding your immediate execution.",
          TalkActionId = {
            [1] = "110032:Explain01_Start",
            [2] = "110041:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110169/1B9464A6"
        },
        [11016904] = {
          Camera = "-189.967773,373.448242,157.484375,0.000144,1.603148,-97.005592,40.0,530.095764,false,Manual,22.0",
          Content = "典狱长大人，这不对——这不符合审判的流程！",
          DialogueId = 11016904,
          Duration = 2,
          FacialId = {
            [1] = "110041:Angry01"
          },
          GUID = "1B9464D0",
          NextDialogue = 11016905,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{110041},AnimationId{"Sit_Idle_End"},Duration{2}},
TurnTo{TurnToDescription{"110041:n(110032)"}},
PlayAnimation{ActorId{110041},AnimationId{"Angry01_Start"},Duration{2}},
CameraMoveTo{TargetPosition{"246.750977,635.553711,145.472656,0.000125,-0.197017,-132.803497,35.000008,530.095764,false,Manual,22.0"},duration{0}}
}]],
          SpeakNpcId = 110041,
          Subtitle = "Ma'am, this is not right — it goes against the standard procedures of interrogation.",
          VoiceName = "voice/$Locale$/story/1002/110169/1B9464D0"
        },
        [11016905] = {
          Camera = "-650.21875,847.072266,405.632812,0.000051,-26.194887,-39.601955,26.0,530.095764,false,Manual,22.0",
          Content = "看看这份文件吧，最后这串签名。连最高法务大臣都签了，西比尔也拦不下。你们真是卷进了了不得的事。",
          DialogueId = 11016905,
          FacialId = {
            [1] = "110041:Unacceptable01"
          },
          FinalCamera = "-650.21875,847.072266,405.632812,0.000047,-22.794765,-43.20211,26.0,530.095764,false,Manual,22.0",
          GUID = "1B9464FA",
          NextDialogue = 11016906,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{110032},AnimationId{"Explain01_End"},Duration{2}},
PlayAnimation{_delay{4},ActorId{110032},AnimationId{"DisagreeHead"},Duration{2}}
}]],
          SpeakNpcId = 110032,
          Subtitle = "Take a look at the writ and the signatures at the bottom. Even the Supreme Minister of Justice has signed it. Not even Chief Sibylle can stop it. Your case has grown beyond anyone's control.",
          TalkActionId = {
            [1] = "110041:Angry01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110169/1B9464FA"
        },
        [11016906] = {
          Camera = "-89.286133,352.804688,215.699219,0.000116,-15.397158,119.181168,35.000011,530.095764,false,Manual,22.0",
          Content = "法露茜呢？只要能找到法露茜，找到那支录音设备，真相就……！",
          DialogueId = 11016906,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110040:Angry01"
          },
          GUID = "1B946524",
          NextDialogue = 11016907,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{110040},AnimationId{"Sit_Idle_End"},Duration{2}},
PlayAnimation{ActorId{110040},AnimationId{"Explain01_Start"},Duration{2}}
}]],
          SpeakNpcId = 110040,
          Subtitle = "What about Falsi? As long as we find Falsi and the recording device, we can prove that...",
          VoiceName = "voice/$Locale$/story/1002/110169/1B946524"
        },
        [11016907] = {
          Camera = "-119.676758,376.845703,212.484375,0.000182,-19.996178,5.170751,35.000015,530.095764,false,Manual,22.0",
          Content = "她失踪了。",
          DialogueId = 11016907,
          FacialId = {
            [1] = "110032:None"
          },
          GUID = "1B94654E",
          LookAt = {
            [1] = "110032:n(110040)"
          },
          NextDialogue = 11016908,
          SpeakNpcId = 110032,
          Subtitle = "She's missing.",
          TalkActionId = {
            [1] = "110040:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110169/1B94654E"
        },
        [11016908] = {
          Content = "在龙莎一役的一场爆炸中，她不慎跌落到要塞外。士兵们在河岸发现了她染血的配枪。虽然军团仍在搜寻她的下落，但依照目前推测，她很可能已经死亡。",
          DialogueId = 11016908,
          GUID = "1B946578",
          NextDialogue = 11016909,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{110032},AnimationId{"Talk01_Start"},Duration{2}},
PlayAnimation{_delay{2},ActorId{110032},AnimationId{"Talk01_End"},Duration{2}},
CameraMoveTo{_delay{1},TargetPosition{"-537.025391,515.268555,271.632812,0.000282,-18.459036,-12.635934,15.000007,100000.0,false,Manual,22.0"},duration{0}},
CameraMoveTo{_delay{0},TargetPosition{"-564.171875,461.899414,229.765625,0.000282,-18.459036,-12.635994,15.000007,100000.0,false,Manual,22.0"},duration{15}}
}]],
          SpeakNpcId = 110032,
          Subtitle = "An explosion occurred during the battle. Falsi was last seen outside the fortress. Her bloodstained pistol was found along the riverbank. Although the Legion continues to search, it is likely that she is deceased.",
          VoiceName = "voice/$Locale$/story/1002/110169/1B946578"
        },
        [11016909] = {
          Camera = "-167.293945,332.791992,154.449219,0.000129,2.60293,-109.422783,35.000011,530.09375,false,Manual,22.0",
          Content = "……典狱长大人，您真的相信这种巧合吗？",
          DialogueId = 11016909,
          GUID = "1B9465A2",
          LookAt = {
            [1] = "110032:n(110041)"
          },
          NextDialogue = 11016910,
          SpeakNpcId = 110041,
          Subtitle = "...Ma'am, do you really believe in such a coincidence?",
          TalkActionId = {
            [1] = "110041:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110169/1B9465A2"
        },
        [11016910] = {
          Camera = "-82.495117,382.399414,154.101562,0.000099,-3.197143,-0.828277,35.000008,530.095764,false,Manual,22.0",
          Content = "…………",
          DialogueId = 11016910,
          Duration = 2,
          GUID = "1B9465CC",
          NextDialogue = 11017001,
          SpeakNpcId = 110032,
          Subtitle = "...",
          TalkActionId = {
            [1] = "110041:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110169/1B9465CC"
        },
        [11017001] = {
          Content = "维吉尔亲王殿下！这是审讯犯人的肮脏地方，请您留步！",
          DialogueId = 11017001,
          GUID = "1B9474BA",
          Scripts = "LookAt{_delay{0.6},LookAtDescription{\"110032:p(28Point3)\"}}",
          SnapShot = "OUTDOOR",
          SpeakNpcName = "UI_Npc_EnemySoldier",
          Subtitle = "Your Royal Highness Prince Vergilius! This place isn't fitting for someone of your stature. Please don't proceed any further!",
          VoiceName = "voice/$Locale$/story/1002/110170/1B9474BA"
        },
        [11017003] = {
          Content = "凑齐这么多签名，可真不容易。",
          DialogueId = 11017003,
          Duration = 3,
          GUID = "1B94750E",
          SpeakNpcId = 110018,
          Subtitle = "Gathering so many signatures must have been quite the feat.",
          VoiceName = "voice/$Locale$/story/1002/110170/1B94750E"
        },
        [11017004] = {
          Content = "可惜这么多签名，应该都没我这个管用吧？",
          DialogueId = 11017004,
          Duration = 4,
          GUID = "1B947538",
          SpeakNpcId = 110032,
          Subtitle = "Yet, these signatures might weigh less than the one in my hand, I suppose?",
          VoiceName = "voice/$Locale$/story/1002/110170/1B947538"
        },
        [11017005] = {
          Content = "…………",
          DialogueId = 11017005,
          Duration = 3,
          GUID = "1B947562",
          SpeakNpcId = 110032,
          Subtitle = "Your Highness.",
          VoiceName = "voice/$Locale$/story/1002/110170/1B947562"
        },
        [11017006] = {
          Content = "维吉尔殿下，皇室也打算干预龙莎间谍案的审判吗？",
          DialogueId = 11017006,
          Duration = 4,
          GUID = "1B94758C",
          SpeakNpcId = 110018,
          Subtitle = "Does the royal family intend to intervene in this military case?",
          VoiceName = "voice/$Locale$/story/1002/110170/1B94758C"
        },
        [11017007] = {
          Content = "典狱长女士，您将陛下亲自签发特赦令一事称作“干预”？皇家军事监狱已经不再隶属“皇家”了吗？",
          DialogueId = 11017007,
          Duration = 10,
          GUID = "1B9475B6",
          SpeakNpcId = 110032,
          Subtitle = [[
Intervene? I must ask, do you view His Majesty's decree of pardon as an "intervention"?
Is the Royal Military Prison no longer under the crown's jurisdiction?]],
          VoiceName = "voice/$Locale$/story/1002/110170/1B9475B6"
        },
        [11017008] = {
          Content = "…………",
          DialogueId = 11017008,
          Duration = 3,
          GUID = "1B9475E0",
          SpeakNpcId = 110018,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1002/110170/1B9475E0"
        },
        [11017009] = {
          Content = "我要和{nickname2}谈谈，无关人等出去。",
          DialogueId = 11017009,
          Duration = 4,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94760A",
          SpeakNpcId = 110018,
          Subtitle = "I need to speak with  alone. Everyone else may leave.",
          VoiceName = "voice/$Locale$/story/1002/110170/1B94760A"
        },
        [11017010] = {
          Content = "……总算走了。",
          DialogueId = 11017010,
          Duration = 3,
          GUID = "1B947634",
          SpeakNpcId = 110018,
          Subtitle = "...Phew, they're finally gone.",
          VoiceName = "voice/$Locale$/story/1002/110170/1B947634"
        },
        [11017101] = {
          Camera = "266.088867,42.083984,149.292969,0.000127,-0.000061,19.197737,45.000023,400.044037,false,DoNotOverride,22.0",
          Content = "还好、还好。要是再来晚一点，恐怕和你这次会面就是在墓园了。",
          DialogueId = 11017101,
          FinalCamera = "261.737305,56.924805,149.292969,0.000127,0.399955,13.99701,45.000023,400.044037,false,DoNotOverride,22.0",
          GUID = "1B948522",
          LookAt = {
            [1] = "110018:n(110018)",
            [2] = "110022:n(110018)"
          },
          NextDialogue = 11017102,
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201012,
            [3] = 201013,
            [4] = 201014,
            [5] = 201019,
            [6] = 201020
          },
          Scripts = [[
SEQ{PlayAnimation{ActorId{110018},AnimationId{"DisagreeHead"},Duration{3}},
TurnTo{_delay{0.5},TurnToDescription{"110018:n(110022)"}},
LookAt{LookAtDescription{"110018:n(110022)"}}
}]],
          SpeakNpcId = 110018,
          Subtitle = "Thank goodness. One moment later and I might have to talk to your headstone instead.",
          ToFinalCameraBlendTime = 18,
          VoiceName = "voice/$Locale$/story/1002/110171/1B948522"
        },
        [11017102] = {
          Camera = "38.443359,-115.731445,90.113281,0.000127,6.999892,36.203079,35.0,400.044037,false,DoNotOverride,22.0",
          Content = "我说朋友，你这次是真的闯了大祸了。你知道见皇兄一面有多难，而我又极少染指政客们的事。不过你还算走运，今早皇兄为别的事情召见我，我才求来这一纸特赦令。",
          DialogueId = 11017102,
          FinalCamera = "33.347656,-115.939453,81.179688,0.000127,6.999892,36.203079,35.0,400.044037,false,DoNotOverride,22.0",
          GUID = "1B94854C",
          LookAt = {
            [1] = "110018:n(110022)",
            [2] = "110022:n(110018)"
          },
          NextDialogue = 11017103,
          Scripts = [[
PARA{
PlayAnimation{_delay{3.5},ActorId{110018},AnimationId{"Talk02_End"},Duration{5}},
SEQ{
CameraMoveTo{_delay{7.5},TargetPosition{"509.366211,-103.800781,280.621094,0.000228,-31.400387,130.990356,18.000004,254.013382,false,DoNotOverride,7.801928"},duration{0}},
CameraMoveTo{TargetPosition{"499.982422,-111.956055,283.566406,0.000228,-31.400387,130.990356,18.000004,254.013382,false,DoNotOverride,7.801928"},duration{15}}
}
}]],
          SpeakNpcId = 110018,
          Subtitle = "By all that is holy, my friend, you've really landed yourself in some serious trouble. You know how hard it is to meet my brother, and how rarely I get involved with politicians. But fortune favours you today — I was summoned for a different matter and seized the opportunity to secure your pardon.",
          TalkActionId = {
            [1] = "110018:Talk02_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110171/1B94854C"
        },
        [11017103] = {
          Content = "不过总算，又可以呼吸自由的空气了——想去哪儿？美术馆、歌剧院？凯旋大街的酒馆？还是随便在絮语河岸吹吹风？",
          DialogueId = 11017103,
          Duration = 2,
          GUID = "1B948576",
          NextDialogue = 11017104,
          RelatedWikiId = {
            [1] = 408008,
            [2] = 408009
          },
          Scripts = [[
PARA{
SEQ{
PlayAnimation{ActorId{110018},AnimationId{"Talk01_Start"},Duration{2}},
PlayAnimation{_delay{3},ActorId{110018},AnimationId{"Talk01_End"},Duration{0}},
PlayAnimation{ActorId{110018},AnimationId{"Talk02_Start"},Duration{5}},
PlayAnimation{ActorId{110018},AnimationId{"Talk02_End"},Duration{5}}
},
SEQ{
CameraMoveTo{_delay{5.01},TargetPosition{"329.342773,-782.536133,108.894531,0.000158,2.99986,91.395897,28.0,400.044037,false,DoNotOverride,22.0"},duration{0}},
CameraMoveTo{TargetPosition{"329.342773,-782.536133,84.554688,0.000158,2.99986,91.395897,28.0,400.044037,false,DoNotOverride,22.0"},duration{40}}
}
}]],
          SpeakNpcId = 110018,
          Subtitle = "Things have finally blown over. You're free at last. Where do you want to go, the art gallery, the opera house, or just a simple stroll along Whisper River for fresh air?",
          VoiceName = "voice/$Locale$/story/1002/110171/1B948576"
        },
        [11017104] = {
          Camera = "541.608398,60.505859,169.71875,0.000138,-8.399841,172.791351,35.0,282.239868,false,Manual,5.900274",
          Content = "……谢谢……不过，先不用了。",
          DialogueId = 11017104,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9485A0",
          NextDialogue = 11017105,
          SpeakNpcId = 110022,
          Subtitle = "...Thanks, but no thanks.",
          TalkActionId = {
            [1] = "110022:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110171/1B9485A0"
        },
        [11017105] = {
          Camera = "261.737305,56.924805,149.292969,0.000127,0.399955,13.99701,45.000023,400.044037,false,DoNotOverride,22.0",
          Content = "……你……脸色好差。看来他们没少折磨你。等下随我去我的居所吧，我安排我的医生为你诊治。",
          DialogueId = 11017105,
          Duration = 1,
          GUID = "1B9485CA",
          NextDialogue = 11017106,
          Scripts = [[
SEQ{PlayAnimation{_delay{1.5},ActorId{110018},AnimationId{"Explain02_Start"},Duration{2}},
PlayAnimation{_delay{1},ActorId{110018},AnimationId{"Explain02_End"},Duration{2}},
PlayAnimation{_delay{2},ActorId{110018},AnimationId{"Talk02_Start"},Duration{2}}
}]],
          SpeakNpcId = 110018,
          Subtitle = "...You... look pale. They did go rough on you. Why don't you come to my place? My personal physicians will tend to your wounds.",
          VoiceName = "voice/$Locale$/story/1002/110171/1B9485CA"
        },
        [11017106] = {
          Content = "千年后的今天，海伯利亚的监狱居然还在用原始野蛮、毫无人道主义可言的刑罚……那些谄媚的作家笔下“最伟大、最繁荣的时代”，简直就是最拙劣的喜剧。",
          DialogueId = 11017106,
          GUID = "1B9485F4",
          NextDialogue = 11017107,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{6.01},TargetPosition{"640.131836,164.128906,414.648438,0.0001,-25.800047,-120.799606,20.0,400.044037,false,DoNotOverride,22.0"},duration{0}},
CameraMoveTo{TargetPosition{"691.962891,133.231445,414.648438,0.0001,-25.800047,-120.799606,20.0,400.044037,false,DoNotOverride,22.0"},duration{20}}
}]],
          SpeakNpcId = 110018,
          Subtitle = "I can't believe after seven centuries, the prisons of Hyperborea still resort to primitive, barbaric, and utterly inhumane forms of torture... Those obsequious writers hail this era as \"the greatest and most prosperous of times,\" which is nothing but a tragic farce.",
          TalkActionId = {
            [1] = "110018:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110171/1B9485F4"
        },
        [11017107] = {
          Camera = "358.598633,12.164062,188.667969,0.000165,-23.000387,156.785355,28.000008,310.596832,false,DoNotOverride,7.801928",
          Content = "先别说这个了……达芙涅呢？",
          DialogueId = 11017107,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "360.378906,16.311523,188.667969,0.000165,-23.000387,156.785355,28.000008,310.596832,false,DoNotOverride,7.801928",
          GUID = "1B94861E",
          NextDialogue = 11017108,
          SpeakNpcId = 110022,
          Subtitle = "Let's not dwell on that... How's Daphne?",
          TalkActionId = {
            [1] = "110022:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110171/1B94861E"
        },
        [11017108] = {
          Camera = "169.751953,12.941406,146.257812,0.000181,-0.200685,23.989719,45.0,254.013382,false,Manual,7.801928",
          Content = "放心。我听闻你一直在护着她，这份特赦令自然也会庇护她。",
          DialogueId = 11017108,
          FinalCamera = "159.480469,8.374023,146.257812,0.000181,-0.200685,23.989157,45.0,254.013382,false,Manual,7.801928",
          GUID = "1B948648",
          NextDialogue = 11017112,
          SpeakNpcId = 110018,
          Subtitle = "I heard about your efforts to ensure her safety. Fear not, the pardon includes her as well.",
          TalkActionId = {
            [1] = "110018:AgreeHead"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110171/1B948648"
        },
        [11017109] = {
          Camera = "626.061523,-377.210938,104.453125,0.000161,-1.200583,124.384415,28.000006,310.596832,false,DoNotOverride,7.801928",
          Content = "那就好……抱歉，现在的我，暂时还没法报答你。",
          DialogueId = 11017109,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "640.552734,-398.384766,104.984375,0.000161,-1.200583,124.384415,28.000006,310.596832,false,DoNotOverride,7.801928",
          GUID = "1B948672",
          NextDialogue = 11017110,
          Scripts = [[
SEQ{
PlayAnimation{_delay{4},ActorId{110022},AnimationId{"DisagreeHead"},Duration{1}},
PlayAnimation{_delay{1},ActorId{110022},AnimationId{"Explain02_Start"},Duration{5}}
}]],
          SpeakNpcId = 110022,
          Subtitle = "That's a relief... Sorry, I don't have anything to repay your kindness at the moment.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110171/1B948672"
        },
        [11017110] = {
          Camera = "-224.194336,-243.641602,117.367188,0.000243,-0.000792,28.586767,45.000011,254.013382,false,Manual,7.801928",
          Content = "报答——嗯……那来给我当半年保镖如何？",
          DialogueId = 11017110,
          FacialId = {
            [1] = "110018:Smile01"
          },
          FinalCamera = "-230.798828,-231.524414,117.367188,0.000243,-0.000792,28.586761,45.000011,717.293152,false,Manual,1.399505",
          GUID = "1B94869C",
          NextDialogue = 11017111,
          Scripts = [[

PlayAnimation{_delay{2},ActorId{110018},AnimationId{"Talk03_Start"},Duration{2}}]],
          SpeakNpcId = 110018,
          Subtitle = "Repay me? Hmm... How about serving as my bodyguard for six months?",
          TalkActionId = {
            [1] = "110022:Explain02_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110171/1B94869C"
        },
        [11017111] = {
          Camera = "499.02832,79.253906,163.570312,0.000184,-5.80075,178.390396,45.0,254.013382,false,Manual,7.801928",
          Content = "保镖？",
          DialogueId = 11017111,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "498.866211,73.417969,163.570312,0.000184,-5.80075,178.390396,45.0,254.013382,false,Manual,7.801928",
          GUID = "1B9486C6",
          NextDialogue = 11019105,
          SpeakNpcId = 110022,
          Subtitle = "Bodyguard?",
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/story/1002/110171/1B9486C6"
        },
        [11017112] = {
          Camera = "34.15918,-378.791016,351.042969,0.000214,-23.400875,60.993435,35.0,254.013382,false,DoNotOverride,7.801928",
          Content = "还有一件事……",
          DialogueId = 11017112,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "56.49707,-391.176758,351.042969,0.000214,-23.400875,60.993435,35.0,254.013382,false,DoNotOverride,7.801928",
          GUID = "1B94871B",
          NextDialogue = 11017114,
          SpeakNpcId = 110022,
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110171/1B94871B"
        },
        [11017113] = {
          Camera = "3.826172,76.46582,165.292969,0.000128,-0.600066,-114.184586,31.194523,100000.0,false,DoNotOverride,22.0",
          Content = "你短期可能回不了军团了。你的嫌疑并未真的洗清，现在回军团只怕身份会尴尬。",
          DialogueId = 11017113,
          Duration = 3,
          GUID = "1B94871A",
          NextDialogue = 11019115,
          Scripts = [[
PARA{
PlayAnimation{_delay{3},ActorId{110018},AnimationId{"Think_End"},Duration{3}},
PlayFacial{ActorId{110022},FacialId{"Think01"}}
}]],
          SpeakNpcId = 110018,
          Subtitle = "And staying away from the Legion might be wise for now. The stigma of a criminal charge lingers. Going back to the Legion at this point could be awkward.",
          TalkActionId = {
            [1] = "110018:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110171/1B94871A"
        },
        [11017114] = {
          Content = "富尔维斯的副官法露茜。我认为她的失踪没那么简单——她是这个案子真相的关键。如果可以，我想拜托你帮忙调查她的下落，无论生死。",
          DialogueId = 11017114,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94871C",
          NextDialogue = 11017115,
          Scripts = [[
PARA{
SEQ{
CameraMoveTo{_delay{8.01},TargetPosition{"346.420898,18.442383,147.914062,0.000204,-2.60082,157.593735,35.0,254.013382,false,DoNotOverride,7.801928"},duration{0}},
CameraMoveTo{TargetPosition{"348.020508,22.321289,147.914062,0.000204,-2.60082,157.593735,35.0,254.013382,false,DoNotOverride,7.801928"},duration{8}}
},
SEQ{
PlayAnimation{ActorId{110022},AnimationId{"Talk02_End"},Duration{2}},
PlayAnimation{ActorId{110022},AnimationId{"Think_Start"},Duration{5}},
PlayAnimation{ActorId{110022},AnimationId{"Think_End"},Duration{2}}
}
}]],
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110171/1B94871C"
        },
        [11017115] = {
          Camera = "315.612305,27.775391,111.347656,0.000177,18.198792,35.193779,45.000011,254.013382,false,DoNotOverride,7.801928",
          Content = "富尔维斯失踪的副官……？好，我记下了。",
          DialogueId = 11017115,
          GUID = "1B94871D",
          NextDialogue = 11017109,
          SpeakNpcId = 110018,
          VoiceName = "voice/$Locale$/story/1002/110171/1B94871D"
        },
        [11017116] = {
          Camera = "211.03125,373.930664,131.835938,0.000081,2.000002,-130.801483,31.194527,100000.0,false,Manual,22.0",
          Content = "嗯。想想那份文件上的一串签名吧——迪斯玛尼亚不知道有多少人在看不见的暗角窥视着你。你的武器可以杀死秽兽，却挡不住来自背后的子弹。",
          DialogueId = 11017116,
          Duration = 3,
          FinalCamera = "215.617188,369.973633,131.835938,0.000081,1.999995,-130.801483,31.194527,100000.0,false,Manual,22.0",
          GUID = "1B948798",
          NextDialogue = 11017117,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{8.01},TargetPosition{"118.792969,12.256836,231.714844,0.000107,-21.599482,-163.622894,45.0,100000.0,false,DoNotOverride,22.0"},duration{0}},
CameraMoveTo{TargetPosition{"130.400391,15.670898,236.511719,0.000107,-21.599482,-163.622894,45.0,100000.0,false,DoNotOverride,22.0"},duration{8}}
}]],
          SpeakNpcId = 110018,
          Subtitle = "Yes. Just think of those signatures — how many people are watching you in Dismania. Your prowess may deter approaching Filthoids, but not hidden assassins.",
          TalkActionId = {
            [1] = "110022:Talk01_End",
            [2] = "110018:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110171/1B948798"
        },
        [11017117] = {
          Camera = "-38.605469,-123.583984,167.742188,0.000094,-5.999843,78.991455,31.194527,446.287842,false,Manual,11.834087",
          Content = "我知道你在担心什么。西比尔·梅森和达芙涅有些故交，且在这起事件中，她明显更相信你们无辜，所以她至少会保证达芙涅的安全。",
          DialogueId = 11017117,
          Duration = 3,
          FinalCamera = "-45.6875,-122.178711,167.742188,0.000092,-6.199858,78.391617,31.194527,446.287842,false,Manual,11.834087",
          GUID = "1B9487C2",
          NextDialogue = 11019119,
          SpeakNpcId = 110018,
          Subtitle = "I know what you're worried about. Sibylle Mason is an old friend of Daphne. She is obviously inclined to your innocence, so she will at least ensure Daphne's safety.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110171/1B9487C2"
        },
        [11017119] = {
          Camera = "653.830078,-1243.886719,875.824219,0.000136,-26.201082,109.391876,31.194523,1682.25708,false,Manual,1.2",
          Content = "……哈，你知道我最厌恶那些老家伙的繁文缛节。不过，你总算有心情开玩笑了，这很好。",
          DialogueId = 11017119,
          Duration = 3,
          FacialId = {
            [1] = "110018:Smile01"
          },
          FinalCamera = "619.453125,-1255.985352,875.824219,0.000136,-26.201082,109.391876,31.194523,1682.25708,false,Manual,1.2",
          GUID = "1B948816",
          NextDialogue = 11019121,
          Scripts = "PlayAnimation{_delay{3},ActorId{110022},AnimationId{\"Explain02_End\"},Duration{3}}",
          SpeakNpcId = 110018,
          Subtitle = "...Come on, you know there's nothing I hate more than these pointless customs and etiquette. But you're in the mood for jokes now, which is a good sign.",
          TalkActionId = {
            [1] = "110018:Talk03_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110171/1B948816"
        },
        [11017201] = {
          Content = "{nickname2}，你就什么都不问？",
          DialogueId = 11017201,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9488C0",
          NextDialogue = 11017202,
          SpeakNpcId = 110010,
          Subtitle = ", so you're not going to ask me anything?",
          VoiceName = "voice/$Locale$/story/1002/110172/1B9488C0"
        },
        [11017202] = {
          Content = "您刚说过，军人要无条件服从命令。",
          DialogueId = 11017202,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9488C1",
          NextDialogue = 11017203,
          SpeakNpcId = 110022,
          Subtitle = "You just said soldiers must obey.",
          VoiceName = "voice/$Locale$/story/1002/110172/1B9488C1"
        },
        [11017203] = {
          Content = "都这个份上了，你怎么还是老样子，像块木雕似的。",
          DialogueId = 11017203,
          Duration = 3,
          GUID = "1B9488C2",
          NextDialogue = 11017204,
          SpeakNpcId = 110010,
          Subtitle = "Given what we've been through, are you really going to be as rigid as a piece of wood?",
          VoiceName = "voice/$Locale$/story/1002/110172/1B9488C2"
        },
        [11017204] = {
          Content = "老师，您还说过，作战时必须集中注意力。",
          DialogueId = 11017204,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9488C3",
          NextDialogue = 11017205,
          SpeakNpcId = 110022,
          Subtitle = "You also said that one must fully concentrate when engaging in combat.",
          VoiceName = "voice/$Locale$/story/1002/110172/1B9488C3"
        },
        [11017205] = {
          Content = "现在情况并不安全，分心批评我，会增加您的伤亡概率。",
          DialogueId = 11017205,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9488C4",
          NextDialogue = 11017206,
          SpeakNpcId = 110022,
          Subtitle = "The current circumstances are perilous; being sidetracked by criticism might lead to casualties.",
          VoiceName = "voice/$Locale$/story/1002/110172/1B9488C4"
        },
        [11017206] = {
          Content = "你这小鬼！",
          DialogueId = 11017206,
          Duration = 3,
          GUID = "1B9488C5",
          SpeakNpcId = 110010,
          Subtitle = "You sharp-tongued brat!",
          VoiceName = "voice/$Locale$/story/1002/110172/1B9488C5"
        },
        [11017301] = {
          Content = "“狮鹫”该不会就剩你一个了？其他人什么情况？",
          DialogueId = 11017301,
          Duration = 3,
          GUID = "1B909E29",
          NextDialogue = 11017302,
          SpeakNpcId = 110010,
          Subtitle = "Don't tell me you're the only Griffin left alive. Where are the rest of your squad?",
          VoiceName = "voice/$Locale$/story/1002/110110/1B909E29"
        },
        [11017302] = {
          Content = "他们在前面，大多伤得不轻。跟我来。",
          DialogueId = 11017302,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B909E30",
          NextDialogue = 11011013,
          SpeakNpcId = 110022,
          Subtitle = "They're right ahead. Most of them are heavily injured. Please follow me.",
          VoiceName = "voice/$Locale$/story/1002/110110/1B909E30"
        },
        [11017401] = {
          DialogueId = 11017401,
          Duration = 2,
          GUID = "1B94B65A",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B65A"
        },
        [11017402] = {
          Content = "达芙涅对伤员们进行了治疗",
          DialogueId = 11017402,
          Duration = 2,
          GUID = "1B94B684",
          Subtitle = "Daphne treated the wounded.",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B684"
        },
        [11017403] = {
          Content = "带着卡嘉一行人离开了此处……",
          DialogueId = 11017403,
          Duration = 2,
          GUID = "1B94B6AE",
          Subtitle = "You take Katya and the guys and leave this place...",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B6AE"
        },
        [11017404] = {
          Content = "这是……继电器，总之先关闭一个",
          DialogueId = 11017404,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94B6D8",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B6D8"
        },
        [11017405] = {
          DialogueId = 11017405,
          Duration = 2,
          GUID = "1B94B702",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B702"
        },
        [11017406] = {
          Content = "不要动！",
          DialogueId = 11017406,
          Duration = 2,
          GUID = "1B909E34",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 110005,
          Subtitle = "Freeze!",
          VoiceName = "voice/$Locale$/story/1002/110110/1B909E34"
        },
        [11017407] = {
          Content = "水位降不下去！",
          DialogueId = 11017407,
          Duration = 2,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94B756",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 11017408,
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B756"
        },
        [11017408] = {
          Content = "从边上绕过去吧。",
          DialogueId = 11017408,
          Duration = 2,
          GUID = "1B94B780",
          SpeakNpcId = 110005,
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B780"
        },
        [11017409] = {
          DialogueId = 11017409,
          Duration = 2,
          GUID = "1B94B7AA",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B7AA"
        },
        [11017410] = {
          Camera = "402.354004,84.89209,149.571686,0.000074,4.19976,-153.080948,21.458063,100000.0,false,Manual,22.0",
          Content = "权限确认，请通行。",
          DialogueId = 11017410,
          Duration = 3,
          FinalCamera = "353.715454,60.211914,153.577911,0.000074,4.19976,-153.080948,21.458063,100000.0,false,Manual,22.0",
          GUID = "1B94B7D4",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "Access privilege confirmed, please proceed.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B7D4"
        },
        [11017411] = {
          Content = "好，月髓连接上了【废弃】",
          DialogueId = 11017411,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          GUID = "1B94B7FE",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B7FE"
        },
        [11017412] = {
          Content = "咦，被挡住了，看起来要绕一下路呢……",
          DialogueId = 11017412,
          Duration = 5,
          GUID = "1B94B828",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 110034,
          Subtitle = "Eh? It's blocked. Seems like we need to take a detour...",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B828"
        },
        [11017413] = {
          Content = "开关还打不开，先启动相连的髓动轮吧。",
          DialogueId = 11017413,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94B852",
          SpeakNpcId = 110022,
          Subtitle = "The switch doesn't work, maybe I should activate the connected Phoxynamo Wheel first.",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B852"
        },
        [11017414] = {
          Content = "（……要抓紧时间打开开关。）",
          DialogueId = 11017414,
          DisableMouth = 1,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94B87C",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(...Gotta turn it on quickly.)",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B87C"
        },
        [11017415] = {
          Content = "炮台的能源已经全部连通，回来汇合吧。【废弃】",
          DialogueId = 11017415,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 5,
          GUID = "1B94B8A6",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B8A6"
        },
        [11017416] = {
          Content = "准备好了，就激活髓动轮出发吧。",
          DialogueId = 11017416,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94B8D0",
          SpeakNpcId = 110010,
          Subtitle = "Go activate the Phoxynamo Wheels once you're ready.",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B8D0"
        },
        [11017417] = {
          Content = "（顺着这些线缆找到髓动轮吧。）",
          DialogueId = 11017417,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94B8FA",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(These cables should lead me to the Phoxynamo Wheels.)",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B8FA"
        },
        [11017418] = {
          Content = "好厉害……",
          DialogueId = 11017418,
          GUID = "1B94B924",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 110034,
          Subtitle = "That's amazing...",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B924"
        },
        [11017419] = {
          Content = "（找到了……启动它吧。）",
          DialogueId = 11017419,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94B94E",
          SpeakNpcId = 110022,
          Subtitle = "(Found it. Gotta activate it now.)",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B94E"
        },
        [11017420] = {
          Content = "他们管这里叫“模拟战场”，说什么……“这次的主题是冰湖城防卫战”。",
          DialogueId = 11017420,
          GUID = "1B94B978",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 11017421,
          SpeakNpcId = 110034,
          Subtitle = "They refer to this place as a \"Simulated Battlefield,\" saying that... \"The theme this time is the Defence of Icelake City.\"",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B978"
        },
        [11017421] = {
          Content = "听说那个冰湖城，到处都是冰天雪地的。我还没见过雪呢……真想去看看！",
          DialogueId = 11017421,
          GUID = "1B94B9A2",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 11017422,
          SpeakNpcId = 110034,
          Subtitle = "I heard that this Icelake City is covered in snow, something that I've never seen in my entire life... How I wish I could go there and see it myself!",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B9A2"
        },
        [11017422] = {
          Content = "……我是说，如果，我能活着回家。",
          DialogueId = 11017422,
          GUID = "1B94B9CC",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 110034,
          Subtitle = "...I mean, if, by any chance, I could make it out alive.",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B9CC"
        },
        [11017423] = {
          Content = "好了。",
          DialogueId = 11017423,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94B9F6",
          SpeakNpcId = 110022,
          Subtitle = "(Done.)",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B9F6"
        },
        [11017501] = {
          Content = "动力室是整座要塞的“心脏”，维持要塞运转的能源都来自里面那台月髓舱。",
          DialogueId = 11017501,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94C6C2",
          NextDialogue = 11017502,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/signal_on\"},PlayAs2D{true}}",
          SpeakNpcId = 110010,
          Subtitle = "The engine room is the \"heart\" of the entire fortress, and all the power that keeps the fortress running comes from the Phoxichor tank in there.",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C6C2"
        },
        [11017502] = {
          Content = "但直接攻击月髓舱会引起爆炸，你得先去关掉四周的<H>髓动轮</>。",
          DialogueId = 11017502,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94C6EC",
          SpeakNpcId = 110010,
          Subtitle = "But a direct attack would only lead to explosion, so you need to shut down the Phoxynamo Wheels around it first.",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C6EC"
        },
        [11017503] = {
          Camera = "804.818848,157.511719,744.295471,0.000002,-8.800173,-4.800692,23.868748,100000.0,false,Manual,22.0",
          Content = "那些髓动轮，蓝色的，你应该能认得出来吧？你现在要做的是把它们变成黄色。",
          DialogueId = 11017503,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94C716",
          NextDialogue = 11017504,
          SpeakNpcId = 110010,
          Subtitle = "You should be able to recognise those wheels, aka the blue ones, right? What you need to do is turn them yellow.",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C716"
        },
        [11017504] = {
          Content = "老师，我早毕业了，不用这样一步一步指导的。",
          DialogueId = 11017504,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94C740",
          NextDialogue = 11017505,
          SpeakNpcId = 110022,
          Subtitle = "I graduated a long time ago, Sir. You don't have to lead me through all the basic steps.",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C740"
        },
        [11017505] = {
          Content = "那你见机行事吧，必要时我再联络你。",
          DialogueId = 11017505,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94C76A",
          SpeakNpcId = 110010,
          Subtitle = "...You kiddo! Alright, play it by ear then. I'll contact you if necessary.",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C76A"
        },
        [11017506] = {
          Content = "（顺着地上这些线缆，应该能顺利找到那些髓动轮。但愿它们不要藏得太刁钻。）",
          DialogueId = 11017506,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94C794",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Following the cables on the ground may help me get to the Phoxynamo Wheels. I hope they're not too tricky to be found.)",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C794"
        },
        [11017507] = {
          Content = "（先处理这台吧。）",
          DialogueId = 11017507,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94C7BE",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(I'll shut down this one first.)",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C7BE"
        },
        [11017508] = {
          Content = "（好，关停了。）",
          DialogueId = 11017508,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94C7E8",
          NextDialogue = 11018203,
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Alright, one down.)",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C7E8"
        },
        [11017509] = {
          Content = "正东方向的门搞定，可以通过了。",
          DialogueId = 11017509,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94C812",
          SpeakNpcId = 110010,
          Subtitle = "The door due east is now open. You can go that way.",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C812"
        },
        [11017510] = {
          Content = "（把髓动轮塞在这么古怪的位置，龙莎的工程师还真不嫌麻烦。）",
          DialogueId = 11017510,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94C83C",
          SpeakNpcId = 110022,
          Subtitle = "(Put the Phoxynamo Wheel in such a weird place... Those engineers sure know how to make things involved.)",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C83C"
        },
        [11017511] = {
          Content = "（这样就可以了。）",
          DialogueId = 11017511,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94C866",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(That should work.)",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C866"
        },
        [11017512] = {
          Content = "（真麻烦……）",
          DialogueId = 11017512,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94C890",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(That was complicated...)",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C890"
        },
        [11017513] = {
          Content = "你那边……什么动静？",
          DialogueId = 11017513,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94C8BA",
          NextDialogue = 11017514,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "What's the noise... Everthing okay?",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C8BA"
        },
        [11017514] = {
          Content = "<W>警告：检测到髓动轮异常关闭，即将重新启动。</>",
          DialogueId = 11017514,
          GUID = "1B94C8E4",
          NextDialogue = 11017515,
          SnapShot = "BROADCAST",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "WARNING: Abnormal Phoxynamo Wheel shutdown detected. Re-activating Phoxynamo Wheels now.",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C8E4"
        },
        [11017515] = {
          Content = "…………！",
          DialogueId = 11017515,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94C90E",
          SpeakNpcId = 110022,
          Subtitle = "...!",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C90E"
        },
        [11017516] = {
