        },
        [11017519] = {
          Camera = "538.932007,61.714844,122.000732,-2.0,2.799223,36.418335,35.000008,100000.0,false,DoNotOverride,20.0",
          Content = "听着，{nickname2}，你现在到动力室下层去，把所有备用髓动轮启动后，立即撤离。",
          DialogueId = 11017519,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "542.133667,57.402344,121.813232,-2.0,2.799223,36.418335,35.000008,100000.0,false,DoNotOverride,20.0",
          GUID = "1B94C9B6",
          NextDialogue = 11017520,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/signal_on\"},PlayAs2D{true}}",
          SpeakNpcId = 110010,
          Subtitle = "Listen, . I need you to go to the lower floor of the engine room, activate all the back-up Phoxynamo Wheels, then evacuate immediately.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C9B6"
        },
        [11017520] = {
          Camera = "699.135376,388.0625,157.425171,10.009494,-3.598785,-51.594585,40.0,100000.0,false,DoNotOverride,20.0",
          Content = "既然常规手段解决不了月髓舱，你就让它自己搞坏自己。",
          DialogueId = 11017520,
          Duration = 3,
          FacialId = {
            [1] = "110010:Angry01"
          },
          FinalCamera = "699.135376,388.0625,156.380249,10.010453,-3.598785,-51.595715,40.0,100000.0,false,DoNotOverride,20.0",
          GUID = "1B94C9E0",
          NextDialogue = 11017521,
          SpeakNpcId = 110010,
          Subtitle = "Since we can't shut them down our way, we can let them do it in a self-destructive way.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C9E0"
        },
        [11017521] = {
          Camera = "992.544189,397.238281,178.074951,-0.0,-8.599126,-138.38974,40.000011,100000.0,false,DoNotOverride,20.0",
          Content = "您指的是……利用过载炸毁月髓舱？我知道了。",
          DialogueId = 11017521,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94CA0A",
          Scripts = "PlayNormalSound{_delay{5},EventPath{\"event:/sfx/common/story/ex01/signal_off\"},PlayAs2D{true}}",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110022,
          Subtitle = "You mean... exploding the Phoxichor tank by overloading it? Got it.",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94CA0A"
        },
        [11017601] = {
          Content = "1号备用髓动轮可以操作了，启动吧。",
          DialogueId = 11017601,
          GUID = "1B94D72A",
          SpeakNpcId = 110010,
          Subtitle = "Back-up Phoxynamo Wheel No.1 is ready. Now activate it.",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D72A"
        },
        [11017602] = {
          Content = "干得好，我会把剩下三台的髓动轮的操作权限一一解锁。",
          DialogueId = 11017602,
          GUID = "1B94D754",
          NextDialogue = 11017603,
          SpeakNpcId = 110010,
          Subtitle = "Well done. I'll unlock the control authority for the remaining three Phoxynamo Wheels.",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D754"
        },
        [11017603] = {
          Content = "等黄色灯光亮起，你就启动它。",
          DialogueId = 11017603,
          GUID = "1B94D77E",
          SpeakNpcId = 110010,
          Subtitle = "Activate them once the yellow light is on.",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D77E"
        },
        [11017604] = {
          Content = "（髓动轮亮了，看来老师那边已经解决了。）",
          DialogueId = 11017604,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94D7A8",
          SpeakNpcId = 110022,
          Subtitle = "(The light is on. Looks like Sir Avar has made it on his side.)",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D7A8"
        },
        [11017605] = {
          Content = "<W>警告：月髓舱负荷过大，已过载50%。请立即停止髓动轮设备使用，不得擅自撤离。</>",
          DialogueId = 11017605,
          GUID = "1B94D7D2",
          NextDialogue = 11017606,
          SnapShot = "BROADCAST",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "WARNING: Phoxichor tank is overloaded by 50%. Please shut down the Phoxynamo Wheels immediately; unauthorized departure is not permitted.",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D7D2"
        },
        [11017606] = {
          Content = "（……要尽快了。）",
          DialogueId = 11017606,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94D7FC",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(...I need to hurry up.)",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D7FC"
        },
        [11017607] = {
          Content = "3号也可以了，去吧！",
          DialogueId = 11017607,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94D826",
          SpeakNpcId = 110010,
          Subtitle = "No.3 is also ready. Go get it!",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D826"
        },
        [11017608] = {
          Content = "（呼……）",
          DialogueId = 11017608,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94D850",
          NextDialogue = 11017609,
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Phew...)",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D850"
        },
        [11017609] = {
          Content = "干净利落，做得漂亮。",
          DialogueId = 11017609,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94D87A",
          SpeakNpcId = 110010,
          Subtitle = "Quick and clean! Well done, kid.",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D87A"
        },
        [11017610] = {
          Content = "权限激活了，这是最后一台！",
          DialogueId = 11017610,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94D8A4",
          SpeakNpcId = 110010,
          Subtitle = "The control authority is unlocked. This is the last one!",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D8A4"
        },
        [11017611] = {
          Content = "<W>警告：月髓舱即将损毁，请自首。</>",
          DialogueId = 11017611,
          GUID = "1B94D8CE",
          SnapShot = "BROADCAST",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "WARNING: Phoxichor tank sabotage detected. Anyone held responsible should confess your crime.",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D8CE"
        },
        [11017612] = {
          Content = "快！撤到安全门后面去！",
          DialogueId = 11017612,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94D8F8",
          NextDialogue = 11017613,
          SpeakNpcId = 110010,
          Subtitle = "Run! Get behind the safety door!",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D8F8"
        },
        [11017613] = {
          Content = "<W>警告：月髓舱即将损毁，请自首。</>",
          DialogueId = 11017613,
          GUID = "1B94D922",
          SnapShot = "BROADCAST",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "WARNING: Phoxichor tank sabotage detected. Anyone held responsible should confess your crime.",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D922"
        },
        [11017701] = {
          Content = "长官，请走这边……",
          DialogueId = 11017701,
          GUID = "1B94E792",
          SpeakNpcId = 110017,
          Subtitle = "This way, sir...",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E792"
        },
        [11017702] = {
          Content = "长官，从这里下去，就是地下水道了。",
          DialogueId = 11017702,
          GUID = "1B94E7BC",
          NextDialogue = 11017703,
          SpeakNpcId = 110017,
          Subtitle = "Sir, we can get into the sewer tunnels from here.",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E7BC"
        },
        [11017703] = {
          Content = "卡戎人，你走前面。",
          DialogueId = 11017703,
          GUID = "1B94E7E6",
          NextDialogue = 11017704,
          SpeakNpcId = 110016,
          Subtitle = "You go first, Charon.",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E7E6"
        },
        [11017704] = {
          Content = "是、是……",
          DialogueId = 11017704,
          GUID = "1B94E810",
          SpeakNpcId = 110017,
          Subtitle = "Yes, sir...",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E810"
        },
        [11017705] = {
          Content = "这股热气是……",
          DialogueId = 11017705,
          GUID = "1B94E83A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 11017706,
          SpeakNpcId = 110034,
          Subtitle = "The hot steam...",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E83A"
        },
        [11017706] = {
          Content = "当心！前面有一台冷凝机，靠太近的话会受伤的！",
          DialogueId = 11017706,
          GUID = "1B94E864",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 110034,
          Subtitle = "Watch out! There's a condenser up ahead. You'll get hurt if you get too close!",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E864"
        },
        [11017707] = {
          Content = "各位长官……冷凝机的蒸汽很危险，千万不要久留。",
          DialogueId = 11017707,
          GUID = "1B94E88E",
          SpeakNpcId = 110017,
          Subtitle = "Sir... Steam produced by the condenser is dangerous. We should not stay too long.",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E88E"
        },
        [11017708] = {
          Content = "呼、呼……好热……长官，您没事吧？",
          DialogueId = 11017708,
          GUID = "1B94E8B8",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 110034,
          Subtitle = "Huff, huff... It's so hot... Are you okay, sir?",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E8B8"
        },
        [11017709] = {
          Content = "长官，请走这边……",
          DialogueId = 11017709,
          GUID = "1B94E8E2",
          NextDialogue = 11017710,
          SpeakNpcId = 110017,
          Subtitle = "This way, sir...",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E8E2"
        },
        [11017710] = {
          Content = "秽、秽兽……！",
          DialogueId = 11017710,
          GUID = "1B94E90C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 11017711,
          SpeakNpcId = 110034,
          Subtitle = "Fil...Filthoids!",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E90C"
        },
        [11017711] = {
          Content = "平民都退到我身后去。",
          DialogueId = 11017711,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94E936",
          SpeakNpcId = 110022,
          Subtitle = "The unarmed retreat behind me.",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E936"
        },
        [11017712] = {
          Content = "谢谢您救了我们！原来也不是所有帝国士兵都……",
          DialogueId = 11017712,
          GUID = "1B94E960",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 11017713,
          SpeakNpcId = 110034,
          Subtitle = "Thank you for saving our lives! It turned out not all the Imperial soldiers are...",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E960"
        },
        [11017713] = {
          Content = "啊，抱歉！我是说，我曾经以为帝国士兵都和同盟的家伙一样蛮横粗暴，但现在我知道了，不是我想的那样！",
          DialogueId = 11017713,
          GUID = "1B94E98A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 110034,
          Subtitle = "Ah, sorry! I mean, I used to think that Imperial soldiers were no different from those Forsaken rotters. But now I know I was wrong!",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E98A"
        },
        [11017714] = {
          Content = "前面那个是……阿瓦尔长官！",
          DialogueId = 11017714,
          GUID = "1B94E9B4",
          NextDialogue = 11017715,
          SpeakNpcId = 110015,
          Subtitle = "Over there is... Sir Avar!",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E9B4"
        },
        [11017715] = {
          Content = "（好，总算是平安会合了。）",
          DialogueId = 11017715,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94E9DE",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Nice, safely join force with them.)",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E9DE"
        },
        [11017801] = {
          Content = "停下吧。",
          DialogueId = 11017801,
          GUID = "1B94F7FA",
          SpeakNpcId = 110010,
          Subtitle = "Here it is.",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F7FA"
        },
        [11017802] = {
          Content = "视野不错，就在这儿轰击中央控制室吧。",
          DialogueId = 11017802,
          GUID = "1B94F824",
          SpeakNpcId = 110010,
          Subtitle = "The view is good. Let's bombard the central control room from here.",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F824"
        },
        [11017803] = {
          Content = "该死……",
          DialogueId = 11017803,
          GUID = "1B94F84E",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F84E"
        },
        [11017804] = {
          Content = "先处理掉秽兽，别让它们干扰到你！",
          DialogueId = 11017804,
          GUID = "1B94F878",
          SpeakNpcId = 110010,
          Subtitle = "Take down the Filthoids first. Don't let them distract you!",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F878"
        },
        [11017805] = {
          Content = "好，清理干净了。",
          DialogueId = 11017805,
          GUID = "1B94F8A2",
          NextDialogue = 11017806,
          SpeakNpcId = 110010,
          Subtitle = "Alright, all cleared out.",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F8A2"
        },
        [11017806] = {
          Content = "接下来，就从相对薄弱的<H>侧门</>开始轰击吧。",
          DialogueId = 11017806,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94F8CC",
          SpeakNpcId = 110010,
          Subtitle = "Next, let's start with the relatively thin side door.",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F8CC"
        },
        [11017807] = {
          Content = "不要停，继续轰击！记得用高爆弹。",
          DialogueId = 11017807,
          GUID = "1B94F8F6",
          SpeakNpcId = 110010,
          Subtitle = "Keep it up! Use the High-Explosive Shells!",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F8F6"
        },
        [11017808] = {
          Content = "差不多了！过去看看吧。",
          DialogueId = 11017808,
          GUID = "1B94F920",
          SpeakNpcId = 110010,
          Subtitle = "That should do it. Let's go check it out after we get rid of the remaining Filthoids.",
          VoiceName = "voice/$Locale$/story/1002/110186/1B957C0C"
        },
        [11017809] = {
          Content = "别发愣啊，快轰！",
          DialogueId = 11017809,
          GUID = "1B94F94A",
          SpeakNpcId = 110010,
          Subtitle = "Snap out of it! Keep firing!",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F94A"
        },
        [11017810] = {
          Content = "你还好吧？别是哪儿受伤了？",
          DialogueId = 11017810,
          GUID = "1B94F974",
          SpeakNpcId = 110010,
          Subtitle = "Are you okay? Did you get hurt?",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F974"
        },
        [11017811] = {
          Content = "等你把这门敲破，我小女儿都变成老奶奶了！回去开炮。",
          DialogueId = 11017811,
          GUID = "1B94F99E",
          SpeakNpcId = 110010,
          Subtitle = "By the time you break the door, my baby would've become a granny! Go back to the cannon.",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F99E"
        },
        [11017812] = {
          DialogueId = 11017812,
          GUID = "1B94F9C8",
          IsBlack = 1,
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F9C8"
        },
        [11017901] = {
          Content = "去吧，保持联络，听我指示。",
          DialogueId = 11017901,
          GUID = "1B950862",
          SpeakNpcId = 110010,
          Subtitle = "Go, stay in touch, and be careful.",
          VoiceName = "voice/$Locale$/story/1002/110179/1B950862"
        },
        [11017902] = {
          Content = "维克……",
          DialogueId = 11017902,
          GUID = "1B95088C",
          SpeakNpcId = 110020,
          Subtitle = "Vic...",
          VoiceName = "voice/$Locale$/story/1002/110179/1B95088C"
        },
        [11017903] = {
          Content = "准备好了，就激活髓动轮出发吧。",
          DialogueId = 11017903,
          GUID = "1B9508B6",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110179/1B9508B6"
        },
        [11018001] = {
          Camera = "-1102.632935,-197.335449,128.499756,0.000169,-1.399683,12.991217,50.0,100000.0,false,DoNotOverride,22.0",
          Content = "等一下。",
          DialogueId = 11018001,
          GUID = "1B9518CA",
          LookAt = {
            [1] = "110022:n(110010)",
            [2] = "110034:n(110010)",
            [3] = "110015:n(110010)",
            [4] = "110017:n(110010)"
          },
          NextDialogue = 11018002,
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201013,
            [3] = 201015,
            [4] = 408007,
            [5] = 101004
          },
          Scripts = [[
PARA{
MoveTo{ActorId{110017},MoveSpeed{150},TargetPoint{"fulankemoVe"}},
MoveTo{ActorId{110010},MoveSpeed{150},TargetPoint{"fix30awa"}},
MoveTo{ActorId{110022},MoveSpeed{150},TargetPoint{"qiannanzhumoVe"}},
MoveTo{ActorId{110034},MoveSpeed{150},TargetPoint{"kajiamoVe"}}
}]],
          SpeakNpcId = 110010,
          Subtitle = "Wait.",
          VoiceName = "voice/$Locale$/story/1002/110180/1B9518CA"
        },
        [11018002] = {
          Camera = "436.131592,1.919922,136.800903,0.000139,-1.999415,173.000534,35.0,100000.0,false,Manual,22.0",
          Content = "接下来的任务容不得出任何错，我们还是得排除风险——小姑娘和老人家不能跟着了。",
          DialogueId = 11018002,
          GUID = "1B9518F4",
          LookAt = {
            [1] = "110010:n(110034)"
          },
          NextDialogue = 11018003,
          SpeakNpcId = 110010,
          Subtitle = "We cannot afford any mistakes in our mission moving forward. We have to rule out all the potential risks — this girl and the old man, they should stop here.",
          VoiceName = "voice/$Locale$/story/1002/110180/1B9518F4"
        },
        [11018003] = {
          Camera = "27.165649,69.382324,136.855469,0.000141,-0.199305,10.000502,35.0,100000.0,false,DoNotOverride,22.0",
          Content = "……为什么？刚才您也看到了，到处都是秽兽，如果在这里和你们分开，我和爷爷一定会没命的！",
          DialogueId = 11018003,
          FacialId = {
            [1] = "110034:Sad01"
          },
          GUID = "1B95191E",
          LookAt = {
            [1] = "110034:n(110010)",
            [2] = "110022:n(110034)"
          },
          NextDialogue = 11018004,
          Scripts = "CameraMoveTo{_delay{8},TargetPosition{\"-263.419067,35.512207,120.94928,0.000142,0.800758,5.202505,30.0,100000.0,false,DoNotOverride,22.0\"},duration{0}}",
          SpeakNpcId = 110034,
          Subtitle = "...Why? As you can see, there are Filthoids all over this place. If you leave us here, Mr Frank and I will die!",
          VoiceName = "voice/$Locale$/story/1002/110180/1B95191E"
        },
        [11018004] = {
          Camera = "-143.649597,-86.15332,142.109314,0.000144,-2.799244,26.800621,35.000008,100000.0,false,DoNotOverride,22.0",
          Content = "长官，我帮过您的！您想，我刚刚给您带路，帮您顺利会合……求求您……求求您不要抛下我们！",
          DialogueId = 11018004,
          GUID = "1B951948",
          LookAt = {
            [1] = "110034:n(110022)",
            [2] = "110017:n(110010)"
          },
          NextOptions = {
            [1] = 11018005,
            [2] = 11018008
          },
          Scripts = "LookAt{_delay{1},LookAtDescription{\"110022:n(110034)\"}}",
          SpeakNpcId = 110034,
          Subtitle = "Sir, please! We offered help, we led you all the way here so you could rendezvous with them... Please... I'm begging you, don't leave us behind!",
          VoiceName = "voice/$Locale$/story/1002/110180/1B951948"
        },
        [11018005] = {
          Content = "信任卡嘉",
          DialogueId = 11018005,
          GUID = "1B951972",
          ImprPlusId = 1009,
          NextDialogue = 11018006,
          Subtitle = "Trust Katya"
        },
        [11018006] = {
          Camera = "-372.804108,82.572754,153.340088,0.000149,-3.999233,-7.999348,50.000011,450.777496,false,DoNotOverride,7.0",
          Content = "老师也许多虑了。如果他们是敌人，那么在地下水道故意带错路会是更好的选择，但他们没有这么做。",
          DialogueId = 11018006,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95199C",
          LookAt = {
            [1] = "110022:n(110010)",
            [2] = "110010:n(110010)"
          },
          NextDialogue = 11018007,
          SpeakNpcId = 110022,
          Subtitle = "Maybe you're overthinking it, sir. If they were enemies, misleading us in the sewer tunnels would be a better idea, but they didn't do that.",
          TalkActionId = {
            [1] = "110022:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110180/1B95199C"
        },
        [11018007] = {
          Camera = "32.585205,14.534668,146.054871,0.00015,-1.399219,162.798279,50.0,100000.0,false,DoNotOverride,22.0",
          Content = "如果他们另有打算呢。你不觉得，刚才这一路，他们“过于了解”这座要塞了吗？",
          DialogueId = 11018007,
          GUID = "1B9519C6",
          LookAt = {
            [1] = "110010:n(110022)"
          },
          NextDialogue = 11018011,
          SpeakNpcId = 110010,
          Subtitle = "What if they're up to something else? Don't you think that they are \"too familiar\" with everything of this fortress along the way?",
          TalkActionId = {
            [1] = "110022:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110180/1B9519C6"
        },
        [11018008] = {
          Content = "不信任卡嘉",
          DialogueId = 11018008,
          GUID = "1B9519F0",
          ImprPlusId = 1008,
          NextDialogue = 11018009,
          Subtitle = "Do not trust Katya"
        },
        [11018009] = {
          Camera = "209.203857,228.964844,146.143616,0.000167,-4.599087,-120.406746,45.000011,100000.0,false,DoNotOverride,22.0",
          Content = "……我赞同老师的判断。",
          DialogueId = 11018009,
          ExStoryInfo = "EXPlayer",
          GUID = "1B951A1A",
          LookAt = {
            [1] = "110022:n(110034)"
          },
          NextDialogue = 11018010,
          Scripts = "SetRotation{SetRotationDescription{\"110022:n(110034)\"}}",
          SpeakNpcId = 110022,
          Subtitle = "...I Agree with Sir Avar.",
          TalkActionId = {
            [1] = "110022:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110180/1B951A1A"
        },
        [11018010] = {
          Camera = "-127.301941,-114.787598,142.109314,0.000143,-1.599302,31.20196,35.0,100000.0,false,DoNotOverride,22.0",
          Content = "如果是进中央控制室之前，我还可以勉强信任你；但是现在看来你似乎“过于了解”这座要塞了。",
          DialogueId = 11018010,
          ExStoryInfo = "EXPlayer",
          GUID = "1B951A44",
          LookAt = {
            [1] = "110010:n(110022)",
            [2] = "110022:n(110034)"
          },
          NextDialogue = 11018011,
          SpeakNpcId = 110022,
          Subtitle = "I could have trusted you if we haven't got into the central control room. But now it seems to me that you're just \"too familiar\" with this fortress.",
          VoiceName = "voice/$Locale$/story/1002/110180/1B951A44"
        },
        [11018011] = {
          Camera = "414.556763,7.735352,138.894348,0.000155,-2.599324,169.392776,50.000008,100000.0,false,DoNotOverride,22.0",
          Content = "中央控制室是龙莎要塞的中枢，就算是同盟，也不会允许路边随便抓来的苦力来这种核心区域闲逛。",
          DialogueId = 11018011,
          GUID = "1B951A6E",
          LookAt = {
            [1] = "110010:n(110010)"
          },
          NextDialogue = 11018012,
          SpeakNpcId = 110010,
          Subtitle = "The central control room is the core of Lonza Fortress, even the Forsakens wouldn't let their enslaved labor hang out in such an essential place.",
          TurnTo = {
            [1] = "110022:n(110010)"
          },
          VoiceName = "voice/$Locale$/story/1002/110180/1B951A6E"
        },
        [11018012] = {
          Content = "你不该对里面的路线也如此轻车熟路。",
          DialogueId = 11018012,
          GUID = "1B951A98",
          LookAt = {
            [1] = "110010:n(110034)"
          },
          NextDialogue = 11018013,
          SpeakNpcId = 110010,
          Subtitle = "You're not supposed to know the routes so well.",
          TalkActionId = {
            [1] = "110010:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110180/1B951A98"
        },
        [11018013] = {
          Camera = "-38.761108,62.896484,133.47168,0.000157,0.600497,8.994007,50.000008,100000.0,false,DoNotOverride,22.0",
          Content = "呃……那是因为——",
          DialogueId = 11018013,
          GUID = "1B951AC2",
          LookAt = {
            [1] = "110034:n(110010)"
          },
          NextDialogue = 11018014,
          SpeakNpcId = 110034,
          Subtitle = "Umm... That's because—",
          TalkActionId = {
            [1] = "110022:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110180/1B951AC2"
        },
        [11018014] = {
          Camera = "528.188843,-8.837402,130.242065,0.000159,-1.599541,172.787582,50.000008,824.380615,false,Manual,10.0",
          Content = "小姑娘，这么喜欢演戏，还是去皇都的大剧院演吧。",
          DialogueId = 11018014,
          GUID = "1B951AEC",
          LookAt = {
            [1] = "110010:n(110010)"
          },
          NextDialogue = 11018015,
          SpeakNpcId = 110010,
          Subtitle = "If you're so interested in acting, little girl, I suggest you find a job in the Grand Theatre in the capital.",
          VoiceName = "voice/$Locale$/story/1002/110180/1B951AEC"
        },
        [11018015] = {
          Camera = "-1102.632935,-197.335449,128.499756,0.000169,-1.399683,12.991217,50.0,100000.0,false,DoNotOverride,22.0",
          Content = "时间不多了，我们走。莱昂，留下来看好他们。",
          DialogueId = 11018015,
          GUID = "1B951B16",
          SpeakNpcId = 110010,
          Subtitle = "We're running out of time. Let's go. Leon, stay here and keep an eye on them.",
          TalkActionId = {
            [1] = "110010:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110180/1B951B16"
        },
        [11018101] = {
          Content = "年轻的士兵半倚着冰冷的墙壁，已经没了气息。一道巨大的爪痕穿过他的胸口，将他贯穿。在刚刚的巨型秽兽面前，普通人类的力量太微弱了。",
          DialogueId = 11018101,
          GUID = "1B952932",
          VoiceName = "voice/$Locale$/story/1002/110181/1B952932"
        }
      }
    end
  },
  {
    MinKey = 11018102,
