          SnapShot = "HEART",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110181/1B95295C"
        },
        [11018201] = {
          Content = "先解决那个神弃者！这群秽兽受他操弄！",
          DialogueId = 11018201,
          GUID = "1B95399A",
          SpeakNpcId = 110010,
