          ExStoryInfo = "EXPlayer",
          GUID = "1B956AFC",
          NextDialogue = 11018503,
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110185/1B956AFC"
        },
        [11018503] = {
          Content = "是……他的铭牌……",
          DialogueId = 11018503,
          GUID = "1B956B26",
          NextDialogue = 11018504,
          SpeakNpcId = 110020,
          VoiceName = "voice/$Locale$/story/1002/110185/1B956B26"
        },
        [11018504] = {
          Content = "“莫妮卡，下次射击比赛我一定会赢你”……哈，哈哈……混账，这算什么……",
          DialogueId = 11018504,
          ExStoryInfo = "EXPlayer",
          GUID = "1B956B50",
          NextDialogue = 11018505,
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110185/1B956B50"
        },
        [11018505] = {
          Content = "早知道这么记仇……上次就让着他了……",
          DialogueId = 11018505,
          GUID = "1B956B7A",
          NextDialogue = 11018506,
          SpeakNpcId = 110020,
          VoiceName = "voice/$Locale$/story/1002/110185/1B956B7A"
        },
        [11018506] = {
          Content = "……莫妮卡，接下来恐怕又是一场恶战，别分心。",
