          VoiceName = "voice/$Locale$/story/1002/110188/1B959DAE"
        },
        [11018812] = {
          Content = "（一份布防计划书，详细记录着神弃者同盟在撤离前夕，于龙莎要塞布设陷阱的安排。工程师的签名为：卡嘉·厄恩。）",
          DialogueId = 11018812,
          GUID = "1B959DD8",
          NextDialogue = 11018813,
          VoiceName = "voice/$Locale$/story/1002/110188/1B959DD8"
        },
        [11018813] = {
          Content = "（原来是她。）",
          DialogueId = 11018813,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B959E02",
          NextDialogue = 11018821,
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110188/1B959E02"
        },
        [11018814] = {
          Content = "查阅第二份文件",
          DialogueId = 11018814,
          GUID = "1B959E2C",
          NextDialogue = 11018815,
          VoiceName = "voice/$Locale$/story/1002/110188/1B959E2C"
        },
        [11018815] = {
          Content = "龙莎要塞位于红溪河谷畔高地，一度扼守皇都与红溪城的水路交通要道。帝国根基尚未稳固之时，初代皇帝盖雷亚在此设伏，击败了敌对的联军，奠定了他一统帝国全境的基础。",
          DialogueId = 11018815,
          GUID = "1B959E56",
          NextDialogue = 11018816,
          VoiceName = "voice/$Locale$/story/1002/110188/1B959E56"
        },
        [11018816] = {
          Content = "但是随着迪斯玛尼亚与红溪城之间铁路的开通，距离铁路尚有一段距离的龙莎要塞地位有所下降，从重要的交通关口变成了单纯的军事要塞。",
          DialogueId = 11018816,
          GUID = "1B959E80",
          NextDialogue = 11018817,
          VoiceName = "voice/$Locale$/story/1002/110188/1B959E80"
        },
        [11018817] = {
