        },
        [12004001] = {
          Camera = "127.357666,-54.3125,106.762451,0.000013,7.799898,-163.400085,35.0,100000.0,False,Manual,10.0",
          Content = "选A还是B",
          DialogueId = 12004001,
          GUID = "1E0CFE6A",
          SpeakNpcId = 100001
        },
        [12004002] = {
          Content = "A",
          DialogueId = 12004002,
          GUID = "1E0CFE94",
          SpeakNpcId = 100001
        },
        [12004003] = {
          Content = "B",
          DialogueId = 12004003,
          GUID = "1E0CFEBE",
          SpeakNpcId = 200002
        },
        [12004101] = {
          Content = "……哇，好多人哦。大家都是来看剧的吗？",
          DialogueId = 12004101,
          GUID = "1E0AE102",
          NextDialogue = 12004102,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120007/1E0AE102"
        },
        [12004102] = {
          Content = "他们好像在聊一些很有意思的事情，小仆从，我们去听听看吧。",
          DialogueId = 12004102,
          GUID = "1E0D0EFC",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120041/1E0D0EFC"
        },
        [12004201] = {
          Content = "止流姐姐，你去水仙平原，莫非是要见什么人？",
          DialogueId = 12004201,
          GUID = "1E0D1F3A",
          NextDialogue = 12004202,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D1F3A"
        },
        [12004202] = {
          Content = "让白猜猜……该不会是一位金色大波浪、说起话来凶巴巴的老板娘吧！",
          DialogueId = 12004202,
          GUID = "1E0D1F64",
          NextDialogue = 12004203,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D1F64"
        },
        [12004203] = {
          Content = "呵呵，这都被你猜中了。",
          DialogueId = 12004203,
          GUID = "1E0D1F8E",
          NextDialogue = 12004204,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D1F8E"
        },
        [12004204] = {
          Content = "魔王大人当然是料事如神啦！",
          DialogueId = 12004204,
          GUID = "1E0D1FB8",
          NextDialogue = 12004205,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D1FB8"
        },
        [12004205] = {
          Content = "啊，不过，刚刚的话，可千万别对卡米拉说哦……不然今天的零花钱又要被扣光了。",
          DialogueId = 12004205,
          GUID = "1E0D1FE2",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D1FE2"
        },
        [12004206] = {
          Content = "我们到啦——",
          DialogueId = 12004206,
          GUID = "1E0D200C",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D200C"
        },
        [12004301] = {
          Content = "皎皎气呼呼地跑走了。",
          DialogueId = 12004301,
          Duration = 2,
          GUID = "1E0D2FA2",
          VoiceName = "voice/$Locale$/story/1200/120043/1E0D2FA2"
        },
        [12004401] = {
          Content = "那边的机器奇奇怪怪的……唔，总觉得绕开它们比较好！",
          DialogueId = 12004401,
          GUID = "1E0D400A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120044/1E0D400A"
        },
        [12004402] = {
          Content = "它转过去啦，就是现在——",
          DialogueId = 12004402,
          GUID = "1E0D4034",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120044/1E0D4034"
        },
        [12004501] = {
          Content = "<W>发现追捕目标，发现追捕目标。</>",
          DialogueId = 12004501,
          GUID = "1E0D5072",
          NextDialogue = 12004502,
          VoiceName = "voice/$Locale$/story/1200/120045/1E0D5072"
        },
        [12004502] = {
          Content = "哇啊……我们的行踪好像暴露了！",
          DialogueId = 12004502,
          GUID = "1E0D509C",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120045/1E0D509C"
        },
        [12004503] = {
          Content = "任务失败，请重新开始。",
          DialogueId = 12004503,
          GUID = "1E0D509D",
          SpeakNpcId = 200002
        },
        [12004504] = {
          Content = "被动失败",
          DialogueId = 12004504,
          GUID = "1E0D509E",
          SpeakNpcId = 200002
        },
        [12030001] = {
          Content = "那是不久之前，发生在冰湖城的一段故事——",
          DialogueId = 12030001,
          Duration = 4,
          GUID = "1E1DA80A",
          NextDialogue = 12030002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DA80A"
        },
        [12030002] = {
          Content = "当一只小夜莺，决定勇敢地飞出它温暖的巢穴。",
          DialogueId = 12030002,
          Duration = 4,
          GUID = "1E1DA834",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DA834"
        },
        [12030003] = {
          Content = "菲娜坐在家里，看着故事书",
          DialogueId = 12030003,
          GUID = "1E1DA85E",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DA85E"
        },
        [12030101] = {
          Content = "菲娜，晚上光线太暗，看书伤眼睛，还是早点睡吧。",
          DialogueId = 12030101,
          GUID = "1E1DB872",
          NextDialogue = 12030102,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB872"
        },
        [12030102] = {
          Content = "唔……",
          DialogueId = 12030102,
          GUID = "1E1DB89C",
          NextDialogue = 12030103,
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB89C"
        },
        [12030103] = {
          Content = "怎么了？",
          DialogueId = 12030103,
          GUID = "1E1DB8C6",
          NextDialogue = 12030104,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB8C6"
        },
        [12030104] = {
          Content = "奥特赛德，菲娜……菲娜有一个愿望！",
          DialogueId = 12030104,
          GUID = "1E1DB8F0",
          NextDialogue = 12030105,
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB8F0"
        },
        [12030105] = {
          Content = "是吗？你说，是什么愿望？",
          DialogueId = 12030105,
          GUID = "1E1DB91A",
          NextDialogue = 12030106,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB91A"
        },
        [12030106] = {
          Content = "菲娜想出去看看。",
          DialogueId = 12030106,
          GUID = "1E1DB944",
          NextDialogue = 12030107,
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB944"
        },
        [12030107] = {
          Content = "出去……？现在吗？",
          DialogueId = 12030107,
          GUID = "1E1DB96E",
          NextDialogue = 12030108,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB96E"
        },
        [12030108] = {
          Content = "不是的，菲娜的意思是，菲娜也想像你和独角兽{性别：先生|小姐}一样，去外面的世界，认识很多的新朋友……",
          DialogueId = 12030108,
          GUID = "1E1DB998",
          NextDialogue = 12030109,
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB998"
        },
        [12030109] = {
          Content = "这可不行，外面很危险的。我和{nickname}大多数时候遇到的都不是朋友，而是秽——怪兽，和很多坏——坏巫师，对，那些坏巫师可吓人了。",
          DialogueId = 12030109,
          GUID = "1E1DB9C2",
          NextDialogue = 12030110,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB9C2"
        },
        [12030110] = {
          Content = "所以，你还是待在家里最安全。",
          DialogueId = 12030110,
          GUID = "1E1DB9EC",
          NextDialogue = 12030111,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB9EC"
        },
        [12030111] = {
          Content = "呜……",
          DialogueId = 12030111,
          GUID = "1E1DBA16",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DBA16"
        },
        [12030112] = {
          Content = "转场，菲娜在睡觉，奥特赛德看到桌上的故事书",
          DialogueId = 12030112,
          GUID = "1E1DBA40",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DBA40"
        },
        [12030201] = {
          Camera = "-345.501678,523.378906,124.574219,0.000322,-4.833527,90.822472,35.000008,77.550713,false,Manual,4.0",
          Content = "“大魔法师总是说，巢穴外的世界充满了危险，呆在巢穴里才是最安全的……可是小小的巢穴虽然温暖，却只能看到一小片方形的天空。”",
          DialogueId = 12030201,
          FinalCamera = "-351.068237,428.320312,123.277344,0.000143,-3.242031,91.01268,35.000008,212.663025,false,Manual,2.8",
