PlayFacial{ActorId{211001},FacialId{"Think01"}}
}]],
          SpeakNpcId = 211001,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F11A2"
        },
        [12032206] = {
          Camera = "-82.042175,-125.063324,139.085938,0.000125,-4.602113,49.317894,35.000008,159.098129,false,Manual,2.8",
          Content = "而且，她是一个小朋友呀！菲娜像她这么大的时候，曾经被一个不知道名字的哥哥帮助过……",
          DialogueId = 12032206,
          GUID = "1E1F11CC",
          NextDialogue = 12032207,
          Scripts = [[
PARA{
PlayAnimation{ActorId{211001},AnimationId{"Think_End"},Duration{1}},
PlayFacial{ActorId{211001},FacialId{"None"}}
}]],
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F11CC"
        },
        [12032207] = {
          Camera = "6.907836,-321.75943,129.159912,0.000122,-0.802151,102.716034,24.0,159.098129,false,Manual,10.0",
          Content = "那时候我就想，等我长大之后，如果遇到了需要帮助的小朋友，我也要像那个哥哥一样帮助他们。",
          DialogueId = 12032207,
          GUID = "1E1F11F6",
          NextDialogue = 12032208,
          Scripts = [[
PARA{
PlayAnimation{ActorId{211001},AnimationId{"Talk03_Start"},Duration{1}},
PlayFacial{ActorId{211001},FacialId{"Sad01"}}
}]],
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F11F6"
        },
        [12032208] = {
          Camera = "-217.036926,-261.586731,133.03418,0.000126,0.197871,53.31599,35.000011,311.586395,false,Manual,2.8",
          Content = "所以，我想去找那个女孩子问问清楚！如果她真的遇到了困难，我不能视而不见。",
          DialogueId = 12032208,
          GUID = "1E1F1220",
          NextDialogue = 12032209,
          Scripts = [[
