          Camera = "-141.834106,56.707031,63.160034,0.000304,-0.200958,-24.822062,50.0,100000.0,false,DoNotOverride,2.8",
          Content = "你、你叫谁小妹妹！现在的年轻人呐，真是越来越不像话啦。",
          DialogueId = 20000504,
          Duration = 2,
          FinalCamera = "-4.205322,-7.019043,62.62915,0.000304,-0.200958,-24.621468,50.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "3211B4B0",
          NextDialogue = 20000505,
          Scripts = "CameraMoveTo{_delay{4},TargetPosition{\"97.50293,-158.120117,52.408936,0.000361,4.799082,121.579559,35.0,326.036194,false,Manual,3.779846\"},duration{0}}",
          SpeakNpcId = 200024,
          Subtitle = "Who are you calling \"girl\"? The younger generation nowadays is so disrespectful.",
          ToFinalCameraBlendTime = 0.14,
          VoiceName = "voice/$Locale$/story/2001/200005/3211B4B0"
        },
        [20000505] = {
          Camera = "235.176758,-74.227051,29.45166,0.00002,4.799417,154.775711,30.0,549.221008,false,Manual,2.095314",
          Content = "你呀，要讲礼貌！虽然皎皎之民看上去都和白一样年轻，但她的年龄其实已经可以当你外婆的外婆的外婆啦……",
          DialogueId = 20000505,
          Duration = 3,
          GUID = "3211B4DA",
          LookAt = {
            [1] = "100001:n(200025)"
          },
          NextDialogue = 20000506,
          Scripts = "CameraMoveTo{_delay{3},TargetPosition{\"10.674805,-22.738281,62.996094,0.000332,-4.200955,-11.227787,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}}",
          SpeakNpcId = 200025,
          Subtitle = "You should watch what you say! ",
          TalkActionId = {
            [1] = "200025:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200005/3211B4DA"
        },
        [20000506] = {
          Camera = "-581.26001,-186.462891,199.332764,0.000334,-14.00104,20.363876,50.0,100000.0,false,DoNotOverride,2.8",
          Content = "（眼前扛着锤子的“女孩”，与早些时间认识的白，她们的外貌和声音如此相似，但年龄阅历却似乎完全不同——<H>皎皎之民</>，真是一群不可思议的家伙。）",
          DialogueId = 20000506,
          DialoguePanelType = "Voiceover",
          DisableMouth = 1,
          Duration = 1,
          FinalCamera = "-603.849854,-194.84375,205.341797,0.000334,-14.00104,20.363876,50.0,100000.0,false,DoNotOverride,2.8",
          GUID = "3211B52E",
          LookAt = {
            [1] = "100001:n(200024)"
          },
          Scripts = "SetLocation{ActorId{100001},TargetPoint{\"P200005Nvzhu1\"},Visibility{\"Show\"}}",
          Subtitle = "(The young \"girl\" with a hammer had a similar voice and appearance as Snow, but their age and experiences were completely different. Lunos are indeed peculiar.)",
          TalkOptions = {
            [1] = 2000050601,
            [2] = 2000050602
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/2001/200005/3211B52E"
        },
        [20000508] = {
          Camera = "-97.633606,36.260742,62.989868,0.000304,-0.200958,-24.822792,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "嗯，还算懂事。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000508,
          Duration = 3,
          FacialId = {
            [1] = "200024:Satisfy01"
          },
          GUID = "3211B558",
          LookAt = {
            [1] = "200024:n(100001)"
          },
          NextDialogue = 20000511,
          SpeakNpcId = 200024,
          Subtitle = "Very well. I'll let it slide this time.",
          TurnTo = {
            [1] = "200025:n(200024)"
          },
          VoiceName = "voice/$Locale$/story/2001/200005/3211B558"
        },
        [20000509] = {
          Camera = "-97.633606,36.260742,62.989868,0.000304,-0.200958,-24.822792,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "你……哼！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000509,
          Duration = 3,
          FacialId = {
            [1] = "200024:Confident02"
          },
          FinalCamera = "-64.05127,20.728027,62.859619,0.000304,-0.200958,-24.822519,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "3211B582",
          LookAt = {
            [1] = "200024:n(100001)"
          },
          NextDialogue = 20000510,
          SpeakNpcId = 200024,
          Subtitle = "You! Hmph!",
          ToFinalCameraBlendTime = 0.2,
          TurnTo = {
            [1] = "200025:n(200024)"
          },
          VoiceName = "voice/$Locale$/story/2001/200005/3211B582"
        },
        [20000510] = {
          BlendTime = 3,
          Camera = "-97.633606,36.260742,62.989868,0.000304,-0.200958,-24.822792,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "算了，老朽不和小孩子计较。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000510,
          Duration = 3,
          FacialId = {
            [1] = "200024:Syouganai01"
          },
          GUID = "3211B5AC",
          NextDialogue = 20000511,
          SpeakNpcId = 200024,
          Subtitle = "Never mind, arguing with a youngster isn't worth my time.",
          VoiceName = "voice/$Locale$/story/2001/200005/3211B5AC"
        },
        [20000511] = {
          Content = "其实呢，刚刚你们路过的时候啊，老朽嗅到了了不得的东西。",
          DialogueId = 20000511,
          Duration = 2,
          FacialId = {
            [1] = "200024:None"
          },
          GUID = "3211B5D6",
          NextDialogue = 20000512,
          SpeakNpcId = 200024,
          Subtitle = "Actually, I caught a whiff of something remarkable as you passed by just now.",
          VoiceName = "voice/$Locale$/story/2001/200005/3211B5D6"
        },
        [20000512] = {
          Camera = "-448.745361,204.227051,210.797119,0.000268,-16.801117,-22.812357,80.0,100000.0,false,DoNotOverride,2.8",
          Content = "没错，就是<H>稀世神兵</>的味道！年轻人，你是不是藏着什么了不得的武器?",
          DialogueId = 20000512,
          Duration = 2,
          FacialId = {
            [1] = "200024:Confident02"
          },
          GUID = "3211B600",
          NextDialogue = 20000513,
          SpeakNpcId = 200024,
          Subtitle = "That's right. It's the scent of a legendary weapon! Do you have any special weapons on you, kiddo?",
          VoiceName = "voice/$Locale$/story/2001/200005/3211B600"
        },
        [20000513] = {
          Camera = "228.46167,-372.115723,10.04248,0.000321,7.79886,123.18483,80.0,614.449585,false,Manual,4.066936",
          Content = "武器？我只有这把剑……",
          DialogueId = 20000513,
          Duration = 3,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "3211B62A",
          NextDialogue = 20000514,
          SpeakNpcId = 100001,
          Subtitle = "This sword is all I have.",
          TalkActionId = {
            [1] = "100001:Give"
          },
          VoiceName = "voice/$Locale$/story/2001/200005/3211B62A"
        },
        [20000514] = {
          Camera = "-77.902344,12.708496,47.934082,0.00031,5.598692,-20.219845,50.0,100000.0,false,DoNotOverride,2.8",
          Content = "……！",
          DialogueId = 20000514,
          Duration = 2,
          FacialId = {
            [1] = "200024:Shock02"
          },
          FinalCamera = "-56.127686,4.689941,50.209229,0.00031,5.598692,-20.219845,50.0,100000.0,false,DoNotOverride,2.8",
          GUID = "3211B654",
          NextDialogue = 20000515,
          SpeakNpcId = 200024,
          Subtitle = "!!!",
          ToFinalCameraBlendTime = 0.2,
          VoiceName = "voice/$Locale$/story/2001/200005/3211B654"
        },
        [20000515] = {
          Camera = "-1132.003174,-2957.388672,210.885498,0.000319,-1.000759,65.576195,27.995377,100000.0,false,DoNotOverride,2.8",
          Content = "（她仔细打量着这把剑，仿佛想要从它的纹路里读出什么。）",
          DialogueId = 20000515,
          DialoguePanelType = "Voiceover",
          DisableMouth = 1,
          Duration = 3,
          FinalCamera = "-1148.861572,-2949.662109,210.885498,0.000319,-1.000759,64.376427,27.995377,100000.0,false,DoNotOverride,2.8",
          GUID = "3211B67E",
          NextDialogue = 20000516,
          Subtitle = "(She carefully examined the sword, attempting to glean some information from its pattern.)",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/2001/200005/3211B67E"
        },
        [20000516] = {
          Camera = "-134.061523,50.801758,95.63208,0.000289,-10.201447,-24.418987,50.000008,100000.0,false,DoNotOverride,2.8",
          Content = "好剑、好剑呀！这剑无论是看材质还是手法，都不是海伯利亚这群庸才的手笔。你年纪轻轻，怎么弄到这种宝贝的？",
          DialogueId = 20000516,
          Duration = 2,
          FacialId = {
            [1] = "200024:Happy01"
          },
          GUID = "3211B6A8",
          NextDialogue = 20000517,
          SpeakNpcId = 200024,
          Subtitle = "Jesus! That's incredible! Look at the texture and the craftsmanship! This clearly wasn't made by those mediocre Hyperborean blacksmiths. Where did you get it?",
          VoiceName = "voice/$Locale$/story/2001/200005/3211B6A8"
        },
        [20000517] = {
          Camera = "-197.926575,232.563965,156.319824,0.000096,-15.201227,-51.775345,50.0,100000.0,false,DoNotOverride,2.8",
          Content = "（在这位皎皎铁匠的眼中，这把剑似乎并不同寻常。于是几天前的回忆再次苏醒：这把剑曾是一把打开遗迹大门的钥匙。然而，它究竟从何而来——这依旧是个谜。）",
          DialogueId = 20000517,
          DialoguePanelType = "Voiceover",
          DisableMouth = 1,
          Duration = 2,
          GUID = "3211B6FC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20000518.T_Story_Recall_20000518'",
          LookAt = {
            [1] = "100001:p(200005Point2)"
          },
          NextDialogue = 20000519,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          Subtitle = "(The Luno blacksmith recognised that this sword was no ordinary weapon. )",
          VoiceName = "voice/$Locale$/story/2001/200005/3211B6FC"
        },
        [20000519] = {
          Camera = "47.933167,48.183594,106.281372,0.000106,0.998942,164.023529,50.0,162.033707,false,Manual,14.755679",
          Content = "我不知道……",
          DialogueId = 20000519,
          Duration = 3,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Uninterested01"
          },
          GUID = "3211B750",
          NextDialogue = 20000520,
          SpeakNpcId = 100001,
          Subtitle = "I'm not sure...",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200005/3211B750"
        },
        [20000520] = {
          Camera = "47.933167,48.183594,106.281372,0.000106,0.998942,164.023529,50.0,162.033707,false,Manual,14.755679",
          Content = "从我记事起，这把剑就在我身边了。也许是我父母留下的?",
          DialogueId = 20000520,
          Duration = 2,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "3211B77A",
          LookAt = {
            [1] = "200024:n(100001)"
          },
          NextDialogue = 20000522,
          SpeakNpcId = 100001,
          Subtitle = "I got it when I was young. Maybe it was passed down to me by my parents?",
          VoiceName = "voice/$Locale$/story/2001/200005/3211B77A"
        },
        [20000522] = {
          Camera = "-189.288086,203.751465,151.934326,0.000147,-16.40097,-49.57642,50.000008,162.033707,false,Disable,14.755679",
          Content = "有趣，有趣。老朽当了一辈子铁匠，也要甘拜下风啦。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000522,
          Duration = 3,
          FacialId = {
            [1] = "200024:Happy02"
          },
          GUID = "3211B7CE",
          NextDialogue = 20000523,
          SpeakNpcId = 200024,
          Subtitle = "Intriguing. Very intriguing. I've been a blacksmith my whole life, yet I've never seen a weapon like this before.",
          VoiceName = "voice/$Locale$/story/2001/200005/3211B7CE"
        },
        [20000523] = {
          Content = "年轻人啊，老朽常年漂泊在外，居无定所。要不，就让老朽跟随你—阵子?",
          DialogueId = 20000523,
          Duration = 3,
          FacialId = {
            [1] = "200024:Smile02"
          },
          GUID = "3211B7F8",
          NextDialogue = 20000524,
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "Kiddo, I'm Lunosmith, a wandering blacksmith. Would you mind if I accompanied you on your journey?",
          VoiceName = "voice/$Locale$/story/2001/200005/3211B7F8"
        },
        [20000524] = {
          Camera = "-38.022217,110.633789,44.966553,0.000129,4.598534,-58.971298,50.000008,162.033707,false,Disable,14.755679",
          Content = "从海伯利亚到艾利西安，老朽见过、锻造过的武器可多啦！如果你想锻造什么兵器，就包在我身上吧。",
          DialogueId = 20000524,
          Duration = 2,
          FinalCamera = "-38.022217,110.633789,46.349609,0.000129,4.598534,-58.971333,50.000008,162.033707,false,Disable,14.755679",
          GUID = "3211B822",
          NextDialogue = 20000525,
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "I've travelled all over the land, from Hyperborea to Elysium, and I've forged countless weapons. If you require any weapons, I'm at your disposal.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/2001/200005/3211B822"
        },
        [20000525] = {
          Camera = "232.871338,-185.234375,83.503784,0.000127,-5.002772,134.234024,60.0,100000.0,false,DoNotOverride,2.8",
          Content = "哇，原来是铁匠前辈啊！",
          DialogueId = 20000525,
          Duration = 3,
          FacialId = {
            [1] = "200025:Shock02"
          },
          GUID = "3211B84C",
          NextDialogue = 20000526,
          SpeakNpcId = 200025,
          Subtitle = "Wow! So you're an experienced master blacksmith!",
          TalkActionId = {
            [1] = "200025:SpecialHappy_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200005/3211B84C"
        },
        [20000526] = {
          Camera = "-189.288086,203.751465,151.934326,0.000147,-16.40097,-49.57642,50.000008,162.033707,false,Disable,14.755679",
          Content = "价钱肯定比外面的铁匠便宜！你只要让我得空研究研究你那把剑就好了，哈哈。",
          DialogueId = 20000526,
          Duration = 2,
          FacialId = {
            [1] = "200024:Happy02"
          },
          GUID = "3211B876",
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "All I request is a basic salary, and an opportunity to examine your sword, hehe.",
          TalkActionId = {
            [1] = "200025:SpecialHappy_End"
          },
          TalkOptions = {
            [1] = 200005261,
            [2] = 200005262
          },
          VoiceName = "voice/$Locale$/story/2001/200005/3211B876"
        },
        [20000528] = {
          Camera = "112.837646,-162.337891,36.354004,0.000129,8.798526,128.416595,50.000008,421.26944,false,Manual,6.435696",
          Content = "嗬……年轻人的表情，这是在怀疑老朽吧。",
          DialogueId = 20000528,
          Duration = 3,
          FacialId = {
            [1] = "200024:Shock01"
          },
          FinalCamera = "114.166748,-161.282227,36.354004,0.000129,8.798526,128.416595,50.000008,421.26944,false,Manual,6.435696",
          GUID = "3211B8CA",
          LookAt = {
            [1] = "200024:n(100001)"
          },
          NextDialogue = 20000529,
          Scripts = "CameraMoveTo{_delay{3.5},TargetPosition{\"-257.094238,105.374512,89.299316,0.000146,-7.001647,-20.17968,50.000008,421.26944,false,Manual,6.435696\"},duration{0}}",
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "Look, I can see scepticism written on your face.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/2001/200005/3211B8CA"
        },
        [20000529] = {
          Camera = "-69.666748,-17.761719,56.248047,0.000116,1.798375,-8.383431,50.000008,100000.0,false,DoNotOverride,2.8",
          Content = "你大可放心——“皎皎之民永远不会主动伤害人类”，这是整片阿特拉西亚大陆人尽皆知的事实。",
          DialogueId = 20000529,
          Duration = 2,
          FacialId = {
            [1] = "200024:Ahaha02"
          },
          FinalCamera = "-69.666748,-17.761719,57.486084,0.000116,1.798375,-8.383431,50.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "3211B8F4",
          NextDialogue = 20000530,
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "You can trust me. You must know the saying, \"Lunos never harm.\" Everyone in Atlasia knows that.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/2001/200005/3211B8F4"
        },
        [20000530] = {
          Camera = "-257.729492,-42.183594,76.834473,0.000131,-5.203491,35.769909,50.0,290.309357,false,Manual,3.710212",
          Content = "就是就是！",
          DialogueId = 20000530,
          Duration = 3,
          FacialId = {
            [1] = "200025:Doubt01"
          },
          GUID = "3211B91E",
          LookAt = {
            [1] = "200025:n(100001)"
          },
          NextDialogue = 20000531,
          SpeakNpcId = 200025,
          Subtitle = "Yes, exactly!",
          TalkActionId = {
            [1] = "200025:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200005/3211B91E"
        },
        [20000531] = {
          Camera = "-7.611328,-33.099121,102.976074,0.0,0.0,129.770859,35.0,211.517212,false,Manual,3.358988",
          Content = "（没错，身为皎皎之民的白就是一个热心肠的孩子。更何况，我身上也没什么值钱的东西，一名铁匠又能图谋什么呢？）",
          DialogueId = 20000531,
          DialoguePanelType = "Voiceover",
          DisableMouth = 1,
          Duration = 2,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Confident01"
          },
          FinalCamera = "-15.199463,-23.983398,104.64917,0.0,0.0,129.770859,35.0,211.517212,false,Manual,3.358988",
          GUID = "3211B948",
          NextDialogue = 20000532,
          Subtitle = "(She was right. You could see that trait in Snow. Besides, what could she get from you? You have nothing to offer.)",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/2001/200005/3211B948"
        },
        [20000532] = {
          Camera = "-2423.703857,1080.132324,250.907959,0.000098,-4.001944,-26.573547,60.0,100000.0,false,DoNotOverride,2.8",
          Content = "嗯，我想多了。那我们一起回去吧。",
          DialogueId = 20000532,
          Duration = 3,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Happy02"
          },
          GUID = "3211B972",
          NextDialogue = 20000533,
          SpeakNpcId = 100001,
          Subtitle = "Yeah, you're right. Let's head back together then.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200005/3211B972"
        },
        [20000533] = {
          Camera = "-2423.703857,1080.132324,250.907959,0.000098,-4.001944,-26.573547,60.0,100000.0,false,DoNotOverride,2.8",
          Content = "看样子年轻人这是答应啦。好，好！快带老朽去你的住处吧！",
          DialogueId = 20000533,
          Duration = 3,
          FinalCamera = "-2421.345459,1084.854004,250.907959,0.000098,-4.001944,-26.573236,60.0,100000.0,false,DoNotOverride,2.8",
          GUID = "3211B99C",
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "So you'll have me? Excellent! Then take me to where you live.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/2001/200005/3211B99C"
        },
        [20000601] = {
          Camera = "-301.271454,-116.678955,97.078186,0.000381,-2.200953,30.000952,25.0,87.874474,false,Disable,2.8",
          Content = "好厉害！不愧是前辈！",
          DialogueId = 20000601,
          Duration = 3,
          FacialId = {
