        },
        [20001801] = {
          Content = "哇……要被吹跑了！",
          DialogueId = 20001801,
          GUID = "3212897A",
          IsBlack = 1,
          NextDialogue = 20001802,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/2001/200018/3212897A"
        },
        [20001802] = {
          Content = "白，跟在我们后面，趁着风小一点的时候一起向前。",
          DialogueId = 20001802,
          ExStoryInfo = "Player",
          GUID = "321289A4",
          NextDialogue = 20001803,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/2001/200018/321289A4"
        },
        [20001803] = {
          Content = "风太大的时候也可以躲在石头后面，别着急。",
          DialogueId = 20001803,
          GUID = "321289CE",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/2001/200018/321289CE"
        },
        [20001901] = {
          Camera = "-362.765625,-80.016602,-24.530273,0.000006,17.167358,25.771385,15.0,100000.0,false,DoNotOverride,2.8",
          Content = "远处的冰湖上刮起了风暴，赛琪应该就在那个方向……",
          DialogueId = 20001901,
          GUID = "321299E2"
        },
        [20002001] = {
          Content = "……蝴蝶？冬天怎么会有蝴蝶？",
          DialogueId = 20002001,
          ExStoryInfo = "Player",
          GUID = "3212AA4A",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/2001/200020/3212AA4A"
        },
        [20002002] = {
          Content = "就像是……在为我们引路一样……",
          DialogueId = 20002002,
          ExStoryInfo = "Player",
          GUID = "3212AA74",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/2001/200020/3212AA74"
        },
        [20002101] = {
          Content = "这些秽兽都半死不活的，很可能是和赛琪交过手。",
          DialogueId = 20002101,
          GUID = "3212BAB2",
          NextDialogue = 20002102,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/2001/200021/3212BAB2"
        },
        [20002102] = {
          Content = "看来只要沿着它们的反方向，就能找到赛琪了……",
          DialogueId = 20002102,
          GUID = "3212BADC",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/2001/200021/3212BADC"
        },
        [20002201] = {
          Content = "兄弟，你还好吗。",
          DialogueId = 20002201,
          ExStoryInfo = "Player",
          GUID = "3212CB1A",
          NextDialogue = 20002202,
          SpeakNpcId = 100001
        },
        [20002202] = {
          Content = "不太好。",
          DialogueId = 20002202,
          GUID = "3212CB44",
          NextDialogue = 20002203
        },
        [20002203] = {
          Content = "外面情况怎么样？",
          DialogueId = 20002203,
          GUID = "3212CB6E",
          NextDialogue = 20002204
        },
        [20002204] = {
          Content = "刮了好大的风，秽兽的行为也很反常。",
          DialogueId = 20002204,
          GUID = "3212CB98"
        },
        [20002301] = {
          Content = "（已经失去理智的赛琪正在与秽蚀对抗……应该为她做些什么……）",
          DialogueId = 20002301,
          DisableMouth = 1,
          GUID = "3212DB82"
        },
        [20002401] = {
          Content = "……赛琪好像往城外去了。",
          DialogueId = 20002401,
          GUID = "3212EBEA",
          NextDialogue = 20002402,
          SpeakNpcId = 700049
        },
        [20002402] = {
          Content = "应该是因为城外人比较少吧，在还有最后一点理智的时候，尽量去人少的地方去。",
          DialogueId = 20002402,
          GUID = "3212EC14",
          SpeakNpcId = 700049
        },
        [20002501] = {
          Content = "你们……要去找赛琪吗？",
          DialogueId = 20002501,
          GUID = "3212FC52",
          NextDialogue = 20002502,
          SpeakNpcId = 200045
        },
        [20002502] = {
          Content = "找到她的话，不要犹豫，结束她的痛苦吧，我想她也希望你们这么做……",
          DialogueId = 20002502,
          GUID = "3212FC7C",
          SpeakNpcId = 200045
        },
        [20002601] = {
          Content = "刚刚那个大姐姐怎么跑那么快？",
          DialogueId = 20002601,
          GUID = "32130CBA",
          NextDialogue = 20002602,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc1",
          VoiceName = "voice/$Locale$/story/2001/200026/32130CBA"
        },
        [20002602] = {
          Content = "别问了，快走，快到城里去，那是秽蚀者！",
          DialogueId = 20002602,
          GUID = "32130CE4",
          NextDialogue = 20002603,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc2",
          VoiceName = "voice/$Locale$/story/2001/200026/32130CE4"
        },
        [20002603] = {
          Content = "别……别慌……已经有人去找卫戍部队了！",
          DialogueId = 20002603,
          GUID = "32130D0E",
          NextDialogue = 20002604,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc3",
          VoiceName = "voice/$Locale$/story/2001/200026/32130D0E"
