          },
          VoiceName = "voice/$Locale$/story/2001/200057/32150CEE"
        },
        [20005801] = {
          Content = "走吧，先往高处走，魔灵的气味更容易传到高处。",
          DialogueId = 20005801,
          GUID = "321519BA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200058/321519BA"
        },
        [20005802] = {
          Content = "啊，榛子闻到了，在那里！",
          DialogueId = 20005802,
          GUID = "321519E4",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200058/321519E4"
        },
        [20005803] = {
          Content = "是这里……但没有魔灵，只有……",
          DialogueId = 20005803,
          GUID = "32151A0E",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200058/32151A0E"
        },
        [20005804] = {
          Content = "这是他们陷阱的痕迹，好可恶，他们应该已经走了。",
          DialogueId = 20005804,
          GUID = "32151A38",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 20005805,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200058/32151A38"
        },
        [20005805] = {
          Content = "那接下来我们去人少一点的地方，气味会明显一些。",
          DialogueId = 20005805,
          GUID = "32151A62",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200058/32151A62"
        },
        [20005901] = {
          Content = "这里这里，{性别：大哥哥|大姐姐}别着急，慢点一点走，别滑倒啦。",
          DialogueId = 20005901,
          GUID = "32152A22",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200059/32152A22"
        },
        [20005902] = {
          Content = "呃……这里也是一样，有人布设过陷阱。",
          DialogueId = 20005902,
          GUID = "32152A4C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 20005903,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200059/32152A4C"
        },
        [20005903] = {
          Content = "哼唧……",
          DialogueId = 20005903,
          GUID = "32152A76",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 20005904,
          SpeakNpcId = 200086,
          VoiceName = "voice/$Locale$/story/2001/200059/32152A76"
        },
        [20005904] = {
          Content = "榛子别丧气，我们再试试下一处地方。",
          DialogueId = 20005904,
          GUID = "32152AA0",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200059/32152AA0"
        },
        [20006001] = {
