          TalkActionId = {
            [1] = "200074:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153B08"
        },
        [20006005] = {
          Camera = "-264.765686,-875.787109,308.994629,0.000174,-6.859033,150.453903,35.000015,174.116943,false,Manual,12.0",
          Content = "太好了，这次总算赶上了。先把它放出来，再等那些魔灵猎人出现吧。",
          DialogueId = 20006005,
          FinalCamera = "-222.946228,-1021.376953,416.390625,0.000172,-15.459046,141.053696,35.000015,174.116943,false,Manual,12.0",
