          SpeakNpcId = 200074,
          TalkActionId = {
            [1] = "200002:SpecialHappy_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153B32"
        },
        [20006006] = {
          Content = "一阵手忙脚乱，困在陷阱里的魔灵被救了出来，但它的态度好像……不是非常友好。",
          DialogueId = 20006006,
          GUID = "32153B5C",
          VoiceName = "voice/$Locale$/story/2001/200060/32153B5C"
        },
        [20006007] = {
          Camera = "-348.273315,-725.485352,348.286133,0.000093,-9.591675,168.57576,35.0,1674.542114,false,Manual,2.8",
          Content = "别害怕了小魔灵，本魔王大人以及小跟班，还有魔灵猎人猎人是来解救你们的，现在你自由了，远离这里吧！",
          DialogueId = 20006007,
          FacialId = {
            [1] = "200002:Confident02"
          },
          GUID = "32153B86",
          LookAt = {
            [1] = "200002:n(820000)"
          },
          NextDialogue = 20006008,
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "200002:SpecialConfident_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32153B86"
        },
        [20006008] = {
          Camera = "-1100.135376,-637.394531,335.55957,0.000086,-3.391571,1.375749,35.0,1674.542114,false,Manual,6.0",
          Content = "咿咿呀——",
          DialogueId = 20006008,
          GUID = "32153BB0",
          NextDialogue = 20006009,
          SpeakNpcId = 820000,
          SpeakNpcName = "UI_Npc_Name_PanTuokun",
          TalkActionId = {
            [1] = "200002:SpecialConfident_End"
