        },
        [20006013] = {
          Camera = "-383.416382,-617.654297,369.226074,0.000175,-13.632108,-162.021347,35.000019,174.116943,false,Manual,12.0",
          Content = "哎呀，别乱叫了，快走快走。下一次再被抓的话，可就不一定有这么好的运气了。",
          DialogueId = 20006013,
          FacialId = {
            [1] = "200002:Confident01"
          },
