        },
        [20006014] = {
          Camera = "-615.953979,-649.889648,308.302246,0.000101,-13.6588,-149.769836,35.000023,174.116943,false,Manual,12.0",
          Content = "我看……这只魔灵不太聪明嘛，和它说了这么多，都还不走。",
          DialogueId = 20006014,
          FacialId = {
            [1] = "200002:Unhappy02"
