        },
        [20006033] = {
          Camera = "-1663.477051,-843.626953,503.279785,0.000179,-12.99065,25.976145,35.0,1674.542114,false,Manual,2.8",
          Content = "本来以为冰湖城里的魔灵已经快被抓完了，没想到还有收获。",
          DialogueId = 20006033,
          GUID = "32153FCA",
          NextDialogue = 20006034,
          SpeakNpcId = 200075,
          VoiceName = "voice/$Locale$/story/2001/200060/32153FCA"
        },
        [20006034] = {
          Camera = "-594.251465,191.474609,344.244141,0.000181,-6.390659,-2.624116,35.0,1674.542114,false,Manual,2.8",
          Content = "还是得出城啊，出城才能抓到更多。也不知道那个骑猪的小女孩什么时候才走。",
          DialogueId = 20006034,
          FinalCamera = "-468.823608,196.549805,329.405273,0.000182,-6.590613,-4.824406,35.0,1674.542114,false,Manual,2.8",
          GUID = "32153FF4",
          NextDialogue = 20006035,
          SpeakNpcId = 200087,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153FF4"
        },
        [20006035] = {
          Content = "别急嘛，我就不信了，捱上半个月，她还能在那里守着。",
          DialogueId = 20006035,
          GUID = "3215401E",
          NextDialogue = 20006036,
          SpeakNpcId = 200075,
          TalkActionId = {
            [1] = "200075:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/3215401E"
        },
        [20006036] = {
          Content = "也是，天寒地冻的还有秽兽，说不定明天她就哭着鼻子回家啦。",
          DialogueId = 20006036,
          GUID = "32154048",
          NextDialogue = 20006037,
          SpeakNpcId = 200087,
          TalkActionId = {
            [1] = "200075:Talk02_End",
            [2] = "200087:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32154048"
        },
        [20006037] = {
          Content = "最好这样！",
          DialogueId = 20006037,
          GUID = "32154072",
          SpeakNpcId = 200075,
          TalkActionId = {
            [1] = "200075:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32154072"
        },
        [20006101] = {
