          VoiceName = "voice/$Locale$/story/2001/200061/32154B46"
        },
        [20006104] = {
          Camera = "-678.081421,-823.285156,256.820801,0.000206,7.409949,135.164078,35.000008,174.116943,false,Manual,5.0",
          Content = "噗哧……你们啊……虽然我年纪不大，但是带着榛子也见过很多人了，但像你们这样，在意魔灵想法的人可不多。",
          DialogueId = 20006104,
          FinalCamera = "-694.658569,-806.806641,259.938965,0.000206,6.409948,135.164078,35.000008,174.116943,false,Manual,5.0",
          GUID = "32154B70",
          LookAt = {
            [1] = "100001:n(200074)"
          },
          NextDialogue = 20006105,
          SpeakNpcId = 200074,
          TalkActionId = {
            [1] = "200074:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200061/32154B70"
        },
        [20006105] = {
          Content = "要是每个人都像你们一样，意识到动物和魔灵也是有自己喜好的，就不会有魔灵猎人了！",
          DialogueId = 20006105,
