            [1] = "700020:Explain01_End"
          }
        },
        [51000207] = {
          Content = "不懂事的小鬼！不知道什么是好东西。",
          DialogueId = 51000207,
          GUID = "7FAC7576",
          NextDialogue = 51000208,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Explain01_End"
          }
        },
        [51000208] = {
          Content = "夫人还是个年轻姑娘的时候就开始喝我煮的汤，已经快四十年了啦。",
          DialogueId = 51000208,
          GUID = "7FAC75A0",
          NextDialogue = 51000209,
          SpeakNpcId = 700020
        },
        [51000209] = {
          Content = "……唉，夫人！也不知道她那病还能不能好。",
          DialogueId = 51000209,
          GUID = "7FAC75CA",
          NextDialogue = 51000210,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Sigh_Start"
          }
        },
        [51000210] = {
          Content = "（老妇人眼睛里洋溢的笑容逐渐消退，取而代之的是闪烁的泪花——刚刚的热情，似乎只是她的强颜欢笑。）",
          DialogueId = 51000210,
          GUID = "7FAC75F4",
          TalkActionId = {
            [1] = "700020:Sigh_End"
          }
        },
        [51000301] = {
          Content = "到底去了哪里啊……",
          DialogueId = 51000301,
          GUID = "7FAC84E2",
          NextDialogue = 51000302,
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Sigh_Start"
          }
        },
        [51000302] = {
          Content = "（老妇人悲伤的目光停驻在远方，对突如其来的搭话充耳不闻。）",
          DialogueId = 51000302,
          GUID = "7FAC850C",
          NextOptions = {
            [1] = 510003021,
            [2] = 510003022,
            [3] = 510003023
          },
          bForbidSkipOptions = true
        },
        [51000303] = {
          Content = "（她的衣服有些旧，但布料精致，做工考究。或许，她来自一个富有的家庭。）",
          DialogueId = 51000303,
          GUID = "7FAC8536",
          NextOptions = {
            [1] = 510003051,
            [2] = 510003053
          },
          bForbidSkipOptions = true
        },
        [51000304] = {
          Content = "（她始终盯着城外，似乎在等待什么人归来。）",
          DialogueId = 51000304,
          GUID = "7FAC8560",
          NextOptions = {
            [1] = 510003051,
            [2] = 510003053
          },
          bForbidSkipOptions = true
        },
        [51000305] = {
          Content = "（她衰老的双眼溢满悲伤，似乎经历了一场漫长无望的等待。）",
          DialogueId = 51000305,
          GUID = "7FAC858A",
          NextOptions = {
            [1] = 510003051,
            [2] = 510003053
          },
          bForbidSkipOptions = true
        },
        [51000306] = {
          Content = "（老妇人回望了你一眼，但又转过头去——她似乎并不关心你在说什么。）",
          DialogueId = 51000306,
          GUID = "7FAC85B4"
        },
        [51000307] = {
          Content = "……你是……",
          DialogueId = 51000307,
          GUID = "7FAC85DE",
          NextDialogue = 51000308,
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Sigh_End"
          }
        },
        [51000308] = {
          Content = "我之前没见过你。你是从附近村镇来的吗？",
          DialogueId = 51000308,
          GUID = "7FAC8608",
          NextDialogue = 51000309,
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Explain02_Start"
          }
        },
        [51000309] = {
          Content = "你有没有见过一个叫哈默尔·狄金森的卡戎男人？他生在冰湖城，浅棕色头发，十八九岁，喜欢穿……不，现在的话，应该是和我差不多的年纪。",
          DialogueId = 51000309,
          GUID = "7FAC8632",
          NextDialogue = 51000310,
          SpeakNpcId = 700019
        },
        [51000310] = {
          Content = "我离开冰湖城已经有四十年了，也是从那时起，我就失去了和他的联系。这次回来，也没能打听到他的消息。",
          DialogueId = 51000310,
          GUID = "7FAC865C",
          NextDialogue = 51000311,
          SpeakNpcId = 700019
        },
        [51000311] = {
          Content = "他在冰湖城出生、长大，我想，就算他不在城里了，应该也不会走得太远。年轻人，你有没有在哪里见过他？",
          DialogueId = 51000311,
          GUID = "7FAC8686",
          NextOptions = {
            [1] = 510003111
          },
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51000312] = {
          Content = "好吧……",
          DialogueId = 51000312,
          GUID = "7FAC86B0",
          NextDialogue = 51000313,
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Agree"
          }
        },
        [51000313] = {
          Content = "如果你以后见到他，能不能麻烦你转告他一句话？",
          DialogueId = 51000313,
          GUID = "7FAC86DA",
          NextDialogue = 51000314,
          SpeakNpcId = 700019
        },
        [51000314] = {
          Content = "“希琳回到了冰湖城。她一直在等你，等你给她一个迟到四十年的理由。”",
          DialogueId = 51000314,
          GUID = "7FAC8704",
          NextDialogue = 51000315,
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Explain01_Start"
          }
        },
        [51000315] = {
          Content = "要是明年见到他，就问他为什么迟到了四十一年，后年的话，就是四十二年……我可是一直在数着呢。",
          DialogueId = 51000315,
          GUID = "7FAC872E",
          NextDialogue = 51000316,
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Explain01_End"
          }
        },
        [51000316] = {
          Content = "（希琳夫人看起来无比困扰，想来这位就是莎莉口中的夫人，应该有什么办法可以帮到她们。）",
          DialogueId = 51000316,
          GUID = "7FAC8758"
        },
        [51000401] = {
          Content = "安妮……安妮！",
          DialogueId = 51000401,
          GUID = "7FAC954A",
          NextDialogue = 51000402,
          SpeakNpcId = 700006,
          Subtitle = "Annie... Annie!",
          TalkActionId = {
            [1] = "700006:Shock_Start"
          }
        },
        [51000402] = {
          Content = "啊啊，你回来了，我的宝贝女儿！",
          DialogueId = 51000402,
          GUID = "7FAC9574",
          NextDialogue = 51000403,
          SpeakNpcId = 700006,
          Subtitle = "Ah, you're back, my dear daughter!"
        },
        [51000403] = {
          Content = "（女子拦住了你的去路。她干涸而涣散的双眼在你身上四处游走着，似乎在拼尽全力从你身上找寻什么。）",
          DialogueId = 51000403,
          GUID = "7FAC959E",
          NextOptions = {
            [1] = 510004031,
            [2] = 510004032,
            [3] = 510004033
          },
          Subtitle = "(A woman stops you. Her dry, vacant eyes roam over you, as if desperately searching for something inside of you.)",
          bForbidSkipOptions = true
        },
        [51000404] = {
          Content = "我就知道，你一定会回来的！你怎么忍心抛下妈妈呢！",
          DialogueId = 51000404,
          GUID = "7FAC95C8",
          NextDialogue = 51000493,
          SpeakNpcId = 700006,
          Subtitle = "I knew you'd come back! How could you leave me like that!",
          TalkActionId = {
            [1] = "700006:Shock_End"
          }
        },
        [51000405] = {
          Content = "（女人沉浸在自己的世界里，不管你说什么都无济于事。）",
          DialogueId = 51000405,
          GUID = "7FAC95F2",
          Subtitle = "(The woman is lost in her own world, and no matter what you say, it's futile.)"
        },
        [51000406] = {
          Content = "你说你不是安妮……",
          DialogueId = 51000406,
          GUID = "7FAC961C",
          NextDialogue = 51000407,
          SpeakNpcId = 700006,
          Subtitle = "You just said you're not Annie...",
          TalkActionId = {
            [1] = "700006:Disagree"
          }
        },
        [51000407] = {
          Content = "都怪我！都怪我！是我逼走了安妮……我就这一个女儿，一直以来只有我们母女俩相依为命。只要你帮我找到她，我什么都答应你！",
          DialogueId = 51000407,
          GUID = "7FAC9646",
          NextOptions = {
            [1] = 510004071,
            [2] = 51000002
          },
          SpeakNpcId = 700006,
          Subtitle = "It's all my fault! I pushed Annie away... She's all I have, it's been just us two all along. I'll do anything for you if you find my baby!",
          TalkActionId = {
            [1] = "700006:Explain02_Start"
          },
          bForbidSkipOptions = true
        },
        [51000408] = {
          Content = "谢谢你，谢谢你……",
          DialogueId = 51000408,
          GUID = "7FAC9670",
          SpeakNpcId = 700006,
          Subtitle = "Thank you. Thank you so much...",
          TalkActionId = {
            [1] = "700006:Explain02_End"
          }
        },
        [51000409] = {
          Content = "拜托你了……",
          DialogueId = 51000409,
          GUID = "7FAC969A",
          SpeakNpcId = 700006,
          Subtitle = "I'm counting on you..."
        },
        [51000420] = {
          Content = "你好，不知道您有没有见过……",
          DialogueId = 51000420,
          GUID = "7FAC969B",
          NextDialogue = 51000421,
          SpeakNpcId = 100001
        },
        [51000421] = {
          Content = "我都看到啦。你也被那个女人认错成自己的女儿了是吧。我劝你还是不要去招惹她比较好。她……",
          DialogueId = 51000421,
          GUID = "7FAC969C",
          NextDialogue = 51000422,
          SpeakNpcId = 700232
        },
        [51000422] = {
          Content = "（女人指了指自己的脑袋。）",
          DialogueId = 51000422,
          GUID = "7FAC969D",
          NextDialogue = 51000423
        },
        [51000423] = {
          Content = "她这里有问题的，在这儿站了一年了。",
          DialogueId = 51000423,
          GUID = "7FAC969E",
          NextDialogue = 51000424,
          SpeakNpcId = 700232
        },
        [51000424] = {
          Content = "不能这么说。她一定是弄丢了女儿，太伤心了才会变成这样。",
          DialogueId = 51000424,
          GUID = "7FAC969F",
          NextDialogue = 51000425,
          SpeakNpcId = 100001
        },
        [51000425] = {
          Content = "我劝你还是放弃吧，她女儿走了那么久，现在也没个影，能找到，早找到了。",
          DialogueId = 51000425,
          GUID = "7FAC96A0",
          NextDialogue = 51000426,
          SpeakNpcId = 700232
        },
        [51000426] = {
          Content = "谢谢，不过既然答应人家了，还是找找看吧。",
          DialogueId = 51000426,
          GUID = "7FAC96A1",
          SpeakNpcId = 100001
        },
        [51000427] = {
          Content = "走失的女孩？我可不太清楚，不过昨天我在城门那块儿见过一个小姑娘。",
          DialogueId = 51000427,
          GUID = "7FAC96A2",
