          DialogueId = 51002811,
          Duration = 4,
          GUID = "7FAE20AE"
        },
        [51002901] = {
          Content = "（一个嗓门奇高的人在大声念诵着什么，酒客们有一搭没一搭听着，时不时发出快活的笑声。）",
          DialogueId = 51002901,
          GUID = "7FAE2F72",
          NextDialogue = 51002902
        },
        [51002902] = {
