          DialogueId = 51002902,
          GUID = "7FAE2F9C",
          NextDialogue = 51002903,
          SpeakNpcId = 700015
        },
        [51002903] = {
          Content = "它们在逼近！它们在逼近！",
          DialogueId = 51002903,
          GUID = "7FAE2FC6",
          NextDialogue = 51002904,
          SpeakNpcId = 700015
        },
        [51002904] = {
          Content = "你来了？",
          DialogueId = 51002904,
          GUID = "7FAE2FF0",
          NextOptions = {
            [1] = 510029041
          },
          SpeakNpcId = 200003
        },
        [51002905] = {
          Content = "我手里暂且没什么活儿给你，不过……",
          DialogueId = 51002905,
          GUID = "7FAE301A",
          NextDialogue = 51002906,
          SpeakNpcId = 200003
        },
        [51002906] = {
          Content = "……你们无法想象！",
          DialogueId = 51002906,
          GUID = "7FAE3044",
          NextDialogue = 51002907,
          SpeakNpcId = 700015
        },
        [51002907] = {
          Content = "一个幽灵！！！一个穿门入户的无声行者！！！！",
          DialogueId = 51002907,
          GUID = "7FAE306E",
          NextDialogue = 51002908,
          SpeakNpcId = 700015
        },
        [51002908] = {
          Content = "如你所听，总是有碰上麻烦的人。",
          DialogueId = 51002908,
          GUID = "7FAE3098",
          NextOptions = {
            [1] = 510029081
          },
          SpeakNpcId = 200003
        },
        [51002909] = {
          Content = "巴克先生，因为沾一点酒精就倒，所以平时只点果汁和牛奶。职业嘛……三流的剧作家，一流的不好懂。喏，已经在那里絮絮叨叨半天了。",
          DialogueId = 51002909,
          GUID = "7FAE30C2",
          NextDialogue = 51002910,
          SpeakNpcId = 200003
        },
        [51002910] = {
          Content = "如你所见，他好像没办法明确表达自己的诉求，你要给他翻译翻译吗？",
          DialogueId = 51002910,
          GUID = "7FAE30EC",
          NextOptions = {
            [1] = 510029101
          },
          RestartTag = 51002910,
          SpeakNpcId = 200003,
          bForbidSkipOptions = true
        },
        [51002911] = {
          Content = "别沮丧，整个冰湖城能听懂他在说什么的也不超过一个巴掌数。",
          DialogueId = 51002911,
          GUID = "7FAE3116",
          SpeakNpcId = 200003
        },
        [51002912] = {
          Content = "以你的才智，这份工作看来非你莫属了。",
          DialogueId = 51002912,
          GUID = "7FAE3140",
          SpeakNpcId = 200003
        },
        [51003001] = {
          Content = "（你侧耳倾听剧作家的高谈阔论。）",
          DialogueId = 51003001,
          GUID = "7FAE3FDA",
          NextDialogue = 51003002
        },
        [51003002] = {
          Content = "诗人的夜晚总是漫长……剧作家也不例外！我们的笔书写着人间的脉动，我们的心自然也与潮汐和月亮为伴！",
          DialogueId = 51003002,
          GUID = "7FAE4004",
          NextDialogue = 51003003,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Talk01_Start"
          }
        },
        [51003003] = {
          Content = "抛却了令人炫目的阳光，抛却了人间的声响，抛却了浮躁的心思，此时才是我与世界促膝长谈的时刻！",
          DialogueId = 51003003,
          GUID = "7FAE402E",
          NextOptions = {
            [1] = 510030031,
            [2] = 510030032
          },
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Talk01_End"
          },
          bForbidSkipOptions = true
        },
        [51003004] = {
          Content = "啊！要么是我不自知的怠慢惹恼了掌管灵感的女神，要么就是睡眠之神在刻意作弄我！否则我怎么会任由光阴的车轮滚滚而过，却没有半分察觉！",
          DialogueId = 51003004,
          GUID = "7FAE4058",
          NextDialogue = 51003005,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Sigh_Start"
          }
        },
        [51003005] = {
          Content = "我应当用写满文辞的纸张去迎接清晨的到来，而不是只留下一个徒有健康的我与空白的稿纸！",
          DialogueId = 51003005,
          GUID = "7FAE4082",
          NextOptions = {
            [1] = 510030051,
            [2] = 510030052
          },
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Sigh_End"
          },
          bForbidSkipOptions = true
        },
        [51003006] = {
          Content = "在充满诱惑的睡梦中，我听到窸窣的足音，它是那么轻盈，像精灵的旋舞，我闻到饱满果实的气味，那上面一定浇着厚厚的蜜糖！",
          DialogueId = 51003006,
          GUID = "7FAE40AC",
          NextDialogue = 51003007,
