          }
        },
        [51003007] = {
          Content = "或许我曾在梦中迷失，但这声息与味道引领我回到现实，他们缥缈不定，他们萦绕我身，他们确实存在……",
          DialogueId = 51003007,
          GUID = "7FAE40D6",
          NextOptions = {
            [1] = 510030071,
            [2] = 510030072
          },
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Explain01_End"
          },
          bForbidSkipOptions = true
        },
        [51003008] = {
          Content = "他们绝不是我的幻觉，但我抓不住痕迹的尾巴，我勘不破这诡秘的行径，是幽灵？是鬼魅？是幻影？",
          DialogueId = 51003008,
          GUID = "7FAE4100",
          NextDialogue = 51003009,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Disagree"
          }
        },
        [51003009] = {
          Content = "我那贫瘠的破屋不增不减，他唯独偷窃了我视为生命的灵感！眼看他就要让我的梦破碎……",
          DialogueId = 51003009,
          GUID = "7FAE412A",
          NextOptions = {
            [1] = 510030091,
            [2] = 510030092
          },
          SpeakNpcId = 700015,
          bForbidSkipOptions = true
        },
        [51003010] = {
          Content = "剧作家的夜晚是绝不可以付诸于睡眠的！在座的诸位谁能听从我的召唤，去为我、去为那即将问世的著作驱散那偷走灵感的窃贼！",
          DialogueId = 51003010,
          GUID = "7FAE4154",
          NextDialogue = 51003011,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Talk03_Start"
          }
        },
        [51003011] = {
          Content = "我将给予你荣耀，给予你身为主角的可能，让我见识你的出色，让我愿意为狩月人作传吧！",
          DialogueId = 51003011,
          GUID = "7FAE417E",
          NextOptions = {
            [1] = 510030111,
            [2] = 510030112
          },
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Talk03_End"
          },
          bForbidSkipOptions = true
        },
        [51003012] = {
          Content = "虽然没什么钱赚，但听起来很有意思，你想接吗？",
          DialogueId = 51003012,
          GUID = "7FAE41A8",
          NextOptions = {
            [1] = 510030121,
            [2] = 510030122
          },
          SpeakNpcId = 200003,
          bForbidSkipOptions = true
        },
        [51003013] = {
          Content = "哦！回应我呼唤的勇士出现了，这说不定是一段崭新冒险的序幕！",
          DialogueId = 51003013,
          GUID = "7FAE41D2",
          NextDialogue = 51003014,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Talk01_Start"
          },
          TurnTo = {
            [1] = "700015:n(0)"
          }
        },
        [51003014] = {
          Content = "我对你们接下来碰到的事情抱以十足的兴趣，当你们归来，请为我讲述你们的故事吧！",
          DialogueId = 51003014,
          GUID = "7FAE41FC",
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Talk01_End"
          }
        },
        [51003101] = {
          Content = "据卡米拉所说，巴克先生不胜酒力、从不喝酒，那壶里的酒难道是其他人加进去的？",
          DialogueId = 51003101,
          GUID = "7FAE5042",
          NextDialogue = 51003102,
          SpeakNpcId = 100001
        },
        [51003102] = {
          Content = "仔细一看，这牛奶壶上还有个黏糊糊的手印……看起来那只手很小巧。",
          DialogueId = 51003102,
          GUID = "7FAE506C",
          SpeakNpcId = 100001
        },
        [51003103] = {
          Content = "小小的脚印从屋外延伸至窗台，屋内还有雪化的积水。显然闯入者没有处理痕迹的意识，单纯就只是一个小孩子而已。",
          DialogueId = 51003103,
          GUID = "7FAE5096",
          SpeakNpcId = 100001
        },
        [51003104] = {
          Content = "看来似乎有个小孩把酒掺在牛奶里，灌醉了巴克先生。再去找找其他线索吧。",
          DialogueId = 51003104,
          Duration = 4,
          GUID = "7FAE50C0",
          SpeakNpcId = 100001
        },
        [51003105] = {
          Content = "你好，请问平时会有小孩子来找巴克先生玩吗？",
          DialogueId = 51003105,
          GUID = "7FAE50EA",
          NextDialogue = 51003106,
          SpeakNpcId = 100001
        },
        [51003106] = {
          Content = "小孩找巴克玩？不可能不可能，哪有小孩会对那种只在<H>家里、酒馆和剧院</>三点一线，还满嘴怪话的家伙感兴趣啊。",
          DialogueId = 51003106,
          GUID = "7FAE5114",
          NextDialogue = 51003107,
          SpeakNpcId = 700213
        },
        [51003107] = {
          Content = "别说小孩了，连我们平时都很少跟他打交道，烦得要死还一句话都听不懂。他是不是犯什么事了？我跟你讲啊，我早就感觉他不是好东西了。",
          DialogueId = 51003107,
          GUID = "7FAE513E",
          NextDialogue = 51003108,
          SpeakNpcId = 700213
        },
        [51003108] = {
          Content = "（老妇人滔滔不绝地数落着巴克，诸如这么大了没有正经工作，一天到晚不出门，没老婆没朋友。一直到她讲得口干舌燥，你才找到机会离开。）",
          DialogueId = 51003108,
          GUID = "7FAE5168",
          NextDialogue = 51003109
        },
        [51003109] = {
          Content = "（巴克先生深居简出没有社交，大部分人都不了解他。所以会想到用酒来灌醉巴克先生的小孩子，一定是从什么地方知道了这个秘密……）",
          DialogueId = 51003109,
          GUID = "7FAE5192",
          NextDialogue = 51003110,
          SpeakNpcId = 100001
        },
        [51003110] = {
          Content = "（水仙平原不招揽小孩子，家附近也没有小孩找巴克先生……那么就只剩下剧院了，过去看看吧。）",
          DialogueId = 51003110,
          GUID = "7FAE51BC",
          SpeakNpcId = 100001
        },
        [51003111] = {
          Content = "（售票厅旁的卡戎小孩哈着冷气，打着冷颤。不停向来往行人推销着门票、海报、啤酒和爆米花。）",
          DialogueId = 51003111,
          GUID = "7FAE51E6",
          NextDialogue = 51003112
        },
        [51003112] = {
          Content = "（不停向路人推销商品的小孩，会是他灌醉的巴克先生吗？）",
          DialogueId = 51003112,
          GUID = "7FAE5210",
          SpeakNpcId = 100001
        },
        [51003113] = {
          Content = "巴克先生经常出入剧院，一定多次碰到并拒绝过那个小孩推销啤酒……",
          DialogueId = 51003113,
          Duration = 3,
          GUID = "7FAE523A",
          NextDialogue = 51003114,
          SpeakNpcId = 100001
        },
        [51003114] = {
          Content = "他袖口粘着的那几枚爆米花，跟我窗户下捡到的一模一样。怎么看他的嫌疑都很大，过去聊聊看吧。",
          DialogueId = 51003114,
          Duration = 4,
          GUID = "7FAE5264",
          SpeakNpcId = 100001
        },
        [51003115] = {
          Content = "喝啊，我还能喝……不就是二十几瓶啤酒嘛，这才哪到哪啊！来，继续上酒继续喝！",
          DialogueId = 51003115,
          GUID = "7FAE528E",
          NextDialogue = 51003116,
          SpeakNpcId = 700214
        },
        [51003116] = {
          Content = "（浑身酒气的大叔。会是他灌醉的巴克先生吗？）",
          DialogueId = 51003116,
          GUID = "7FAE52B8",
          SpeakNpcId = 100001
        },
        [51003117] = {
          Content = "那个爆米花……是什么味道的呀，爸爸，我想尝尝看！",
          DialogueId = 51003117,
          GUID = "7FAE52E2",
          LookAt = {
            [1] = "700215:n(700219)",
            [2] = "700219:n(700215)"
          },
          NextDialogue = 51003118,
          SpeakNpcId = 700215
        },
        [51003118] = {
          Content = "孩子，你是个淑女，不应该吃那种垃圾食品，等看完歌剧了，爸爸带你去银色和平餐厅吃大餐。",
          DialogueId = 51003118,
          GUID = "7FAE530C",
          NextDialogue = 51003119,
          SpeakNpcId = 700219,
          TalkActionId = {
            [1] = "700219:Talk03_Start"
          }
        },
        [51003119] = {
          Content = "好吧……",
          DialogueId = 51003119,
          GUID = "7FAE5336",
          NextDialogue = 51003120,
          SpeakNpcId = 700215,
          TalkActionId = {
            [1] = "700219:Talk03_End"
          }
        },
        [51003120] = {
          Content = "（出现在剧院附近的小孩，很想尝一口爆米花的样子。会是她灌醉的巴克先生吗？）",
          DialogueId = 51003120,
          GUID = "7FAE5360",
          SpeakNpcId = 100001
        },
        [51003301] = {
          Content = "阿嚏！怎么好像更冷了……",
          DialogueId = 51003301,
          GUID = "7FAE7112",
          NextDialogue = 51003302,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Sigh_Start"
          }
        },
        [51003302] = {
          Content = "就算是卡戎，不怕冷也是有极限的……到了晚上起码会降温二十多度，说不定又有孩子要冻死了，唉……",
          DialogueId = 51003302,
          GUID = "7FAE713C",
          NextDialogue = 51003303,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Sigh_End"
          }
        },
        [51003303] = {
          Content = "你好。",
          DialogueId = 51003303,
          GUID = "7FAE7166",
          NextDialogue = 51003304,
          SpeakNpcId = 100001
        },
        [51003304] = {
          Content = "您好，尊敬的阁下！看戏辛苦了！坐了三个小时，您一定饿了吧！想来点零食和饮品吗？",
          DialogueId = 51003304,
          GUID = "7FAE7190",
          NextDialogue = 51003305,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Explain02_Start"
          }
        },
        [51003305] = {
          Content = "或者您感动于精彩的表演，想看一看有演员签名的海报呢？",
          DialogueId = 51003305,
          GUID = "7FAE71BA",
          NextOptions = {
            [1] = 510033051,
            [2] = 510033052
          },
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51003306] = {
          Content = "让我瞧瞧你都卖些什么。",
          DialogueId = 51003306,
          GUID = "7FAE71E4",
          NextDialogue = 51003307,
          SpeakNpcId = 100001
        },
        [51003307] = {
          Content = "维蒂的珍藏版签名海报，《冰湖往事》的纪念手册，冰山融水，剧院联名版爆米花，以及清甜的啤酒！",
          DialogueId = 51003307,
          GUID = "7FAE720E",
          NextDialogue = 51003308,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Explain01_Start"
          }
        },
        [51003308] = {
          Content = "您放心，这度数聊胜于无，喝不醉人的！",
          DialogueId = 51003308,
          GUID = "7FAE7238",
          NextDialogue = 51003309,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Explain01_End"
          }
        },
        [51003309] = {
          Content = "那可不一定……你认识剧作家巴克先生吗？",
          DialogueId = 51003309,
          GUID = "7FAE7262",
          NextDialogue = 51003310,
          SpeakNpcId = 100001
        },
        [51003310] = {
          Content = "当然认识！他是剧院的常客，也经常光顾我的生意，身为贵族但尊重我这样的卡戎小孩，是难得一见的大好人！",
          DialogueId = 51003310,
          GUID = "7FAE728C",
          NextDialogue = 51003311,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Agree"
          }
        },
        [51003311] = {
          Content = "我知道有人嘲笑他，但比起那些人，巴克先生更值得尊敬。",
          DialogueId = 51003311,
          GUID = "7FAE72B6",
          NextDialogue = 51003312,
          SpeakNpcId = 700080
        },
        [51003312] = {
          Content = "这不是你从窗台摸进他家，偷偷在他牛奶里倒酒的理由。",
          DialogueId = 51003312,
          GUID = "7FAE72E0",
          NextDialogue = 51003313,
          SpeakNpcId = 100001
        },
        [51003313] = {
          Content = "你、你是怎么知道的……",
          DialogueId = 51003313,
          GUID = "7FAE730A",
          NextDialogue = 51003321,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Shock_Start"
          }
        },
        [51003314] = {
          Content = "巴克先生总在夜间进行创作，你的行为让他的剧本一个月都没有进展，于是他雇佣我去寻找神秘的“灵感飞贼”。",
          DialogueId = 51003314,
          GUID = "7FAE7334",
          NextOptions = {
            [1] = 510033141
          },
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700080:Shock_End"
          },
          bForbidSkipOptions = true
        },
        [51003315] = {
          Content = "（想说的话突然卡在嘴边，在脑海里重新整理一下措辞吧。）",
          DialogueId = 51003315,
          GUID = "7FAE735E"
        },
        [51003316] = {
          Content = "你的生意并不支持你买到足够的过冬物资，巴克先生虽然没什么钱，但好歹是个贵族，他的房子足够暖和，所以你才想潜入巴克先生家取暖。",
          DialogueId = 51003316,
          GUID = "7FAE7388",
          NextDialogue = 51003317,
          SpeakNpcId = 100001
        },
        [51003317] = {
          Content = "至于为什么是巴克先生，那是因为不管度数有多低，只要沾一点点酒他都会睡过去，在这之后你就能安心地睡上一整晚而不必担心被冻死，对吗？",
          DialogueId = 51003317,
          GUID = "7FAE73B2",
          NextDialogue = 51003318,
          SpeakNpcId = 100001
        },
        [51003318] = {
          Content = "唉……您可真是名侦探再世，事情就像您说的一样。",
          DialogueId = 51003318,
          GUID = "7FAE73DC",
          NextDialogue = 51003319,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Explain02_Start"
          }
        },
        [51003319] = {
          Content = "您把我抓起来吧，我感到十分抱歉，但如果不这么做，我连被您抓起来的机会都没有……",
          DialogueId = 51003319,
          GUID = "7FAE7406",
          NextDialogue = 51003320,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Explain02_End"
          }
        },
        [51003320] = {
          Content = "我没有权利决定怎么处理你，我会带你去见我的雇主。",
          DialogueId = 51003320,
          GUID = "7FAE7430",
          SpeakNpcId = 100001
        },
        [51003321] = {
          Content = "（果然如此。）",
          DialogueId = 51003321,
          GUID = "7FAE730B",
          NextDialogue = 51003314,
          SpeakNpcId = 100001
        },
        [51003401] = {
          Camera = "98.558472,-67.410156,133.285156,0.0,-1.600033,173.800858,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "我找到人了。",
          DialogueId = 51003401,
          GUID = "7FAE817A",
          LookAt = {
            [1] = "700102:n(100001)",
            [2] = "100001:n(700102)"
          },
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Give"
          }
        },
        [51003402] = {
          Content = "你将事情的来龙去脉告知给了巴克先生。",
          DialogueId = 51003402,
          Duration = 3,
          GUID = "7FAE81A4"
        },
        [51003403] = {
          Camera = "-262.830322,120.149414,121.775391,0.000007,-0.200008,-45.795547,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "哦！我的勇士，对您道一万次的感谢！想必从今夜起，灵感女神的宠爱将重回我身！",
          DialogueId = 51003403,
          GUID = "7FAE81CE",
          LookAt = {
            [1] = "700102:n(100001)"
          },
          NextDialogue = 51003404,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700102:Agree"
          },
          TurnTo = {
            [1] = "700103:n(700102)"
          }
        },
        [51003404] = {
          Camera = "-73.412354,63.213867,126.775391,0.000008,0.200002,-62.796665,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "至于你……我梦中的小飞贼，你可真是给了我一个莫大的意外！",
          DialogueId = 51003404,
          GUID = "7FAE81F8",
          LookAt = {
            [1] = "700102:n(700103)"
          },
          NextDialogue = 51003405,
          SpeakNpcId = 700015,
          TurnTo = {
            [1] = "700102:n(700103)"
          }
        },
        [51003405] = {
          Camera = "-49.103394,-198.604492,136.482422,0.000076,-6.999994,74.199654,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "非常抱歉，巴克先生……但请您相信我，我从没有要伤害你的意思……",
          DialogueId = 51003405,
          GUID = "7FAE8222",
          LookAt = {
            [1] = "700103:n(700102)"
          },
          NextDialogue = 51003406,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700103:Explain02_Start"
          }
        },
        [51003406] = {
          Camera = "-92.579468,176.0,104.482422,0.000083,1.000179,-63.000008,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "哦，小飞贼，我知道人们在背后是怎么笑话我的，我是个卖不出作品的废物剧作家。",
          DialogueId = 51003406,
          GUID = "7FAE824C",
          LookAt = {
            [1] = "700102:n(700103)"
          },
          NextDialogue = 51003407,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700103:Explain02_End"
          }
        },
        [51003407] = {
          Camera = "-92.579468,176.0,104.482422,0.000083,1.000179,-63.000008,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "就算用再优美的辞藻装饰我的言语，也换不来他们对我的欣赏，他们拒绝倾听，拒绝理解……但依我看，这世上又有几个能有话直说的人呢？",
          DialogueId = 51003407,
          GUID = "7FAE8276",
          LookAt = {
            [1] = "700102:n(700103)"
          },
          NextDialogue = 51003408,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700102:Talk03_Start"
          }
        },
        [51003408] = {
          Camera = "-49.103394,-198.604492,136.482422,0.000076,-6.999994,74.199654,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "先生，我不明白您的意思。",
          DialogueId = 51003408,
          GUID = "7FAE82A0",
          LookAt = {
            [1] = "700103:n(700102)"
          },
          NextDialogue = 51003409,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700102:Talk03_End",
            [2] = "700103:Disagree"
          }
        },
        [51003409] = {
          Camera = "-92.579468,176.0,104.482422,0.000083,1.000179,-63.000008,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "我是说，你从不把我当成一个只知道痴人说梦的蠢货，那么对于你，我也有自己的尊重，如果你无法渡过这个冬天，何不早说呢？",
          DialogueId = 51003409,
          GUID = "7FAE82CA",
          LookAt = {
            [1] = "700102:n(700103)"
          },
          NextDialogue = 51003410,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700102:Agree"
          }
        },
        [51003410] = {
          Camera = "-92.579468,176.0,104.482422,0.000083,1.000179,-63.000008,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "我会为你收拾出房间，如果你乐意，还能拿起我的稿纸当睡前故事，只是我不确定那些故事是否足够助眠。",
          DialogueId = 51003410,
          GUID = "7FAE82F4",
          LookAt = {
            [1] = "700102:n(700103)"
          },
          NextDialogue = 51003411,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700102:Explain01_Start"
          }
        },
        [51003411] = {
          Camera = "-49.103394,-198.604492,136.482422,0.000076,-6.999994,74.199654,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "您真的愿意收留我吗……我不值得您这样做，但我可以帮您做一些琐事，就当是我耽误您一个月创作的补偿吧……",
          DialogueId = 51003411,
          GUID = "7FAE831E",
          LookAt = {
            [1] = "700103:n(700102)"
          },
          NextDialogue = 51003412,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700102:Explain01_End",
            [2] = "700103:Explain02_Start"
          }
        },
        [51003412] = {
          Camera = "-143.197754,12.932617,126.775391,0.000008,0.0,-32.595322,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "感谢您所做的一切，尊敬的狩月人阁下！明察秋毫的冰湖城侦探非您莫属，我收获了一个温馨的故事，也收获了两个诚挚的朋友。",
          DialogueId = 51003412,
          GUID = "7FAE8348",
          LookAt = {
            [1] = "700102:n(100001)"
          },
          NextDialogue = 51003413,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700103:Explain02_End"
          },
          TurnTo = {
            [1] = "700102:n(100001)"
          }
        },
        [51003413] = {
          Camera = "-143.197754,12.932617,126.775391,0.000008,0.0,-32.595322,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "啊！灵感纷至沓来！我得迅速回去把他们记下来，如果我的诗篇能得到传颂，千百年后人们也依然赞美着您的名字！",
          DialogueId = 51003413,
          GUID = "7FAE8372",
          LookAt = {
            [1] = "700102:n(100001)"
          },
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700102:Talk01_Start"
          }
        },
        [51003414] = {
          Content = "两人一起离去了，每个人都得到了他想要的，不知道巴克先生的下一部大作是否能和他说的一样精彩。",
          DialogueId = 51003414,
          Duration = 4,
          GUID = "7FAE839C"
        },
        [51003501] = {
          Camera = "-813.361816,168.229736,207.784668,0.000003,-6.799986,-16.405685,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "感谢牺牲、感谢慈悲、感谢银色和平，让我们远离瘟疫，让我们远离蒙昧，让我们远离恶魔的威胁……",
          DialogueId = 51003501,
          GUID = "7FAE91E2",
          NextDialogue = 51003520,
          SpeakNpcId = 700086,
          TalkActionId = {
            [1] = "700086:Explain02_Start"
          }
        },
        [51003502] = {
          Camera = "-336.324951,48.679199,108.230957,0.0,0.0,-9.40437,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "艾玛？艾玛？你在发什么楞？",
          DialogueId = 51003502,
          GUID = "7FAE920C",
          LookAt = {
            [1] = "700016:n(700086)"
          },
          NextDialogue = 51003503,
          SpeakNpcId = 700086,
          TalkActionId = {
            [1] = "700086:Explain02_End",
            [2] = "700086:Confident_Start"
          }
        },
        [51003503] = {
          Camera = "-344.113281,-49.567139,176.708252,0.000003,-0.399996,158.596222,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "抱歉老师！我这就来！",
          DialogueId = 51003503,
          GUID = "7FAE9236",
          SpeakNpcId = 700016,
          TalkActionId = {
            [1] = "700086:Confident_End",
            [2] = "700016:Shock_Start"
          }
        },
        [51003504] = {
          Camera = "-336.324951,48.679199,108.230957,0.0,0.0,-9.40437,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "你这孩子最近怎么魂不守舍的，下次可不能这样了。",
          DialogueId = 51003504,
          GUID = "7FAE9260",
          NextDialogue = 510035041,
          SpeakNpcId = 700086,
          TalkActionId = {
            [1] = "700086:Sigh_Start"
          }
        },
        [51003505] = {
          Content = "唉……真无聊……不知道婆婆在做什么呢？",
          DialogueId = 51003505,
          GUID = "7FAE928A",
          NextOptions = {
            [1] = 510035051,
            [2] = 510035052,
            [3] = 510035053
          },
          SpeakNpcId = 700016,
          bForbidSkipOptions = true
        },
        [51003506] = {
          Content = "当然有原因啦，告诉你也不是不行，但你得保证守口如瓶。",
          DialogueId = 51003506,
          GUID = "7FAE92B4",
          LookAt = {
            [1] = "700016:n(0)"
          },
          NextOptions = {
            [1] = 510035061
          },
          RestartTag = 51003506,
          SpeakNpcId = 700016,
          bForbidSkipOptions = true
        },
        [51003507] = {
          Content = "像，很像啊！",
          DialogueId = 51003507,
          GUID = "7FAE92DE",
          SpeakNpcId = 700016
        },
        [51003508] = {
          Content = "那我就告诉你吧！",
          DialogueId = 51003508,
          GUID = "7FAE9308",
          LookAt = {
            [1] = "700016:n(0)"
          },
          NextDialogue = 51003509,
          SpeakNpcId = 700016,
          TalkActionId = {
            [1] = "700016:Confident_Start"
          }
        },
        [51003509] = {
          Content = "上个月我偷偷溜去贫民窟玩，结果在小巷子里碰到了一个神秘的老婆婆！",
          DialogueId = 51003509,
          GUID = "7FAE9332",
          NextDialogue = 51003510,
          SpeakNpcId = 700016
        },
        [51003510] = {
          Content = "她手可巧啦，会给我编各种花式的小辫子，会用鲜花给我染指甲，还知道许许多多我从来没听过的小故事！",
          DialogueId = 51003510,
          GUID = "7FAE935C",
          NextDialogue = 51003511,
          SpeakNpcId = 700016,
          TalkActionId = {
            [1] = "700016:Confident_End"
          }
        },
        [51003511] = {
          Content = "她从不对我说教，也不把我当小孩糊弄，虽然那是我们头一回见，但她搂着我的时候就像我奶奶一样温暖……",
          DialogueId = 51003511,
          GUID = "7FAE9386",
          NextDialogue = 51003512,
          SpeakNpcId = 700016
        },
        [51003512] = {
          Content = "那不是很好吗？为什么不坦然告诉别人你有新朋友了呢？",
          DialogueId = 51003512,
          GUID = "7FAE93B0",
          NextDialogue = 51003513,
          SpeakNpcId = 100001
        },
        [51003513] = {
          Content = "因为婆婆长了角……如果我告诉父母、同学、老师，一定会让她受到伤害吧……",
          DialogueId = 51003513,
          GUID = "7FAE93DA",
          NextDialogue = 51003514,
          SpeakNpcId = 700016,
          TalkActionId = {
            [1] = "700016:Explain02_Start"
          }
        },
        [51003514] = {
          Content = "我们本来约好了今天见面，可是学校临时增加了纪念活动，我只能爽约了，如果你有空，可不可以帮我把这个布娃娃带给她？",
          DialogueId = 51003514,
          GUID = "7FAE9404",
          LookAt = {
            [1] = "700016:n(0)"
          },
          NextOptions = {
            [1] = 510035141,
            [2] = 51000002
          },
          SpeakNpcId = 700016,
          TalkActionId = {
            [1] = "700016:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51003515] = {
          Content = "集合时间到了，拜托你可千万要送到哦！谢谢你！",
          DialogueId = 51003515,
          GUID = "7FAE942E",
          SpeakNpcId = 700016
        },
        [51003520] = {
          Content = "下面由艾玛献上纪念的花……",
          DialogueId = 51003520,
          GUID = "7FAE9500",
          NextDialogue = 51003502,
          SpeakNpcId = 700086
        },
        [51003601] = {
          Camera = "-59.474121,-281.53418,130.205078,0.000004,0.0,71.19751,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "谢谢你，婆婆，我觉得好多了，如果这是罗伯期望的，我会为了他好好生活。",
          DialogueId = 51003601,
          GUID = "7FAEA24A",
          NextDialogue = 51003602,
          SpeakNpcId = 700087,
          TalkActionId = {
            [1] = "700087:Explain02_Start"
          }
        },
        [51003602] = {
          Camera = "-83.495605,207.759766,134.179199,0.000004,-0.199981,-68.802429,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "希望你早日走出悲痛，我们与你同在，孩子，如果你需要，贝琳达的小屋永远为你开放。",
          DialogueId = 51003602,
          GUID = "7FAEA274",
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700087:Explain02_End",
            [2] = "700081:Explain01_Start"
          }
        },
        [51003604] = {
          Content = "你好呀！我从没见过你，我猜你是刚来冰湖城的朋友？找贝琳达有什么事呢？",
          DialogueId = 51003604,
          GUID = "7FAEA2C8",
          NextOptions = {
            [1] = 510036041
          },
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Explain01_Start"
          }
        },
        [51003605] = {
          Content = "（虽然手艺粗糙，但你能看出娃娃和贝琳达有几分相似。卡戎婆婆满是喜悦，将娃娃抚摸了一遍又一遍。）",
          DialogueId = 51003605,
          GUID = "7FAEA2F2",
          NextDialogue = 51003606,
          TalkActionId = {
            [1] = "700081:Explain01_End"
          }
        },
        [51003606] = {
          Content = "我从娃娃上感觉到了广场的气息……啊，瞧我这记性！纪念周到啦，这时候的活动总是很多……",
          DialogueId = 51003606,
          GUID = "7FAEA31C",
          NextDialogue = 51003607,
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Agree"
          }
        },
        [51003607] = {
          Content = "我很感谢你，孩子。",
          DialogueId = 51003607,
          GUID = "7FAEA346",
          NextDialogue = 51003608,
          SpeakNpcId = 700081
        },
        [51003608] = {
          Content = "（她仔细地端详着你，有好几分钟都没有说话。）",
          DialogueId = 51003608,
          GUID = "7FAEA370",
          NextDialogue = 51003609
        },
        [51003609] = {
          Content = "你好像惹上了大麻烦，我闻到了海风的味道，感受到了潮水的包裹，还有……你手掌上残留的，他人的温度，但这份温暖正逐渐远去……",
          DialogueId = 51003609,
          GUID = "7FAEA39A",
          NextDialogue = 51003610,
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Explain02_Start"
          }
        },
        [51003610] = {
          Content = "来到这里的每时每刻，你都被困惑与悲伤缠绕，但你努力把这些压抑在心底，不去表露……",
          DialogueId = 51003610,
          GUID = "7FAEA3C4",
          NextDialogue = 51003611,
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Explain02_End"
          }
        },
        [51003611] = {
          Content = "无意冒犯，你是否失去了重要之人？",
          DialogueId = 51003611,
          GUID = "7FAEA3EE",
          NextOptions = {
            [1] = 510036111,
            [2] = 510036112,
            [3] = 510036113
          },
          SpeakNpcId = 700081,
          bForbidSkipOptions = true
        },
        [51003612] = {
          Content = "能活到我这么大年纪的卡戎很稀奇吧？",
          DialogueId = 51003612,
          GUID = "7FAEA418",
          NextDialogue = 51003615,
          SpeakNpcId = 700081
        },
        [51003613] = {
          Content = "你在难过，孩子。",
          DialogueId = 51003613,
          GUID = "7FAEA442",
          NextDialogue = 51003615,
          SpeakNpcId = 700081
        },
        [51003614] = {
          Content = "不用强撑，我知道的，孩子。",
          DialogueId = 51003614,
          GUID = "7FAEA46C",
          NextDialogue = 51003615,
          SpeakNpcId = 700081
        },
        [51003615] = {
          Content = "很遗憾，孩子，我没有帮助你的办法，但有一句话，我想正适合此时的你……",
          DialogueId = 51003615,
          GUID = "7FAEA496",
          NextDialogue = 51003616,
          SpeakNpcId = 700081
        },
        [51003616] = {
          Content = "“行人走上一线旅途，命运女神纺锤收束。当千头万绪重聚，失物在眼前沉浮。”",
          DialogueId = 51003616,
          GUID = "7FAEA4C0",
          NextOptions = {
            [1] = 510036161
          },
          RestartTag = 51003616,
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Agree"
          },
          bForbidSkipOptions = true
        },
        [51003617] = {
          Content = "孩子，你将在旅途中拾得你缺少的一切，去吧，去吧。",
          DialogueId = 51003617,
          GUID = "7FAEA4EA",
          SpeakNpcId = 700081
        },
        [51003618] = {
          Content = "出自《命运女神的纺锤》终幕……无可剥夺者在双面之境见到了自己失去的一切……你是在告诉我终有一天我们会再次相见？",
          DialogueId = 51003618,
          GUID = "7FAEA514",
          NextDialogue = 51003619,
          SpeakNpcId = 100001
        },
        [51003619] = {
          Content = "请把这句箴言当作送来娃娃的谢礼吧。你很聪明，孩子，就像我所看到的一样……不需要我告诉你什么，你会依靠自己的力量探明疑问。",
          DialogueId = 51003619,
          GUID = "7FAEA53E",
          NextDialogue = 51003620,
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Agree"
          }
        },
        [51003620] = {
          Content = "另外，我会送给每个初次来拜访我的人一件小礼物，只要一件带有你自身气息的铁丝就好，不急于现在，我会一直在这里等你。",
          DialogueId = 51003620,
          GUID = "7FAEA568",
          NextDialogue = 51003621,
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Explain02_Start"
          }
        },
        [51003621] = {
          Content = "气息……虽然不太明白，但只要是我接触过的，或者在我身上待过的就可以吧。",
          DialogueId = 51003621,
          GUID = "7FAEA592",
          NextDialogue = 51003622,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700081:Explain02_End"
          }
        },
        [51003622] = {
          Content = "格雷姆废矿那里应该有不少铁丝，我去那边看看。",
          DialogueId = 51003622,
          Duration = 3,
          GUID = "7FAEA5BC",
          SpeakNpcId = 100001
        },
        [51003630] = {
          Content = "陌生的卡戎虽然还挂着泪痕，但你能从他的眼中看出，他已经燃起了活下去的勇气。",
          DialogueId = 51003630,
          Duration = 4,
          GUID = "7FAEA70C",
          NextDialogue = 51003631
        },
        [51003631] = {
          Content = "他与贝琳达拥抱后，依依不舍地离去了。",
          DialogueId = 51003631,
          Duration = 2,
          GUID = "7FAEA736"
        },
        [51003701] = {
          Content = "（贝琳达从你手中接过铁丝，将其弯成了一枚侧脸肖像，你能看出这件小工艺品与贝蕾妮卡有些相似。）",
          DialogueId = 51003701,
          GUID = "7FAEB2B2",
          NextDialogue = 51003702
        },
        [51003702] = {
          Content = "我并不强大，只能看到些朦胧的影子，不知道这与你思念之人是否相像，只是希望这能让你好受一些。",
          DialogueId = 51003702,
          GUID = "7FAEB2DC",
          NextDialogue = 51003703,
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Disagree"
          }
        },
        [51003703] = {
          Content = "衷心祝愿你们再次重逢。",
          DialogueId = 51003703,
          GUID = "7FAEB306",
          NextDialogue = 51003704,
          SpeakNpcId = 700081
        },
        [51003704] = {
          Content = "（你离开了贝琳达的小帐篷，现在你好像理解为什么艾玛对这里如此留恋了，贝琳达的力量并不强大，但她始终在治愈心灵，抚平伤痛。）",
          DialogueId = 51003704,
          GUID = "7FAEB330"
        },
        [51003705] = {
          Camera = "-279.652405,-157.0,151.0,0.000004,-6.0,21.800476,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "嗯……这样应该就差不多了！",
          DialogueId = 51003705,
          FinalCamera = "-279.652405,-135.0,151.0,0.000004,-6.0,21.80052,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FAEA5BD",
          NextDialogue = 51003706,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 5
        },
        [51003706] = {
          Camera = "-279.652405,-135.0,151.0,0.000004,-6.0,21.80052,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "打打打打打劫！你怀里的宝贝是我的啦！",
          DialogueId = 51003706,
          GUID = "7FAEA5BE",
          NextDialogue = 51003707,
          Scripts = "SEQ{PlayAnimation{ActorId{100001},AnimationId{\"Think_End\"},Duration{1}},TurnTo{_delay{1},TurnToDescription{\"100001:p(180)\"}}}",
          SpeakNpcId = 700206
        },
        [51003707] = {
          Camera = "128.007935,301.234375,103.0,0.000009,0.0,-108.798302,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "（皎皎之民的身影猛地从一旁窜出，一把抢过你怀中的铁丝，一边跑一边回头嘲笑着你。）",
          DialogueId = 51003707,
          GUID = "7FAEA5BF",
          NextDialogue = 51003708,
          Scripts = "MoveTo{ActorId{700206},TargetPoint{\"QuestPoint_DJMove\"},MoveSpeed{200},Visibility{\"Show\"}}"
        },
        [51003708] = {
