          NextDialogue = 51007105,
          SpeakNpcId = 700147,
          TalkActionId = {
            [1] = "700147:Confident_Start"
          }
        },
        [51007105] = {
          Content = "过分！请说词，让她止住刻薄语言！",
          DialogueId = 51007105,
          GUID = "7FB0E12A",
          LookAt = {
            [1] = "700147:n(700148)"
