          TalkActionId = {
            [1] = "700147:Angry01_Start"
          }
        },
        [51007109] = {
          Content = "为什么说是垃圾？在我看来，这是很用心完成的手工艺品，可以感觉到制作者真挚的感情。",
          DialogueId = 51007109,
          GUID = "7FB0E1D2",
          NextDialogue = 51007110,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700147:Angry01_End"
          }
        },
        [51007110] = {
          Content = "华胥也有，折纸星星习俗。据说，折得多，会美梦成真。",
          DialogueId = 51007110,
          GUID = "7FB0E1FC",
          LookAt = {
            [1] = "700148:n(0)"
          },
          NextDialogue = 51007111,
          SpeakNpcId = 700148,
          TalkActionId = {
            [1] = "700148:Think_Start"
          }
        },
        [51007111] = {
          Content = "原来是这样……怪不得，我之前想研究一下它是怎么叠起来的，就拆了一个，结果发现里面写了字。",
          DialogueId = 51007111,
          GUID = "7FB0E226",
          NextDialogue = 51007112,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700148:Think_End"
          }
        },
        [51007112] = {
          Content = "上面写的好像正是……某个人许下的愿望？",
          DialogueId = 51007112,
          GUID = "7FB0E250",
          NextDialogue = 51007113,
          SpeakNpcId = 100001
        },
        [51007113] = {
          Content = "你……你都打开看了？！",
          DialogueId = 51007113,
          GUID = "7FB0E27A",
          LookAt = {
            [1] = "700148:n(700147)"
          },
          NextDialogue = 51007114,
          SpeakNpcId = 700147,
          TalkActionId = {
            [1] = "700147:Sigh_Start"
          }
        },
        [51007114] = {
          Content = "我只看了一张。我发现它是用车票折的，背面写的文字也和列车有关，所以我才想来车站看看，想着也许能物归原主。",
          DialogueId = 51007114,
          GUID = "7FB0E2A4",
          NextDialogue = 51007115,
          SpeakNpcId = 100001
        },
        [51007115] = {
          Content = "但既然你说是垃圾，那就随我处置喽。",
          DialogueId = 51007115,
          GUID = "7FB0E2CE",
          NextDialogue = 51007116,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700147:Sigh_End"
          }
        },
        [51007116] = {
          Content = "（你将纸星星拿在手里，再次看向售票员。她的目光分明跟着盒子移了过来，但她似乎还是不愿意开口。）",
          DialogueId = 51007116,
          GUID = "7FB0E2F8",
