          DialogueId = 51007118,
          GUID = "7FB0E34C",
          NextDialogue = 51007121,
          SpeakNpcId = 100001
        },
        [51007119] = {
          Content = "“5月21日。凯瑟琳太太把银币扔在我脚边，让我蹲着一枚枚捡起来。她说我没资格从她手中接过钱袋。唉，如果我也能像她一样有花不完的银币就好了。”",
          DialogueId = 51007119,
          GUID = "7FB0E376",
          NextDialogue = 51007120,
          SpeakNpcId = 100001
        },
        [51007120] = {
          Content = "“9月13日。昨晚再次梦见自己终于攒够了钱，买下车票。这次梦里的终点站是红溪城……”",
          DialogueId = 51007120,
          GUID = "7FB0E3A0",
          NextDialogue = 51007121,
          SpeakNpcId = 100001
        },
        [51007121] = {
          Content = "……住口！别说了！",
          DialogueId = 51007121,
          GUID = "7FB0E3CA",
          NextDialogue = 51007122,
          SpeakNpcId = 700147,
          TalkActionId = {
            [1] = "700147:Sigh_Start"
          }
        },
        [51007122] = {
          Content = "其实这是你的东西，对吗——",
          DialogueId = 51007122,
          GUID = "7FB0E3F4",
          NextDialogue = 51007123,
          SpeakNpcId = 100001
        },
        [51007123] = {
          Content = "（你回忆了一下车票上写着的名字。）",
          DialogueId = 51007123,
          GUID = "7FB0E41E",
          NextDialogue = 51007124
        },
        [51007124] = {
