          DialogueId = 51007124,
          GUID = "7FB0E448",
          NextDialogue = 51007125,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700147:Sigh_End"
          }
        },
        [51007125] = {
          Content = "你……",
          DialogueId = 51007125,
          GUID = "7FB0E472",
          NextDialogue = 51007126,
          SpeakNpcId = 700147
        },
        [51007126] = {
          Content = "……好吧，没错。我是杰西卡。这些垃圾确实是我扔的，行了吧？你弯弯绕绕说了一大堆，不就想看我笑话吗？",
          DialogueId = 51007126,
          GUID = "7FB0E49C",
          NextDialogue = 51007127,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi",
          TalkActionId = {
            [1] = "700147:Agree"
          }
        },
        [51007127] = {
          Content = "没错，我和所有穷鬼一样，根本坐不起这破车，满意了吗？！",
          DialogueId = 51007127,
          GUID = "7FB0E4C6",
