          NextDialogue = 51007150,
          SpeakNpcId = 700148,
          TalkActionId = {
            [1] = "700147:Explain02_End",
            [2] = "700148:Think_Start"
          }
        },
        [51007150] = {
          Content = "我用不着你可怜，织星客。",
          DialogueId = 51007150,
          GUID = "7FB0E88C",
          NextOptions = {
