          TalkActionId = {
            [1] = "700148:Think_End"
          }
        },
        [51007151] = {
          Content = "你就不能好好说话吗？",
          DialogueId = 51007151,
          GUID = "7FB0E8B6",
          NextDialogue = 51007152
        },
        [51007152] = {
          Content = "“好好说话”？你的意思是要我也像那个织星客、像那个售票员一样，说些漂亮的空话，什么“远方”，什么“未来”，然后让人眼巴巴地盼望着？",
