          DialogueId = 51007164,
          GUID = "7FB0EAD8",
          NextDialogue = 51007165
        },
        [51007165] = {
          Content = "有空的时候，再把这些星星叠起来吧。",
          DialogueId = 51007165,
          GUID = "7FB0EB02",
          NextDialogue = 51007166,
          SpeakNpcId = 100001
        },
        [51007166] = {
          Content = "你……",
          DialogueId = 51007166,
          GUID = "7FB0EB2C",
          NextDialogue = 51007167,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi"
        },
        [51007167] = {
          Content = "好……好吧。受不了你的啰嗦了，我收下就是了。谢……谢谢。",
          DialogueId = 51007167,
          GUID = "7FB0EB56",
          NextDialogue = 51007172,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi"
        },
        [51007168] = {
          Content = "（就这样吧，尊重他人命运。）",
          DialogueId = 51007168,
          GUID = "7FB0EB80",
          NextDialogue = 51007169
        },
        [51007169] = {
          Content = "把它拿走吧。你以为我为什么要扔掉那些星星？这么多年下来，该想的我早就想清楚了，现实也早就认清了。",
          DialogueId = 51007169,
          GUID = "7FB0EBAA",
          NextDialogue = 51007170,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi"
        },
        [51007170] = {
          Content = "唉，憾事，憾事！",
          DialogueId = 51007170,
          GUID = "7FB0EBD4",
          NextDialogue = 51007171,
          SpeakNpcId = 700148,
          TalkActionId = {
            [1] = "700148:Disagree"
          }
        },
        [51007171] = {
          Content = "…………",
          DialogueId = 51007171,
          GUID = "7FB0EBFE",
          NextDialogue = 51007172,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi"
        },
        [51007172] = {
          Content = "……对了，就算是开往同一个目的地，不同车次的价格也不一样，有几趟会便宜些。虽然也省不了多少钱，但……",
          DialogueId = 51007172,
          GUID = "7FB0EC28",
          NextDialogue = 51007173,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi"
        },
        [51007173] = {
          Content = "如果，有一天你们真能从自己的破口袋里掏出点钱来买票的话……我可以帮你们提前看一看，预留最便宜的那趟车的票。",
          DialogueId = 51007173,
          GUID = "7FB0EC52",
          NextDialogue = 51007174,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi"
        },
        [51007174] = {
          Content = "作为交换，星星的事，别说出去。",
          DialogueId = 51007174,
          GUID = "7FB0EC7C",
          NextDialogue = 51007175,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi"
        },
        [51007175] = {
          Content = "感谢感谢，你原来是善良售票员！",
          DialogueId = 51007175,
          GUID = "7FB0ECA6",
          NextDialogue = 51007176,
          SpeakNpcId = 700148,
          TalkActionId = {
            [1] = "700148:Agree"
          }
        },
        [51007176] = {
          Content = "你说的，十几年前织星客，我遇到帮你捎话。",
          DialogueId = 51007176,
          GUID = "7FB0ECD0",
          NextDialogue = 51007177,
          SpeakNpcId = 700148,
          TalkActionId = {
            [1] = "700148:Talk02_Start"
          }
        },
        [51007177] = {
          Content = "谢谢你的好意，不过……不用了。如果有一天真的能离开这里，我大概也不会去找他了。我想去个不会下雪的地方，看看外边的人是不是都和冰湖城不一样。",
          DialogueId = 51007177,
          GUID = "7FB0ECFA",
          NextDialogue = 51007178,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi",
          TalkActionId = {
            [1] = "700148:Talk02_End",
            [2] = "700147:Explain02_Start"
          }
        },
        [51007178] = {
          Content = "也很好，用功攒钱，一定能够离开。",
          DialogueId = 51007178,
          GUID = "7FB0ED24",
          NextDialogue = 51007179,
          SpeakNpcId = 700148,
          TalkActionId = {
            [1] = "700147:Explain02_End",
            [2] = "700148:Agree"
          }
        },
        [51007179] = {
          Content = "……嗯。",
          DialogueId = 51007179,
          GUID = "7FB0ED4E",
          NextDialogue = 51007186,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi"
        },
        [51007180] = {
          Content = "你也有自己的星星。保存好你的星星，切记，不要丢进垃圾桶。",
          DialogueId = 51007180,
          GUID = "7FB0ED78",
          NextDialogue = 51007181,
          SpeakNpcId = 700148,
          TurnTo = {
            [1] = "700148:n(0)"
          }
        },
        [51007181] = {
          Content = "我名李安德，是织星客。前日子，生意有点赔，现在城门附近用心摆摊，请光顾！",
          DialogueId = 51007181,
          GUID = "7FB0EDA2",
          SpeakNpcName = "UI_CMNpc_Name_Liande",
          TalkActionId = {
            [1] = "700148:Explain02_Start"
          }
        },
        [51007182] = {
          Content = "是你啊……要买车票的话和我说一声就好。",
          DialogueId = 51007182,
          GUID = "7FB0EDCC",
          SpeakNpcId = 700021,
          TalkActionId = {
            [1] = "700021:Agree"
          }
        },
        [51007186] = {
          Content = "对了！我也有美丽纸张。我们一起折星星。",
          DialogueId = 51007186,
          GUID = "7FB0ED4F",
          NextDialogue = 51007187,
          SpeakNpcId = 700148
        },
        [51007187] = {
          Content = "啊？你是想让我帮你吗？可我不会折星星。",
          DialogueId = 51007187,
          GUID = "7FB0ED50",
          NextDialogue = 51007188,
          SpeakNpcId = 100001
        },
        [51007188] = {
          Content = "我也不会折，很丑。但是互帮互助，就会好看！",
          DialogueId = 51007188,
          GUID = "7FB0ED51",
          NextDialogue = 51007189,
          SpeakNpcId = 700148
        },
        [51007189] = {
          Content = "那我试试吧。",
          DialogueId = 51007189,
          GUID = "7FB0ED52",
          SpeakNpcId = 100001
        },
        [51007190] = {
          Content = "收下吧，善良有龙氏同胞。这里还有一些谢礼。",
          DialogueId = 51007190,
          GUID = "7FB0ED53",
          NextDialogue = 51007191,
          SpeakNpcId = 700148
        },
        [51007191] = {
          Content = "送我的？",
          DialogueId = 51007191,
          GUID = "7FB0ED54",
          NextDialogue = 51007192,
          SpeakNpcId = 100001
        },
        [51007192] = {
          Content = "嗯！她的星星，是愿望。织星客的星星，是远方，是故乡。",
          DialogueId = 51007192,
          GUID = "7FB0ED55",
          NextDialogue = 51007180,
          SpeakNpcId = 700148
        },
        [51007301] = {
          Content = "忠于欲望，忠于欲望，忠于欲望，哎，到底怎么才算忠于欲望啊……",
          DialogueId = 51007301,
          GUID = "7FB10152",
          NextDialogue = 51007302,
          SpeakNpcId = 700077
        },
        [51007302] = {
          Content = "我是考古学者！欲望这种东西不在我的研究领域啊！！！",
          DialogueId = 51007302,
          GUID = "7FB1017C",
          NextOptions = {
            [1] = 510073021,
            [2] = 510073022,
            [3] = 510073023
          },
          SpeakNpcId = 700077,
          bForbidSkipOptions = true
        },
        [51007303] = {
          Content = "你的见解很有意思，能帮帮我吗？",
          DialogueId = 51007303,
          GUID = "7FB101A6",
          NextOptions = {
            [1] = 510073031,
            [2] = 510073032
          },
          SpeakNpcId = 700077
        },
        [51007304] = {
          Content = "我是阿特拉西亚大陆考古协会，帝国分会的研究员，最近交上去的学术报告总是被“感受不到欲望”为由打回来。",
          DialogueId = 51007304,
          GUID = "7FB101D0",
          NextDialogue = 51007305,
          SpeakNpcId = 700077
        },
        [51007305] = {
          Content = "哎……真是搞不懂投资人的要求……",
          DialogueId = 51007305,
          GUID = "7FB101FA",
          NextDialogue = 51007306,
          SpeakNpcId = 700077
        },
        [51007306] = {
          Content = "什么投资人居然还懂学术？",
          DialogueId = 51007306,
          GUID = "7FB10224",
          NextDialogue = 51007307,
          SpeakNpcId = 100001
        },
        [51007307] = {
          Content = "虬先生可不是一般的投资人，卢卡的百年沉船、艾利西安的千年遗迹、海伯利亚的战争遗址等等考古学重大发现都是他亲自找到的。",
          DialogueId = 51007307,
          GUID = "7FB1024E",
          NextDialogue = 51007308,
          SpeakNpcId = 700077
        },
        [51007308] = {
          Content = "（雪莉眼含崇拜，滔滔不绝地向你讲述虬先生的过往。）",
          DialogueId = 51007308,
          GUID = "7FB10278",
          NextDialogue = 51007309
        },
        [51007309] = {
          Content = "虬先生是大陆考古协会的总投资人，更是一名伟大的考古学家与大收藏家。甚至还有传言说他是行走在华胥“阴影”中的君主……",
          DialogueId = 51007309,
          GUID = "7FB102A2",
          NextDialogue = 51007310,
          SpeakNpcId = 700077
        },
        [51007310] = {
          Content = "要是没有他的幕后资助，考古协会根本发展不成遍布大陆各个角落的庞大组织。",
          DialogueId = 51007310,
          GUID = "7FB102CC",
          NextDialogue = 51007311,
          SpeakNpcId = 700077
        },
        [51007311] = {
          Content = "唉……他老人家之前都不怎么管的，怎么突然又抓起我们考古协会不放了，华胥那边的退休生活这么清闲吗？",
          DialogueId = 51007311,
          GUID = "7FB102F6",
          NextDialogue = 51007312,
          SpeakNpcId = 700077
        },
        [51007312] = {
          Content = "能看看你的报告吗？",
          DialogueId = 51007312,
          GUID = "7FB10320",
          NextDialogue = 51007313,
          SpeakNpcId = 100001
        },
        [51007313] = {
          Content = "好啊，《冰湖城酒馆客流变化的简要分析》、《水仙平原饮品技术工艺演变》，《自称魔王的皎皎的观察记录》，要看哪个？",
          DialogueId = 51007313,
          GUID = "7FB1034A",
          NextOptions = {
            [1] = 510073131,
            [2] = 510073132
          },
          SpeakNpcId = 700077
        },
        [51007314] = {
          Content = "这也没办法呀，冰湖城冰天雪地的啥都挖不出来，所以写不了什么正常的考古报告嘛！",
          DialogueId = 51007314,
          GUID = "7FB10374",
          NextOptions = {
            [1] = 510073141
          },
          SpeakNpcId = 700077
        },
        [51007315] = {
          Content = "也许你缺一个合适的向导。",
          DialogueId = 51007315,
          FailDialogue = 510073151,
          GUID = "7FB1039E",
          ImprCheckId = 1061,
          NextDialogue = 510073152
        },
        [51007316] = {
          Content = "拜托你不要放弃我！",
          DialogueId = 51007316,
          GUID = "7FB103C8",
          SpeakNpcId = 700077
        },
        [51007317] = {
          Content = "好复杂的下水道，要不是你带我进来肯定会迷路。",
          DialogueId = 51007317,
          GUID = "7FB103F2",
          NextDialogue = 51007318,
          SpeakNpcId = 700172
        },
        [51007318] = {
          Content = "我偶尔也会迷路。",
          DialogueId = 51007318,
          GUID = "7FB1041C",
          NextDialogue = 51007319,
          SpeakNpcId = 100001
        },
        [51007319] = {
          Content = "嗯……就连经常来下水道探险的狩月人也会迷路，这个下水道的规模也太过巨大了。",
          DialogueId = 51007319,
          GUID = "7FB10446",
          NextDialogue = 51007320,
          SpeakNpcId = 700172
        },
        [51007320] = {
          Content = "对了，在海伯利亚的官方正史里，他们国家最早就是在冰湖城建立的。所以才会有这么一个和地面建筑差不多大的下水道吧。",
          DialogueId = 51007320,
          GUID = "7FB10447",
          NextDialogue = 51007321,
          SpeakNpcId = 700172
        },
        [51007321] = {
          Content = "感觉这里的墙壁要更古老一些。",
          DialogueId = 51007321,
          GUID = "7FB10470",
          NextDialogue = 51007322,
          SpeakNpcId = 100001
        },
        [51007322] = {
          Content = "应该是随着当时冰湖城的扩建不断完善的吧，好像冰湖城一开始是就是一个卡戎的定居点……",
          DialogueId = 51007322,
          GUID = "7FB1049A",
          NextDialogue = 51007323,
          SpeakNpcId = 700172
        },
        [51007323] = {
          Content = "啊，你这倒提醒我了，虽然外面的是冻土终年封冻，地面的建筑不断翻新，但是下水道说不定没有彻底翻新过。",
          DialogueId = 51007323,
          GUID = "7FB104C4",
          NextDialogue = 510073231,
          SpeakNpcId = 700172
        },
        [51007325] = {
          Content = "呜啊啊啊，这里也太高了吧，也不知道和华胥的执律阁比起来哪个高……我恐高症要犯了！",
          DialogueId = 51007325,
          GUID = "7FB10542",
          NextDialogue = 51007326,
          SpeakNpcId = 700173
        },
        [51007326] = {
          Content = "你先别看外面，盯着脚底下看一会儿缓一下吧。",
          DialogueId = 51007326,
          GUID = "7FB1056C",
          NextDialogue = 51007327,
          SpeakNpcId = 100001
        },
        [51007327] = {
          Content = "呼，呼……好多了。",
          DialogueId = 51007327,
          GUID = "7FB10596",
          NextDialogue = 51007328,
          SpeakNpcId = 700173
        },
        [51007328] = {
          Content = "真是的，当初帝国这帮人到底想什么，要修这么高的城墙。",
          DialogueId = 51007328,
          GUID = "7FB105C0",
          NextDialogue = 51007329,
          SpeakNpcId = 700173
        },
        [51007329] = {
          Content = "？",
          DialogueId = 51007329,
          GUID = "7FB105EA",
          NextDialogue = 51007330,
          SpeakNpcId = 700173
        },
        [51007330] = {
          Content = "对哦，为什么呢？我记得按照帝国正史记载的话，冰湖城最初是卡戎人的聚落。",
          DialogueId = 51007330,
          GUID = "7FB10614",
          NextDialogue = 51007331,
          SpeakNpcId = 700173
        },
        [51007331] = {
          Content = "初代皇帝迪斯·盖雷亚，也就是迪斯一世在大迁徙后到了这附近，想要和这里的卡戎部落和平相处，但是他的弟弟却被这里的卡戎以宴会的名义诱杀了。",
          DialogueId = 51007331,
          GUID = "7FB1063E",
          NextDialogue = 51007333,
          SpeakNpcId = 700173
        },
        [51007333] = {
          Content = "所以迪斯一世才会认定卡戎们是一群恶魔，率领着他的骑士团征服了附近的卡戎，带来了所谓的银色和平。",
          DialogueId = 51007333,
          GUID = "7FB10692",
          NextDialogue = 51007334,
          SpeakNpcId = 700173
        },
        [51007334] = {
          Content = "但如果是这样的话，这么高大的城墙，是要防备谁呢？是秽兽吗？还是说当时那些卡戎还在继续反抗？",
          DialogueId = 51007334,
          GUID = "7FB106BC",
          NextDialogue = 51007335,
          SpeakNpcId = 700173
        },
        [51007335] = {
          Content = "看来你又获得了灵感？",
          DialogueId = 51007335,
          GUID = "7FB106E6",
          NextDialogue = 51007336,
          SpeakNpcId = 100001
        },
        [51007336] = {
          Content = "灵感说不上啦，但是就是感到有一些奇怪，但是虬先生有教导我们说，不要放过任何感到奇怪的时刻，那里潜藏着真相。",
          DialogueId = 51007336,
          GUID = "7FB10710",
          NextDialogue = 51007339,
          SpeakNpcId = 700173
        },
        [51007339] = {
          Content = "总之谢谢，谢谢！现在的我感觉能写出有意思的考察报告了！",
          DialogueId = 51007339,
          GUID = "7FB1078E",
          NextDialogue = 51007340,
          SpeakNpcId = 700173
        },
        [51007340] = {
          Content = "如果没有你，我肯定像个傻瓜一样，认为冰湖城这破冻土没什么考古价值，然后像之前那样糊弄下去。",
          DialogueId = 51007340,
          GUID = "7FB107B8",
          NextDialogue = 51007341,
          SpeakNpcId = 700173
        },
        [51007341] = {
          Content = "是我太浅薄了！难道说，您就是潜藏在冰湖城的考古大师！",
          DialogueId = 51007341,
          GUID = "7FB107E2",
          NextOptions = {
            [1] = 510073411,
            [2] = 510073412,
            [3] = 510073413
          },
          SpeakNpcId = 700173,
          bForbidSkipOptions = true
        },
        [51007342] = {
          Content = "我想想……什么报酬才配的上大师您呢……",
          DialogueId = 51007342,
          GUID = "7FB1080C",
          NextDialogue = 51007343,
          SpeakNpcId = 700173
        },
        [51007343] = {
          Content = "有了，大师您在城门口等我一会儿！",
          DialogueId = 51007343,
          GUID = "7FB10836",
          SpeakNpcId = 700173
        },
        [51007344] = {
          Content = "不愧是大师，太有高人风范了！",
          DialogueId = 51007344,
          GUID = "7FB1080D",
          NextDialogue = 51007342,
          SpeakNpcId = 700173
        },
        [51007345] = {
          Content = "（没过多久，雪莉就拎着两个大袋子跑到了你的面前。）",
          DialogueId = 51007345,
          GUID = "7FB1088A",
          NextDialogue = 51007346
        },
        [51007346] = {
          Content = "大师！这是考古协会最新收到的帝国皇家钦定史书《海伯利亚史》第三十二编，小小敬意，希望大师不要嫌弃！",
          DialogueId = 51007346,
          GUID = "7FB108B4",
          NextDialogue = 51007347,
          SpeakNpcId = 700174
        },
        [51007347] = {
          Content = "（虽说是不要嫌弃，但雪莉丝毫没有给你拒绝的机会，硬是把两大袋子书塞到了你的手中，然后一边道谢一边蹦跳着跑远了。）",
          DialogueId = 51007347,
          GUID = "7FB108DE"
        },
        [51007382] = {
          Content = "13号管道已经在修了，我天，里面老鼠实在是太多了。",
          DialogueId = 51007382,
          GUID = "7FB10E9C",
          NextDialogue = 51007383,
          SpeakNpcId = 700069
        },
        [51007383] = {
          Content = "（达顿抬起头来，他身上臭气熏天，强烈刺鼻的味道逼得你不得不后退一步，你忍住干呕。）",
          DialogueId = 51007383,
          GUID = "7FB10EC6",
          NextDialogue = 51007384
        },
        [51007384] = {
          Content = "嘶，你躲什么躲，在下水道干活儿身上哪能没点味道。",
          DialogueId = 51007384,
          GUID = "7FB10EF0",
          SpeakNpcId = 700069,
          TalkOptions = {
            [1] = 510073841,
            [2] = 510073842,
            [3] = 510073843
          }
        },
        [51007388] = {
          Content = "别看我现在这样，在几年前，大多数人还是会尊敬地叫我“达顿医生”。",
          DialogueId = 51007388,
          GUID = "7FB10F98",
          NextDialogue = 51007389,
          SpeakNpcId = 700069
        },
        [51007389] = {
          Content = "你应该明白作为一个出生在贫民区的卡戎人，这个称呼有怎样特别的意义吧。",
          DialogueId = 51007389,
          GUID = "7FB10FC2",
          NextDialogue = 51007390,
          SpeakNpcId = 700069
        },
        [51007390] = {
          Content = "我在中心医院给数不清的卡戎人看病，甚至有贵族慕名请我问诊。",
          DialogueId = 51007390,
          GUID = "7FB10FEC",
          NextDialogue = 51007391,
          SpeakNpcId = 700069
        },
        [51007391] = {
          Content = "不信的话你可以问问年轻一辈的卡戎小孩，他们父母以前最常说的话就是让这帮孩子向我好好学习。",
          DialogueId = 51007391,
          GUID = "7FB11016",
          NextDialogue = 51007392,
          SpeakNpcId = 700069
        },
        [51007392] = {
          Content = "那时候我可有着不轻的洁癖呢，地砖缝但凡有一点灰尘都受不了......",
          DialogueId = 51007392,
          GUID = "7FB11040",
          RestartTag = 51007392,
          SpeakNpcId = 700069,
          TalkOptions = {
            [1] = 51007393
          }
        },
        [51007393] = {
          Content = "一个救死扶伤的人怎么会来修理下水道？",
          DialogueId = 51007393,
          GUID = "7FB1106A",
          ImprCheckId = 1062,
          NextDialogue = 510073931
        },
        [51007395] = {
          Content = "我之前修理人们，现在修理管道，也没什么不同吧。",
          DialogueId = 51007395,
          GUID = "7FB110BE",
          NextDialogue = 51007396,
          SpeakNpcId = 700069
        },
        [51007396] = {
          Content = "（达顿笑了笑，好像有什么不算轻松的故事就这么翻了篇。）",
          DialogueId = 51007396,
          GUID = "7FB110E8",
          NextDialogue = 51007398
        },
        [51007398] = {
          Content = "生活本来就是这样充满意外，突发高危急症的行人晕倒在一个医生面前，医生大义凛然，选了抢救。",
          DialogueId = 51007398,
          GUID = "7FB1113C",
          NextDialogue = 51007399,
          SpeakNpcId = 700069
        },
        [51007399] = {
          Content = "想知道结局是什么？等我修完下水道那几条破管子着，还是说你要跟我一起？",
          DialogueId = 51007399,
          GUID = "7FB11166",
          SpeakNpcId = 700069
        },
        [51007401] = {
          Content = "行，跟我来吧，路上那些乱七八糟的东西就交给你了。",
          DialogueId = 51007401,
          GUID = "7FB111BA",
          SpeakNpcId = 700069
        },
        [51007404] = {
          Content = "帮我拿下扳手——",
          DialogueId = 51007404,
          GUID = "7FB11238",
          SpeakNpcId = 700193
        },
        [51007405] = {
          Content = "总之，他的抢救不但没能请来奇迹，来的还是巨额赔偿金，医院为了名誉只好辞退了一个员工。",
          DialogueId = 51007405,
          GUID = "7FB11262",
          NextDialogue = 51007406,
          SpeakNpcId = 700194
        },
        [51007406] = {
          Content = "谁能想到呢，他竟然除了治病救人什么都不会，所以欢迎他的只有下水管道。",
          DialogueId = 51007406,
          GUID = "7FB1128C",
          NextDialogue = 51007407,
          SpeakNpcId = 700194
        },
        [51007407] = {
          Content = "好在当年怎么都没治好的洁癖，来这儿几个月就治好了。",
          DialogueId = 51007407,
          GUID = "7FB112B6",
          NextDialogue = 51007408,
          SpeakNpcId = 700194
        },
        [51007408] = {
          Content = "再者说，干这活儿也不至于被饿死在街上，不过就是得还债还到进棺材喽。",
          DialogueId = 51007408,
          GUID = "7FB112E0",
          NextDialogue = 51007409,
          SpeakNpcId = 700194
        },
        [51007409] = {
          Content = "如果再给你的人生重来一次的机会，你还会救他吗？",
          DialogueId = 51007409,
          GUID = "7FB1130A",
          NextDialogue = 51007410,
          SpeakNpcId = 700194
        },
        [51007410] = {
          Content = "（达顿转过身用扳手拧紧新换的螺丝，他甩着胳膊干得卖力又熟练，好像没听见你的问题。）",
          DialogueId = 51007410,
          GUID = "7FB11334",
          NextDialogue = 51007411
        },
        [51007411] = {
          Content = "（只是在如轰鸣般的沉默中，你和他都已经对答案心知肚明了。）",
          DialogueId = 51007411,
          GUID = "7FB1135E"
        },
        [51007415] = {
          Content = "哎呦……！里边这儿的老鼠也太多了！",
          DialogueId = 51007415,
          GUID = "7FB11406",
          SpeakNpcId = 700192
        },
        [51007501] = {
          Content = "嗯……实验对象1号，就决定是你了！",
          DialogueId = 51007501,
          GUID = "7FB12222",
          NextDialogue = 51007502,
          SpeakNpcId = 700011
        },
        [51007502] = {
          Content = "（眼前的孩子正满脸期待地看着你。）",
          DialogueId = 51007502,
          GUID = "7FB1224C",
          NextOptions = {
            [1] = 51007503,
            [2] = 51007506,
            [3] = 51007509
          }
        },
        [51007503] = {
          Content = "（注意到他穿着考究的制服，似乎还是一名学生。）",
          DialogueId = 51007503,
          GUID = "7FB12276",
          ImprPlusId = 1003,
          NextDialogue = 51007504
        },
        [51007504] = {
          Content = "你在说什么实验，是你的作业吗？",
          DialogueId = 51007504,
          GUID = "7FB122A0",
          NextDialogue = 51007505,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Explain01_Start"
          }
        },
        [51007505] = {
          Content = "不是啦，这是我的个人爱好！",
          DialogueId = 51007505,
          GUID = "7FB122CA",
          NextDialogue = 51007512,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Disagree"
          }
        },
        [51007506] = {
          Content = "（担心他一个人会遭遇危险。）",
          DialogueId = 51007506,
          GUID = "7FB122F4",
          ImprPlusId = 1004,
          NextDialogue = 51007507
        },
        [51007507] = {
          Content = "小朋友，你一个人待在这里不安全，我送你回家吧。",
          DialogueId = 51007507,
          GUID = "7FB1231E",
          NextDialogue = 51007508,
          SpeakNpcId = 700192,
          TalkActionId = {
            [1] = "0:Explain01_Start"
          }
        },
        [51007508] = {
          Content = "谢谢你，你人真好啊！不过我要先做完实验再回家。",
          DialogueId = 51007508,
          GUID = "7FB12348",
          NextDialogue = 51007512,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Agree"
          }
        },
        [51007509] = {
          Content = "（询问他说的实验是否能获取报酬。）",
          DialogueId = 51007509,
          GUID = "7FB12372",
          ImprPlusId = 1001,
          NextDialogue = 51007510
        },
        [51007510] = {
          Content = "诶？啊……有，当然有！我的零花钱都可以给你。",
          DialogueId = 51007510,
          GUID = "7FB1239C",
          NextDialogue = 51007512,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Agree"
          }
        },
        [51007512] = {
          Content = "是这样的，我正在开展一项针对卡戎之民的实验调查，恭喜你被选中成为我的第一个实验对象！",
          DialogueId = 51007512,
          GUID = "7FB123F0",
          NextDialogue = 51007513,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Explain01_Start"
          }
        },
        [51007513] = {
          Content = "为什么选我？",
          DialogueId = 51007513,
          GUID = "7FB1241A",
          NextDialogue = 51007514,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Think_Start"
          }
        },
        [51007514] = {
          Content = "是随机抽选的哦，这样才能排除主观因素影响！",
          DialogueId = 51007514,
          GUID = "7FB12444",
          NextDialogue = 51007515,
          SpeakNpcId = 700011
        },
        [51007515] = {
          Content = "咳咳，请先告诉我你的名字吧。",
          DialogueId = 51007515,
          GUID = "7FB1246E",
          NextOptions = {
            [1] = 51007516,
            [2] = 51007519
          },
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Explain01_End"
          }
        },
        [51007516] = {
          Content = "我叫诞生于净界岛·重生之焰·冰湖城守护者·光荣的·{nickname}。",
          DialogueId = 51007516,
          GUID = "7FB12498",
          ImprPlusId = 1005,
          NextDialogue = 51007517,
          Scripts = "SetTag{Tag{\"XiAoTag\"}, Value{\"Value_1\"}}"
        },
        [51007517] = {
          Content = "啊，请你说慢点……！那么，诞生于净界岛·重生……诞……蛋……",
          DialogueId = 51007517,
          GUID = "7FB124C2",
          NextDialogue = 51007518,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Talk01_Start"
          }
        },
        [51007518] = {
          Content = "呜，好难念！方便起见我就叫你{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}{性别：哥哥|姐姐}好了。",
          DialogueId = 51007518,
          GUID = "7FB124EC",
          NextDialogue = 51007522,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Agree"
          }
        },
        [51007519] = {
          Content = "我叫西比尔。",
          DialogueId = 51007519,
          GUID = "7FB12516",
          ImprPlusId = 1003,
          NextDialogue = 51007520,
          Scripts = "SetTag{Tag{\"XiAoTag\"}, Value{\"Value_2\"}}"
        },
        [51007520] = {
          Content = "总觉得这个名字有点耳熟，从哪里听过来着……",
          DialogueId = 51007520,
          GUID = "7FB12540",
          NextDialogue = 51007521,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Think_Start"
          }
        },
        [51007521] = {
          Content = "算了，不重要。{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}{性别：哥哥|姐姐}，我们开始吧。",
          DialogueId = 51007521,
          GUID = "7FB1256A",
          NextDialogue = 51007522,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Disagree"
          }
        },
        [51007522] = {
          Content = "放心，实验内容很简单，你只要填完这个调查问卷就行了！",
          DialogueId = 51007522,
          GUID = "7FB12594",
          NextDialogue = 51007523,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Explain01_Start"
          }
        },
        [51007523] = {
          Content = "（男孩双手捧起一沓厚厚的纸递给了你。）",
          DialogueId = 51007523,
          GUID = "7FB125BE",
          NextDialogue = 51007524
        },
        [51007524] = {
          Content = "（纸张的边缘并不整齐，似乎是从作业本上撕下来的；纸上是用稚嫩但工整的字体写下的一长串问题，序号甚至标到了三位数。）",
          DialogueId = 51007524,
          GUID = "7FB125E8",
          NextOptions = {
            [1] = 51007525,
            [2] = 51007527,
            [3] = 51007529
          }
        },
        [51007525] = {
          Content = "你这问卷未免也太长了吧……",
          DialogueId = 51007525,
          GUID = "7FB12612",
          NextDialogue = 51007526
        },
        [51007526] = {
          Content = "也还好吧，只有七百七十七个问题哦！",
          DialogueId = 51007526,
          GUID = "7FB1263C",
          NextDialogue = 51007531,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Explain01_Start"
          }
        },
        [51007527] = {
          Content = "这个长度的问卷要加钱。",
          DialogueId = 51007527,
          GUID = "7FB12666",
          NextDialogue = 51007528
        },
        [51007528] = {
          Content = "啊……可是我已经没有多的钱了……可以分期付款吗？",
          DialogueId = 51007528,
          GUID = "7FB12690",
          NextDialogue = 51007531,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Explain01_Start"
          }
        },
        [51007529] = {
          Content = "好的，我争取十年内填完。",
          DialogueId = 51007529,
          GUID = "7FB126BA",
          NextDialogue = 51007530
        },
        [51007530] = {
          Content = "咦？！那也太久了吧！",
          DialogueId = 51007530,
          GUID = "7FB126E4",
          NextDialogue = 51007531,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Explain01_Start"
          }
        },
        [51007531] = {
          Content = "拜托你答应我吧，冰湖城有这么多的卡戎，偏偏是你成为了我随机选中的那个观察目标，这可是天大的运气呢！",
          DialogueId = 51007531,
          GUID = "7FB1270E",
          NextDialogue = 51007532,
          SpeakNpcId = 700011
        },
        [51007532] = {
          Content = "（此时，一个高大的卡戎之民从你们旁边路过，男孩的身影在一瞬间消失不见了。你转过头，发现他缩进了你身后的阴影里。）",
          DialogueId = 51007532,
          GUID = "7FB12738",
          IsBlack = 1,
          NextDialogue = 51007533
        },
        [51007533] = {
          Content = "（高大的卡戎之民离开后，男孩又在一瞬间回到了原来的站立位置，仿佛什么都没发生过那样。）",
          DialogueId = 51007533,
          GUID = "7FB12762",
          IsBlack = 1,
          NextDialogue = 51007534
        },
        [51007534] = {
          Content = "好不好嘛，{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}{性别：哥哥|姐姐}？",
          DialogueId = 51007534,
          GUID = "7FB1278C",
          NextDialogue = 51007535,
          SpeakNpcId = 700011
        },
        [51007535] = {
          Content = "你刚才是在害怕吗？",
          DialogueId = 51007535,
          GUID = "7FB127B6",
          NextDialogue = 51007536,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Explain01_Start"
          }
        },
        [51007536] = {
          Content = "才、才没有呢！我、我只是……担心不打招呼会显得不礼貌而已！",
          DialogueId = 51007536,
          GUID = "7FB127E0",
          NextDialogue = 51007537,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Disagree"
          }
        },
        [51007537] = {
          Content = "研究者不能撒谎。",
          DialogueId = 51007537,
          GUID = "7FB1280A",
          NextDialogue = 51007538,
          SpeakNpcId = 100001
        },
        [51007538] = {
          Content = "呃……可、可能是有一点点点点害怕……总之，这些小事不重要啦！",
          DialogueId = 51007538,
          GUID = "7FB12834",
          NextDialogue = 51007539,
          SpeakNpcId = 700011
        },
        [51007539] = {
          Content = "刚才说到哪儿了……噢，对了，问卷！如果你实在不愿意填的话，我就挑几个重要的问题问吧，你只要口头回答就行了！",
          DialogueId = 51007539,
          GUID = "7FB1285E",
          NextDialogue = 51007540,
          SpeakNpcId = 700011
        },
        [51007540] = {
          Content = "如果你现在有空的话，我们就立刻开始问答吧？",
          DialogueId = 51007540,
          GUID = "7FB12888",
          SpeakNpcId = 700011
        },
        [51007543] = {
          Content = "好耶！那就听好咯——",
          DialogueId = 51007543,
          GUID = "7FB12906",
          NextDialogue = 51007544,
          SpeakNpcId = 700011
        },
        [51007544] = {
          Content = "问题1：你为什么只有一只角？",
          DialogueId = 51007544,
          GUID = "7FB12930",
          NextOptions = {
            [1] = 51007545,
            [2] = 51007547,
            [3] = 51007550
          },
          SpeakNpcId = 700011
        },
        [51007545] = {
          Content = "生来就是这样。",
          DialogueId = 51007545,
          GUID = "7FB1295A",
          NextDialogue = 51007546
        },
        [51007546] = {
          Content = "噢，所以是先天的差异……",
          DialogueId = 51007546,
          GUID = "7FB12984",
          NextDialogue = 51007553,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Agree"
          }
        },
        [51007547] = {
          Content = "另一只被我卖掉换钱了。",
          DialogueId = 51007547,
          GUID = "7FB129AE",
          NextDialogue = 51007548
        },
        [51007548] = {
          Content = "咦，还能这样？！",
          DialogueId = 51007548,
          GUID = "7FB129D8",
          NextDialogue = 51007549,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Shock_Start"
          }
        },
        [51007549] = {
          Content = "好想买一个用来研究啊……",
          DialogueId = 51007549,
          GUID = "7FB12A02",
          NextDialogue = 51007553,
          SpeakNpcId = 700011
        },
        [51007550] = {
          Content = "只有聪明的孩子才能看到另一只。",
          DialogueId = 51007550,
          GUID = "7FB12A2C",
          NextDialogue = 51007551
        },
        [51007551] = {
          Content = "……我才不会信这种骗小孩的话呢。",
          DialogueId = 51007551,
          GUID = "7FB12A56",
          NextDialogue = 51007552,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Disagree"
          }
        },
        [51007552] = {
          Content = "不过，原来卡戎也会开玩笑啊……",
          DialogueId = 51007552,
          GUID = "7FB12A80",
          NextDialogue = 51007553,
          SpeakNpcId = 700011
        },
        [51007553] = {
          Content = "嗯……下面是问题2：你的角摸起来是什么感觉，可以切一片给我摸摸吗？",
          DialogueId = 51007553,
          GUID = "7FB12AAA",
          NextOptions = {
            [1] = 51007554,
            [2] = 51007556,
            [3] = 51007558
          },
          SpeakNpcId = 700011
        },
        [51007554] = {
          Content = "会痛，不可以。",
          DialogueId = 51007554,
          GUID = "7FB12AD4",
          NextDialogue = 51007555
        },
        [51007555] = {
          Content = "对不起！……不过，原来恶魔的孩子也会感到痛吗，好像和爸爸说的不太一样……",
          DialogueId = 51007555,
          GUID = "7FB12AFE",
          NextDialogue = 51007562,
          SpeakNpcId = 700011
        },
        [51007556] = {
          Content = "一片三万银币。",
          DialogueId = 51007556,
          GUID = "7FB12B28",
          NextDialogue = 51007557
        },
        [51007557] = {
          Content = "诶诶诶——？那、那就算了吧……",
          DialogueId = 51007557,
          GUID = "7FB12B52",
          NextDialogue = 51007562,
          SpeakNpcId = 700011
        },
        [51007558] = {
          Content = "摸了会中毒哦。",
          DialogueId = 51007558,
          GUID = "7FB12B7C",
          NextDialogue = 51007559
        },
        [51007559] = {
          Content = "真的吗？毒性有多大呢？有解毒的方法吗？你自己也会中毒吗？",
          DialogueId = 51007559,
          GUID = "7FB12BA6",
          NextDialogue = 51007560,
          SpeakNpcId = 700011
        },
        [51007560] = {
          Content = "……没毒，只是开个玩笑。但是受伤会痛，所以不可以切。",
          DialogueId = 51007560,
          GUID = "7FB12BD0",
          NextDialogue = 51007561,
          SpeakNpcId = 100001
