        },
        [51007658] = {
          Content = "让我想想……假设这些小老鼠对老鼠战士抱有尊敬之情，那么它们应该也会像它一样，非常勇敢、对人友好、爱护同伴吧？",
          DialogueId = 51007658,
          GUID = "7FB13BE4",
          NextDialogue = 51007659,
          SpeakNpcId = 700204
        },
        [51007659] = {
          Content = "好，就让我们去亲眼验证一下！刚才的小老鼠往拐角方向去了，我们快追上它吧。",
          DialogueId = 51007659,
          GUID = "7FB13C0E",
          SpeakNpcId = 700204
        },
        [51007660] = {
          Content = "看，那就是老鼠们的家！",
          DialogueId = 51007660,
          GUID = "7FB13C38",
          NextDialogue = 51007661,
          SpeakNpcId = 700204
        },
        [51007661] = {
          Content = "（老鼠窝中传来“吱——吱——”的尖锐叫声，伴随着一阵微妙的臭气，但西奥并没有退缩。他睁大了眼睛，认真地观察着老鼠们的行动。）",
          DialogueId = 51007661,
          GUID = "7FB13C62",
          NextDialogue = 51007662
        },
        [51007662] = {
          Content = "（小老鼠们正在为了争夺半块饼而互相撕咬。）",
          DialogueId = 51007662,
          GUID = "7FB13C8C",
          NextDialogue = 51007663
        },
        [51007663] = {
          Content = "啊……他们好像……不是太爱护同伴。",
          DialogueId = 51007663,
          GUID = "7FB13CB6",
          NextDialogue = 51007664,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Shock_Start"
          }
        },
        [51007664] = {
          Content = "（注意到有人接近，一部分小老鼠受到了惊吓，慌张地逃走了。）",
          DialogueId = 51007664,
          GUID = "7FB13CE0",
          NextDialogue = 51007665
        },
        [51007665] = {
          Content = "呃……他们好像……也不太勇敢。",
          DialogueId = 51007665,
          GUID = "7FB13D0A",
          NextDialogue = 51007666,
          SpeakNpcId = 700204
        },
        [51007666] = {
          Content = "（剩下的几只老鼠忽然眼露凶光，朝你们发起了攻击！）",
          DialogueId = 51007666,
          GUID = "7FB13D34",
          NextDialogue = 51007667
        },
        [51007667] = {
          Content = "啊啊啊——怎么平白无故地袭击人呀，太没有礼貌了吧？！",
          DialogueId = 51007667,
          GUID = "7FB13D5E",
          NextDialogue = 51007668,
          SpeakNpcId = 700204
        },
        [51007668] = {
          Content = "{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}{性别：哥哥|姐姐}，我们快逃！",
          DialogueId = 51007668,
          GUID = "7FB13D88",
          NextDialogue = 51007669,
          SpeakNpcId = 700204
        },
        [51007669] = {
          Content = "你先逃，我来对付它们。",
          DialogueId = 51007669,
          GUID = "7FB13DB2",
          SpeakNpcId = 100001
        },
        [51007670] = {
          Content = "{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}{性别：哥哥|姐姐}，你回来啦！我刚才远远地观察了你战斗的情况，你好厉害呀！",
          DialogueId = 51007670,
          GUID = "7FB13DDC",
          NextDialogue = 51007671,
          SpeakNpcId = 700204
        },
        [51007671] = {
          Content = "“{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}拥有强大的战斗能力”……嗯，我记下了。",
          DialogueId = 51007671,
          GUID = "7FB13E06",
          NextDialogue = 51007672,
          SpeakNpcId = 700204
        },
        [51007672] = {
          Content = "不过……唉，看来那些小老鼠并没有情感吧……",
          DialogueId = 51007672,
          GUID = "7FB13E30",
          NextOptions = {
            [1] = 51007673,
            [2] = 51007675
          },
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Disagree"
          }
        },
        [51007673] = {
          Content = "也许它们只是还在成长。",
          DialogueId = 51007673,
          GUID = "7FB13E5A",
          NextDialogue = 51007674
        },
        [51007674] = {
          Content = "嗯……！你说得对，也许等它们长大之后，就会成为像老鼠战士一样优秀的大老鼠了。",
          DialogueId = 51007674,
          GUID = "7FB13E84",
          NextDialogue = 51007677,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007675] = {
          Content = "也许是因为能教导它们的前辈已经不在了。",
          DialogueId = 51007675,
          GUID = "7FB13EAE",
          NextDialogue = 51007676
        },
        [51007676] = {
          Content = "嗯……你说得对。真是让人难过啊……希望就算失去了前辈的保护，它们也能坚强地长大。",
          DialogueId = 51007676,
          GUID = "7FB13ED8",
          NextDialogue = 51007677,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007677] = {
          Content = "我已经做好记录了，今天的调查就到这里为止吧。",
          DialogueId = 51007677,
          GUID = "7FB13F02",
          NextDialogue = 51007678,
          SpeakNpcId = 700204
        },
        [51007678] = {
          Content = "谢谢你陪我，{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}{性别：哥哥|姐姐}，你真是个聪明又可靠的人呀！看来他们说的那些关于狩月人的坏话并不是真的。",
          DialogueId = 51007678,
          GUID = "7FB13F2C",
          NextDialogue = 51007679,
          SpeakNpcId = 700204
        },
        [51007679] = {
          Content = "要是所有卡戎都像你一样友善就好啦……比如说，之前我在城北一家旅馆门口看到了一个绿衣服姐姐，我和她打招呼，但她完全不理我。",
          DialogueId = 51007679,
          GUID = "7FB13F56",
          NextDialogue = 51007680,
          SpeakNpcId = 700204
        },
        [51007680] = {
          Content = "她可能只是刚好没看到吧。",
          DialogueId = 51007680,
          GUID = "7FB13F80",
          NextDialogue = 51007681,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Explain01_Start"
          }
        },
        [51007681] = {
          Content = "嗯？你这么说……难道是你认识那个姐姐吗？",
          DialogueId = 51007681,
          GUID = "7FB13FAA",
          NextDialogue = 51007682,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007682] = {
          Content = "是的。",
          DialogueId = 51007682,
          GUID = "7FB13FD4",
          NextDialogue = 51007683,
          SpeakNpcId = 100001
        },
        [51007683] = {
          Content = "真了不起，你居然认识这么多人……你是怎么和他们沟通的，也教教我吧？",
          DialogueId = 51007683,
          GUID = "7FB13FFE",
          NextOptions = {
            [1] = 51007684,
            [2] = 51007686
          },
          SpeakNpcId = 700204
        },
        [51007684] = {
          Content = "多和不同的人对话，积累技巧。",
          DialogueId = 51007684,
          GUID = "7FB14028",
          NextDialogue = 51007685
        },
        [51007685] = {
          Content = "（西奥在本子上写下：“{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}与人沟通的秘诀是：多和不同的人对话，积累技巧。”）",
          DialogueId = 51007685,
          GUID = "7FB14052",
          NextDialogue = 51007688
        },
        [51007686] = {
          Content = "遇事不决武力威胁。",
          DialogueId = 51007686,
          GUID = "7FB1407C",
          NextDialogue = 51007687
        },
        [51007687] = {
          Content = "（西奥在本子上写下：“{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}与人沟通的秘诀是：遇事不决武力威胁。备注：这个方法似乎不适合我。”）",
          DialogueId = 51007687,
          GUID = "7FB140A6",
          NextDialogue = 51007688
        },
        [51007688] = {
          Content = "嗯嗯……我记下了。",
          DialogueId = 51007688,
          GUID = "7FB140D0",
          NextDialogue = 51007689,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007689] = {
          Content = "（不远处忽然传来了一阵急促的脚步声，一位打扮得体的女士怒气冲冲地朝你们走来。）",
          DialogueId = 51007689,
          GUID = "7FB140FA",
          IsBlack = 1
        },
        [51007690] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          Content = "西奥，你又跑到哪里去了？天呐，瞧瞧你，怎么把衣服弄得这么脏！",
          DefaultLookAt = "1.0",
          DialogueId = 51007690,
          GUID = "7FB14124",
          NextDialogue = 51007691,
          SpeakNpcId = 700205,
          SpeakNpcName = "UI_CMNpc_Name_DeTiWoman",
          TurnTo = {
            [1] = "700204:n(700205)",
            [2] = "100001:n(700205)",
            [3] = "700205:n(700204)"
          }
        },
        [51007691] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          Content = "妈妈……！我们刚才去下水道里观察老鼠了。",
          DefaultLookAt = "1.0",
          DialogueId = 51007691,
          GUID = "7FB1414E",
          NextDialogue = 51007692,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Explain01_Start"
          }
        },
        [51007692] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          Content = "什么？那种肮脏的生物有什么值得观察的？",
          DefaultLookAt = "1.0",
          DialogueId = 51007692,
          GUID = "7FB14178",
          NextDialogue = 51007693,
          SpeakNpcId = 700205
        },
        [51007693] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          Content = "成天研究这些莫名其妙的玩意儿，偏偏就是不愿意好好上课……真是愁死我了……",
          DefaultLookAt = "1.0",
          DialogueId = 51007693,
          GUID = "7FB141A2",
          NextDialogue = 51007694,
          SpeakNpcId = 700205,
          TalkActionId = {
            [1] = "700205:Sigh_Start"
          }
        },
        [51007694] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          Content = "（女人抱怨了一通后，终于注意到了你。她警惕地把西奥拉到了身后。）",
          DefaultLookAt = "1.0",
          DialogueId = 51007694,
          GUID = "7FB141CC",
          NextDialogue = 51007695,
          TurnTo = {
            [1] = "700204:n(100001)",
            [2] = "700205:n(100001)"
          }
        },
        [51007695] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          Content = "你又是谁？就是你把这孩子带坏的吧？",
          DefaultLookAt = "1.0",
          DialogueId = 51007695,
          GUID = "7FB141F6",
          NextOptions = {
            [1] = 51007696,
            [2] = 51007698
          },
          SpeakNpcId = 700205
        },
        [51007696] = {
          Content = "请你不要无凭无据地随意诬陷人。",
          DialogueId = 51007696,
          GUID = "7FB14220",
          ImprPlusId = 1002,
          NextDialogue = 51007697
        },
        [51007697] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          Content = "呵，你们卡戎也好意思喊冤？",
          DefaultLookAt = "1.0",
          DialogueId = 51007697,
          GUID = "7FB1424A",
          NextDialogue = 51007700,
          SpeakNpcId = 700205
        },
        [51007698] = {
          Content = "没错，就是我，恭喜你猜对了！",
          DialogueId = 51007698,
          GUID = "7FB14274",
          ImprPlusId = 1005,
          NextDialogue = 51007699
        },
        [51007699] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          Content = "你……！",
          DefaultLookAt = "1.0",
          DialogueId = 51007699,
          GUID = "7FB1429E",
          NextDialogue = 51007700,
          SpeakNpcId = 700205
        },
        [51007700] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          Content = "西奥……我跟你说了多少次，别和卡戎混在一起！他们没一个好东西！",
          DefaultLookAt = "1.0",
          DialogueId = 51007700,
          GUID = "7FB142C8",
          NextDialogue = 51007701,
          SpeakNpcId = 700205,
          TurnTo = {
            [1] = "700204:n(700205)",
            [2] = "100001:n(700205)",
            [3] = "700205:n(700204)"
          }
        },
        [51007701] = {
          Content = "（男孩被母亲强行拽走了。在离开之前，他悄悄地回过头，用口型对你说了一句“下次见”，并轻轻将一个小包裹扔给了你。）",
          DialogueId = 51007701,
          GUID = "7FB142F2",
          IsBlack = 1
        },
        [51007702] = {
          Content = "{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}{性别：哥哥|姐姐}，{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}{性别：哥哥|姐姐}，我在这里！",
          DialogueId = 51007702,
          GUID = "7FB1431C",
          NextDialogue = 51007703,
          SpeakNpcId = 700204
        },
        [51007703] = {
          Content = "（男孩躲在建筑的阴影中，激动地向你挥手。）",
          DialogueId = 51007703,
          GUID = "7FB14346",
          NextDialogue = 51007704
        },
        [51007704] = {
          Content = "又见面啦！",
          DialogueId = 51007704,
          GUID = "7FB14370",
          NextDialogue = 51007705,
          SpeakNpcId = 700204
        },
        [51007705] = {
          Content = "我后来去打听了哦，你的真名叫{nickname}对吧！真是的，怎么能骗小孩呢？",
          DialogueId = 51007705,
          GUID = "7FB1439A",
          NextDialogue = 51007706,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Talk03_Start"
          }
        },
        [51007706] = {
          Content = "上次真是对不起，我妈妈好像很怕卡戎。",
          DialogueId = 51007706,
          GUID = "7FB143C4",
          NextDialogue = 51007707,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Explain01_Start"
          }
        },
        [51007707] = {
          Content = "那天回去以后，妈妈拉着我说了一大堆话，什么“卡戎人都是好吃懒做的家伙，是天生的罪犯，非常危险”之类的。",
          DialogueId = 51007707,
          GUID = "7FB143EE",
          NextDialogue = 51007708,
          SpeakNpcId = 700204
        },
        [51007708] = {
          Content = "其他大人说的也都差不多。但是我越想越觉得奇怪呀！",
          DialogueId = 51007708,
          GUID = "7FB14418",
          NextDialogue = 51007709,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Disagree"
          }
        },
        [51007709] = {
          Content = "我想去了解卡戎人，但要么是我不敢跟他们说话，要么是他们不愿意和我聊天，所以你能给我讲讲他们的生活吗？",
          DialogueId = 51007709,
          GUID = "7FB14442",
          NextDialogue = 51007710,
          SpeakNpcId = 700204
        },
        [51007710] = {
          Content = "比起说，不如直接带你去看看吧。我这里还有相机，你可以拍点照片带回去好好想一想。",
          DialogueId = 51007710,
          GUID = "7FB1446C",
          NextDialogue = 51007711,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Explain01_Start"
          }
        },
        [51007711] = {
          Content = "真的吗？谢谢你！",
          DialogueId = 51007711,
          GUID = "7FB14496",
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007712] = {
          Camera = "-329.898193,-397.409424,278.790771,0.000011,-19.79974,48.99963,22.97237,100000.0,false,Manual,22.0",
          Content = "你看这些破旧的小摊，每天天不亮的时候便会支起来，很多卡戎之民就是这样谋生的。跟他们熟起来的话，说不定会给你打点折扣呢。",
          DialogueId = 51007712,
          GUID = "7FB144C0",
          NextDialogue = 51007713,
          SpeakNpcId = 100001
        },
        [51007713] = {
          Camera = "-329.898193,-397.409424,278.790771,0.000011,-19.79974,48.99963,22.97237,100000.0,false,Manual,22.0",
          Content = "大家……很累很辛苦呢。",
          DialogueId = 51007713,
          GUID = "7FB144EA",
          SpeakNpcId = 700204
        },
        [51007714] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          Content = "这里就是大部分卡戎生活的地方了。",
          DialogueId = 51007714,
          GUID = "7FB14514",
          NextDialogue = 51007715,
          SpeakNpcId = 100001
        },
        [51007715] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          Content = "唔嗯……房子破破的，啊，这是那个很凶的大叔在帮邻居修房顶呢。还有这些小朋友在玩的游戏，我在内城也和朋友们玩过。",
          DialogueId = 51007715,
          GUID = "7FB1453E",
          NextDialogue = 51007716,
          SpeakNpcId = 700204
        },
        [51007716] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          Content = "我懂你的意思了，事实并不像妈妈说的那样，虽然有些卡戎人说话很凶、行为古怪……但我们索拉人里也有这种人啊。",
          DialogueId = 51007716,
          GUID = "7FB14568",
          NextDialogue = 51007717,
          SpeakNpcId = 700204
        },
        [51007717] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          Content = "除了头上的角以外，我觉得你们和我们没有什么不同。",
          DialogueId = 51007717,
          GUID = "7FB14592",
          NextDialogue = 51007718,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Explain01_Start"
          }
        },
        [51007718] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          Content = "这么明显的事实，只要稍微观察一下就明白了，为什么大家还是坚持那些错误的说法呢？",
          DialogueId = 51007718,
          GUID = "7FB145BC",
          NextOptions = {
            [1] = 51007719,
            [2] = 51007720
          },
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Think_Start"
          }
        },
        [51007719] = {
