          DialogueId = 51007817,
          GUID = "7FB155FA",
          NextOptions = {
            [1] = 51007818
          },
          RestartTag = 51007817,
          SpeakNpcId = 700018
        },
        [51007818] = {
          Content = "红角鹿活了三亿年，不该被人们的贪婪一朝逼入绝境。",
          DialogueId = 51007818,
          GUID = "7FB15624",
          ImprCheckId = 1063,
          NextDialogue = 51007819
        },
        [51007819] = {
          Content = "算了，多说无益......",
          DialogueId = 51007819,
          GUID = "7FB1564E",
          NextDialogue = 51007820,
          SpeakNpcId = 700018
        },
        [51007820] = {
          Content = "（阿尔加尔叹了口气，瘦弱的身体在转身时踉跄了一下，离开的背影如同一位殉道者。）",
          DialogueId = 51007820,
          GUID = "7FB15678",
          NextDialogue = 51007821,
          SpeakNpcId = 700018
        },
        [51007821] = {
          Content = "正如你所说，它们珍贵的鹿角不该成了猎人的摇钱树。",
          DialogueId = 51007821,
          GUID = "7FB156A2",
          NextDialogue = 51007822,
          SpeakNpcId = 700018
        },
        [51007822] = {
          Content = "红角鹿的繁殖期马上就要到了，我们必须为自然真的做些什么。",
          DialogueId = 51007822,
          GUID = "7FB156CC",
          NextDialogue = 51007823,
          SpeakNpcId = 700018
        },
        [51007823] = {
