          FacialId = {
            [1] = "230002:Satisfy01"
          },
          GUID = "7FB229C8",
          LookAt = {
            [1] = "230002:n(100001)"
          },
          NextDialogue = 51009109,
          SpeakNpcId = 230002
        },
        [51009109] = {
