          },
          NextDialogue = 51009129,
          SpeakNpcId = 230002,
          TalkActionId = {
            [1] = "230001:Explain02_End"
          }
        },
        [51009129] = {
          Content = "年轻人，能不能帮老朽一个忙？",
          DialogueId = 51009129,
          FacialId = {
            [1] = "230002:None"
          },
          GUID = "7FB22D3A",
          LookAt = {
            [1] = "230002:n(100001)"
