          DialogueId = 51009321,
          GUID = "7FB24CBA",
          NextDialogue = 51009322
        },
        [51009322] = {
          Content = "嗯，“精灵”是他的说法。",
          DialogueId = 51009322,
          GUID = "7FB24CE4",
          NextDialogue = 51009323,
          SpeakNpcId = 700247
        },
        [51009323] = {
          Content = "说起来，外面起风了吗？",
          DialogueId = 51009323,
          GUID = "7FB24D0E",
          NextOptions = {
            [1] = 51009324,
            [2] = 51009326,
            [3] = 51009328
          },
          SpeakNpcId = 700247
        },
        [51009324] = {
          Content = "我没注意。",
          DialogueId = 51009324,
          GUID = "7FB24D38",
          NextDialogue = 51009325
        },
        [51009325] = {
          Content = "这样啊……没关系，我等会儿自己出去确认一下。",
          DialogueId = 51009325,
          GUID = "7FB24D62",
          NextDialogue = 51009330,
          SpeakNpcId = 700247
        },
        [51009326] = {
          Content = "正在刮大风。",
          DialogueId = 51009326,
          GUID = "7FB24D8C",
          NextDialogue = 51009327
        },
        [51009327] = {
          Content = "那就太好了。",
          DialogueId = 51009327,
          GUID = "7FB24DB6",
          NextDialogue = 51009330,
          SpeakNpcId = 700247
        },
        [51009328] = {
          Content = "没有风我也可以制造风。",
          DialogueId = 51009328,
          GUID = "7FB24DE0",
          NextDialogue = 51009329
        },
        [51009329] = {
          Content = "是吗，原来你这么厉害呀！谢谢你的好意。",
          DialogueId = 51009329,
          GUID = "7FB24E0A",
          NextDialogue = 51009330,
          SpeakNpcId = 700247
        },
        [51009330] = {
          Content = "我得等到起风的时候，才能把花送给他呢。",
          DialogueId = 51009330,
          GUID = "7FB24E34",
          NextOptions = {
            [1] = 51009331,
            [2] = 51009333,
            [3] = 51009335
          },
          SpeakNpcId = 700247
        },
        [51009331] = {
          Content = "为什么一定要等起风？",
          DialogueId = 51009331,
          GUID = "7FB24E5E",
          NextDialogue = 51009332
        },
        [51009332] = {
          Content = "因为起风的时候，花才会往空中飘呀。",
          DialogueId = 51009332,
          GUID = "7FB24E88",
          NextDialogue = 51009337,
          SpeakNpcId = 700247
        },
        [51009333] = {
          Content = "莫非你的朋友是风精灵吗？",
          DialogueId = 51009333,
          GUID = "7FB24EB2",
          NextDialogue = 51009334
        },
        [51009334] = {
          Content = "呵呵，很有意思的想法！说不定真的是喔。",
          DialogueId = 51009334,
          GUID = "7FB24EDC",
          NextDialogue = 51009337,
          SpeakNpcId = 700247
        },
        [51009335] = {
          Content = "这是某种特殊的仪式吗？",
          DialogueId = 51009335,
          GUID = "7FB24F06",
          NextDialogue = 51009336
        },
        [51009336] = {
          Content = "嗯……是传递思念的仪式。",
          DialogueId = 51009336,
          GUID = "7FB24F30",
          NextDialogue = 51009337,
          SpeakNpcId = 700247
        },
        [51009337] = {
          Content = "我的那位朋友，在几年前就去天上啦。",
          DialogueId = 51009337,
          GUID = "7FB24F5A",
          NextDialogue = 51009338,
          SpeakNpcId = 700247
        },
        [51009338] = {
          Content = "今天是每年一次的纪念日。",
          DialogueId = 51009338,
          GUID = "7FB24F84",
          NextOptions = {
            [1] = 51009339
          },
          RestartTag = 51009338,
          SpeakNpcId = 700247
        },
        [51009339] = {
          Content = "（提醒她卡戎人的习俗。）",
          DialogueId = 51009339,
          FailDialogue = 51009340,
          GUID = "7FB24FAE",
          ImprCheckId = 1071,
          NextDialogue = 51009341
        },
        [51009340] = {
          Content = "（你一时记不起习俗的细节。）",
          DialogueId = 51009340,
          GUID = "7FB24FD8"
        },
        [51009341] = {
          Content = "在卡戎人的观念中，雾海才是灵魂的归去之地。如果要纪念他，将花送往水中更加合理。",
          DialogueId = 51009341,
          GUID = "7FB25002",
          NextDialogue = 51009342,
          SpeakNpcId = 100001
        },
        [51009342] = {
          Content = "嗯……我知道。但是，他不一样。",
          DialogueId = 51009342,
          GUID = "7FB2502C",
          NextDialogue = 51009343,
          SpeakNpcId = 700247
        },
        [51009343] = {
          Content = "（女子沉默了片刻，看向窗外，眼神中流露着温柔的怀念。）",
          DialogueId = 51009343,
          GUID = "7FB25056",
          NextDialogue = 51009344
        },
        [51009344] = {
          Content = "我第一次遇见他是在城外。我们年纪相仿，性格也很像，所以很快就成了好朋友。",
          DialogueId = 51009344,
          GUID = "7FB25080",
          NextDialogue = 51009345,
          SpeakNpcId = 700247
        },
        [51009345] = {
          Content = "他对我说自己从是天上来的“精灵”……呵呵，其实我早知道他是卡戎人，但每次看到他那么努力地圆谎，实在是舍不得戳穿。",
          DialogueId = 51009345,
          GUID = "7FB250AA",
          NextDialogue = 51009346,
          SpeakNpcId = 700247
        },
        [51009346] = {
          Content = "而且，他确实就像故事里的精灵一样，知道许多我不知道的事，永远有讲不完的新奇见闻。",
          DialogueId = 51009346,
          GUID = "7FB250D4",
          NextOptions = {
            [1] = 51009347,
            [2] = 51009349
          },
          SpeakNpcId = 700247
        },
        [51009347] = {
          Content = "听起来是个很棒的朋友。",
          DialogueId = 51009347,
          GUID = "7FB250FE",
          NextDialogue = 51009348
        },
        [51009348] = {
          Content = "嗯！他是最棒的朋友。",
          DialogueId = 51009348,
          GUID = "7FB25128",
          NextDialogue = 51009351,
          SpeakNpcId = 700247
        },
        [51009349] = {
          Content = "所以他从小到大一直在扮演精灵吗？",
          DialogueId = 51009349,
          GUID = "7FB25152",
          NextDialogue = 51009350
        },
        [51009350] = {
          Content = "呵呵，听起来有点幼稚，对吧？",
          DialogueId = 51009350,
          GUID = "7FB2517C",
          NextDialogue = 51009351,
          SpeakNpcId = 700247
        },
        [51009351] = {
          Content = "我心里一直都有些苦恼——等到我们都长大，过了能理所当然地相信童话的年纪以后，要怎么开口说破这件事？",
          DialogueId = 51009351,
          GUID = "7FB251A6",
          NextDialogue = 51009352,
          SpeakNpcId = 700247
        },
        [51009352] = {
          Content = "无论是我先开口还是他先开口，想象一下都很尴尬呀……",
          DialogueId = 51009352,
          GUID = "7FB251D0",
          NextDialogue = 51009353,
          SpeakNpcId = 700247
        },
        [51009353] = {
          Content = "但最后我们并没有走到那个时间点。他在成年之前便离开了。",
          DialogueId = 51009353,
          GUID = "7FB251FA",
          NextDialogue = 51009354,
          SpeakNpcId = 700247
        },
        [51009354] = {
          Content = "你说，他会不会是想到了这一点，才故意选在那个时候离开的？呵呵，真是个温柔的人啊……",
          DialogueId = 51009354,
          GUID = "7FB25224",
          NextDialogue = 51009355,
          SpeakNpcId = 700247
        },
        [51009355] = {
          Content = "（女子抚摸着柔软的花瓣，轻轻垂下了眼眸。你分辨不出她脸上的情绪。）",
          DialogueId = 51009355,
          GUID = "7FB2524E",
          NextOptions = {
            [1] = 51009356,
            [2] = 51009358,
            [3] = 51009360
          }
        },
        [51009356] = {
          Content = "抱歉，请节哀……",
          DialogueId = 51009356,
          GUID = "7FB25278",
          ImprPlusId = 1002,
          NextDialogue = 51009357
        },
        [51009357] = {
          Content = "没关系，已经过去很多年啦。",
          DialogueId = 51009357,
          GUID = "7FB252A2",
          NextDialogue = 51009362,
          SpeakNpcId = 700247
        },
        [51009358] = {
          Content = "你们都是非常温柔的人。",
          DialogueId = 51009358,
          GUID = "7FB252CC",
          ImprPlusId = 1004,
          NextDialogue = 51009359
        },
        [51009359] = {
          Content = "呵呵，谢谢你。",
          DialogueId = 51009359,
          GUID = "7FB252F6",
          NextDialogue = 51009362,
          SpeakNpcId = 700247
        },
        [51009360] = {
          Content = "成年这个时间点……难道说，他是出现了秽蚀的征兆？",
          DialogueId = 51009360,
          GUID = "7FB25320",
          ImprPlusId = 1003,
          NextDialogue = 51009361
        },
        [51009361] = {
          Content = "嗯，我也这么想。毕竟他离开的时候，刚好是快满十八岁。",
          DialogueId = 51009361,
          GUID = "7FB2534A",
          NextDialogue = 51009362,
          SpeakNpcId = 700247
        },
        [51009362] = {
          Content = "他早就预料到了自己的结局……最后见面的那次，他对我说，自己将要回到天上的故乡，从今往后不能再来找我。",
          DialogueId = 51009362,
          GUID = "7FB25374",
          NextDialogue = 51009363,
          SpeakNpcId = 700247
        },
        [51009363] = {
          Content = "那是他撒谎撒得最拙劣的一次……明明眼泪已经在眼眶里打转了，还拼命挤出一副微笑的表情，用愉快的语调对我说——",
          DialogueId = 51009363,
          GUID = "7FB2539E",
          NextDialogue = 51009364,
          SpeakNpcId = 700247
        },
        [51009364] = {
          Content = "“请你不要感到难过。虽然我不能再来见你，但我会在云端之上一直、一直注视着你……”",
          DialogueId = 51009364,
          GUID = "7FB253C8",
          NextDialogue = 51009365,
          SpeakNpcId = 700247
        },
        [51009365] = {
          Content = "“无论何时，只要你抬头望向天空，你的思念就能够随风抵达我的身边。”",
          DialogueId = 51009365,
          GUID = "7FB253F2",
          NextDialogue = 51009366,
          SpeakNpcId = 700247
        },
        [51009366] = {
          Content = "（说到这里，女子露出了微笑。不知是否是错觉，她的眼中隐约闪过了一丝光亮——那究竟是泪光，还是从玻璃窗中洒下的阳光呢？）",
          DialogueId = 51009366,
          GUID = "7FB2541C",
          NextDialogue = 51009367
        },
        [51009367] = {
          Content = "所以，你才会把花撒向天空……？",
          DialogueId = 51009367,
          GUID = "7FB25446",
          NextDialogue = 51009368,
          SpeakNpcId = 100001
        },
        [51009368] = {
          Content = "嗯。既然那是他想要告诉我的故事，那么我也愿意相信，他的归处不是雾海，而是辽阔的蓝天。",
          DialogueId = 51009368,
          GUID = "7FB25470",
          NextDialogue = 51009369,
          SpeakNpcId = 700247
        },
        [51009369] = {
          Content = "只要将花瓣撒向天空，他就能感受到我的思念。",
          DialogueId = 51009369,
          GUID = "7FB2549A",
          NextOptions = {
            [1] = 51009370,
            [2] = 51009371
          },
          SpeakNpcId = 700247
        },
        [51009370] = {
          Content = "如果他能收到你的花就好了。",
          DialogueId = 51009370,
          GUID = "7FB254C4",
          NextDialogue = 51009372
        },
        [51009371] = {
          Content = "他一定会收到你的花的。",
          DialogueId = 51009371,
          GUID = "7FB254EE",
          NextDialogue = 51009372
        },
        [51009372] = {
          Content = "嗯，谢谢你！",
          DialogueId = 51009372,
          GUID = "7FB25518",
          NextDialogue = 51009373,
          SpeakNpcId = 700247
        },
        [51009373] = {
          Content = "现在回想起来，他大概也早就知道我已经看穿了他的谎话吧。",
          DialogueId = 51009373,
          GUID = "7FB25542",
          NextDialogue = 51009374,
          SpeakNpcId = 700247
        },
        [51009374] = {
          Content = "一个由谎言编织的故事，最后有了一个用谎言写就的结局……不也算是恰如其分吗？",
          DialogueId = 51009374,
          GUID = "7FB2556C",
          NextDialogue = 51009375,
          SpeakNpcId = 700247
        },
        [51009375] = {
          Content = "好啦，我要趁天还没黑，去城外完成和他的约定。",
          DialogueId = 51009375,
          GUID = "7FB25596",
          NextDialogue = 51009376,
          SpeakNpcId = 700247
        },
        [51009376] = {
          Content = "再见了，可爱的小精灵。祝愿你的故事有一个真实而美满的结局。",
          DialogueId = 51009376,
          GUID = "7FB255C0",
          SpeakNpcId = 700247
        },
        [51009377] = {
          Content = "哎呀，小精灵，又见面了。今天的天色很美吧？",
          DialogueId = 51009377,
          GUID = "7FB255EA",
          SpeakNpcId = 700247
        },
        [51009401] = {
          Content = "请留步，{性别：尊贵的先生|美丽的女士}！",
          DialogueId = 51009401,
          GUID = "7FB259DA",
          NextDialogue = 51009402,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0033_story_humour\"}}",
          SpeakNpcId = 700306,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "700306:Talk01_Start"
          }
        },
        [51009402] = {
          Content = "哦，我该用什么形容你？",
          DialogueId = 51009402,
          GUID = "7FB25A04",
          NextDialogue = 51009403,
          SpeakNpcId = 700306,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009403] = {
          Content = "无言的狸猫为你吟唱诗篇，青绿的皓月将你镀上黄金。海兔为你的王冠镶上棕榈果做的宝石，而我在无人途径的垃圾桶旁歌颂你——",
          DialogueId = 51009403,
          GUID = "7FB25A2E",
          NextDialogue = 51009404,
          SpeakNpcId = 700306,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009404] = {
          Content = "无论我的赞美能否俘获您的垂眸，还请您……还请您……",
          DialogueId = 51009404,
          GUID = "7FB25A58",
          NextDialogue = 51009405,
          SpeakNpcId = 700306,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009405] = {
          Content = "噢！这幅非凡的仪表！您一定就是大名鼎鼎的狩月人{nickname}{性别：先生|小姐}吧！",
          DialogueId = 51009405,
          GUID = "7FB25A82",
          NextDialogue = 51009406,
          SpeakNpcId = 700306,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "700306:Talk01_End"
          }
        },
        [51009406] = {
          Content = "（我这么有名了吗？……不对，总觉得这句话后面不会接什么好事……）",
          DialogueId = 51009406,
          GUID = "7FB25AAC",
          NextDialogue = 51009407,
          SpeakNpcId = 100001
        },
        [51009407] = {
          Content = "初次见面，我叫费恩。老师已经等您很久了，请跟我来。",
          DialogueId = 51009407,
          GUID = "7FB25AD6",
          NextDialogue = 51009408,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0033_story_humour\"}}",
          SpeakNpcId = 700306,
          TalkActionId = {
            [1] = "700306:Talk02_Start"
          }
        },
        [51009408] = {
          Content = "老师？",
          DialogueId = 51009408,
          GUID = "7FB25B00",
          NextDialogue = 51009409,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700306:Talk02_End"
          }
        },
        [51009409] = {
          Content = "不……唉我怎么忘了老师不让我在公开场合这么叫她。不过如果是您的话应该没问题吧……还请您不要外传。",
          DialogueId = 51009409,
          GUID = "7FB25B2A",
          Scripts = "PlayOrStopBGM{_delay{8},PlayType{\"Stop\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0033_story_humour\"}}",
          SpeakNpcId = 700306
        },
        [51009410] = {
          Camera = "-401.135742,235.075195,139.57666,0.000003,-1.799823,-39.399132,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "老师，我把{nickname}{性别：先生|小姐}带来了。",
          DialogueId = 51009410,
          GUID = "7FB25B54",
          LookAt = {
            [1] = "700306:n(700300)"
          },
          NextDialogue = 51009411,
          SpeakNpcId = 700306
        },
        [51009411] = {
          Camera = "-398.734863,102.79834,140.336914,0.000002,-0.59967,-17.199116,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "你来了，年轻的狩月人。",
          DialogueId = 51009411,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB25B7E",
          LookAt = {
            [1] = "700306:n(100001)"
          },
          NextDialogue = 51009412,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51009412] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "呀，真是个可爱的孩子。你的容貌让我想起这座城市晶莹的初雪，还有那点缀于初雪之上，鸽血般的石榴石，多让人忍不住想要轻抚——",
          DialogueId = 51009412,
          GUID = "7FB25BA8",
          NextDialogue = 51009413,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain02_End"
          }
        },
        [51009413] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "等等，你不要过来——",
          DialogueId = 51009413,
          FacialId = {
            [1] = "100001:Shock01"
          },
          FinalCamera = "-93.166504,20.057129,149.304932,-1.999999,-3.400054,-165.189987,30.0,100000.0,true,DoNotOverride,2.8",
          GUID = "7FB25BD2",
          NextDialogue = 51009414,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Shock_Start"
          },
          ToFinalCameraBlendTime = 1
        },
        [51009414] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "呵呵，原来你不喜欢这样的亲密接触。失礼了，很抱歉用这种看起来很可疑的方式邀请你，请容许我先自我介绍一下。",
          DialogueId = 51009414,
          GUID = "7FB25BFC",
          NextDialogue = 51009415,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain01_Start"
          }
        },
        [51009415] = {
          Content = "我叫薇奥莱塔，一名歌剧演员。",
          DialogueId = 51009415,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB25C26",
          NextDialogue = 51009416,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain01_End"
          }
        },
        [51009416] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "（他们唱歌剧的说话怎么一个比一个怪啊！）",
          DialogueId = 51009416,
          GUID = "7FB25C50",
          NextDialogue = 51009417,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Shock_End"
          }
        },
        [51009417] = {
          Camera = "-142.214844,78.577148,148.40918,0.000003,-0.599971,-20.395008,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "如果你见过我，应该是在剧院里，或者是在附近的剧目海报上。",
          DialogueId = 51009417,
          GUID = "7FB25C7A",
          NextOptions = {
            [1] = 510093271,
            [2] = 510093272
          },
          SpeakNpcId = 700300
        },
        [51009418] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "我想起来了，“来自卢卡的梦幻之声，颠覆常识的百变容颜”，剧院的宣传标语好像是这么写的。",
          DialogueId = 51009418,
          FacialId = {
            [1] = "100001:Confident02"
          },
          GUID = "7FB25CA4",
          NextDialogue = 51009420,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Agree"
          }
        },
        [51009419] = {
          Camera = "-401.135742,235.075195,139.57666,0.000003,-1.799823,-39.399132,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "“来自卢卡的梦幻之声，颠覆常识的百变容颜”——薇奥莱塔老师是如今冰湖城炙手可热的歌者。如果您去盖雷亚剧院，就能看到画着老师肖像的大幅海报。",
          DialogueId = 51009419,
          GUID = "7FB25CCE",
          LookAt = {
            [1] = "100001:n(700306)"
          },
          NextDialogue = 51009420,
          SpeakNpcId = 700306,
          TalkActionId = {
            [1] = "700306:Talk01_Start"
          }
        },
        [51009420] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "原来他们是这样形容我的。虽然有些夸张，但是我喜欢。",
          DialogueId = 51009420,
          FacialId = {
            [1] = "700300:CM_Happy01"
          },
          GUID = "7FB25CF8",
          LookAt = {
            [1] = "100001:n(700300)"
          },
          NextDialogue = 51009421,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700306:Talk01_End",
            [2] = "700300:Confident_Start"
          }
        },
        [51009421] = {
          Content = "我喜欢看着人们为我的表演喝彩，喜欢听到他们在街头巷尾讨论某个唱段。",
          DialogueId = 51009421,
          GUID = "7FB25D22",
          NextDialogue = 51009422,
          SpeakNpcId = 700300
        },
        [51009422] = {
          Content = "每一次不同的舞台样貌，又或者是单纯突发奇想的临场发挥，都会在接下来的一个月占据所有的娱乐报刊——我很享受这样的感觉。",
          DialogueId = 51009422,
          GUID = "7FB25D4C",
          NextDialogue = 51009423,
          SpeakNpcId = 700300
        },
        [51009423] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "不好意思……所以委托的内容是？",
          DialogueId = 51009423,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB25D76",
          NextDialogue = 51009424,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51009424] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "啊呀，看来多余的话说的太多了。",
          DialogueId = 51009424,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB25DA0",
          NextDialogue = 51009425,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "100001:Talk01_End",
            [2] = "700300:Explain02_Start"
          }
        },
        [51009425] = {
          Camera = "-437.178223,124.364746,139.453369,0.000004,-1.399676,-18.998108,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "实际上，虽然我很享受站在所有人的视线中心，也已经习惯了这么做。不过有些特殊的情况还是很难应付……",
          DialogueId = 51009425,
          GUID = "7FB25DCA",
          NextDialogue = 51009426,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain02_End"
          }
        },
        [51009426] = {
          Content = "请你看看这个。",
          DialogueId = 51009426,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Letter.T_Guide_ChapterFire_Letter'}",
          GUID = "7FB25DF4",
          NextDialogue = 51009427,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Give"
          }
        },
        [51009427] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "一封情书？看内容像是薇奥莱塔女士的剧迷写的。",
          DialogueId = 51009427,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB25E1E",
          NextDialogue = 51009428,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009428] = {
          Camera = "-216.009766,106.786621,145.499023,0.000003,1.000056,-22.195528,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "太过受欢迎有时候也是一种烦恼，我理解大家对我的热情，虽然我没有办法接受他们的心意，但我也会尽量礼貌地回应。",
          DialogueId = 51009428,
          GUID = "7FB25E48",
          NextDialogue = 51009429,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Sigh_Start"
          }
        },
        [51009429] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "我曾不止一次收到过类似的信件，也都尽量给出了回复，不过这次……我收到了整整一箱。",
          DialogueId = 51009429,
          GUID = "7FB25E72",
          NextDialogue = 51009430,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Sigh_End"
          }
        },
        [51009430] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "这……这么多？！",
          DialogueId = 51009430,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "7FB25E9C",
          NextDialogue = 51009431,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Shock_Start"
          }
        },
        [51009431] = {
          Camera = "-437.178223,124.364746,139.453369,0.000004,-1.399676,-18.998108,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "嗯，而且都是同一个人寄来的。一开始是信箱，然后是马车里，再往后是门缝，窗台的花盆下……",
          DialogueId = 51009431,
          GUID = "7FB25EC6",
          NextDialogue = 51009432,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Talk01_Start",
            [2] = "100001:Shock_End"
          }
        },
        [51009432] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "几乎宅邸的每个角落都会在我不经意间塞满类似的信件。",
          DialogueId = 51009432,
          GUID = "7FB25EF0",
          NextDialogue = 51009433,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Talk01_End"
          }
        },
        [51009433] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "这件事是不是应该交给卫戍部队来处理？",
          DialogueId = 51009433,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "7FB25F1A",
          NextDialogue = 51009434,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          }
        },
        [51009434] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "我也在第一时间这样想过，可是作为万众瞩目的明星总会有这样或者那样的不便。",
          DialogueId = 51009434,
          GUID = "7FB25F44",
          NextDialogue = 51009435,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain01_Start"
          }
        },
        [51009435] = {
          Content = "也许一些小小的插曲会让我在茶余饭后的闲谈中占据更多的分量，不过作为一名演员，我还是希望大家对我的讨论尽量集中于舞台上的演绎，还望你能理解。",
          DialogueId = 51009435,
          GUID = "7FB25F6E",
          NextDialogue = 51009436,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain01_End"
          }
        },
        [51009436] = {
          Camera = "124.308105,149.785156,166.572021,0.000009,-4.799984,-153.390015,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "好吧，我明白了。对于送信的人，薇奥莱塔女士有什么线索吗？",
          DialogueId = 51009436,
          GUID = "7FB25F98",
          NextDialogue = 51009437,
          SpeakNpcId = 100001
        },
        [51009437] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "关于这个，刚才忘记说了。实际上我已经知道了送信人的住址，虽然是匿名信，但对方并没有隐瞒自己身份的意思。",
          DialogueId = 51009437,
          GUID = "7FB25FC2",
          NextDialogue = 51009438,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Confident_Start"
          }
        },
        [51009438] = {
          Content = "如果连求爱信都不得不隐藏自己的身份，那么这位可怜的先生又如何能够等来对方的回应呢？",
          DialogueId = 51009438,
          FacialId = {
            [1] = "700300:CM_Angry01"
          },
          GUID = "7FB25FEC",
          NextDialogue = 51009439,
          SpeakNpcId = 700300
        },
        [51009439] = {
          Camera = "-642.584961,260.924316,353.573975,0.000005,-21.200073,-26.393641,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "你只需要找到他，然后小小地“警告”一下就好。",
          DialogueId = 51009439,
          GUID = "7FB26016",
          NextOptions = {
            [1] = 510093491,
            [2] = 510093492
          },
          SpeakNpcId = 700300
        },
        [51009440] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "那就拜托你了。",
          DialogueId = 51009440,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB26040",
          NextDialogue = 51009444,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51009441] = {
          Camera = "-216.009766,106.786621,145.499023,0.000003,1.000056,-22.195528,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "你知道的，如果我给予这样的人太多的关注，就会让他误以为自己有资格吸引我的注意，并因此变本加厉。",
          DialogueId = 51009441,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2606A",
          NextDialogue = 51009442,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Disagree"
          }
        },
        [51009442] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "的确有点道理。",
          DialogueId = 51009442,
          FacialId = {
            [1] = "700300:CM_Idle"
          },
          GUID = "7FB26094",
          NextDialogue = 51009443,
          SpeakNpcId = 100001
        },
        [51009443] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "那就拜托你了。",
          DialogueId = 51009443,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB260BE",
          NextDialogue = 51009444,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51009444] = {
          Content = "哦，对了。我把这个交给你，应该会用得上。",
          DialogueId = 51009444,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon01.T_Guide_ChapterFire_Ribbon01'}",
          GUID = "7FB260E8",
          NextDialogue = 51009445,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Give"
          }
        },
        [51009445] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "这根发带……",
          DialogueId = 51009445,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "7FB26112",
          NextDialogue = 51009446,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009446] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "怎么了吗？",
          DialogueId = 51009446,
          GUID = "7FB2613C",
          NextDialogue = 51009447,
          SpeakNpcId = 700300
        },
        [51009447] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "不，没什么。我去去就回。",
          DialogueId = 51009447,
          FacialId = {
            [1] = "100001:Confident01"
          },
          GUID = "7FB26166",
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51009448] = {
          Camera = "695.307617,-554.236328,471.275024,0.000054,-20.794161,139.593384,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "薇奥莱塔女士说的地址就是这里，不过附近好像没什么住宅的样子。",
          DialogueId = 51009448,
          GUID = "7FB26190",
          NextDialogue = 51009449,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700313:Think_Start"
          }
        },
        [51009449] = {
          Content = "旁边有个卫兵，过去打听一下吧。",
          DialogueId = 51009449,
          GUID = "7FB261BA",
          NextDialogue = 51009450,
          SpeakNpcId = 100001
        },
        [51009450] = {
          Camera = "232.955078,593.629395,162.682861,0.000058,-3.794279,-115.003006,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "你好，我想和你打听点事情。",
          DialogueId = 51009450,
          GUID = "7FB261E4",
          NextDialogue = 51009451,
          Scripts = "MoveTo{ActorId{100001},TargetPoint{\"Questpoint_Nvzhu_20023002\"},MoveSpeed{150},Visibility{\"Show\"}}",
          SpeakNpcId = 100001
        },
        [51009451] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "我在忙，等我有空再说吧。奇怪，这里应该是这样啊……这唱机怎么了……",
          DialogueId = 51009451,
          GUID = "7FB2620E",
          NextDialogue = 51009452,
          SpeakNpcId = 700313
        },
        [51009452] = {
          Camera = "408.029297,-87.160217,216.346191,0.000075,-13.994142,150.79335,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "（男人焦头烂额地摆弄着地上的一台旧唱机。）",
          DialogueId = 51009452,
          GUID = "7FB26238",
          NextDialogue = 51009453
        },
        [51009453] = {
          Content = "它坏掉了吗？",
          DialogueId = 51009453,
          GUID = "7FB26262",
          NextDialogue = 51009454,
          SpeakNpcId = 100001
        },
        [51009454] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "应该也不算坏掉……但有些年头了，偶尔会失灵。我明明记得这么来一下就行啊……",
          DialogueId = 51009454,
          GUID = "7FB2628C",
          NextOptions = {
            [1] = 510093641
          },
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "700313:Talk01_Start"
          }
        },
        [51009455] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "你会折腾这东西？那这样，如果你能帮我修好我一定知无不言。",
          DialogueId = 51009455,
          GUID = "7FB262B6",
          NextDialogue = 51009456,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "700313:Talk01_End"
          }
        },
        [51009456] = {
          Camera = "96.858398,213.679291,148.014893,0.00006,-3.794279,-114.800949,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "一言为定。",
          DialogueId = 51009456,
          FacialId = {
            [1] = "100001:Confident02"
          },
          GUID = "7FB262E0",
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start",
            [2] = "700313:Talk01_End"
          }
        },
        [51009457] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "这样应该就可以了。",
          DialogueId = 51009457,
          FacialId = {
            [1] = "100001:Ahaha02"
          },
          GUID = "7FB2630A",
          NextDialogue = 51009458,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51009458] = {
          Camera = "490.863281,-71.149292,246.487061,0.000077,-14.394158,157.593735,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "有两下子啊，这样总算能听我的录音带了。啊，薇奥莱塔女士的歌喉——",
          DialogueId = 51009458,
          GUID = "7FB26334",
          NextDialogue = 51009459,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "100001:Talk01_End",
            [2] = "700313:Shock_Start"
          }
        },
        [51009459] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "你知道薇奥莱塔？",
          DialogueId = 51009459,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2635E",
          NextDialogue = 51009460,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start",
            [2] = "700313:Shock_End"
          }
        },
        [51009460] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "这冰湖城有谁不知道吗？她的首部唱片都已经炒到了天价，我攒了三个月的薪水还买不起！唉，只能先听便宜录音带解解馋。",
          DialogueId = 51009460,
          GUID = "7FB26388",
          NextDialogue = 51009461,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "700313:Confident_Start"
          }
        },
        [51009461] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "那就好说了，我要问的事刚好和薇奥莱塔女士有关。",
          DialogueId = 51009461,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB263B2",
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009462] = {
          Content = "（再三叮嘱对方务必保密后，向卫兵大概说明了薇奥莱塔女士遭遇骚扰的事。）",
          DialogueId = 51009462,
          GUID = "7FB263DC"
        },
        [51009463] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "什么？居然有这种事？！这真的是太不成体统了！如果犯人真的住在这片街区，我一定帮你把他揪出来好好教训一顿！",
          DialogueId = 51009463,
          GUID = "7FB26406",
          NextDialogue = 51009464,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "700313:Angry01_Start"
          }
        },
        [51009464] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "倒也不用这么夸张……",
          DialogueId = 51009464,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB26430",
          NextDialogue = 51009465,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:ScratchHead_Start"
          }
        },
        [51009465] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "怎么就夸张了？我生平最见不得这种危害社会治安的败类，你放心，这一带的住户我都或多或少打过交道，只要有点线索我一定能把犯人抓到！",
          DialogueId = 51009465,
          GUID = "7FB2645A",
          NextDialogue = 51009466,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "100001:ScratchHead_End",
            [2] = "700313:Confident_Start"
          }
        },
        [51009466] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "线索的话……这封信你有什么头绪吗？",
          DialogueId = 51009466,
          GUID = "7FB26484",
          NextDialogue = 51009467,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Give"
          }
        },
        [51009467] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "什么信？我看看。",
          DialogueId = 51009467,
          GUID = "7FB264AE",
          NextDialogue = 51009468,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "700313:Confident_End"
          }
        },
        [51009468] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "…………",
          DialogueId = 51009468,
          FinalCamera = "28.276367,114.675842,163.198242,0.000057,-8.794093,105.195099,12.0,100000.0,true,DoNotOverride,2.8",
          GUID = "7FB264D8",
          NextDialogue = 51009469,
          SpeakNpcId = 700313,
          ToFinalCameraBlendTime = 1
        },
        [51009469] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "…………",
          DialogueId = 51009469,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB26502",
          NextDialogue = 51009470,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          }
        },
        [51009470] = {
          Content = "怎么了，你为什么不说话？",
          DialogueId = 51009470,
          GUID = "7FB2652C",
          NextDialogue = 51009471,
          SpeakNpcId = 100001
        },
        [51009471] = {
          Camera = "28.276367,114.675842,163.198242,0.000057,-8.794093,105.195099,12.0,100000.0,true,DoNotOverride,2.8",
          Content = "这……这对吗？这不对吧？我觉得这封信言辞恳切情感真挚，和骚扰信天差地别。",
          DialogueId = 51009471,
          GUID = "7FB26556",
          NextDialogue = 51009472,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "700313:Talk01_Start"
          }
        },
        [51009472] = {
          Camera = "224.37207,502.975342,173.965332,0.000078,-3.594175,-121.197639,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "看来寄信的人已经找到了。刚才好像有人说要把犯人好好教训一顿？",
          DialogueId = 51009472,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB26580",
          NextDialogue = 51009473,
          SpeakNpcId = 100001
        },
        [51009473] = {
          Camera = "28.276367,114.675842,163.198242,0.000057,-8.794093,105.195099,12.0,100000.0,true,DoNotOverride,2.8",
          Content = "这是误会，一定是误会。我发誓我对薇奥莱塔女士一片真心——不是说薇奥莱塔女士最喜欢热情洋溢的表白吗？她怎么会说那是骚扰啊？",
          DialogueId = 51009473,
          GUID = "7FB265AA",
          NextDialogue = 51009474,
          SpeakNpcId = 700313
        },
        [51009474] = {
          Content = "……难道是<H>那家伙在骗我</>……",
          DialogueId = 51009474,
          GUID = "7FB265D4",
          NextDialogue = 51009475,
          SpeakNpcId = 700313
        },
        [51009475] = {
          Content = "等一下，我明白了！是你！你根本不是薇奥莱塔女士派来的，你是来拆散我们的！",
          DialogueId = 51009475,
          GUID = "7FB265FE",
          NextDialogue = 51009476,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "700313:Angry01_Start"
          }
        },
        [51009476] = {
          Content = "你有什么证据证明是薇奥莱塔女士让你来的？依我看你就是在挑拨离间！",
          DialogueId = 51009476,
          GUID = "7FB26628",
          NextDialogue = 51009477,
          SpeakNpcId = 700313
        },
        [51009477] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "居然试图用这样的手段来破坏薇奥莱塔女士和追随者之间的信任，我必须要好好教训一下你！",
          DialogueId = 51009477,
          GUID = "7FB26652",
          NextDialogue = 51009478,
          SpeakNpcId = 700313
        },
        [51009478] = {
          Camera = "92.173828,227.503815,153.63623,0.000067,-3.594264,-113.599007,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "你这人怎么……",
          DialogueId = 51009478,
          GUID = "7FB2667C",
          NextDialogue = 51009479,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk03_End"
          }
        },
        [51009479] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "（还是先想办法让这个自说自话的家伙冷静一下吧。）",
          DialogueId = 51009479,
          GUID = "7FB266A6",
          SpeakNpcId = 100001
        },
        [51009480] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "薇奥莱塔女士，是我……是我太弱小……",
          DialogueId = 51009480,
          GUID = "7FB266D0",
          NextDialogue = 51009481,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "700313:Stop01_Start"
          }
        },
        [51009481] = {
          Camera = "172.162109,534.255371,170.810547,0.000068,-3.594264,-113.598976,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "闹够了？看看这个吧。",
          DialogueId = 51009481,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon01.T_Guide_ChapterFire_Ribbon01'}",
          FacialId = {
            [1] = "100001:Angry01"
          },
          GUID = "7FB266FA",
          NextDialogue = 51009482,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Give",
            [2] = "700313:Stop01_End"
          }
        },
        [51009482] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "这是，薇奥莱塔女士的缎带？她从十多年前第一次公开演出开始就一直带着的……",
          DialogueId = 51009482,
          GUID = "7FB26724",
          NextDialogue = 51009483,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "700313:Shock_Start"
          }
        },
        [51009483] = {
          Camera = "92.173828,227.503815,153.63623,0.000067,-3.594264,-113.599007,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "这也能认出来？",
          DialogueId = 51009483,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "7FB2674E",
          NextDialogue = 51009484,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Disagree"
          }
        },
        [51009484] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "怎么可能认不出来！我跟你说这些干吗……",
          DialogueId = 51009484,
          GUID = "7FB26778",
          NextDialogue = 51009485,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "700313:Shock_End"
          }
        },
        [51009485] = {
          Content = "既然你拿着这个，那看来我是真的被拒绝了。我不会再去骚扰薇奥莱塔女士了，祝你们幸福。",
          DialogueId = 51009485,
          GUID = "7FB267A2",
          NextOptions = {
            [1] = 510093951,
            [2] = 510093952
          },
          SpeakNpcId = 700313
        },
        [51009486] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "不要再说了，就让一颗炽烈的心在角落默默哭泣吧！",
          DialogueId = 51009486,
          GUID = "7FB267CC",
          NextDialogue = 51009487,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "700313:Stop01_Start"
          }
        },
        [51009487] = {
          Camera = "92.173828,227.503815,153.63623,0.000067,-3.594264,-113.599007,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "（卫兵不再回答，只是一味流泪……还是让他自己安静一会儿吧。）",
          DialogueId = 51009487,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB267F6",
          SpeakNpcId = 100001
        },
        [51009488] = {
          Camera = "154.741699,155.880859,184.548828,0.000014,-8.400074,-153.591629,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "薇奥莱塔女士，我回来了。",
          DialogueId = 51009488,
          GUID = "7FB26820",
          NextDialogue = 51009489,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009489] = {
          Camera = "-225.489746,72.248535,138.279785,0.000003,0.400024,-11.196657,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "辛苦你了，看起来问题已经解决了。",
          DialogueId = 51009489,
          FacialId = {
            [1] = "700300:CM_Happy01"
          },
          GUID = "7FB2684A",
          NextDialogue = 51009490,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "700300:Talk02_Start"
          }
        },
        [51009490] = {
          Camera = "154.741699,155.880859,184.548828,0.000014,-8.400074,-153.591629,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "嗯，他不会再来骚扰你了。这条缎带也还给你，如果没有它，恐怕还要再被纠缠一段时间。",
          DialogueId = 51009490,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon01.T_Guide_ChapterFire_Ribbon01'}",
          FacialId = {
            [1] = "100001:Confident01"
          },
          GUID = "7FB26874",
          NextDialogue = 51009491,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700300:Talk02_End",
            [2] = "100001:Give"
          }
        },
        [51009491] = {
          Content = "听说这条缎带，你从十几年前就一直戴着？",
          DialogueId = 51009491,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2689E",
          NextDialogue = 51009492,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009492] = {
          Camera = "-225.489746,72.248535,138.279785,0.000003,0.400024,-11.196719,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "是的，这是一位友人留给我的纪念，她才华横溢，但却不受命运垂怜……",
          DialogueId = 51009492,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB268C8",
          NextDialogue = 51009493,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "700300:Sigh_Start"
          }
        },
        [51009493] = {
          Content = "出于某些原因，她无法实现自己的梦想了，不过我可以，所以我希望能够让她也一起在舞台上闪耀。",
          DialogueId = 51009493,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB268F2",
          NextDialogue = 51009494,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Sigh_End"
          }
        },
        [51009494] = {
          Content = "所以在我第一次公演的时候，我亲自设计了一张海报，在黑白的画面里，只有一抹紫色格外亮眼——",
          DialogueId = 51009494,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2691C",
          NextDialogue = 51009495,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Talk02_Start"
          }
        },
        [51009495] = {
          Content = "你应该听说过“千面的薇奥莱塔”这个称呼，我有着足以让自己变成另一个人的化妆技术，在每场演出都会根据角色用不同的容貌登台。",
          DialogueId = 51009495,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB26946",
          NextDialogue = 51009496,
          SpeakNpcId = 700300
        },
        [51009496] = {
          Content = "但唯独这条缎带，我每次都会戴上。久而久之，<H>它也就成了我独有的标志</>。",
          DialogueId = 51009496,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB26970",
          NextDialogue = 51009497,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Talk02_End"
          }
        },
        [51009497] = {
          Camera = "6.950195,47.361328,152.822266,0.000007,-4.600037,-165.990051,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "原来如此……",
          DialogueId = 51009497,
          FacialId = {
            [1] = "100001:Unhappy02"
          },
          GUID = "7FB2699A",
          NextDialogue = 51009498,
          SpeakNpcId = 100001
        },
        [51009498] = {
          Content = "老师！",
          DialogueId = 51009498,
          GUID = "7FB269C4",
          LookAt = {
            [1] = "100001:n(700306)",
            [2] = "700300:n(700306)"
          },
          NextDialogue = 51009499,
          SpeakNpcId = 700306
        },
        [51009499] = {
          Camera = "-225.489746,72.248535,138.279785,0.000003,0.400024,-11.196657,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "费恩，我应该教过你不要大呼小叫。",
          DialogueId = 51009499,
          FacialId = {
            [1] = "700300:CM_Angry01"
          },
          GUID = "7FB269EE",
          NextDialogue = 51009500,
