          }
        },
        [51009644] = {
          Camera = "704.804688,1549.59082,762.798828,0.000162,-10.801759,-103.40123,25.0,100000.0,true,DoNotOverride,2.8",
          Content = "这里真是比我想象中还要破败……",
          DialogueId = 51009644,
          FinalCamera = "704.804688,1549.59082,762.798828,0.000163,-10.801759,-103.401352,30.0,100000.0,true,DoNotOverride,2.8",
          GUID = "7FB281B8",
          NextDialogue = 51009645,
          SpeakNpcId = 700301,
          ToFinalCameraBlendTime = 5
        },
        [51009645] = {
          Camera = "949.248047,585.90332,736.995117,0.000167,0.198089,-138.598633,30.0,100000.0,true,DoNotOverride,2.8",
          Content = "这大门也落了锁。还好，这边的管道还能过人……",
          DialogueId = 51009645,
          GUID = "7FB281E2",
          SpeakNpcId = 700301
        },
        [51009646] = {
          Content = "咳……咳、咳……",
          DialogueId = 51009646,
          GUID = "7FB2820C",
          NextDialogue = 51009647,
          SpeakNpcId = 700301
        },
        [51009647] = {
          Content = "你还好吗？",
          DialogueId = 51009647,
          GUID = "7FB28236",
          NextDialogue = 51009648,
          SpeakNpcId = 100001
        },
        [51009648] = {
          Content = "我没……咳、咳，没事……我们继续往前走吧，我要找的地方离这里不远了。",
          DialogueId = 51009648,
          GUID = "7FB28260",
          NextDialogue = 51009649,
          SpeakNpcId = 700301
        },
        [51009649] = {
          Content = "你对这里好像很熟悉？",
          DialogueId = 51009649,
          GUID = "7FB2828A",
          NextDialogue = 51009650,
          SpeakNpcId = 100001
        },
        [51009650] = {
          Content = "是啊……我曾经是这里的矿工。十六年前，这里就是我每天工作都要经过的地方。",
          DialogueId = 51009650,
          GUID = "7FB282B4",
          NextDialogue = 51009651,
          SpeakNpcId = 700301
        },
        [51009651] = {
          Content = "那时候，我们一天要在这里待上十多个小时，角角落落的路，就算闭上眼睛也不会走错。",
          DialogueId = 51009651,
          GUID = "7FB282DE",
          SpeakNpcId = 700301
        },
        [51009652] = {
          Content = "糟糕，怎么被秽兽围着……",
          DialogueId = 51009652,
          GUID = "7FB28308",
          SpeakNpcId = 700301
        },
        [51009653] = {
          Camera = "-273.187012,-303.795898,131.41748,0.000022,-13.001005,53.600559,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "还好，看起来没被弄坏……多谢你，年轻人。",
          DialogueId = 51009653,
          GUID = "7FB28332",
          NextDialogue = 51009654,
          SpeakNpcId = 700301
        },
        [51009654] = {
          Camera = "-273.187012,-303.795898,131.41748,0.000022,-13.001005,53.600559,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "西格，老朋友，我来看你了……",
          DialogueId = 51009654,
          FinalCamera = "-61.812988,-45.275879,85.529785,0.000021,-12.800989,58.799252,35.0,100000.0,true,DoNotOverride,2.8",
          GUID = "7FB2835C",
          NextDialogue = 51009655,
          SpeakNpcId = 700301,
          ToFinalCameraBlendTime = 5
        },
        [51009655] = {
          Content = "这是……墓碑？",
          DialogueId = 51009655,
          GUID = "7FB28386",
          NextDialogue = 51009656,
          SpeakNpcId = 100001
        },
        [51009656] = {
          Content = "看起来很不像样对吧？",
          DialogueId = 51009656,
          GUID = "7FB283B0",
          NextDialogue = 51009657,
          SpeakNpcId = 700301
        },
        [51009657] = {
          Camera = "391.647461,354.068359,51.502441,0.000019,-5.200888,-159.003296,40.0,565.324158,true,Manual,2.8",
          Content = "明明口口声声说是他最好的兄弟，却只能把他埋葬在这么个窝囊的地方。",
          DialogueId = 51009657,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB283DA",
          NextDialogue = 51009658,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009658] = {
          Content = "等等，这是……不，为什么？",
          DialogueId = 51009658,
          FacialId = {
            [1] = "700301:CM_Shock01"
          },
          GUID = "7FB28404",
          NextDialogue = 51009659,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Shock_Start"
          }
        },
        [51009659] = {
          Content = "（病重之人寂如死灰的脸突然青筋暴起——惊讶、不解与悲哀同时凝固在他脸上。你顺着他的视线看去，只看到一条紫罗兰色的缎带静静地躺在墓碑旁。）",
          DialogueId = 51009659,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon02.T_Guide_ChapterFire_Ribbon02'}",
          GUID = "7FB2842E",
          NextDialogue = 51009660
        },
        [51009660] = {
          Camera = "-61.812988,-45.275879,85.529785,0.000021,-12.800989,58.799252,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "维尔莉特，为什么你会回来？",
          DialogueId = 51009660,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB28458",
          NextDialogue = 51009661,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Sigh_Start"
          },
          TurnTo = {
            [1] = "100001:n(700301)"
          }
        },
        [51009661] = {
          Camera = "-160.715332,330.500977,58.830566,0.00003,-6.800997,-43.798355,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "维尔莉特……是谁？",
          DialogueId = 51009661,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB28482",
          NextDialogue = 51009662,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009662] = {
          Camera = "201.632812,149.822754,39.556641,0.000044,-1.60086,173.405228,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "唉……年轻人，你愿意听我讲一些陈年旧事吗？",
          DialogueId = 51009662,
          GUID = "7FB284AC",
          NextDialogue = 51009663,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Sigh_End",
            [2] = "100001:Talk02_End"
          },
          TurnTo = {
            [1] = "700301:n(100001)"
          }
        },
        [51009663] = {
          Camera = "-160.715332,330.500977,58.830566,0.00003,-6.800997,-43.798355,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "好，不过我们先回去好吗，拉斯应该已经等急了。",
          DialogueId = 51009663,
          GUID = "7FB284D6",
          NextDialogue = 51009664,
          SpeakNpcId = 100001
        },
        [51009664] = {
          Camera = "201.632812,149.822754,39.556641,0.000044,-1.60086,173.405228,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "好，好……回去吧。",
          DialogueId = 51009664,
          GUID = "7FB28500",
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009665] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "多纳特大叔，你可算回来了！",
          DialogueId = 51009665,
          GUID = "7FB2852A",
          NextDialogue = 51009666,
          SpeakNpcId = 700303,
          TurnTo = {
            [1] = "700303:n(700301)",
            [2] = "700301:n(700303)",
            [3] = "100001:n(700303)"
          }
        },
        [51009666] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,true,DoNotOverride,2.8",
          Content = "抱歉，孩子，让你担心了——咳……咳咳……",
          DialogueId = 51009666,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB28554",
          NextDialogue = 51009667,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009667] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "大叔，你又发病了！我带你去找医生。",
          DialogueId = 51009667,
          GUID = "7FB2857E",
          NextDialogue = 51009668,
          SpeakNpcId = 700303,
          TalkActionId = {
            [1] = "700303:Talk02_Start"
          }
        },
        [51009668] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,true,DoNotOverride,2.8",
          Content = "不，不用了……这是我的报应，治不了的。",
          DialogueId = 51009668,
          GUID = "7FB285A8",
          NextDialogue = 51009669,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0036_story_renweidaozu\"}}",
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700303:Talk02_End"
          }
        },
        [51009669] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "大叔，你怎么又在说这种话了——",
          DialogueId = 51009669,
          GUID = "7FB285D2",
          NextDialogue = 51009670,
          SpeakNpcId = 700303,
          TalkActionId = {
            [1] = "700303:Confident_Start"
          }
        },
        [51009670] = {
          Content = "你忘了吗？有个冬天特别特别冷，我只能去工厂排废气的管道那里蹲着，这样就能暖和一些。大叔你也冻得打哆嗦，却把唯一一件厚棉衣给了我。",
          DialogueId = 51009670,
          GUID = "7FB285FC",
          NextDialogue = 51009671,
          SpeakNpcId = 700303
        },
        [51009671] = {
          Content = "整条街都知道大叔是多好的人！为什么你总是把“报应”这种难听话挂在嘴边呢？",
          DialogueId = 51009671,
          GUID = "7FB28626",
          LookAt = {
            [1] = "100001:n(700301)"
          },
          NextDialogue = 51009672,
          SpeakNpcId = 700303
        },
        [51009672] = {
          Camera = "-115.218262,-202.711914,123.809082,0.000057,-5.200553,24.798326,30.0,100000.0,true,DoNotOverride,2.8",
          Content = "……难道和你说的“往事”有关？",
          DialogueId = 51009672,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB28650",
          LookAt = {
            [1] = "700301:n(100001)"
          },
          NextDialogue = 51009673,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "700301:Explain02_End"
          }
        },
        [51009673] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,true,DoNotOverride,2.8",
          Content = "嗯，那是十六年前……",
          DialogueId = 51009673,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB2867A",
          NextDialogue = 51009674,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Talk02_Start",
            [2] = "700303:Confident_End"
          }
        },
        [51009674] = {
          Camera = "51.153076,68.407227,128.048828,0.000057,-5.000518,-77.201683,30.0,100000.0,true,DoNotOverride,2.8",
          Content = "就和我的每一段无聊至极的人生经历一样，当矿工的那些年算不上好，但也不算太坏。每天有恰好做到精疲力尽的工作，也能换取让一家人吃饱的面包。",
          DialogueId = 51009674,
          GUID = "7FB286A4",
          NextDialogue = 51009675,
          SpeakNpcId = 700301
        },
        [51009675] = {
          Content = "现在想想，虽然那些大人物从来没有给予我们公正的对待，但那时候反而是我这一生最无忧无虑的日子……",
          DialogueId = 51009675,
          GUID = "7FB286CE",
          NextDialogue = 51009676,
          SpeakNpcId = 700301
        },
        [51009676] = {
          Camera = "-21.725342,235.385742,212.564453,0.000078,-22.799852,-68.394066,20.0,100000.0,true,DoNotOverride,2.8",
          Content = "可我的朋友西格，他就没有那么幸运了。病痛无端地降临到他唯一的家人——他的妹妹，维尔莉特身上，可怜那女孩才只有十八岁。",
          DialogueId = 51009676,
          GUID = "7FB286F8",
          NextDialogue = 51009677,
          SpeakNpcId = 700301
        },
        [51009677] = {
          Content = "而当你觉得遇到很糟糕的事时，情况往往会变得更糟。",
          DialogueId = 51009677,
          GUID = "7FB28722",
          NextDialogue = 51009678,
          SpeakNpcId = 700301
        },
        [51009678] = {
          Content = "格雷姆矿场运出来的月石变得一天比一天少，拿在手里的薪水也越来越微薄。渐渐地，面包从白面包变成黑面包，到后来连黑面包都混着麸皮和木屑。",
          DialogueId = 51009678,
          GUID = "7FB2874C",
          NextDialogue = 51009679,
          SpeakNpcId = 700301
        },
        [51009679] = {
          Content = "维尔莉特的病，对于报酬只能勉强活命的西格来说，无异于亲耳听到对亲人宣告死刑。",
          DialogueId = 51009679,
          GUID = "7FB28776",
          NextDialogue = 51009680,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Talk02_End"
          }
        },
        [51009680] = {
          Content = "我还记得那个凌晨，西格向工友讨了很多暖身的廉价烈酒，我们就这样坐在格雷姆矿场前的石头上，一瓶一瓶地往身子里灌。",
          DialogueId = 51009680,
          GUID = "7FB287A0",
          NextDialogue = 51009681,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Talk01_Start"
          }
        },
        [51009681] = {
          Content = "他一边不像样地哭，一边回忆和妹妹相依为命的往事。他时而学着维尔莉特的样子唱起歌，时而低低咒骂着法布瑞斯·鲁斯福德。",
          DialogueId = 51009681,
          GUID = "7FB287CA",
          NextDialogue = 51009682,
          SpeakNpcId = 700301
        },
        [51009682] = {
          Camera = "-115.218262,-202.711914,123.809082,0.000057,-5.200553,24.798326,30.0,100000.0,true,DoNotOverride,2.8",
          Content = "法布瑞斯·鲁斯福德是谁？",
          DialogueId = 51009682,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB287F4",
          NextDialogue = 51009683,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk03_Start",
            [2] = "700301:Talk01_End"
          }
        },
        [51009683] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,true,DoNotOverride,2.8",
          Content = "工程炼金院的长官，当时格雷姆矿场的负责人。",
          DialogueId = 51009683,
          GUID = "7FB2881E",
          NextDialogue = 51009684,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Talk02_Start"
          }
        },
        [51009684] = {
          Content = "我拍着西格的肩膀和他说，“骂他有什么用，还不是咱们没本事。你要是真有能耐，怎么不绑了他，干票大的？”",
          DialogueId = 51009684,
          GUID = "7FB28848",
          NextDialogue = 51009685,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Talk02_End"
          }
        },
        [51009685] = {
          Content = "……这十六年里，我无时无刻不在质问自己，如果那天我没有喝多酒，没有说出那些轻佻的昏话，一切悲剧是不是都不会发生。",
          DialogueId = 51009685,
          GUID = "7FB28872",
          NextDialogue = 51009686,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009686] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "难道，那位西格叔叔真的……",
          DialogueId = 51009686,
          GUID = "7FB2889C",
          NextDialogue = 51009687,
          SpeakNpcId = 700303,
          TalkActionId = {
            [1] = "700301:Explain02_End"
          },
          TurnTo = {
            [1] = "700301:n(700303)"
          }
        },
        [51009687] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,true,DoNotOverride,2.8",
          Content = "是的。某一天，西格突然辞去了矿场的工作，我去他家找他，却发现他和维尔莉特都已经不在那里了。",
          DialogueId = 51009687,
          GUID = "7FB288C6",
          NextDialogue = 51009688,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Agree"
          }
        },
        [51009688] = {
          Content = "起初我以为他是带着维尔莉特离开了冰湖城，去其他地方求医……可一周后，我却收到了维尔莉特的来信。",
          DialogueId = 51009688,
          GUID = "7FB288F0",
          NextDialogue = 51009689,
          SpeakNpcId = 700301
        },
        [51009689] = {
          Content = "虽然我和西格是好兄弟，但从我认识西格起，维尔莉特就常常卧病在床，所以我和她也没见过几面。信是她用仅剩的铜币拜托一位过路的狩月人送到矿场的。",
          DialogueId = 51009689,
          GUID = "7FB2891A",
          NextDialogue = 51009690,
          SpeakNpcId = 700301
        },
        [51009690] = {
          Camera = "-21.725342,235.385742,212.564453,0.000078,-22.799852,-68.394066,20.0,100000.0,true,DoNotOverride,2.8",
          Content = "信上说，西格绑架了长官的女儿，希望讨要一笔赎金。维尔莉特请求我阻止他，不要让他一错再错。",
          DialogueId = 51009690,
          GUID = "7FB28944",
          NextDialogue = 51009691,
          SpeakNpcId = 700301
        },
        [51009691] = {
          Content = "他把那个女孩关在了城郊的一栋老房子里，当我找到那里时他非常震惊，但还是承认了自己的所作所为。",
          DialogueId = 51009691,
          GUID = "7FB2896E",
          NextDialogue = 51009692,
          SpeakNpcId = 700301
        },
        [51009692] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,true,DoNotOverride,2.8",
          Content = "我意识到正是我那晚的胡话打开了罪恶的匣子，我后悔极了。我本想劝阻他，但看到虚弱到已经说不出来话的维尔莉特，我还是犹豫了……",
          DialogueId = 51009692,
          GUID = "7FB28998",
          NextDialogue = 51009693,
          SpeakNpcId = 700301
        },
        [51009693] = {
          Content = "西格让我就当这件事情没有发生过，但随着排查越来越严格，我一想到这件事就会害怕到颤抖不止。",
          DialogueId = 51009693,
          GUID = "7FB289C2",
          NextDialogue = 51009694,
          SpeakNpcId = 700301
        },
        [51009694] = {
          Content = "最后……最后……",
          DialogueId = 51009694,
          GUID = "7FB289EC",
          NextDialogue = 51009695,
          SpeakNpcId = 700301
        },
        [51009695] = {
          Camera = "-115.218262,-202.711914,123.809082,0.000057,-5.200553,24.798326,30.0,100000.0,true,DoNotOverride,2.8",
          Content = "你……揭发了他们？",
          DialogueId = 51009695,
          GUID = "7FB28A16",
          NextDialogue = 51009696,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          TurnTo = {
            [1] = "700301:n(100001)"
          }
        },
        [51009696] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,true,DoNotOverride,2.8",
          Content = "我不该这么做，我不该这么做啊！",
          DialogueId = 51009696,
          GUID = "7FB28A40",
          NextDialogue = 51009697,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Sigh_Start"
          }
        },
        [51009697] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "后来呢，后来他们怎么样了？",
          DialogueId = 51009697,
          GUID = "7FB28A6A",
          LookAt = {
            [1] = "700301:n(700303)"
          },
          NextDialogue = 51009698,
          SpeakNpcId = 700303,
          TalkActionId = {
            [1] = "700301:Sigh_End"
          }
        },
        [51009698] = {
          Camera = "-21.725342,235.385742,212.564453,0.000078,-22.799852,-68.394066,20.0,100000.0,true,DoNotOverride,2.8",
          Content = "军团的长官亲自带人来抓捕西格，西格在抵抗的时候不慎点燃了屋子。",
          DialogueId = 51009698,
          GUID = "7FB28A94",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023101.T_Story_Recall_20023101'",
          NextDialogue = 51009699,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009699] = {
          Content = "我冲进去想要救人，但最后却只在混乱中救出了维尔莉特。她是那样害怕，整张脸都被熏成煤黑，只有眼窝被止不住的泪水冲出两道泪痕。",
          DialogueId = 51009699,
          GUID = "7FB28ABE",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023101.T_Story_Recall_20023101'",
          NextDialogue = 51009700,
          SpeakNpcId = 700301
        },
        [51009700] = {
          Content = "我怕维尔莉特被她哥哥牵连，就把她藏在运水的桶里，瞒过了军团的视线。",
          DialogueId = 51009700,
          GUID = "7FB28AE8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023101.T_Story_Recall_20023101'",
          NextDialogue = 51009701,
          SpeakNpcId = 700301
        },
        [51009701] = {
          Content = "最后，西格被军团的人抓到，而那位长官的女儿……大家只在废墟中找到她烧成焦炭的遗体。",
          DialogueId = 51009701,
          GUID = "7FB28B12",
          NextDialogue = 51009702,
          SpeakNpcId = 700301
        },
        [51009702] = {
          Content = "在那之后，愤怒的长官直接绕过审判流程，亲自将西格处决。而维尔莉特……我把检举的赏金都给了她，趁乱把她送出了冰湖城，希望她不要被牵连……",
          DialogueId = 51009702,
          GUID = "7FB28B3C",
          NextDialogue = 51009703,
          SpeakNpcId = 700301
        },
        [51009703] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,true,DoNotOverride,2.8",
          Content = "我至今还能想起我送她离开时，她那副憔悴但又愤怒的表情，她当时戴着的，就是这条紫罗兰色的缎带……",
          DialogueId = 51009703,
          GUID = "7FB28B66",
          NextDialogue = 51009704,
          SpeakNpcId = 700301
        },
        [51009704] = {
          Content = "她说她会永远离开冰湖城，永远不想再见到我。",
          DialogueId = 51009704,
          GUID = "7FB28B90",
          NextDialogue = 51009705,
          SpeakNpcId = 700301
        },
        [51009705] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,true,DoNotOverride,2.8",
          Content = "是啊……谁会想见到祸从口出导致朋友铤而走险，后来又因为一时胆怯害死两条人命的懦夫呢？",
          DialogueId = 51009705,
          FinalCamera = "-115.218262,-202.711914,123.809082,0.000057,-5.200553,24.798326,30.0,100000.0,true,DoNotOverride,2.8",
          GUID = "7FB28BBA",
          LookAt = {
            [1] = "700301:n(100001)"
          },
          NextOptions = {
            [1] = 510095461,
            [2] = 510095462
          },
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Explain02_End"
          }
        },
        [51009706] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,true,DoNotOverride,2.8",
          Content = "你说得不错。",
          DialogueId = 51009706,
          GUID = "7FB28BE4",
          NextDialogue = 51009709,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Agree"
          }
        },
        [51009707] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "对啊，多纳特大叔，你只是做了你该做的事！",
          DialogueId = 51009707,
          GUID = "7FB28C0E",
          NextDialogue = 51009708,
          SpeakNpcId = 700303,
          TalkActionId = {
            [1] = "700303:Angry01_Start"
          }
        },
        [51009708] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,true,DoNotOverride,2.8",
          Content = "我曾经听到很多人这么说……但这无法改变有两个原本无辜的生命因我而死。",
          DialogueId = 51009708,
          GUID = "7FB28C38",
          NextDialogue = 51009709,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Disagree",
            [2] = "700303:Angry01_End"
          }
        },
        [51009709] = {
          Content = "我生了一场大病，从那之后我开始不停地做好事，不停地帮助他人。我觉得只要做一件好事，就能弥补一分当年的罪过。",
          DialogueId = 51009709,
          GUID = "7FB28C62",
          NextDialogue = 51009710,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Explain01_Start"
          }
        },
        [51009710] = {
          Camera = "-21.725342,235.385742,212.564453,0.000078,-22.799852,-68.394066,20.0,100000.0,true,DoNotOverride,2.8",
          Content = "可我总是梦见西格愤怒地盯着我，还有艾诺拉，那可怜女孩在火场里无助的哀嚎。他们说，你为活人做再多，死去的人也不会原谅你。",
          DialogueId = 51009710,
          GUID = "7FB28C8C",
          NextDialogue = 51009711,
          SpeakNpcId = 700301
        },
        [51009711] = {
          Content = "啊……维尔莉特，你就是因此回到冰湖城的吗？你也和我一样，终究是无法原谅罪人多纳特吗？",
          DialogueId = 51009711,
          GUID = "7FB28CB6",
          NextDialogue = 51009712,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Disagree"
          }
        },
        [51009712] = {
          Content = "你是来让我解脱的吗？维尔莉特……",
          DialogueId = 51009712,
          GUID = "7FB28CE0",
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Sigh_Start"
          }
        },
        [51009713] = {
          Content = "（多纳特的声音逐渐虚弱，随即倒在了地上。）",
