        },
        [51009724] = {
          Camera = "693.018372,159.482361,393.903809,0.000131,-25.999353,-158.378677,27.283031,100000.0,true,DoNotOverride,2.8",
          Content = "可怜的人啊，你是否同我一样？身处冰冷的回廊，焦急地观望，那因爱与希冀而闪烁的星光……",
          DialogueId = 51009724,
          GUID = "7FB28ED8",
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009725] = {
          Content = "（你听到街角的歌声。环顾四望，却并未发现唱歌的人。要继续在周围看看吗？）",
          DialogueId = 51009725,
          GUID = "7FB28F02"
        },
        [51009726] = {
          Camera = "693.018372,159.482361,393.903809,0.000131,-25.999353,-158.378677,27.283031,100000.0,true,DoNotOverride,2.8",
          Content = "哒……哒哒……",
          DialogueId = 51009726,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "7FB28F2C",
          NextDialogue = 51009727,
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "100001:Shock_Start"
          }
        },
        [51009727] = {
          Content = "谁？谁在那里？",
          DialogueId = 51009727,
          GUID = "7FB28F56",
          NextDialogue = 51009728,
          SpeakNpcId = 100001
        },
        [51009728] = {
          Content = "哦，抱歉，我好像吓到了你？我在这里，稍微往前五步。对，就是这边。",
          DialogueId = 51009728,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB28F80",
          NextDialogue = 51009729,
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "100001:Shock_End"
          }
        },
        [51009729] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,true,DoNotOverride,2.8",
          Content = "你好，今夜无法入眠的朋友。",
          DialogueId = 51009729,
          GUID = "7FB28FAA",
          NextOptions = {
            [1] = 510096391,
            [2] = 510096392,
            [3] = 510096393
          },
          Scripts = [[
SEQ{
MoveTo{ActorId{100001},MoveSpeed{150},TargetPoint{"NvzhuPoint_20023201"}},
TurnTo{TurnToDescription{"100001:n(700309)"}}
}]],
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009730] = {
          Content = "当然不是你的错觉，你正在和我说话。",
          DialogueId = 51009730,
          GUID = "7FB28FD4",
          NextDialogue = 51009733,
          SpeakNpcId = 700309
        },
        [51009731] = {
          Content = "为什么一定要有人躲在这里，不能单纯是一只会说话的箱子呢？",
          DialogueId = 51009731,
          GUID = "7FB28FFE",
          NextDialogue = 51009733,
          SpeakNpcId = 700309
        },
        [51009732] = {
          Content = "抱歉，我只是一只普通的箱子，没有那种力量。",
          DialogueId = 51009732,
          GUID = "7FB29028",
          NextDialogue = 51009733,
          SpeakNpcId = 700309
        },
        [51009733] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "可为什么箱子会说话？",
          DialogueId = 51009733,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29052",
          NextDialogue = 51009734,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009734] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,true,DoNotOverride,2.8",
          Content = "要问为什么……你觉得，唱歌和说话哪个更困难一些？",
          DialogueId = 51009734,
          GUID = "7FB2907C",
          NextDialogue = 51009735,
          SpeakNpcId = 700309
        },
        [51009735] = {
          Content = "唱歌吧。",
          DialogueId = 51009735,
          GUID = "7FB290A6",
          NextDialogue = 51009736,
          SpeakNpcId = 100001
        },
        [51009736] = {
          Content = "可有一种会唱歌的小盒子，只要拧几圈发条就可以歌唱。说话比唱歌更加简单，而我比八音盒更大，也更好——",
          DialogueId = 51009736,
          GUID = "7FB290D0",
          NextDialogue = 51009737,
          SpeakNpcId = 700309
        },
        [51009737] = {
          Content = "所以我可以像这样对你说话，就像你现在正对我说话一样。",
          DialogueId = 51009737,
          GUID = "7FB290FA",
          NextDialogue = 51009738,
          SpeakNpcId = 700309,
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51009738] = {
          Content = "可是……",
          DialogueId = 51009738,
          GUID = "7FB29124",
          NextDialogue = 51009739,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009739] = {
          Content = "我明白，你在疑惑。",
          DialogueId = 51009739,
          GUID = "7FB2914E",
          NextDialogue = 51009740,
          SpeakNpcId = 700309
        },
        [51009740] = {
          Content = "每个人都认为一只木箱不应该说话，就像他们记忆中那个只会响起回音的树洞一样。但是扪心自问，谁不想要一个会说话的木箱呢？",
          DialogueId = 51009740,
          GUID = "7FB29178",
          NextDialogue = 51009741,
          SpeakNpcId = 700309
        },
        [51009741] = {
          Content = "既然你没有第一时间掀开我，说明你还是希望会有一只木箱陪你说说话不是吗？",
          DialogueId = 51009741,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB291A2",
          NextDialogue = 51009742,
          SpeakNpcId = 700309,
          TalkActionId = {
            [1] = "100001:Explain01_End"
          }
        },
        [51009742] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "…………",
          DialogueId = 51009742,
          GUID = "7FB291CC",
          NextDialogue = 51009743,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009743] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,true,DoNotOverride,2.8",
          Content = "看来你似乎接受了我的说法，那可以陪我聊会天吗？",
          DialogueId = 51009743,
          GUID = "7FB291F6",
          NextDialogue = 51009744,
          SpeakNpcId = 700309,
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51009744] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "你想聊些什么？",
          DialogueId = 51009744,
          FacialId = {
            [1] = "100001:Uninterested01"
          },
          GUID = "7FB29220",
          NextDialogue = 51009745,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009745] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,true,DoNotOverride,2.8",
          Content = "嗯，让我想想，聊聊两天前冰湖城歌剧院的剧目怎么样？",
          DialogueId = 51009745,
          GUID = "7FB2924A",
          NextDialogue = 51009746,
          SpeakNpcId = 700309,
          TalkActionId = {
            [1] = "100001:Talk02_End"
          }
        },
        [51009746] = {
          Content = "那部剧叫《普蒂妮》，你看过吗？那个女主角唱的怎么样？",
          DialogueId = 51009746,
          GUID = "7FB29274",
          NextDialogue = 51009747,
          SpeakNpcId = 700309
        },
        [51009747] = {
          Content = "你知道的，我只是一只木箱，我没有办法去剧院看戏。",
          DialogueId = 51009747,
          GUID = "7FB2929E",
          NextDialogue = 51009748,
          SpeakNpcId = 700309
        },
        [51009748] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "抱歉，我没看过。",
          DialogueId = 51009748,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB292C8",
          NextDialogue = 51009749,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          }
        },
        [51009749] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,true,DoNotOverride,2.8",
          Content = "没关系，没人会因此责怪你。或许你应该找个机会去看一看，那是一出好戏。那个叫普蒂妮的主角，她美丽、善良。还有着……追逐自由的勇气。",
          DialogueId = 51009749,
          GUID = "7FB292F2",
          NextDialogue = 51009750,
          SpeakNpcId = 700309
        },
        [51009750] = {
          Content = "我也想成为她那样的人，可我却只是一只木箱。",
          DialogueId = 51009750,
          GUID = "7FB2931C",
          NextDialogue = 51009751,
          SpeakNpcId = 700309
        },
        [51009751] = {
          Content = "所以我做出了一个决定。",
          DialogueId = 51009751,
          GUID = "7FB29346",
          NextDialogue = 51009752,
          SpeakNpcId = 700309
        },
        [51009752] = {
          Content = "什么样的决定？",
          DialogueId = 51009752,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29370",
          NextDialogue = 51009753,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009753] = {
          Camera = "693.018372,159.482361,393.903809,0.000131,-25.999353,-158.378677,27.283031,100000.0,true,DoNotOverride,2.8",
          Content = "我想去远航，没人规定木箱只能堆放在街道的角落，它也可以被做成船，随着洋流漂泊——我想感受混着海水与砂砾的风。",
          DialogueId = 51009753,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB2939A",
          NextDialogue = 51009754,
          SpeakNpcId = 700309,
          TalkActionId = {
            [1] = "100001:Talk02_End"
          }
        },
        [51009754] = {
          Content = "可离开这里，就意味着我同样会失去现有的一切。",
          DialogueId = 51009754,
          GUID = "7FB293C4",
          NextDialogue = 51009755,
          SpeakNpcId = 700309
        },
        [51009755] = {
          Content = "失去了囚笼，也代表着失去了容身之所。拥有了自由，也代表拥有了未知的风险。",
          DialogueId = 51009755,
          GUID = "7FB293EE",
          NextDialogue = 51009756,
          SpeakNpcId = 700309
        },
        [51009756] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,true,DoNotOverride,2.8",
          Content = "我的朋友，你觉得，我应该怎么选呢？",
          DialogueId = 51009756,
          GUID = "7FB29418",
          NextOptions = {
            [1] = 510096661,
            [2] = 510096662
          },
          SpeakNpcId = 700309
        },
        [51009757] = {
          Content = "……说的也是。",
          DialogueId = 51009757,
          GUID = "7FB29442",
          NextDialogue = 51009758,
          SpeakNpcId = 700309
        },
        [51009758] = {
          Content = "谢谢你愿意陪一只箱子聊天，善良的人啊。天快亮了，属于朽木的魔法要消失了。",
          DialogueId = 51009758,
          GUID = "7FB2946C",
          NextDialogue = 51009759,
          SpeakNpcId = 700309
        },
        [51009759] = {
          Content = "祝愿你在未来的每一个无眠的夜晚，都有……不，祝愿你每个夜晚都能安享美梦。",
          DialogueId = 51009759,
          GUID = "7FB29496",
          SpeakNpcId = 700309
        },
        [51009760] = {
          Content = "（你听到了一阵微小的震颤声，如同躲藏在箱子背后的小精灵赶在天亮前离开了孩子的床头。当回过神来的时候，你意识到那位箱子小姐似乎已经离开了。）",
          DialogueId = 51009760,
          GUID = "7FB294C0"
        },
        [51009761] = {
          Camera = "181.495728,-78.722099,88.629395,0.000093,-3.999294,136.804047,30.022871,100000.0,true,DoNotOverride,2.8",
          Content = "（躲在箱子里的那个声音……不知道为什么就顺着她的想法聊下去了。）",
          DialogueId = 51009761,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB294EA",
          NextDialogue = 51009762,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009762] = {
          Camera = "-5654.617676,-3244.824707,4837.760742,0.000161,-38.599369,19.822903,27.283031,100000.0,true,DoNotOverride,2.8",
          Content = "（可能是谁家的小孩子在乱跑，不能就这么放着不管，还是找周围的人问问吧。）",
          DialogueId = 51009762,
          GUID = "7FB29514",
          SpeakNpcId = 100001
        },
        [51009763] = {
          Content = "请问……你是谁？从刚才开始似乎就一直在我家附近转悠。",
          DialogueId = 51009763,
          GUID = "7FB2953E",
          NextDialogue = 51009764,
          SpeakNpcId = 700302,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009764] = {
          Content = "是有委托找我吗，找人？还是收集素材？其他的委托也不是不接，但必须合法。",
          DialogueId = 51009764,
          GUID = "7FB29568",
          NextDialogue = 51009765,
          SpeakNpcId = 700302,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009765] = {
          Content = "委托？",
          DialogueId = 51009765,
          GUID = "7FB29592",
          NextDialogue = 51009766,
          SpeakNpcId = 100001
        },
        [51009766] = {
          Content = "嗯？原来你不是来找我发委托的？",
          DialogueId = 51009766,
          GUID = "7FB295BC",
          NextDialogue = 51009767,
          SpeakNpcId = 700302,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009767] = {
          Content = "好吧，看来“狩月人吉赛尔”的名气没有卡米拉说的那么响。",
          DialogueId = 51009767,
          GUID = "7FB295E6",
          NextDialogue = 51009768,
          SpeakNpcId = 700302
        },
        [51009768] = {
          Content = "狩月人吉赛尔……这么一说我好像听到过——",
          DialogueId = 51009768,
          GUID = "7FB29610",
          NextDialogue = 51009769,
          SpeakNpcId = 100001
        },
        [51009769] = {
          Content = "倒也不用为了照顾我的心情这么说。",
          DialogueId = 51009769,
          GUID = "7FB2963A",
          NextDialogue = 51009770,
          SpeakNpcId = 700302
        },
        [51009770] = {
          Content = "不……其实……",
          DialogueId = 51009770,
          GUID = "7FB29664",
          NextDialogue = 51009771,
          SpeakNpcId = 100001
        },
        [51009771] = {
          Content = "（向吉赛尔说明了她家屋后那个箱子的事。）",
          DialogueId = 51009771,
          GUID = "7FB2968E",
          NextDialogue = 51009772
        },
        [51009772] = {
          Content = "你是说，我家房后的木箱说话了，还推荐你去听一场歌剧。嗯，我了解了。",
          DialogueId = 51009772,
          GUID = "7FB296B8",
          NextDialogue = 51009773,
          SpeakNpcId = 700302
        },
        [51009773] = {
          Content = "……",
          DialogueId = 51009773,
          GUID = "7FB296E2",
          NextDialogue = 51009774,
          SpeakNpcId = 100001
        },
        [51009774] = {
          Content = "你好像，反应和我想象中有点不一样？",
          DialogueId = 51009774,
          GUID = "7FB2970C",
          NextDialogue = 51009775,
          SpeakNpcId = 100001
        },
        [51009775] = {
          Content = "是吗？可能是我性格如此。无论是有小孩子淘气钻进去和你说话，还是箱子本身就会说话，对我来说都是可以接受的现实。",
          DialogueId = 51009775,
          GUID = "7FB29736",
          NextDialogue = 51009776,
          SpeakNpcId = 700302
        },
        [51009776] = {
          Content = "谢谢你把这件事告诉我，我会在这一带问一问的。",
          DialogueId = 51009776,
          GUID = "7FB29760",
          NextDialogue = 51009777,
          SpeakNpcId = 700302
        },
        [51009777] = {
          Content = "哦对了，我想起来了。你是{nickname}对吗？最近在狩月人圈子里评价很高的新星。",
          DialogueId = 51009777,
          GUID = "7FB2978A",
          NextOptions = {
            [1] = 510096871,
            [2] = 510096872,
            [3] = 510096873
          },
          SpeakNpcId = 700302
        },
        [51009778] = {
          Content = "果然是你，看来我的眼光还没退步。",
          DialogueId = 51009778,
          GUID = "7FB297B4",
          NextDialogue = 51009781,
          SpeakNpcId = 700302
        },
        [51009779] = {
          Content = "不用那么警惕，像你这样的有能力的新人出名很快的。",
          DialogueId = 51009779,
          GUID = "7FB297DE",
          NextDialogue = 51009781,
          SpeakNpcId = 700302
        },
        [51009780] = {
          Content = "品味稍微差了点……不过确实是个辨识度很高的称号。",
          DialogueId = 51009780,
          GUID = "7FB29808",
          NextDialogue = 51009781,
          SpeakNpcId = 700302
        },
        [51009781] = {
          Content = "既然你看起来有空，可以帮我一个忙吗？",
          DialogueId = 51009781,
          GUID = "7FB29832",
          NextDialogue = 51009782,
          SpeakNpcId = 700302
        },
        [51009782] = {
          Content = "帮我找些草药来，种类和数量我会列一个清单给你，收集好之后直接送到水仙平原就好，报酬我也会提前留给卡米拉。",
          DialogueId = 51009782,
          GUID = "7FB2985C",
          NextDialogue = 51009783,
          SpeakNpcId = 700302
        },
        [51009783] = {
          Content = "不用送到这里？",
          DialogueId = 51009783,
          GUID = "7FB29886",
          NextDialogue = 51009784,
          SpeakNpcId = 100001
        },
        [51009784] = {
          Content = "没事，放到水仙平原就可以。",
          DialogueId = 51009784,
          GUID = "7FB298B0",
          SpeakNpcId = 700302
        },
        [51009785] = {
          Camera = "777.87793,290.900391,409.416016,0.000004,-23.199877,-161.79744,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "（差不多应该够了。）",
          DialogueId = 51009785,
          FacialId = {
            [1] = "100001:Smile02"
          },
          GUID = "7FB298DA",
          NextDialogue = 51009786,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Confident_Start"
          }
        },
        [51009786] = {
          Camera = "104.59375,60.244141,114.90918,0.000007,-13.199702,-164.194138,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "（这些草药……都是些随处可见的品种，如果吉赛尔也是狩月人为什么要专门拜托我？）",
          DialogueId = 51009786,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29904",
          NextDialogue = 51009787,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009787] = {
          Content = "（现在回想起来，她的态度也有些奇怪……）",
          DialogueId = 51009787,
          GUID = "7FB2992E",
          NextDialogue = 51009788,
          SpeakNpcId = 100001
        },
        [51009788] = {
          Content = "（先把这些草药带回水仙平原吧，顺便向卡米拉打听一下。）",
          DialogueId = 51009788,
          GUID = "7FB29958",
          SpeakNpcId = 100001
        },
        [51009789] = {
          Camera = "-670.438599,-35.56543,192.935547,0.000003,-7.599917,-2.401886,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "下午好，今天是想喝上一杯，还是在看委托？",
          DialogueId = 51009789,
          FacialId = {
            [1] = "200003:Smile01"
          },
          GUID = "7FB29982",
          NextDialogue = 51009790,
          SpeakNpcId = 200003
        },
        [51009790] = {
          Content = "我是来送东西的，是吉赛尔的委托，说让我把东西送到水仙平原就好。",
          DialogueId = 51009790,
          GUID = "7FB299AC",
          NextDialogue = 51009791,
          SpeakNpcId = 100001
        },
        [51009791] = {
          Content = "吉赛尔？她的确不久前来过一趟，说让我帮忙把一个包裹转交给你。不过总感觉有些不对劲……委托的内容是什么？",
          DialogueId = 51009791,
          GUID = "7FB299D6",
          NextDialogue = 51009792,
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "200003:Talk03_Start"
          }
        },
        [51009792] = {
          Content = "（向卡米拉说明了吉赛尔委托自己采集草药的事。）",
          DialogueId = 51009792,
          GUID = "7FB29A00",
          NextDialogue = 51009793
        },
        [51009793] = {
          Content = "…………",
          DialogueId = 51009793,
          GUID = "7FB29A2A",
          NextDialogue = 51009794,
          SpeakNpcId = 200003
        },
        [51009794] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "有什么不对吗？",
          DialogueId = 51009794,
          GUID = "7FB29A54",
          NextDialogue = 51009795,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51009795] = {
          Camera = "-263.901001,-18.859375,168.283203,0.000002,-5.799807,9.398898,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "委托本身倒是没什么，不过为什么她会发出这种委托？",
          DialogueId = 51009795,
          GUID = "7FB29A7E",
          NextDialogue = 51009796,
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "100001:Talk01_End"
          }
        },
        [51009796] = {
          Content = "需求都是些很常见的风寒草药，她自己去收集的话一早上就能回来，没有必要专门请人去做。",
          DialogueId = 51009796,
          GUID = "7FB29AA8",
          NextDialogue = 51009797,
          SpeakNpcId = 200003
        },
        [51009797] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "说起来我的确听她提到过，她自己就是个狩月人。",
          DialogueId = 51009797,
          GUID = "7FB29AD2",
          NextDialogue = 51009798,
          SpeakNpcId = 100001
        },
        [51009798] = {
          Camera = "-263.901001,-18.859375,168.283203,0.000002,-5.799807,9.398898,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "嗯，她以前做过卫戍官，十六年前因为某个案子的判决和上级起了矛盾离开卫戍部队做了狩月人。思维敏捷身手也不错，在圈子里名气不小。",
          DialogueId = 51009798,
          GUID = "7FB29AFC",
          NextDialogue = 51009799,
          SpeakNpcId = 200003
        },
        [51009799] = {
          Content = "算了，不提那些了。既然委托没什么问题，她也提前留过了口信，我就没什么好多说的。",
          DialogueId = 51009799,
          FacialId = {
            [1] = "200003:None"
          },
          GUID = "7FB29B26",
          NextDialogue = 51009800,
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "200003:Talk03_End"
          }
        },
        [51009800] = {
          Content = "这是她留给你的东西，拿好。",
          DialogueId = 51009800,
          GUID = "7FB29B50",
          NextDialogue = 51009801,
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "200003:Give"
          }
        },
        [51009801] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "这是……委托的报酬，还有一封信？",
          DialogueId = 51009801,
          FacialId = {
            [1] = "100001:Doubt01"
          },
