        [51009862] = {
          Camera = "-1404.640625,-280.359375,849.211426,0.00002,-23.200226,22.597872,35.0,100000.0,true,Manual,2.8",
          Content = "十六年前，冰湖城发生了一起绑架案，一个叫西格的年轻人绑架了时任格雷姆矿场负责人法布瑞斯·鲁斯福德的女儿——艾诺拉·鲁斯福德。",
          DialogueId = 51009862,
          GUID = "7FB2A57C",
          NextDialogue = 51009863,
          SpeakNpcId = 700302
        },
        [51009863] = {
          Content = "在抵抗抓捕的过程中，西格不慎点燃了房屋，导致了艾诺拉丧生，而他也因此被判处死刑。",
          DialogueId = 51009863,
          GUID = "7FB2A5A6",
          NextDialogue = 51009864,
          SpeakNpcId = 700302
        },
        [51009864] = {
          Camera = "-314.688477,142.042969,142.037598,1.000012,-0.599793,-21.008369,40.559872,100000.0,true,DoNotOverride,2.8",
          Content = "那起陈年旧事我的确有所耳闻。真是一出令人扼腕的悲剧，愿那个可怜的女孩安息。",
          DialogueId = 51009864,
          GUID = "7FB2A5D0",
          NextDialogue = 51009865,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51009865] = {
          Content = "——但我只是近年来才来到冰湖城，那起案件，又和我有什么关系呢？",
          DialogueId = 51009865,
          GUID = "7FB2A5FA",
          NextDialogue = 51009866,
          SpeakNpcId = 700300
        },
        [51009866] = {
          Camera = "-357.697266,-104.112305,130.897461,0.99998,-2.799988,24.192202,24.205383,100000.0,true,DoNotOverride,2.8",
          Content = "当然是因为，那场火灾有一个幸存者。",
          DialogueId = 51009866,
          GUID = "7FB2A624",
          NextDialogue = 51009867,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700300:Explain02_End"
          }
        },
        [51009867] = {
          Content = "根据一位知情人的说法，在火灾现场除了西格和艾诺拉以外，还有一个人——西格的妹妹，维尔莉特。一个与当年的艾诺拉年岁相仿的女孩。",
          DialogueId = 51009867,
          GUID = "7FB2A64E",
          NextDialogue = 51009868,
          SpeakNpcId = 700302
        },
        [51009868] = {
          Content = "在混乱的火灾现场，那位知情人救出了当时也在屋子里的维尔莉特……或者说，他<H>以为</>自己救出了维尔莉特。",
          DialogueId = 51009868,
          GUID = "7FB2A678",
          NextDialogue = 51009869,
          SpeakNpcId = 700302
        },
        [51009869] = {
          Content = "到此为止，我说的没错吧？十六年前杀害了维尔莉特，又假扮成她，利用她的身份蒙骗多纳特逃出了冰湖城的你，艾诺拉·鲁斯福德！",
          DialogueId = 51009869,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2A6A2",
          NextDialogue = 51009870,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Angry01_Start"
          }
        },
        [51009870] = {
          Camera = "-220.682617,16.6875,142.309082,1.000003,-2.999962,-14.610696,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "……呵，有趣的剧本，是不多见的悬疑题材呢。",
          DialogueId = 51009870,
          FacialId = {
            [1] = "700300:CM_Idle"
          },
          GUID = "7FB2A6CC",
          NextDialogue = 51009871,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Talk01_Start",
            [2] = "700302:Angry01_End"
          }
        },
        [51009871] = {
          Content = "说下去，我喜欢听。",
          DialogueId = 51009871,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2A6F6",
          NextDialogue = 51009872,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700302:Confident_End"
          }
        },
        [51009872] = {
          Camera = "-357.697266,-104.112305,130.897461,0.99998,-2.799988,24.192202,24.205383,100000.0,true,DoNotOverride,2.8",
          Content = "这些年我一直在调查那桩案件，烧焦的尸体，幸存的维尔莉特，这一切都太过巧合。",
          DialogueId = 51009872,
          GUID = "7FB2A720",
          NextDialogue = 51009873,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700300:Talk01_End",
            [2] = "700302:Think_Start"
          }
        },
        [51009873] = {
          Content = "这一切似乎都有着某种关联，但破碎的关键词之间缺少一条能将这一切连起来的线。",
          DialogueId = 51009873,
          GUID = "7FB2A74A",
          NextDialogue = 51009874,
          SpeakNpcId = 700302
        },
        [51009874] = {
          Content = "如果不是我在卫戍部队期间给法布瑞斯那个家伙当过几天护卫，并且凑巧听到了她女儿的歌声——",
          DialogueId = 51009874,
          GUID = "7FB2A774",
          NextDialogue = 51009875,
          SpeakNpcId = 700302
        },
        [51009875] = {
          Camera = "-220.682617,16.6875,142.309082,1.000003,-2.999962,-14.610696,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "恐怕我永远都不会把这些和你联系起来，“千面的薇奥莱塔”。",
          DialogueId = 51009875,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2A79E",
          NextDialogue = 51009876,
          SpeakNpcId = 700302
        },
        [51009876] = {
          Content = "我用各种方法试图调查你的生活习惯，比如……找一些人以送信的名义观察你。",
          DialogueId = 51009876,
          GUID = "7FB2A7C8",
          NextDialogue = 51009877,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Explain01_Start"
          }
        },
        [51009877] = {
          Content = "原来那个卫兵是你派来的。",
          DialogueId = 51009877,
          GUID = "7FB2A7F2",
          NextDialogue = 51009878,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Talk01_Start",
            [2] = "700302:Explain01_End"
          }
        },
        [51009878] = {
          Content = "不，他的确是你的剧迷，我也只是稍稍煽动了一下罢了。多亏了他，我才最终确定了你的身份。",
          DialogueId = 51009878,
          GUID = "7FB2A81C",
          NextDialogue = 51009879,
          SpeakNpcId = 700302
        },
        [51009879] = {
          Camera = "127.291016,-233.679688,146.983398,1.000008,-1.000206,118.987587,38.469608,100000.0,true,DoNotOverride,2.8",
          Content = "即便如此，我还是有一件事没有搞清楚。",
          DialogueId = 51009879,
          GUID = "7FB2A846",
          NextDialogue = 51009880,
          SpeakNpcId = 700302
        },
        [51009880] = {
          Content = "在火灾中和维尔莉特调换身份，这种方法没有西格和维尔莉特的配合难以实施，你到底是怎么说服他们的？",
          DialogueId = 51009880,
          GUID = "7FB2A870",
          NextDialogue = 51009881,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700300:Talk01_End",
            [2] = "700302:Think_Start"
          }
        },
        [51009881] = {
          Camera = "-294.663086,168.334961,176.219727,1.000005,-6.799897,-27.606359,56.0,100000.0,true,DoNotOverride,2.8",
          Content = "我还以为你要问什么呢……这种事不是很简单吗？",
          DialogueId = 51009881,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2A89A",
          NextDialogue = 51009882,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Sigh_Start",
            [2] = "700302:Think_End"
          }
        },
        [51009882] = {
          Content = "我可是那个法布瑞斯的女儿，既然你曾经在父亲的手下工作过，就应该知道触碰他逆鳞的后果。",
          DialogueId = 51009882,
          GUID = "7FB2A8C4",
          NextDialogue = 51009883,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Sigh_End"
          }
        },
        [51009883] = {
          Content = "可怜的西格早就做好了牺牲自己的准备，但按父亲的作风，维尔莉特也无法幸免。",
          DialogueId = 51009883,
          GUID = "7FB2A8EE",
          NextDialogue = 51009884,
          SpeakNpcId = 700300
        },
        [51009884] = {
          Content = "而我则告诉他们：唯一的办法，就是在拿到赎金后尽可能拖延时间，同时想办法制造混乱让维尔莉特逃跑。",
          DialogueId = 51009884,
          GUID = "7FB2A918",
          NextDialogue = 51009885,
          SpeakNpcId = 700300
        },
        [51009885] = {
          Content = "真是可笑，惊慌失措的他居然真的独自去拖延卫戍部队，期待一个重病的小姑娘在火灾中逃出生天……",
          DialogueId = 51009885,
          GUID = "7FB2A942",
          NextDialogue = 51009886,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Talk02_Start"
          }
        },
        [51009886] = {
          Content = "我抓住了这个机会，杀死了那个碍事的小可怜，用她的身份摆脱了那栋破房子，也摆脱了我的父亲，摆脱了所有阻止我踏上舞台的一切。",
          DialogueId = 51009886,
          GUID = "7FB2A96C",
          NextDialogue = 51009887,
          SpeakNpcId = 700300
        },
        [51009887] = {
          Camera = "96.022461,-329.655273,121.388672,0.999973,0.800034,107.991287,33.074104,100000.0,true,DoNotOverride,2.8",
          Content = "……",
          DialogueId = 51009887,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2A996",
          NextDialogue = 51009888,
          SpeakNpcId = 700302
        },
        [51009888] = {
          Content = "啊呀，得到了自己十几年来日思夜想的真相，你看起来并不开心，吉赛尔女士。",
          DialogueId = 51009888,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2A9C0",
          NextDialogue = 51009889,
          SpeakNpcId = 700300
        },
        [51009889] = {
          Content = "不可理喻……就为了这种理由？就为了这种理由害死了两个人？！你把人命当成什么了！",
          DialogueId = 51009889,
          GUID = "7FB2A9EA",
          NextDialogue = 51009890,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Angry01_Start",
            [2] = "700300:Talk02_End"
          }
        },
        [51009890] = {
          Content = "那么你打算怎么做？去满世界宣扬薇奥莱塔的恶毒手段让我身败名裂？又或者……现在就为他们两人报仇？",
          DialogueId = 51009890,
          GUID = "7FB2AA14",
          NextDialogue = 51009891,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Confident_Start"
          }
        },
        [51009891] = {
          Content = "……我原本只是想揭露这一切，然后把你交给卫戍部队。",
          DialogueId = 51009891,
          GUID = "7FB2AA3E",
          NextDialogue = 51009892,
          SpeakNpcId = 700302
        },
        [51009892] = {
          Content = "（吉赛尔从腰间拔出匕首，她愤怒的神情，让你似乎感觉自己听到了攥紧刀柄，又或者是几乎要把牙齿咬碎的碾磨声。）",
          DialogueId = 51009892,
          GUID = "7FB2AA68",
          IsBlack = 1,
          NextDialogue = 51009893,
          TalkActionId = {
            [1] = "700302:Angry01_End"
          }
        },
        [51009893] = {
          Content = "（如果再不阻止她，那柄利刃毫无疑问会在下一刻划开这冰湖城最美妙的歌喉。无论如何，一场命案是你不愿看到的。）",
          DialogueId = 51009893,
          GUID = "7FB2AA69",
          IsBlack = 1
        },
        [51009894] = {
          Content = "{nickname}？你为什么会在这里？",
          DialogueId = 51009894,
          GUID = "7FB2AABC",
          NextDialogue = 51009895,
          SpeakNpcId = 700300
        },
        [51009895] = {
          Content = "闪开，我无法容忍这样的败类继续活在世上！",
          DialogueId = 51009895,
          GUID = "7FB2AAE6",
          NextDialogue = 51009896,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Angry01_Start"
          }
        },
        [51009896] = {
          Content = "（吉赛尔似乎因愤怒失去了理智，得想办法让她冷静下来。）",
          DialogueId = 51009896,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2AB10",
          SpeakNpcId = 100001
        },
        [51009897] = {
          Camera = "-19.636719,461.339844,156.540039,0.000053,-6.400208,-95.20314,35.333332,100000.0,true,DoNotOverride,2.8",
          Content = "冷静下来，吉赛尔，或许事情并不是你想的那样。",
          DialogueId = 51009897,
          GUID = "7FB2AB3A",
          NextDialogue = 51009898,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51009898] = {
          Content = "你听到她刚才说的那些话了吗？这让我怎么冷静？！",
          DialogueId = 51009898,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2AB64",
          NextDialogue = 51009899,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Angry01_Start"
          }
        },
        [51009899] = {
          Content = "有我们两个在这里，她跑不掉的。所以，至少先冷静下来让我问她几个问题！",
          DialogueId = 51009899,
          GUID = "7FB2AB8E",
          NextDialogue = 51009900,
          SpeakNpcId = 100001
        },
        [51009900] = {
          Camera = "157.706055,-54.485352,141.052246,0.0001,-1.599849,150.594193,53.202648,100000.0,true,DoNotOverride,2.8",
          Content = "…………",
          DialogueId = 51009900,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2ABB8",
          NextDialogue = 51009901,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Angry01_End"
          }
        },
        [51009901] = {
          Content = "你问吧。",
          DialogueId = 51009901,
          GUID = "7FB2ABE2",
          NextDialogue = 51009902,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Talk03_Start",
            [2] = "100001:Talk02R_End"
          },
          TurnTo = {
            [1] = "100001:n(700300)",
            [2] = "700300:n(100001)"
          }
        },
        [51009902] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,true,DoNotOverride,2.8",
          Content = "在那之前，薇奥莱塔女士，这个东西你有印象吗？",
          DialogueId = 51009902,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon02.T_Guide_ChapterFire_Ribbon02'}",
          GUID = "7FB2AC0C",
          NextDialogue = 51009903,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Give"
          }
        },
        [51009903] = {
          Content = "那是……",
          DialogueId = 51009903,
          FacialId = {
            [1] = "700300:CM_Shock01"
          },
          GUID = "7FB2AC36",
          NextDialogue = 51009904,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Sigh_Start"
          }
        },
        [51009904] = {
          Content = "（薇奥莱塔下意识地将手伸向自己脑后，在确认到熟悉的触感后愣在了原地。）",
          DialogueId = 51009904,
          GUID = "7FB2AC60",
          NextDialogue = 51009905,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0036_story_renweidaozu\"}}"
        },
        [51009905] = {
          Content = "看你的反应，我想的果然没错……这条缎带，是你放在西格墓前的吧？",
          DialogueId = 51009905,
          GUID = "7FB2AC8A",
          NextDialogue = 51009906,
          SpeakNpcId = 100001
        },
        [51009906] = {
          Content = "你曾经告诉过我，这条缎带来自你的一位挚友，你是为了她的梦想才站上舞台的。",
          DialogueId = 51009906,
          GUID = "7FB2ACB4",
          NextDialogue = 51009907,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700300:Sigh_End"
          }
        },
        [51009907] = {
          Content = "你还真是个天真的傻瓜，居然连那么肉麻的谎言也会相信。",
          DialogueId = 51009907,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2ACDE",
          NextDialogue = 51009908,
          SpeakNpcId = 700300
        },
        [51009908] = {
          Camera = "233.676758,-71.671875,155.098145,0.000096,-6.00058,179.598373,35.333332,100000.0,true,DoNotOverride,2.8",
          Content = "或许吧，所以我去找多纳特借来了这条缎带，并且确认了它的来历。",
          DialogueId = 51009908,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB2AD08",
          NextDialogue = 51009909,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51009909] = {
          Content = "多纳特告诉了我维尔莉特的事。他说那是个才华横溢的姑娘，如果不是贫穷和罹患重病，她也许会成为一名优秀的剧作家。",
          DialogueId = 51009909,
          GUID = "7FB2AD32",
          NextDialogue = 51009910,
          SpeakNpcId = 100001
        },
        [51009910] = {
          Content = "虽然命运没能眷顾那个女孩，但她从未放弃。即便几乎不能下床行动，她也还是用另外的方式追寻着自己的梦想。",
          DialogueId = 51009910,
          GUID = "7FB2AD5C",
          NextDialogue = 51009911,
          SpeakNpcId = 100001
        },
        [51009911] = {
          Content = "她希望能让世界上最好的演员表演她创作的作品，把她在生命的最后写下的她最满意的故事传遍整个阿特拉西亚。",
          DialogueId = 51009911,
          GUID = "7FB2AD86",
          NextDialogue = 51009912,
          SpeakNpcId = 100001
        },
        [51009912] = {
          Content = "那部作品的名字是——",
          DialogueId = 51009912,
          GUID = "7FB2ADB0",
          NextDialogue = 51009913,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_End"
          }
        },
        [51009913] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,true,DoNotOverride,2.8",
          Content = "……三幕剧《普蒂妮》。后来被改编为同名歌剧。",
          DialogueId = 51009913,
          GUID = "7FB2ADDA",
          NextDialogue = 51009914,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51009914] = {
          Camera = "233.676758,-71.671875,155.098145,0.000096,-6.00058,179.598373,35.333332,100000.0,true,DoNotOverride,2.8",
          Content = "嗯，你已经意识到了，继续说谎只会让你的处境更危险。所以……",
          DialogueId = 51009914,
          GUID = "7FB2AE04",
          NextOptions = {
            [1] = 510098241,
            [2] = 510098242
          },
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:ConfidentLR_Start"
          }
        },
        [51009915] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,true,DoNotOverride,2.8",
          Content = "说的也是，剧本总该有结局的。",
          DialogueId = 51009915,
          GUID = "7FB2AE2E",
          NextDialogue = 51009917,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51009916] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,true,DoNotOverride,2.8",
          Content = "在这种时候说悬疑剧的经典台词吗……",
          DialogueId = 51009916,
          GUID = "7FB2AE58",
          NextDialogue = 51009917,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Disagree"
          }
        },
        [51009917] = {
          Content = "如果每一部悬疑剧的观众都如你一样敏锐，那些剧作家也无需绞尽脑汁思考如何把剧本再改简单些了。",
          DialogueId = 51009917,
          GUID = "7FB2AE82",
          NextDialogue = 51009918,
          SpeakNpcId = 700300
        },
        [51009918] = {
          Camera = "167.182617,-305.451172,119.724609,0.000095,2.599987,124.794083,44.87347,100000.0,true,DoNotOverride,2.8",
          Content = "你们在说什么？这是什么意思？",
          DialogueId = 51009918,
          GUID = "7FB2AEAC",
          LookAt = {
            [1] = "100001:n(700302)"
          },
          NextDialogue = 51009919,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "100001:ConfidentLR_End"
          },
          TurnTo = {
            [1] = "700300:n(700302)"
          }
        },
        [51009919] = {
          Camera = "-19.636719,461.339844,156.540039,0.000053,-6.400208,-95.20314,35.333332,100000.0,true,DoNotOverride,2.8",
          Content = "很简单，吉赛尔。如果薇奥莱塔真的只把维尔莉特当做随意丢弃的工具，她怎么会给自己取一个和维尔莉特如此相似的名字呢？",
          DialogueId = 51009919,
          GUID = "7FB2AED6",
          NextDialogue = 51009920,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51009920] = {
          Camera = "-1216.617188,-202.104492,761.92041,0.000021,-23.200226,22.597822,35.0,100000.0,true,Manual,2.8",
          Content = "我继续说我的猜测吧：十六年前，西格为了筹到钱给维尔莉特治病，绑架了艾诺拉·鲁斯福德……也就是如今的薇奥莱塔。",
          DialogueId = 51009920,
          FinalCamera = "-1418.189453,-286.000977,855.499756,0.000021,-23.200226,22.597822,35.0,100000.0,true,Manual,2.8",
          GUID = "7FB2AF00",
          NextDialogue = 51009921,
          SpeakNpcId = 100001,
          ToFinalCameraBlendTime = 10
        },
        [51009921] = {
          Content = "在被绑架的期间，艾诺拉结识了生病卧床的维尔莉特。你们就是在那时成为了挚友。",
          DialogueId = 51009921,
          GUID = "7FB2AF2A",
          NextDialogue = 51009922,
          SpeakNpcId = 100001
        },
        [51009922] = {
          Content = "但好景不长……",
          DialogueId = 51009922,
          GUID = "7FB2AF54",
          NextDialogue = 51009923,
          SpeakNpcId = 100001
        },
        [51009923] = {
          Content = "维尔莉特察觉到了自己已经时日无多，她不希望哥哥为了虚无缥缈的可能性一错再错，于是写信给哥哥的好友多纳特，希望他阻止西格。",
          DialogueId = 51009923,
          GUID = "7FB2AF7E",
          NextDialogue = 51009924,
          SpeakNpcId = 100001
        },
        [51009924] = {
          Content = "如她所想，多纳特最终还是找到了吉赛尔，向你举报了西格绑架了艾诺拉的事。不过我猜，那个时候恐怕维尔莉特已经……",
          DialogueId = 51009924,
          GUID = "7FB2AFA8",
          NextDialogue = 51009925,
          SpeakNpcId = 100001
        },
        [51009925] = {
          Camera = "-158.601562,204.59082,150.237305,0.000071,-3.199944,-50.20327,35.333332,100000.0,true,DoNotOverride,2.8",
          Content = "啊……说来好笑，明明是被人绑架，但那段时光却是我出生以来最快乐的回忆。",
          DialogueId = 51009925,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          FinalCamera = "-91.950195,124.576172,144.41748,0.000071,-3.199944,-50.20327,35.333332,100000.0,true,DoNotOverride,2.8",
          GUID = "7FB2AFD2",
          LookAt = {
            [1] = "100001:n(700300)"
          },
          NextDialogue = 51009926,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          },
          ToFinalCameraBlendTime = 15
        },
        [51009926] = {
          Content = "虽然把我绑在了房间里，但西格并没有打算伤害我，甚至并未对我有过多的关注，只是在屋子里匆忙地走来走去。",
          DialogueId = 51009926,
          GUID = "7FB2AFFC",
          NextDialogue = 51009927,
          SpeakNpcId = 700300
        },
        [51009927] = {
          Content = "当时的我清楚地知道屋子里还有第三个人，那是个女孩子，总会在心情好的时候哼着歌……",
          DialogueId = 51009927,
          GUID = "7FB2B026",
          NextDialogue = 51009928,
          SpeakNpcId = 700300
        },
        [51009928] = {
          Content = "或许是因为西格实在无法同时照顾两个无法自理的人，所以几天后，他给我解了绑，允许我在一楼自由行动。",
          DialogueId = 51009928,
          GUID = "7FB2B050",
          NextDialogue = 51009929,
          SpeakNpcId = 700300
        },
        [51009929] = {
          Camera = "-91.950195,124.576172,144.41748,0.000071,-3.199944,-50.20327,35.333332,100000.0,true,DoNotOverride,2.8",
          Content = "我总是在他外出的时候去二楼和维尔莉特偷偷见面，我们会一起聊她写的故事。她会把她的想法告诉我，而我则把存在于她想象中的画面表演出来。",
          DialogueId = 51009929,
          GUID = "7FB2B07A",
          NextDialogue = 51009930,
          SpeakNpcId = 700300
        },
        [51009930] = {
          Content = "“亲爱的人儿，请不要为我悲伤！在这个无眠之夜，我将远航——”",
          DialogueId = 51009930,
          GUID = "7FB2B0A4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009931,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora"
        },
        [51009931] = {
          Content = "“风儿鼓起船帆，我撑起木桨——灯塔映在海里啊，月光多明亮！”",
          DialogueId = 51009931,
          GUID = "7FB2B0CE",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009932,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora"
        },
        [51009932] = {
          Content = "谢谢你，艾诺拉……你演得很好，很好。呵呵……我想象中的普蒂妮啊，她就是你的样子……热烈，勇敢，心儿永远向着自由……",
          DialogueId = 51009932,
          GUID = "7FB2B0F8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009933,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet"
        },
        [51009933] = {
          Content = "谢谢！这个是我自己瞎唱的……不过我认识一位很优秀的作曲家！他叫卡瓦拉多西。我们可以拜托他把《普蒂妮》改编成歌剧——",
          DialogueId = 51009933,
          GUID = "7FB2B122",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009934,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora"
        },
        [51009934] = {
          Content = "……不过我应该没有机会演唱了。",
          DialogueId = 51009934,
          GUID = "7FB2B14C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009935,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora"
        },
        [51009935] = {
          Content = "我已经十八岁了。父亲已经给我安排好了婚事，就在两个月后。对方也是炼金院的年轻长官。",
          DialogueId = 51009935,
          GUID = "7FB2B176",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009936,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora"
        },
        [51009936] = {
          Content = "我想我接下来的一生，不是要待在小房间里做个瓷娃娃一样的漂亮摆件，就是要和那些该死的月髓液罐子打一辈子交道了。",
          DialogueId = 51009936,
          GUID = "7FB2B1A0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009937,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora"
        },
        [51009937] = {
          Content = "不，不……艾诺拉，不应该是这样的——你有着云雀一样的歌喉……你不属于小房间……而是更大的，更大的舞台……",
          DialogueId = 51009937,
          GUID = "7FB2B1CA",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009938,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet"
        },
        [51009938] = {
          Content = "每一个热爱歌唱的人……都有资格在舞台上熠熠发光……无论是索拉还是卡戎，是富有还是贫穷……",
          DialogueId = 51009938,
          GUID = "7FB2B1F4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009939,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet"
        },
        [51009939] = {
          Content = "我会想办法让哥哥放你离开。我的身体已经没有办法了，我不知道还有没有机会把《普蒂妮》的最后一幕写完……",
          DialogueId = 51009939,
          GUID = "7FB2B21E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009940,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet"
        },
        [51009940] = {
          Content = "但艾诺拉，请你答应我，一定要走上舞台，把我们的《普蒂妮》唱给所有人……",
          DialogueId = 51009940,
          GUID = "7FB2B248",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009941,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet"
        },
        [51009941] = {
          Content = "“每一个热爱歌唱的人，都有资格在舞台上熠熠发光。无论他们是索拉还是卡戎，是富有还是贫穷。”这是维尔莉特的遗愿，也是我一生的箴言。",
          DialogueId = 51009941,
          GUID = "7FB2B272",
          NextDialogue = 51009942,
          SpeakNpcId = 700300
        },
        [51009942] = {
          Content = "……后来，当我在维尔莉特病逝后，在颓废的西格面前唱出终于完稿的《普蒂妮》最后一幕时，他的眼里充满惊讶，却又像是在一片死灰中稍稍燃起了火星。",
          DialogueId = 51009942,
          GUID = "7FB2B29C",
          NextDialogue = 51009943,
          SpeakNpcId = 700300
        },
        [51009943] = {
          Content = "我们仍有弥补维尔莉特的机会，她的快乐、她的忧伤、她的希望、她的思念全都寄存在这部作品里。我想让这部作品闻名世界——我可以做到，我也必须做到。",
          DialogueId = 51009943,
          GUID = "7FB2B2C6",
          NextDialogue = 51009944,
          SpeakNpcId = 700300
        },
        [51009944] = {
          Content = "她和我都是为舞台而生的，即便病魔就这样让一位天才陨落，我也要带着她的灵魂踏上舞台。",
          DialogueId = 51009944,
          GUID = "7FB2B2F0",
          NextDialogue = 51009945,
          SpeakNpcId = 700300
        },
        [51009945] = {
          Content = "所以为了让你能够摆脱你父亲的控制，以及实现维尔莉特的遗愿，西格决定配合你演一出戏。",
          DialogueId = 51009945,
          GUID = "7FB2B31A",
          NextDialogue = 51009946,
          SpeakNpcId = 100001
        },
        [51009946] = {
          Camera = "173.006836,-16.306641,127.36377,0.000095,0.999769,158.194092,44.87347,100000.0,true,DoNotOverride,2.8",
          Content = "不……不可能，如果真的是这样，那她刚刚又为什么……",
          DialogueId = 51009946,
          FacialId = {
            [1] = "700302:CM_Shock01"
          },
          GUID = "7FB2B344",
          NextDialogue = 51009947,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Shock_Start"
          }
        },
        [51009947] = {
          Content = "你带着预设好的答案而来，吉赛尔。如果薇奥莱塔女士没有顺着你的意思说下去，她害怕她的学生罗莎琳会遭遇不测。",
          DialogueId = 51009947,
          GUID = "7FB2B36E",
          NextDialogue = 51009948,
          SpeakNpcId = 100001
        },
        [51009948] = {
          Content = "什……",
          DialogueId = 51009948,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2B398",
          NextDialogue = 51009949,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Shock_End"
          }
        },
        [51009949] = {
          Camera = "-158.601562,204.59082,150.237305,0.000071,-3.199944,-50.20327,35.333332,100000.0,true,DoNotOverride,2.8",
          Content = "我有个请求……我不会逃跑的，所以陪我去一个地方走走，可以吗？",
          DialogueId = 51009949,
          GUID = "7FB2B3C2",
          NextOptions = {
            [1] = 510098591
          },
          Scripts = "PlayOrStopBGM{PlayType{\"Stop\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0036_story_renweidaozu\"}}",
          SpeakNpcId = 700300
        },
        [51009950] = {
          Camera = "173.006836,-16.306641,127.36377,0.000095,0.999769,158.194092,44.87347,100000.0,true,DoNotOverride,2.8",
          Content = "可以，但最好不要想耍什么花样。",
          DialogueId = 51009950,
          GUID = "7FB2B3EC",
          LookAt = {
            [1] = "100001:n(700302)"
          },
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Agree"
          }
        },
        [51009951] = {
          Camera = "-257.950684,511.992188,553.037598,0.000167,-36.995567,-61.979073,17.27956,100000.0,true,DoNotOverride,2.8",
          Content = "这里已经重建了，但在我眼里，它的每一寸砖石都还是当年的样子。",
          DialogueId = 51009951,
          FinalCamera = "-156.373047,321.121094,390.135742,0.000167,-36.995567,-61.979073,17.27956,100000.0,true,DoNotOverride,2.8",
          GUID = "7FB2B416",
          LookAt = {
            [1] = "100001:n(700300)",
            [2] = "700302:n(700300)"
          },
          NextDialogue = 51009952,
          SpeakNpcId = 700300,
          ToFinalCameraBlendTime = 5
        },
        [51009952] = {
          Content = "维尔莉特，我又来看你了……和我们的作品一起。",
          DialogueId = 51009952,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2B440",
          LookAt = {
            [1] = "100001:n(700300)"
          },
          NextDialogue = 51009953,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain01_Start"
          }
        },
        [51009953] = {
          Content = "已经有聪明的家伙知道了我们的故事，但不知道为什么，我并不害怕，反而有些轻松。也许是因为我终于可以堂堂正正对你说……西格的事，对不起。",
          DialogueId = 51009953,
          GUID = "7FB2B46A",
          NextDialogue = 51009954,
          SpeakNpcId = 700300
        },
        [51009954] = {
          Content = "（薇奥莱塔的指尖在墙壁上轻轻拂过，像是在和多年不见老友诉说着过往的经历。或许是发觉已经到了应当离别的时候，她才会选择在此刻回到这里。）",
          DialogueId = 51009954,
          GUID = "7FB2B494",
          NextDialogue = 51009955,
          TalkActionId = {
            [1] = "700300:Explain01_End"
          }
        },
        [51009955] = {
          Camera = "-412.794434,216.719727,171.631836,0.000165,-6.39514,-27.7768,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "谢谢你们纵容我的任性……",
          DialogueId = 51009955,
          GUID = "7FB2B4BE",
          NextDialogue = 51009956,
          SpeakNpcId = 700300,
          TurnTo = {
            [1] = "700300:n(700302)"
          }
        },
        [51009956] = {
          Content = "所以，薇奥莱塔，你主动担下罪行还有另一个原因——西格的死并不在你的预料之中，对吗？",
          DialogueId = 51009956,
          GUID = "7FB2B4E8",
          NextDialogue = 51009957,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009957] = {
          Content = "……法布瑞斯·鲁斯福德，那是个冷酷无情的男人。那些矿工因为他几乎食不果腹，手下的卫戍部队也因为他的残暴管理苦不堪言。",
          DialogueId = 51009957,
          GUID = "7FB2B512",
          NextDialogue = 51009958,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Disagree",
            [2] = "100001:Explain01_End"
          }
        },
        [51009958] = {
          Camera = "-412.794434,216.719727,171.631836,0.000165,-6.39514,-27.7768,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "就连自己的亲生女儿，那个男人也不留情面地否定她的一切，践踏她的梦想，禁锢她的自由，强迫那个可怜的孩子按照他规划好的无趣的人生去成长。",
          DialogueId = 51009958,
          FinalCamera = "-134.225342,69.999023,159.965332,0.000165,-6.39514,-27.776773,35.0,100000.0,true,DoNotOverride,2.8",
          GUID = "7FB2B53C",
          NextDialogue = 51009959,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Sigh_Start"
          },
          ToFinalCameraBlendTime = 10
        },
        [51009959] = {
          Content = "可就是这样一个冷酷无情的人，却因为亲生女儿的死，越过了所有的审判流程亲自将绑架犯处决——即使那会让他被名利场上的敌人抓住把柄，最终被解职。",
          DialogueId = 51009959,
          GUID = "7FB2B566",
          NextDialogue = 51009960,
          SpeakNpcId = 700300
        },
        [51009960] = {
          Content = "我设想过无数种方案，要怎么在逃出他的掌控之后，再想办法悄悄把书信送到法庭上去，这样就能把西格救出来。但我唯独没想到……",
          DialogueId = 51009960,
          GUID = "7FB2B590",
          NextDialogue = 51009961,
          SpeakNpcId = 700300
        },
        [51009961] = {
          Content = "你的父亲比你想象中爱你……",
          DialogueId = 51009961,
          GUID = "7FB2B5BA",
          NextDialogue = 51009962,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Talk02_Start"
          }
        },
        [51009962] = {
          Content = "……后来，我无数次想要说出实情，但海伯利亚只是起点，她的作品还需要我传遍整个世界——我必须遵守我的承诺，至少我必须要这么想。",
          DialogueId = 51009962,
          GUID = "7FB2B5E4",
          NextDialogue = 51009963,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Sigh_End",
            [2] = "700302:Talk02_End"
          }
        },
        [51009963] = {
          Content = "所以当你找上我的时候，我反而感到有些轻松……我已经有了很多学生，他们都是拥有天赋的孩子，他们可以代替我把《普蒂妮》带上更多更广阔的舞台。",
          DialogueId = 51009963,
          GUID = "7FB2B60E",
          LookAt = {
            [1] = "700300:n(700302)"
          },
          NextDialogue = 51009964,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Talk02_Start"
          }
        },
        [51009964] = {
          Content = "而你，只需要在这里承认吉赛尔的指控，就可以洗去西格身上本不属于他的罪名。",
          DialogueId = 51009964,
          GUID = "7FB2B638",
          NextDialogue = 51009965,
          SpeakNpcId = 100001
        },
        [51009965] = {
          Content = "……我会跟你走的，吉赛尔。但必须在你放了罗莎琳·马格努斯之后。",
          DialogueId = 51009965,
          FacialId = {
            [1] = "700300:CM_Idle"
          },
          GUID = "7FB2B662",
          NextDialogue = 51009966,
          SpeakNpcId = 700300
        },
        [51009966] = {
          Content = "不管是为了我自己，还是为了西格和维尔莉特，她都绝对不能有事。",
          DialogueId = 51009966,
          GUID = "7FB2B68C",
          NextDialogue = 51009967,
          SpeakNpcId = 700300
        },
        [51009967] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,true,DoNotOverride,2.8",
          Content = "……她已经离开冰湖城了。",
          DialogueId = 51009967,
          GUID = "7FB2B6B6",
          LookAt = {
            [1] = "100001:n(700302)"
          },
          NextDialogue = 51009968,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Talk01_Start",
            [2] = "700300:Talk02_End"
          }
        },
        [51009968] = {
          Camera = "-134.225342,69.999023,159.965332,0.000165,-6.39514,-27.776773,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "什么？",
          DialogueId = 51009968,
          FacialId = {
            [1] = "700300:CM_Shock01"
          },
          GUID = "7FB2B6E0",
          NextDialogue = 51009969,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Shock_Start"
          }
        },
        [51009969] = {
          Camera = "-156.373047,321.121094,390.135742,0.000167,-36.995567,-61.979073,17.27956,100000.0,true,DoNotOverride,2.8",
          Content = "既然你作为声乐老师和她的父母打过交道，就应该知道她所面临的处境。",
          DialogueId = 51009969,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2B70A",
          NextDialogue = 51009970,
          SpeakNpcId = 700302
        },
        [51009970] = {
          Content = "雏鸟为了摆脱囚笼不惜折断翅膀，作为师徒，你们两个倒是如出一辙。",
          DialogueId = 51009970,
          GUID = "7FB2B734",
          NextDialogue = 51009971,
          SpeakNpcId = 700302
        },
        [51009971] = {
          Content = "原来你从一开始就在骗我……",
          DialogueId = 51009971,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2B75E",
          NextDialogue = 51009972,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Shock_End"
          }
        },
        [51009972] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,true,DoNotOverride,2.8",
          Content = "我也不会想到会和你关系如此密切的人会突然跑过来雇我“绑架”她，我只是利用下这小小的巧合罢了。",
          DialogueId = 51009972,
          GUID = "7FB2B788",
          NextDialogue = 51009973,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51009973] = {
          Content = "怎么样，我的演技是不是也还不错？是时候考虑接下来要不要转行了。",
          DialogueId = 51009973,
          GUID = "7FB2B7B2",
          NextDialogue = 51009974,
          SpeakNpcId = 700302
        },
        [51009974] = {
          Camera = "-204.130859,4.202148,148.053223,0.000166,-3.794798,6.829297,41.877083,100000.0,true,DoNotOverride,2.8",
          Content = "吉赛尔不打算做狩月人了？",
          DialogueId = 51009974,
          FacialId = {
            [1] = "100001:Happy01"
          },
          GUID = "7FB2B7DC",
          NextDialogue = 51009975,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51009975] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,true,DoNotOverride,2.8",
          Content = "呵，也多亏了马格努斯家大小姐的绑架案闹得满城风雨，接下来很长一段时间我也得避避风头了。",
          DialogueId = 51009975,
          GUID = "7FB2B806",
          NextDialogue = 51009976,
          SpeakNpcId = 700302
        },
        [51009976] = {
          Content = "至于薇奥莱塔……",
          DialogueId = 51009976,
          GUID = "7FB2B830",
          NextDialogue = 51009977,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "100001:Talk02R_End"
          }
        },
        [51009977] = {
          Camera = "-204.130859,4.202148,148.053223,0.000166,-3.794798,6.829297,41.877083,100000.0,true,DoNotOverride,2.8",
          Content = "{nickname}，你来做决定吧。既然你比我先一步查清真相，就由你来选择怎么处置她吧。",
          DialogueId = 51009977,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2B85A",
          LookAt = {
            [1] = "700300:n(100001)"
          },
          NextDialogue = 51009978,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_End"
          }
        },
        [51009978] = {
          Content = "这样就好吗，吉赛尔？",
          DialogueId = 51009978,
          GUID = "7FB2B884",
          NextDialogue = 51009979,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51009979] = {
          Camera = "-62.87207,113.884766,154.009766,0.000172,-4.994904,-44.169758,41.877083,100000.0,true,DoNotOverride,2.8",
          Content = "我不知道。<H>揭露真相，她也许会因当年的欺骗行径名誉扫地，无法再登台演出。隐瞒真相，那西格的冤屈……</>",
          DialogueId = 51009979,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2B8AE",
          NextDialogue = 51009980,
          SpeakNpcId = 700302
        },
        [51009980] = {
          Content = "我现在脑子很乱，或许现在让你做决定才是正确的选择。",
          DialogueId = 51009980,
          GUID = "7FB2B8D8",
          NextDialogue = 51009981,
          SpeakNpcId = 700302
        },
        [51009981] = {
          Content = "如果是你做出的决定……我会接受的。",
          DialogueId = 51009981,
          GUID = "7FB2B902",
          NextOptions = {
            [1] = 510098911,
            [2] = 510098912
          },
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Agree"
          },
          bForbidSkipOptions = true
        },
        [51009982] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,true,DoNotOverride,2.8",
          Content = "吉赛尔。",
          DialogueId = 51009982,
          GUID = "7FB2B92C",
          LookAt = {
            [1] = "100001:n(700302)"
          },
          NextDialogue = 51009983,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700302:Talk03_Start"
          }
        },
        [51009983] = {
          Content = "说吧，我在听。",
          DialogueId = 51009983,
          GUID = "7FB2B956",
          NextDialogue = 51009984,
          SpeakNpcId = 700302
        },
        [51009984] = {
          Camera = "-204.130859,4.202148,148.053223,0.000166,-3.794798,6.829297,41.877083,100000.0,true,DoNotOverride,2.8",
          Content = "可不可以就这样维持现状，不去揭发薇奥莱塔女士？",
          DialogueId = 51009984,
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "7FB2B980",
          NextDialogue = 51009985,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          }
        },
        [51009985] = {
          Camera = "-134.225342,69.999023,159.965332,0.000165,-6.39514,-27.776773,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "西格愿意牺牲自己的生命和名誉让薇奥莱塔女士将《普蒂妮》传唱，这应该不是他希望看到的局面。",
          DialogueId = 51009985,
          GUID = "7FB2B9AA",
          NextDialogue = 51009986,
          SpeakNpcId = 100001
        },
        [51009986] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,true,DoNotOverride,2.8",
          Content = "……我明白了。",
          DialogueId = 51009986,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2B9D4",
          NextDialogue = 51009987,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Agree",
            [2] = "100001:Explain02_End"
          }
        },
        [51009987] = {
          Content = "吉赛尔？",
          DialogueId = 51009987,
          GUID = "7FB2B9FE",
          NextDialogue = 51009988,
          SpeakNpcId = 700300
        },
        [51009988] = {
          Content = "是我把选择的权利交给了你，自然会尊重你的选择。",
          DialogueId = 51009988,
          GUID = "7FB2BA28",
          NextDialogue = 51009989,
          SpeakNpcId = 700302
        },
        [51009989] = {
          Camera = "-412.794434,216.719727,171.631836,0.000165,-6.39514,-27.7768,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "感激不尽。",
          DialogueId = 51009989,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2BA52",
          LookAt = {
            [1] = "100001:n(700300)"
          },
          NextDialogue = 51009990,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51009990] = {
          Content = "那看来已经达成共识了。",
          DialogueId = 51009990,
          GUID = "7FB2BA7C",
          NextDialogue = 51009991,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51009991] = {
          Camera = "-156.373047,321.121094,390.135742,0.000167,-36.995567,-61.979073,17.27956,100000.0,true,DoNotOverride,2.8",
          Content = "对了，不知道二位可否赏光来看两天后的演出，我会为二位准备特等席。",
          DialogueId = 51009991,
          GUID = "7FB2BAA6",
          NextDialogue = 51009992,
          SpeakNpcId = 700300
        },
        [51009992] = {
          Content = "演出吗……",
          DialogueId = 51009992,
          GUID = "7FB2BAD0",
          NextDialogue = 51009993,
          SpeakNpcId = 700302
        },
        [51009993] = {
          Content = "嗯，是《普蒂妮》。就当是我给那个孩子的送行演出吧，这是她最喜欢的剧目。",
          DialogueId = 51009993,
          GUID = "7FB2BAFA",
          NextDialogue = 51010006,
          SpeakNpcId = 700300
        },
        [51009994] = {
          Camera = "-62.87207,113.884766,154.009766,0.000172,-4.994904,-44.169758,41.877083,100000.0,true,DoNotOverride,2.8",
          Content = "我理解你的做法，薇奥莱塔女士。可我们不该让一个已经逝去的生命从此只能以杀人犯的身份被他人想起。",
          DialogueId = 51009994,
          GUID = "7FB2BB24",
          LookAt = {
            [1] = "700300:n(100001)"
          },
          NextDialogue = 51009995,
          Scripts = [[
SEQ{
TurnTo{TurnToDescription{"100001:n(700300)"}},
PlayAnimation{ActorId{100001},AnimationId{"Talk01_Start"},Duration{1}}
}]],
          SpeakNpcId = 100001
        },
        [51009995] = {
          Content = "虽然西格已经不在了，但至少我们还有能力还他清白。",
          DialogueId = 51009995,
          GUID = "7FB2BB4E",
          NextDialogue = 51009996,
          SpeakNpcId = 100001
        },
        [51009996] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,true,DoNotOverride,2.8",
          Content = "{nickname}……谢谢。",
          DialogueId = 51009996,
          GUID = "7FB2BB78",
          NextDialogue = 51009997,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "100001:Talk01_End"
          }
        },
        [51009997] = {
          Content = "西格的确出于金钱目的绑架了你，但和他的罪行相比一条人命还是太过沉重了，我们应该真相公之于众。",
          DialogueId = 51009997,
          GUID = "7FB2BBA2",
          NextDialogue = 51009998,
          SpeakNpcId = 100001
        },
        [51009998] = {
          Camera = "-62.87207,113.884766,154.009766,0.000172,-4.994904,-44.169758,41.877083,100000.0,true,DoNotOverride,2.8",
          Content = "薇奥莱塔女士，这件事一经公开，恐怕你的事业会受到影响。",
          DialogueId = 51009998,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2BBCC",
          NextDialogue = 51009999,
          SpeakNpcId = 100001
        },
        [51009999] = {
          Content = "我明白，不过这样就好……抱歉，维尔莉特，我们的梦想只能拜托给那些孩子们了。",
          DialogueId = 51009999,
          GUID = "7FB2BBF6",
          NextDialogue = 51010000,
          SpeakNpcId = 700300
        },
        [51010000] = {
          Camera = "-412.794434,216.719727,171.631836,0.000165,-6.39514,-27.7768,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "那看来已经达成共识了。",
          DialogueId = 51010000,
          GUID = "7FB2BC20",
          LookAt = {
            [1] = "700300:n(700302)"
          },
          NextDialogue = 51010001,
          SpeakNpcId = 700302
        },
        [51010001] = {
          Content = "还有一件事……",
          DialogueId = 51010001,
          GUID = "7FB2BC4A",
          NextDialogue = 51010002,
          SpeakNpcId = 700300
        },
        [51010002] = {
          Content = "嗯哼？现在反悔可来不及了。",
          DialogueId = 51010002,
          GUID = "7FB2BC74",
          NextDialogue = 51010003,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010003] = {
          Camera = "-156.373047,321.121094,390.135742,0.000167,-36.995567,-61.979073,17.27956,100000.0,true,DoNotOverride,2.8",
          Content = "怎么会呢，我只是想邀请二位来看两天后的演出，就当是我的告别演出吧。我会为二位准备特等席。",
          DialogueId = 51010003,
          GUID = "7FB2BC9E",
          NextDialogue = 51010004,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51010004] = {
          Content = "告别演出啊……",
          DialogueId = 51010004,
          GUID = "7FB2BCC8",
          NextDialogue = 51010005,
          SpeakNpcId = 700302
        },
        [51010005] = {
          Content = "嗯，是《普蒂妮》。从这部戏开始也从这部戏结束，也算是有始有终。",
          DialogueId = 51010005,
          GUID = "7FB2BCF2",
          NextDialogue = 51010006,
          SpeakNpcId = 700300
        },
        [51010006] = {
          Content = "我会去的。",
          DialogueId = 51010006,
          GUID = "7FB2BD1C",
          NextDialogue = 51010007,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Agree"
          }
        },
        [51010007] = {
          Content = "特等席准备一个就行了。",
          DialogueId = 51010007,
          GUID = "7FB2BD46",
          NextDialogue = 51010008,
          SpeakNpcId = 700302
        },
        [51010008] = {
          Content = "…………",
          DialogueId = 51010008,
          GUID = "7FB2BD70",
          NextDialogue = 51010009,
          SpeakNpcId = 700300
        },
        [51010009] = {
          Content = "别误会，我会去捧场的。不过我好歹也是半个通缉犯，看个戏还是不要那么招摇了。",
          DialogueId = 51010009,
          GUID = "7FB2BD9A",
          NextDialogue = 51010010,
          SpeakNpcId = 700302
        },
        [51010010] = {
          Content = "明白了，我这就让剧团去安排。",
          DialogueId = 51010010,
          GUID = "7FB2BDC4",
          NextDialogue = 51010011,
          SpeakNpcId = 700300
        },
        [51010011] = {
          Content = "那么，我们两天后见。",
          DialogueId = 51010011,
          GUID = "7FB2BDEE",
          SpeakNpcId = 700300
        },
        [51010012] = {
          Camera = "-257.685547,-253.308594,133.213379,0.000042,-0.199585,40.001606,38.587292,100000.0,true,DoNotOverride,2.8",
          Content = "早上好，薇奥莱塔女士。",
          DialogueId = 51010012,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB2BE18",
          NextDialogue = 51010013,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51010013] = {
          Content = "你们来了，给，这是你们二位的门票。",
          DialogueId = 51010013,
          GUID = "7FB2BE42",
          NextDialogue = 51010014,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Give",
            [2] = "100001:Talk02_End"
          }
        },
        [51010014] = {
          Content = "那我就不客气了。",
          DialogueId = 51010014,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2BE6C",
          NextDialogue = 51010015,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010015] = {
          Camera = "-182.809326,149.35498,133.001709,0.000049,-0.999878,-49.996906,35.520077,340.13559,true,Manual,2.8",
          Content = "请便，让《普蒂妮》传遍世界是维尔莉特的遗愿，只是少收两张票而已，她不会有意见的。",
          DialogueId = 51010015,
          GUID = "7FB2BE96",
          NextDialogue = 51010016,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51010016] = {
          Content = "只是……",
          DialogueId = 51010016,
          GUID = "7FB2BEC0",
          NextDialogue = 51010017,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51010017] = {
          Content = "你在想罗莎琳小姐吗？",
          DialogueId = 51010017,
          GUID = "7FB2BEEA",
          NextDialogue = 51010018,
          SpeakNpcId = 100001
        },
        [51010018] = {
          Content = "嗯，虽说是给她的送行演出，但我也不知道她是否还在冰湖城中，能否看到这场她最喜欢的戏。",
          DialogueId = 51010018,
          GUID = "7FB2BF14",
          LookAt = {
            [1] = "100001:n(700302)",
            [2] = "700300:n(700302)"
          },
          NextDialogue = 51010019,
          SpeakNpcId = 700300
        },
        [51010019] = {
          Camera = "-257.685547,-253.308594,133.213379,0.000042,-0.199585,40.001564,38.587292,100000.0,true,DoNotOverride,2.8",
          Content = "别看我啊，为了不让她再被父母抓回去，连我也不知道她现在的行踪。",
          DialogueId = 51010019,
          FacialId = {
            [1] = "700302:CM_Shock01"
          },
          GUID = "7FB2BF3E",
          NextOptions = {
            [1] = 510099291,
            [2] = 510099292
          },
          SpeakNpcId = 700302
        },
        [51010020] = {
          Camera = "-182.809326,149.35498,133.001709,0.000049,-0.999878,-49.996906,35.520077,340.13559,true,Manual,2.8",
          Content = "但愿如此。",
          DialogueId = 51010020,
          FacialId = {
            [1] = "700302:CM_Idle",
            [2] = "700300:CM_Smile01"
          },
          GUID = "7FB2BF68",
          SpeakNpcId = 700300
        },
        [51010021] = {
          Content = "你能将三件看似毫无关联的事件联系在一起，并书写这场皆大欢喜的结局，你的聪慧和行动力令我惊叹。",
          DialogueId = 51010021,
          GUID = "7FB2BF92",
          NextDialogue = 51010022,
          SpeakNpcId = 700300
        },
        [51010022] = {
          Content = "所以，我有另一个重要的委托，希望你可以接下。事关我的另一位学生，报酬不是问题，等你得空了，来剧院找我就好。",
          DialogueId = 51010022,
          GUID = "7FB2BFBC",
          NextDialogue = 51010023,
          SpeakNpcId = 700300
        },
        [51010023] = {
          Content = "不过无需在今夜——今夜属于歌曲和远航。愿二位抛却烦恼，度过一个美妙的假日。",
          DialogueId = 51010023,
          GUID = "7FB2BFE6",
          SpeakNpcId = 700300
        },
        [51010024] = {
          Content = "你找到了薇奥莱塔为你安排的座位，在观众席等待着演出开场。",
          DialogueId = 51010024,
          GUID = "7FB2C010",
          NextDialogue = 51010025
        },
        [51010025] = {
          Content = "随着看台的灯光逐渐熄灭，洪亮的女声唱白带着你的期待与好奇从幕布后侵染到整个演出厅。",
          DialogueId = 51010025,
          GUID = "7FB2C03A",
          NextDialogue = 51010026
        },
        [51010026] = {
          Content = "看台下异常安静，尚未习惯这种环境的你稍稍有些不安。",
          DialogueId = 51010026,
          GUID = "7FB2C064",
          NextDialogue = 51010027
        },
        [51010027] = {
          Content = "控制住对精彩桥段的赞美并非易事，你害怕自己无意识的感叹扰了他人雅兴。",
          DialogueId = 51010027,
          GUID = "7FB2C08E",
          NextDialogue = 51010028
        }
      }
    end
  },
  {
