        [51010068] = {
          Content = "早上好，{nickname}，怎么看起来不太开心？",
          DialogueId = 51010068,
          GUID = "7FB2C748",
          NextDialogue = 51010069,
          SpeakNpcId = 700300
        },
        [51010069] = {
          Content = "薇奥莱塔女士……",
          DialogueId = 51010069,
          GUID = "7FB2C772",
          NextDialogue = 51010070,
          SpeakNpcId = 100001
        },
        [51010070] = {
          Camera = "-182.809326,149.35498,133.001709,0.000049,-0.999878,-49.996906,35.520077,340.13559,true,Manual,2.8",
          Content = "好啦，不用再说了。明明要退休的是我，怎么反倒是你在难过。",
          DialogueId = 51010070,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2C79C",
          NextDialogue = 51010071,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Disagree"
          }
        },
        [51010071] = {
          Content = "你只是做出了每一个坚守底线的人会做出的选择，不要为此有负担。就当是帮忙抓到了一个离家出走的孩子，好吗？",
          DialogueId = 51010071,
          GUID = "7FB2C7C6",
          NextDialogue = 51010072,
          SpeakNpcId = 700300
        },
        [51010072] = {
          Camera = "-257.685547,-253.308594,133.213379,0.000042,-0.199585,40.001606,38.587292,100000.0,true,DoNotOverride,2.8",
          Content = "看来人都到齐了？",
          DialogueId = 51010072,
          GUID = "7FB2C7F0",
          NextDialogue = 51010073,
          Scripts = "MoveTo{ActorId{700302},TargetPoint{\"GisellePoint_20023305\"},MoveSpeed{150},Visibility{\"Show\"}}",
          SpeakNpcId = 700302
        },
        [51010073] = {
          Content = "吉赛尔女士也来了，给，这是二位的门票。",
          DialogueId = 51010073,
          GUID = "7FB2C81A",
          NextDialogue = 51010074,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Give"
          }
        },
        [51010074] = {
          Content = "那我就不客气了。已经和卫戍部队的朋友们打过招呼了，直到演出结束前他们都不会有动作。",
          DialogueId = 51010074,
          GUID = "7FB2C844",
          NextDialogue = 51010075,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010075] = {
          Content = "非常感谢。演出快要开始了，我先失陪去后台了。",
          DialogueId = 51010075,
          GUID = "7FB2C86E",
          NextDialogue = 51010076,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51010076] = {
          Content = "那我们也进去吧，虽然好像是我导致的，不过薇奥莱塔的告别演出的确让人期待。",
          DialogueId = 51010076,
          GUID = "7FB2C898",
          LookAt = {
            [1] = "100001:n(700302)",
            [2] = "700302:n(100001)"
          },
          NextDialogue = 51010077,
          SpeakNpcId = 700302
        },
        [51010077] = {
          Content = "好。",
          DialogueId = 51010077,
          GUID = "7FB2C8C2",
          SpeakNpcId = 100001
        },
        [51010078] = {
          Content = "你找到了薇奥莱塔为你安排的座位，在观众席等待着演出开场。",
          DialogueId = 51010078,
          GUID = "7FB2C8EC",
          NextDialogue = 51010079
        },
        [51010079] = {
          Content = "随着看台的灯光逐渐熄灭，洪亮的女声唱白带着你的期待与好奇从幕布后侵染到整个演出厅。",
          DialogueId = 51010079,
          GUID = "7FB2C916",
          NextDialogue = 51010080
        },
        [51010080] = {
          Content = "看台下异常安静，尚未习惯这种环境的你稍稍有些不安。",
          DialogueId = 51010080,
          GUID = "7FB2C940",
          NextDialogue = 51010081
        },
        [51010081] = {
          Content = "控制住对精彩桥段的赞美并非易事，你害怕自己无意识的感叹扰了他人雅兴。",
          DialogueId = 51010081,
          GUID = "7FB2C96A",
          NextDialogue = 51010082
        },
        [51010082] = {
          Content = "不过这种担忧是多余的——",
          DialogueId = 51010082,
          GUID = "7FB2C994",
          NextDialogue = 51010083
        },
        [51010083] = {
          Content = "为剧中人所牵动的你甚至忘记了鼓掌，直至演出结束……",
          DialogueId = 51010083,
          GUID = "7FB2C9BE"
        },
        [51010084] = {
          Camera = "-34.440796,-11.397461,144.465332,0.000003,0.80015,-179.606598,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "吉赛尔，我需要你给我一个解释！",
          DialogueId = 51010084,
          FacialId = {
            [1] = "700304:CM_Angry01"
          },
          GUID = "7FB2C9E8",
          NextDialogue = 51010085,
          SpeakNpcId = 700304,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "700304:Angry01_Start"
          }
        },
        [51010085] = {
          Camera = "-446.109863,-216.286133,176.425781,0.000133,-6.999605,41.589813,60.202423,100000.0,true,DoNotOverride,2.8",
          Content = "哦？无所不知的法布瑞斯大人，有什么事是需要我来给你解释的？",
          DialogueId = 51010085,
          GUID = "7FB2CA12",
          NextDialogue = 51010086,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010086] = {
          Content = "是你举报了薇奥莱塔就是艾诺拉，可我带人来到了后台，那里一个人也没有！",
          DialogueId = 51010086,
          GUID = "7FB2CA3C",
          NextDialogue = 51010087,
          SpeakNpcId = 700304
        },
        [51010087] = {
          Content = "是这件事啊……没想到您居然亲自来了，真是负责任的长官。",
          DialogueId = 51010087,
          FacialId = {
            [1] = "700302:CM_Happy01"
          },
          GUID = "7FB2CA66",
          NextDialogue = 51010088,
          SpeakNpcId = 700302
        },
        [51010088] = {
          Content = "别跟我阴阳怪气！我命令你，马上带我找到艾诺拉！",
          DialogueId = 51010088,
          GUID = "7FB2CA90",
          NextDialogue = 51010089,
          SpeakNpcId = 700304
        },
        [51010089] = {
          Content = "您似乎忘了一件事，我现在已经不是卫戍部队的人了，您也不是。我只是作为一介平民向卫戍部队提供了一些线索而已。",
          DialogueId = 51010089,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2CABA",
          NextDialogue = 51010090,
          SpeakNpcId = 700302
        },
        [51010090] = {
          Content = "所以我没有义务听从你的命令，噢，也许你可以给“狩月人吉赛尔”发一份委托？",
          DialogueId = 51010090,
          GUID = "7FB2CAE4",
          NextDialogue = 51010091,
          SpeakNpcId = 700302
        },
        [51010091] = {
          Camera = "-34.440796,-11.397461,144.465332,0.000003,0.80015,-179.606598,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "你……！发委托就发委托！",
          DialogueId = 51010091,
          GUID = "7FB2CB0E",
          NextDialogue = 51010092,
          SpeakNpcId = 700304,
          TalkActionId = {
            [1] = "700302:Confident_End"
          }
        },
        [51010092] = {
          Camera = "-446.109863,-216.286133,176.425781,0.000133,-6.999605,41.589813,60.202423,100000.0,true,DoNotOverride,2.8",
          Content = "好的，我不接。",
          DialogueId = 51010092,
          FacialId = {
            [1] = "700302:CM_Happy01"
          },
          GUID = "7FB2CB38",
          NextDialogue = 51010093,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Talk01_Start"
          }
        },
        [51010093] = {
          Content = "你耍我？！",
          DialogueId = 51010093,
          GUID = "7FB2CB62",
          NextDialogue = 51010094,
          SpeakNpcId = 700304
        },
        [51010094] = {
          Content = "毕竟我现在有绑架伯爵千金的嫌疑，狩月人业务也只能暂停咯。",
          DialogueId = 51010094,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2CB8C",
          NextDialogue = 51010095,
          SpeakNpcId = 700302
        },
        [51010095] = {
          Content = "说到底，如果当年您老老实实听从我的建议推进谈判，如今也不会有这么多麻烦事。",
          DialogueId = 51010095,
          GUID = "7FB2CBB6",
          NextDialogue = 51010096,
          SpeakNpcId = 700302
        },
        [51010096] = {
          Camera = "-34.440796,-11.397461,144.465332,0.000003,0.80015,-179.606598,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "你这女人……算我瞎了眼，居然信了你能找到艾诺拉。",
          DialogueId = 51010096,
          GUID = "7FB2CBE0",
          NextDialogue = 51010097,
          SpeakNpcId = 700304,
          TalkActionId = {
            [1] = "700302:Talk01_End"
          }
        },
        [51010097] = {
          Content = "艾诺拉……我的女儿，我会找到你的……至于你，以后别再让我看到你！",
          DialogueId = 51010097,
          GUID = "7FB2CC0A",
          NextDialogue = 51010098,
          SpeakNpcId = 700304
        },
        [51010098] = {
          Camera = "-446.109863,-216.286133,176.425781,0.000133,-6.999605,41.589813,60.202423,100000.0,true,DoNotOverride,2.8",
          Content = "求之不得。",
          DialogueId = 51010098,
          GUID = "7FB2CC34",
          NextDialogue = 51010099,
          Scripts = "MoveTo{ActorId{700304},TargetPoint{\"FabricePoint_20023305\"},MoveSpeed{150},Visibility{\"Hide\"}}",
