          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Nvzhu_Story_StretchHand_Start"
          }
        },
        [51010114] = {
          Content = "——送给你了！！",
          DialogueId = 51010114,
          GUID = "7FB2CED4",
          NextDialogue = 51010115,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          TalkActionId = {
            [1] = "100001:Nvzhu_Story_StretchHand_End"
          }
        },
        [51010115] = {
          Camera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "现在的年轻人还真是风风火火。",
          DialogueId = 51010115,
          GUID = "7FB2CEFE",
          LookAt = {
            [1] = "700302:n(100001)",
            [2] = "100001:n(700302)"
          },
          NextDialogue = 51010116,
          SpeakNpcId = 700302
        },
        [51010116] = {
          Content = "说什么送给我了……这上面好像绣了字，是那个女孩的名字吗？",
          DialogueId = 51010116,
          FacialId = {
            [1] = "100001:Doubt01",
