          GUID = "7FB2CFA6",
          NextDialogue = 51010120,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51010120] = {
          Content = "……普蒂妮？",
          DialogueId = 51010120,
          GUID = "7FB2CFD0",
          NextDialogue = 51010121,
          SpeakNpcId = 100001
        },
        [51010121] = {
          Content = "如果你以后遇到了一个叫普蒂妮的女孩，请一定要认出我，我也一定会认出你的。",
          DialogueId = 51010121,
          GUID = "7FB2CFFA",
          IsBlack = 1,
          NextDialogue = 51010122
        },
        [51010122] = {
          Content = "原来是这样啊，看来箱子小姐她平安踏上自己的旅途了。这么说来你是——",
          DialogueId = 51010122,
          GUID = "7FB2D024",
          NextDialogue = 51010123,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51010123] = {
          Camera = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "嘘——虽然我认可你们的揭发，但还是会保守秘密的孩子更可爱哦。",
          DialogueId = 51010123,
          GUID = "7FB2D04E",
          NextDialogue = 51010124,
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "700311:Disagree"
          }
        },
        [51010124] = {
          Content = "就这么暴露身份，你不怕我再找麻烦？",
          DialogueId = 51010124,
          GUID = "7FB2D078",
          NextDialogue = 51010125,
          SpeakNpcId = 700302
        },
        [51010125] = {
          Content = "“薇奥莱塔”不会再登台，可我短期内并不打算离开这里。当然，就算你再次揭发，我也不会有怨言。只是事关我的另一位学生，我无法弃之不顾。",
          DialogueId = 51010125,
          GUID = "7FB2D0A2",
          NextDialogue = 51010126,
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51010126] = {
          Content = "……",
          DialogueId = 51010126,
          GUID = "7FB2D0CC",
          NextDialogue = 51010127,
          SpeakNpcId = 700302
        },
        [51010127] = {
          Content = "……感谢你的沉默。",
          DialogueId = 51010127,
          FacialId = {
            [1] = "700311:CM_Happy01"
          },
          GUID = "7FB2D0F6",
          NextDialogue = 51010128,
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "700311:Agree"
          }
        },
        [51010128] = {
          Content = "那么失陪了，愿二位度过一个美妙的假日。",
          DialogueId = 51010128,
          GUID = "7FB2D120",
          NextDialogue = 51010129,
          Scripts = "MoveTo{ActorId{700311},TargetPoint{\"RosalindPoint2_20023305\"},MoveSpeed{150},Visibility{\"Hide\"}}",
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51010129] = {
          Camera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,true,DoNotOverride,2.8",
          Content = "哈，我就知道，那样的女人怎么可能乖乖束手就擒。",
          DialogueId = 51010129,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2D14A",
          LookAt = {
            [1] = "700302:n(100001)",
            [2] = "100001:n(700302)"
          },
          NextDialogue = 51010130,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010130] = {
          Content = "你看起来好像有点高兴？",
          DialogueId = 51010130,
          GUID = "7FB2D174",
          NextDialogue = 51010131,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51010131] = {
          Content = "这样吗？说实话，我也纠结过到底要不要牺牲活人的生活去换死者的清白……",
          DialogueId = 51010131,
          GUID = "7FB2D19E",
          NextDialogue = 51010132,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "100001:Talk02R_End"
          }
        },
        [51010132] = {
          Content = "如你所见，我做出了选择，这是吉赛尔的执着。",
          DialogueId = 51010132,
          GUID = "7FB2D1C8",
          NextDialogue = 51010133,
          SpeakNpcId = 700302
        },
        [51010133] = {
          Content = "不过既然能在二选一的局面被打破后而感到开心，说明我这十六年来也有了成长不是吗？",
          DialogueId = 51010133,
          FacialId = {
            [1] = "700302:CM_Sad01"
          },
          GUID = "7FB2D1F2",
          NextDialogue = 51010134,
          SpeakNpcId = 700302
        },
        [51010134] = {
          Content = "要是十六年前的我也能像现在一样，或许就不会有人因此逝去了。",
          DialogueId = 51010134,
          GUID = "7FB2D21C",
          NextDialogue = 51010135,
          SpeakNpcId = 700302
        },
        [51010135] = {
          Content = "这不是你的错，吉赛尔。",
          DialogueId = 51010135,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB2D246",
          NextDialogue = 51010136,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Disagree"
          }
        },
        [51010136] = {
          Content = "放心，我没有难过，我只是在想“狩月人吉赛尔”歇业后要去做点什么。",
          DialogueId = 51010136,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2D270",
          NextDialogue = 51010137,
          SpeakNpcId = 700302
        },
        [51010137] = {
          Content = "我放弃当演员了，看过薇奥莱塔的演出之后很难再夸下这种海口啊……",
          DialogueId = 51010137,
          GUID = "7FB2D29A",
          NextOptions = {
            [1] = 510100471,
            [2] = 510100472
          },
          SpeakNpcId = 700302
        },
        [51010138] = {
          Content = "因为感觉很赚钱。",
          DialogueId = 51010138,
          FacialId = {
            [1] = "700302:CM_Happy01"
          },
          GUID = "7FB2D2C4",
          NextDialogue = 51010140,
          SpeakNpcId = 700302
        },
        [51010139] = {
          Content = "就别挖苦我了，真正的神探。",
          DialogueId = 51010139,
          GUID = "7FB2D2EE",
          NextDialogue = 51010140,
          SpeakNpcId = 700302
        },
        [51010140] = {
          Content = "那现在呢，你打算做什么？",
          DialogueId = 51010140,
          GUID = "7FB2D318",
          NextDialogue = 51010141,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51010141] = {
          Content = "嗯……不知道。不过反正时间还有很多，我会慢慢想。",
          DialogueId = 51010141,
          FacialId = {
            [1] = "700302:CM_Happy01"
          },
          GUID = "7FB2D342",
          NextDialogue = 51010142,
          SpeakNpcId = 700302
        },
        [51010142] = {
          Content = "毕竟舞台那么大，总会找到适合自己的那个角色的。",
          DialogueId = 51010142,
          GUID = "7FB2D36C",
          SpeakNpcId = 700302
        },
        [51010143] = {
          Camera = "-19.636719,461.339844,156.540039,0.000053,-6.400208,-95.20314,35.333332,100000.0,true,DoNotOverride,2.8",
          Content = "请等一下！",
          DialogueId = 51010143,
          FacialId = {
            [1] = "700300:CM_Smile01",
            [2] = "700302:CM_Angry01",
            [3] = "100001:Angry01"
          },
          GUID = "7FB2AA92",
          NextDialogue = 51009894,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Nvzhu_Story_StretchHand_Start"
          }
        },
        [51010201] = {
          Content = "♪熔炉焚烧黎明 倾倒出白雪与铁的城塞……",
          DialogueId = 51010201,
          GUID = "7FB2DD1A",
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/env/700342/7FB2DD1A"
        },
        [51010202] = {
          Content = "♪熔炉焚烧黎明 倾倒出白雪与铁的城塞\n齿轮高歌 吞没晨星 赞颂北地的伟大时代——",
          DialogueId = 51010202,
          GUID = "7FB2DD44",
          NextDialogue = 51010203,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DD44"
        },
        [51010203] = {
          Content = "嗯？你叫我……",
          DialogueId = 51010203,
          GUID = "7FB2DD6E",
          LookAt = {
            [1] = "700342:n(0)"
          },
          NextOptions = {
            [1] = 510102031,
            [2] = 510102032
          },
          SpeakNpcId = 700342,
          TalkActionId = {
            [1] = "700342:Lilikou_Story_Playlyre_End"
          },
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DD6E"
        },
        [51010204] = {
          Content = "谢谢你，陌生的旅人！不过这首歌还没有完成，或许你可以和我一起来创作它。",
          DialogueId = 51010204,
          GUID = "7FB2DD98",
          NextDialogue = 51010206,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DD98"
        },
        [51010205] = {
          Content = "很抱歉打扰到你！不过我问过那边的士兵，这座城市的广场并没有张贴律令，禁止一位吟游诗人在这里唱歌。",
          DialogueId = 51010205,
          GUID = "7FB2DDC2",
          NextDialogue = 51010206,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DDC2"
        },
        [51010206] = {
          Content = "后一句应该是什么呢……",
          DialogueId = 51010206,
          GUID = "7FB2DDEC",
          NextDialogue = 51010207,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DDEC"
        },
        [51010207] = {
          Content = "我想我应该写“风”……每个地方的风都是不同的……",
          DialogueId = 51010207,
          GUID = "7FB2DE16",
          NextDialogue = 51010208,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DE16"
        },
        [51010208] = {
          Content = "艾利西安的风是融化在晚祷里的乳香，卢卡的风是画室的松节油和咖啡店的焦糖，伊瑟尔的风是混着野薄荷的油墨……",
          DialogueId = 51010208,
          GUID = "7FB2DE40",
          NextDialogue = 51010209,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DE40"
        },
        [51010209] = {
          Content = "那么海伯利亚的“风”是什么呢？",
          DialogueId = 51010209,
          GUID = "7FB2DE6A",
          NextOptions = {
            [1] = 510102091,
            [2] = 510102092,
            [3] = 510102093
          },
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DE6A"
        },
        [51010210] = {
          Content = "嗯……你说的有道理。这里有很多钢铁的森林，就像这座城市一样。",
          DialogueId = 51010210,
          GUID = "7FB2DE94",
          NextDialogue = 51010211,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DE94"
        },
        [51010211] = {
          Content = "虽然吹起来有些冷，但风会捎来那些齿轮和引擎的声音，它们摸起来总是滚烫的。",
          DialogueId = 51010211,
          GUID = "7FB2DEBE",
          NextDialogue = 51010212,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DEBE"
        },
        [51010212] = {
          Content = "士兵的枪管或许也是滚烫的，虽然他们的表情是冷的……",
          DialogueId = 51010212,
          GUID = "7FB2DEE8",
          NextDialogue = 51010220,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DEE8"
        },
        [51010213] = {
          Content = "嗯！这座城市的四分之三是由雪组成的。因为这里的人说，冰湖城总是在下雪，融雪季只有短短的三个月~",
          DialogueId = 51010213,
          GUID = "7FB2DF12",
          NextDialogue = 51010214,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DF12"
        },
        [51010214] = {
          Content = "而且风和雪总是在一起的，这是大自然给我们的经典搭配！",
          DialogueId = 51010214,
          GUID = "7FB2DF3C",
          NextDialogue = 51010220,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DF3C"
        },
        [51010215] = {
          Content = "“眼泪”吗……是这首歌前面没有用过的意象呢……",
          DialogueId = 51010215,
          GUID = "7FB2DF66",
          NextDialogue = 51010216,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DF66"
        },
        [51010216] = {
          Content = "…………",
          DialogueId = 51010216,
          GUID = "7FB2DF90",
          NextDialogue = 51010217,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DF90"
        },
        [51010217] = {
          Content = "第一天来到这座广场时，我看到一位目盲的小丑在广场表演，他说他的眼是多年前被锅炉熏坏的。一个孩子被表演逗得狂笑不止，他的仆人便抛下银币。",
          DialogueId = 51010217,
          GUID = "7FB2DFBA",
          NextDialogue = 51010218,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DFBA"
        },
        [51010218] = {
          Content = "我现在坐的这条长椅上，一个退伍老兵叫喊着，兜售自己最后一枚勋章。旁边的长椅上，一个消瘦的母亲挤出干瘪的奶水喂给她重病的孩子。",
          DialogueId = 51010218,
          GUID = "7FB2DFE4",
          NextDialogue = 51010219,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DFE4"
        },
        [51010219] = {
          Content = "……我想那时，吹过这座广场的风，捎来的就是“眼泪”吧。",
          DialogueId = 51010219,
          GUID = "7FB2E00E",
          NextDialogue = 51010220,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2E00E"
        },
        [51010220] = {
          Content = "谢谢你的建议，如冰原上玫瑰一般的{性别：先生|小姐}……我想，我很快就可以完成这首歌了。",
          DialogueId = 51010220,
          GUID = "7FB2E038",
          SpeakNpcId = 700342,
          TalkActionId = {
            [1] = "700342:Lilikou_Story_Playlyre_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2E038"
        },
        [51010221] = {
          Content = "谢谢你的建议，如冰原上玫瑰一般的{性别：先生|小姐}。",
          DialogueId = 51010221,
          GUID = "7FB2E062",
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2E062"
        },
        [51010301] = {
          Content = "卡戎之民的雾海神话……",
          DialogueId = 51010301,
          GUID = "7FB2ED82",
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/env/700342/7FB2ED82"
        },
        [51010302] = {
          Content = "……最有趣的就是这一篇，它说雾海中的万物都在生和死的循环中，你觉得呢？伊——",
          DialogueId = 51010302,
          GUID = "7FB2EDAC",
          NextDialogue = 51010303,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EDAC"
        },
        [51010303] = {
          Content = "啊，是你！我记得你的，我们上次就在这儿说过话。",
          DialogueId = 51010303,
          GUID = "7FB2EDD6",
          NextDialogue = 51010304,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EDD6"
        },
        [51010304] = {
          Content = "你有看到我的朋友吗？一个红发的女孩子，刚才应该就在这儿……",
          DialogueId = 51010304,
          GUID = "7FB2EE00",
          NextOptions = {
            [1] = 51010305
          },
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EE00"
        },
        [51010305] = {
          Content = "没有见过。",
          DialogueId = 51010305,
          GUID = "7FB2EE2A",
          NextDialogue = 51010306
        },
        [51010306] = {
          Content = "谢谢！那我继续等一会儿。她常常突然离开，又突然回来。",
          DialogueId = 51010306,
          GUID = "7FB2EE54",
          NextDialogue = 51010307,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EE54"
        },
        [51010307] = {
          Content = "这几天，我们在这儿收集了许多卡戎之民的古老神话。我很惊讶，这里的人竟然不避讳讲这些。",
          DialogueId = 51010307,
          GUID = "7FB2EE7E",
          NextDialogue = 51010308,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EE7E"
        },
        [51010308] = {
          Content = "在我们的故乡艾利西安，那里的卡戎之民地位比这里崇高得多。他们坐在高台上，与神问答，执掌权柄。但在那儿，讨论古老的神话是一件危险的事。",
          DialogueId = 51010308,
          GUID = "7FB2EEA8",
          NextDialogue = 51010309,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EEA8"
        },
        [51010309] = {
          Content = "对了，你知道卡戎之民的神话吗？",
          DialogueId = 51010309,
          GUID = "7FB2EED2",
          NextOptions = {
            [1] = 51010310,
            [2] = 51010311
          },
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EED2"
        },
        [51010310] = {
          Content = "知道一点。",
          DialogueId = 51010310,
          GUID = "7FB2EEFC",
          NextDialogue = 51010312
        },
        [51010311] = {
          Content = "不知道。",
          DialogueId = 51010311,
          GUID = "7FB2EF26",
          NextDialogue = 51010312
        },
        [51010312] = {
          Content = "“卡戎”，这个词的意思是“来自雾海之人”……",
          DialogueId = 51010312,
          GUID = "7FB2EF50",
          NextDialogue = 51010313,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EF50"
        },
        [51010313] = {
          Content = "雾海是一切的原点。圣树自雾海生长，天之树是它庞大的枝叶，世界则立于圣树之上。",
          DialogueId = 51010313,
          GUID = "7FB2EF7A",
          NextDialogue = 51010314,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EF7A"
        },
        [51010314] = {
          Content = "圣树绽放纯白的花，从中走出母神茵布拉。她创造万物，其中就有父神埃斯刻。母神与父神诞育出卡戎之民共同的先祖。",
          DialogueId = 51010314,
          GUID = "7FB2EFA4",
          NextDialogue = 51010315,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EFA4"
        },
        [51010315] = {
          Content = "但执掌<W>死之权能</>的埃斯刻却成为灾厄的化身，并最终带来叫做“日蚀”的末日。",
          DialogueId = 51010315,
          GUID = "7FB2EFCE",
          NextDialogue = 51010316,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EFCE"
        },
        [51010316] = {
          Content = "在末日中，执掌<H>生之权能</>的母神庇护了她的子民，她散碎的灵魂飘向海洋，最终归于雾海——",
          DialogueId = 51010316,
          GUID = "7FB2EFF8",
          NextDialogue = 51010317,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EFF8"
        },
        [51010317] = {
          Content = "父神的身躯则化为大地，他高高举起的手臂化为山岳，永远伸向不知何时归来的神明。",
          DialogueId = 51010317,
          GUID = "7FB2F022",
          NextOptions = {
            [1] = 51010318
          },
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F022"
        },
        [51010318] = {
          Content = "是个有些伤感的故事。",
          DialogueId = 51010318,
          GUID = "7FB2F04C",
          NextDialogue = 51010319
        },
        [51010319] = {
          Content = "嗯，不过在这些古老的神话里，还有另一个有趣的故事。",
          DialogueId = 51010319,
          GUID = "7FB2F076",
          NextDialogue = 51010320,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F076"
        },
        [51010320] = {
          Content = "有个故事说，埃斯刻和茵布拉已经在末日后的新世界，以新生的样貌出现。",
          DialogueId = 51010320,
          GUID = "7FB2F0A0",
          NextDialogue = 51010321,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F0A0"
        },
        [51010321] = {
          Content = "而新生的他们则会带来新的一轮末日，以及再一度毁灭，再一度新生。",
          DialogueId = 51010321,
          GUID = "7FB2F0CA",
          NextDialogue = 51010322,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F0CA"
        },
        [51010322] = {
          Content = "世界在无尽的循环之中，万物都在新生与死亡间轮回往复。",
          DialogueId = 51010322,
          GUID = "7FB2F0F4",
          NextOptions = {
            [1] = 51010323
          },
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F0F4"
        },
        [51010323] = {
          Content = "看来古人也不喜欢悲剧的结局。",
          DialogueId = 51010323,
          GUID = "7FB2F11E",
          NextDialogue = 51010324
        },
        [51010324] = {
          Content = "不过……我有些在意的是，为什么这个故事的作者坚信父神和母神得到了新生？或者说，是什么“定义”了茵布拉和埃斯刻的本质呢？",
          DialogueId = 51010324,
          GUID = "7FB2F148",
          NextDialogue = 51010325,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F148"
        },
        [51010325] = {
          Content = "是他们的肉体，他们的灵魂？……还是其他？",
          DialogueId = 51010325,
          GUID = "7FB2F172",
          NextDialogue = 51010326,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F172"
        },
        [51010326] = {
          Content = "假设——我是说假设，一位伟大的魔法师把我们脚下的大地重新变成了埃斯刻的模样——那么这个埃斯刻，和新生的埃斯刻，哪个才是我们的父神大人呢？",
          DialogueId = 51010326,
          GUID = "7FB2F19C",
          NextOptions = {
            [1] = 510103261,
            [2] = 510103262,
            [3] = 510103263,
            [4] = 510103264
          },
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F19C"
        },
        [51010327] = {
          Content = "原来你是这样认为的……谢谢！你的观点启发了我很多。",
          DialogueId = 51010327,
          GUID = "7FB2F1C6",
          NextDialogue = 51010329,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F1C6"
        },
        [51010328] = {
          Content = "很多创作都是从一个无聊的问题开始的，不是吗？",
          DialogueId = 51010328,
          GUID = "7FB2F1F0",
          NextDialogue = 51010329,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F1F0"
        },
        [51010329] = {
          Content = "谢谢你，如蜡烛上火焰一般的{性别：先生|小姐}。我很喜欢这些神话，现在我已经有了关于它们的歌。",
          DialogueId = 51010329,
          GUID = "7FB2F21A",
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F21A"
        },
        [51010330] = {
          Content = "是什么让我们得以成为“我们”？",
          DialogueId = 51010330,
          GUID = "7FB2F244",
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F244"
        },
        [51010401] = {
          Content = "盖雷亚剧院……",
          DialogueId = 51010401,
          GUID = "7FB2FDEA",
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/env/700342/7FB2FDEA"
        },
        [51010402] = {
          Content = "又见面了，如白沙上石榴石一般的{性别：先生|小姐}。你很喜欢到这儿来呢，我也是。",
          DialogueId = 51010402,
          GUID = "7FB2FE14",
          NextDialogue = 51010403,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FE14"
        },
        [51010403] = {
          Content = "你去过盖雷亚剧院吗？",
          DialogueId = 51010403,
          GUID = "7FB2FE3E",
          NextOptions = {
            [1] = 510104031,
            [2] = 510104032,
            [3] = 510104033
          },
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FE3E"
        },
        [51010404] = {
          Content = "噢！真让人羡慕，你一定很富有。",
          DialogueId = 51010404,
          GUID = "7FB2FE68",
          NextDialogue = 51010407,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FE68"
        },
        [51010405] = {
          Content = "嗯……你也是吗。",
          DialogueId = 51010405,
          GUID = "7FB2FE92",
          NextDialogue = 51010407,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FE92"
        },
        [51010406] = {
          Content = "和军团？不可思议。看来你身上也有很多很多故事。",
          DialogueId = 51010406,
          GUID = "7FB2FEBC",
          NextDialogue = 51010407,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FEBC"
        },
        [51010407] = {
          Content = "我在卢卡去过大大小小的歌剧院，但总被海伯利亚的剧院关在门外。",
          DialogueId = 51010407,
          GUID = "7FB2FEE6",
          NextDialogue = 51010408,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FEE6"
        },
        [51010408] = {
          Content = "虽然知道卡戎之民在这儿过得不算好，但公共设施收的监护金比我想象中还要昂贵。",
          DialogueId = 51010408,
          GUID = "7FB2FF10",
          NextDialogue = 51010409,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FF10"
        },
        [51010409] = {
          Content = "虽然幸运地赶上这座城市一年一度不需要门票的狂欢日，但又不幸地听说那儿发生了械战……简直糟透了。",
          DialogueId = 51010409,
          GUID = "7FB2FF3A",
          NextDialogue = 51010410,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FF3A"
        },
        [51010410] = {
          Content = "不过还好——我收集了很多乐谱！书店的价格还算公道，很多人也同意让我用歌声交换乐谱，还有一位神秘的好心朋友教过我一首有名的歌！",
          DialogueId = 51010410,
          GUID = "7FB2FF64",
          NextOptions = {
            [1] = 510104101
          },
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FF64"
        },
        [51010411] = {
          Content = "前阵子的一个晚上，我靠着一堵墙，就着月光，随意弹唱一首从淘来的乐谱里学的歌。那首歌的旋律并不复杂，很容易便能记住。",
          DialogueId = 51010411,
          GUID = "7FB2FF8E",
          NextDialogue = 51010412,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FF8E"
        },
        [51010412] = {
          Content = "但我唱完后，墙的那边突然传来奇怪的敲击声……我能听出来，那些敲击声遵循着某种规律。你知道的，吟游诗人总是对节奏格外敏感。",
          DialogueId = 51010412,
          GUID = "7FB2FFB8",
          NextDialogue = 51010413,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FFB8"
        },
        [51010413] = {
          Content = "我试着拆解了那些节奏。那是一种很常见的古老密码，用两种不同的敲击声就可以传递讯号。",
          DialogueId = 51010413,
          GUID = "7FB2FFE2",
          NextDialogue = 51010414,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FFE2"
        },
        [51010414] = {
          Content = "墙那边的人告诉我，我唱错了。那是一首歌剧的唱段，在这儿很有名——因为没读过剧本的缘故，我未能准确理解那首歌所传递给观众的情感。",
          DialogueId = 51010414,
          GUID = "7FB3000C",
          NextDialogue = 51010415,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB3000C"
        },
        [51010415] = {
          Content = "他则是因为某种原因没有办法开口说话和演唱。但他可以用这种讯号教给我如何演唱。",
          DialogueId = 51010415,
          GUID = "7FB30036",
          NextDialogue = 51010416,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB30036"
        },
        [51010416] = {
          Content = "但当我终于在他的教导下学会了那首歌，跑到对面那条街打算当面道谢时，那位好心人已经不在那里了。",
          DialogueId = 51010416,
          GUID = "7FB30060",
          NextOptions = {
            [1] = 510104161,
            [2] = 510104162
          },
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB30060"
        },
        [51010417] = {
          Content = "噢，真是太巧了！",
          DialogueId = 51010417,
          GUID = "7FB3008A",
          NextDialogue = 51010418,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB3008A"
        },
        [51010418] = {
          Content = "如果方便，还请你代我向那位先生或女士致谢——还有祝福！虽然不知道他为什么无法开口，但还是祝愿他早日好起来。我能感受到，他喜欢唱歌，非常喜欢。",
          DialogueId = 51010418,
          GUID = "7FB300B4",
          NextDialogue = 51010419,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB300B4"
        },
        [51010419] = {
          Content = "……好，我会的。",
          DialogueId = 51010419,
          GUID = "7FB300DE",
          NextDialogue = 51010421,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Agree"
          },
          VoiceName = "voice/$Locale$/story/1002/510104/7FB300DE"
        },
        [51010420] = {
          Content = "是呢……也藏着很多故事。",
          DialogueId = 51010420,
          GUID = "7FB30108",
          NextDialogue = 51010421,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB30108"
        },
        [51010421] = {
          Content = "说来，这里的歌剧和卢卡的很不一样……",
          DialogueId = 51010421,
          GUID = "7FB30132",
          NextDialogue = 51010422,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB30132"
        },
        [51010422] = {
          Content = "卢卡的歌剧是焰火，伊瑟尔的歌剧是风。",
          DialogueId = 51010422,
          GUID = "7FB3015C",
          NextDialogue = 51010423,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB3015C"
        },
        [51010423] = {
          Content = "而这里的歌剧是大地。广阔的，苦痛的大地……",
          DialogueId = 51010423,
          GUID = "7FB30186",
          NextDialogue = 51010424,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB30186"
        },
        [51010424] = {
          Content = "我和朋友就快要离开这儿了，在那之前，我还想为这里写一首歌。",
          DialogueId = 51010424,
          GUID = "7FB301B0",
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB301B0"
        },
        [51010425] = {
          Content = "♪白雪是她的羊水 晨昏线是她的脐带……",
          DialogueId = 51010425,
          GUID = "7FB301DA",
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/env/700342/7FB301DA"
        },
        [51010426] = {
          Content = "♪白雪是她的羊水 晨昏线是她的脐带\n她娩出伟大与苦难 汇入白山下的黑铁摇篮……",
          DialogueId = 51010426,
          GUID = "7FB30204",
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB30204"
        },
        [51010501] = {
          Content = "通行证——喂，说你呢，通行证带了吗？",
          DialogueId = 51010501,
          GUID = "7FB30E52",
          NextOptions = {
            [1] = 51010502,
            [2] = 51010504,
            [3] = 51010506
          },
          SpeakNpcId = 700111
        },
        [51010502] = {
          Content = "（声泪俱下地哭诉你是一个遵纪守法的人，只是碰巧又忘带通行证了。）",
          DialogueId = 51010502,
          GUID = "7FB30E7C",
          ImprPlusId = 1004,
          NextDialogue = 51010503
        },
        [51010503] = {
          Content = "算了吧，你这话听得我耳朵都快起茧子了。去去，快过去，别搞得那么显眼。",
          DialogueId = 51010503,
          GUID = "7FB30EA6",
          NextDialogue = 51010508,
          SpeakNpcId = 700111
        },
        [51010504] = {
          Content = "（掏出卡米拉帮忙伪造的通行证。）",
          DialogueId = 51010504,
          GUID = "7FB30ED0",
          ImprPlusId = 1003,
          NextDialogue = 51010505
        },
        [51010505] = {
          Content = "通行证核验无误，准许放行。",
          DialogueId = 51010505,
          GUID = "7FB30EFA",
          NextDialogue = 51010508,
          SpeakNpcId = 700111
        },
        [51010506] = {
          Content = "凯文先生，你也不想你在泪湖边上那件事被上级知……",
          DialogueId = 51010506,
          GUID = "7FB30F24",
          ImprPlusId = 1005,
          NextDialogue = 51010507
        },
        [51010507] = {
          Content = "别念了！！！让你过还不行吗！！",
          DialogueId = 51010507,
          GUID = "7FB30F4E",
          NextDialogue = 51010508,
          SpeakNpcId = 700111
        }
      }
    end
