        },
        [51010611] = {
          Content = "工作……哈。谁还没有过一份体面的工作……",
          DialogueId = 51010611,
          GUID = "7FB3205E",
          NextDialogue = 51010612,
          SpeakNpcId = 700338
        },
        [51010612] = {
          Content = "可那又有什么用？有时候啊，他们夺走你的工作，就和夺走这破碗中的硬币一样简单。",
          DialogueId = 51010612,
          GUID = "7FB32088",
          NextDialogue = 51010613,
          SpeakNpcId = 700338
        },
        [51010613] = {
          Content = "在漂亮屋子里乞讨，在大街上乞讨，都一样的。",
          DialogueId = 51010613,
          GUID = "7FB320B2",
          SpeakNpcId = 700338
        },
        [51010614] = {
          Content = "好好活着吧……唉，这世道，越是好人越难立足啊。",
          DialogueId = 51010614,
          GUID = "7FB320DC",
          SpeakNpcId = 700338
        },
        [51010701] = {
          Content = "末日将至啊……末日将至……",
          DialogueId = 51010701,
          GUID = "7FB32F22",
          NextDialogue = 51010702,
          SpeakNpcId = 700337
        },
        [51010702] = {
          Content = "（眼前的皎皎摇头晃脑地趴在桌子上，昏昏欲睡。）",
          DialogueId = 51010702,
          GUID = "7FB32F4C",
          NextOptions = {
            [1] = 51010703,
            [2] = 51010704
          }
        },
        [51010703] = {
          Content = "把她叫醒。",
          DialogueId = 51010703,
          GUID = "7FB32F76",
          NextDialogue = 51010705
        },
        [51010704] = {
          Content = "让她继续睡。",
          DialogueId = 51010704,
          GUID = "7FB32FA0",
          Scripts = "SetOutport{FinishType{\"Fail\"}}"
        },
        [51010705] = {
          Content = "（悲观皎皎猛地抬起头，眼神闪闪发光，声音如洪水一般宣泄出来。）",
          DialogueId = 51010705,
          GUID = "7FB32FCA",
          NextDialogue = 51010706
        },
        [51010706] = {
          Content = "末日……末日要来了，没人能够逃掉。",
          DialogueId = 51010706,
          GUID = "7FB32FF4",
          NextDialogue = 51010707,
          SpeakNpcId = 700337
        },
        [51010707] = {
          Content = "花店里的花朵不再鲜艳，褪色成纯白的石楠……",
          DialogueId = 51010707,
          GUID = "7FB3301E",
          NextDialogue = 51010708,
          SpeakNpcId = 700337
        },
        [51010708] = {
          Content = "广场上的猫猫不再毛绒绒，而是像石膏雕像一样又硬又滑……",
          DialogueId = 51010708,
          GUID = "7FB33048",
          NextDialogue = 51010709,
          SpeakNpcId = 700337
        },
        [51010709] = {
          Content = "面包房再也做不出蓬松的面包，无论怎么烘焙都会变成黑漆漆的烂泥……",
          DialogueId = 51010709,
          GUID = "7FB33072",
          NextDialogue = 51010710,
          SpeakNpcId = 700337
        },
        [51010710] = {
          Content = "我最爱吃的冰棍也不再冰冰凉凉，放到嘴里只会黏糊糊粘住嗓子……",
          DialogueId = 51010710,
          GUID = "7FB3309C",
          NextDialogue = 51010711,
          SpeakNpcId = 700337
        },
        [51010711] = {
          Content = "大家也开始慢慢变得和皎皎一样高，和皎皎一样白……",
          DialogueId = 51010711,
          GUID = "7FB330C6",
          NextDialogue = 51010712,
          SpeakNpcId = 700337
        },
        [51010712] = {
          Content = "到最后……",
          DialogueId = 51010712,
          GUID = "7FB330F0",
          NextDialogue = 51010713,
          SpeakNpcId = 700337
        },
        [51010713] = {
          Content = "花店的阿姨，面包房的大婶，卖冰棍的爷爷……大家都会变成皎皎！",
          DialogueId = 51010713,
          GUID = "7FB3311A",
          NextOptions = {
            [1] = 51010714,
            [2] = 51010715
          },
          SpeakNpcId = 700337
        },
        [51010714] = {
          Content = "皎皎好，我也想变成皎皎。",
          DialogueId = 51010714,
          GUID = "7FB33144",
          ImprPlusId = 1005,
          NextDialogue = 51010716,
          SpeakNpcId = 700337
        },
        [51010715] = {
          Content = "好可怕的末日……",
          DialogueId = 51010715,
          GUID = "7FB3316E",
          ImprPlusId = 1004,
          NextDialogue = 51010716,
          SpeakNpcId = 700337
        },
        [51010716] = {
          Content = "你……你的头发、你的衣服、你的身高……你已经开始变成皎皎了吗！",
          DialogueId = 51010716,
          GUID = "7FB33198",
          NextDialogue = 51010717,
          SpeakNpcId = 700337
        },
        [51010717] = {
          Content = "末日……末日果然来了，一切都完了。",
          DialogueId = 51010717,
          GUID = "7FB331C2",
          NextDialogue = 51010718,
          SpeakNpcId = 700337
        },
        [51010718] = {
          Content = "（悲观皎皎无力地垂下双手，看向你的视线透过你的身躯，透过层叠的建筑，失神地望向昏暗的天空。仿佛她口中的末日马上就要变为现实。）",
          DialogueId = 51010718,
          GUID = "7FB331EC",
          NextDialogue = 51010719
        },
        [51010719] = {
          Content = "（几分钟过去，理所当然的什么都未发生，悲观皎皎的视线再也没有落到你的身上，不断呢喃着末日将至。）",
          DialogueId = 51010719,
          GUID = "7FB33216",
          NextDialogue = 51010720
        },
        [51010720] = {
          Content = "（你有些好奇变成皎皎会是怎么样的感觉，但现在你能做的，也只有转身离开了。）",
          DialogueId = 51010720,
          GUID = "7FB33240"
        },
        [51010721] = {
          Content = "末日，末日已经开始了……",
          DialogueId = 51010721,
          GUID = "7FB3326A",
          SpeakNpcId = 700337
        },
        [51010801] = {
          Content = "您好，这朵花与您今天的装扮很相称……如果那孩子还在的话，一定也会这么说吧。",
          DialogueId = 51010801,
          GUID = "7FB33F8A",
          NextOptions = {
            [1] = 51010802,
            [2] = 51010803
          },
          SpeakNpcId = 700203
        },
        [51010802] = {
          Content = "你认识我？",
          DialogueId = 51010802,
          GUID = "7FB33FB4",
          NextDialogue = 51010804
        },
        [51010803] = {
          Content = "“那孩子”难道指的是……",
          DialogueId = 51010803,
          GUID = "7FB33FDE",
          NextDialogue = 51010804
        },
        [51010804] = {
          Content = "我的女儿。她的名字是赛琪。",
          DialogueId = 51010804,
          GUID = "7FB34008",
          NextDialogue = 51010805,
          SpeakNpcId = 700203
        },
        [51010805] = {
          Content = "她曾在给我的信里提到过“一个新交的朋友”。您的模样与那封书信中的描述很相似……如果我认错了人，还请您谅解。",
          DialogueId = 51010805,
          GUID = "7FB34032",
          NextOptions = {
            [1] = 51010806,
            [2] = 51010807
          },
          SpeakNpcId = 700203,
          bForbidSkipOptions = true
        },
        [51010806] = {
          Content = "……她是怎么说我的？",
          DialogueId = 51010806,
          GUID = "7FB3405C",
          NextDialogue = 51010809
        },
        [51010807] = {
          Content = "……是的，你认错人了。（离开）",
          DialogueId = 51010807,
          GUID = "7FB34086",
          NextDialogue = 51010808
        },
        [51010808] = {
          Content = "（你像逃跑一样转身离开。那是你们心中共同的隐痛，你不愿再触及它。）",
          DialogueId = 51010808,
          GUID = "7FB340B0",
          Scripts = "SetOutport{FinishType{\"Fail\"}}"
        },
        [51010809] = {
          Content = "你很聪明，又很勇敢。听说你到冰湖城的第一天就深入格雷姆废矿，在她见过的所有同龄人里，你是最强大的一个。更重要的是……",
          DialogueId = 51010809,
          GUID = "7FB340DA",
          NextDialogue = 51010810,
          SpeakNpcId = 700203
        },
        [51010810] = {
          Content = "“{性别：他|她}和冰湖城的大多数人不一样，{性别：他|她}还有着我们早就丢失了的东西——对正义和自由的渴望。”",
          DialogueId = 51010810,
          GUID = "7FB34104",
          NextDialogue = 51010811,
          SpeakNpcId = 700203
        },
        [51010811] = {
          Content = "“从{性别：他|她}身上，我看到了另一种不一样的生活。”",
          DialogueId = 51010811,
          GUID = "7FB3412E",
          NextDialogue = 51010812,
          SpeakNpcId = 700203
        },
        [51010812] = {
          Content = "这是她信里写的。",
          DialogueId = 51010812,
          GUID = "7FB34158",
          NextDialogue = 51010813,
          SpeakNpcId = 700203
        },
        [51010813] = {
          Content = "（女人熟练地复述着——显然，那封信她不知看了多少遍。）",
          DialogueId = 51010813,
          GUID = "7FB34182",
          NextDialogue = 51010814
        },
        [51010814] = {
          Content = "对不起，我没能……",
          DialogueId = 51010814,
          GUID = "7FB341AC",
          NextDialogue = 51010815,
          SpeakNpcId = 100001
        },
        [51010815] = {
          Content = "不要说抱歉，孩子。我看得到，有你最后的陪伴，她是快乐的。这就够了。是我们应该感谢你。",
          DialogueId = 51010815,
          GUID = "7FB341D6",
          NextDialogue = 51010816,
          SpeakNpcId = 700203
        },
        [51010816] = {
          Content = "请带上这束花吧，我们的祝福与你同在。",
          DialogueId = 51010816,
          GUID = "7FB34200",
          SpeakNpcId = 700203
        },
        [51010817] = {
          Content = "一路顺利，我们的祝福与你同在。",
          DialogueId = 51010817,
          GUID = "7FB3422A",
          SpeakNpcId = 700203
        },
        [51010901] = {
          Content = "自家庄园的好果子，别的地方没有这培育技术！",
          DialogueId = 51010901,
          GUID = "7FB34FF2",
          NextDialogue = 51010902,
          SpeakNpcId = 700009
        },
        [51010902] = {
          Content = "您来点果子吗？一等一的肥料加上好种子，自家温室培养出来的，个个营养丰富口感好！",
          DialogueId = 51010902,
          GUID = "7FB3501C",
          NextOptions = {
            [1] = 51010903,
            [2] = 51010905
          },
          SpeakNpcId = 700009
        },
        [51010903] = {
          Content = "温室培育的果子应该很贵吧。",
          DialogueId = 51010903,
          GUID = "7FB35046",
          ImprPlusId = 1001,
          NextDialogue = 51010904
        },
        [51010904] = {
          Content = "果子不同价格也不同，能吃到好果子本身就很难了，我之前在战场上根本吃不到。",
          DialogueId = 51010904,
          GUID = "7FB35070",
          NextOptions = {
            [1] = 51010907
          },
          SpeakNpcId = 700009
        },
        [51010905] = {
          Content = "掌握温室培育的技术应该很难。",
          DialogueId = 51010905,
          GUID = "7FB3509A",
          ImprPlusId = 1003,
          NextDialogue = 51010906
        },
        [51010906] = {
          Content = "技术是我爷爷传下来的，我一开始还不想继承，后来退伍了才接受。",
          DialogueId = 51010906,
          GUID = "7FB350C4",
          NextOptions = {
            [1] = 51010907
          },
          SpeakNpcId = 700009
        },
        [51010907] = {
          Content = "您当过兵？",
          DialogueId = 51010907,
          GUID = "7FB350EE",
          NextDialogue = 51010908
        },
        [51010908] = {
          Content = "是啊，我当初可是优秀士兵，一个顶三个！",
          DialogueId = 51010908,
          GUID = "7FB35118",
          NextDialogue = 51010909,
          SpeakNpcId = 700009
        },
        [51010909] = {
          Content = "后来受伤了，越来越力不从心，就提前退伍了。",
          DialogueId = 51010909,
          GUID = "7FB35142",
          NextDialogue = 51010910,
          SpeakNpcId = 700009
        },
        [51010910] = {
          Content = "现在才明白平平淡淡才是真，踏踏实实培育果子，再遇到个好姑娘，一辈子挺好的了。",
          DialogueId = 51010910,
          GUID = "7FB3516C",
          NextOptions = {
            [1] = 51010911
          },
          RestartTag = 51010910,
          SpeakNpcId = 700009
        },
        [51010911] = {
          Content = "有心仪的人选吗？",
          DialogueId = 51010911,
          FailDialogue = 51010912,
          GUID = "7FB35196",
          ImprCheckId = 1075,
          NextDialogue = 51010914
        },
        [51010912] = {
          Content = "（男人一时语塞，尴尬地张了张嘴，艰难地挤出一句话。）",
          DialogueId = 51010912,
          GUID = "7FB351C0",
          NextDialogue = 51010913
        },
        [51010913] = {
          Content = "您，您别问了，您还是多看看果子，我帮您挑挑。",
          DialogueId = 51010913,
          GUID = "7FB351EA",
          SpeakNpcId = 700009
        },
        [51010914] = {
          Content = "（男人的眼睛闪过一丝亮光，不自觉地微笑了起来，但瞬间又陷入了困惑。）",
          DialogueId = 51010914,
          GUID = "7FB35214",
          NextDialogue = 51010915
        },
        [51010915] = {
          Content = "……虽然有，但我只见过她的背影。",
          DialogueId = 51010915,
          GUID = "7FB3523E",
          NextDialogue = 51010916,
          SpeakNpcId = 700009
        },
        [51010916] = {
          Content = "这么久了，我还没和她说过话呢，唉。",
          DialogueId = 51010916,
          GUID = "7FB35268",
          NextDialogue = 51010917,
          SpeakNpcId = 700009
        },
        [51010917] = {
          Content = "贸然搭话又怕吓到心爱的姑娘，我只好先让空空皎皎帮我传下话。唉，可我真是太倒霉了，每次空空皎皎去传话的时候，都赶上她不在家。",
          DialogueId = 51010917,
          GUID = "7FB35292",
          NextOptions = {
            [1] = 51010918
          },
          SpeakNpcId = 700009
        },
        [51010918] = {
          Content = "你看上去不拘小节，却很懂得尊重对方。",
          DialogueId = 51010918,
          GUID = "7FB352BC",
          ImprPlusId = 1002,
          NextDialogue = 51010919
        },
        [51010919] = {
          Content = "您夸得我都不好意思了，哈哈。",
          DialogueId = 51010919,
          GUID = "7FB352E6",
          NextDialogue = 51010920,
          SpeakNpcId = 700009
        },
        [51010920] = {
          Content = "对了，我看您像是个文化人，可不可以帮我这个粗人润色一下句子，我怎么写怎么别扭。",
          DialogueId = 51010920,
          GUID = "7FB35310",
          NextOptions = {
            [1] = 51010921
          },
          SpeakNpcId = 700009
        },
        [51010921] = {
          Content = "我现在正好有时间，你读来听听？",
          DialogueId = 51010921,
          GUID = "7FB3533A",
          NextDialogue = 51010922
        },
        [51010922] = {
          Content = "咳咳。",
          DialogueId = 51010922,
          GUID = "7FB35364",
          NextDialogue = 51010923,
          SpeakNpcId = 700009
        },
        [51010923] = {
          Content = "“我对你的感情，一直升温，比冬天的温室，还要温暖。”",
          DialogueId = 51010923,
          GUID = "7FB3538E",
          NextOptions = {
            [1] = 51010924
          },
          SpeakNpcId = 700009
        },
        [51010924] = {
          Content = "……",
          DialogueId = 51010924,
          GUID = "7FB353B8",
          NextDialogue = 51010925
        },
        [51010925] = {
          Content = "“你什么时候能发现，我的心像果子，就等着你来采摘。”",
          DialogueId = 51010925,
          GUID = "7FB353E2",
          NextDialogue = 51010926,
          SpeakNpcId = 700009
        },
        [51010926] = {
          Content = "“接受我吧，我的姑娘！不要让我的爱像烂果子一样，烂在地里。”",
          DialogueId = 51010926,
          GUID = "7FB3540C",
          NextDialogue = 51010927,
          SpeakNpcId = 700009
        },
        [51010927] = {
          Content = "……怎么样，有可以润色的地方吗？",
          DialogueId = 51010927,
          GUID = "7FB35436",
          NextOptions = {
            [1] = 51010928
          },
          SpeakNpcId = 700009
        },
        [51010928] = {
          Content = "……很有个人特色，也很真挚，我觉得保持现状就好。",
          DialogueId = 51010928,
          GUID = "7FB35460",
          NextDialogue = 51010929
        },
        [51010929] = {
          Content = "真的吗？那太好了，借您吉言。",
          DialogueId = 51010929,
          GUID = "7FB3548A",
          NextDialogue = 51010930,
          SpeakNpcId = 700009
        },
        [51010930] = {
          Content = "如果这份感情有结果了，您来买果子我给您最大优惠，哈哈。",
          DialogueId = 51010930,
          GUID = "7FB354B4",
          SpeakNpcId = 700009
        },
        [51010931] = {
          Content = "我的爱对方还没回应，唉，最大优惠您要等等了。",
          DialogueId = 51010931,
          GUID = "7FB354DE",
          SpeakNpcId = 700009
        },
        [51011001] = {
          Content = "请留步，很抱歉突然叫住您。",
          DialogueId = 51011001,
          GUID = "7FB3605A",
          NextDialogue = 51011002,
          SpeakNpcId = 700008
        },
        [51011002] = {
          Content = "但若是我家衣服能拥有自己的思想，一定很盼望能够被像您一样俊美的人穿在身上。",
          DialogueId = 51011002,
          GUID = "7FB36084",
          NextDialogue = 51011003,
          SpeakNpcId = 700008
        },
        [51011003] = {
          Content = "如果就这么错过了您，它们一定会伤心的。",
          DialogueId = 51011003,
          GUID = "7FB360AE",
          NextDialogue = 51011004,
          SpeakNpcId = 700008
        },
        [51011004] = {
          Content = "（眼前的男人有着贵族的气质，举手投足之间尽显优雅，身躯瘦弱却又挺拔，富有亲和力的笑眼让人如沐春风。）",
          DialogueId = 51011004,
          GUID = "7FB360D8",
          NextOptions = {
            [1] = 51011005,
            [2] = 51011006
          }
        },
        [51011005] = {
          Content = "你这里的衣服是我能买得起的吗？",
          DialogueId = 51011005,
          GUID = "7FB36102",
          ImprPlusId = 1001,
          NextDialogue = 51011007
        },
        [51011006] = {
          Content = "我穿麻袋都好看。",
          DialogueId = 51011006,
          GUID = "7FB3612C",
          ImprPlusId = 1005,
          NextDialogue = 51011007
        },
        [51011007] = {
          Content = "那是当然，您可以先看看我们的款式图册，如果看中了哪件可以试穿。",
          DialogueId = 51011007,
          GUID = "7FB36156",
          NextDialogue = 51011008,
          SpeakNpcId = 700008
        },
        [51011008] = {
          Content = "（你接过了那本册子，上面的款式令人目不暇接。）",
          DialogueId = 51011008,
          GUID = "7FB36180",
          NextDialogue = 51011009
        },
        [51011009] = {
          Content = "（是时候享受生活了，就从买一件新衣服开始如何？这么想着的你指了指了一件色彩艳丽的{性别：衣服|裙子}。）",
          DialogueId = 51011009,
          GUID = "7FB361AA",
          NextDialogue = 51011010
        },
        [51011010] = {
          Content = "{性别：不好意思，这件是女装。而且是按照我的身材缝制的，暂时没有适合您的尺码……|真不巧，这件是按照我的身材缝制的，暂时没有适合您的尺码……}",
          DialogueId = 51011010,
          GUID = "7FB361D4",
          NextOptions = {
            [1] = 51011011
          },
          RestartTag = 51011010,
          SpeakNpcId = 700008
        },
        [51011011] = {
          Content = "我就想要这件，要不你先穿上让我参考一下。",
          DialogueId = 51011011,
          FailDialogue = 51011012,
          GUID = "7FB361FE",
          ImprCheckId = 1076,
          NextDialogue = 51011013
        },
        [51011012] = {
          Content = "呵呵，还是请您不要取笑我了。",
          DialogueId = 51011012,
          GUID = "7FB36228",
          SpeakNpcId = 700008
        },
        [51011013] = {
          Content = "如果您一定要看的话倒也没什么，只是现在换上的话可能会带来一些不必要的困扰。",
          DialogueId = 51011013,
          GUID = "7FB36252",
          NextDialogue = 51011014,
          SpeakNpcId = 700008
        },
        [51011014] = {
          Content = "会被认成女性吗？",
          DialogueId = 51011014,
          GUID = "7FB3627C",
          NextDialogue = 51011015,
          SpeakNpcId = 100001
        },
        [51011015] = {
          Content = "确实如此，但又不完全是这样……重点不在于有谁“把我认成女士”，而是“把我认成女士后会发生什么”。",
          DialogueId = 51011015,
          GUID = "7FB362A6",
          NextDialogue = 51011016,
          SpeakNpcId = 700008
        },
        [51011016] = {
          Content = "或许这样和您表述很难理解……",
          DialogueId = 51011016,
          GUID = "7FB362D0",
          NextDialogue = 51011017,
          SpeakNpcId = 700008
        },
        [51011017] = {
          Content = "难道……有人把你当成了女人，然后对你心生爱意？！",
          DialogueId = 51011017,
          GUID = "7FB362FA",
          NextDialogue = 51011018,
          SpeakNpcId = 100001
        },
        [51011018] = {
          Content = "哦，幸好您是这般聪慧，省去了不少解释的时间。",
          DialogueId = 51011018,
          GUID = "7FB36324",
          NextDialogue = 51011019,
          SpeakNpcId = 700008
        },
        [51011019] = {
          Content = "不过那位专情的先生似乎是认定了另一种现实，在他的想象中我有一个美丽的妹妹。",
          DialogueId = 51011019,
          GUID = "7FB3634E",
          NextDialogue = 51011020,
          SpeakNpcId = 700008
        },
        [51011020] = {
          Content = "直到一位可爱的皎皎小姐突然找到我的店里，对我声情并茂地朗诵对方的情书，我才知道自己的行为引起了误会。",
          DialogueId = 51011020,
          GUID = "7FB36378",
          NextDialogue = 51011021,
          SpeakNpcId = 700008
        },
        [51011021] = {
          Content = "我不得不在那位皎皎小姐代其传达爱意的时候谎称我的妹妹有事出门，才一次次地搪塞过去。",
          DialogueId = 51011021,
          GUID = "7FB363A2",
          NextDialogue = 51011022,
          SpeakNpcId = 700008
        },
        [51011022] = {
          Content = "那你为什么不直接和他说清楚呢？",
          DialogueId = 51011022,
          GUID = "7FB363CC",
          NextDialogue = 51011023,
          SpeakNpcId = 100001
        },
        [51011023] = {
          Content = "为什么……因为很有趣？",
          DialogueId = 51011023,
          GUID = "7FB363F6",
          NextDialogue = 51011024,
          SpeakNpcId = 700008
        },
        [51011024] = {
          Content = "“你漂亮的头巾，和我家的北风莓一样鲜甜诱人。”",
          DialogueId = 51011024,
          GUID = "7FB36420",
          NextDialogue = 51011025,
          SpeakNpcId = 700008
        },
        [51011025] = {
          Content = "“你火红的裙子，像火焰根那样炽烈，让我紧张的冒汗。”",
          DialogueId = 51011025,
          GUID = "7FB3644A",
          NextDialogue = 51011026,
          SpeakNpcId = 700008
        },
        [51011026] = {
          Content = "不管我换成什么样的装扮，他都会在两天后对每一套衣装给出类似风格的评价。",
          DialogueId = 51011026,
          GUID = "7FB36474",
          NextDialogue = 51011027,
          SpeakNpcId = 700008
        },
        [51011027] = {
          Content = "尽管措辞稍微有些……质朴，但对于我而言也是相当直观的参考。",
          DialogueId = 51011027,
          GUID = "7FB3649E",
          NextDialogue = 51011028,
          SpeakNpcId = 700008
        },
        [51011028] = {
          Content = "这个风格总觉得有些熟悉……",
          DialogueId = 51011028,
          GUID = "7FB364C8",
          NextDialogue = 51011029,
          SpeakNpcId = 100001
        },
        [51011029] = {
          Content = "您认识那位为情所困的先生？既然如此，还请您代为保守这个秘密。",
          DialogueId = 51011029,
          GUID = "7FB364F2",
          NextDialogue = 51011030,
          SpeakNpcId = 700008
        },
        [51011030] = {
          Content = "你只是想找一个工具人帮你评论你新设计的衣服吧……",
          DialogueId = 51011030,
          GUID = "7FB3651C",
          NextDialogue = 51011031,
          SpeakNpcId = 100001
        },
        [51011031] = {
          Content = "“这位情感真挚的先生明天会用什么样新奇的比喻来描述我的衣服”，如果是您遇到这样的事，也会有这样的好奇心吧？",
          DialogueId = 51011031,
          GUID = "7FB36546",
          NextDialogue = 51011032,
          SpeakNpcId = 700008
        },
        [51011032] = {
          Content = "不过最近这位先生的言辞不像往常那样直白，就像对一个捉摸不透的梦产生了犹豫……",
          DialogueId = 51011032,
          GUID = "7FB36570",
          NextDialogue = 51011033,
          SpeakNpcId = 700008
        },
        [51011033] = {
          Content = "也许我可以在适当的时机做出一些适当的回应，才能在保持距离的同时让他不要放弃？",
          DialogueId = 51011033,
          GUID = "7FB3659A",
          NextDialogue = 51011034,
          SpeakNpcId = 700008
        },
        [51011034] = {
          Content = "你这完全是乐在其中了啊……",
          DialogueId = 51011034,
          GUID = "7FB365C4",
          SpeakNpcId = 100001
        },
        [51011035] = {
          Content = "是您啊，还请您帮忙保守秘密。作为回报，本店对您永久打折。",
          DialogueId = 51011035,
          GUID = "7FB365EE",
          SpeakNpcId = 700008
        },
        [51011101] = {
          Content = "哇，商户们工作得好认真！",
          DialogueId = 51011101,
          GUID = "7FB370C2",
          NextDialogue = 51011102,
          SpeakNpcId = 700336
        },
        [51011102] = {
          Content = "不像我，只会睡觉和晒太阳……",
          DialogueId = 51011102,
          GUID = "7FB370EC",
          NextOptions = {
            [1] = 51011103,
            [2] = 51011104,
            [3] = 51011105
          },
          SpeakNpcId = 700336
        },
        [51011103] = {
          Content = "每个人都有适合自己的生活方式。",
          DialogueId = 51011103,
          GUID = "7FB37116",
          ImprPlusId = 1002,
          NextDialogue = 51011106
        },
        [51011104] = {
          Content = "晒太阳和睡觉才是人生啊！",
          DialogueId = 51011104,
          GUID = "7FB37140",
          ImprPlusId = 1004,
          NextDialogue = 51011106
        },
        [51011105] = {
          Content = "晒太阳和睡觉对身体有好处，是对健康的长期投资。",
          DialogueId = 51011105,
          GUID = "7FB3716A",
          ImprPlusId = 1003,
          NextDialogue = 51011106
        },
        [51011106] = {
          Content = "哇，你很懂嘛。",
          DialogueId = 51011106,
          GUID = "7FB37194",
          NextDialogue = 51011107,
          SpeakNpcId = 700336
        },
        [51011107] = {
          Content = "但不劳动就总是有愧疚感，看到他们这么辛苦地赚钱，而我无所事事的却还这么富有，总觉得过意不去……",
          DialogueId = 51011107,
          GUID = "7FB371BE",
          NextDialogue = 51011108,
          SpeakNpcId = 700336
        },
        [51011108] = {
          Content = "但是对皎皎来说，如果不帮人干点啥就会浑身难受，不踏实，唉……",
          DialogueId = 51011108,
          GUID = "7FB371E8",
          NextOptions = {
            [1] = 51011109
          },
          RestartTag = 51011108,
          SpeakNpcId = 700336
        },
        [51011109] = {
          Content = "（询问空空皎皎致富秘诀。）",
          DialogueId = 51011109,
          FailDialogue = 51011110,
          GUID = "7FB37212",
          ImprCheckId = 1077,
          NextDialogue = 51011111
        },
        [51011110] = {
          Content = "……什么？哈（呵欠），你刚才说了什么吗……",
          DialogueId = 51011110,
          GUID = "7FB3723C",
          SpeakNpcId = 700336
        },
        [51011111] = {
          Content = "致富秘诀？就是我有次不小心从山崖掉了下去，碰巧捡了块价值连城的石头，一下子就变有钱了。这么多钱根本花不完……",
          DialogueId = 51011111,
          GUID = "7FB37266",
          NextDialogue = 51011112,
          SpeakNpcId = 700336
        },
        [51011112] = {
          Content = "要不你也从山崖上跳下去试试？",
          DialogueId = 51011112,
          GUID = "7FB37290",
          NextOptions = {
            [1] = 51011113,
            [2] = 51011114
          },
          SpeakNpcId = 700336
        },
        [51011113] = {
          Content = "谢谢，已经试过了……",
          DialogueId = 51011113,
          GUID = "7FB372BA",
          NextDialogue = 51011115
        },
        [51011114] = {
          Content = "可恶，为什么同样是从山崖上掉下去，我就没摊上这种好事！",
          DialogueId = 51011114,
          GUID = "7FB372E4",
          NextDialogue = 51011115
        },
        [51011115] = {
          Content = "唔……那我只能帮你到这里了。",
          DialogueId = 51011115,
          GUID = "7FB3730E",
          NextDialogue = 51011116,
          SpeakNpcId = 700336
        },
        [51011116] = {
          Content = "哦！我想起来了，那个卖果子的瓦伦大叔又要我帮他传话呢！太好了，有事做了……",
          DialogueId = 51011116,
          GUID = "7FB37338",
          SpeakNpcId = 700336
        },
        [51011201] = {
          Content = "……",
          DialogueId = 51011201,
          GUID = "7FB3812A",
          NextDialogue = 51011202,
          SpeakNpcId = 700339
        },
        [51011202] = {
          Content = "（少女盯着窗外一言不发，聚焦在远处的目光似乎在浩瀚的苍穹中寻找着什么。）",
          DialogueId = 51011202,
          GUID = "7FB38154",
          NextDialogue = 51011203
        },
        [51011203] = {
          Content = "（从她的身上，你感受到了一种不该属于她这个年纪的气息——凝滞、衰朽的气息。）",
          DialogueId = 51011203,
          GUID = "7FB3817E",
          NextOptions = {
            [1] = 51011204,
            [2] = 51011220
          }
        },
        [51011204] = {
          Content = "向她搭话",
          DialogueId = 51011204,
          GUID = "7FB381A8",
          NextDialogue = 51011205
        },
        [51011205] = {
          Content = "（或许是担心下一刻她就会做出什么不可挽回的事情，又或者是对她在寻找的事物产生了好奇，你决定向她搭话。）",
          DialogueId = 51011205,
          GUID = "7FB381D2",
          NextDialogue = 51011206
        },
        [51011206] = {
          Content = "你好？",
          DialogueId = 51011206,
          GUID = "7FB381FC",
          NextDialogue = 51011207,
          SpeakNpcId = 100001
        },
        [51011207] = {
          Content = "……",
          DialogueId = 51011207,
          GUID = "7FB38226",
          NextDialogue = 51011208,
          SpeakNpcId = 700339
        },
        [51011208] = {
          Content = "……",
          DialogueId = 51011208,
          GUID = "7FB38250",
          NextDialogue = 51011209,
          SpeakNpcId = 100001
        },
        [51011209] = {
          Content = "有什么事直接说就好。",
          DialogueId = 51011209,
          GUID = "7FB3827A",
          NextDialogue = 51011210,
          SpeakNpcId = 700339
        },
        [51011210] = {
          Content = "没什么，只是你好像一直在看很远的地方，是在找什么吗？",
          DialogueId = 51011210,
          GUID = "7FB382A4",
          NextDialogue = 51011211,
          SpeakNpcId = 100001
        },
        [51011211] = {
          Content = "是吗……说不定，我没有在看向任何地方呢？",
          DialogueId = 51011211,
          GUID = "7FB382CE",
          NextDialogue = 51011212,
          SpeakNpcId = 700339
        },
        [51011212] = {
          Content = "就只是……无意义地消磨时间而已。",
          DialogueId = 51011212,
          GUID = "7FB382F8",
          NextOptions = {
            [1] = 51011213,
            [2] = 51011215
          },
          SpeakNpcId = 700339
        },
        [51011213] = {
          Content = "我有时也会像这样发呆，感觉心情会变得平静。",
          DialogueId = 51011213,
          GUID = "7FB38322",
          ImprPlusId = 1004,
          NextDialogue = 51011214
        },
        [51011214] = {
          Content = "“有时”吗……看来你和我是不一样的人……",
          DialogueId = 51011214,
          GUID = "7FB3834C",
          NextDialogue = 51011217,
          SpeakNpcId = 700339
        },
        [51011215] = {
          Content = "要不要聊聊别的话题，比如——晚饭吃什么？",
          DialogueId = 51011215,
          GUID = "7FB38376",
          ImprPlusId = 1001,
          NextDialogue = 51011216
        },
        [51011216] = {
          Content = "随便——我知道这算不上回答，但我的确没什么想吃的东西。",
          DialogueId = 51011216,
          GUID = "7FB383A0",
          NextDialogue = 51011217,
          SpeakNpcId = 700339
        },
        [51011217] = {
          Content = "（少女垂下头去，不再多言。）",
          DialogueId = 51011217,
          GUID = "7FB383CA",
          NextDialogue = 51011218
        },
        [51011218] = {
          Content = "（每个人都会有旁人无法得知的困境，并且终有一日将要独自面对。）",
          DialogueId = 51011218,
          GUID = "7FB383F4",
          NextDialogue = 51011219
        },
        [51011219] = {
          Content = "（也许此刻的她还没有鼓起勇气，那就让她自己先静一静吧——你这样想着。）",
          DialogueId = 51011219,
          GUID = "7FB3841E"
        },
        [51011220] = {
          Content = "无视她",
          DialogueId = 51011220,
          GUID = "7FB38448",
          NextDialogue = 51011221
        },
        [51011221] = {
          Content = "（或许是她过于阴郁的表情在周围凝结出了一片生人勿近的气场，你决定还是不要多管闲事了。）",
          DialogueId = 51011221,
          GUID = "7FB38472",
          Scripts = "SetOutport{FinishType{\"Fail\"}}"
        },
        [51011301] = {
          Content = "离我远一点……我什么都不知道！！",
          DialogueId = 51011301,
          GUID = "7FB39192",
          NextDialogue = 51011302,
          SpeakNpcId = 700341
        },
        [51011302] = {
          Content = "我只是想看看那只怀表，或许能修好也说不定。",
          DialogueId = 51011302,
          GUID = "7FB391BC",
          NextDialogue = 51011303,
          SpeakNpcId = 100001
        },
        [51011303] = {
          Content = "……",
          DialogueId = 51011303,
          GUID = "7FB391E6",
          NextDialogue = 51011304,
          SpeakNpcId = 700341
        },
        [51011304] = {
          Content = "那是很重要的东西吧？",
          DialogueId = 51011304,
          GUID = "7FB39210",
          NextDialogue = 51011305,
          SpeakNpcId = 100001
        },
        [51011305] = {
          Content = "真的……能修好吗？",
          DialogueId = 51011305,
          GUID = "7FB3923A",
          NextOptions = {
            [1] = 51011306,
            [2] = 51011312
          },
          SpeakNpcId = 700341
        },
        [51011306] = {
          Content = "你愿意让我试试吗？",
          DialogueId = 51011306,
          GUID = "7FB39264",
          ImprPlusId = 1004,
          NextDialogue = 51011307
        },
        [51011307] = {
          Content = "我……我不知道……",
          DialogueId = 51011307,
          GUID = "7FB3928E",
          NextDialogue = 51011308,
          SpeakNpcId = 700341
        },
        [51011308] = {
          Content = "亨特……我该怎么做？",
          DialogueId = 51011308,
          GUID = "7FB392B8",
          NextDialogue = 51011309,
          SpeakNpcId = 700341
        },
        [51011309] = {
          Content = "所以，亨特他到底发生了什么？",
          DialogueId = 51011309,
          GUID = "7FB392E2",
          NextDialogue = 51011310,
          SpeakNpcId = 100001
        },
        [51011310] = {
          Content = "他……",
          DialogueId = 51011310,
          GUID = "7FB3930C",
          NextDialogue = 51011311,
          SpeakNpcId = 700341
        },
        [51011311] = {
          Content = "不，我不能说。请你离开这里吧，不要再来了。",
          DialogueId = 51011311,
          GUID = "7FB39336",
          NextDialogue = 51011317,
          SpeakNpcId = 700341
        },
        [51011312] = {
          Content = "城里应该有钟表匠吧，我们可以找他们帮忙。",
          DialogueId = 51011312,
          GUID = "7FB39360",
          ImprPlusId = 1003,
          NextDialogue = 51011313
        },
        [51011313] = {
          Content = "那请你……",
          DialogueId = 51011313,
          GUID = "7FB3938A",
          NextDialogue = 51011314,
          SpeakNpcId = 700341
        },
        [51011314] = {
          Content = "不……不可以相信外面的人。",
          DialogueId = 51011314,
          GUID = "7FB393B4",
          NextDialogue = 51011315,
          SpeakNpcId = 700341
        },
        [51011315] = {
          Content = "当我什么都没说过吧。",
          DialogueId = 51011315,
          GUID = "7FB393DE",
          NextDialogue = 51011316,
          SpeakNpcId = 700341
        },
        [51011316] = {
          Content = "请你离开这里，不要再来了。",
          DialogueId = 51011316,
          GUID = "7FB39408",
          NextDialogue = 51011317,
          SpeakNpcId = 700341
        },
        [51011317] = {
          Content = "（少女的情绪转变让你一时间不知道该如何应对，只能试图从她的眼神中得到更多信息。）",
          DialogueId = 51011317,
          GUID = "7FB39432",
          NextDialogue = 51011318
        },
        [51011318] = {
          Content = "（那是双充满迷茫与悲伤的眼睛，却又夹杂着一丝不易察觉的信念。你并不知道那信念从何而来，又意味着什么。但你明白这就是她守口如瓶的原因。）",
          DialogueId = 51011318,
          GUID = "7FB3945C"
        },
        [51011401] = {
          Content = "桌子……擦过了。地板……也擦过了。还剩……扶手，对，还有扶手。",
          DialogueId = 51011401,
          GUID = "7FB3A1FA",
          NextDialogue = 51011402,
          SpeakNpcId = 700340
        },
        [51011402] = {
