        },
        [60040401] = {
          Content = "检查站的门可以开啦，继续出发！滴滴滴~",
          DialogueId = 60040401,
          Duration = 4,
          GUID = "964E0A4A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600404/964E0A4A"
        },
        [60040501] = {
          Content = "车子被前面的障碍物拦住了，破坏掉它吧！",
          DialogueId = 60040501,
          Duration = 4,
          GUID = "964E1AB2",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600405/964E1AB2"
        },
        [60040601] = {
          Content = "不行呀，障碍物还是没碎，全力破坏它然后冲过去吧！",
          DialogueId = 60040601,
          Duration = 4,
          GUID = "964E2B1A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600406/964E2B1A"
        },
        [60040701] = {
          Content = "哼哼，小小障碍物怎么可能拦得住我们嘛，去车子边继续发信号让委托人把车子开起来吧！",
          DialogueId = 60040701,
          Duration = 4,
          GUID = "964E3B82",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600407/964E3B82"
        },
        [60040801] = {
          Content = "可恶，检查站的门被关上了！打倒那个军官然后冲过去吧！",
          DialogueId = 60040801,
          Duration = 4,
          GUID = "964E3B86",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600408/964E3B86"
        },
        [60050101] = {
          Content = "这次委托是让我们把这片区域的敌人都驱逐出去吗？真是简单易懂呀，让我们放开手脚大干一场吧！",
          DialogueId = 60050101,
          Duration = 4,
          GUID = "965441B2",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600501/965441B2"
        },
        [60050201] = {
          Content = "驱逐了这么多敌人，他们总该吸取教训了吧！收工收工，回去领报酬喽。",
          DialogueId = 60050201,
          Duration = 4,
          GUID = "9654521A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600502/9654521A"
        },
        [60060101] = {
          Content = "目标已倒下，委托失败。",
          DialogueId = 60060101,
          Duration = 1,
          GUID = "965AAA52",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/0/600601/965AAA52"
        },
        [60060201] = {
          Content = "这次的委托有点复杂，我们得先解救被困的目标，再护送目标安全撤离。",
          DialogueId = 60060201,
          Duration = 4,
          GUID = "965ABABA",
          NextDialogue = 60060202,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600602/965ABABA"
        },
        [60060202] = {
          Content = "先按照委托人给的标记，找到敌人据点里的<H>密室区域</>吧。",
          DialogueId = 60060202,
          Duration = 4,
          GUID = "965ABAE4",
          NextDialogue = 60060203,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600602/965ABAE4"
        },
        [60060203] = {
          Content = "说起来，这个目标到底是什么人啊……值这么多钱又神神秘秘的，该不会是什么大人物吧？",
          DialogueId = 60060203,
          Duration = 4,
          GUID = "965ABB0E",
          NextDialogue = 60060204,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600602/965ABB0E"
        },
        [60060204] = {
          Content = "又或者，是和委托人有什么不可告人的关系……哼哼……",
          DialogueId = 60060204,
          Duration = 4,
          GUID = "965ABB38",
          NextDialogue = 60060205,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600602/965ABB38"
        },
        [60060205] = {
          Content = "你别忘了，委托人说过不要多问，否则我们就拿不到钱了。",
          DialogueId = 60060205,
          Duration = 4,
          GUID = "965ABB62",
          NextDialogue = 60060206,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/0/600602/965ABB62"
        },
        [60060206] = {
          Content = "呃——好吧，那我就忍一忍，不好奇了。",
          DialogueId = 60060206,
          Duration = 3,
          GUID = "965ABB8C",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600602/965ABB8C"
        },
        [60060301] = {
          Content = "根据事先调查到的情报，密室区域是由很多独立的小房间组成的，其中一间关着我们要找的目标。",
          DialogueId = 60060301,
          Duration = 4,
          GUID = "965ACB22",
          NextDialogue = 60060302,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600603/965ACB22"
        },
        [60060302] = {
          Content = "看来敌人很谨慎啊！万一发现有人来营救，他们搞不好会破罐破摔，把目标灭口……",
          DialogueId = 60060302,
          Duration = 4,
          GUID = "965ACB4C",
          NextDialogue = 60060303,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600603/965ACB4C"
        },
        [60060303] = {
          Content = "尽量小心一些吧！",
          DialogueId = 60060303,
          Duration = 2.5,
          GUID = "965ACB76",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600603/965ACB76"
        },
        [60060401] = {
          Content = "快看，前面就是密室区域了！要注意避开敌人中的<H>巡逻单位</>哦！",
          DialogueId = 60060401,
          Duration = 4,
          GUID = "965ADB8A",
          NextDialogue = 60060402,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600604/965ADB8A"
        },
        [60060402] = {
          Content = "如果他们发出了警报，目标可就危险啦。",
          DialogueId = 60060402,
          Duration = 3,
          GUID = "965ADBB4",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600604/965ADBB4"
        },
        [60060501] = {
          Content = "呜哇，这些密室还真是长得一模一样啊……不过，以小仆从的聪明才智，解开这些机关绰绰有余。",
          DialogueId = 60060501,
          Duration = 4,
          GUID = "965AEBF2",
          NextDialogue = 60060502,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600605/965AEBF2"
        },
        [60060502] = {
          Content = "抓紧时间找到目标所在的密室吧！本魔王会在旁边帮你注意动静的。",
          DialogueId = 60060502,
          Duration = 4,
          GUID = "965AEC1C",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600605/965AEC1C"
        },
        [60060601] = {
          Content = "不、不要靠近我……！",
          DialogueId = 60060601,
          Duration = 2.5,
          GUID = "965AFC5A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 60060602,
          SpeakNpcId = 930001,
          VoiceName = "voice/$Locale$/story/0/600606/965AFC5A"
        },
        [60060602] = {
          Content = "别怕，我们是狩月人，来救你的！",
          DialogueId = 60060602,
          Duration = 3,
          GUID = "965AFC84",
          NextDialogue = 60060603,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600606/965AFC84"
        },
        [60060603] = {
          Content = "咦……？啊，我知道了，是那个人让你们来的，一定是的……",
          DialogueId = 60060603,
          Duration = 4,
          GUID = "965AFCAE",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 60060604,
          SpeakNpcId = 930001,
          VoiceName = "voice/$Locale$/story/0/600606/965AFCAE"
        },
        [60060604] = {
          Content = "谢谢！我们快走吧，我等不及要见到……",
          DialogueId = 60060604,
          Duration = 4,
          GUID = "965AFCD8",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 930001,
          VoiceName = "voice/$Locale$/story/0/600606/965AFCD8"
        },
        [60060701] = {
          Content = "不好啦，那个巡逻的家伙发出了警报！",
          DialogueId = 60060701,
          Duration = 3,
          GUID = "965B0CC2",
          NextDialogue = 60060702,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600607/965B0CC2"
        },
        [60060702] = {
          Content = "和我想的一样，他们果然狗急跳墙，打算把目标处理掉了！",
          DialogueId = 60060702,
          Duration = 4,
          GUID = "965B0CEC",
          NextDialogue = 60060703,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600607/965B0CEC"
        },
        [60060703] = {
          Content = "得赶在他们之前救出目标才行。",
          DialogueId = 60060703,
          Duration = 2,
          GUID = "965B0D16",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600607/965B0D16"
        },
        [60060801] = {
          Content = "哎，我好像听见目标的呼救声了！",
          DialogueId = 60060801,
          Duration = 2,
          GUID = "965B1D2A",
          NextDialogue = 60060802,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600608/965B1D2A"
        },
        [60060802] = {
          Content = "就是那间密室，快去救人吧！",
          DialogueId = 60060802,
          Duration = 2,
          GUID = "965B1D54",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600608/965B1D54"
        },
        [60060901] = {
          Content = "我……好像动不了了……拜托，请救救我……！",
          DialogueId = 60060901,
          Duration = 3,
          GUID = "965B2D92",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 60060902,
          SpeakNpcId = 930001,
          VoiceName = "voice/$Locale$/story/0/600609/965B2D92"
        },
        [60060902] = {
          Content = "我不能……在这里……倒下……我还没有……",
          DialogueId = 60060902,
          Duration = 3,
          GUID = "965B3DFA",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 930001,
          VoiceName = "voice/$Locale$/story/0/600609/965B3DFA"
        },
        [60110101] = {
          Content = "这次的任务是追捕目标，如果他要反抗的话，就只好先打倒他了。",
          DialogueId = 60110101,
          Duration = 4,
          GUID = "967AB572",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601101/967AB572"
        },
        [60110201] = {
          Content = "目标被打倒啦，赶紧在他恢复体力逃跑前抓住目标吧。",
          DialogueId = 60110201,
          Duration = 4,
          GUID = "967AC5DA",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601102/967AC5DA"
        },
        [60110301] = {
          Content = "任务完成啦，我们也准备离开吧。",
          DialogueId = 60110301,
          Duration = 4,
          GUID = "967AD642",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601103/967AD642"
        },
        [60110501] = {
          Content = "这次的目标擅长<H>潜匿</>，不仅可以隐藏自己……",
          DialogueId = 60110501,
          Duration = 4,
          GUID = "967AF712",
          NextDialogue = 60110502,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601105/967AF712"
        },
        [60110502] = {
          Content = "还能用模样相同的替身迷惑对手！不要被他骗啦！",
          DialogueId = 60110502,
          Duration = 4,
          GUID = "967AF73C",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601105/967AF73C"
        },
        [60110601] = {
          Content = "这次的目标十分<H>善战</>，还随身携带着机器人提升自己的战斗能力！",
          DialogueId = 60110601,
          Duration = 4,
          GUID = "967B077A",
          NextDialogue = 60110602,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601106/967B077A"
        },
        [60110602] = {
          Content = "爆破机器人会自爆造成伤害，务必小心！",
          DialogueId = 60110602,
          Duration = 4,
          GUID = "967B07A4",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601106/967B07A4"
        },
        [60110701] = {
          Content = "这次的目标有着丰富的<H>武装</>，小心他的地雷和枪托！",
          DialogueId = 60110701,
          Duration = 4,
          GUID = "967B180C",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601107/967B180C"
        },
        [60120101] = {
          Content = "这就是我们要勘察的区域啦，让我找找哪里适合放下我宝贵的勘探器。",
          DialogueId = 60120101,
          Duration = 4,
          GUID = "96811E12",
          SpeakNpcId = 900005,
          VoiceName = "voice/$Locale$/story/0/601201/96811E12"
        },
        [60120201] = {
          Content = "勘探器装好啦，记得要保护好它哦，如果它不动了，那就从敌人身上找点勘探模组带回来吧。",
          DialogueId = 60120201,
          Duration = 4,
          GUID = "96812E7A",
          SpeakNpcId = 900005,
          VoiceName = "voice/$Locale$/story/0/601202/96812E7A"
        },
        [60120301] = {
          Content = "勘察完成，这是谢礼，你要陪我继续勘察还是回去休息呢？",
          DialogueId = 60120301,
          Duration = 4,
          GUID = "96813EE2",
          SpeakNpcId = 900005,
          VoiceName = "voice/$Locale$/story/0/601203/96813EE2"
        },
        [60120401] = {
          Content = "勘探器不动啦，去找点勘探模组回来吧。",
          DialogueId = 60120401,
          Duration = 4,
          GUID = "96814F4A",
          SpeakNpcId = 900005,
          VoiceName = "voice/$Locale$/story/0/601204/96814F4A"
        },
        [60120501] = {
          Content = "那边有个地方也需要勘探一下，我帮你标注出来了，等你过去了我就装一下勘探器。",
          DialogueId = 60120501,
          Duration = 4,
          GUID = "96815FB2",
          SpeakNpcId = 900005,
          VoiceName = "voice/$Locale$/story/0/601205/96815FB2"
        },
        [60120601] = {
          Content = "没错没错，你拿的这些就是勘探模组了，去把它们装到我宝贵的勘探器里吧！",
          DialogueId = 60120601,
          Duration = 4,
          GUID = "9681701A",
          SpeakNpcId = 900005,
          VoiceName = "voice/$Locale$/story/0/601206/9681701A"
        },
        [60130101] = {
          Content = "神弃者同盟在这里安装了很危险的炸弹！不阻止它爆炸的话所有人都危险了。",
          DialogueId = 60130101,
          Duration = 4,
          GUID = "968786B2",
          NextDialogue = 60130102,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601301/968786B2"
        },
        [60130102] = {
          Content = "委托人说有三名神弃者同盟成员策划了这起爆炸，找到他们的话我会告诉你。",
          DialogueId = 60130102,
          Duration = 4,
          GUID = "968786DC",
          NextDialogue = 60130103,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601301/968786DC"
        },
        [60130103] = {
          Content = "要是先击败他们再去破坏“大烟花”的引信，应该能让委托变轻松很多的吧！",
          DialogueId = 60130103,
          Duration = 4,
          GUID = "968787DE",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601301/968787DE"
        },
        [60130201] = {
          Content = "打倒一个！从他身上的信件来看……找到了，另外两名神弃者同盟成员大概就在我标的这片区域。",
          DialogueId = 60130201,
          Duration = 4,
          GUID = "9687971A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601302/9687971A"
        },
        [60130301] = {
          Content = "“大烟花”的引信暴露出来了，破坏掉它吧！",
          DialogueId = 60130301,
          Duration = 4,
          GUID = "9687A782",
          NextDialogue = 60130302,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601303/9687A782"
        },
        [60130302] = {
          Content = "真是的，这炸弹明明不是我们装的，周围的敌人怎么都冲着我们来啦……",
          DialogueId = 60130302,
          Duration = 4,
          GUID = "9687A784",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601303/9687A784"
        },
        [60130401] = {
          Content = "拆掉“大烟花”了，我们也快跑吧。",
          DialogueId = 60130401,
          Duration = 4,
          GUID = "9687B7EA",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601304/9687B7EA"
        },
        [60130501] = {
          Content = "发现神弃者同盟的首领了！",
          DialogueId = 60130501,
          Duration = 4,
          GUID = "9687C852",
          NextDialogue = 60130502,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601305/9687C852"
        },
        [60130502] = {
          Content = "既然委托让我们阻止“大烟花”爆炸，那打倒这些首领也会对我们的计划更有利吧，我们上！",
          DialogueId = 60130502,
          Duration = 4,
          GUID = "9687C87C",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601305/9687C87C"
        },
        [60130601] = {
          Content = "我的杰作……还没完成……",
          DialogueId = 60130601,
          Duration = 4,
          GUID = "9687C880",
          SpeakNpcId = 200034,
          VoiceName = "voice/$Locale$/story/0/601305/9687C880"
        },
        [60130701] = {
          Content = "傲慢而盲目的家伙们，一起加入这场混战吧！",
          DialogueId = 60130701,
          Duration = 4,
          GUID = "9687C884",
          SpeakNpcId = 200035,
          VoiceName = "voice/$Locale$/story/0/601305/9687C884"
        },
        [60130801] = {
          Content = "原来，我才是玩具……有趣。那就让我看看，你要如何逃离死亡。",
          DialogueId = 60130801,
          Duration = 4,
          GUID = "9687C888",
          SpeakNpcId = 200036,
          VoiceName = "voice/$Locale$/story/0/601305/9687C888"
        },
        [60140001] = {
          Content = "……呵，困兽之斗。",
          DialogueId = 60140001,
          Duration = 4,
          GUID = "968DDEEA",
          VoiceName = "sfx/boss/Xibi/vo_$Locale$_battleStart"
        },
        [60140002] = {
          Content = "让我看看你的极限。",
          DialogueId = 60140002,
          Duration = 4,
          GUID = "968DDF14",
          VoiceName = "sfx/boss/Xibi/vo_$Locale$_battleEnd"
        },
        [60140003] = {
          Content = "勇气可嘉，继续。",
          DialogueId = 60140003,
          Duration = 4,
          GUID = "968DDF3E",
          VoiceName = "sfx/boss/Xibi/vo_$Locale$_condemn"
        },
        [60140004] = {
          Content = "闹剧，该结束了。",
          DialogueId = 60140004,
          Duration = 4,
          GUID = "968DDF68",
          VoiceName = "sfx/boss/Xibi/vo_$Locale$_skill06"
        },
        [60140005] = {
          Content = "颤栗吧。",
          DialogueId = 60140005,
          Duration = 4,
          GUID = "968DDF92",
          VoiceName = "sfx/boss/Xibi/vo_$Locale$_skill07_01"
        },
        [60140006] = {
          Content = "蝼蚁，无处可藏。",
          DialogueId = 60140006,
          Duration = 4,
          GUID = "968DDFBC",
          VoiceName = "sfx/boss/Xibi/vo_$Locale$_skill07_02"
        },
        [60140201] = {
          Content = "……不要……过来……！",
          DialogueId = 60140201,
          Duration = 4,
          GUID = "968DFFBA",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_battleStart"
        },
        [60140202] = {
          Content = "是的。我没有……活下去的……资格……",
          DialogueId = 60140202,
          Duration = 6,
          GUID = "968DFFE4",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_flyingStageStart"
        },
        [60140203] = {
          Content = "啊啊——",
          DialogueId = 60140203,
          Duration = 4,
          GUID = "968E000E",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_flyingStageEnd"
        },
        [60140204] = {
          Content = "呃啊啊啊啊——",
          DialogueId = 60140204,
          Duration = 4,
          GUID = "968E0038",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_Condemn"
        },
        [60140205] = {
          Content = "……谢谢……你……",
          DialogueId = 60140205,
          Duration = 5,
          GUID = "968E0062",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_battleEnd"
        },
        [60140206] = {
          Content = "……啊啊……",
          DialogueId = 60140206,
          Duration = 2,
          GUID = "968E008C",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_skill03"
        },
        [60140207] = {
          Content = "……快……逃……！",
          DialogueId = 60140207,
          Duration = 4,
          GUID = "968E00B6",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_skill10"
        },
        [60140401] = {
          Content = "我最亲爱的孩子，谢谢你来到世界上。",
          DialogueId = 60140401,
          Duration = 4,
          GUID = "968E208A",
          VoiceName = "voice/$Locale$/story/1002/101125/968E208A"
        },
        [60140402] = {
          Content = "你是我们一生的骄傲。",
          DialogueId = 60140402,
          Duration = 3,
          GUID = "968E20B4",
          VoiceName = "voice/$Locale$/story/1002/101125/968E20B4"
        },
        [60140403] = {
          Content = "赛琪，来拉钩，我们要做一辈子的好朋友！",
          DialogueId = 60140403,
          Duration = 4,
          GUID = "968E20DE",
          VoiceName = "voice/$Locale$/story/1002/101125/968E20DE"
        },
        [60140404] = {
          Content = "我会记住你曾经活过。",
          DialogueId = 60140404,
          Duration = 3,
          GUID = "968E2108",
          VoiceName = "voice/$Locale$/story/1002/101125/968E2108"
        },
        [60140405] = {
          Content = "我们等你回来。",
          DialogueId = 60140405,
          Duration = 2.5,
          GUID = "968E2132",
          VoiceName = "voice/$Locale$/story/1002/101125/968E2132"
        },
        [60140406] = {
          Content = "命运啊，求你怜悯我唯一一次，让我帮她实现这个愿望吧。",
          DialogueId = 60140406,
          Duration = 6,
          GUID = "968E215C",
          VoiceName = "voice/$Locale$/story/1002/101125/968E215C"
        },
        [60140407] = {
          Content = "带上这朵花吧，它会给你带来好运。",
          DialogueId = 60140407,
          Duration = 3,
          GUID = "968E2186",
          VoiceName = "voice/$Locale$/story/1002/101125/968E2186"
        },
        [60140408] = {
          Content = "你可以去一座小岛，在那里盖几间房子，在房子边种满白色的花。",
          DialogueId = 60140408,
          Duration = 6,
          GUID = "968E21B0",
          VoiceName = "voice/$Locale$/story/1002/101125/968E21B0"
        },
        [60140409] = {
          Content = "赛琪，我来带你回家。",
          DialogueId = 60140409,
          Duration = 3,
          GUID = "968E21DA",
          VoiceName = "voice/$Locale$/story/1002/101125/968E21DA"
        },
        [60140501] = {
          Content = "所有审判，皆为正义。",
          DialogueId = 60140501,
          Duration = 5,
          GUID = "968E30F2",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_battleStart"
        },
        [60140502] = {
          Content = "竟敢反抗律法……",
          DialogueId = 60140502,
          Duration = 5,
          GUID = "968E311C",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_condemn"
        },
        [60140503] = {
          Content = "你……在怒火面前证明了自己。",
          DialogueId = 60140503,
          Duration = 5,
          GUID = "968E3146",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_battleEnd"
        },
        [60140504] = {
          Content = "开始你最后的狡辩。",
          DialogueId = 60140504,
          Duration = 5,
          GUID = "968E3170",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_skill06_01"
        },
        [60140505] = {
          Content = "在宣判前，丑陋地挣扎吧。",
          DialogueId = 60140505,
          Duration = 5,
          GUID = "968E319A",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_skill06_02"
        },
        [60140506] = {
          Content = "在枷锁中迎接死亡。",
          DialogueId = 60140506,
          Duration = 5,
          GUID = "968E31C4",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_skill08_01"
        },
        [60140507] = {
          Content = "律法会历数你的罪状。",
          DialogueId = 60140507,
          Duration = 5,
          GUID = "968E31EE",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_skill08_02"
        },
        [60140508] = {
          Content = "休想逃脱火焰的囚笼。",
          DialogueId = 60140508,
          Duration = 5,
          GUID = "968E3218",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_skill03"
        },
        [60149001] = {
          Content = "打打打打打劫，唔……这家伙看起来好猛，溜了溜了。",
          DialogueId = 60149001,
          Duration = 5,
          GUID = "9693A37A",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_birth_r01"
        },
        [60149002] = {
          Content = "可恶！怎么是你，再再再见。",
          DialogueId = 60149002,
          Duration = 3.8,
          GUID = "9693A3A4",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_birth_r02"
        },
        [60149003] = {
          Content = "留留留下买路财！啧，怎么今天一上来就碰到硬茬子，告辞。",
          DialogueId = 60149003,
          Duration = 6.7,
          GUID = "9693A3CE",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_birth_r03"
        },
        [60149004] = {
          Content = "除了打劫，逃跑我也是专业的！",
          DialogueId = 60149004,
          Duration = 3.5,
          GUID = "9693A3F8",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Skill01"
        },
        [60149005] = {
          Content = "舍不得孩子套不着狼，这些都给你，别再追啦！",
          DialogueId = 60149005,
          Duration = 5.1,
          GUID = "9693A422",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Skill02"
        },
        [60149006] = {
          Content = "咋还在追我啊，这个给你行了吧。",
          DialogueId = 60149006,
          Duration = 3.5,
          GUID = "9693A44C",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Skill03"
        },
        [60149007] = {
          Content = "你使那么大劲干啥呢！",
          DialogueId = 60149007,
          Duration = 2.5,
          GUID = "9693A476",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_be_hit_heavy_r01"
        },
        [60149008] = {
          Content = "可恶，以后走夜路小心点！",
          DialogueId = 60149008,
          Duration = 3.2,
          GUID = "9693A4A0",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_be_hit_heavy_r02"
        },
        [60149009] = {
          Content = "啊啊啊啊啊，我要生气了！",
          DialogueId = 60149009,
          Duration = 3.4,
          GUID = "9693A4CA",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_be_hit_heavy_r03"
        },
        [60149010] = {
          Content = "笨笨笨蛋，追不上我吧，桀桀桀桀桀桀~",
          DialogueId = 60149010,
          Duration = 6,
          GUID = "9693A4F4",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Skill04"
        },
        [60149011] = {
          Content = "这次是我大意了，下次我一定要把你打得抱头大哭，呜……",
          DialogueId = 60149011,
          Duration = 10.4,
          GUID = "9693A51E",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_death"
        },
        [60149012] = {
          Content = "东西南北四条街，打听打听谁是爹，道上谁不知道我打劫皎皎的名号！",
          DialogueId = 60149012,
          Duration = 6.9,
          GUID = "9693A548",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Run_r01"
        },
        [60149013] = {
          Content = "跟我斗，你还是太年轻了呀~",
          DialogueId = 60149013,
          Duration = 5.7,
          GUID = "9693A572",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Run_r02"
        },
        [60149014] = {
          Content = "哼，我打打打劫皎皎可不是好惹的。",
          DialogueId = 60149014,
          Duration = 4.8,
          GUID = "9693A59C",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Run_r03"
        },
        [60149015] = {
          Content = "呼，呼……你咋还不累呢，吃啥玩意长大的啊。",
          DialogueId = 60149015,
          Duration = 8.8,
          GUID = "9693A5C6",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Run_r04"
        },
        [60150001] = {
          Content = "离我远点！",
          DialogueId = 60150001,
          Duration = 3,
          GUID = "9694478A",
          SpeakNpcId = 200053,
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Attack01"
        },
        [60150002] = {
          Content = "非要吃点苦头？",
          DialogueId = 60150002,
          Duration = 3,
          GUID = "969447B4",
          SpeakNpcId = 200053,
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Attack02"
        },
        [60150003] = {
          Content = "我跑不动了……我投降……",
          DialogueId = 60150003,
          Duration = 5,
          GUID = "969447DE",
          SpeakNpcId = 200053,
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Die"
        },
        [60150004] = {
          Content = "别逞能了！",
          DialogueId = 60150004,
          Duration = 3,
          GUID = "96944808",
          SpeakNpcId = 200053,
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Skill01"
        },
        [60150005] = {
          Content = "别追了!",
          DialogueId = 60150005,
          Duration = 3,
          GUID = "96944832",
          SpeakNpcId = 200053,
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Skill02"
        },
        [60150006] = {
          Content = "追不上的你们！",
          DialogueId = 60150006,
          Duration = 4,
          GUID = "9694485C",
          SpeakNpcId = 200053,
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Skill03"
        },
        [60160001] = {
          Content = "开启锯轮攻击！（待包装）",
          DialogueId = 60160001,
          Duration = 4,
          GUID = "969AB02A",
          SpeakNpcId = 920001
        },
        [60160002] = {
          Content = "持续轰炸目标！（待包装）",
          DialogueId = 60160002,
          Duration = 4,
          GUID = "969AB054",
          SpeakNpcId = 920001
        },
        [60160003] = {
          Content = "列车，提速，狂暴模式！！（待包装）",
          DialogueId = 60160003,
          Duration = 4,
          GUID = "969AB07E",
          SpeakNpcId = 920001
        },
        [60160004] = {
          Content = "连锁型-炸弹攻击！（待包装）",
          DialogueId = 60160004,
          Duration = 4,
          GUID = "969AB0A8",
          SpeakNpcId = 920001
        },
        [60160005] = {
          Content = "追踪型-炸弹攻击！（待包装）",
          DialogueId = 60160005,
          Duration = 4,
          GUID = "969AB0D2",
          SpeakNpcId = 920001
        },
        [60170001] = {
          Content = "死……死！",
          DialogueId = 60170001,
          Duration = 1.5,
          GUID = "96A118CA",
          VoiceName = "sfx/boss/Tuosi/vo_$Locale$_BattleStart01"
        },
        [60170002] = {
          Content = "吼……呃……啊啊啊啊……",
          DialogueId = 60170002,
          Duration = 1.5,
          GUID = "96A118F4",
          VoiceName = "sfx/boss/Tuosi/vo_$Locale$_Skill06"
        },
        [60170003] = {
          Content = "嘎嗷嗷嗷……吼……吼！！",
          DialogueId = 60170003,
          Duration = 4,
          GUID = "96A1191E",
          VoiceName = "sfx/boss/Tuosi/vo_$Locale$_Skill08"
        },
        [60200101] = {
          Content = "不好，我们被敌人发现了！",
          DialogueId = 60200101,
          Duration = 4,
          GUID = "96B46312",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602001/96B46312"
        },
        [60200201] = {
          Content = "发现敌人，在他们呼叫同伴前阻止他们吧。",
          DialogueId = 60200201,
          Duration = 4,
          GUID = "96B4737A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602002/96B4737A"
        },
        [60200301] = {
          Content = "当心，敌人要去呼叫同伴了！再这样下去就麻烦啦。",
          DialogueId = 60200301,
          Duration = 4,
          GUID = "96B483E2",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602003/96B483E2"
        },
        [60200401] = {
          Content = "他们要去呼叫同伴，快想想办法阻止一下呀！",
          DialogueId = 60200401,
          Duration = 4,
          GUID = "96B4944A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602004/96B4944A"
        },
        [60200501] = {
          Content = "真是的，我们躲藏得这么好居然都被发现了，没办法，快点解决掉他们吧。",
          DialogueId = 60200501,
          Duration = 4,
          GUID = "96B4A4B2",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602005/96B4A4B2"
        },
        [60210101] = {
          Content = "委托人只能帮我们争取到一点点时间，我们趁现在快把那三台奇奇怪怪的装置拆掉吧！",
          DialogueId = 60210101,
          Duration = 4,
          GUID = "9687C88C",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602101/9687C88C"
        },
        [60210201] = {
          Content = "好耶，全都拆掉了，委托圆满完成！",
          DialogueId = 60210201,
          Duration = 3,
          GUID = "9687C892",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602102/9687C892"
        },
        [60210301] = {
          Content = "委托人说没时间了，我们也快撤吧！",
          DialogueId = 60210301,
          Duration = 3,
          GUID = "9687C896",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602103/9687C896"
        },
        [60220101] = {
          Content = "什么什么，第一场比赛这就开始了吗？",
          DialogueId = 60220101,
          Duration = 4,
          GUID = "9687C89A",
          NextDialogue = 60220102,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602201/9687C89A"
        },
        [60220102] = {
          Content = "我看看哇……第一场我们要做的是淘汰“神奇的同盟”这支队伍的种子选手！",
          DialogueId = 60220102,
          Duration = 3,
          GUID = "9687C89E",
          NextDialogue = 60220103,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602201/9687C89E"
        },
        [60220103] = {
          Content = "但我们根本不知道其他人藏在哪嘛！去周围找找线索吧。",
          DialogueId = 60220103,
          Duration = 3,
          GUID = "9687C8A2",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602201/9687C8A2"
        },
        [60220201] = {
          Content = "知道他们的种子选手藏在哪了！去打败啊不是，淘汰他们吧~",
          DialogueId = 60220201,
          Duration = 3,
          GUID = "9687C8A6",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602202/9687C8A6"
        },
        [60220301] = {
          Content = "下场好像是个抢地盘的比赛耶，我们快过去吧。",
          DialogueId = 60220301,
          Duration = 3,
          GUID = "9687C8AA",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602203/9687C8AA"
        },
        [60220401] = {
          Content = "把他们从指定区域赶走！这场比赛的胜利必将属于我们“军团长天下第一”。",
          DialogueId = 60220401,
          Duration = 4,
          GUID = "9687C8AE",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930002,
          VoiceName = "voice/$Locale$/story/0/602204/9687C8AE"
        },
        [60220501] = {
          Content = "军团的骄傲，靠你们了。",
          DialogueId = 60220501,
          Duration = 4,
          GUID = "9687C8B2",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930002,
          VoiceName = "voice/$Locale$/story/0/602205/9687C8B2"
        },
        [60220601] = {
          Content = "可恶，居然如此难缠，看来不是保留实力的时候了。",
          DialogueId = 60220601,
          Duration = 4,
          GUID = "9687C8B6",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930002,
          VoiceName = "voice/$Locale$/story/0/602206/9687C8B6"
        },
        [60220701] = {
          Content = "虽然输了……但下场比赛，我们还有机会！",
          DialogueId = 60220701,
          Duration = 3,
          GUID = "9687C8BA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930002,
          VoiceName = "voice/$Locale$/story/0/602207/9687C8BA"
        },
        [60220801] = {
          Content = "终于到第三场比赛了呀，快去奖箱那里吧，绝不能让其他人抢走！",
          DialogueId = 60220801,
          Duration = 4,
          GUID = "9687C8BE",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602208/9687C8BE"
        },
        [60220901] = {
          Content = "开始了开始了！从这群家伙手里夺回钥匙，打开最后的宝箱吧。",
          DialogueId = 60220901,
          Duration = 3,
          GUID = "9687C8C2",
          NextDialogue = 60220902,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602209/9687C8C2"
        },
        [60220902] = {
          Content = "一群异教徒，妄想染指神赐的宝物。准备好承受祂的怒火了吗？",
          DialogueId = 60220902,
          Duration = 4,
          GUID = "9687C8C4",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930003,
          VoiceName = "voice/$Locale$/story/0/602209/9687C8C4"
        },
        [60221001] = {
          Content = "去吧，神最虔诚的信徒们，为祂摘下名为胜利的果实。",
          DialogueId = 60221001,
          Duration = 4,
          GUID = "9687C8C6",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930003,
          VoiceName = "voice/$Locale$/story/0/602210/9687C8C6"
        },
        [60221101] = {
          Content = "为了军团的荣耀，前进！",
          DialogueId = 60221101,
          Duration = 4,
          GUID = "9687C8CA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930002,
          VoiceName = "voice/$Locale$/story/0/602211/9687C8CA"
        },
        [60221201] = {
          Content = "如我所料，大赛最重要的还是第三场。现在，该我们大显身手了。",
          DialogueId = 60221201,
          Duration = 4,
          GUID = "9687C8CE",
          SpeakNpcId = 930004,
          VoiceName = "voice/$Locale$/story/0/602212/9687C8CE"
        },
        [60221301] = {
