        },
        [70010101] = {
          Camera = "240.799805,-19.96875,71.943665,0.000028,-8.199457,146.99736,18.0,100000,false,Manual,2.8",
          Content = "近日岛上秽兽日渐活跃，所有居民准备好船只与物资，随时准备出海避险。",
          DialogueId = 70010101,
          Duration = 5,
          GUID = "AF435032",
          SpeakNpcId = 102011
        },
        [70010201] = {
          Camera = "299.416992,-190.118652,-59.832947,0.000008,10.199979,140.800186,20.0,100000.0,false,Manual,2.8",
          Content = "居民谨记，为了避免海伯利亚官员发现我们，出海捕鱼时远离不明船只。\n祖辈为了避免卷入无谓的战争逃到这里，相信他们的智慧，严守告诫。",
          DialogueId = 70010201,
          Duration = 5,
          GUID = "AF43609A",
          SpeakNpcId = 102012
        },
        [70010301] = {
          Camera = "-364.107666,1506.973633,120.13916,0.000131,13.391685,87.755157,18.0,100000.0,false,Manual,18.0",
          Content = "村民们应该早已乘船逃离秽兽肆虐的村子，而远处的“天之树”正是他们出海的天然灯塔。",
          DialogueId = 70010301,
          Duration = 5,
          GUID = "AF437102",
          SpeakNpcId = 102013
        },
        [70010401] = {
          Camera = "-564.918457,-24.525635,71.417542,0.000015,34.991844,0.800468,18.0,1932.963745,false,Manual,2.8",
          Content = "从未见过的雕像，供奉着不知姓名的神明，不知是什么时代的遗物……",
          DialogueId = 70010401,
          Duration = 5,
          GUID = "AF43816A",
          SpeakNpcId = 102014
        },
        [70010501] = {
          Camera = "-33.021576,347.337158,98.72699,0.000062,6.798647,-91.995422,18.0,100000.0,false,Manual,2.8",
          Content = "用剑刃刻下的铭文，只能辨认其中部分内容：\n……\n格里昂尼亚的加拉斯随布伦丹将军远征至此，将伪教艾利西安的盲信徒尽数驱逐。\n……\n尽一切可能毁去伪神的痕迹。\n……\n虽然想要留守于此，但岛屿贫瘠，不知能否常驻。\n……",
          DialogueId = 70010501,
          Duration = 5,
          GUID = "AF4391D2",
          SpeakNpcId = 102015
        },
        [70010601] = {
          Camera = "-1111.150024,-564.398438,447.803864,0.000071,30.199543,17.596375,15.0,100000.0,false,Manual,2.8",
          Content = "从巨大的雕像与两侧悬崖边缘残余的建筑来看，很久以前，这里应该是一处神庙。",
          DialogueId = 70010601,
          Duration = 5,
          GUID = "AF43A23A",
          SpeakNpcId = 102016
        },
        [70010701] = {
          Camera = "507.757812,-5157.005371,-457.544922,0.000083,-13.799645,-41.00135,20.0,511.06842,false,Manual,2.8",
          Content = "秽兽的残骸，余温尚存。可见不久之前，这里发生过一场交战。",
          DialogueId = 70010701,
          Duration = 5,
          GUID = "AF43B2A2",
          SpeakNpcId = 102017
        },
        [70010801] = {
          Camera = "454.451172,-463.453125,534.632812,0.000046,-15.999574,138.796616,15.0,100000.0,false,Manual,8.0",
          Content = "彩绘的神像，虽然保持完好，但是周围的断壁残垣显示着很久以前，这里曾经发生过一次彻底的劫掠。",
          DialogueId = 70010801,
          Duration = 5,
          GUID = "AF43C30A",
          SpeakNpcId = 102018
        },
        [70010901] = {
          Camera = "-742.34668,128.554199,307.391235,0.000063,-10.999725,71.996475,15.0,100000.0,false,Manual,2.8",
          Content = "似乎是用来炼金的装置，不知为何出现在神庙遗迹里。",
          DialogueId = 70010901,
          Duration = 5,
          GUID = "AF43D372",
          SpeakNpcId = 102019
        },
        [70011001] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.8",
          Content = "一张拍摄于十几年的照片，相框玻璃有着清晰的摩挲痕迹。照片中的卡戎少女恬淡地微笑着，任由微风拂过她的发尾。\n照片背后用钢笔写着一行字：“我的女儿——海莉，摄于红溪城”。虽然样貌并不十分相像，但少女澄澈无瑕的笑脸让你莫名想起了赛琪。",
          DialogueId = 70011001,
          Duration = 5,
          GUID = "AF43E3DA",
          SpeakNpcId = 102020
        },
        [70011101] = {
          Camera = "460.416016,1822.310425,211.930038,0.000008,-4.800414,169.194534,35.0,100000.0,false,Manual,2.8",
          Content = "（高大的档案柜，按字母顺序井然有序地排列着“住客”的档案。每份档案除了孩子的照片，还清楚地记着孩子们在修普诺斯之家度过的每一天。）\n\n赛琪的档案\n年龄：17\n症状：失明，失聪\n赛琪来的时候已是秽蚀中期，但她还是坚强、热情地向每个人打招呼。我多么希望诊断的结果是错误的，这样我还能欺骗自己，赛琪并没有出现秽蚀，她的人生还能回到正轨。\n……\n她将父母来看望时送的花都放在床头，连落脚和睡觉的地方都被压缩得很小很小。\n……\n我把二楼的空房收拾了出来，那边采光更好，赛琪和她的花搬进去以后应该能待得更舒适一些。\n……\n她真的很喜欢花，每天仔细地打理花束，再分发给其他孩子们，如果不是因为秽蚀，她将来一定能将“牵念之花”打理得比她父母还要出色。\n……\n赛琪今天给我也送了支花，看着她恬静的笑脸，我仿佛又见到了你……海莉……\n……\n我看着账本发愁的样子不小心被赛琪看到了，她缠着我询问原因，我拗不过她，如实将修普诺斯之家财政上的问题说给了她听。\n（批注：我得尽快给收购者回信，不能再让孩子们担心下去了。）\n……\n赛琪把老宅打扫了出来，还顺势租给个来路不明的小鬼……希望那个小鬼别给修普诺斯之家惹来什么麻烦。\n……\n<H>她说想要活下去，哪怕能以人类的身份再多活一天也好，听到这句话时我既欣慰又愤怒。\n欣慰是因为她终于吐露了心声，她以看淡生死的样子强撑太久了。\n愤怒是因为那个小鬼！我不知道那个小鬼对赛琪做了什么，但给必死之人活下去的勇气，太过残忍了。\n如果无法拯救，那就不要给予无意义的希望！\n……\n（批注：但如果这是赛琪的愿望……我得加快抑制秽蚀手术的研究了。为了赛琪，为了孩子们。）</>",
          DialogueId = 70011101,
          Duration = 5,
          GUID = "AF43F442",
          SpeakNpcId = 102021
        },
        [70011201] = {
          Camera = "460.416016,1822.310425,211.930038,0.000008,-4.800414,169.194534,35.0,100000.0,false,Manual,2.8",
          Content = "艾克的档案\n年龄：19\n症状：失明\n艾克是独自来修普诺斯之家的，不知道他的父母是不忍心看到孩子的结局，还是单纯的狠心。居然任由一个盲人独自来到冰湖城。\n……\n他说想看书，但我这里只有无趣冗长的医学典籍，即使这样他也没有嫌弃。我读着书，他坐在一旁听，就这样度过了一天。\n……\n我听到艾克在梦里呼唤他父亲的名字。\n……\n我在弗莱格桑行省找到了艾克的父亲，他没注意到我，只是专注地哼着摇篮曲，哄着他怀里的人族婴儿入睡。\n……\n我去买了些用盲文撰写的书，艾克开心地说谢谢父亲，我本想告诉他我不是，但最后只能艰难地嗯了一声然后匆匆离开了病房。\n……",
          DialogueId = 70011201,
          Duration = 5,
          GUID = "AF4404AA",
          SpeakNpcId = 102022
        },
        [70011301] = {
          Camera = "460.416016,1822.310425,211.930038,0.000008,-4.800414,169.194534,35.0,100000.0,false,Manual,2.8",
          Content = "罗比的档案\n年龄：18\n症状：成骨不全\n罗比被送到修普诺斯之家的时候浑身缠满了绷带，轻微的磕碰就可能引起严重的骨折，甚至连下床都很困难。\n……\n我把他的床位挪到了窗边，这样他可以多晒晒太阳。\n……\n康复训练很成功，莱娜女士的料理给罗比的身体提供了足够的营养，现在他可以拄着拐杖在修普诺斯之家走走了。\n……\n今天罗比的腿又骨折了，比来得时候还要严重。为了不给我添麻烦居然从楼梯上摔下来都不愿大声喊叫……看来我最近确实太憔悴了，害得孩子们反过来担心我。\n……\n他想出去采朵花作为赛琪的回礼，我同意了。虽然我们最后只捡到几根枯枝，但他还是笑得很开心。\n……",
          DialogueId = 70011301,
          Duration = 5,
          GUID = "AF441512",
          SpeakNpcId = 102023
        },
        [70011401] = {
          Camera = "460.416016,1822.310425,211.930038,0.000008,-4.800414,169.194534,35.0,100000.0,false,Manual,2.8",
          Content = "约瑟芬的档案\n年龄：17\n症状：脏器变形，呼吸困难\n她的秽蚀印记出现在脖子上，看着她跑上跑下活泼的样子，我反而有种不好的预感。\n……\n她突然跌倒在地喘着粗气，全身检查的结果很不理想，脏器出现了严重变形，接下来几天她都只能待在手术室了。\n……\n她的状态好些了，但还是离不开呼吸器，为了不让她在睡觉时出事，我必须每晚守在她的床边为她扶稳呼吸器，擦去冷汗。好在咖啡的储备足够，我还撑得住。\n……",
          DialogueId = 70011401,
          Duration = 5,
          GUID = "AF44257A",
          SpeakNpcId = 102024
        },
        [70011501] = {
          Camera = "589.100586,92.850586,87.400391,0.000028,0.0,-178.390396,22.0,400.0,false,DoNotOverride,2.8",
          Content = "受恶劣天气影响，城外第一公路发生严重侧翻事故。目前第六军团下属卫戍部队已展开抢修工作，请广大市民减少外出，出行时做好防滑措施。",
          DialogueId = 70011501,
          Duration = 5,
          GUID = "AF4435E2",
          SpeakNpcId = 102025
        },
        [70011601] = {
          Camera = "-83.132812,-721.489746,92.419189,0.000006,-0.600217,80.994888,20.0,100000.0,false,DoNotOverride,2.8",
          Content = "紧闭的大门切断了人们进入矿场的道路，耳旁传来冰冷的机械音，断断续续地重复着当年矿坑被封禁时的通知……\n月石矿脉枯竭……即日起列为废弃状态……工程炼金院不再提供安全保障……强行进入出现意外，概不负责……",
          DialogueId = 70011601,
          Duration = 5,
          GUID = "AF44464A",
          SpeakNpcId = 102026
        },
        [70011701] = {
          Content = "冰冷的机械音反复重复着军团转移矿工时的通知。\n第六军团驻扎部队将护送名单中的矿工转移至弗莱格桑行省继续从事相关工作。\n转移列车将于格雷姆矿场关闭前三小时准时发车，请名单中的各位矿工谨记以下注意事项：\n1、随身携带物品超过五公斤者，鞭刑\n2、不在规定时间乘车者，鞭刑\n3、对名单有疑问者，鞭刑",
          DialogueId = 70011701,
          Duration = 5,
          GUID = "AF4456B2",
          SpeakNpcId = 102027
        },
        [70011801] = {
          Camera = "-415.066528,-79.582031,152.246094,0.000006,0.599875,-0.799286,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "上了年头的老旧合照，记录着水仙平原开业时的盛况，平民、富商甚至是一些内城的官员都围聚在这里，为这家年轻的店铺献上最美好的祝福。",
          DialogueId = 70011801,
          Duration = 5,
          GUID = "AF44671A",
          SpeakNpcId = 102028
        },
        [70011901] = {
          Camera = "-652.218567,-446.646545,311.657959,0.000055,7.500012,42.603733,10.0,100000.0,false,DoNotOverride,2.8",
          Content = "在帝国随处可见的巨幅海报，上面写着“荣耀尽归吾皇”等标语。",
          DialogueId = 70011901,
          Duration = 5,
          GUID = "AF447782",
          SpeakNpcId = 102029
        },
        [70012001] = {
          Camera = "251.815674,-114.571671,67.927124,0.000047,-3.399658,170.391632,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "第六军团面向卡戎之民的新一期选拔考核即将展开，满足申报条件的卡戎之民可自行提交申请材料。\n改变命运的时刻已至，在黑狼旗下呼唤吾皇尤里乌斯的威名，向海伯利亚献上你们的忠诚！\n注：\n1、考核表现特别优异者可取得桂冠卡戎奖章，拥有入驻内城的资格。\n2、未能获取桂冠卡戎奖章但表现突出者，将编入外围卫戍部队服役。\n3、考核最终解释权归第六军团科赛托斯行省驻扎部队所有。\n4、考核途中出现的一切意外由本人承担。",
          DialogueId = 70012001,
          Duration = 5,
          GUID = "AF4487EA",
          SpeakNpcId = 102030
        },
        [70012101] = {
          Camera = "-413.806396,24.681641,230.520782,0.000089,-29.19894,-18.408882,35.0,400.0,false,DoNotOverride,2.8",
          Content = "储藏罐上写着“月髓液”的字样。在帝国的交通、照明等一系列物品上都能看到这一名词，从名字判断，应该是某种从月石演变来的产物。",
          DialogueId = 70012101,
          Duration = 5,
          GUID = "AF449852",
          SpeakNpcId = 102031
        },
        [70012201] = {
          Camera = "-829.676514,67.595215,115.704071,0.000047,28.996904,-8.414193,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "钟表指针每次划过12点都会在表盘上短暂地浮现出一个姓名——陶德·威尔斯。能将机关技术与光学原理结合，在作品上隐晦地留下名字。\n想必威尔斯先生应是一位杰出的钟表匠。",
          DialogueId = 70012201,
          Duration = 5,
          GUID = "AF44A8BA",
          SpeakNpcId = 102032
        },
        [70012301] = {
          Camera = "576.424805,22.139282,190.283051,0.000035,-16.800291,175.187546,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "刚一靠近车辆就听到一阵激昂的叫喊，“嗨嗨嗨，你也对这台PRT20A感兴趣对吧，这也是没办法的嘛！\n毕竟是第二代<H>由军用转为民用，搭载着月髓引擎的小型汽车</>，无数人传承下来的智慧结晶啊。\n虽然速度比不上军用的，但能近距离听着月髓引擎的轰鸣，开着它上路就已经是一种高贵身份的象征了……”。\n说话者滔滔不绝地从这台车的历史讲到结构，引擎讲到车身，甚至连轮胎的纹路都不放过，连讲数个小时。\n当耳边终于清静下来，脑海里还萦绕着一堆缸啊转啊等不知所云的词组。抬头环顾四周确认请静下来的原因。\n原来是这名狂热的爱好者早已跑去跟另一名倒霉的行人介绍起了面前的车辆。",
          DialogueId = 70012301,
          Duration = 5,
          GUID = "AF44B922",
          SpeakNpcId = 102033
        },
        [70012401] = {
          Camera = "-712.020264,-289.200195,10.626465,0.000082,16.793509,22.182402,10.0,100000.0,false,DoNotOverride,2.8",
          Content = "高大的纪念碑，背面记满了帝国人的姓名，正面则深深地刻着简短的一句话：\n纪念为这片土地带来悠久和平而英勇牺牲的军人们。\n荣耀尽归吾皇。",
          DialogueId = 70012401,
          Duration = 5,
          GUID = "AF44C98A",
          SpeakNpcId = 102034
        },
        [70012501] = {
          Camera = "-593.807617,-151.208984,181.682983,0.000059,-13.99979,25.798237,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "不知这是第几次在冰湖城看到矿灯、矿镐和矿车了，如此数量庞大的矿业工具无疑宣告着冰湖城在过去进行月石开采时的辉煌。\n但看着这些工具被丢在垃圾箱旁，落满灰尘，任谁都能明白，属于矿工的辉煌早已成为过去。",
          DialogueId = 70012501,
          Duration = 5,
          GUID = "AF44D9F2",
          SpeakNpcId = 102035
        },
        [70012601] = {
          Camera = "-429.546875,-25.467529,208.017578,0.000075,25.39749,-29.411985,20.0,100000.0,false,Manual,2.8",
          Content = "工厂巨大的阴影洒向城市，如俯视蝼蚁的巨人，将弱小的生命笼罩在自己的身影之下。\n每天都有数以千计的工人进出其中，即使身隔数百米，也能听到那巨人永不停歇的轰鸣。",
          DialogueId = 70012601,
          Duration = 5,
          GUID = "AF44EA5A",
          SpeakNpcId = 102036
        },
        [70012701] = {
          Camera = "7.69043,-170.557617,63.654785,0.0,0.0,-89.999939,10.0,100000.0,false,DoNotOverride,2.24",
          Content = "封锁的路障禁止任何人通行，从路障旁醒目的提示来看，前方区域已被第六军团卫戍部队接管。",
          DialogueId = 70012701,
          Duration = 5,
          GUID = "AF44FAC2",
          SpeakNpcId = 102037
        },
        [70012801] = {
          Camera = "902.932129,1093.807129,22.332031,0.000012,7.59978,-122.402924,35.0,100000.0,false,Manual,2.8",
          Content = "以月髓液驱动的供暖设施，坐在旁边会感觉心里暖洋洋的。但从其简陋的安装手法和位置来看，应该是某位民间非专业人士安置的。\n毕竟对帝国官方来说，为卡戎之民修筑供暖设施是完全没有意义的行为。",
          DialogueId = 70012801,
          Duration = 5,
          GUID = "AF450B2A",
          SpeakNpcId = 102038
        },
        [70012901] = {
          Camera = "538.746094,139.100586,83.406647,0.000042,-10.399529,-172.984406,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "凌乱的喷漆，密密麻麻地写满了对卡戎之民的侮辱性文字。",
          DialogueId = 70012901,
          Duration = 5,
          GUID = "AF451B92",
          SpeakNpcId = 102039
        },
        [70013001] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.27",
          Content = "小到只能容纳一只鸟的坟墓，上面的墓碑上没有姓名，只刻着一句话，“我永远的伙伴，带我逃出生天的英雄，长眠于此。——科农”。",
          DialogueId = 70013001,
          Duration = 5,
          GUID = "AF452BFA",
          SpeakNpcId = 102040
        },
        [70013101] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.28",
          Content = "发着淡淡黄光的编织袋，通过凸起的棱角能辨别出里面装满了月石，编织袋的底部有红色的血迹。",
          DialogueId = 70013101,
          Duration = 5,
          GUID = "AF453C62",
          SpeakNpcId = 102041
        },
        [70013201] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.29",
          Content = "积木\n（简易的积木，曾经在孩子们之间很流行的款式，但现在看来有些过时老旧了。）\n",
          DialogueId = 70013201,
          Duration = 5,
          GUID = "AF454CCA",
          SpeakNpcId = 102042
        },
        [70013301] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.30",
          Content = "赛琪的房间\n（门上挂着绿色蝴蝶画板，稚嫩的笔触在上面涂鸦出“赛琪的房间”，这里应该是赛琪曾生活过的地方，只是现在房门锁着，应该是母亲黛西的意愿。）",
          DialogueId = 70013301,
          Duration = 5,
          GUID = "AF455D32",
          SpeakNpcId = 102043
        },
        [70013401] = {
          Camera = "-274.459961,499.943848,20.897705,0.000001,4.999999,-79.999969,16.0,100000.0,false,Manual,2.8",
          Content = "透过“百相”服装店的橱窗，能看到一条富有品味的长裙，每一寸布料都恰到好处，彰显身段的同时衬出裙子主人优雅的气质，完美贴合哈兰的身材。",
          DialogueId = 70013401,
          Duration = 5,
          GUID = "AF456D9A",
          SpeakNpcId = 102044
        },
        [70013501] = {
          Camera = "36.606445,286.352539,23.979492,0.000003,-8.400025,-108.599854,15.0,100000.0,false,Manual,2.32",
          Content = "摆放在里奥拉身旁的水桶、抹布，这些工具应该是用来清洁旁边暗红色污渍的，想来这里之前发生过惨烈的冲突。",
          DialogueId = 70013501,
          Duration = 5,
          GUID = "AF457E02",
          SpeakNpcId = 102045
        },
        [70013601] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.33",
          Content = "泛黄的老海报，能勉强分辨出上面的内容：\n……\n首席歌者薇奥莱塔女士的演出将在下周开启！\n《雪国的孩子》经典重现，天籁般的歌谣将响彻冰湖城！\n持续一整个星期！不能错过！决不能错过！\n给钱就能带你混进内城！体验人上人的音乐盛宴！\n……\n联系人：杰克先生\n联系方式：每天半夜在下水道井盖旁汇合，向红头发的男人报暗号“布谷布谷”。",
          DialogueId = 70013601,
          Duration = 5,
          GUID = "AF458E6A",
          SpeakNpcId = 102046
        },
        [70013701] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.34",
          Content = "一本破破烂烂的教科书，空白的部分被人画上了许多粗劣的涂鸦。在这些涂鸦中，费伊被描绘成了一个长角的恶魔，正在施放可怕的巫术。",
          DialogueId = 70013701,
          Duration = 5,
          GUID = "AF459ED2",
          SpeakNpcId = 102047
        },
        [70013801] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.35",
          Content = "时不时会在修普诺斯之家见到这位严肃的女性，她似乎会定期前来打扫卫生，再为孩子们做上一顿热饭菜。\n\n当别人问起，她会说：“恩里克先生雇佣了我，那么我就得为他工作，行业如此。”\n\n她似乎为此深感无奈，人们也就识趣地放弃了追问。\n\n但所有修普诺斯之家的孩子都知道，莱娜女士从未收过恩里克哪怕一分钱的报酬。",
          DialogueId = 70013801,
          Duration = 5,
          GUID = "AF45AF3A",
          SpeakNpcId = 102048
        },
        [70013901] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.36",
          Content = "五花八门的废弃品，很难判断玛尔洁选品的依据是什么。他们曾经的主人都是谁呢？",
          DialogueId = 70013901,
          Duration = 5,
          GUID = "AF45BFA2",
          SpeakNpcId = 102049
        },
        [70014001] = {
          Camera = "-394.105225,225.10498,147.011475,0.00004,-19.999113,-46.394775,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "卡米拉拒收的酒水，不知道接下来会流通到哪里。",
          DialogueId = 70014001,
          Duration = 5,
          GUID = "AF45D00A",
          SpeakNpcId = 102050
        },
        [70014101] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.38",
          Content = "孩子的尺码，看来巴克听到的脚步声来源于此。",
          DialogueId = 70014101,
          Duration = 5,
          GUID = "AF45E072",
          SpeakNpcId = 102051
        },
        [70014201] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.39",
          Content = "看来犯人的背包破了个小洞，零碎的爆米花撒了一路。“饱满果实的气味”……原来如此。",
          DialogueId = 70014201,
          Duration = 5,
          GUID = "AF45F0DA",
          SpeakNpcId = 102052
        },
        [70014301] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.40",
          Content = "简陋的小帐篷，贝琳达长居于此，并且经营着一家起咨询作用的小店，没有招牌，没有明确的咨询范围，往来的客人似乎有自己的难言之隐。",
          DialogueId = 70014301,
          Duration = 5,
          GUID = "AF460142",
          SpeakNpcId = 102053
        },
        [70014401] = {
          Camera = "-277.21875,1095.014038,199.530029,0.000023,24.997671,-88.593628,15.0,100000.0,false,DoNotOverride,2.8",
          Content = "以月髓液驱动的巨大吊机。随着工程炼金院的改良，工人们只用在操纵室推一下摇杆即可完成对复数个巨大吊机的操作，大大提升了工作效率。\n但这一改动同时也磨灭了不少年幼时喜爱巨大吊机的男孩的梦，以及大量工人的工作机会。",
          DialogueId = 70014401,
          Duration = 5,
          GUID = "AF4611AA",
          SpeakNpcId = 102054
        },
        [70014501] = {
          Camera = "-553.419922,-854.08313,145.091064,0.000012,-2.200284,52.400944,20.0,100000.0,false,DoNotOverride,2.8",
          Content = "从标签来看似乎是一款名叫PRT05MV的军用钻探车，风吹日晒与斑驳锈迹在它的车身上留下岁月的痕迹。\n既没人看管也无人回收，不知是帝国对车辆安保的自信，还是军团的威严让所有想要靠近这辆废车的生物望而却步。",
          DialogueId = 70014501,
          Duration = 5,
          GUID = "AF462212",
          SpeakNpcId = 102055
        },
        [70014601] = {
          Camera = "18.892578,-214.330688,159.580475,0.000026,-31.400263,99.99868,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "一块已经长毛，用旧报纸包裹起来的黑面包。\n面包虽已无法食用，但展开报纸，擦掉霉菌后还能勉强看出这是一张十几年前的老旧报纸。\n与报道一同刊登的还有庆祝仪式的数张照片，照片里军官和工人们拿着工程炼金院发表的格雷姆新矿脉报告开心的笑着。",
          DialogueId = 70014601,
          Duration = 5,
          GUID = "AF46327A",
          SpeakNpcId = 102056
        },
        [70014701] = {
          Content = "揉成一团的信件，从字迹来看应是统一印刷而非人工手写。\n你好，帝国子民：\n我是海伯利亚的建立者，你们最伟大的迪斯一世。我于皇都迪斯玛尼亚写下这封信，\n是的，我没有死，而是通过秘术活了下来。\n如今我正准备重启对艾利西安的伟大征途，但当年的资金都被冻结了，暂时取不出。如果你仍有身为帝国之人的荣耀与血性，可将赞助资金寄到皇都凯旋大街233号，待我攻陷艾利西安圣都后，必将双倍奉还。\n记住，战争一触即发，不要拖延！我等待着你的赞助资金，届时，我将如闪电般归来！",
          DialogueId = 70014701,
          Duration = 5,
          GUID = "AF4642E2",
          SpeakNpcId = 102057
        },
        [70014801] = {
          Camera = "-233.383423,129.945312,39.479553,0.000071,26.799578,-19.787138,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "一款名叫冰湖往事的发酵饮品，转动阀门即可装上满满一杯。\n其色调接近月石，初尝时有股薄荷般的清爽，如冰湖拂过的冷风。\n咽下时有股蜜糖般的甘甜。如月石开采事业的辉煌，紧接着，泥煤的苦涩充斥五脏六腑，留下无穷的回味。\n冰湖往事，恰如其名，难怪成为水仙平原最受欢迎的饮品。",
          DialogueId = 70014801,
          Duration = 5,
          GUID = "AF46534A",
          SpeakNpcId = 102058
        },
        [70014901] = {
          Camera = "144.133301,295.799561,71.270615,0.000111,5.599437,-116.392715,20.0,100000.0,false,DoNotOverride,2.8",
          Content = "精妙的齿轮结构，不管怎么转动，水仙平原的一切都没有发生变化，然而从吧台后方那隐隐传来的机械运转声可以推测，这些齿轮并不是简单的装饰。",
          DialogueId = 70014901,
          Duration = 5,
          GUID = "AF4663B2",
          NextDialogue = 70014902,
          SpeakNpcId = 102059
        },
        [70014902] = {
          Content = "也许正如卡米拉说过的那样，商人为了一丁点蝇头小利连上绞架的事都做得出，水仙平原也并不仅是表面上卖卖发酵饮品那么简单。",
          DialogueId = 70014902,
          GUID = "AF4663B3",
          SpeakNpcId = 102059
        },
        [70015001] = {
          Camera = "267.163086,229.933594,218.354156,0.000008,-28.000093,-144.996719,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "月髓科技应用在帝国人民生活中的标志之一，虽然照明效果一般，但凭借消耗少、成本低、寿命长等特点，还是让其成为冰湖城人民使用的主流灯具。\n在过去，工程炼金院扩建格雷姆矿场时也曾大量使用该款灯具。",
          DialogueId = 70015001,
          Duration = 5,
          GUID = "AF46741A",
          SpeakNpcId = 102060
        },
        [70015101] = {
          Camera = "-293.902832,-246.538574,58.947754,0.000011,22.198734,42.000011,35.0,100000.0,false,Manual,2.8",
          Content = "明明是帝国常见的门楣样式，但看着那两个小方框，脑海里还是不自觉地将其过滤成一张龇牙咧嘴说着“看什么看！”的奇怪面容。",
          DialogueId = 70015101,
          Duration = 5,
          GUID = "AF46741B",
          SpeakNpcId = 102061
        },
        [70015201] = {
          Content = "骨架、武器和未吃完的食物压在破烂的背包之下，诉说着那些消失在废矿深处的，狩月人的最终宿命。\n这些背包有新有旧，它们的主人出于相似的目的进入废矿，幻想着自己不会成为失败的那一个，最终又迎来相似的，令人悲哀的结局。",
          DialogueId = 70015201,
          GUID = "AF4694EA"
        },
        [70015301] = {
          Content = "从背包中的日记和早已失去光泽的月石来看，如果变故来得再晚一些，也许背包的主人能得到更好的未来。",
          DialogueId = 70015301,
          GUID = "AF46A552"
        },
        [70015401] = {
          Content = "被弃置在垃圾桶里的《冰湖城早报》，但仔细一看，有几个字印刷错了——看来只是一份仿制品。\n展开一看，上面似乎记载了不少耸人听闻的内容。",
          DialogueId = 70015401,
          Duration = 5,
          GUID = "AF46B5BA",
          NextDialogue = 70015402,
          SpeakNpcId = 102064
        },
        [70015402] = {
          Content = "莫里斯·格伦维尔秘事\n……冰湖城的市民都知道昙花一现的格伦维尔家族，以及莫里斯·格伦维尔先生生前白手起家，一跃成为钢铁大亨，但家族成员先后遭遇诅咒，疯癫、意外死亡或失踪的故事。但是我们今天要谈的是另一件事——为什么格伦维尔先生要保留他穷小子的历史？",
          DialogueId = 70015402,
          Duration = 5,
          GUID = "AF46B5E4",
          NextDialogue = 70015403,
          SpeakNpcId = 102064
        },
        [70015403] = {
          Content = "……读者们有所不知，莫里斯发迹的第一桶金，正是他少年时在这位工程炼金院高官手下办事时赚得的，而这位官员是一名桂冠卡戎；结合莫里斯在日后成为了一名不折不扣的反卡戎主义者这一事实，我们不难推测出，在少年时，莫里斯和他的卡戎上司之间一定埋藏着一些隐秘的往事……",
          DialogueId = 70015403,
          Duration = 5,
          GUID = "AF46B60E",
          NextDialogue = 70015404,
          SpeakNpcId = 102064
        },
        [70015404] = {
          Content = "震惊！尤里乌斯陛下真实身份竟是替身？\n……当年报纸的报道和皇宫供职人士的回忆录中都记载了尤里乌斯陛下即位前的言谈，那时的他毫无疑问是一位谦和谨慎，风度翩翩的皇子。那么，为什么陛下会在即位后性情大变？\n真相只有一个，那就是——真实的陛下早就被谋害了，如今坐在柏罗纳宫中的那位皇帝，是不折不扣的假货！……\n",
          DialogueId = 70015404,
          Duration = 5,
          GUID = "AF46B638",
          NextDialogue = 70015405,
          SpeakNpcId = 102064
        },
        [70015405] = {
          Content = "你觉得自己好像知道得太多了，连忙把这份伪造的小报扔回了垃圾桶。",
          DialogueId = 70015405,
          Duration = 5,
          GUID = "AF46B662",
          SpeakNpcId = 102064
        },
        [70015501] = {
          Camera = "382.455078,-10.461182,127.896484,0.000083,-5.801112,-108.595062,30.0,96.67099,false,Manual,4.0",
          Content = "一张拍摄于十几年的照片，相框玻璃有着清晰的摩挲痕迹。照片中的卡戎少女恬淡地微笑着，任由微风拂过她的发尾。\n照片背后用钢笔写着一行字：“我的女儿——海莉，摄于红溪城”。虽然样貌并不十分相像，但少女澄澈无瑕的笑脸让你莫名想起了赛琪。",
          DialogueId = 70015501,
          Duration = 5,
          GUID = "AF46C622"
        },
        [70015601] = {
          Camera = "-277.050781,-1.119873,213.634766,0.0,0.0,-179.999985,10.0,100000.0,false,Manual,2.8",
          Content = "日志的封面上写着简短的一句话，“愿灵魂永眠于雾海”。翻开这本厚重的日志，能看到一个个熟悉的日期与姓名。",
          DialogueId = 70015601,
          Duration = 5,
          GUID = "AF46D68A",
          NextDialogue = 70015602
        },
        [70015602] = {
          Camera = "-277.050781,-1.119873,213.634766,0.0,0.0,-179.999985,10.0,100000.0,false,Manual,2.8",
          Content = "……\n9月3日，卡罗琳娜·布朗。\n……\n10月29日，亨特·克拉克。\n……\n11月25日，赛琪·弗莱伊。",
          DialogueId = 70015602,
          Duration = 5,
          GUID = "AF46D6B4"
        },
        [70015701] = {
          Camera = "-746.286377,-2980.045654,256.510742,0.000001,14.999996,-44.999969,18.0,100000.0,false,Disable,2.8",
          Content = "与月石颜色相似的晶石。但仔细观察，纹路和质地与月石完全不同，只是一些普通的“会发光的石头”而已。",
          DialogueId = 70015701,
          Duration = 5,
          GUID = "AF46E6F2",
          NextDialogue = 70015702
        },
        [70015702] = {
          Camera = "-746.286377,-2980.045654,256.510742,0.000001,14.999996,-44.999969,18.0,100000.0,false,Disable,2.8",
          Content = "人类按照使用价值把矿石分为三六九等，月石是珍贵的资源，而它们则是无用的废品。\n但也正因于此，月石被采掘一空，被打碎，被切割，最终成为工厂里冰凉的月髓液，而它们则幸运而完整地留下了。",
          DialogueId = 70015702,
          Duration = 5,
          GUID = "AF46E71C"
        },
        [70016001] = {
          Content = "<H>银烛狂欢</>将在盖雷亚剧院如期举行，请参与者自行准备你心仪的装扮，选择你要扮演的身份。\n让我们放下职业、放下种族、放下冲突相聚在于此，沐浴在皇帝的恩典之下，齐声赞颂皇帝的仁德，荣耀尽归吾皇！",
          DialogueId = 70016001,
          GUID = "AF47182A"
        },
        [70016002] = {
          Content = "厚厚的点名册，详细地记录了每位工作人员一天的行程，除了排练，连吃饭睡觉和如厕的行程都被记录在内。\n不知是剧团长狠心地将所有人“软禁”在剧院之内，还是剧团长为了保护自己的演员，而不得不时刻关注每个人的动向。",
          DialogueId = 70016002,
          GUID = "AF471854"
        },
        [70016003] = {
          Content = "帝皇尾戒勋章，完全由纯金打造，只会颁发给为帝国做出卓越贡献的军人。\n\n科赛托斯行省冰湖城第六军团下属卫戍部队，<H>黎瑟·费西尔</>。\n在连年、数次<H>清缴秽兽作战</>中，决策果断，作战英勇，收尾迅速。\n在维护地区治安的过程中起到了无可比拟的关键作用。\n现经军团评估，以吾皇尤里乌斯之名，授予黎瑟·费西尔帝皇尾戒勋章及准尉军衔，望广大军人以其为榜样，奋发上进，共同成长。\n荣耀尽归吾皇。",
          DialogueId = 70016003,
          GUID = "AF47187E"
        },
        [70016004] = {
          Content = "压在一堆杂物下的老旧报纸，记录着很久以前的悲惨事故。\n\n<H>秽蚀者异常凶险，不要被表象欺骗！</>\n9月24日，本市发生一起极为恶劣的“秽蚀”事件，经第六军团卫戍部队调查后，得出以下结论：\n冰湖城市民费西尔夫妇于9月13日在泪湖畔公路边上偶遇一名叫做罗比·布朗的青年。因其身受重伤，费西尔夫妇将其带回家中照料。\n然而，罗比·布朗是一名秽蚀者，他躲过了帝国对潜在秽蚀者的例行盘查并潜逃至城外，且在接受费西尔夫妇帮助时，刻意掩盖了自己的秽蚀痕迹。十日后，悲剧发生：布朗蜕变成为秽兽，杀死了包括费西尔夫妇在内数十名居住在冰湖城南区的市民。第六军团下属冰湖城卫戍部队紧急出动才平息此次骚乱。\n骚乱共造成18人死亡，其中包含3名索拉之民；另有34人受伤。在此提醒各位市民谨记，不要轻易收留身份不明的卡戎之民，一旦发现秽蚀者，立即上报治安署。它们永远只是人类的敌人，无一例外。如有刻意包庇秽蚀者、隐瞒不报者，一律按照《海伯利亚刑事法典》第54条规定，处以死刑。",
          DialogueId = 70016004,
          GUID = "AF4718A8"
        },
        [70016005] = {
          Content = "系着歪扭蝴蝶结的朴素礼盒，礼盒边是一瓶帝国最顶尖的止痛剂，和一封不知是什么原因没被塞入礼盒的纸条，上面写着“希望你能早日康复”。",
          DialogueId = 70016005,
          GUID = "AF4718D2"
        },
        [70016006] = {
          Camera = "-35.015625,151.625,225.035156,0.000034,-14.798724,-71.592674,35.0,100000.0,false,Manual,22.0",
          Content = "（内城城墙下姐弟的合照，照片的右上角写着“黎瑟·费西尔”与“布鲁斯·费西尔”两个名字，还有庆祝弟弟布鲁斯通过第六军团考核的祝语。）",
          DialogueId = 70016006,
          GUID = "AF4718FC"
        },
        [70016007] = {
          Camera = "36.316406,112.411133,226.279297,0.00002,-31.198172,-98.592926,35.0,100000.0,false,Manual,22.0",
          Content = "（看起来很久没使用过的口琴，比起黎瑟的爱好，更像某种礼物。）",
          DialogueId = 70016007,
          GUID = "AF471926"
        },
        [70016008] = {
          Content = "石灰墙的一角用小刀刻满了密密麻麻的字，有的歪歪扭扭，似是孩童的字迹；有些已经成熟，像是成年人所写。这些字都是同一句话：\n“我不会再看着任何人被秽兽杀死。”",
          DialogueId = 70016008,
          GUID = "AF471950"
        },
        [70016009] = {
          Content = "多位幕后人员记录的道具筹备单，详细记录着盖雷亚剧院近半个月所有道具的出入情况。\n\n10月08日，服装、睡袋筹备完成，确认人：蒙德里（批注：食物储备不足，<H>为了接下来为期一个月的集中排练，得托人再送一批进来</>）\n…………\n11月12日，新麦克风3只替换完成，确认人：格林德（批注：有一只麦克风声音巨响，普奇剧团长说这样就好，不做更换。）\n11月14日，红色幕布替换完成，金色幕布已收回仓库。确认人：贝尔\n…………\n11月24日，丢失的5顶假发回收完成，确认人：贝尔（批注：更衣室的角落容易藏东西，我今天去把那清空一下。）\n11月25日，花冠15顶筹备完成，马靴9双筹备完成，确认人：蒙德里",
          DialogueId = 70016009,
          GUID = "AF47197A"
        },
        [70016010] = {
          Content = "与剧院帷幕材质十分接近的布料，虽然老旧但十分整洁，显然经过什么人的认真打理。\n仔细观察和触摸会发现，和袭击现场发现的帷幕是同一块布料。",
          DialogueId = 70016010,
          GUID = "AF4719A4"
        },
        [70016011] = {
          Content = "假人模型虽然很旧，但造型和姿势明显经过了精心设计，看起来端庄而优雅。",
          DialogueId = 70016011,
          GUID = "AF4719CE"
        },
        [70016012] = {
          Content = "四周遍布着巨大而凌乱的爪痕，就算这里不是怪物的藏身处，也一定是怪物经常活动的地方。想必这就是十三军团将此处列为封锁区域的原因之一。",
          DialogueId = 70016012,
          GUID = "AF4719F8"
        },
        [70016013] = {
          Content = "冰湖城下水道的部分布局图，错综复杂的管道连接着各个区域，图上大量区域还标注着“未经军团许可，常时禁止进入”的标语。",
          DialogueId = 70016013,
          GUID = "AF471A22"
        },
        [70016101] = {
          Camera = "-15.959961,1605.265137,1322.948242,0.000059,-29.399687,-89.596825,20.875948,100000.0,false,Manual,22.0",
          Content = "（恢复炮台运输装置的供能，需要连通四根缆线。）",
          DialogueId = 70016101,
          GUID = "AF472892",
          NextDialogue = 70016102
        },
        [70016102] = {
          Camera = "224.294922,655.639038,672.151611,0.000109,-27.999538,-125.796112,20.875948,100000.0,false,Manual,22.0",
          Content = "（一根已经处于连通状态。）",
          DialogueId = 70016102,
          GUID = "AF4728BC",
          NextDialogue = 70016103
        },
        [70016103] = {
          Camera = "-1774.869141,-1374.734619,1171.844727,0.000131,-33.399078,23.004192,20.875948,100000.0,false,Manual,22.0",
          Content = "（还需要连通另外三根缆线，顺着它们找到髓动轮吧。）",
          DialogueId = 70016103,
          GUID = "AF4728E6"
        },
        [70016104] = {
          Camera = "-5344.007812,-255.292114,647.478394,0.000156,-14.998623,83.199738,20.875948,100000.0,false,Manual,22.0",
          Content = "（这是<H>一组</>髓动轮，且似乎需要在<H>特定时间</>内完成激活。）",
          DialogueId = 70016104,
          GUID = "AF472910"
        },
        [70016105] = {
          Camera = "5543.811523,-2108.574219,180.364319,0.000151,-3.998317,-104.994102,20.875948,100000.0,false,Manual,22.0",
          Content = "（似乎无法进入，有没有什么办法可以从<H>远处</>激活髓动轮呢？）",
          DialogueId = 70016105,
          GUID = "AF47293A"
        },
        [70016106] = {
          Camera = "157.341797,-91.314453,242.558594,0.0,-60.19952,101.398407,16.122608,100000.0,false,Manual,22.0",
          Content = "（这是一张陌生的脸。）",
          DialogueId = 70016106,
          GUID = "AF472964"
        },
        [70016107] = {
          Camera = "-71.794922,628.722656,135.195312,0.000076,12.199674,-90.596268,17.78793,100000.0,false,Manual,22.0",
          Content = "※“一角鲸”分队士兵凯鲁姆的证词\n“我看到‘狮鹫’小队的队长{nickname2}独自从▇▇▇▇出来，胸口沾了▇▇▇▇。”\n“{性别2：他|她}示意我们守在▇▇▇▇不要擅自行动，并表示自己将去▇▇▇▇查看是否有躲藏的同盟成员。“\n“大约两分钟后我听到▇▇▇▇传来的警报声，便与法露茜长官一起前去查看。我们发现‘雪狼’分队的阿瓦尔队长倒在血泊中，而▇▇▇▇已经启动。”\n",
          DialogueId = 70016107,
          GUID = "AF47298E"
        },
        [70016108] = {
          Content = "（士兵们已经没有了气息。）",
          DialogueId = 70016108,
          GUID = "AF4729B8"
        },
        [70016109] = {
          Content = "（秽兽的尸骸——正是这些怪物夺走了士兵们年轻的生命；而士兵们也在最后一刻，在它们身上留下了致命的弹孔。）",
          DialogueId = 70016109,
          GUID = "AF4729E2"
        },
        [70016110] = {
          Camera = "129.879883,311.569336,152.664062,0.000072,3.399556,-2.996889,17.78793,100000.0,false,Manual,22.0",
          Content = "※{nickname2}的家庭关系调查\n{nickname2}是三年前▇▇▇▇中，▇▇▇▇事件的幸存者。{nickname2}自述记忆丧失，但意识清醒，思维敏捷。\n值得注意的是，据事件其他幸存者的证言，{nickname2}是不应该出现在▇▇▇▇的——换言之，<H>{性别2：他|她}是一位货真价实的“幽灵乘客”</>。\n当时十三军团对其身世进行了多方调查，仍未能确认其真实身份，但也排除了▇▇▇▇的可能性。据推测，有可能是当地居民为躲避炮火而选择▇▇▇▇藏身，并在剧烈的轰击中脑部受创，失去记忆。",
          DialogueId = 70016110,
          GUID = "AF47298F"
        },
        [71000000] = {
          Content = "喵……",
          DialogueId = 71000000,
          Duration = 3,
          GUID = "B1BDB580",
          SpeakNpcId = 800002
        },
        [71000100] = {
          Content = "（野猫寂寞地叫着，似乎在渴求某位好心人的注意。）",
          DialogueId = 71000100,
          GUID = "B1BDC5E8",
          SpeakNpcId = 800006
        },
        [71000200] = {
          Content = "请问这里有猫粮卖吗？",
          DialogueId = 71000200,
          GUID = "B1BDD650",
          NextDialogue = 710002001,
          SpeakNpcId = 100001
        },
        [71000210] = {
          Content = "请问这里有猫粮卖吗？",
          DialogueId = 71000210,
          GUID = "B1BDD7F4",
          NextDialogue = 710002101,
          SpeakNpcId = 100001
        },
        [71000220] = {
          Content = "（摆下猫粮）",
          DialogueId = 71000220,
          GUID = "B1BDD998",
          NextDialogue = 710002201,
          SpeakNpcId = 100001
        },
        [71000300] = {
          Content = "（野猫蹦跳着跑开几步以后驻足看向了你，似乎想让你跟上它的步伐。）",
          DialogueId = 71000300,
          Duration = 3,
          GUID = "B1BDE6B8",
          SpeakNpcId = 800006
        },
        [71000310] = {
          Content = "（野猫蹦跳着跑开几步以后驻足看向了你，似乎想让你跟上它的步伐。）",
          DialogueId = 71000310,
          Duration = 3,
          GUID = "B1BDE85C",
          SpeakNpcId = 800006
        },
        [71000320] = {
          Content = "（野猫蹦跳着跑开几步以后驻足看向了你，似乎想让你跟上它的步伐。）",
          DialogueId = 71000320,
          Duration = 3,
          GUID = "B1BDEA00",
          SpeakNpcId = 800006
        },
        [71000330] = {
          Content = "（野猫围着你的脚边开心地转了两圈。看着它满足的表情，你的内心也得到了极大的治愈。）",
          DialogueId = 71000330,
          GUID = "B1BDEBA4",
          SpeakNpcId = 800006
        },
        [71000501] = {
          Content = "别打啦，再打我就要使出绝活了……好，我要用了哦……救命啊啊啊啊啊！！！\n",
          DialogueId = 71000501,
          Duration = 3,
          GUID = "B1BE07B2",
          SpeakNpcId = 800005
        },
        [71000502] = {
          Content = "呜哇哇哇……",
          DialogueId = 71000502,
          Duration = 3,
          GUID = "B1BE07DC",
          SpeakNpcId = 800005
        },
        [71000503] = {
          Content = "最后一个，搞定。",
          DialogueId = 71000503,
          GUID = "B1BE0806",
          SpeakNpcId = 818014
        },
        [71000504] = {
          Content = "我去看看附近还有没有敌人，你自己小心。",
          DialogueId = 71000504,
          GUID = "B1BE0830",
          NextDialogue = 71000505,
          SpeakNpcId = 818014
        },
        [71000505] = {
          Content = "收到收到，我会注意的！",
          DialogueId = 71000505,
          GUID = "B1BE085A",
          NextDialogue = 71000506,
          SpeakNpcId = 818015
        },
        [71000506] = {
          Content = "诶，你也来啦。呜呜……原来有这么多人愿意帮助我……这是给大家准备的谢礼，以后也请多多关照了。",
          DialogueId = 71000506,
          GUID = "B1BE0884",
          Scripts = "TurnTo{TurnToDescription{\"818015:n(0)\"}}",
          SpeakNpcId = 818015
        },
        [71000511] = {
          Camera = "182.995117,-239.510742,101.057129,0.000077,-2.797147,129.385254,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "谢谢，探险家大危机解除！继续冒险喽。",
          DialogueId = 71000511,
          GUID = "B1BE0956",
          SpeakNpcId = 800005,
          TalkActionId = {
            [1] = "800005:Confident_Start"
          }
        },
        [71000512] = {
          Camera = "125.800781,-57.036377,76.0,0.000008,0.0,155.202805,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "谢谢，探险家大危机解除！继续冒险喽。",
          DialogueId = 71000512,
          GUID = "B1BE0980",
          SpeakNpcId = 800005,
          TalkActionId = {
            [1] = "800005:Confident_Start"
          }
        },
        [71000601] = {
          Content = "（被海浪冲上岸的木桶堆积在沙滩上，找找看的话，也许能发现一些有用的东西。）",
          DialogueId = 71000601,
          Duration = 3,
          GUID = "B1BE181A",
          SpeakNpcId = 800006
        },
        [71000612] = {
          Content = "（木桶底部破了个大洞，不管它曾装过什么金银财宝，现在都是件无用的垃圾。去看看其他木桶吧。）",
          DialogueId = 71000612,
          GUID = "B1BE19E8"
        },
        [71000613] = {
          Content = "（木桶里除了腐烂的鱼虾以外什么也没有，去看看其他木桶吧。）",
          DialogueId = 71000613,
          GUID = "B1BE1A12"
        },
        [71000615] = {
          Content = "（功夫不负有心人，仔细翻找之后，你终于在木桶的夹层里找到了一些能用的物资。）",
          DialogueId = 71000615,
          GUID = "B1BE1A66"
        },
        [71000701] = {
          Content = "真是头疼啊，就剩几条管道了。",
          DialogueId = 71000701,
          Duration = 3,
          GUID = "B1BE2882",
          SpeakNpcId = 800007
        },
        [71000710] = {
          Content = "发生什么了？",
          DialogueId = 71000710,
          GUID = "B1BE29FC",
          NextDialogue = 71000711,
          SpeakNpcId = 100001
        },
        [71000711] = {
          Content = "哎呀，我得检查一下城里这些月髓管有没有坏。",
          DialogueId = 71000711,
          Duration = 3,
          GUID = "B1BE2A26",
          NextDialogue = 71000721,
          SpeakNpcId = 800007
        },
        [71000721] = {
          Content = "但我的作业绳在上条管子那里弄断了，你能帮我上去看一看剩下的几条管子吗？",
          DialogueId = 71000721,
          Duration = 3,
          GUID = "B1BE2BCA",
          NextOptions = {
            [1] = 710007210,
            [2] = 710007211
          },
          SpeakNpcId = 800007
        },
        [71000741] = {
          Content = "剩下的几条管道我帮你标出来了，真是麻烦你了！",
          DialogueId = 71000741,
          Duration = 3,
          GUID = "B1BE2F12",
          SpeakNpcId = 800007
        },
        [71000751] = {
          Content = "（这条管道没有破损，去看看下一条管道吧。）",
          DialogueId = 71000751,
          Duration = 2,
          GUID = "B1BE30B6",
          SpeakNpcId = 800006
        },
        [71000761] = {
          Content = "（最后一条管道也没有破损，去告诉那名工人吧。）",
          DialogueId = 71000761,
          GUID = "B1BE325A",
          SpeakNpcId = 800006
        },
        [71000771] = {
          Content = "都没问题？太好了！万分感谢！",
          DialogueId = 71000771,
          GUID = "B1BE33FE",
          SpeakNpcId = 800007
        },
        [71000780] = {
          Content = "（这条管道出现了轻微破损，去告诉那名工人吧。）",
          DialogueId = 71000780,
          GUID = "B1BE3578",
          SpeakNpcId = 800006
        },
        [71000781] = {
          Content = "唉……看来又得上工了，我回去拿点工具，你拿上我的钥匙，先去帮我关一下月髓管的总阀吧。",
          DialogueId = 71000781,
          GUID = "B1BE35A2",
          SpeakNpcId = 800007
        },
        [71000782] = {
          Content = "谢谢，剩下的就交给我吧。",
          DialogueId = 71000782,
          GUID = "B1BE35CC",
          SpeakNpcId = 800007
        },
        [71000801] = {
          Content = "{nickname}，{nickname}，快来，我找到新的研究课题了。",
          DialogueId = 71000801,
          Duration = 3,
          GUID = "B1BE38EA",
          SpeakNpcId = 800011
        },
        [71000802] = {
          Content = "这次的研究素材在湖对面，你能帮帮我吗？",
          DialogueId = 71000802,
          Duration = 3,
          GUID = "B1BE3914",
          NextOptions = {
            [1] = 710008021,
            [2] = 710008022
          },
          SpeakNpcId = 800011
        },
        [71000803] = {
          Content = "这就是西奥要研究的东西了，拿点回去给他吧。",
          DialogueId = 71000803,
          Duration = 2,
          GUID = "B1BE393E",
          SpeakNpcId = 100001
        },
        [71000804] = {
          Content = "谢谢你！想要成为伟大的炼金术师，要学习的东西真的好多好多呢……",
          DialogueId = 71000804,
          Duration = 2,
          GUID = "B1BE3968",
          SpeakNpcId = 800011
        },
        [71000805] = {
          Content = "……好吧，我明白了，你的意思是，成为伟大的炼金术师的第一步，就是靠自己的力量寻找研究素材！",
          DialogueId = 71000805,
          GUID = "B1BE3992",
          SpeakNpcId = 800011
        },
        [71000901] = {
          Content = "捉迷藏，捉迷藏，一起来玩捉迷藏！",
          DialogueId = 71000901,
          Duration = 3,
          GUID = "B1BE4952",
          SpeakNpcId = 800008
        },
        [71000902] = {
          Content = "捉迷藏，捉迷藏，一起来玩捉迷藏！",
          DialogueId = 71000902,
          GUID = "B1BE497C",
          NextDialogue = 71000903,
          Scripts = "SEQ{TurnTo{TurnToDescription{\"800008:n(0)\"}},LookAt{LookAtDescription{\"800008:n(0)\"}},PlayAnimation{ActorId{800008},AnimationId{\"Explain02_Start\"},Duration{1}}}",
          SpeakNpcId = 800008,
          TurnTo = {
            [1] = "800009:n(0)",
            [2] = "800010:n(0)"
          }
        },
        [71000903] = {
          Content = "好呀好呀！但是我不想找人，我想藏。",
          DialogueId = 71000903,
          Duration = 3,
          GUID = "B1BE49A6",
          NextDialogue = 71000904,
          SpeakNpcId = 800009,
          TalkActionId = {
            [1] = "800009:Explain01_Start"
          }
        },
        [71000904] = {
          Content = "我也是，我发现一个超级隐蔽的地方，躲在那一定能赢！",
          DialogueId = 71000904,
          Duration = 3,
          GUID = "B1BE49D0",
          NextDialogue = 71000905,
          SpeakNpcId = 800010,
          TalkActionId = {
            [1] = "800010:Talk03_Start"
          }
        },
        [71000905] = {
          Content = "那怎么办？还有人愿意和我们一起捉迷藏吗……",
          DialogueId = 71000905,
          Duration = 3,
          GUID = "B1BE49FA",
          NextDialogue = 71000906,
          SpeakNpcId = 800009
        },
        [71000906] = {
          Content = "（孩子们注意到了路过的你，满眼期待地等待着你的回应。）",
          DialogueId = 71000906,
          Duration = 3,
          GUID = "B1BE4A24",
          SpeakNpcId = 800006
        },
        [71000907] = {
          Content = "（孩子们兴奋地跳了起来，一眨眼就消失在了街角。现在该好好想想去哪里寻找这些孩子了。）",
          DialogueId = 71000907,
          GUID = "B1BE4A4E"
        },
        [71000908] = {
          Content = "哇，这么快就被你找到了。",
          DialogueId = 71000908,
          GUID = "B1BE4A78",
          SpeakNpcId = 800008
        },
        [71000909] = {
          Content = "你好厉害呀。",
          DialogueId = 71000909,
          Duration = 2,
          GUID = "B1BE4AA2",
          SpeakNpcId = 800009
        },
        [71000910] = {
          Content = "可恶，我居然输了……",
          DialogueId = 71000910,
          Duration = 2,
          GUID = "B1BE4ACC",
          SpeakNpcId = 800010
        },
        [71000911] = {
          Content = "好吧好吧，愿赌服输，这是给你的谢礼，下次还要和我们一起玩哦！",
          DialogueId = 71000911,
          Duration = 2,
          GUID = "B1BE4AF6",
          SpeakNpcId = 800008
        },
        [71001001] = {
          Content = "（一台崭新的车辆，这或许是一个……发财的机会？）",
          DialogueId = 71001001,
          Duration = 3,
          GUID = "B1BE59BA",
          SpeakNpcId = 800006
        },
        [71001002] = {
          Content = "（车里的月髓能源装置装得满满当当，果然是一个发财的机会！）",
          DialogueId = 71001002,
          GUID = "B1BE59E4",
          SpeakNpcId = 800006
        },
        [71001003] = {
          Content = "你在干什么！快来人啊！",
          DialogueId = 71001003,
          Duration = 2,
          GUID = "B1BE5A0E",
          SpeakNpcId = 818010
        },
        [71001004] = {
          Content = "（现在不会再有人来阻拦你的脚步了。撬开车锁，带走装满月髓液的能源装置，卖个好价钱。一切都在按你的计划进行，又是令人心情愉悦的一天。）",
          DialogueId = 71001004,
          Duration = 4,
          GUID = "B1BE5A38",
          SpeakNpcId = 800006
        },
        [71001005] = {
          Content = "（良知最终战胜了诱惑，你决定向城门守卫汇报车辆安保的疏漏。）",
          DialogueId = 71001005,
          Duration = 3,
          GUID = "B1BE5A62",
          SpeakNpcId = 800006
        },
        [71001006] = {
          Content = "感谢您的通知，我这就派人加强巡逻，这是一点谢礼，还望不要嫌弃。",
          DialogueId = 71001006,
          GUID = "B1BE5A8C",
          SpeakNpcId = 818010
        },
        [71001101] = {
          Content = "（秽兽来袭，击退它们！）",
          DialogueId = 71001101,
          Duration = 3,
          GUID = "B1BE6A22",
          SpeakNpcId = 800006
        },
        [71001201] = {
          Content = "（杂草淹没了你与贝蕾曾经留在此处的痕迹，也许应该清理一下神像附近的杂草了。）",
          DialogueId = 71001201,
          Duration = 2,
          GUID = "B1BE7A8A",
          SpeakNpcId = 800006
        },
        [71001202] = {
          Content = "（在你的努力下，神像附近恢复了整洁，一如你回忆中的景色。）",
          DialogueId = 71001202,
          GUID = "B1BE7AB4",
          SpeakNpcId = 800006
        },
        [71001301] = {
          Content = "依贝蕾所说，这里就是我们曾经的家，可我却一点印象都没有……",
          DialogueId = 71001301,
          GUID = "B1BE8AF2",
          NextDialogue = 71001302,
          SpeakNpcId = 100001
        },
        [71001302] = {
          Content = "也许我该在这附近转转，兴许能想起些什么。",
          DialogueId = 71001302,
          GUID = "B1BE8B1C",
          SpeakNpcId = 100001
        },
        [71001303] = {
          Content = "家具的制作十分粗糙，不少钉子都被深深砸进了木头里，就像我们在村里的房门把手一样。贝蕾原来从小就有这么大力气呢。",
          DialogueId = 71001303,
          GUID = "B1BE8B46"
        },
        [71001304] = {
          Content = "这是……一本炼金故事书？原来贝蕾小时候给我讲的那些奇奇怪怪的睡前故事，都是从这本书上来的。",
          DialogueId = 71001304,
          GUID = "B1BE8B70",
          NextDialogue = 71001305
        },
        [71001305] = {
          Content = "但是书上这些批注比贝蕾的字迹工整好多，会是谁写的呢？",
          DialogueId = 71001305,
          GUID = "B1BE8B9A"
        },
        [71001306] = {
          Content = "想起了不少贝蕾的事呢。至于这里，还是什么都想不起来……",
          DialogueId = 71001306,
          GUID = "B1BE8BC4",
          NextDialogue = 71001307,
          SpeakNpcId = 100001
        },
        [71001307] = {
          Content = "算了，也许等到以后，自然就想起来了。",
          DialogueId = 71001307,
          GUID = "B1BE8BEE",
          SpeakNpcId = 100001
        },
        [71001401] = {
          Content = "（你远远的便闻到了北风莓的香味，去摘一些的话，应该能卖个好价钱。）",
          DialogueId = 71001401,
          Duration = 4,
          GUID = "B1BE9B5A",
          SpeakNpcId = 800006
        },
        [71001402] = {
          Content = "（这一批北风莓色泽艳丽、果肉饱满，任谁都能看得出，这样的特产根本不愁卖不出去。）",
          DialogueId = 71001402,
          Duration = 4,
          GUID = "B1BE9B84",
          SpeakNpcId = 800006
        },
        [71001403] = {
          Content = "（远处有两名商人都在收购北风莓，与他们聊聊看再决定卖给谁吧。）",
          DialogueId = 71001403,
          Duration = 4,
          GUID = "B1BE9BAE",
          SpeakNpcId = 800006
        },
        [71001404] = {
          Content = "我这小摊在冰湖城开了好几年了，虽然利润不高，但来做买卖的都是熟人。你这批北风莓我全收了就当交个朋友吧，大伙都在冰湖城，以后还能互相照顾照顾。",
          DialogueId = 71001404,
          GUID = "B1BE9BD8",
          NextOptions = {
            [1] = 710014041,
            [2] = 710014042
          },
          SpeakNpcId = 818002
        },
        [71001405] = {
          Content = "嘿，我看到你怀里那些北风莓了。我出的钱可比冰湖城那些穷商人多了去了。怎么样，咱两一起赚笔大的如何？",
          DialogueId = 71001405,
          GUID = "B1BE9C02",
          NextOptions = {
            [1] = 710014051,
            [2] = 710014052
          },
          SpeakNpcId = 818003
        },
        [71001406] = {
          Content = "（虽然利润较低，但为了长久而稳定的人脉，你最终还是与本地商人完成了交易。）",
          DialogueId = 71001406,
          Duration = 3,
          GUID = "B1BE9C2C",
          SpeakNpcId = 800006
        },
        [71001407] = {
          Content = "（未来的承诺远没有当下的利益来得靠谱，你最终还是与外地商人完成了交易，并收获了一大笔丰厚的报酬。）",
          DialogueId = 71001407,
          Duration = 4,
          GUID = "B1BE9C56",
          SpeakNpcId = 800006
        },
        [71001501] = {
          Content = "唉……这破玩意怎么又坏了……",
          DialogueId = 71001501,
          Duration = 3,
          GUID = "B1BEABC2",
          SpeakNpcId = 818006
        },
        [71001502] = {
          Content = "发生什么了？",
          DialogueId = 71001502,
          GUID = "B1BEABEC",
          NextDialogue = 71001503,
          SpeakNpcId = 100001
        },
        [71001503] = {
          Content = "这台机器我老用不好，要不你也来试试，看看是机器的问题还是我的问题。",
          DialogueId = 71001503,
          GUID = "B1BEAC16",
          SpeakNpcId = 818006
        },
        [71001504] = {
          Content = "谢了啊。",
          DialogueId = 71001504,
          Duration = 2,
          GUID = "B1BEAC40",
          SpeakNpcId = 818006
        },
        [71001505] = {
          Content = "有两下子！唉，看来还是我的操作方式不对……",
          DialogueId = 71001505,
          GUID = "B1BEAC6A",
          SpeakNpcId = 818006
        },
        [71001506] = {
          Content = "这也行？",
          DialogueId = 71001506,
          Duration = 2,
          GUID = "B1BEAC94",
          SpeakNpcId = 818006
        },
        [71001507] = {
          Content = "呃……真的拍两下就能好吗？",
          DialogueId = 71001507,
          Duration = 2,
          GUID = "B1BEACBE",
          SpeakNpcId = 818006
        },
        [71001508] = {
          Content = "喂喂，刚刚是不是有零件飞出去了。",
          DialogueId = 71001508,
          Duration = 2,
          GUID = "B1BEACE8",
          SpeakNpcId = 818006
        },
        [71001509] = {
          Content = "厉害啊，居然真有用！",
          DialogueId = 71001509,
          GUID = "B1BEAD12",
          SpeakNpcId = 818006
        },
        [71001601] = {
          Content = "好多秽兽啊……这可怎么办……",
          DialogueId = 71001601,
          Duration = 3,
          GUID = "B1BEBC2A",
          SpeakNpcId = 818004
        },
        [71001602] = {
          Content = "发生什么了？",
          DialogueId = 71001602,
          GUID = "B1BEBC54",
          NextDialogue = 71001603,
          SpeakNpcId = 100001
        },
        [71001603] = {
          Content = "哇，看你的打扮，是位很厉害的狩月人吧！那个……我其实也是狩月人，只是我太弱了……",
          DialogueId = 71001603,
          GUID = "B1BEBC7E",
          NextDialogue = 71001604,
          SpeakNpcId = 818004
        },
        [71001604] = {
          Content = "你能帮我把落在那群秽兽里的武器拿回来吗，不然我连下个委托都做不了了……",
          DialogueId = 71001604,
          GUID = "B1BEBCA8",
          NextDialogue = 71001605,
          SpeakNpcId = 818004
        },
        [71001605] = {
          Content = "……我来帮忙吧。",
          DialogueId = 71001605,
          GUID = "B1BEBCD2",
          NextDialogue = 71001606,
          SpeakNpcId = 100001
        },
        [71001606] = {
          Content = "谢谢谢谢！",
          DialogueId = 71001606,
          GUID = "B1BEBCFC",
          SpeakNpcId = 818004
        },
        [71001607] = {
          Content = "秽兽就在前面，大师，你也小心些哦。",
          DialogueId = 71001607,
          Duration = 3,
          GUID = "B1BEBD26",
          SpeakNpcId = 818004
        },
        [71001608] = {
          Content = "呜呜呜……要是接不了委托可怎么办呀，好几天没吃饭了……",
          DialogueId = 71001608,
          GUID = "B1BEBD50",
          NextOptions = {
            [1] = 710016081,
            [2] = 710016082
          },
          SpeakNpcId = 818004
        },
        [71001609] = {
          Content = "谢谢！那我这就去做委托了，大师，我们以后再见！",
          DialogueId = 71001609,
          GUID = "B1BEBD7A",
          SpeakNpcId = 818004
        },
        [71001610] = {
