        },
        [71002405] = {
          Content = "（勘探器的响动将周围的秽兽吸引了过来，击退它们吧。）",
          DialogueId = 71002405,
          GUID = "B1BF4012",
          SpeakNpcId = 800006
        },
        [71002406] = {
          Content = "诶，你还帮我把卡住的零件掰开了吗，好感动！",
          DialogueId = 71002406,
          GUID = "B1BF403C",
          SpeakNpcId = 818015
        },
        [71002407] = {
          Content = "久等啦！我就知道交给你照看肯定没问题！",
          DialogueId = 71002407,
          GUID = "B1BF4066",
          SpeakNpcId = 818015
        },
        [71002501] = {
          Content = "唉……这破下水道怎么又堵了……",
          DialogueId = 71002501,
          GUID = "B1BF4FD2",
          SpeakNpcId = 818021
        },
        [71002502] = {
          Content = "发生什么了？",
          DialogueId = 71002502,
          GUID = "B1BF4FFC",
          NextDialogue = 71002503,
          SpeakNpcId = 100001
        },
        [71002503] = {
          Content = "这片下水道堵住了，长官给了我个说明书，但我根本看不懂啊……你能帮帮我吗？",
          DialogueId = 71002503,
          GUID = "B1BF5026",
          NextOptions = {
            [1] = 710025041,
            [2] = 710025042
          },
          SpeakNpcId = 818021
        },
        [71002505] = {
          Content = "说明书上说，遇到下水道堵塞只要开启三道闸门放水强冲即可。",
          DialogueId = 71002505,
          GUID = "B1BF507A",
          NextDialogue = 71002511,
          SpeakNpcId = 100001
        },
        [71002507] = {
          Content = "好嘞，接下来第二个在那边。",
          DialogueId = 71002507,
          GUID = "B1BF50CE",
          SpeakNpcId = 818021
        },
        [71002508] = {
          Content = "第三个我看看啊……找到了，就在那！",
          DialogueId = 71002508,
          GUID = "B1BF50F8",
          SpeakNpcId = 818021
        },
        [71002509] = {
          Content = "好，我已经完全掌握了！这是我的一点心意，辛苦你啦！",
          DialogueId = 71002509,
          GUID = "B1BF5122",
          SpeakNpcId = 818021
        },
        [71002510] = {
          Content = "嘿，你这法子也不赖嘛，来来，这是给你的报酬。",
          DialogueId = 71002510,
          GUID = "B1BF514C",
          SpeakNpcId = 818021
        },
        [71002511] = {
          Content = "原来是这样啊，那你能示范一下怎么操作吗，我看着学一下。",
          DialogueId = 71002511,
          GUID = "B1BF507B",
          SpeakNpcId = 818021
        },
        [71002601] = {
          Content = "可恶，这镐子也太不耐用了，剩下这些石头咋办呢，总不能让我用手挖吧……",
          DialogueId = 71002601,
          GUID = "B1BF603A",
          SpeakNpcId = 818023
        },
        [71002602] = {
          Content = "看你的打扮，也是狩月人吧。我接的这个挖石头委托一个人做不完了，你要不要跟我一起？报酬直接分你一半。",
          DialogueId = 71002602,
          GUID = "B1BF6064",
          NextOptions = {
            [1] = 710026021,
            [2] = 710026022
          },
          SpeakNpcId = 818023,
          bForbidSkipOptions = true
        },
        [71002603] = {
          Content = "好，剩下的这些就交给你了，我来整理下之前挖好的。",
          DialogueId = 71002603,
          GUID = "B1BF608E",
          SpeakNpcId = 818023
        },
        [71002604] = {
          Content = "原来还有这种办法，太厉害了！",
          DialogueId = 71002604,
          GUID = "B1BF60B8",
          NextDialogue = 71002605,
          SpeakNpcId = 818023
        },
        [71002605] = {
          Content = "辛苦你了，这是说好的报酬。",
          DialogueId = 71002605,
          GUID = "B1BF60E2",
          SpeakNpcId = 818023
        },
        [71002701] = {
          Content = "（一些木桶顺着水道漂来，有的还发出着诡异的声响，谨慎打开的话，也许能发现一些有用的东西。）",
          DialogueId = 71002701,
          GUID = "B1BF70A2",
          SpeakNpcId = 800006
        },
        [71002702] = {
          Content = "（木桶底部破了个大洞，除了风声穿过的嘶吼，你找不到任何有用的东西，去看看其他木桶吧。）",
          DialogueId = 71002702,
          GUID = "B1BF70CC",
          SpeakNpcId = 800006
        },
        [71002703] = {
          Content = "（木桶里装满了生活垃圾，散发着咕嘟咕嘟的闷响和刺鼻的气味，去看看其他木桶吧。）",
          DialogueId = 71002703,
          GUID = "B1BF70F6",
          SpeakNpcId = 800006
        },
        [71002704] = {
          Content = "（付出必然要有回报，仔细翻找之后，你果然在木桶的夹层里找到了一些能用的物资。）",
          DialogueId = 71002704,
          GUID = "B1BF7120",
          SpeakNpcId = 800006
        },
        [71002705] = {
          Content = "（破旧的木桶轰然散架，巨大的噪音将周围的秽兽吸引了过来，击败它们，拿到你应得的战利品吧。）",
          DialogueId = 71002705,
          GUID = "B1BF714A",
          SpeakNpcId = 800006
        },
        [71002801] = {
          Content = "（坍塌的碎石挡住了前路，将它们清理掉吧。）",
          DialogueId = 71002801,
          GUID = "B1BF810A",
          SpeakNpcId = 800006
        },
        [71002802] = {
          Content = "（你在清理碎石的过程中找到了些能用的物资，将它们收好吧。）",
          DialogueId = 71002802,
          GUID = "B1BF8134",
          SpeakNpcId = 800006
        },
        [71002803] = {
          Content = "（清理碎石的响动将周围的秽兽吸引了过来，借助洞顶的落石击退它们吧。）",
          DialogueId = 71002803,
          GUID = "B1BF815E",
          SpeakNpcId = 800006
        },
        [71002804] = {
          Content = "（一番战斗后，你在周围找到了些能用的物资，将它们收好吧。）",
          DialogueId = 71002804,
          GUID = "B1BF8188",
          SpeakNpcId = 800006
        },
        [71002901] = {
          Content = "（敌人在士官的指挥下稳步向你推进，尽快击败士官，打乱对方的指挥吧。）",
          DialogueId = 71002901,
          GUID = "B1BF9172",
          SpeakNpcId = 800006
        },
        [71002902] = {
          Content = "（敌人在你冷静而正确的应对中溃败。）",
          DialogueId = 71002902,
          GUID = "B1BF919C",
          SpeakNpcId = 800006
        },
        [71002903] = {
          Content = "（士官呼叫了新的援军，更多的敌人向你袭来了。）",
          DialogueId = 71002903,
          GUID = "B1BF91C6",
          SpeakNpcId = 800006
        },
        [71003001] = {
          Content = "（游荡的秽兽不安地嘶吼着，为附近笼罩起一丝不详的气息。尽快击退它们吧。）",
          DialogueId = 71003001,
          GUID = "B1BFA1DA",
          SpeakNpcId = 800006
        },
        [71003002] = {
          Content = "（笼罩于此的不详气息越发凝重，你知道，有什么东西就要降临了。）",
          DialogueId = 71003002,
          GUID = "B1BFA204",
          SpeakNpcId = 800006
        },
        [71003003] = {
          Content = "（争斗的声响引来了不屈的灾厄，不详的化身终于降临于此。击败它吧，就像过去的无数次一样。）",
          DialogueId = 71003003,
          GUID = "B1BFA22E",
          SpeakNpcId = 800006
        },
        [71003004] = {
          Content = "（不祥的气息随着这些秽兽一同消失了，你知道，这附近暂时安全了。）",
          DialogueId = 71003004,
          GUID = "B1BFA258",
          SpeakNpcId = 800006
        },
        [71003101] = {
          Content = "（最近多了好些觊觎魔灵的家伙，击退他们，救下眼前这只可怜的魔灵吧。）",
          DialogueId = 71003101,
          GUID = "B1BFB242",
          SpeakNpcId = 800006
        },
        [71003102] = {
          Content = "（更多敌人从远处冲了过来。）",
          DialogueId = 71003102,
          GUID = "B1BFB26C",
          SpeakNpcId = 800006
        },
        [71003103] = {
          Content = "（现在，这只魔灵安全了。）",
          DialogueId = 71003103,
          GUID = "B1BFB296",
          SpeakNpcId = 800006
        },
        [71003201] = {
          Content = "（坍塌的碎石挡住了前路，四周遗落的爆炸物也许能帮你更快地清理这些碎石。）",
          DialogueId = 71003201,
          GUID = "B1BFC2AA",
          SpeakNpcId = 800006
        },
        [71003202] = {
          Content = "（你找到了矿工们的简易爆破手册，勉强还能分辨出上面写的内容。）",
          DialogueId = 71003202,
          GUID = "B1BFC2D4",
          SpeakNpcId = 800006
        },
        [71003203] = {
          Content = "（你找到了一些爆炸物，稍微处理下应该还能用。）",
          DialogueId = 71003203,
          GUID = "B1BFC2FE",
          SpeakNpcId = 800006
        },
        [71003204] = {
          Content = "（你找到了一些引线，稍微处理下应该还能用。）",
          DialogueId = 71003204,
          GUID = "B1BFC328",
          SpeakNpcId = 800006
        },
        [71003206] = {
          Content = "（你按照旷工手册上的指示安装好了爆炸物，用它们清空面前区域吧。）",
          DialogueId = 71003206,
          Duration = 3,
          GUID = "B1BFC37C",
          SpeakNpcId = 800006
        },
        [71003207] = {
          Content = "（你在清理碎石的过程中找到了些能用的物资，将它们收好吧。）",
          DialogueId = 71003207,
          GUID = "B1BFC3A6",
          SpeakNpcId = 800006
        },
        [71003501] = {
          Content = "（远处闪闪发光的东西吸引了你的注意，靠近看看到底是什么吧。）",
          DialogueId = 71003501,
          GUID = "B1BFF3E2",
          SpeakNpcId = 800006
        },
        [71003502] = {
          Content = "我就说这亮闪闪的破镜子能引来狩月人吧，动手！",
          DialogueId = 71003502,
          GUID = "B1BFF40C",
          SpeakNpcId = 818028
        },
        [71003504] = {
          Content = "别打了别打了，我们再也不敢了……",
          DialogueId = 71003504,
          GUID = "B1BFF460",
          SpeakNpcId = 818028
        },
        [71003601] = {
          Content = "（四周突然响起了刺耳的警报，大量磁暴机朝你涌了过来。）",
          DialogueId = 71003601,
          GUID = "B1C0044A",
          SpeakNpcId = 800006
        },
        [71003602] = {
          Content = "（警报愈发响亮，更多敌人朝你涌了过来。）",
          DialogueId = 71003602,
          GUID = "B1C00474",
          SpeakNpcId = 800006
        },
        [71003603] = {
          Content = "（在逐渐安静的警报声中，最后一批敌人抵达了此处。）",
          DialogueId = 71003603,
          GUID = "B1C0049E",
          SpeakNpcId = 800006
        },
        [71003604] = {
          Content = "（伴随着所有敌人倒下，四周总算重归寂静。）",
          DialogueId = 71003604,
          GUID = "B1C004C8",
          SpeakNpcId = 800006
        },
        [71003701] = {
          Content = "咱不想……不想……不想上工啊……",
          DialogueId = 71003701,
          GUID = "B1C014B2",
          SpeakNpcId = 818019
        },
        [71003702] = {
          Content = "可恶……怎么这次还要往泪湖送吃的啊。大家就不能挑点正常的地方吃饭吗！不怕出事吗！跑死我了……",
          DialogueId = 71003702,
          GUID = "B1C014DC",
          NextDialogue = 71003703,
          SpeakNpcId = 818019
        },
        [71003703] = {
          Content = "需要帮忙吗？",
          DialogueId = 71003703,
          GUID = "B1C014DD",
          NextDialogue = 71003704,
          SpeakNpcId = 100001
        },
        [71003704] = {
          Content = "需要！我需要你狠狠咬几口这些麻烦的客人，还要朝他们丢一大堆雪球！让他们以后别在这么难找的地方叫人送菜了。",
          DialogueId = 71003704,
          GUID = "B1C014DE",
          NextOptions = {
            [1] = 710037041,
            [2] = 710037042
          },
          SpeakNpcId = 818019,
          bForbidSkipOptions = true
        },
        [71003705] = {
          Content = "唉……也就只能嘴上过过瘾了，你来了就陪咱一起去吧，多个人路上还能解解闷。上工上工……",
          DialogueId = 71003705,
          GUID = "B1C01506",
          SpeakNpcId = 818019
        },
        [71003706] = {
          Content = "这些冰渣渣掉进菜里就不好了，有没有什么办法把它们清理掉呢……",
          DialogueId = 71003706,
          GUID = "B1C01530",
          SpeakNpcId = 818019
        },
        [71003707] = {
          Content = "诶，好快！菜都还是暖的呢，我们快点送过去吧，不然老板又要唠唠叨叨了。",
          DialogueId = 71003707,
          GUID = "B1C01656",
          SpeakNpcId = 818019
        },
        [71003708] = {
          Content = "救命啊，至少让我吃饱了再死！",
          DialogueId = 71003708,
          GUID = "B1C0155A",
          NextDialogue = 71003709,
          SpeakNpcId = 818029
        },
        [71003709] = {
          Content = "居然真出事了啊！我们过去救他吧，如果他在老板面前夸夸我，老板说不定会给咱加工钱呢，嘿嘿，嘿嘿嘿……",
          DialogueId = 71003709,
          GUID = "B1C01584",
          SpeakNpcId = 818019
        },
        [71003710] = {
          Content = "碍眼的家伙没了，还有新鲜的饭菜，配着泪湖的美景，真是一大享受啊~",
          DialogueId = 71003710,
          GUID = "B1C015AE",
          NextDialogue = 71003711,
          SpeakNpcId = 818024
        },
        [71003711] = {
          Content = "啊，那个……客人，你还没付钱……",
          DialogueId = 71003711,
          GUID = "B1C015D8",
          NextDialogue = 71003712,
          SpeakNpcId = 818019
        },
        [71003712] = {
          Content = "嗯？你不就是个跑腿的吗，站在这干啥？餐钱等我下次去你们餐厅再结。",
          DialogueId = 71003712,
          GUID = "B1C01602",
          NextDialogue = 71003713,
          SpeakNpcId = 818024
        },
        [71003713] = {
          Content = "可是……这样咱没法交差呀……",
          DialogueId = 71003713,
          Duration = 3,
          GUID = "B1C0162C",
          NextDialogue = 71003714,
          SpeakNpcId = 818019
        },
        [71003714] = {
          Content = "（你将一切看在眼里，迈步跟了上去。没有人注意到，你背在身后的手上已经悄悄攒出了一枚雪球，蓄势待发。）",
          DialogueId = 71003714,
          Duration = 4,
          GUID = "B1C0162D",
          NextDialogue = 71003715,
          SpeakNpcId = 800006
        },
        [71003715] = {
          Content = "啊！哪来的雪球，好冰好冰！啊啊啊啊我的饭掉水里了！不————",
          DialogueId = 71003715,
          GUID = "B1C0162E",
          SpeakNpcId = 818024
        },
        [71003801] = {
          Content = "（游荡的秽兽挤满了通道，击退它们吧。）",
          DialogueId = 71003801,
          GUID = "B1C0251A",
          SpeakNpcId = 800006
        },
        [71003802] = {
          Content = "（更多秽兽被打斗的声响吸引，涌向了通道，击退它们吧。）",
          DialogueId = 71003802,
          GUID = "B1C02544",
          SpeakNpcId = 800006
        },
        [71003803] = {
          Content = "（通道中的所有秽兽都被你清理干净，这里暂时安全了。）",
          DialogueId = 71003803,
          GUID = "B1C0256E",
          SpeakNpcId = 800006
        },
        [71003901] = {
          Content = "房间中传来一股肃杀的气息，不安的预感萦绕在心头（待包装）",
          DialogueId = 71003901,
          GUID = "B1C03582",
          SpeakNpcId = 800006
        },
        [71003902] = {
          Content = "齿轮运动的声音响起，敌人正从开启的通道口中窜出（待包装）",
          DialogueId = 71003902,
          GUID = "B1C035AC",
          SpeakNpcId = 800006
        },
        [71003903] = {
          Content = "又是齿轮响动的声音，不远处的两个通道也开启了（待包装）",
          DialogueId = 71003903,
          GUID = "B1C035D6",
          SpeakNpcId = 800006
        },
        [71003904] = {
          Content = "齿轮转动，室内的全部通道均已开启，努力击杀敌人吧（待包装）",
          DialogueId = 71003904,
          GUID = "B1C03600",
          SpeakNpcId = 800006
        },
        [71003905] = {
          Content = "所有通道均已关闭，剩余的敌人将在不久后溃散（待包装）",
          DialogueId = 71003905,
          GUID = "B1C0362A",
          SpeakNpcId = 800006
        },
        [71004101] = {
          Content = "（废弃飞艇不知何时成了山间部分动物的大号储物箱，翻找一下也许能发现些有用的物资。）",
          DialogueId = 71004101,
          GUID = "B1C05652",
          SpeakNpcId = 800006
        },
        [71004102] = {
          Content = "（翻动物资的声响将周围的敌人吸引了过来，击退他们吧。）",
          DialogueId = 71004102,
          GUID = "B1C056A6",
          SpeakNpcId = 800006
        },
        [71004103] = {
          Content = "（敌人退去，现在可以清点下你方才收集的物资了。）",
          DialogueId = 71004103,
          GUID = "B1C056D0",
          SpeakNpcId = 800006
        },
        [71004201] = {
          Content = "唔嗯嗯嗯嗯，好结实……",
          DialogueId = 71004201,
          GUID = "B1C066BA",
          SpeakNpcId = 818038
        },
        [71004202] = {
          Content = "你在干什么？",
          DialogueId = 71004202,
          GUID = "B1C066E4",
          NextDialogue = 71004203,
          SpeakNpcId = 100001
        },
        [71004203] = {
          Content = "我最近在研究秽兽的生态，你要不要帮我找点死掉的秽兽样本呀。",
          DialogueId = 71004203,
          GUID = "B1C066E5",
          NextOptions = {
            [1] = 710042031,
            [2] = 710042032
          },
          SpeakNpcId = 818038
        },
        [71004204] = {
          Content = "好，那就交给你了！我先休息一下，一直一个人收集样本差点累死我……",
          DialogueId = 71004204,
          GUID = "B1C0670E",
          SpeakNpcId = 818038
        },
        [71004205] = {
          Content = "呜哇哇哇，周围怎么还有活的秽兽呀，别过来别过来，是我研究你们不是你们研究我！",
          DialogueId = 71004205,
          GUID = "B1C06738",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 818038
        },
        [71004206] = {
          Content = "谢啦谢啦，现在样本集齐了，我也该去继续研究了，下次见喽！",
          DialogueId = 71004206,
          GUID = "B1C0678C",
          SpeakNpcId = 818038
        },
        [71004301] = {
          Content = "（这一带总能捡到些漂亮的贝壳，打碎那些冲上岸的箱子找找看吧。）",
          DialogueId = 71004301,
          GUID = "B1C07722",
          SpeakNpcId = 800006
        },
        [71004302] = {
          Content = "（你在箱子底部找到了些被压住的贝壳。）",
          DialogueId = 71004302,
          GUID = "B1C0774C",
          SpeakNpcId = 800006
        },
        [71004303] = {
          Content = "（你早就听闻部分秽兽会躲藏在阴暗的箱子内袭击他人，但不幸的是，这一次它们撞上你了。击败它们，拿到你应得的战利品吧。）",
          DialogueId = 71004303,
          GUID = "B1C07776",
          SpeakNpcId = 800006
        },
        [71004401] = {
          Content = "（游荡的秽兽挤满了四周，先击退它们，再去解救魔灵吧。）",
          DialogueId = 71004401,
          GUID = "B1C0878A",
          SpeakNpcId = 800006
        },
        [71004402] = {
          Content = "（争斗的声响引来了不屈的灾厄，不详的化身终于降临于此。击败它吧，就像过去的无数次一样。）",
          DialogueId = 71004402,
          GUID = "B1C087B4",
          SpeakNpcId = 800006
        },
        [71004403] = {
          Content = "（附近暂时安全了，趁现在解救魔灵吧。）",
          DialogueId = 71004403,
          GUID = "B1C087DE",
          SpeakNpcId = 800006
        },
        [71004501] = {
          Content = "（敌人站在要回收的物资前，击败他们吧。）",
          DialogueId = 71004501,
          GUID = "B1C097F2",
          SpeakNpcId = 800006
        },
        [71004502] = {
          Content = "（不详的化身终于降临于此，击败它后再回收物资吧。）",
          DialogueId = 71004502,
          GUID = "B1C0981C",
          SpeakNpcId = 800006
        },
        [71004503] = {
          Content = "（附近暂时安全了，趁现在回收所有物资吧。）",
          DialogueId = 71004503,
          GUID = "B1C09846",
          SpeakNpcId = 800006
        },
        [71004601] = {
          Content = "（面前摆放着大量的物资箱，打开它们搜寻有用的物资吧。）",
          DialogueId = 71004601,
          GUID = "B1C0A85A",
          SpeakNpcId = 800006
        },
        [71004602] = {
          Content = "（你在箱子中找到了些有用的物资。）",
          DialogueId = 71004602,
          GUID = "B1C0A884",
          SpeakNpcId = 800006
        },
        [71004603] = {
          Content = "（你早就听闻部分秽兽会躲藏在阴暗的箱子内袭击他人，但不幸的是，这一次它们撞上你了。击败它们，拿到你应得的战利品吧。）",
          DialogueId = 71004603,
          GUID = "B1C0A8AE",
          SpeakNpcId = 800006
        },
        [71004701] = {
          Content = "（远处闪闪发光的东西吸引了你的注意，靠近看看到底是什么吧。）",
          DialogueId = 71004701,
          GUID = "B1C0B8C2",
          SpeakNpcId = 800006
        },
        [71004702] = {
          Content = "（在你捡起物资的一瞬间，警报响起，大量敌人朝你涌了过来，击退他们吧。）",
          DialogueId = 71004702,
          GUID = "B1C0B8EC",
          SpeakNpcId = 800006
        },
        [71004703] = {
          Content = "（警报解除，又一批敌人循着声响赶到了此处，击退他们吧。）",
          DialogueId = 71004703,
          GUID = "B1C0B916",
          SpeakNpcId = 800006
        },
        [71004704] = {
          Content = "（伴随着所有敌人倒下，四周总算重归寂静。）",
          DialogueId = 71004704,
          GUID = "B1C0B940",
          SpeakNpcId = 800006
        },
        [71004801] = {
          Content = "（远处传来碎冰掉落的声音，过去看看发生了什么吧。）",
          DialogueId = 71004801,
          GUID = "B1C0C92A",
          SpeakNpcId = 800006
        },
        [71004802] = {
          Content = "狩月人？你来得正好，最近公路下面结的冰锥有点多了，一起把它们清理掉吧。",
          DialogueId = 71004802,
          GUID = "B1C0C954",
          NextOptions = {
            [1] = 710048021,
            [2] = 710048022
          },
          SpeakNpcId = 818039
        },
        [71004803] = {
          Content = "感谢帮助，那边几块交给你了。",
          DialogueId = 71004803,
          GUID = "B1C0C97E",
          SpeakNpcId = 818039
        },
        [71004805] = {
          Content = "这样安全隐患就小很多了，拿上吧，这些都是给你的报酬。",
          DialogueId = 71004805,
          GUID = "B1C0C9D2",
          SpeakNpcId = 818039
        },
        [71004901] = {
          Content = "唉……我过不去啊，早知道提前买点草饵了。",
          DialogueId = 71004901,
          GUID = "B1C0D992",
          SpeakNpcId = 818040
        },
        [71004902] = {
          Content = "狩月人啊，我需要点莲草做鱼饵，但莲草都在湖对面我过不去啊，你能帮我采点回来吗？",
          DialogueId = 71004902,
          GUID = "B1C0D9BC",
          NextOptions = {
            [1] = 710049021,
            [2] = 710049022
          },
          SpeakNpcId = 818040,
          bForbidSkipOptions = true
        },
        [71004903] = {
          Content = "谢谢！那我就先把竿架上等你哈。",
          DialogueId = 71004903,
          GUID = "B1C0D9E6",
          SpeakNpcId = 818040
        },
        [71004905] = {
          Content = "（游荡的秽兽挤满了四周，先击退它们，再去采集莲草吧。）",
          DialogueId = 71004905,
          GUID = "B1C0DA3A",
          SpeakNpcId = 800006
        },
        [71004906] = {
          Content = "（附近的莲草被你一扫而空，把它们交给捕鱼人吧。）",
          DialogueId = 71004906,
          GUID = "B1C0DA64",
          SpeakNpcId = 800006
        },
        [71004907] = {
          Content = "好好好，这么多饵料，今天绝对能钓上鱼！",
          DialogueId = 71004907,
          GUID = "B1C0DA8E",
          SpeakNpcId = 818040
        },
        [71005001] = {
          Content = "喂，那边的朋友，能帮我拍张照吗？",
          DialogueId = 71005001,
          GUID = "B1C0E9FA",
          SpeakNpcId = 818041
        },
        [71005002] = {
          Content = "这位朋友，你能帮我拍几张照片吗？难得来一趟冰湖城，不留点合影就太可惜了。",
          DialogueId = 71005002,
          GUID = "B1C0EA24",
          NextOptions = {
            [1] = 710050021,
            [2] = 710050022
          },
          SpeakNpcId = 818041,
          bForbidSkipOptions = true
        },
        [71005004] = {
          Content = "太好了，记得把我后面的这栋房子也拍进去哦，我很喜欢它的造型。",
          DialogueId = 71005004,
          GUID = "B1C0EA78",
          SpeakNpcId = 818041
        },
        [71005005] = {
          Content = "你拍得也太好了，真棒呀，多谢多谢。",
          DialogueId = 71005005,
          GUID = "B1C0EAA2",
          SpeakNpcId = 818041
        },
        [71005101] = {
