          GUID = "B1C0FA62",
          NextDialogue = 71005103,
          SpeakNpcId = 100001
        },
        [71005103] = {
          Content = "钓鱼呢，等会再说。",
          DialogueId = 71005103,
          GUID = "B1C0FA8C",
          SpeakNpcId = 818045
        },
        [71005104] = {
          Content = "（你在一旁等了许久，男人一条鱼都没钓上来。）",
