          DialogueId = 71005105,
          GUID = "B1C0FAB6",
          NextDialogue = 71005106,
          SpeakNpcId = 100001
        },
        [71005106] = {
          Content = "别说话，看着就好。",
          DialogueId = 71005106,
          GUID = "B1C0FAE0",
          SpeakNpcId = 818045
        },
        [71005107] = {
          Content = "（你在一旁等了许久，男人还是一条鱼都没钓上来。）",
