          DialogueId = 80004205,
          Duration = 3,
          GUID = "C84839E2",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120114/C84839E2"
        },
        [80004206] = {
          Content = "终于走出迷雾了！快看，森林的出口就在前面。",
          DialogueId = 80004206,
          Duration = 3,
          GUID = "C8483A0C",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120114/C8483A0C"
        },
        [80004207] = {
          Content = "走出森林之后，会见到怎样的风景呢？好期待呀！",
          DialogueId = 80004207,
          Duration = 3,
          GUID = "C8483A36",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120114/C8483A36"
        },
        [80004208] = {
          Content = "咦，那是……大魔法师、独角兽{性别：先生|小姐}和蝴蝶小姐！大家都在等我们呢。",
          DialogueId = 80004208,
          Duration = 3,
          GUID = "C8483A60",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 80004209,
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120114/C8483A60"
        },
        [80004209] = {
          Content = "小夜莺，我们赶快过去和它们会合吧！",
          DialogueId = 80004209,
          Duration = 3,
          GUID = "C8483A8A",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120114/C8483A8A"
        },
