        [80004250] = {
          Content = "好像不该选这个颜色……再换一种颜料试试看吧！",
          DialogueId = 80004250,
          Duration = 3,
          GUID = "C8483B09",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120114/C8483B09"
        },
        [80004251] = {
          Content = "它好像更适合另一种颜色哦。",
          DialogueId = 80004251,
          Duration = 3,
          GUID = "C8483B0A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120114/C8483B0A"
        },
        [80004252] = {
          Content = "哎呀，刚才涂好的颜色已经不见了……",
          DialogueId = 80004252,
          Duration = 3,
          GUID = "C8483B0B",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 80004253,
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120114/C8483B0B"
        },
        [80004253] = {
          Content = "看来要快一点涂完才行呢！",
          DialogueId = 80004253,
          Duration = 3,
          GUID = "C8483B0C",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
