        },
        [80050315] = {
          Content = "…………",
          DialogueId = 80050315,
          FacialId = {
            [1] = "790017:Disappoint01"
          },
          GUID = "C865C6CE",
          NextOptions = {
            [1] = 80050316
          },
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/003/C865C6CE"
        },
        [80050316] = {
          Content = "怎么了？你不认识的话，我来告诉你吧。",
          DialogueId = 80050316,
          GUID = "C865C6F8",
