          DialogueId = 80080120,
          FacialId = {
            [1] = "790004:Unhappy01"
          },
          GUID = "C878E0B0",
          LookAt = {
            [1] = "790002:n(790004)",
            [2] = "790001:n(790004)",
            [3] = "790003:n(790004)"
