        [80080125] = {
          Camera = "-182.740234,418.929565,109.427734,0.000006,0.00002,-72.598679,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "就像亨特告诉我们狩月人每天都能遇到怎样的委托，米娅让我们知道泪湖的冰下面其实藏着各种各样的鱼……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080125,
          GUID = "C878E182",
          NextDialogue = 80080126,
          SpeakNpcId = 790004,
          TalkActionId = {
