          Content = "现在的我变贪心了许多许多……我开始渴望能再多一些时间，再多一些……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080333,
          GUID = "C87903A2",
          NextDialogue = 80080334,
          SpeakNpcId = 790004,
          TalkActionId = {
            [1] = "790004:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87903A2"
        },
        [80080334] = {
