          Content = "我开始渴望可以牵起一个人的手，一起逃离冰湖城，到很远、很远的地方……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080334,
          GUID = "C87903CC",
          NextDialogue = 80080335,
          SpeakNpcId = 790004,
          TalkActionId = {
            [1] = "790004:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87903CC"
        },
        [80080335] = {
          Camera = "-178.794922,-57.247498,139.419922,0.000046,-6.999994,44.603405,32.0,100000.0,false,DoNotOverride,2.8",
          Content = "我开始渴望可以长到爸爸妈妈的年纪……可以变成满脸皱纹的老婆婆……可以坐在广场上，一边给鸟儿喂食，一边和城里的孩子们讲述年轻时的故事……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080335,
          GUID = "C87903F6",
          NextDialogue = 80080336,
          SpeakNpcId = 790004,
          TalkActionId = {
            [1] = "790004:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87903F6"
        },
        [80080336] = {
          Camera = "-178.794922,-57.247498,139.419922,0.000046,-6.999994,44.603405,32.0,100000.0,false,DoNotOverride,2.8",
          Content = "我曾以为，我只要过好最后的日子就已经足够了。但是现在的我想要……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080336,
          GUID = "C8790420",
          NextDialogue = 80080337,
          SpeakNpcId = 790004,
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790420"
        },
        [80080337] = {
          Camera = "-115.541016,2.555298,138.173828,0.000146,-6.001127,46.597878,32.000004,100000.0,false,DoNotOverride,2.8",
          Content = "“活下去”。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080337,
          GUID = "C879044A",
          NextDialogue = 80080338,
          SpeakNpcId = 790004,
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C879044A"
        },
        [80080338] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          Content = "所以，恩里克叔叔，请答应我的请求吧。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080338,
          GUID = "C8790474",
          NextDialogue = 80080339,
          SpeakNpcId = 790004,
          TalkActionId = {
