        [80090100] = {
          Content = "嘻嘻，今天要玩什么？",
          DialogueId = 80090100,
          GUID = "C87F4608"
        },
        [80090101] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          Content = "……",
          DialogueId = 80090101,
          FacialId = {
            [1] = "92301:Unhappy01"
          },
          GUID = "C87F4632",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090102,
          SpeakNpcId = 92301
        },
        [80090102] = {
          Content = "……",
          DialogueId = 80090102,
          GUID = "C87F465C",
          NextDialogue = 80090103,
          SpeakNpcId = 92301
        },
        [80090103] = {
          Content = "……喂！我刚才喝完饮料突然消失了，你怎么跟没事人似的！",
          DialogueId = 80090103,
          GUID = "C87F4686",
          NextDialogue = 80090104,
          SpeakNpcId = 92301
        },
        [80090104] = {
          Content = "光天化日之下，“恶魔大盗”神秘失踪！你就不觉得很奇怪、很担心吗！",
          DialogueId = 80090104,
          GUID = "C87F46B0",
          NextOptions = {
            [1] = 80090105,
            [2] = 80090107
          },
          SpeakNpcId = 92301
        },
        [80090105] = {
          Content = "刚才这里多了一把椅子，那是你变的吧。",
          DialogueId = 80090105,
          GUID = "C87F46DA",
          NextDialogue = 80090106
        },
        [80090106] = {
          Content = "什么！你居然看破了我的伪装绝技！",
          DialogueId = 80090106,
          FacialId = {
            [1] = "92301:Shock01"
          },
          GUID = "C87F4704",
          NextDialogue = 80090109,
          SpeakNpcId = 92301
        },
        [80090107] = {
          Content = "担心？塔比瑟变成椅子逗我开心，我欣慰才是。",
          DialogueId = 80090107,
          GUID = "C87F472E",
          NextDialogue = 80090108
        },
        [80090108] = {
          Content = "噫，你也太自作多情了，我只是想吓唬你！吓——唬！",
          DialogueId = 80090108,
          GUID = "C87F4758",
          NextDialogue = 80090109,
          SpeakNpcId = 92301
        },
        [80090109] = {
          Content = "……嘁，这次算我失手了，下次我一定变成你想不到的东西！",
          DialogueId = 80090109,
          FacialId = {
            [1] = "92301:Unhappy01"
          },
          GUID = "C87F4782",
          NextDialogue = 80090110,
          SpeakNpcId = 92301
        },
        [80090110] = {
          Content = "变什么好呢……酒桶？吊灯？大锤？",
          DialogueId = 80090110,
          GUID = "C87F47AC",
          NextDialogue = 80090111,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Think_Start"
          }
        },
        [80090111] = {
          Content = "哇哦，你好有本领。",
          DialogueId = 80090111,
          GUID = "C87F47D6",
          NextDialogue = 80090112,
          SpeakNpcId = 790008
        },
        [80090112] = {
          Content = "那当然！听说我这本事叫做……泥，泥什么来着……泥台？……拟态！对对，“拟态”！",
          DialogueId = 80090112,
          FacialId = {
            [1] = "92301:Satisfy01"
          },
          GUID = "C87F4800",
          NextDialogue = 80090113,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_End"
          }
        },
        [80090113] = {
          Content = "所以你什么都能变？",
          DialogueId = 80090113,
          GUID = "C87F482A",
          NextDialogue = 80090114,
          SpeakNpcId = 790008
        },
        [80090114] = {
          Content = "嘻嘻，可不是！看好了——",
          DialogueId = 80090114,
          GUID = "C87F4854",
          NextDialogue = 80090144,
          SpeakNpcId = 92301
        },
        [80090115] = {
          Camera = "159.880188,-5.018555,149.99321,0.000005,1.39885,175.800934,30.000002,159.585938,false,Manual,3.0",
          Content = "我会提出一个你无法拒绝的条件，你最好深思熟虑之后再回答我。",
          DialogueId = 80090115,
          GUID = "C87F487E",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090116,
          SpeakNpcId = 790052,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [80090116] = {
          Content = "叫醒我的是生意，叫醒你的是什么？",
          DialogueId = 80090116,
          GUID = "C87F48A8",
          NextOptions = {
            [1] = 80090117,
            [2] = 80090119
          },
          SpeakNpcId = 790052,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [80090117] = {
          Content = "噗嗤——叫醒我的是恶魔大盗的万丈光芒！",
          DialogueId = 80090117,
          GUID = "C87F48D2",
          NextDialogue = 80090118
        },
        [80090118] = {
          Content = "嘻嘻，嘴真甜，比你调的饮料还甜！",
          DialogueId = 80090118,
          FacialId = {
            [1] = "790052:Happy01"
          },
          GUID = "C87F48FC",
          NextDialogue = 80090144,
          SpeakNpcId = 790052,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "790052:Explain02_Start"
          }
        },
        [80090119] = {
          Content = "噗嗤——我告卡米拉了！",
          DialogueId = 80090119,
          GUID = "C87F4926",
          NextDialogue = 80090120
        },
        [80090120] = {
          Content = "我才不怕她嘞！没人能抓到恶魔大盗！",
          DialogueId = 80090120,
          FacialId = {
            [1] = "790052:Confident01"
          },
          GUID = "C87F4950",
          NextDialogue = 80090144,
          SpeakNpcId = 790052,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "790052:Angry01_Start"
          }
        },
        [80090121] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          Content = "不过我也不是什么都会变，太大和太小的东西都不行。猫咪可以，老鼠就不可以。木桶可以，路灯架子就不可以。",
          DialogueId = 80090121,
          GUID = "C87F497A",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090122,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk02_Start"
          }
        },
        [80090122] = {
          Content = "但这就足够了，大部分人根本发现不了我的完美伪装！我随便变个罐子箱子垃圾桶什么的，那些坏小偷啊，就只能乖乖地被我收拾了！",
          DialogueId = 80090122,
          GUID = "C87F49A4",
          NextOptions = {
            [1] = 80090123,
            [2] = 80090131
          },
          SpeakNpcId = 92301
        },
        [80090123] = {
          Content = "……完了，以后可有得头疼了。",
          DialogueId = 80090123,
          GUID = "C87F49CE",
          NextDialogue = 80090124
        },
        [80090124] = {
          Content = "你嘀嘀咕咕什么呢？",
          DialogueId = 80090124,
          FacialId = {
            [1] = "92301:Doubt01"
          },
          GUID = "C87F49F8",
          NextDialogue = 80090125,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToTalkL_End"
          }
        },
        [80090125] = {
          Content = "没什么，夸你很厉害的意思。",
          DialogueId = 80090125,
          GUID = "C87F4A22",
          NextDialogue = 80090126,
          SpeakNpcId = 790008
        },
        [80090126] = {
          Content = "但之后还是别变箱子罐子垃圾桶了，万一被人路过随手打烂了然后翻翻找找有用的东西可怎么办……",
          DialogueId = 80090126,
          GUID = "C87F4A4C",
          NextDialogue = 80090127,
          SpeakNpcId = 790008
        },
        [80090127] = {
          Content = "谁手这么欠啊？",
          DialogueId = 80090127,
          GUID = "C87F4A76",
          NextDialogue = 80090128,
          SpeakNpcId = 92301
        },
        [80090128] = {
          Content = "呃……一些特别富有好奇心的路过市民？",
          DialogueId = 80090128,
          GUID = "C87F4AA0",
          NextDialogue = 80090129,
          SpeakNpcId = 790008
        },
        [80090129] = {
          Content = "有用的就收起来，没用的就利用完丢掉，坏大人都一个样！",
          DialogueId = 80090129,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F4ACA",
          NextDialogue = 80090130,
          SpeakNpcId = 92301
        },
        [80090130] = {
          Content = "路过市民可没想伤害任何人！不过，你一直挂在嘴上的“坏大人”是什么？",
          DialogueId = 80090130,
          GUID = "C87F4AF4",
          NextDialogue = 80090136,
          SpeakNpcId = 790008
        },
        [80090131] = {
          Content = "听起来很厉害，还好你没什么坏心思。",
          DialogueId = 80090131,
          GUID = "C87F4B1E",
          NextDialogue = 80090132
        },
        [80090132] = {
          Content = "什么意思？",
          DialogueId = 80090132,
          FacialId = {
            [1] = "92301:Doubt01"
          },
          GUID = "C87F4B48",
          NextDialogue = 80090133,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToTalkL_End"
          }
        },
        [80090133] = {
          Content = "我是说，要是那些有点小聪明但心思很坏的家伙有这种本事，那整座城都要鸡飞狗跳了。",
          DialogueId = 80090133,
          GUID = "C87F4B72",
          NextDialogue = 80090134,
          SpeakNpcId = 790008
        },
        [80090134] = {
          Content = "哼哼，我也这么觉得！我和那些坏大人可不是一路人。等等，你难道是想说本“恶魔大盗”不够聪明？",
          DialogueId = 80090134,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F4B9C",
          NextDialogue = 80090135,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          }
        },
        [80090135] = {
          Content = "没有没有，塔比瑟是很聪明的好恶魔。不过这些不重要，我更好奇，“那些坏大人”是什么？",
          DialogueId = 80090135,
          GUID = "C87F4BC6",
          NextDialogue = 80090136,
          SpeakNpcId = 790008
        },
        [80090136] = {
          Content = "就是欺负弱小的坏蛋大人！我最先碰到的坏大人就是孤儿院那些照顾小孩的……啧，说是照顾，其实和看犯人没啥两样。",
          DialogueId = 80090136,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F4BF0",
          NextDialogue = 80090137,
          SpeakNpcId = 92301
        },
        [80090137] = {
          Content = "小时候我饿着肚子去厨房找东西吃，被那些坏大人们发现了的话，就会挨打。坏死了！明明是他们不给我东西吃在先！",
          DialogueId = 80090137,
          GUID = "C87F4C1A",
          NextDialogue = 80090138,
          SpeakNpcId = 92301
        },
        [80090138] = {
          Content = "要是现在再让我遇到他们，我就把他们一个个倒立着捆起来挂在房顶，让他们瞪大眼看着我把厨房的东西吃光光！",
          DialogueId = 80090138,
          GUID = "C87F4C44",
          NextOptions = {
            [1] = 80090139,
            [2] = 80090140
          },
          SpeakNpcId = 92301
        },
        [80090139] = {
          Content = "都过去了。现在的塔比瑟已经不会被坏大人打了。",
          DialogueId = 80090139,
          GUID = "C87F4C6E",
          NextDialogue = 80090141
        },
        [80090140] = {
          Content = "对，这些坏家伙就该给点颜色瞧瞧。",
          DialogueId = 80090140,
          GUID = "C87F4C98",
          NextDialogue = 80090141
        },
        [80090141] = {
          Content = "哼！就是就是！",
          DialogueId = 80090141,
          FacialId = {
            [1] = "92301:Satisfy01"
          },
          GUID = "C87F4CC2",
          NextDialogue = 80090142,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          }
        },
        [80090142] = {
          Content = "饮料喝完了，“坏大人”的事下次再讲，现在快陪我出去玩！",
          DialogueId = 80090142,
          GUID = "C87F4CEC",
          NextDialogue = 80090143,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03_End"
          }
        },
        [80090143] = {
          Content = "嘻嘻嘻，我们来玩捉迷藏吧，这次我可不会再被你轻松找到了！",
          DialogueId = 80090143,
          FacialId = {
            [1] = "92301:Smile02"
          },
          GUID = "C87F4D16",
          SpeakNpcId = 92301
        },
        [80090144] = {
          DialogueId = 80090144,
          DialoguePanelType = "None",
          Duration = 1,
          GUID = "C87F4D17",
          IsBlack = 1
        },
        [80090201] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          Content = "嗯~喝起来有点咸咸的，不过好好喝喔，就像海风味的棉花糖一样！",
          DialogueId = 80090201,
          FacialId = {
            [1] = "92301:Smile01"
          },
          GUID = "C87F569A",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090202,
          SpeakNpcId = 92301
        },
        [80090202] = {
          Content = "总感觉在很久很久以前我好像喝过类似的饮料，那时候我和爸爸妈妈一起乘上的船还没有沉，我也还没有漂到镇上被孤儿院收养……",
          DialogueId = 80090202,
          GUID = "C87F56C4",
          NextDialogue = 80090203,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Think_Start"
          }
        },
        [80090203] = {
          Content = "但如果再让我选，还不如自己一个人流浪呢！坏大人们连吃的都不愿多给，更别说饮料了。",
          DialogueId = 80090203,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F56EE",
          NextDialogue = 80090204,
          SpeakNpcId = 92301
        },
        [80090204] = {
          Content = "就算是流浪好歹也能在垃圾桶里捡点吃的，总比在坏大人魔爪下饿肚子强多了！",
          DialogueId = 80090204,
          GUID = "C87F5718",
          NextDialogue = 80090205,
          SpeakNpcId = 92301
        },
        [80090205] = {
          Content = "等到长大点了，就会有群贵客时不时带走一些和我一样没人要的长角小孩，说是被有钱人领养了。",
          DialogueId = 80090205,
          FacialId = {
            [1] = "92301:None"
          },
          GUID = "C87F5742",
          NextDialogue = 80090206,
          SpeakNpcId = 92301
        },
        [80090206] = {
          Content = "我不想要别的爸爸妈妈，但有钱人家一定不缺吃的，我想去，但坏大人说我调皮捣蛋又不老实，贵客才不会看上我咧！",
          DialogueId = 80090206,
          GUID = "C87F576C",
          NextDialogue = 80090207,
          SpeakNpcId = 92301
        },
        [80090207] = {
          Content = "哼！那又怎么样，要是乖乖听话我就不是塔比瑟了！反正这鬼地方我是一天也待不下去了，于是我就趁着贵客不注意，变成了他的手提箱。",
          DialogueId = 80090207,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F5796",
          NextDialogue = 80090208,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_End"
          }
        },
        [80090208] = {
          Content = "看来所谓的有钱人也不怎么聪明嘛！贵客把我拎起来就走，什么也没发现，就是苦了我的耳朵，被当成提手拎了一路，差点就掉在地上啦！",
          DialogueId = 80090208,
          GUID = "C87F57C0",
          NextOptions = {
            [1] = 80090209,
            [2] = 80090211
          },
          SpeakNpcId = 92301
        },
        [80090209] = {
          Content = "噫，听着就痛！以后我一定好好保护你的耳朵！",
          DialogueId = 80090209,
          GUID = "C87F57EA",
          NextDialogue = 80090210
        },
        [80090210] = {
          Content = "……这话怎么好像听着怪怪的……算了，这个不是重点！",
          DialogueId = 80090210,
          FacialId = {
            [1] = "92301:Doubt01"
          },
          GUID = "C87F5814",
          NextDialogue = 80090213,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_DisagreeHead"
          }
        },
        [80090211] = {
          Content = "塔比瑟居然能从那种地方逃出来，未来的“恶魔大盗”的人非同一般！",
          DialogueId = 80090211,
          GUID = "C87F583E",
          NextDialogue = 80090212
        },
        [80090212] = {
          Content = "嘻嘻，那当然！可惜那时候我还不太熟练，否则我才不会把耳朵变成脸对着提手呢。",
          DialogueId = 80090212,
          GUID = "C87F5868",
          NextDialogue = 80090213,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          }
        },
        [80090213] = {
          Content = "其实我本来是想悄悄混在那几个被领养的孩子里的，想着如果能被有钱人领养，我就再也不用饿肚子了吧。",
          DialogueId = 80090213,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F5892",
          NextDialogue = 80090214,
          SpeakNpcId = 92301
        },
        [80090214] = {
          Content = "但是贵客浑身上下都是奇怪的消毒水味儿，呛得我鼻子痛！而且，不知道为什么，我总觉得……他看孩子们的眼神，有点瘆人……",
          DialogueId = 80090214,
          GUID = "C87F58BC",
          NextDialogue = 80090215,
          SpeakNpcId = 92301
        },
        [80090215] = {
          Content = "就像是……厨师大叔看鱼，看鸭子的那种眼神！",
          DialogueId = 80090215,
          GUID = "C87F58E6",
          NextDialogue = 80090216,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_Start"
          }
        },
        [80090216] = {
          Content = "好大人少见，坏大人我可见太多啦！与其去相信他们，还不如靠我自己呢。所以我最后没有混进孩子的队伍里，一个人悄悄逃掉了。",
          DialogueId = 80090216,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F5910",
          NextDialogue = 80090217,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_End"
          }
        },
        [80090217] = {
          Content = "这就是塔比瑟成为恶魔大盗的第一步！",
          DialogueId = 80090217,
          GUID = "C87F593A",
          NextOptions = {
            [1] = 80090218,
            [2] = 80090220
          },
          SpeakNpcId = 92301
        },
        [80090218] = {
          Content = "我想塔比瑟并不是坏孩子，你只是……很特别。",
          DialogueId = 80090218,
          GUID = "C87F5964",
          NextDialogue = 80090219
        },
        [80090219] = {
          Content = "我不是坏，而是很特别吗？还没人这么说过我……特别的孩子，特别的孩子……嘻嘻！",
          DialogueId = 80090219,
          FacialId = {
            [1] = "92301:Happy01"
          },
          GUID = "C87F598E",
          NextDialogue = 80090223,
          SpeakNpcId = 92301
        },
        [80090220] = {
          Content = "“贵客”听起来就很可疑，塔比瑟做出了冷静的判断。",
          DialogueId = 80090220,
          GUID = "C87F59B8",
          NextDialogue = 80090221
        },
        [80090221] = {
          Content = "就是就是！你也这么觉得吧！",
          DialogueId = 80090221,
          GUID = "C87F59E2",
          NextDialogue = 80090222,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          }
        },
        [80090222] = {
          Content = "不过那时候我光顾着自己逃了。要是我有现在的本事，一定悄悄跟在他们屁股后面，看看他们是不是在做坏事！",
          DialogueId = 80090222,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F5A0C",
          NextDialogue = 80090223,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_End"
          }
        },
        [80090223] = {
          Content = "能安全逃出来，塔比瑟已经做得很好了，恭喜你获得了自由。",
          DialogueId = 80090223,
          GUID = "C87F5A36",
          NextDialogue = 80090224,
          SpeakNpcId = 790008
        },
        [80090224] = {
          Content = "是呀，恭喜我自己！好不容易又呼吸到新鲜空气，第一次发现夜空并不一直都是黑黢黢的，那些透过脏玻璃看起来没精打采的星星，原来也可以这么明亮。",
          DialogueId = 80090224,
          FacialId = {
            [1] = "92301:Happy01"
          },
          GUID = "C87F5A60",
          NextDialogue = 80090225,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          }
        },
        [80090225] = {
          Content = "我躺在草地上，伴着星星睡了一大觉，转天醒来，是个大晴天！之后我就一直住在那个海边小镇，再也没有“坏大人”打我了！",
          DialogueId = 80090225,
          GUID = "C87F5A8A",
          NextDialogue = 80090226,
          SpeakNpcId = 92301
        },
        [80090226] = {
          Content = "我还在那里遇到了一个人……",
          DialogueId = 80090226,
          GUID = "C87F5AB4",
          NextDialogue = 80090227,
          SpeakNpcId = 92301
        },
        [80090227] = {
          Content = "塔比瑟终于碰到好人了吗？",
          DialogueId = 80090227,
          GUID = "C87F5ADE",
          NextDialogue = 80090228,
          SpeakNpcId = 790008
        },
        [80090228] = {
          Content = "大好人！但我今天有点累了……“恶魔大盗”也会累的！",
          DialogueId = 80090228,
          FacialId = {
            [1] = "92301:Smile02"
          },
          GUID = "C87F5B08",
          NextDialogue = 80090229,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          }
        },
        [80090229] = {
          Content = "等你下次准备好新饮料了，我再讲给你听！",
          DialogueId = 80090229,
          GUID = "C87F5B32",
          SpeakNpcId = 92301
        },
        [80090301] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          Content = "这次的饮料也很美味！嘻嘻嘻，你可真了解我的口味！",
          DialogueId = 80090301,
          FacialId = {
            [1] = "92301:Happy01"
          },
          GUID = "C87F6702",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090302,
          SpeakNpcId = 92301
        },
        [80090302] = {
          Content = "本大盗昨天晚上是躺着草地看着夜空睡着的，天空从湛蓝色逐渐变深，星星一颗颗挂在上面，和撒着糖霜的蓝莓奶盖一模一样！",
          DialogueId = 80090302,
          GUID = "C87F672C",
          NextDialogue = 80090303,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk02_Start"
          }
        },
        [80090303] = {
          Content = "除了逃出孤儿院的那晚，我其实很少在草地上睡得这么安稳。",
          DialogueId = 80090303,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F6756",
          NextDialogue = 80090304,
          SpeakNpcId = 92301
        },
        [80090304] = {
          Content = "……因为，刚到小镇的时候，我做了很多不好的事……",
          DialogueId = 80090304,
          GUID = "C87F6780",
          NextDialogue = 80090305,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk02_End"
          }
        },
        [80090305] = {
          Content = "所以大人们不喜欢我，叫我“恶魔”……",
          DialogueId = 80090305,
          GUID = "C87F67AA",
          NextOptions = {
            [1] = 80090306,
            [2] = 80090308
          },
          SpeakNpcId = 92301
        },
        [80090306] = {
          Content = "是不是恶作剧没掌握好分寸？",
          DialogueId = 80090306,
          GUID = "C87F67D4",
          NextDialogue = 80090307
        },
        [80090307] = {
          Content = "是他们太笨了！唔……好吧，你说的对。",
          DialogueId = 80090307,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F67FE",
          NextDialogue = 80090310,
          SpeakNpcId = 92301
        },
        [80090308] = {
          Content = "是不是偷吃了小镇上所有的海鱼？",
          DialogueId = 80090308,
          GUID = "C87F6828",
          NextDialogue = 80090309
        },
        [80090309] = {
          Content = "我哪有那么能吃！唔，不过你也说对了一部分……",
          DialogueId = 80090309,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F6852",
          NextDialogue = 80090310,
          SpeakNpcId = 92301
        },
        [80090310] = {
          Content = "我一直靠偷吃小摊上的食物过活。小贩们气得想打我，我就学他们气急败坏的样子，还对他们做鬼脸，也没觉得有什么不对。",
          DialogueId = 80090310,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F687C",
          NextDialogue = 80090311,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk01_Start"
          }
        },
        [80090311] = {
          Content = "“分我一点你们又饿不死，小气鬼！”",
          DialogueId = 80090311,
          GUID = "C87F68A6",
          NextDialogue = 80090312,
          SpeakNpcId = 92301
        },
        [80090312] = {
          Content = "直到遇见了她……",
          DialogueId = 80090312,
          FacialId = {
            [1] = "92301:Smile01"
          },
          GUID = "C87F68D0",
          NextDialogue = 80090313,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk01_End"
          }
        },
        [80090313] = {
          Content = "她是鱼摊摊主的女儿，看见我偷她家东西，不仅不打我，分海鱼给我吃，还问我家人在哪，如果走丢了可以在她家先住一晚，我第一次遇到这么好的人。",
          DialogueId = 80090313,
          GUID = "C87F68FA",
          NextDialogue = 80090314,
          SpeakNpcId = 92301
        },
        [80090314] = {
          Content = "后来发生了许多事……她没有家了，只能去孤儿院，那可不行！我受过的罪，才不会让她也受一遍！我要带着她一起生活！",
          DialogueId = 80090314,
          GUID = "C87F6924",
          NextDialogue = 80090315,
          SpeakNpcId = 92301
        },
        [80090315] = {
          Content = "我们一起在大太阳下傻笑，在海边撩起水花溅到对方身上，在泥泞的小路上跑来跑去，我会变成各种小动物逗她开心。",
          DialogueId = 80090315,
          GUID = "C87F694E",
          NextDialogue = 80090316,
          SpeakNpcId = 92301
        },
        [80090316] = {
          Content = "她还叫我“塔比瑟姐姐”！虽然和我一起饥一顿饱一顿地过日子，她却一直说自己很幸福。",
          DialogueId = 80090316,
          GUID = "C87F6978",
          NextDialogue = 80090317,
          SpeakNpcId = 92301
        },
        [80090317] = {
          Content = "也是因为她，我才决定不再拿好大人的东西了，我要做个“恶魔大盗”，专门去惩罚那些坏大人！",
          DialogueId = 80090317,
          GUID = "C87F69A2",
          NextOptions = {
            [1] = 80090318,
            [2] = 80090320
          },
          SpeakNpcId = 92301
        },
        [80090318] = {
          Content = "是因为很在意她的想法吗？",
          DialogueId = 80090318,
          GUID = "C87F69CC",
          NextDialogue = 80090319
        },
        [80090319] = {
          Content = "嗯，我不想她伤心。",
          DialogueId = 80090319,
          GUID = "C87F69F6",
          NextDialogue = 80090326,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          }
        },
        [80090320] = {
          Content = "塔比瑟姐姐！",
          DialogueId = 80090320,
          GUID = "C87F6A20",
          NextDialogue = 80090321
        },
        [80090321] = {
          Content = "怎么突然……救命，住口啊，尴尬死了！",
          DialogueId = 80090321,
          FacialId = {
            [1] = "92301:Unacceptable01"
          },
          GUID = "C87F6A4A",
          NextDialogue = 80090322,
          SpeakNpcId = 92301
        },
        [80090322] = {
          Content = "我就想试试如果我也喊一下，你会不会也带我过日子……",
          DialogueId = 80090322,
          GUID = "C87F6A74",
          NextDialogue = 80090323,
          SpeakNpcId = 790008
        },
        [80090323] = {
          Content = "噫！你怎么拿自己跟八岁小孩比呢！我还以为你已经是个成熟的大人了。",
          DialogueId = 80090323,
          GUID = "C87F6A9E",
          NextDialogue = 80090324,
          SpeakNpcId = 92301
        },
        [80090324] = {
          Content = "开玩笑的。所以，塔比瑟是很在意她的想法吗？",
          DialogueId = 80090324,
          GUID = "C87F6AC8",
          NextDialogue = 80090325,
          SpeakNpcId = 790008
        },
        [80090325] = {
          Content = "因为她问我：“偷善良人的东西，是对的吗？”",
          DialogueId = 80090325,
          GUID = "C87F6AF2",
          NextDialogue = 80090326,
          SpeakNpcId = 92301
        },
        [80090326] = {
          Content = "我一开始想，那些小贩哪里善良了，看我饿的肚皮都贴一起了，也不给我点吃的，就知道对我发脾气。",
          DialogueId = 80090326,
          FacialId = {
            [1] = "92301:None"
          },
          GUID = "C87F6B1C",
          NextDialogue = 80090327,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03_Start"
          }
        },
        [80090327] = {
          Content = "后来我才发现，有的小贩明明看见我拿东西吃，却没管我。",
          DialogueId = 80090327,
          GUID = "C87F6B46",
          NextDialogue = 80090328,
          SpeakNpcId = 92301
        },
        [80090328] = {
          Content = "追着我打的小贩们，好像也只是追几步就算了……当然了，也是因为本大盗逃得够快！",
          DialogueId = 80090328,
          GUID = "C87F6B70",
          NextDialogue = 80090329,
          SpeakNpcId = 92301
        },
        [80090329] = {
          Content = "有些摊主还会主动把没卖完的食物留给我，但我只当他们怕了我，那些食物统统是上贡给本大盗的保护费！",
          DialogueId = 80090329,
          GUID = "C87F6B9A",
          NextDialogue = 80090330,
          SpeakNpcId = 92301
        },
        [80090330] = {
          Content = "我只记得别人对我有多坏，却假装没看见这些好人。",
          DialogueId = 80090330,
          GUID = "C87F6BC4",
          NextDialogue = 80090331,
          SpeakNpcId = 92301
        },
        [80090331] = {
          Content = "……想来想去，就觉得心里堵堵的，吃到嘴里的食物也不是滋味了。",
          DialogueId = 80090331,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F6BEE",
          NextDialogue = 80090332,
          SpeakNpcId = 92301
        },
        [80090332] = {
          Content = "我好像把对“坏大人”的恨，都报复到了这些小贩身上。",
          DialogueId = 80090332,
          GUID = "C87F6C18",
          NextDialogue = 80090333,
          SpeakNpcId = 92301
        },
        [80090333] = {
          Content = "我真是个“恶魔”……",
          DialogueId = 80090333,
          GUID = "C87F6C42",
          NextOptions = {
            [1] = 80090334,
            [2] = 80090336
          },
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03_End"
          }
        },
        [80090334] = {
          Content = "塔比瑟已经做得很好了，很多人用一生都未必能正视自己的错误。",
          DialogueId = 80090334,
          GUID = "C87F6C6C",
          NextDialogue = 80090335
        },
        [80090335] = {
          Content = "谢谢你……唉，其实你不用安慰我的，错了就是错了。",
          DialogueId = 80090335,
          FacialId = {
            [1] = "92301:None"
          },
          GUID = "C87F6C96",
          NextDialogue = 80090338,
          SpeakNpcId = 92301
        },
        [80090336] = {
          Content = "塔比瑟总有一天也会长大，如果一直欺负好人，不也成了坏大人的一员了吗？",
          DialogueId = 80090336,
          GUID = "C87F6CC0",
          NextDialogue = 80090337
        },
        [80090337] = {
          Content = "你说的没错……唉，你骂吧，多骂几句，我会乖乖听着，不还嘴的。",
          DialogueId = 80090337,
          GUID = "C87F6CEA",
          NextDialogue = 80090338,
          SpeakNpcId = 92301
        },
        [80090338] = {
          Content = "之后我就一直拿坏小偷和坏大人的东西了，又威风，还不会伤害那些好人。",
          DialogueId = 80090338,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F6D14",
          NextDialogue = 80090339,
          SpeakNpcId = 92301
        },
        [80090339] = {
          Content = "你还真别说，那些坏人可有钱了！我已经很少饿肚子了，偶尔再逗逗他们，看他们恼羞成怒的样子，嘻嘻嘻，日子过得可有趣了！",
          DialogueId = 80090339,
          GUID = "C87F6D3E",
          NextOptions = {
            [1] = 80090340
          },
          SpeakNpcId = 92301
        },
        [80090340] = {
          Content = "想捉弄他们才是重点吧。",
          DialogueId = 80090340,
          GUID = "C87F6D68",
          NextDialogue = 80090341
        },
        [80090341] = {
          Content = "没错！咳咳咳，才不是！这叫“为民除害”，他们长记性了，就知道欺负好人是不对的了。",
          DialogueId = 80090341,
          GUID = "C87F6D92",
          NextDialogue = 80090342,
          SpeakNpcId = 92301
        },
        [80090342] = {
          Content = "今天说了好多话，嗓子都冒烟了！",
          DialogueId = 80090342,
          GUID = "C87F6DBC",
          NextDialogue = 80090343,
          SpeakNpcId = 92301
        },
        [80090343] = {
          Content = "嘻嘻嘻，刚才的蓝莓饮料，再来一杯嘛！",
          DialogueId = 80090343,
          FacialId = {
            [1] = "92301:Smile02"
          },
          GUID = "C87F6DE6",
          SpeakNpcId = 92301
        },
        [80090401] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          Content = "真好喝！不管喝多少次都不会腻呢！本大盗可不经常夸人的，不过，还是谢谢你总是为我准备食物啦。",
          DialogueId = 80090401,
          FacialId = {
            [1] = "92301:Smile01"
          },
          GUID = "C87F776A",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090402,
          SpeakNpcId = 92301
        },
        [80090402] = {
          Content = "嘻嘻嘻，白喝了你这么多次饮料，难得让你也尝尝本大盗的手艺吧！",
          DialogueId = 80090402,
          FacialId = {
            [1] = "92301:Smile02"
          },
          GUID = "C87F7794",
          NextDialogue = 80090403,
          SpeakNpcId = 92301
        },
        [80090403] = {
          Content = "你的面前放了一杯可疑的黑色液体，不断有小气泡涌上来，散发着一股诡异的味道，仔细看里面的沉淀物五花八门，能辨认出来的就有各种果干与糖果。",
          DialogueId = 80090403,
          GUID = "C87F77BE",
          NextDialogue = 80090404
        },
        [80090404] = {
          Content = "当当当！这就是塔比瑟的独家特调——和我共享同一个称号的“恶魔大盗”！嘻嘻嘻，我可是把我所有的感激之情都放在里面咯！",
          DialogueId = 80090404,
          GUID = "C87F77E8",
          NextOptions = {
            [1] = 80090405,
            [2] = 80090410
          },
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk01_Start"
          }
        },
        [80090405] = {
          Content = "不喝",
          DialogueId = 80090405,
          GUID = "C87F7812",
          NextDialogue = 80090406
        },
        [80090406] = {
          Content = "真没品味！这可是世界上仅此一杯的“恶魔大盗”！",
          DialogueId = 80090406,
          FacialId = {
            [1] = "92301:Unhappy01"
          },
          GUID = "C87F783C",
          NextDialogue = 80090407,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_DisagreeHead"
          }
        },
        [80090407] = {
          Content = "里面的材料全都是好大人分享我的好东西，本大盗自己都舍不得吃，才一点点存到现在得，我都不敢想把他们放在一起有多美味！",
          DialogueId = 80090407,
          GUID = "C87F7866",
          NextDialogue = 80090408,
          SpeakNpcId = 92301
        },
        [80090408] = {
          Content = "这样吧！本大盗和你一人一半怎么样？咳咳，才不是我也想尝尝，只是为了给胆小鬼做个榜样！",
          DialogueId = 80090408,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F7890",
          NextDialogue = 80090409,
          SpeakNpcId = 92301
        },
        [80090409] = {
          Content = "来，干杯！",
          DialogueId = 80090409,
          GUID = "C87F78BA",
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk01_End"
          }
        },
        [80090410] = {
          Content = "喝",
          DialogueId = 80090410,
          GUID = "C87F78E4",
          NextDialogue = 80090411
        },
        [80090411] = {
          Content = "真有眼光！",
          DialogueId = 80090411,
          FacialId = {
            [1] = "92301:Happy01"
          },
          GUID = "C87F790E",
          NextDialogue = 80090412,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          }
        },
        [80090412] = {
          Content = "里面的材料全都是好大人分享我的好东西，本大盗自己都舍不得吃，才一点点存到现在得，我都不敢想把他们放在一起有多美味！",
          DialogueId = 80090412,
          GUID = "C87F7938",
          NextDialogue = 80090413,
          SpeakNpcId = 92301
        },
        [80090413] = {
          Content = "这么珍贵的东西我要留给谁喝呢？想来想去果然只有你了。不过可不可以分我一点？嘻嘻，本大盗也很好奇“世界上最好喝的饮料”是什么味道嘛！",
          DialogueId = 80090413,
          GUID = "C87F7962",
          NextDialogue = 80090414,
          SpeakNpcId = 92301
        },
        [80090414] = {
          Content = "好啦好啦！害臊的话说到这里就可以啦，干杯！",
          DialogueId = 80090414,
          GUID = "C87F798C",
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk01_End"
          }
        },
        [80090415] = {
          Content = "你们一起喝下了塔比瑟的专属特调，诡异的甜味充斥着你的口腔，随后你就失去了意识。",
          DialogueId = 80090415,
          GUID = "C87F79B6",
          IsBlack = 1,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}"
        },
        [80090416] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          Content = "还有气。只是睡过去了，两个都没事。",
          DialogueId = 80090416,
          DisableMouth = 1,
          FacialId = {
            [1] = "92301:Close"
          },
          GUID = "C87F79E0",
