          NextDialogue = 80090417,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "92301:Zhangyu_Story_Tentacle"
          }
        },
        [80090417] = {
          Content = "呜呜……吓死我了……早就和塔比瑟说了不要什么都往里放，出事了可怎么办……呜呜……",
          DialogueId = 80090417,
          DisableMouth = 1,
          GUID = "C87F7A0A",
          IsBlack = 1,
          NextDialogue = 80090418,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [80090418] = {
          Content = "嘻嘻嘻嘻，说不定会把脑袋喝坏，再出现奇奇怪怪的后遗症！",
          DialogueId = 80090418,
          DisableMouth = 1,
          GUID = "C87F7A34",
          IsBlack = 1,
          NextDialogue = 80090419,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [80090419] = {
          Content = "乌鸦嘴，少说两句吧！",
          DialogueId = 80090419,
          DisableMouth = 1,
          GUID = "C87F7A5E",
          IsBlack = 1,
          NextOptions = {
            [1] = 80090420
          },
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [80090420] = {
          Content = "……谁？",
          DialogueId = 80090420,
          GUID = "C87F7A88",
          NextDialogue = 80090421
        },
        [80090421] = {
          Content = "你看到几条从塔比瑟身上延伸出来的触须正对着你轻柔地摇晃。",
          DialogueId = 80090421,
          DisableMouth = 1,
          GUID = "C87F7AB2",
          NextDialogue = 80090422
        },
        [80090422] = {
          Content = "你们听到了吗？……{nickname}在和我们说话。",
          DialogueId = 80090422,
          DisableMouth = 1,
          GUID = "C87F7ADC",
          NextDialogue = 80090423,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [80090423] = {
          Content = "据鄙人所知，只有塔比瑟才能听见我们说话吧？",
          DialogueId = 80090423,
          DisableMouth = 1,
          GUID = "C87F7B06",
          NextDialogue = 80090424,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [80090424] = {
          Content = "……糟了糟了糟了，好像真的喝出毛病了！我就知道……每次5号说什么不好就应什么！算我求求你了，下次可千万别再张嘴了！",
          DialogueId = 80090424,
          DisableMouth = 1,
          GUID = "C87F7B30",
          NextOptions = {
            [1] = 80090425
          },
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [80090425] = {
          Content = "触手……在说话……？",
          DialogueId = 80090425,
          GUID = "C87F7B5A",
          NextDialogue = 80090426
        },
        [80090426] = {
          Content = "呃……你好？我们确实是塔比瑟的腕足，没想到会在这种情况下说上话！人生还真是猝不及防呀~哈、哈……",
          DialogueId = 80090426,
          DisableMouth = 1,
          GUID = "C87F7B84",
          NextDialogue = 80090427,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu6"
        },
        [80090427] = {
