            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B11E"
        },
        [80100116] = {
          Content = "但我从未放弃过寻找，这片土地既然孕育了我这幅怪模样，那就一定也孕育了能够包容我的人。",
          DialogueId = 80100116,
          GUID = "C885B148",
          NextDialogue = 80100117,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B148"
        },
        [80100117] = {
          Content = "而你，我酒红色瞳仁的朋友，你让我看到了这种可能。",
          DialogueId = 80100117,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885B172",
          NextDialogue = 80100118,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B172"
        },
        [80100118] = {
          Content = "所以，就把这次共饮当作是我们的初次甜蜜约会吧，作为对我坦白的赠礼。",
          DialogueId = 80100118,
          GUID = "C885B19C",
          NextDialogue = 80100119,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B19C"
        },
        [80100119] = {
          Content = "或者，你也可以选择拒绝。不过那会让你的唇舌被毒液封住，永远为我保守秘密。你觉得哪个更好呢？",
          DialogueId = 80100119,
          GUID = "C885B1C6",
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B1C6"
        },
        [80100201] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          Content = "我们又一次独处了，难得，很少有人在知晓我的那一面之后还没有尖叫离去。",
          DialogueId = 80100201,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885BF3A",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextOptions = {
            [1] = 801002011
          },
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BF3A"
        },
        [80100202] = {
          Content = "你肯定有所察觉吧？",
          DialogueId = 80100202,
          GUID = "C885BF64",
          NextDialogue = 80100203,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BF64"
        },
        [80100203] = {
          Content = "伸出你自己的手臂看看吧。看，那是一双多么干净的手啊，即使带着旧日的茧子和伤痕，依旧洁净无暇。在劳累时，这只手臂会渗出咸咸的汗水——",
          DialogueId = 80100203,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885BF8E",
          NextDialogue = 80100204,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BF8E"
        },
        [80100204] = {
          Content = "但我这只手呢，渗出的只有致命的毒。",
          DialogueId = 80100204,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885BFB8",
          NextDialogue = 80100205,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BFB8"
        },
        [80100205] = {
          Content = "无法控制的毒液像一个不听话的老朋友，我倚仗它，它帮我驱赶走林间小径中伏击的秽兽，让追捕我的士兵们在暗处永眠。",
          DialogueId = 80100205,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885BFE2",
          NextDialogue = 80100206,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BFE2"
        },
        [80100206] = {
          Content = "可是它也会张牙舞爪地让我想要亲近的事物远离，哪怕我只是用泉水洗一洗脸，凑近的鱼儿也会麻痹窒息。",
          DialogueId = 80100206,
          GUID = "C885C00C",
          NextDialogue = 80100207,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C00C"
        },
        [80100207] = {
          Content = "我曾经厌弃它，如果没有这些毒液，那么我就会同年龄相仿的那些女孩子一样，去市集挑选衣服，在墙角探头，偷偷看喜欢的人。",
          DialogueId = 80100207,
          FacialId = {
            [1] = "92101:Iyada01"
          },
          GUID = "C885C036",
          NextOptions = {
            [1] = 801002071,
            [2] = 801002072
          },
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C036"
        },
        [80100208] = {
          Content = "称不上是梦想，只不过是那时候偶尔闪过的念头，回想起来只会觉得可笑。",
          DialogueId = 80100208,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885C060",
          NextDialogue = 80100210,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C060"
        },
        [80100209] = {
          Content = "与其说是习惯，不如说是驯服，我找到了更合适的相处方法。",
          DialogueId = 80100209,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885C08A",
          NextDialogue = 80100210,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C08A"
        },
        [80100210] = {
          Content = "如今的我不需要默默偷看，更不需要用漫长而聒噪的交谈彼此试探。只需要一瞬间的甜蜜拥抱，我便知晓眼前的人是否能够与我长相厮守。",
          DialogueId = 80100210,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885C0B4",
          NextDialogue = 80100211,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C0B4"
        },
        [80100211] = {
          Content = "毒液正是我最宝贵的试金石——倘若真的有一天，一个能够承受住我拥抱的人出现在面前，那我便立刻可以确定，这个人就是我命中注定的爱人。",
          DialogueId = 80100211,
          GUID = "C885C0DE",
          NextDialogue = 80100212,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C0DE"
        },
        [80100212] = {
          Content = "只可惜，这样的人还没出现，也许永远都不会出现，但是你不觉得，这要比俗人们浅薄无聊的情话要浪漫得多吗？",
          DialogueId = 80100212,
          FacialId = {
            [1] = "92101:Iyada01"
          },
          GUID = "C885C108",
          NextDialogue = 80100213,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C108"
        },
        [80100213] = {
          Content = "至少对于现在的我来说，这就是一份礼物。畏惧我的，恐吓我的，怜爱我的，迎合我的，都需要接受平等的考验。",
          DialogueId = 80100213,
          GUID = "C885C132",
          NextDialogue = 80100214,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C132"
        },
        [80100214] = {
          Content = "所以虽然现在的我与之前同样，一路漂泊，但是再也不会羡慕别人，毕竟我独一无二的毒液，也一定会帮我找到一份独一无二的爱情。",
          DialogueId = 80100214,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885C15C",
          NextDialogue = 80100215,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C15C"
        },
        [80100215] = {
          Content = "那么现在，我想张开双臂问你一个问题：要和我拥抱吗？",
          DialogueId = 80100215,
          GUID = "C885C186",
          NextOptions = {
            [1] = 801002151,
            [2] = 801002152
          },
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C186"
        },
        [80100216] = {
          Content = "呵呵，别害怕嘛，你还是头一个能听我讲了这么多过去的事的人，尽管机会只有一次，但说不定你就是我要找的那个人呢？",
          DialogueId = 80100216,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885C1B0",
          NextDialogue = 80100218,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C1B0"
        },
        [80100217] = {
          Content = "然后你就会用手中的剑刺穿我的喉咙？不用这么戒备，我能感觉到，其实我们是同一类人，都拥有与他人不同的命运。",
          DialogueId = 80100217,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885C1DA",
          NextDialogue = 80100218,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C1DA"
        },
        [80100218] = {
          Content = "唉，没想到这场自你而始的约会居然以你的拒绝而结束，真是让人遗憾。",
          DialogueId = 80100218,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885C204",
          NextDialogue = 80100219,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C204"
        },
        [80100219] = {
          Content = "不过，我们之间还有的是时间，你可要小心咯，说不定哪一天，我就会从背后紧紧抱住你。",
          DialogueId = 80100219,
          FacialId = {
            [1] = "92101:Confident02"
          },
          GUID = "C885C22E",
          NextOptions = {
            [1] = 801002191
          },
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C22E"
        },
        [80100220] = {
          Content = "哎呀，真可爱，像是露出牙齿的小猫，看来我还是稍微远离你好一点，再见啦，我很期待我们下一次见面。",
          DialogueId = 80100220,
          FacialId = {
            [1] = "92101:Happy02"
          },
          GUID = "C885C258",
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C258"
        },
        [80100221] = {
          Camera = "106.860352,-6.606262,134.715088,0.0,-0.99996,-137.396057,51.444664,130.0,false,Manual,2.8",
          Content = "嘿，时隔数秒，我们又见面了。",
          DialogueId = 80100221,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885C282",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextDialogue = 80100222,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C282"
        },
        [80100222] = {
          Content = "看起来，你也没有真的很防备我嘛，真让人高兴。放心吧，我也没有打算现在就拥抱你，只想忠告你一句：",
          DialogueId = 80100222,
          GUID = "C885C2AC",
          NextDialogue = 80100223,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C2AC"
        },
        [80100223] = {
          Content = "等下次再见面，只要听到我的声音，就一定要转过身来看着我，不要移开视线，否则，会很危险哦。",
          DialogueId = 80100223,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885C2D6",
          NextDialogue = 80100224,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C2D6"
        },
        [80100224] = {
          Content = "那么，这次是真正的再见。",
          DialogueId = 80100224,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885C300",
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C300"
        },
        [80100301] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          Content = "今天我是被“爱的默契”呼唤来的，我的每一滴毒液都渴望着见你。",
          DialogueId = 80100301,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885CFA2",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextDialogue = 80100302,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885CFA2"
        },
        [80100302] = {
          Content = "来，看看现在的我们有多默契吧。猜猜我接下来会说些什么呢？",
          DialogueId = 80100302,
          GUID = "C885CFCC",
          NextOptions = {
            [1] = 801003021,
            [2] = 801003022
          },
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885CFCC"
        },
        [80100303] = {
          Content = "直截了当也是你的魅力之一呢。",
          DialogueId = 80100303,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885CFF6",
          NextDialogue = 80100304,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885CFF6"
        },
        [80100304] = {
          Content = "那就让我们跳过这些弯弯绕绕，直接聊聊过去的故事吧。",
          DialogueId = 80100304,
          GUID = "C885D020",
          NextDialogue = 80100307,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D020"
        },
        [80100305] = {
          Content = "没错呢，我们果然默契十足，看来我接下来要做的事果然没错。",
          DialogueId = 80100305,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885D04A",
          NextDialogue = 80100306,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D04A"
        },
        [80100306] = {
          Content = "实际上，我要向你坦白一些事情，向你坦白危险正在迫近。",
          DialogueId = 80100306,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D074",
          NextDialogue = 80100307,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D074"
        },
        [80100307] = {
          Content = "我曾经遇到过一位与我类似的人，她生来便是皮肤通红，如同烈火一般，个性也是同样，易怒，难以容忍杂质。",
          DialogueId = 80100307,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885D09E",
          NextDialogue = 80100308,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D09E"
        },
        [80100308] = {
          Content = "与我这样自幼遭人厌弃的怪物不同，她承担着家族的使命，肩负着厚望，并且最终成为了看管囚人的正义裁决者，不会放过任何一个她盯上的罪犯。",
          DialogueId = 80100308,
          GUID = "C885D0C8",
          NextDialogue = 80100309,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D0C8"
        },
        [80100309] = {
          Content = "不过，她的火焰与我的毒相似，会驱赶一切想要靠近的人，无论是善意还是恶意，都无法靠近，或是因为害怕而远离。",
          DialogueId = 80100309,
          GUID = "C885D0F2",
          NextOptions = {
            [1] = 801003091
          },
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D0F2"
        },
        [80100310] = {
          Content = "是啦。你知道的，像我这种天生携带剧毒的怪物，故意也好无意也罢，总是会不小心背上几条命的。所以，有人追捕我，也不足为奇吧？",
          DialogueId = 80100310,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D11C",
          NextDialogue = 80100311,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D11C"
        },
        [80100311] = {
          Content = "不过在她漫长而执着的追捕中，我意识到了一点：她其实和我一样，也是个孤独的怪物。所以呢，我利用了这一点。",
          DialogueId = 80100311,
          GUID = "C885D146",
          NextDialogue = 80100312,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D146"
        },
        [80100312] = {
          Content = "我献上看似真诚的倾诉，让她一度迟疑，觉得自己并非阿特拉西亚广袤大陆上唯一一个异类，觉得她的怜悯和宽恕可以让我就此停手。",
          DialogueId = 80100312,
          GUID = "C885D170",
          NextDialogue = 80100313,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D170"
        },
        [80100313] = {
          Content = "而我则在她亲手帮我毁灭罪证之后，逃走了。",
          DialogueId = 80100313,
          GUID = "C885D19A",
          LookAt = {
            [1] = "92101:p(18000P2)"
          },
          NextDialogue = 80100314,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D19A"
        },
        [80100314] = {
          Content = "你大概无法想象那个人咬碎了牙，火冒三丈想要抓到我的样子。不过，你应该明白，包庇我的你，会被视为共犯，而一同被投入牢狱。",
          DialogueId = 80100314,
          FacialId = {
            [1] = "92101:Iyada01"
          },
          GUID = "C885D1C4",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextOptions = {
            [1] = 801003141,
            [2] = 801003142
          },
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D1C4"
        },
        [80100315] = {
          Content = "原来是这样，我开始理解为什么一见到你时，就能够感到一丝令人沉醉的危险气息。",
          DialogueId = 80100315,
          FacialId = {
            [1] = "92101:Shock01"
          },
          GUID = "C885D1EE",
          NextDialogue = 80100316,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D1EE"
        },
        [80100316] = {
          Content = "那么，我已经告知了你未来将会面对的危险，而你并没有表示反对，是不是意味着，我可以继续和你走得近了。",
          DialogueId = 80100316,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D218",
          NextDialogue = 80100317,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D218"
        },
        [80100317] = {
          Content = "原本在告知你这些过去的危险之前，我还是有一些忐忑，担心我会不会就此再次踏上旅途游荡。",
          DialogueId = 80100317,
          GUID = "C885D242",
          NextDialogue = 80100318,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D242"
        },
        [80100318] = {
          Content = "但，我更加不愿意见到我面前的你，遭受更多的危险——只是我的毒液，便已足够危险了。",
          DialogueId = 80100318,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885D26C",
          NextDialogue = 80100319,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D26C"
        },
        [80100319] = {
          Content = "还好，你的回答让我越发坚信，只要我留在这里，就一定能够寻觅到我的命定之人。",
          DialogueId = 80100319,
          GUID = "C885D296",
          NextOptions = {
            [1] = 801003191
          },
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D296"
        },
        [80100320] = {
          Content = "是啊，一个我从卢卡之国到海伯利亚，都未曾找到的人，我曾经以为那个人只存在于我的梦境之中，熠熠生辉，却又飘摇模糊。",
          DialogueId = 80100320,
          GUID = "C885D2C0",
          NextDialogue = 80100321,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D2C0"
        },
        [80100321] = {
          Content = "{性别：他|她}会以刚强的身躯，承受我全部的毒……会以无瑕的心，接受我全部的爱……会用慈悲的手，拂去我全部的悲哀……",
          DialogueId = 80100321,
          FacialId = {
            [1] = "92101:Confident02"
          },
          GUID = "C885D2EA",
          NextDialogue = 80100322,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D2EA"
        },
        [80100322] = {
          Content = "你说，那个人，{性别：他|她}会听到吗？",
          DialogueId = 80100322,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D314",
          NextOptions = {
            [1] = 801003221,
            [2] = 801003222
          },
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D314"
        },
        [80100323] = {
          Content = "啊……噗……哈哈哈哈……",
          DialogueId = 80100323,
          FacialId = {
            [1] = "92101:Happy02"
          },
          GUID = "C885D33E",
          NextDialogue = 80100324,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D33E"
        },
        [80100324] = {
          Content = "你果然是个可爱、古怪、有趣到让我欲罢不能的家伙呢……",
          DialogueId = 80100324,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885D368",
          NextDialogue = 80100325,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D368"
        },
        [80100325] = {
          Content = "虽然现在我很想用毒液将你立刻包裹……但我这个人啊，也不喜欢草率的玩笑。",
          DialogueId = 80100325,
          GUID = "C885D392",
          NextDialogue = 80100326,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D392"
        },
        [80100326] = {
          Content = "所以不妨给你我一点思考时间，让我想想应该怎么做吧。",
          DialogueId = 80100326,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D3BC",
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D3BC"
        },
        [80100327] = {
          Content = "狡猾的人啊，你是如何想出这样模棱两可的话语，拒绝别人，但又留下一丝若有若无的机会。",
          DialogueId = 80100327,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885D3E6",
          NextDialogue = 80100328,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D3E6"
        },
        [80100328] = {
          Content = "适当的距离，我该怎么理解才好？对我来说，最适当的距离，那自然是形影不离。但……在你的眼里，合适的距离是如何呢？",
          DialogueId = 80100328,
          GUID = "C885D410",
          NextDialogue = 80100329,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D410"
        },
        [80100329] = {
          Content = "是像隐藏关系的爱侣一般，在其他人面前装作熟视无睹，只暗地里纠缠不休？还是就此天各一方，永远永远都不会再见？",
          DialogueId = 80100329,
          GUID = "C885D43A",
          NextDialogue = 80100330,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D43A"
        },
        [80100330] = {
          Content = "但这天平的两端反而是最简单的答案。看起来，比起直接了当地说出“我愿意”或是“你会遇见更好的人”，你宁愿选择会一直持续的交谈与试探。",
          DialogueId = 80100330,
          FacialId = {
            [1] = "92101:Iyada01"
          },
          GUID = "C885D464",
          NextDialogue = 80100331,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D464"
        },
        [80100331] = {
          Content = "我不能太过靠近而给你带来危险，也不能离你远去而让我们彻底成为陌路。",
          DialogueId = 80100331,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D48E",
          NextDialogue = 80100332,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D48E"
        },
        [80100332] = {
          Content = "如同去调制一份没有标明比例的香水配方，只能不断拨弄砝码，寻找最合适的结果。",
          DialogueId = 80100332,
          GUID = "C885D4B8",
          NextOptions = {
            [1] = 801003321
          },
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D4B8"
        },
        [80100333] = {
          Content = "是啊，毕竟我从未面对这样的难题，并且我相信，解开它之后，我会获得一直在寻求的那个答案，找到我的命定之人。",
          DialogueId = 80100333,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885D4E2",
          NextOptions = {
            [1] = 801003331
          },
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D4E2"
        },
        [80100334] = {
          Content = "是啊，一个我从卢卡之国到海伯利亚，都未曾找到的人，我曾经以为那个人只存在于我的梦境之中，熠熠生辉，却又飘摇模糊。",
          DialogueId = 80100334,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885D50C",
          NextDialogue = 80100335,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D50C"
        },
        [80100335] = {
          Content = "{性别：他|她}会以刚强的身躯，承受我全部的毒……会以无瑕的心，接受我全部的爱……会用慈悲的手，拂去我全部的悲哀……",
          DialogueId = 80100335,
          GUID = "C885D536",
          NextDialogue = 80100336,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D536"
        },
        [80100336] = {
          Content = "至于那个命定之人，是不是你这个可爱、古怪、有趣到让我欲罢不能的家伙……",
          DialogueId = 80100336,
          FacialId = {
            [1] = "92101:Smile01"
          },
          GUID = "C885D560",
          NextDialogue = 80100337,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D560"
        },
        [80100337] = {
          Content = "给我一点时间，让我想想应该怎么做吧。",
          DialogueId = 80100337,
          GUID = "C885D58A",
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D58A"
        },
        [80100401] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          Content = "唉……",
          DialogueId = 80100401,
          FacialId = {
            [1] = "92101:Sad02"
          },
          GUID = "C885E00A",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextOptions = {
            [1] = 801004011,
            [2] = 801004012
          },
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E00A"
        },
        [80100402] = {
          Content = "是的哦，是非常非常烦心的事，让我心烦意乱。而心烦的原因，就是出现在我面前的你。",
          DialogueId = 80100402,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E034",
          NextDialogue = 80100404,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E034"
        },
        [80100403] = {
          Content = "不，并不是时间的问题，而是人的问题。从收到邀请的那一刻开始，我就开始烦恼。",
          DialogueId = 80100403,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E05E",
          NextDialogue = 80100404,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E05E"
        },
        [80100404] = {
          Content = "你知道吗，虽然你看起来纯白无瑕，但也能够用毒将人窒息。",
          DialogueId = 80100404,
          GUID = "C885E088",
          NextDialogue = 80100405,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E088"
        },
        [80100405] = {
          Content = "不过你并非是像我那样，在初初见面时就宣告自己的危险，而是精心编制了一张言语的网。",
          DialogueId = 80100405,
          GUID = "C885E0B2",
          NextDialogue = 80100406,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E0B2"
        },
        [80100406] = {
          Content = "也许你并非有意，但正因如此，所以才更加让人在不知不觉间习惯停留在这里，被你潜移默化，变得不像原本的自己。",
          DialogueId = 80100406,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885E0DC",
          NextDialogue = 80100407,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E0DC"
        },
        [80100407] = {
          Content = "我离开卢卡之国之后，就很少一个地方过多停留，也没有遇见过真正值得重视的人。",
          DialogueId = 80100407,
          GUID = "C885E106",
          LookAt = {
            [1] = "92101:p(18000P2)"
          },
          NextDialogue = 80100408,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E106"
        },
        [80100408] = {
          Content = "本以为这次也是同样，我会在一个我厌倦的时刻，以拥抱作为最终的告别。",
          DialogueId = 80100408,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E130",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextDialogue = 80100409,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E130"
        },
        [80100409] = {
          Content = "但是这次我竟然犹豫了，身体内的毒液在和我窃窃私语：你无法离开这里。",
          DialogueId = 80100409,
          FacialId = {
            [1] = "92101:Iyada01"
          },
          GUID = "C885E15A",
          NextDialogue = 80100410,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E15A"
        },
        [80100410] = {
          Content = "我不能接受这样的自己，而这也是我烦恼的根源。所以我决定，必须在今天，为这场旅途的休憩画上一个句点。",
          DialogueId = 80100410,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E184",
          NextDialogue = 80100411,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E184"
        },
        [80100411] = {
          Content = "简而言之——我要用毒液将你包裹，向你告别。",
          DialogueId = 80100411,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885E1AE",
          NextDialogue = 80100412,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E1AE"
        },
        [80100412] = {
          Content = "那么，在你的生命剩下的这最后几秒里，还有什么想说的？",
          DialogueId = 80100412,
          GUID = "C885E1D8",
          NextOptions = {
            [1] = 801004121,
            [2] = 801004122
          },
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E1D8"
        },
        [80100413] = {
          Content = "逃避？没有哦，我很清楚自己到底想要的是什么。我只想欣赏你那恐惧的面容。",
          DialogueId = 80100413,
          FacialId = {
            [1] = "92101:Shock01"
          },
          GUID = "C885E202",
          NextDialogue = 80100414,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E202"
        },
        [80100414] = {
          Content = "可惜，你看起来并没有被吓到，真是让人遗憾。",
          DialogueId = 80100414,
          GUID = "C885E22C",
          NextDialogue = 80100416,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E22C"
        },
        [80100415] = {
          Content = "真的吗？你居然没有被吓到？我本来还想欣赏你那恐惧的面容，真是让人遗憾。",
          DialogueId = 80100415,
          FacialId = {
            [1] = "92101:Shock01"
          },
          GUID = "C885E256",
          NextDialogue = 80100416,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E256"
        },
        [80100416] = {
          Content = "那我只能退而求其次，和你说一说我真正的决定了。",
          DialogueId = 80100416,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E280",
          NextDialogue = 80100417,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E280"
        },
        [80100417] = {
          Content = "与你相处的这段日子和我过去的每一天都完全不同。我在每个这样的午后说起情话，和你彼此试探……",
          DialogueId = 80100417,
          FacialId = {
            [1] = "92101:Smile01"
          },
          GUID = "C885E2AA",
          NextDialogue = 80100418,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E2AA"
        },
        [80100418] = {
          Content = "然后在分别后撑起伞，跑到没有人的小巷子里，回想着我们说过的话，一个人跳舞，晃晃悠悠。",
          DialogueId = 80100418,
          GUID = "C885E2D4",
          NextDialogue = 80100419,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E2D4"
        },
        [80100419] = {
          Content = "呵呵……这也不失为一种浪漫？",
          DialogueId = 80100419,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E2FE",
          NextDialogue = 80100420,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E2FE"
        },
        [80100420] = {
          Content = "虽然一直以来我都想要一个可以承受住我拥抱的命定之人，但直到今天，我才意识到，我想要的不过是一份独一无二的爱情。",
          DialogueId = 80100420,
          FacialId = {
            [1] = "92101:Smile01"
          },
          GUID = "C885E328",
          NextDialogue = 80100421,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E328"
        },
        [80100421] = {
          Content = "“拥抱”曾是我的试金石，但当唯一一次心动了，我便知晓，独一无二的爱，本就无需考验。",
          DialogueId = 80100421,
          GUID = "C885E352",
          NextDialogue = 80100422,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E352"
        },
        [80100422] = {
          Content = "亲吻和拥抱并非必要，相反，我想要的是更长久，不会散去的后调。",
          DialogueId = 80100422,
          GUID = "C885E37C",
          NextDialogue = 80100423,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E37C"
        },
        [80100423] = {
          Content = "每天互相道一声早安，闻一闻我最新调配的香水，再去尝试更多的配方，这样日复一日的生活，好像也不错。",
          DialogueId = 80100423,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885E3A6",
          NextDialogue = 80100424,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E3A6"
        },
        [80100424] = {
          Content = "我会设法配制能让我的毒液失效的香水，或者去寻找可以净化毒素的魔法。像故乡童谣里的小美人鱼那样，为了爱人，想尽办法，让自己脱胎换骨。",
          DialogueId = 80100424,
          GUID = "C885E3D0",
          NextDialogue = 80100425,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E3D0"
        },
        [80100425] = {
          Content = "或许在未来的某一天，我可以拥抱你。",
          DialogueId = 80100425,
          GUID = "C885E3FA",
          LookAt = {
            [1] = "92101:p(18000P2)"
          },
          NextDialogue = 80100426,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E3FA"
        },
        [80100426] = {
          Content = "不为试探，只因为，我爱你。",
          DialogueId = 80100426,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885E424",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E424"
        },
        [80110100] = {
          Content = "哈，谢了。",
          DialogueId = 80110100,
          GUID = "C88C1748",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1748"
        },
        [80110101] = {
          Camera = "127.060242,12.009277,131.847168,0.0,-0.799959,-137.39563,30.0,150.0,false,Manual,2.8",
          Content = "评价你的手艺？那你找错人了，我又不懂这些。",
          DialogueId = 80110101,
          FacialId = {
            [1] = "93101:Sad02"
          },
          GUID = "C88C1772",
          LookAt = {
            [1] = "93101:p(18000P3)"
          },
          NextDialogue = 80110102,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1772"
        },
        [80110102] = {
          Content = "对我来说，全天下所有的酒都一样，能喝就行。你对着那些瓶瓶罐罐捣鼓半天，和在我面前念诗一样，就听个响。",
          DialogueId = 80110102,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C179C",
          NextOptions = {
            [1] = 801101021
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C179C"
        },
        [80110103] = {
          Content = "军团是打仗的，不是野餐的。",
          DialogueId = 80110103,
          GUID = "C88C17C6",
          NextDialogue = 80110104,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C17C6"
        },
        [80110104] = {
          Content = "等等，你说“军团”……",
          DialogueId = 80110104,
          FacialId = {
            [1] = "93101:Doubt01"
          },
          GUID = "C88C17F0",
          NextDialogue = 80110105,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C17F0"
        },
        [80110105] = {
          Content = "……你什么居心？打什么主意？什么身份？谁派你来的？想探听哪一块情报？给我交代。",
          DialogueId = 80110105,
          GUID = "C88C181A",
          NextOptions = {
            [1] = 801101051,
            [2] = 801101052
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C181A"
        },
        [80110106] = {
          Content = "区区一个“狩月人”，你知道的也太多了。",
          DialogueId = 80110106,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1844",
          NextDialogue = 80110107,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1844"
        },
        [80110107] = {
          Content = "……我就知道，无事献殷勤，一定图谋不轨。",
          DialogueId = 80110107,
          GUID = "C88C186E",
          NextDialogue = 80110108,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C186E"
        },
        [80110108] = {
          Content = "跟我回军团接受讯问。自觉点，不要让我把你捆起来扛着，咱们都不好看。",
          DialogueId = 80110108,
          FacialId = {
            [1] = "93101:Confident01"
          },
          GUID = "C88C1898",
          NextDialogue = 80110109,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1898"
        },
        [80110109] = {
          Content = "（琳恩不由分说地拔出了手枪，黑洞洞的枪口对准了你的眉心——你脑海中浮现出这样的画面。）",
          DialogueId = 80110109,
          GUID = "C88C18C2",
          IsBlack = 1,
          NextDialogue = 80110110,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C18C2"
        },
        [80110110] = {
          Content = "（可以预见，这是必然的结局。你摇摇头，打消了这个过于冒险的念头。）",
          DialogueId = 80110110,
          GUID = "C88C18EC",
          IsBlack = 1,
          NextDialogue = 80110111,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C18EC"
        },
        [80110111] = {
          Content = "你误会了，只是看见了你，顺带请你坐坐，喝杯酒而已。",
          DialogueId = 80110111,
          GUID = "C88C1916",
          NextDialogue = 80110112,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1916"
        },
        [80110112] = {
          Content = "…………",
          DialogueId = 80110112,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1940",
          NextDialogue = 80110113,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1940"
        },
        [80110113] = {
          Content = "是我太紧张了，嗯，咳，对不住啊{性别：兄弟|小妹}。",
          DialogueId = 80110113,
          FacialId = {
            [1] = "93101:Iyada01"
          },
          GUID = "C88C196A",
          NextDialogue = 80110114,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C196A"
        },
        [80110114] = {
          Content = "毕竟之前也有胆大包天的狩月人看我以前也干过这行，就跑来套近乎，跟我打听军团的秘密。",
          DialogueId = 80110114,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1994",
          NextOptions = {
            [1] = 801101141,
            [2] = 801101142
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1994"
        },
        [80110115] = {
          Content = "是啊，挺多年前的事了。不对，这话可以说吗？",
          DialogueId = 80110115,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C19BE",
          NextDialogue = 80110116,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C19BE"
        },
        [80110116] = {
          Content = "……算了，军团也没规定必须隐瞒自己以前的身份。",
          DialogueId = 80110116,
          GUID = "C88C19E8",
          NextOptions = {
            [1] = 801101161
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C19E8"
        },
        [80110117] = {
          Content = "唉，你不知道军团是个什么鬼地方。",
          DialogueId = 80110117,
          FacialId = {
            [1] = "93101:Iyada01"
          },
          GUID = "C88C1A12",
          NextDialogue = 80110118,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1A12"
        },
        [80110118] = {
          Content = "军团的围墙上都是滋啦滋啦冒着火花的月髓电网，防逃兵，也能防不长眼的贼和间谍。",
          DialogueId = 80110118,
          GUID = "C88C1A3C",
          NextDialogue = 80110119,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1A3C"
        },
        [80110119] = {
          Content = "但那只是看得见的电网，好躲，军团里还有一层看不见的电网——你要是不小心办错事说错话，指不定就“啪”一下，给自己电死了。",
          DialogueId = 80110119,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1A66",
          NextDialogue = 80110120,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1A66"
        },
        [80110120] = {
          Content = "特别是我那个大长官最讨厌叛徒。我可不想平白无故被人套了情报，一不留神丢了小命。",
          DialogueId = 80110120,
          FacialId = {
            [1] = "93101:Sad02"
          },
          GUID = "C88C1A90",
          NextOptions = {
            [1] = 801101201,
            [2] = 801101202
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1A90"
        },
        [80110121] = {
          Content = "废话，这军团又不是我想去的。",
          DialogueId = 80110121,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1ABA",
          NextDialogue = 80110123,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1ABA"
        },
        [80110122] = {
          Content = "威风？让你威风，然后让你天天干一些把小命拴在扳机上的活，你干不干啊？",
          DialogueId = 80110122,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1AE4",
          NextDialogue = 80110123,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1AE4"
        },
        [80110123] = {
          Content = "……还不如之前当狩月人的时候，虽然也不轻松，但好歹自在。",
          DialogueId = 80110123,
          GUID = "C88C1B0E",
          NextDialogue = 80110124,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1B0E"
        },
        [80110124] = {
          Content = "委托也不是件件都要刀头舔血，偶尔还能接到遛遛狗，猎猎鹿这样的好活计，甚至在干一票大的后，还能去“水仙平原”喝杯酒，暖暖胃。",
          DialogueId = 80110124,
          GUID = "C88C1B38",
          NextDialogue = 80110125,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1B38"
        },
        [80110125] = {
          Content = "你可以一个人，不跟人搭伙，不用费嘴皮子说服别人听你的计划，不用一边执行任务，一边照顾那些碍手碍脚的拖油瓶。",
          DialogueId = 80110125,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C1B62",
          NextDialogue = 80110126,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1B62"
        },
        [80110126] = {
          Content = "更重要的是，不用理会麻雀一样叽里呱啦聒噪的长官。",
          DialogueId = 80110126,
          GUID = "C88C1B8C",
          NextOptions = {
            [1] = 801101261
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1B8C"
        },
        [80110127] = {
          Content = "这样说长官算不算说错话？会不会被“电死”？",
          DialogueId = 80110127,
          GUID = "C88C1BB6",
          NextDialogue = 80110128,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1BB6"
        },
        [80110128] = {
          Content = "…………！！",
          DialogueId = 80110128,
          FacialId = {
            [1] = "93101:Shock01"
          },
          GUID = "C88C1BE0",
          NextDialogue = 80110129,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1BE0"
        },
        [80110129] = {
          Content = "当然会！我又不是那群贵族出身的家伙，跟皮糙肉厚的大秽兽似的，怎么电都电不死。这话传出去，我就不被电死，也得吃不了兜着走。",
          DialogueId = 80110129,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1C0A",
          NextDialogue = 80110130,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1C0A"
        },
        [80110130] = {
          Content = "敢说出去就一枪崩了你的脑壳，听到没？！",
          DialogueId = 80110130,
          GUID = "C88C1C34",
          NextOptions = {
            [1] = 801101301
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1C34"
        },
        [80110131] = {
          Content = "不过，你倒是让我觉得有些……意外。",
          DialogueId = 80110131,
          GUID = "C88C1C5E",
          NextDialogue = 80110132,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1C5E"
        },
        [80110132] = {
          Content = "我本以为琳恩作为海伯利亚的军官会更有一些——“信念感”？就是“荣耀”啦，“忠诚”啦……",
          DialogueId = 80110132,
          GUID = "C88C1C88",
          NextDialogue = 80110133,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1C88"
        },
        [80110133] = {
          Content = "嗤，这些骗骗手下那些新兵蛋子也就算了。我自己……",
          DialogueId = 80110133,
          GUID = "C88C1CB2",
          NextDialogue = 80110134,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1CB2"
        },
        [80110134] = {
          Content = "可能很多人会为了那些看不见抓不到的东西付出一切，但我不是。我拎得清自己为什么成为狩月人，又为什么加入军团。",
          DialogueId = 80110134,
          GUID = "C88C1CDC",
          NextDialogue = 80110135,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1CDC"
        },
        [80110135] = {
          Content = "……不过是为了一口饭吃，我从一开始就清楚得很。军团要我的力量办事，我要他们的薪饷，这就是个各取所需的买卖。",
          DialogueId = 80110135,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C1D06",
          NextDialogue = 80110136,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1D06"
        },
        [80110136] = {
          Content = "你说的荣耀啊信念啊什么的，那是一丁点儿都没有。",
          DialogueId = 80110136,
          GUID = "C88C1D30",
          NextOptions = {
            [1] = 801101361
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1D30"
        },
        [80110137] = {
          Content = "…………！！",
          DialogueId = 80110137,
          FacialId = {
            [1] = "93101:Shock01"
          },
          GUID = "C88C1D5A",
          NextDialogue = 80110138,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1D5A"
        },
        [80110138] = {
          Content = "*的，烦死了。我就不该喝这破酒，一喝就忍不住说些有的没的。",
          DialogueId = 80110138,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1D84",
          NextDialogue = 80110139,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1D84"
        },
        [80110139] = {
          Content = "走了，不喝了！不许乱讲啊！",
          DialogueId = 80110139,
          GUID = "C88C1DAE",
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1DAE"
        },
        [80110201] = {
          Camera = "127.060242,12.009277,131.847168,0.0,-0.799959,-137.39563,30.0,150.0,false,Manual,2.8",
          Content = "……再来一杯。",
          DialogueId = 80110201,
          GUID = "C88C27DA",
          LookAt = {
            [1] = "93101:p(18000P3)"
          },
          NextDialogue = 80110202,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C27DA"
        },
        [80110202] = {
          Content = "哎，你平常在冰湖城，都是怎么接活啊？还是在“水仙平原”吗？",
          DialogueId = 80110202,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C2804",
          NextOptions = {
            [1] = 801102021
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2804"
        },
        [80110203] = {
          Content = "这倒是和从前一点都没变。“水仙平原”的话，挺好的……至少卡米拉不会突然让你去杀人越货。",
          DialogueId = 80110203,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C282E",
          NextOptions = {
            [1] = 801102031
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C282E"
        },
        [80110204] = {
          Content = "哈，别看冰湖城地方挺偏的，比皇都还人才辈出，尤其是外围这种治安署懒得管的地方。不过别担心，你在卡米拉那儿干，别乱接私活，这些委托是碰不上的。",
          DialogueId = 80110204,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C2858",
          NextDialogue = 80110205,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2858"
        },
        [80110205] = {
          Content = "说起来，卡米拉现在怎么样了？还是和以前一样凶巴巴的吗？",
          DialogueId = 80110205,
          GUID = "C88C2882",
          NextOptions = {
            [1] = 801102051,
            [2] = 801102052
          },
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2882"
        },
        [80110206] = {
          Content = "那挺好的！唉，时间过那么快，卡米拉都变和善了，可惜我长官还是几年如一日地凶神恶煞。",
          DialogueId = 80110206,
          FacialId = {
            [1] = "93101:Happy01"
          },
          GUID = "C88C28AC",
          NextOptions = {
            [1] = 801102071
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C28AC"
        },
        [80110207] = {
          Content = "好吧，卡米拉也还是老样子啊……唉，和我长官一个样，明明是个大美人，却整天把自己搞得凶神恶煞的。",
          DialogueId = 80110207,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C28D6",
          NextOptions = {
            [1] = 801102071
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C28D6"
        },
        [80110208] = {
          Content = "名字……不能告诉你，说了会被扔到军团围墙上的电网电死。",
          DialogueId = 80110208,
          GUID = "C88C2900",
          NextDialogue = 80110209,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2900"
        },
        [80110209] = {
          Content = "她整天垮着一张脸，好像全军团上下都欠她很多钱一样。",
          DialogueId = 80110209,
          FacialId = {
            [1] = "93101:Sad02"
          },
          GUID = "C88C292A",
          NextOptions = {
            [1] = 801102091
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C292A"
        },
        [80110210] = {
          Content = "唉！她有一大堆奇奇怪怪的癖好，比如正经人谁不用枪啊，她非得甩她那带电的鞭子，说那玩意儿比枪顺手多了。",
          DialogueId = 80110210,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C2954",
          NextDialogue = 80110211,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2954"
        },
        [80110211] = {
          Content = "（你心里骤然沉了一下。这个描述让你想起了某个人，某个你正在寻找的人——西比尔。）",
          DialogueId = 80110211,
          GUID = "C88C297E",
          NextDialogue = 80110212,
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C297E"
        },
        [80110212] = {
          Content = "正经人想问题的时候都喜欢安静对吧，她整天抱着一段吵吵闹闹的录音听，还说这玩意儿听了就带劲，更好想问题。",
          DialogueId = 80110212,
          GUID = "C88C29A8",
          NextDialogue = 80110213,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C29A8"
        },
        [80110213] = {
          Content = "还在办公室养了几只乌鸦，她就不怕鸟粪刚好落到她写给陛——呸，写给她上司的报告上吗！",
          DialogueId = 80110213,
          GUID = "C88C29D2",
          NextDialogue = 80110214,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C29D2"
        },
        [80110214] = {
          Content = "还有还有，正经人去河边都是去散散心，吹吹风，看看风景对吧？就我长官，她去河边是为了看钓鱼的家伙空着手回去。她说压力大的时候看这个能缓解压力。",
          DialogueId = 80110214,
          GUID = "C88C29FC",
          NextDialogue = 80110215,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C29FC"
        },
        [80110215] = {
          Content = "怎么会有这样的人啊！",
          DialogueId = 80110215,
          GUID = "C88C2A26",
          NextOptions = {
            [1] = 801102151
          },
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2A26"
        },
        [80110216] = {
          Content = "怪人一个，真见到她你就不有趣了。刚才说的是大长官，还有个小长官，比大长官还他*怪。",
          DialogueId = 80110216,
          FacialId = {
            [1] = "93101:Sad02"
          },
          GUID = "C88C2A50",
          NextDialogue = 80110217,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2A50"
        },
        [80110217] = {
          Content = "说话拿腔捏调的，以为自己挺优雅，但我怎么听都觉得像条摇摆的鹅。",
          DialogueId = 80110217,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C2A7A",
          NextDialogue = 80110218,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2A7A"
        },
        [80110218] = {
          Content = "整天把什么高效节能挂在嘴边，嗨，实际上就是在给偷懒找借口，他那点心思谁不知道啊。",
          DialogueId = 80110218,
          GUID = "C88C2AA4",
          NextDialogue = 80110219,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2AA4"
        },
        [80110219] = {
          Content = "不过这家伙倒是聪明，经常一边偷懒，一边把事儿给办成了，还让人挑不出错处。",
          DialogueId = 80110219,
          GUID = "C88C2ACE",
          NextDialogue = 80110220,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2ACE"
        },
        [80110220] = {
          Content = "前段时间就是他，通过一丁点儿蛛丝马迹就猜出来了大长官找了十几年的宝贝藏在哪儿。就是中间……生了点波折……",
          DialogueId = 80110220,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C2AF8",
          NextDialogue = 80110221,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2AF8"
        },
        [80110221] = {
          Content = "（如果没猜错，琳恩说的“宝贝”……很可能就是贝蕾妮卡。）",
          DialogueId = 80110221,
          GUID = "C88C2B22",
          NextOptions = {
            [1] = 801102211
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2B22"
        },
        [80110222] = {
          Content = "你别问我啊……他俩去找的，这事是机密，我哪知道。",
          DialogueId = 80110222,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C2B4C",
          NextDialogue = 80110223,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2B4C"
        },
        [80110223] = {
          Content = "…………",
          DialogueId = 80110223,
          GUID = "C88C2B76",
          NextDialogue = 80110224,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2B76"
        },
        [80110224] = {
          Content = "坏了，我今天好像是真的说了太多不该说的……唉，都怪这破酒！你不会在酒里加了吐真剂什么的吧？",
          DialogueId = 80110224,
          FacialId = {
            [1] = "93101:Shock01"
