          GUID = "C88C2BA0",
          NextDialogue = 80110225,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2BA0"
        },
        [80110225] = {
          Content = "走了走了。唉——还好我在迪斯玛尼亚不喝酒，要不哪天说不定就被长官用鞭子一下子给电……不对这个不能再说了……",
          DialogueId = 80110225,
          FacialId = {
            [1] = "93101:None"
