        [80120212] = {
          Camera = "-409.604431,-6.535156,126.660339,0.000048,-2.997824,66.607025,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "“你好啊，很久以后的可萨克，你现在开心吗？还是不太高兴？我要和你说，我即将做一件很冒险的事情：",
          DialogueId = 80120212,
          FacialId = {
            [1] = "790019:None"
          },
          FinalCamera = "-407.011719,-7.655762,126.660339,0.000048,-2.997797,66.607208,35.000008,100000.0,false,DoNotOverride,2.8",
