        [80120219] = {
          Camera = "-318.570557,225.146973,124.440643,0.000003,-1.999934,-117.594925,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "哎，这个很久以前的可萨克，其实还是一个好人嘛。",
          DialogueId = 80120219,
          FacialId = {
            [1] = "790019:None"
          },
          GUID = "C892936E",
          NextDialogue = 80120222,
          SpeakNpcId = 790019,
          TalkActionId = {
            [1] = "790019:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C892936E"
        },
        [80120220] = {
          Camera = "-318.570557,225.146973,124.440643,0.000003,-1.999934,-117.594925,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "唔……确实有可能，他对所有乐谱都不屑一顾，却偏偏很确定最重要的宝贝“早就放在了它该放的位置”……",
          DialogueId = 80120220,
          FacialId = {
            [1] = "790019:None"
          },
          GUID = "C8929398",
          LookAt = {
