          VoiceName = "voice/$Locale$/inv/Maer/002/C89293C2"
        },
        [80120222] = {
          Camera = "-252.260193,281.916748,126.221512,0.000009,-3.999636,-119.588837,35.0,234.284531,false,Manual,5.0",
          Content = "歌词写得真好……哎，也不知道这首歌唱出来到底是什么样的。",
