            [2] = "790036:Explain02_Start"
          },
          TurnTo = {
            [1] = "790042:n(790041)"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6A42"
        },
        [80140254] = {
          Camera = "-99.941406,228.310547,146.640625,0.000004,0.0,-78.789078,35.000011,100000.0,false,DoNotOverride,2.8",
          Content = "好哇，好哇！你这家伙，真是个好“演员”！看你打扮得衣冠楚楚，我才好心请你进来，听你说了这许多废话，没想到你竟是个骗子！",
          DialogueId = 80140254,
          FacialId = {
            [1] = "790041:CM_Angry01"
          },
          GUID = "C89F6A6C",
          NextDialogue = 80140255,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790041},AnimationId{"Confident_Start"},Duration{3},_click{false}},
PlayAnimation{ActorId{790041},AnimationId{"Agree"},Duration{1},_click{false}}
}]],
          SpeakNpcId = 790041,
          TalkActionId = {
            [1] = "790036:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6A6C"
        },
        [80140255] = {
          Camera = "-110.15625,89.980957,151.796875,0.000004,0.0,59.005974,35.000011,100000.0,false,DoNotOverride,2.8",
          Content = "不，我没有骗您！",
          DialogueId = 80140255,
          FacialId = {
            [1] = "790036:Shock01"
          },
          GUID = "C89F6A96",
          NextDialogue = 80140256,
          SpeakNpcId = 790043,
          TalkActionId = {
            [1] = "790036:Disagree",
            [2] = "790041:Confident_End"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6A96"
        },
        [80140256] = {
          Camera = "-171.984375,506.293945,146.203125,0.000005,-1.800076,-72.188232,38.476471,100000.0,false,DoNotOverride,2.8",
          Content = "胡扯！卡戎女人怎配为我生儿育女！你——你到底是什么人，打的什么算盘？",
          DialogueId = 80140256,
          GUID = "C89F6AC0",
          NextDialogue = 80140257,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790041},AnimationId{"Angry01_Start"},Duration{2},_click{false}},
PlayAnimation{ActorId{790041},AnimationId{"Angry01_End"},Duration{1},_click{false}}
}]],
          SpeakNpcId = 790041,
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6AC0"
        },
        [80140257] = {
          Content = "我知道了……你准是《冰湖城早报》那个老秃头派来的！我的对头给他塞了钱，他就总是杜撰那些捕风捉影的见鬼丑闻。",
          DialogueId = 80140257,
          GUID = "C89F6AEA",
          NextDialogue = 80140258,
          Scripts = [[
SEQ{
TurnTo{_click{false},TurnToDescription{"790041:p(100)"}},
PlayAnimation{_delay{1},ActorId{790041},AnimationId{"Confident_Start"},Duration{3},_click{false}}
}]],
          SpeakNpcId = 790041,
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6AEA"
        },
        [80140258] = {
          Camera = "-125.214844,146.510742,141.648438,0.00002,6.999755,41.210266,35.000011,133.743912,false,Manual,2.8",
          Content = "我——我不是……我说的都是真话！您刚才不是还说——说您记得我母亲的事，记得你们有多么相爱吗？",
          DialogueId = 80140258,
          FacialId = {
            [1] = "790036:Sad01"
          },
          GUID = "C89F6B14",
          NextDialogue = 80140259,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790036},AnimationId{"Disagree"},Duration{1},_click{false}},
PlayAnimation{_delay{1},ActorId{790036},AnimationId{"Talk02_Start"},Duration{2},_click{false}}
}]],
          SpeakNpcId = 790043,
          TalkActionId = {
            [1] = "790041:Confident_End"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6B14"
        },
        [80140259] = {
          Camera = "-121.521484,456.680664,136.171875,0.0,0.0,-75.5924,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "混账东西，二十年前我莫里斯交往的女人那么多，谁知道你说的哪个？！",
          DialogueId = 80140259,
          GUID = "C89F6B3E",
          NextDialogue = 80140260,
          SpeakNpcId = 790041,
          TalkActionId = {
            [1] = "790036:Talk02_End"
          },
          TurnTo = {
            [1] = "790041:p(-100)"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6B3E"
        },
        [80140260] = {
          Camera = "-516.966797,271.29248,136.0,0.0,0.0,-17.59621,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "咳。老爷，演出快要开始了。",
          DialogueId = 80140260,
          GUID = "C89F6B68",
          NextDialogue = 80140261,
          SpeakNpcId = 790042,
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6B68"
        },
        [80140261] = {
          Camera = "-121.521484,456.680664,136.171875,0.0,0.0,-75.5924,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "……哼。这位不知从哪儿冒出来的先生，我可没说过那些胡话，有管家为证，想必是您听错了。",
          DialogueId = 80140261,
          FacialId = {
            [1] = "790036:None"
          },
          GUID = "C89F6B92",
          NextDialogue = 80140262,
          Scripts = "PlayAnimation{_delay{2},ActorId{790041},AnimationId{\"Disagree\"},Duration{1},_click{false}}",
          SpeakNpcId = 790041,
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6B92"
        },
        [80140262] = {
          Camera = "-130.255859,176.895508,152.324219,0.000013,0.00002,-64.789436,35.000011,100000.0,false,DoNotOverride,2.8",
          Content = "我听闻卡戎之民出现听觉失灵是个不祥的征兆，您要多多关心自己的身体才是。现在，请您离开我的包厢，否则我就要叫安保人员了。",
          DialogueId = 80140262,
          GUID = "C89F6BBC",
          NextDialogue = 80140263,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790041},AnimationId{"Think_Start"},Duration{3},_click{false}},
PlayAnimation{_delay{2},ActorId{790041},AnimationId{"Think_End"},Duration{1},_click{false}}
}]],
          SpeakNpcId = 790041,
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6BBC"
        },
        [80140263] = {
          Camera = "-338.359375,215.333984,136.617188,0.000013,-0.80002,-26.987488,35.000011,100000.0,false,DoNotOverride,2.8",
          Content = "请恕我不送，眼下我得抓紧时间教育一下我家的仆人，让他们以后别再和来路不明的东西搭话。",
          DialogueId = 80140263,
          FacialId = {
            [1] = "790042:CM_Sad01"
          },
          GUID = "C89F6BE6",
          NextDialogue = 80140264,
          SpeakNpcId = 790041,
          TurnTo = {
            [1] = "790041:n(790042)"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6BE6"
        },
        [80140264] = {
          Camera = "-201.84375,-98.977539,157.707031,0.000015,-3.000024,56.802822,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "“东西”？",
          DialogueId = 80140264,
          FacialId = {
            [1] = "790036:Shock01"
          },
          FinalCamera = "-235.755859,-150.816406,160.089844,0.000015,-3.000024,56.802822,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F6C10",
          NextDialogue = 80140265,
          SpeakNpcId = 790043,
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6C10"
        },
        [80140265] = {
          Content = "……我明白了。很抱歉占用了您的时间，我这就离开。",
          DialogueId = 80140265,
          FacialId = {
            [1] = "790036:Disappoint01"
          },
