          SpeakNpcId = 790043,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6C64"
        },
        [80140267] = {
          Content = "真是一出滑稽戏。",
          DialogueId = 80140267,
          GUID = "C89F6C8E",
          SpeakNpcId = 790043,
          TalkActionId = {
            [1] = "790043:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6C8E"
        },
        [80140268] = {
          Content = "我是绝望的赌徒，用力掷出最后的筹码。",
          DialogueId = 80140268,
          Duration = 4,
          GUID = "C89F6CB8",
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6CB8"
        },
        [80140269] = {
          Content = "然后，一无所有。",
          DialogueId = 80140269,
          Duration = 3,
          GUID = "C89F6CE2",
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6CE2"
        },
        [80140301] = {
          Content = "你是谁？",
          DialogueId = 80140301,
          Duration = 3,
          GUID = "C89F7222",
          NextDialogue = 80140302,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7222"
        },
        [80140302] = {
          Content = "你想说什么？",
          DialogueId = 80140302,
          Duration = 3,
          GUID = "C89F724C",
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F724C"
        },
        [80140303] = {
