          SpeakNpcId = 790036,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7AD4"
        },
        [80140355] = {
          Content = "（啊……我明白了。）",
          DialogueId = 80140355,
          GUID = "C89F7AFE",
          NextDialogue = 80140356,
          SpeakNpcId = 790036,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7AFE"
        },
        [80140356] = {
          Content = "（你——也变成怪物了。）",
          DialogueId = 80140356,
          GUID = "C89F7B28",
          IsBlack = 1,
          SpeakNpcId = 790036,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7B28"
        },
        [80140357] = {
          Content = "我是凶残的野兽，奉命撕碎所有的猎物。",
          DialogueId = 80140357,
          Duration = 4,
          GUID = "C89F7B52",
          NextDialogue = 80140358,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7B52"
        },
        [80140358] = {
          Content = "然后，埋葬自己。",
          DialogueId = 80140358,
          Duration = 3,
          GUID = "C89F7B7C",
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7B7C"
        },
        [80140401] = {
          Content = "你是谁？",
          DialogueId = 80140401,
          Duration = 3,
          GUID = "C89F828A",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F828A"
        },
        [80140402] = {
