          TalkActionId = {
            [1] = "790027:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F835C"
        },
        [80140407] = {
          Camera = "226.189453,553.110352,113.588379,0.000044,-4.199979,-87.397324,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "不是吧，这才几点？别那么急嘛，陪我对一会儿戏！今天老师教的那段我还背得不怎么熟练。",
          DialogueId = 80140407,
          FacialId = {
            [1] = "790027:CM_Smile01"
