          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8386"
        },
        [80140408] = {
          Camera = "602.087891,-88.831787,85.242676,0.000014,-0.400024,133.199921,35.000008,525.224243,false,Manual,2.8",
          Content = "又来……？啊——好好好，陪你练就是了，别动手啊！",
