        },
        [80140409] = {
          Content = "（他们两个真是一点也没变。）",
          DialogueId = 80140409,
          GUID = "C89F83DA",
          NextDialogue = 80140410,
          SpeakNpcId = 790029,
          SpeakNpcName = "UI_Npc_Name_Tuosi",
          TalkActionId = {
