        [80140410] = {
          Camera = "136.138672,760.375244,255.158691,0.000026,-19.999907,-75.596756,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "说起来，下个月的演出剧目定了吗？",
          DialogueId = 80140410,
          FinalCamera = "-128.058105,642.81958,243.39624,0.000037,-18.99983,-43.396786,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F8404",
          NextDialogue = 80140411,
          SpeakNpcId = 790026,
          TalkActionId = {
            [1] = "790026:Think_Start"
          },
          ToFinalCameraBlendTime = 35,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8404"
        },
        [80140411] = {
          Content = "团长说是《雨日》。",
          DialogueId = 80140411,
          GUID = "C89F842E",
          NextDialogue = 80140412,
          SpeakNpcId = 790027,
          TalkActionId = {
            [1] = "790027:Explain01_Start",
            [2] = "790026:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F842E"
        },
        [80140412] = {
          Content = "《雨日》的人气也就一般般吧？靠它出人头地可不容易。唉，要是能再演《雪国的孩子》就好了。那部剧在冰湖城可受欢迎了……",
          DialogueId = 80140412,
          GUID = "C89F8458",
          NextDialogue = 80140413,
          SpeakNpcId = 790026,
          TalkActionId = {
            [1] = "790026:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8458"
        },
        [80140413] = {
          Content = "就是啊！我也好想再演一次无名的妖精，那可是我最得意的角色，虽然唱段又多又难，但完整演下来的感觉真是太棒了。",
          DialogueId = 80140413,
          GUID = "C89F8482",
          NextDialogue = 80140414,
          Scripts = [[
