          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BC14"
        },
        [80150115] = {
          Content = "城里所有的杂事基本上卫戍部队都要管。城市巡逻、处理秽兽、居民纠纷、清理下水道……有时候也需要协助军团上层的机密事务。",
          DialogueId = 80150115,
          GUID = "C8A5BC3E",
          NextOptions = {
            [1] = 801501151,
            [2] = 801501152
