          SpeakNpcId = 790008,
          TalkActionId = {
            [1] = "790008:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5D018"
        },
        [80150237] = {
          Content = "我想你应该好好享受“停下来”的时间。也许，你就会在不经意间发现真正想做的事，自然而然地明白前进的意义——不是别人给的，而是自己找到的。",
          DialogueId = 80150237,
          GUID = "C8A5D042",
          NextDialogue = 80150238,
          SpeakNpcId = 790008,
          TalkActionId = {
            [1] = "790008:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5D042"
        },
        [80150238] = {
