          Camera = "163.349609,102.542969,151.724365,0.000122,-8.39728,-154.012268,30.000008,303.919434,false,Manual,2.099485",
          Content = "什么乱七八糟的……",
          DialogueId = 80180342,
          FinalCamera = "166.277344,96.828125,151.724365,0.000123,-8.39728,-157.012573,30.000008,303.919434,false,Manual,2.099485",
          GUID = "C8B91B5C",
          NextDialogue = 80180343,
          SpeakNpcId = 110025,
          SpeakNpcName = "UI_Npc_Name_Shibing4",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91B5C"
        },
        [80180343] = {
          Camera = "-173.388672,-447.8125,33.189331,0.00006,9.004928,71.363441,40.0,1144.406128,false,DoNotOverride,1.422013",
          Content = "抱歉……自顾自说起来了。你不用操心别的，只要记住，如果你受伤了，我也一定不会弃你不顾就好。",
          DialogueId = 80180343,
          FinalCamera = "-154.09375,-454.523438,33.189331,0.000057,9.004921,73.362991,40.0,1144.406128,false,DoNotOverride,1.422013",
          GUID = "C8B91B86",
          NextDialogue = 80180344,
          SpeakNpcId = 790045,
          TalkActionId = {
            [1] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91B86"
        },
        [80180344] = {
          Camera = "62.640625,-18.921875,119.119995,0.000043,3.604052,-161.235825,40.0,1144.406128,false,DoNotOverride,1.422013",
          Content = "……那你也记住，别把自己的生命看得那么轻。活下去的人，能做的事远比死去的多。",
          DialogueId = 80180344,
          FinalCamera = "65.09375,-25.960938,119.119995,0.000042,3.604052,-162.835632,40.0,1144.406128,false,DoNotOverride,1.422013",
          GUID = "C8B91BB0",
          NextDialogue = 80180345,
          SpeakNpcId = 110025,
          SpeakNpcName = "UI_Npc_Name_Shibing4",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91BB0"
        },
        [80180345] = {
          Camera = "65.09375,-25.960938,119.119995,0.000042,3.604052,-162.835632,40.0,1144.406128,false,DoNotOverride,1.422013",
          Content = "“背负着战友的意志活下去是和牺牲同样伟大的事”——这是阿瓦尔长官告诉过我们的。",
          DialogueId = 80180345,
          GUID = "C8B91BDA",
          NextDialogue = 80180346,
          SpeakNpcId = 110025,
          SpeakNpcName = "UI_Npc_Name_Shibing4",
          TalkActionId = {
            [1] = "790045:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91BDA"
        },
        [80180346] = {
          Camera = "-150.710938,-191.480469,126.76355,0.000074,-0.195801,55.361076,45.0,362.249939,false,Manual,3.206755",
          Content = "长官……他说了这种话吗……",
          DialogueId = 80180346,
          FinalCamera = "-145.195312,-195.398438,126.76355,0.000074,-0.195801,57.360607,45.0,362.249939,false,Manual,3.206755",
          GUID = "C8B91C04",
          NextDialogue = 80180347,
          SpeakNpcId = 790045,
          TalkActionId = {
            [1] = "790045:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91C04"
        },
        [80180347] = {
          Camera = "-23.109375,-128.339844,101.804077,0.0001,7.60392,62.159901,45.0,242.334976,false,Manual,3.206755",
          Content = "好，我会记住的。",
          DialogueId = 80180347,
          FinalCamera = "-19.283203,-130.453125,101.804077,0.000098,7.60392,63.560059,45.0,254.569183,false,Manual,3.206755",
          GUID = "C8B91C2E",
          NextDialogue = 80180348,
          SpeakNpcId = 790045,
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91C2E"
        },
        [80180348] = {
          Camera = "-19.283203,-130.453125,101.804077,0.000098,7.60392,63.560059,45.0,254.569183,false,Manual,3.206755",
          Content = "差不多了，我该出发了。",
          DialogueId = 80180348,
          GUID = "C8B91C58",
          NextDialogue = 80180349,
          SpeakNpcId = 790045,
          TalkActionId = {
            [1] = "790045:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91C58"
        },
        [80180349] = {
          Camera = "1023.142578,-512.480469,-28.856567,0.000109,7.203766,151.359207,45.0,1202.78186,false,Manual,2.168443",
          Content = "去哪儿？",
          DialogueId = 80180349,
          FinalCamera = "1013.601562,-529.96875,-28.856567,0.000109,7.203766,151.359207,45.0,1202.78186,false,Manual,2.168443",
          GUID = "C8B91C82",
          NextDialogue = 80180350,
          SpeakNpcId = 110025,
          SpeakNpcName = "UI_Npc_Name_Shibing4",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91C82"
        },
        [80180350] = {
          Camera = "1013.601562,-529.96875,-28.856567,0.000109,7.203766,151.359207,45.0,1202.78186,false,Manual,2.168443",
          Content = "去找找有没有应急物资，还有……",
          DialogueId = 80180350,
          GUID = "C8B91CAC",
          NextDialogue = 80180351,
          SpeakNpcId = 790045,
          TalkActionId = {
            [1] = "790045:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91CAC"
        },
        [80180351] = {
          Camera = "-128.251953,-146.082031,134.427856,0.000144,-1.196642,52.959221,45.0,317.18219,false,Manual,6.360716",
          Content = "去找{nickname2}队长，确认{性别2：他|她}是否安全。",
          DialogueId = 80180351,
          FinalCamera = "-126.076172,-147.757812,134.427856,0.000144,-1.196642,53.559261,45.0,317.18219,false,Manual,6.360716",
          GUID = "C8B91CD6",
          SpeakNpcId = 790045,
          TalkActionId = {
            [1] = "790045:Talk01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91CD6"
        },
        [80180352] = {
          Camera = "-14.550781,-91.125,107.247437,0.000139,8.803205,58.55764,45.0,317.18219,false,Manual,6.360716",
          Content = "（穿越遍布尸骸的路，我听到自己沉重的喘息，摸到自己的心跳。我从未感觉过自己如此渺小。）",
          DialogueId = 80180352,
          FinalCamera = "-9.892578,-94.234375,107.247437,0.000138,8.803205,60.757439,45.0,317.18219,false,Manual,6.360716",
          GUID = "C8B91D00",
          IsBlack = 1,
          NextDialogue = 80180353,
          SpeakNpcId = 790045,
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91D00"
        },
        [80180353] = {
          Camera = "-9.892578,-94.234375,107.247437,0.000138,8.803205,60.757439,45.0,317.18219,false,Manual,6.360716",
          Content = "（我曾战胜过同窗，战胜过实验，战胜过疼痛。我一度以为自己无所不能；但如今我已知晓，我无法战胜的东西，远比我可以战胜的多得多。）",
          DialogueId = 80180353,
          GUID = "C8B91D2A",
          IsBlack = 1,
          NextDialogue = 80180354,
          SpeakNpcId = 790045,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91D2A"
        },
        [80180354] = {
          Camera = "47.957031,-1250.3125,16.771729,0.000155,3.202962,92.956001,45.0,317.18219,false,Manual,6.360716",
          Content = "（但无论前路是什么，我希望这场战役结束后，无论是活着的我，还是我的灵魂，在归去时，可以把这句话带给西比尔·梅森——）",
          DialogueId = 80180354,
          FinalCamera = "76.232422,-1248.960938,16.771729,0.000158,3.202962,93.755997,45.0,317.18219,false,Manual,6.360716",
          GUID = "C8B91D54",
          IsBlack = 1,
          SpeakNpcId = 790045,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91D54"
        },
        [80180355] = {
          Camera = "76.232422,-1248.960938,16.771729,0.000158,3.202962,93.755997,45.0,317.18219,false,Manual,6.360716",
          Content = "（<H>达芙涅·塞奥多尔理想仍存。</>）",
          DialogueId = 80180355,
          GUID = "C8B91D7E",
          IsBlack = 1,
          SpeakNpcId = 790045,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91D7E"
        },
        [80190001] = {
          Content = "白吃白喝那我就不客气啦，有便宜不占纯傻瓜嘛。",
          DialogueId = 80190001,
          GUID = "C8BF4C0A"
        },
        [80190101] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          DialogueId = 80190101,
          Duration = 3,
          GUID = "C8BF5C72",
          NextDialogue = 80190102,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190102] = {
          Content = "你一个人住这么大宅子？看着还有模有样，居然还整理出了一个调酒台。",
          DialogueId = 80190102,
          FacialId = {
            [1] = "95102:Shock01"
          },
          GUID = "C8BF5C9C",
          NextDialogue = 80190103,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190103] = {
          Content = "挺好的，多请一些朋友来吧，这样一来，你也能在冰湖城拥有自己的人脉。",
          DialogueId = 80190103,
          FacialId = {
            [1] = "95102:Smile01"
          },
          GUID = "C8BF5CC6",
          NextDialogue = 80190104,
          SpeakNpcId = 95102
        },
        [80190104] = {
          Content = "那么，说吧，又有啥事要我帮忙。太麻烦就算了啊，我这几天手上还有个大活呢。",
          DialogueId = 80190104,
          GUID = "C8BF5CF0",
          NextOptions = {
            [1] = 801901041,
            [2] = 801901042
          },
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190105] = {
          Content = "噫……我鸡皮疙瘩都起来了。这话我勉强能受得了，要是你请其他人来喝酒也是这个说辞，人家不一定吃得消啊。",
          DialogueId = 80190105,
          GUID = "C8BF5D1A",
          NextDialogue = 80190107,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190106] = {
          Content = "行，那么我就不客气了，让我来尝一尝你的手艺怎么样。",
          DialogueId = 80190106,
          GUID = "C8BF5D44",
          NextDialogue = 80190107,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190107] = {
          DialogueId = 80190107,
          Duration = 3,
          GUID = "C8BF5D6E",
          NextDialogue = 80190108,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190108] = {
          Content = "啧啧，嗯，甜中带酸，特意做成了温酒，和“水仙平原”的水准差不多，但是也有自己的风格。",
          DialogueId = 80190108,
          FacialId = {
            [1] = "95102:Smile01"
          },
          GUID = "C8BF5D98",
          NextDialogue = 80190109,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190109] = {
          Content = "这一杯挺麻烦的吧。说实话水准超过我的预期了，实话说煮杯热水我都能乐呵地喝下去，没必要费这么大劲。",
          DialogueId = 80190109,
          GUID = "C8BF5DC2",
          NextDialogue = 80190110,
          SpeakNpcId = 95102
        },
        [80190110] = {
          Content = "不过，看你这么兴致勃勃，啊……我懂了，攒了点钱就得挥霍一下，请客喝酒，添置新物。用最近流行的话说，就叫“花钱买乐子”？",
          DialogueId = 80190110,
          GUID = "C8BF5DEC",
          NextOptions = {
            [1] = 801901101,
            [2] = 801901102
          },
          SpeakNpcId = 95102
        },
        [80190111] = {
          Content = "你请人来喝上一杯不就是为了说话？这说明我比其他人都要了解你在想什么，比其他人都要赏脸。",
          DialogueId = 80190111,
          GUID = "C8BF5E16",
          NextDialogue = 80190113,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk01_Start"
          }
        },
        [80190112] = {
          Content = "别别别，我错了我错了，你花钱你是老大，要不你打我一拳消消气。",
          DialogueId = 80190112,
          GUID = "C8BF5E40",
          NextDialogue = 80190113,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk01_Start"
          }
        },
        [80190113] = {
          Content = "不过说笑归说笑，作为半个过来人，我也得提醒你一下，并不是每个人都值得你视为“朋友”请客喝酒的。",
          DialogueId = 80190113,
          GUID = "C8BF5E6A",
          NextDialogue = 80190114,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk01_End"
          }
        },
        [80190114] = {
          Content = "尤其在冰湖城这个地界，总有那么些心术不正的人，会盯上你现在拥有的东西，主动来做你的酒肉之交。",
          DialogueId = 80190114,
          GUID = "C8BF5E94",
          NextDialogue = 80190115,
          SpeakNpcId = 95102
        },
        [80190115] = {
          Content = "他们表面上挂着笑，变着法哄你开心，恨不得把你捧到天上去。但真遇到事儿的时候啊，指望他们还不如指望路边的一条狗。",
          DialogueId = 80190115,
          GUID = "C8BF5EBE",
          NextOptions = {
            [1] = 801901151
          },
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190116] = {
          Content = "啊对的对的对的，我奥特赛德就是你身边最大的那一号狐朋狗友，有好处的时候不管多远我闻着味儿都能找过来。",
          DialogueId = 80190116,
          GUID = "C8BF5EE8",
          NextDialogue = 80190117,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_AgreeHead"
          }
        },
        [80190117] = {
          Content = "其他人要跟我抢这个名号，也得先掂量掂量自己的斤两。他们要想从你这吃到好处，那也得等本大爷“吃饱喝足”先。",
          DialogueId = 80190117,
          GUID = "C8BF5F12",
          NextOptions = {
            [1] = 801901171,
            [2] = 801901172
          },
          SpeakNpcId = 95102
        },
        [80190118] = {
          Content = "哎，别啊，我还没待够呢。",
          DialogueId = 80190118,
          GUID = "C8BF5F3C",
          NextDialogue = 80190120,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190119] = {
          Content = "哦？是怎么回事呢？我可不知道呀。",
          DialogueId = 80190119,
          GUID = "C8BF5F66",
          NextDialogue = 80190120,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190120] = {
          Content = "酒味道不错，再给我来一杯。喝完这口我就去接着忙活了。",
          DialogueId = 80190120,
          GUID = "C8BF5F90",
          SpeakNpcId = 95102
        },
        [80190201] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          Content = "嗨呀，迟到了半个钟头。为表歉意，哪怕你今天的酒味道像鲱鱼罐头，我也会一口喝下！",
          DialogueId = 80190201,
          FacialId = {
            [1] = "95102:Ahaha01"
          },
          GUID = "C8BF6CDA",
          NextOptions = {
            [1] = 801902011,
            [2] = 801902012
          },
          SpeakNpcId = 95102
        },
        [80190202] = {
          Content = "哈哈，怎么一下就看穿了。",
          DialogueId = 80190202,
          FacialId = {
            [1] = "95102:Smile02"
          },
          GUID = "C8BF6D04",
          NextDialogue = 80190203,
          SpeakNpcId = 95102
        },
        [80190203] = {
          Content = "前几天跟你说的那个大活，记得吧？今天跟威尔斯刚弄完，所以多花了点时间。",
          DialogueId = 80190203,
          FacialId = {
            [1] = "95102:None"
          },
          GUID = "C8BF6D2E",
          NextDialogue = 80190204,
          SpeakNpcId = 95102
        },
        [80190204] = {
          Content = "委托内容本身不麻烦，委托牵连到的家伙很麻烦。",
          DialogueId = 80190204,
          GUID = "C8BF6D58",
          NextOptions = {
            [1] = 801902041
          },
          SpeakNpcId = 95102
        },
        [80190205] = {
          Content = "不是他们。只要你符合规矩，会察言观色，不违背帝国利益，总有很多办法可以规避军团的麻烦。",
          DialogueId = 80190205,
          GUID = "C8BF6D82",
          NextDialogue = 80190206,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_DisagreeHead"
          }
        },
        [80190206] = {
          Content = "他们就像一把剑，危险致命却有迹可循。",
          DialogueId = 80190206,
          GUID = "C8BF6DAC",
          NextDialogue = 80190207,
          SpeakNpcId = 95102
        },
        [80190207] = {
          Content = "但有一群人比他们更加暴力且毫无章法，就像一颗藏在暗处的炸弹——",
          DialogueId = 80190207,
          GUID = "C8BF6DD6",
          NextDialogue = 80190208,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190208] = {
          Content = "神弃者同盟，那个不要命的组织。跟他们扯上关系的事都会变得无比麻烦。",
          DialogueId = 80190208,
          GUID = "C8BF6E00",
          NextDialogue = 80190209,
          SpeakNpcId = 95102
        },
        [80190209] = {
          Content = "比如这次，本来只是个普普通通的送货委托，但威尔斯觉得货的重量不对，偷偷凿了个洞一看，里面装满了神弃者同盟的违规武器。",
          DialogueId = 80190209,
          GUID = "C8BF6E2A",
          NextDialogue = 80190210,
          SpeakNpcId = 95102
        },
        [80190210] = {
          Content = "这要是光明正大走大门，怕不是被门口的卫兵当场给毙了。",
          DialogueId = 80190210,
          GUID = "C8BF6E54",
          NextDialogue = 80190211,
          SpeakNpcId = 95102
        },
        [80190211] = {
          Content = "但这应该正是他们想要的。有可能是他们想要几具狩月人的尸体，也可能是他们想要一场骚乱，趁乱进入冰湖城。",
          DialogueId = 80190211,
          GUID = "C8BF6E7E",
          NextDialogue = 80190212,
          SpeakNpcId = 95102
        },
        [80190212] = {
          Content = "也有可能只是他们想要通过这种方式，向他们的追随者宣扬索拉是如何残忍对待卡戎的。",
          DialogueId = 80190212,
          GUID = "C8BF6EA8",
          NextDialogue = 80190213,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190213] = {
          Content = "完全不可理喻，对吧？总之，一般人根本无法想象他们的行事手段和目的。",
          DialogueId = 80190213,
          FacialId = {
            [1] = "95102:Angry01"
          },
          GUID = "C8BF6ED2",
          NextDialogue = 80190214,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk02_Start"
          }
        },
        [80190214] = {
          Content = "最后我们只能想办法把这批武器弄到下水道里，顺着排水口运进城，完成了他们表面上的送货委托。",
          DialogueId = 80190214,
          GUID = "C8BF6EFC",
          NextDialogue = 80190215,
          SpeakNpcId = 95102
        },
        [80190215] = {
          Content = "听我说可能觉得还挺轻松，实际上为了这事，我跟威尔斯几天都没合眼了。",
          DialogueId = 80190215,
          GUID = "C8BF6F26",
          NextOptions = {
            [1] = 801902151,
            [2] = 801902152
          },
          SpeakNpcId = 95102
        },
        [80190216] = {
          Content = "两码事两码事，威尔斯那边再忙，这边也确实是迟到了。",
          DialogueId = 80190216,
          GUID = "C8BF6F50",
          NextDialogue = 80190218,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk02_End"
          }
        },
        [80190217] = {
          Content = "两码事两码事，酒肉朋友就是这样，有酒喝，那躺在棺材里也要爬出来喝一口。",
          DialogueId = 80190217,
          GUID = "C8BF6F7A",
          NextDialogue = 80190218,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk02_End"
          }
        },
        [80190218] = {
          DialogueId = 80190218,
          Duration = 3,
          GUID = "C8BF6FA4",
          NextDialogue = 80190219,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190219] = {
          Content = "但我现在确实得回去睡觉了。不过临走之前还是得和你说一句：为了你和关心你的人着想，少跟现在的神弃者同盟接触。",
          DialogueId = 80190219,
          GUID = "C8BF6FCE",
          NextOptions = {
            [1] = 801902191
          },
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190220] = {
          Content = "……就跟大多数人一样，看到危险，离远一点，仅此而已。",
          DialogueId = 80190220,
          FacialId = {
            [1] = "95102:Sad01"
          },
          GUID = "C8BF6FF8",
          NextDialogue = 80190221,
          SpeakNpcId = 95102
        },
        [80190221] = {
          Content = "这是我挣扎在暴力机器相互撕咬的夹缝中这么久，总结出的宝贵经验——绝对，绝对，绝对不要靠近神弃者同盟。",
          DialogueId = 80190221,
          GUID = "C8BF7022",
          NextDialogue = 80190222,
          SpeakNpcId = 95102
        },
        [80190222] = {
          Content = "这不是酒局上的胡话……而是关乎性命的建议。",
          DialogueId = 80190222,
          GUID = "C8BF704C",
          SpeakNpcId = 95102
        },
        [80190301] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          Content = "奥特塞德如期赴约，但是喝了一口酒后便一直没有了声响。",
          DialogueId = 80190301,
          Duration = 3,
          FacialId = {
            [1] = "95102:Unhappy02"
          },
          GUID = "C8BF7D42",
          NextDialogue = 80190302,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190302] = {
          Content = "……",
          DialogueId = 80190302,
          GUID = "C8BF7D6C",
          NextDialogue = 80190303,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190303] = {
          Content = "…………",
          DialogueId = 80190303,
          GUID = "C8BF7D96",
          NextOptions = {
            [1] = 801903031,
            [2] = 801903032
          },
          SpeakNpcId = 95102
        },
        [80190304] = {
          Content = "……",
          DialogueId = 80190304,
          GUID = "C8BF7DC0",
          NextDialogue = 80190305,
          SpeakNpcId = 95102
        },
        [80190305] = {
          Content = "啊……嗯，我没事，没事，酒不错，和之前一样，高水准。",
          DialogueId = 80190305,
          GUID = "C8BF7DEA",
          NextDialogue = 80190306,
          SpeakNpcId = 95102
        },
        [80190306] = {
          Content = "……",
          DialogueId = 80190306,
          GUID = "C8BF7E14",
          NextOptions = {
            [1] = 801903061,
            [2] = 801903062
          },
          SpeakNpcId = 95102
        },
        [80190307] = {
          Content = "哈？想多了，我怎么会在人前掉眼泪，多愁善感和“狐朋狗友”这几个字可不怎么搭。",
          DialogueId = 80190307,
          FacialId = {
            [1] = "95102:Shock01"
          },
          GUID = "C8BF7E3E",
          NextDialogue = 80190308,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190308] = {
          Content = "不过，最近确实老想起过去的一些事……哎呀，没准是岁数大了。",
          DialogueId = 80190308,
          FacialId = {
            [1] = "95102:Sad01"
          },
          GUID = "C8BF7E68",
          NextDialogue = 80190309,
          SpeakNpcId = 95102
        },
        [80190309] = {
          Content = "别这样一脸凝重地看着我，我可没打算继续说下去，你不会以为几顿酒就能换来我过去的一切吧。",
          DialogueId = 80190309,
          GUID = "C8BF7E92",
          NextDialogue = 80190310,
          SpeakNpcId = 95102
        },
        [80190310] = {
          Content = "每个人身上都有几件需要独自带入坟墓的秘密。它们不会出现在墓穴，却是墓主最重要的陪葬。",
          DialogueId = 80190310,
          GUID = "C8BF7EBC",
          NextDialogue = 80190311,
          SpeakNpcId = 95102
        },
        [80190311] = {
          Content = "这些秘密可大可小，小到一些奇怪经历，比如喜欢闻月髓液的味道、喜欢啃硬硬的姜饼结果硌掉了门牙，大到不为人知的过去。",
          DialogueId = 80190311,
          GUID = "C8BF7EE6",
          NextDialogue = 80190312,
          SpeakNpcId = 95102
        },
        [80190312] = {
          Content = "但毫无疑问，这些你看不见的秘密才是一个人会做出什么事的最重要依据。唔，说是最重要可能也过了，但你明白意思就好。",
          DialogueId = 80190312,
          GUID = "C8BF7F10",
          NextDialogue = 80190313,
          SpeakNpcId = 95102
        },
        [80190313] = {
          Content = "随便把秘密和过去讲给你听的人只有几种可能，要么是那段过去对他们来说不够重要……",
          DialogueId = 80190313,
          GUID = "C8BF7F3A",
          NextDialogue = 80190314,
          SpeakNpcId = 95102
        },
        [80190314] = {
          Content = "要么是期望从你这得到什么安慰，而随意捏造了一段不存在的过往。",
          DialogueId = 80190314,
          GUID = "C8BF7F64",
          NextDialogue = 80190315,
          SpeakNpcId = 95102
        },
        [80190315] = {
          Content = "总之，随意向其他人吐露自己的秘密，是很轻率的。既是把自己的把柄交了出去，也很容易被别人认为当做是行为轻佻。",
          DialogueId = 80190315,
          GUID = "C8BF7F8E",
          NextOptions = {
            [1] = 801903151,
            [2] = 801903152
          },
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190316] = {
          Content = "是是是，通常来说确实如此，你说得这些我也明白。我也时不时在水仙平原和人说我又偷偷接了几件大活这样的秘密。",
          DialogueId = 80190316,
          GUID = "C8BF7FB8",
          NextDialogue = 80190317,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_AgreeHead"
          }
        },
        [80190317] = {
          Content = "但……有点狡辩地说，秘密也是有大有小的。",
          DialogueId = 80190317,
          GUID = "C8BF7FE2",
          NextOptions = {
            [1] = 801903171
          },
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk01_Start"
          }
        },
        [80190318] = {
          Content = "说什么呢，别瞎想！",
          DialogueId = 80190318,
          GUID = "C8BF800C",
          NextDialogue = 80190319,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk01_End"
          }
        },
        [80190319] = {
          Content = "……正因为是你，才不能让你知道我的过去。这不是故弄玄虚吊你胃口，而是希望你能够理解的忠告吧：",
          DialogueId = 80190319,
          GUID = "C8BF8036",
          NextDialogue = 80190320,
          SpeakNpcId = 95102
        },
        [80190320] = {
          Content = "挖开过去的坟冢，发现的可能不是宝藏，而是死亡。为了不给大家添麻烦，这些事就让我一个人烂在肚子里吧。",
          DialogueId = 80190320,
          GUID = "C8BF8060",
          NextDialogue = 80190321,
          SpeakNpcId = 95102
        },
        [80190321] = {
          Content = "放心，这些年我不都成功地把过去远远甩在身后了嘛。就算真追上来了，也还有我扛着。你担心明天不如过好当下。",
          DialogueId = 80190321,
          FacialId = {
            [1] = "95102:Smile01"
          },
          GUID = "C8BF808A",
          NextDialogue = 80190322,
          SpeakNpcId = 95102
        },
        [80190322] = {
          Content = "我要再来一杯！刚才那杯喝得太快了没尝出个咸淡来。",
          DialogueId = 80190322,
          GUID = "C8BF80B4",
          NextOptions = {
            [1] = 801903221,
            [2] = 801903222
          },
          SpeakNpcId = 95102
        },
        [80190323] = {
          Content = "哈哈哈哈哈。就着好酒，和好朋友有一茬没一茬地唠唠，多好的一天啊。",
          DialogueId = 80190323,
          FacialId = {
            [1] = "95102:Smile02"
          },
          GUID = "C8BF80DE",
          NextOptions = {
            [1] = 801903231
          },
          SpeakNpcId = 95102
        },
        [80190324] = {
          Content = "你刚才是不是骂人了？",
          DialogueId = 80190324,
          GUID = "C8BF8108",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Think_Start"
          }
        },
        [80190401] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          Content = "拿起酒杯，猛喝一口",
          DialogueId = 80190401,
          GUID = "C8BF8DAA",
          NextDialogue = 80190402,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190402] = {
          Content = "嗯？你刚刚叫我吗？",
          DialogueId = 80190402,
          FacialId = {
            [1] = "95102:Doubt01"
          },
          GUID = "C8BF8DD4",
          NextOptions = {
            [1] = 801904021
          },
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102
        },
        [80190403] = {
          Content = "啊……是吗？最近我有点疑神疑鬼的，抱歉。",
          DialogueId = 80190403,
          FacialId = {
            [1] = "95102:Unhappy01"
          },
          GUID = "C8BF8DFE",
          NextDialogue = 80190404,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_DisagreeHead"
          }
        },
        [80190404] = {
          Content = "实际上从很久之前开始，我就会幻听有人叫我本来的名字。这些声音有的温柔，有的坚毅。",
          DialogueId = 80190404,
          GUID = "C8BF8E28",
          NextDialogue = 80190405,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk02_Start"
          }
        },
        [80190405] = {
          Content = "就跟耳鸣差不多吧，听久了也就习惯了。我无聊的时候还会回她们一声解解闷呢，反正知道是假的。",
          DialogueId = 80190405,
          GUID = "C8BF8E52",
          NextDialogue = 80190406,
          SpeakNpcId = 95102
        },
        [80190406] = {
          Content = "但最近吓人的事发生了，昨天我习惯性地诶了一声，结果居然真有人“回应”了。",
          DialogueId = 80190406,
          GUID = "C8BF8E7C",
          NextDialogue = 80190407,
          SpeakNpcId = 95102
        },
        [80190407] = {
          Content = "街角的垃圾桶突然翻了过来，蹦出来一个黑黢黢的人影，跟我打招呼。",
          DialogueId = 80190407,
          GUID = "C8BF8EA6",
          NextDialogue = 80190408,
          SpeakNpcId = 95102
        },
        [80190408] = {
          Content = "我多希望那是哪个倒霉孩子的恶作剧。但可惜的是我听到了那个只有神弃者同盟的人才会叫的名字，而不是你所知的“奥特赛德”。",
          DialogueId = 80190408,
          GUID = "C8BF8ED0",
          NextDialogue = 80190409,
          SpeakNpcId = 95102
        },
        [80190409] = {
          Content = "我赶紧装听错的路人搪塞过去了，也不知道那人信了没……唉，早知道前几天那个神弃者同盟的活就全甩给威尔斯了。",
          DialogueId = 80190409,
          GUID = "C8BF8EFA",
          NextOptions = {
            [1] = 801904091
          },
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk02_End"
          }
        },
        [80190410] = {
          Content = "……",
          DialogueId = 80190410,
          GUID = "C8BF8F24",
          NextDialogue = 80190411,
          SpeakNpcId = 95102
        },
        [80190411] = {
          DialogueId = 80190411,
          GUID = "C8BF8F4E",
          NextDialogue = 80190412,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190412] = {
          Content = "好吧，也该告诉你一些的。不然你走在路上莫名其妙被神弃者同盟的疯子捅了一刀，都不知道该怨谁了。",
          DialogueId = 80190412,
          GUID = "C8BF8F78",
          NextDialogue = 80190413,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk01_Start"
          }
        },
        [80190413] = {
          Content = "我以前跟神弃者同盟有点……小过节，所以他们一直在找我。然后前几天那个委托<H>可能</>暴露了我的行踪。",
          DialogueId = 80190413,
          GUID = "C8BF8FA2",
          NextDialogue = 80190414,
          SpeakNpcId = 95102
        },
        [80190414] = {
          Content = "所以我得费点功夫，消掉在冰湖城的一些痕迹，免得他们真的顺着线索找到我。",
          DialogueId = 80190414,
          GUID = "C8BF8FCC",
          NextDialogue = 80190415,
          SpeakNpcId = 95102
        },
        [80190415] = {
          Content = "真要被他们找到了啊，我的朋友们都得遭殃，挨个拷打，不吐出我的下落不罢休。连你也跑不掉。",
          DialogueId = 80190415,
          GUID = "C8BF8FF6",
          NextDialogue = 80190416,
          SpeakNpcId = 95102
        },
        [80190416] = {
          Content = "不过嘛，你也大可以说，我是你的酒肉朋友，和我相关的事情一概不知——",
          DialogueId = 80190416,
          GUID = "C8BF9020",
          NextOptions = {
            [1] = 801904161,
            [2] = 801904162
          },
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk01_End"
          }
        },
        [80190417] = {
          Content = "哎，别着急打断我，这不还没发生嘛。不过……万一真的有那么一天……",
          DialogueId = 80190417,
          GUID = "C8BF904A",
          NextDialogue = 80190418,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Think_Start"
          }
        },
        [80190418] = {
          Content = "到时候我得离开你们，离开这座城市。菲娜就拜托你照顾了。",
          DialogueId = 80190418,
          GUID = "C8BF9074",
          NextDialogue = 80190419,
          SpeakNpcId = 95102
        },
        [80190419] = {
          Content = "她要是问起来你就说我接了个大活。我这里写了些信，你到时候每个月给她一封，应该能稳住她一段时间。",
          DialogueId = 80190419,
          GUID = "C8BF909E",
          NextDialogue = 80190420,
          SpeakNpcId = 95102
        },
        [80190420] = {
          Content = "对了还有，我家暖炉右手第三块砖后面藏了一笔钱，你直接拿去用吧。我想想还有什么……",
          DialogueId = 80190420,
          GUID = "C8BF90C8",
          NextDialogue = 80190421,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Think_End"
          }
        },
        [80190421] = {
          Content = "奥特赛德你先冷静点。",
          DialogueId = 80190421,
          GUID = "C8BF90F2",
          NextDialogue = 80190422,
          SpeakNpcId = 790008
        },
        [80190422] = {
          Content = "我很冷静。你跟我复述一遍我刚才说的，我到时候不在了一切都得靠你了。",
          DialogueId = 80190422,
          GUID = "C8BF911C",
          NextDialogue = 80190423,
          SpeakNpcId = 95102
        },
        [80190423] = {
          Content = "这可不是你平时的样子，就因为神弃者同盟吗？",
          DialogueId = 80190423,
          GUID = "C8BF9146",
          NextDialogue = 80190424,
          SpeakNpcId = 790008
        },
        [80190424] = {
          Content = "平时？平时可应付不了毫无底线的疯子。",
          DialogueId = 80190424,
          FacialId = {
            [1] = "95102:Unacceptable01"
          },
          GUID = "C8BF9170",
          NextDialogue = 80190425,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190425] = {
          Content = "举个例子，为了一条情报，他们会一枚一枚地拔掉你的指甲。",
          DialogueId = 80190425,
          GUID = "C8BF919A",
          NextDialogue = 80190426,
          SpeakNpcId = 95102
        },
        [80190426] = {
          Content = "而这一切只是那群疯子折磨的开始罢了……我不想看到这种事……发生在朋友身上……",
          DialogueId = 80190426,
          GUID = "C8BF91C4",
          NextDialogue = 80190427,
          SpeakNpcId = 95102
        },
        [80190427] = {
          Content = "但这些都还没发生，而且你也说了自己的行踪只是<H>可能</>暴露了而已，不是吗？",
          DialogueId = 80190427,
          GUID = "C8BF91EE",
          NextDialogue = 80190428,
          SpeakNpcId = 790008
        },
        [80190428] = {
          Content = "即使是“可能”，也得做好万全准备。",
          DialogueId = 80190428,
          GUID = "C8BF9218",
          NextDialogue = 80190429,
          SpeakNpcId = 95102
        },
        [80190429] = {
          Content = "过去没有类似的“可能”吗？现在比过去更危险吗？",
          DialogueId = 80190429,
          GUID = "C8BF9242",
          NextDialogue = 80190430,
          SpeakNpcId = 790008
        },
        [80190430] = {
          Content = "要说最危险的时候，这次好像还真不算什么……",
          DialogueId = 80190430,
          FacialId = {
            [1] = "95102:Think01"
          },
          GUID = "C8BF926C",
          NextDialogue = 80190431,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190431] = {
          Content = "这不就对了，过去你是怎么解决的。",
          DialogueId = 80190431,
          GUID = "C8BF9296",
          NextDialogue = 80190432,
          SpeakNpcId = 790008
        },
        [80190432] = {
          Content = "……有些只是虚惊一场，有些被我用恐吓、欺骗，把军团引来，或者在其他城市抛头露面之类的把戏解决掉了。",
          DialogueId = 80190432,
          GUID = "C8BF92C0",
          NextOptions = {
            [1] = 801904321,
            [2] = 801904322
          },
          SpeakNpcId = 95102
        },
        [80190433] = {
          DialogueId = 80190433,
          GUID = "C8BF92EA",
          NextDialogue = 80190434,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190434] = {
          Content = "是啊……你说的对。刚才我好像是有点……不太对劲。更危险的时候我都挺过来了，这次却早早把“后事”交代给了你。",
          DialogueId = 80190434,
          FacialId = {
            [1] = "95102:None"
          },
          GUID = "C8BF9314",
          NextDialogue = 80190435,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190435] = {
          Content = "是最近跟你聊得太多还是我下意识地想要依赖你这个队长了，亦或是我变软弱了吗……",
          DialogueId = 80190435,
          GUID = "C8BF933E",
          NextDialogue = 80190436,
          SpeakNpcId = 95102
        },
        [80190436] = {
          Content = "不对不对，怎么可能嘛！肯定是今天的酒有问题！刚才我说过什么很恶心的话吗？没有吧，绝对没有，对吧！",
          DialogueId = 80190436,
          GUID = "C8BF9368",
          NextOptions = {
            [1] = 801904361,
            [2] = 801904362
          },
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_DisagreeHead"
          }
        },
        [80190437] = {
          Content = "所以说回来，比起担心还未发生的“可能”，不如还是等一切发生的时候再来拜托我吧，也许那时候我们还能找到更好的办法。",
          DialogueId = 80190437,
          GUID = "C8BF9392",
          NextDialogue = 80190438,
          SpeakNpcId = 790008
        },
        [80190438] = {
          Content = "咳咳，说得好。拜托了，未来的我！来来喝酒喝酒，敬未来的我们。",
          DialogueId = 80190438,
          FacialId = {
            [1] = "95102:Smile01"
          },
          GUID = "C8BF93BC",
          NextDialogue = 80190439,
          SpeakNpcId = 95102
        },
        [80190439] = {
          DialogueId = 80190439,
          GUID = "C8BF93E6",
          NextDialogue = 80190440,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190440] = {
          Content = "哦，但我还得道个歉，关于未来的担心是解决了，但关于我的过去，还是没办法全部告诉你。",
          DialogueId = 80190440,
          GUID = "C8BF9410",
          NextDialogue = 80190441,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190441] = {
          Content = "不过我向你保证，一定会有一天，我会带你看我来到冰湖城之前的路。虽然它会让我痛苦，也可能让你对我有所怀疑。",
          DialogueId = 80190441,
          GUID = "C8BF943A",
          NextDialogue = 80190442,
          SpeakNpcId = 95102
        },
        [80190442] = {
          Content = "但我相信，到那时候，你依旧不会介意为我调上一杯和今日一样的酒的，我的朋友。",
          DialogueId = 80190442,
          GUID = "C8BF9464",
          SpeakNpcId = 95102
        },
        [80200001] = {
          Camera = "371.189178,358.122345,166.996094,0.000053,-4.198886,-152.598816,30.0,1011.382263,false,Manual,2.8",
          Content = "春采薇，夏生苋，秋结枳，冬访芝……",
          DialogueId = 80200001,
          FinalCamera = "255.737183,256.213654,144.412109,0.000053,-4.398778,-152.798981,30.000002,1011.382263,false,Manual,2.8",
