}]],
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Explain02_End"
          },
          ToFinalCameraBlendTime = 8
        },
        [80200004] = {
          Content = "的确如此，方才提及的皆可入药，有的也可以食用。",
          DialogueId = 80200004,
          GUID = "C8C5B528",
          NextDialogue = 80200009,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Talk02_Start"
          }
        },
        [80200006] = {
          Content = "呵呵，没想到你涉猎如此之广，正是出自《草木精要》。",
          DialogueId = 80200006,
          GUID = "C8C5B57C",
          NextDialogue = 80200009,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Talk02_Start"
          }
        },
        [80200008] = {
          Content = "无碍，你我之间不必如此小心。你愿来拜访，我自是欢迎。",
          DialogueId = 80200008,
          GUID = "C8C5B5D0",
          NextDialogue = 80200009,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Talk02_Start"
          }
        },
        [80200009] = {
          Camera = "-299.287354,935.059692,618.705078,0.000024,-30.199797,-77.19545,30.0,1011.382263,false,Manual,1.2",
          Content = "正巧，我已读了半晌书，是该休息的时候了。",
          DialogueId = 80200009,
          FinalCamera = "-309.453308,979.785645,645.397461,0.000024,-30.199797,-77.19545,30.0,1011.382263,false,Manual,1.2",
          GUID = "C8C5B5FA",
          NextDialogue = 80200010,
          Scripts = [[
