790008:Talk03_Start]]
          },
          ToFinalCameraBlendTime = 15
        },
        [80200010] = {
          Camera = "-232.469772,-43.903526,169.408203,0.000064,-9.39922,29.805199,35.0,1011.382263,false,DoNotOverride,1.2",
          Content = "只是如今的枯荣阁早已人去楼空，并无好茶款待，倒是失礼。",
          DialogueId = 80200010,
          FinalCamera = "-235.925156,-37.86274,169.408203,0.000064,-9.39922,29.80522,35.0,1011.382263,false,DoNotOverride,1.2",
          GUID = "C8C5B624",
          NextOptions = {
            [1] = 802000101,
            [2] = 802000102,
            [3] = 802000103
          },
          Scripts = "LookAt{_delay{5.1},LookAtDescription{\"790053:n(790008)\"}}",
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790008:Talk03_End",
            [2] = "790053:Explain02_Start"
          },
          ToFinalCameraBlendTime = 8
        },
        [80200012] = {
          Content = "起初确实不大习惯，但我实在留恋故地，因此不惯也惯了。",
          DialogueId = 80200012,
          GUID = "C8C5B678",
          NextDialogue = 80200017,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Explain02_End"
          }
        },
        [80200014] = {
          Content = "谢你海涵，这就是所谓的“君子之交淡若水”吧。",
          DialogueId = 80200014,
          GUID = "C8C5B6CC",
          NextDialogue = 80200017,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Explain02_End"
          }
        },
        [80200016] = {
          Content = "饿了吗？但此刻天色尚早，并不是正经用餐的时候，再过些时候吧。",
          DialogueId = 80200016,
          GUID = "C8C5B720",
          NextDialogue = 80200017,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Explain02_End"
          }
        },
        [80200017] = {
          Camera = "8.049835,364.447235,138.173828,0.000069,-1.798737,-95.393364,35.0,1011.382263,false,DoNotOverride,1.2",
          Content = "难得今日有缘相见，那我也不再遮掩，其实……扶疏有一事相求。",
          DialogueId = 80200017,
          FinalCamera = "6.295837,345.858063,137.587891,0.000069,-1.798737,-96.993561,35.0,1011.382263,false,DoNotOverride,1.2",
          GUID = "C8C5B74A",
          NextDialogue = 80200018,
          SpeakNpcId = 790053,
          ToFinalCameraBlendTime = 6,
          TurnTo = {
            [1] = "790053:n(790008)"
          }
        },
        [80200018] = {
          Camera = "-151.623276,12.392727,139.394531,0.000081,-2.999197,33.605621,35.0,194.999741,false,Manual,7.870067",
          Content = "可以说来听听。",
          DialogueId = 80200018,
          GUID = "C8C5B774",
          NextDialogue = 80200019,
          SpeakNpcId = 790008,
          TalkActionId = {
            [1] = "790008:Talk02_Start"
          }
        },
        [80200019] = {
          Camera = "13.768398,198.582336,145.302734,0.000078,-2.199123,-112.991898,35.0,194.999741,false,Manual,7.870067",
          Content = "上次凭笔记中寻来的方子治好了那位被玄色狴犴所伤的姑娘，使我对药理生出几分兴趣。",
          DialogueId = 80200019,
          GUID = "C8C5B79E",
          NextDialogue = 80200020,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Talk02_Start",
            [2] = "790008:Talk02_End"
          }
        },
        [80200020] = {
          Camera = "-151.623276,12.392727,139.394531,0.000081,-2.999197,33.605621,35.0,194.999741,false,Manual,7.870067",
          Content = "扶氏世代以枯荣之术救人，药理则是近百年才出现的学问。家姐生前精于此道，我所知却是微末。",
          DialogueId = 80200020,
          GUID = "C8C5B7C8",
          NextDialogue = 80200021,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Talk02_End",
            [2] = "790008:Think_Start"
          }
        },
        [80200021] = {
          Camera = "3.627094,154.315002,128.976562,0.000067,6.000922,-123.393097,35.0,1011.382263,false,DoNotOverride,1.2",
          Content = "我……我想贯彻家传使命的愿望自然未改，但从棺中苏醒的因缘，是家姐与她的弟子耗尽心血得来，我也不愿轻易辜负他们。",
          DialogueId = 80200021,
          FinalCamera = "-4.169064,142.494461,130.460938,0.000067,6.000922,-123.393059,35.0,1011.382263,false,DoNotOverride,1.2",
          GUID = "C8C5B7F2",
          NextDialogue = 80200022,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10
        },
        [80200022] = {
          Camera = "-92.099129,54.970886,136.441406,0.000081,0.000908,39.804794,35.0,194.999741,false,Manual,7.870067",
          Content = "因此我才试着去研习如今的医药学问，但这样的事终究是纸上得来终觉浅。",
          DialogueId = 80200022,
          GUID = "C8C5B81C",
          NextDialogue = 80200023,
          SpeakNpcId = 790053
        },
        [80200023] = {
          Camera = "-998.92572,807.125,118.349609,0.000104,2.800753,-34.992069,35.0,12772.838867,false,Manual,1.460963",
          Content = "我一直很想找人实践一番，看看要如何去望闻问切，所谓病理，在人身上究竟是何等境况。",
          DialogueId = 80200023,
          FinalCamera = "-998.92572,807.125,61.935547,0.000104,2.800753,-34.992069,35.0,12772.838867,false,Manual,1.460963",
          GUID = "C8C5B846",
          NextDialogue = 80200024,
          SpeakNpcId = 790053,
          ToFinalCameraBlendTime = 15
        },
        [80200024] = {
          Content = "只是百年光阴转瞬即逝，我在此地早已是无亲无友。",
          DialogueId = 80200024,
          GUID = "C8C5B870",
          NextDialogue = 80200025,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Explain02_End"
          }
        },
        [80200025] = {
          Content = "若随意为人诊治，要是出了差错，岂不成了医德不修之人？",
          DialogueId = 80200025,
          GUID = "C8C5B89A",
          NextDialogue = 80200026,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790008:Think_End"
          }
        },
        [80200026] = {
          Camera = "37.140533,321.639557,117.170898,0.00008,4.200812,-104.992432,35.0,194.999741,false,Manual,7.870067",
          Content = "若要寻找有些交情，也愿担待扶疏一二的……思来想去，你竟是唯一的人选。",
          DialogueId = 80200026,
          FinalCamera = "22.796768,325.479004,117.170898,0.000079,4.200812,-101.992058,35.0,194.999741,false,Manual,7.870067",
          GUID = "C8C5B8C4",
          NextDialogue = 80200027,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{6.01},TargetPosition{"-58.677288,55.479034,145.46582,0.000065,-3.399037,55.0061,35.0,1011.382263,false,DoNotOverride,1.2"},duration{0}},
CameraMoveTo{TargetPosition{"-52.295345,64.584396,144.802734,0.000065,-3.399037,55.006577,35.0,1011.382263,false,DoNotOverride,1.2"},duration{8}}
}]],
          SpeakNpcId = 790053,
          ToFinalCameraBlendTime = 20
        },
        [80200027] = {
          Camera = "-371.388824,918.673523,618.705078,0.000024,-30.199797,-77.19545,30.0,1011.382263,false,Manual,1.2",
          Content = "然而身体状况乃是私隐，你若不愿，我定不会勉强你。",
          DialogueId = 80200027,
          FinalCamera = "-298.00293,935.355347,618.705078,0.000024,-30.199797,-77.19545,30.0,1011.382263,false,Manual,1.2",
          GUID = "C8C5B8EE",
          NextOptions = {
            [1] = 802000271,
            [2] = 802000272,
            [3] = 802000273
          },
          SpeakNpcId = 790053,
          ToFinalCameraBlendTime = 20
        },
        [80200029] = {
          Content = "多谢……对你来说虽是举手小事，但扶疏铭记在心。",
          DialogueId = 80200029,
          GUID = "C8C5B942",
          NextDialogue = 80200034,
          SpeakNpcId = 790053
        },
        [80200031] = {
          Content = "诶？竟、竟如此信任我吗？等一下，倒也不用这么急着脱下斗篷……",
          DialogueId = 80200031,
          GUID = "C8C5B996",
          NextDialogue = 80200034,
          SpeakNpcId = 790053
        },
        [80200033] = {
          Content = "我自然不会提如此危险之事！不过……这是答应的意思吗？",
          DialogueId = 80200033,
          GUID = "C8C5B9EA",
          NextDialogue = 80200034,
          SpeakNpcId = 790053
        },
        [80200034] = {
          Camera = "-12.930632,116.6409,137.194336,0.000094,6.600558,-127.588852,45.000011,194.999756,false,DoNotOverride,7.870067",
          Content = "承蒙不弃，扶疏一定尽力而为。",
          DialogueId = 80200034,
          GUID = "C8C5BA14",
          NextDialogue = 80200035,
          SpeakNpcId = 790053
        },
        [80200035] = {
          Content = "扶疏仔仔细细地为你诊治一番。",
          DialogueId = 80200035,
          GUID = "C8C5BA3E",
          IsBlack = 1
        },
        [80200036] = {
          Camera = "-40.848995,85.709183,149.865234,0.000094,1.200781,-124.785934,45.000011,194.999756,false,DoNotOverride,7.870067",
          Content = "嗯……你的身体十分健康，至少在我看来没有什么大的不妥，只是……",
          DialogueId = 80200036,
          FinalCamera = "-27.404249,104.783081,149.896484,0.000094,0.000697,-124.58551,45.000023,194.999756,false,DoNotOverride,7.870067",
          GUID = "C8C5BA68",
          NextDialogue = 80200037,
          SpeakNpcId = 790053,
          ToFinalCameraBlendTime = 4
        },
        [80200037] = {
          Camera = "-77.972321,4.005304,157.167969,0.000114,-5.999071,62.412296,45.000011,194.999756,false,Manual,7.870067",
          Content = "从面色上看不出来，但您应该很久、很久没有睡觉了吧？",
          DialogueId = 80200037,
          GUID = "C8C5BA92",
          NextOptions = {
            [1] = 802000371,
            [2] = 802000372,
            [3] = 802000373
          },
          SpeakNpcId = 790053
        },
        [80200039] = {
          Camera = "86.032745,191.327408,140.46875,0.000115,0.600701,-140.191589,45.000011,194.999756,false,Manual,7.870067",
          Content = "长此以往，可能会落下病根，可要千万注意。若是没有安枕的地方，这枯荣阁也可做你暂时落脚的地方。",
          DialogueId = 80200039,
          GUID = "C8C5BAE6",
          NextDialogue = 80200049,
          SpeakNpcId = 790053
        },
        [80200041] = {
          Camera = "86.032745,191.327408,140.46875,0.000115,0.600701,-140.191589,45.000011,194.999756,false,Manual,7.870067",
          Content = "求财虽是人之常情，但连轴转并不可取。如果不加改善，下次就没有免费诊治的机会了，或许……我还会考虑向你收取高额诊金喔。",
          DialogueId = 80200041,
          GUID = "C8C5BB3A",
          NextDialogue = 80200042,
          SpeakNpcId = 790053
        },
        [80200042] = {
          Camera = "-77.972321,4.005304,152.584961,0.000114,-5.999071,62.41214,45.000011,194.999756,false,Manual,7.870067",
          Content = "不——要——啊——我——要——撤——回——这——个——诊——疗——",
          DialogueId = 80200042,
          GUID = "C8C5BB64",
          NextDialogue = 80200049,
          SpeakNpcId = 790008
        },
        [80200044] = {
          Camera = "86.032745,191.327408,140.46875,0.000115,0.600701,-140.191589,45.000011,194.999756,false,Manual,7.870067",
          Content = "嗯……如果病人的态度非常不配合的话，我只能把药方换成别的了。",
          DialogueId = 80200044,
          GUID = "C8C5BBB8",
          NextDialogue = 80200045,
          SpeakNpcId = 790053
        },
        [80200045] = {
          Camera = "-77.972321,4.005304,152.584961,0.000114,-5.999071,62.41214,45.000011,194.999756,false,Manual,7.870067",
          Content = "比如？",
          DialogueId = 80200045,
          GUID = "C8C5BBE2",
          NextDialogue = 80200046,
          SpeakNpcId = 790008
        },
        [80200046] = {
          Camera = "86.032745,191.327408,140.46875,0.000115,0.600701,-140.191589,45.000011,194.999756,false,Manual,7.870067",
          Content = "我自幼练武，只是寻常伤筋动骨的话，不用枯荣之术我也能医治。",
          DialogueId = 80200046,
          GUID = "C8C5BC0C",
          NextDialogue = 80200047,
          SpeakNpcId = 790053
        },
        [80200047] = {
          Content = "不过有时病人疼得厉害，乱动起来可能会加重病情，这时候只要击打这里，就可以让人暂时失去意识，来，我指给你看……",
          DialogueId = 80200047,
          GUID = "C8C5BC36",
          NextDialogue = 80200048,
          SpeakNpcId = 790053
        },
        [80200048] = {
          Camera = "-77.972321,4.005304,152.584961,0.000114,-5.999071,62.41214,45.000011,194.999756,false,Manual,7.870067",
          Content = "不不不用了医生，我选择保守治疗！",
          DialogueId = 80200048,
          GUID = "C8C5BC60",
          NextDialogue = 80200049,
          SpeakNpcId = 790008
        },
        [80200049] = {
          Camera = "86.032745,191.327408,140.46875,0.000115,0.600701,-140.191589,45.000011,194.999756,false,Manual,7.870067",
          Content = "确实能察觉到，你的睡眠时间少到了夸张的地步……是有失眠，或者入睡困难之类的问题吗？",
          DialogueId = 80200049,
          GUID = "C8C5BC8A",
          NextDialogue = 80200050,
          SpeakNpcId = 790053
        },
        [80200050] = {
          Camera = "-56.48967,56.785522,140.112305,0.000036,-0.399088,56.015965,35.0,194.999756,false,DoNotOverride,7.870067",
          Content = "我可能是天生觉少……不过我有多梦的症状。有时从梦中突然惊醒，就再也睡不着了。",
          DialogueId = 80200050,
          GUID = "C8C5BCB4",
          NextDialogue = 80200051,
          SpeakNpcId = 790008
        },
        [80200051] = {
          Camera = "21.420506,52.709782,178.382812,0.00004,-17.199427,-170.186905,35.0,194.999756,false,DoNotOverride,7.870067",
          Content = "竟是如此。我还以为你是自入华胥以来无暇休息所致，原来是老症候了。",
          DialogueId = 80200051,
          GUID = "C8C5BCDE",
          NextDialogue = 80200052,
          SpeakNpcId = 790053
        },
        [80200052] = {
          Content = "不过我已经想好了一剂药方，不敢保证药到病除，但坚持服用也会有所裨益。",
          DialogueId = 80200052,
          GUID = "C8C5BD08",
          NextDialogue = 80200053,
          SpeakNpcId = 790053
        },
        [80200053] = {
          Camera = "1945.186279,141.809723,246.677734,0.000132,-2.999115,-178.399689,35.0,912.188171,false,Manual,2.349894",
          Content = "只是……其中最关键的一味“怀梦草”，是枯荣阁中没有的。要去百年春求购，又需好些时日。",
          DialogueId = 80200053,
          FinalCamera = "2107.597168,146.344818,255.18457,0.000132,-2.999115,-178.399689,35.0,912.188171,false,Manual,2.349894",
          GUID = "C8C5BD32",
          NextDialogue = 80200054,
          SpeakNpcId = 790053,
          ToFinalCameraBlendTime = 20
        },
        [80200054] = {
          Content = "最好便是枯荣阁附近寻上一寻，若是幸运，今晚你便能好好休息了。不知你意下如何呢？",
          DialogueId = 80200054,
          GUID = "C8C5BD5C",
          NextDialogue = 80200055,
          SpeakNpcId = 790053
        },
        [80200055] = {
          Camera = "-138.100891,-376.441467,153.882812,0.000078,-5.798817,78.616974,35.0,194.999756,false,DoNotOverride,7.870067",
          Content = "那就多谢你了！",
          DialogueId = 80200055,
          FinalCamera = "-148.366501,-427.434601,159.165039,0.000079,-5.798817,78.617157,35.0,194.999756,false,DoNotOverride,7.870067",
          GUID = "C8C5BD86",
          NextDialogue = 80200056,
          SpeakNpcId = 790008,
          ToFinalCameraBlendTime = 15
        },
        [80200056] = {
