          Content = "身膺大风九章给予的神力，就应当救死扶伤，尽职尽责，哪怕耗尽最后一滴精血也在所不惜，我们扶氏代代如此……",
          DialogueId = 80200134,
          GUID = "C8C5CA7C",
          NextDialogue = 80200135,
          SpeakNpcId = 790053
        },
        [80200135] = {
          Content = "怎么只有你扶风如此特殊，上不应天命，下不惜生灵，不尽祝由义务，离经叛道……",
          DialogueId = 80200135,
          GUID = "C8C5CAA6",
          NextDialogue = 80200136,
          SpeakNpcId = 790053
        },
        [80200136] = {
          Camera = "462.438812,-170.091492,137.168945,0.00028,-13.203664,164.636902,25.0,3742.911621,false,DoNotOverride,2.8",
          Content = "等等！我不是你姐姐——",
          DialogueId = 80200136,
          GUID = "C8C5CAD0",
          NextDialogue = 80200137,
          SpeakNpcId = 790008
        },
        [80200137] = {
          Camera = "-48.62505,-141.917023,26.847168,0.000313,6.394382,59.628559,25.000006,76.531006,false,DoNotOverride,3.949137",
          Content = "做出这等事来，你自然不再是我姐姐——",
          DialogueId = 80200137,
          GUID = "C8C5CAFA",
          NextOptions = {
            [1] = 802001371,
            [2] = 802001372,
            [3] = 802001373
          },
          SpeakNpcId = 790053
        },
        [80200139] = {
          Content = "我怎会信你那天马行空的理论……但{nickname}，好熟悉的名字，这是……",
          DialogueId = 80200139,
          GUID = "C8C5CB4E",
          NextDialogue = 80200144,
          SpeakNpcId = 790053
        },
        [80200141] = {
          Content = "……你竟幡然悔悟了？这……有些突然，我还没做好要原谅你的准备……",
          DialogueId = 80200141,
          GUID = "C8C5CBA2",
          NextDialogue = 80200144,
          SpeakNpcId = 790053
        },
        [80200143] = {
          Content = "母亲……？母亲为何在此？您不是早已……对不起，一定是小疏让您失望，您才会前来面责……",
          DialogueId = 80200143,
          GUID = "C8C5CBF6",
          NextDialogue = 80200144,
          SpeakNpcId = 790053
        },
        [80200144] = {
          Camera = "570.165649,-48.307911,20.491699,0.000324,0.794221,-170.781219,25.000006,76.530998,false,DoNotOverride,3.949137",
          Content = "我这是……不对、不对……我已不是百年前的扶疏……",
          DialogueId = 80200144,
          GUID = "C8C5CC20",
          NextDialogue = 80200145,
          SpeakNpcId = 790053
        },
        [80200145] = {
          Content = "姐姐也早已……",
          DialogueId = 80200145,
          GUID = "C8C5CC4A",
          NextDialogue = 80200146,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Sigh_End"
          }
        },
        [80200146] = {
          Content = "……我要一个人静静，你……不要跟来。",
          DialogueId = 80200146,
          GUID = "C8C5CC74",
          NextDialogue = 80200147,
          Scripts = "MoveTo{_delay{2},ActorId{790053},TargetPoint{\"BP_Stage_200201a fushu02\"},MoveSpeed{65},Visibility{\"Show\"}}",
          SpeakNpcId = 790053,
          TurnTo = {
            [1] = "790053:p(-170)"
          }
        },
        [80200147] = {
          Content = "一炷香后，扶疏回到了你们分开的的地方。",
          DialogueId = 80200147,
          GUID = "C8C5CC9E",
          IsBlack = 1
        },
        [80200148] = {
          Camera = "1368.781494,151.177246,68.581055,0.000042,-0.399935,-170.196045,30.000002,125.0,false,DoNotOverride,2.8",
          Content = "好点了吗？",
          DialogueId = 80200148,
          FinalCamera = "1361.394897,193.91571,68.581055,0.000042,-0.399935,-170.196045,30.000002,125.0,false,DoNotOverride,2.8",
          GUID = "C8C5CCC8",
