}]],
          SpeakNpcId = 790008
        },
        [80200214] = {
          Content = "（扶疏的脸逐渐模糊，你确认了一件事：你不属于音容草耐受人群。）",
          DialogueId = 80200214,
          GUID = "C8C5D160",
          IsBlack = 1
        },
        [80200215] = {
          Content = "进入幻境，主角在枯荣阁中刷出，NPC扶风刷出，背对主角。",
          DialogueId = 80200215,
          GUID = "C8C5D18A"
        },
        [80200216] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          Content = "头、头好晕……这里是枯荣阁？我什么时候回到来的？",
          DialogueId = 80200216,
          GUID = "C8C5D1B4",
          NextDialogue = 80200217,
          SpeakNpcId = 790008
        },
        [80200217] = {
          Content = "那是……扶疏？是她送我回来的吗？",
          DialogueId = 80200217,
          GUID = "C8C5D1DE",
          NextDialogue = 80200218,
          SpeakNpcId = 790008
        },
        [80200218] = {
          Content = "麻烦。麻烦。麻烦。麻烦！",
          DialogueId = 80200218,
          GUID = "C8C5D208",
          NextDialogue = 80200219,
          SpeakNpcId = 790054,
          SpeakNpcName = "？？？"
        },
        [80200219] = {
          Content = "唉，早上起来的时候，还再三告诫自己别去惹她别去惹她，怎么早饭还没吃完，就破戒了！",
          DialogueId = 80200219,
          GUID = "C8C5D232",
          NextDialogue = 80200220,
          SpeakNpcId = 790054,
          SpeakNpcName = "？？？"
        },
        [80200220] = {
          Content = "扶风啊扶风！你怎能如此沉不住气呢！那小妮子脾气再臭，也是你亲妹子！你又不可能扔下她不管，干嘛总是气她呢！",
          DialogueId = 80200220,
          GUID = "C8C5D25C",
          NextDialogue = 80200221,
          SpeakNpcId = 790054,
          SpeakNpcName = "？？？"
        },
        [80200221] = {
          Content = "没办法啊没办法，扶疏那一本正经的样子，实在是很好气……笑容没有消失，只是从扶疏妹妹的脸上，移到了我的脸上……",
          DialogueId = 80200221,
          GUID = "C8C5D286",
          NextDialogue = 80200222,
          SpeakNpcId = 790054
        },
        [80200222] = {
          Content = "人之常情，人之常情嘛！",
          DialogueId = 80200222,
          GUID = "C8C5D2B0",
          NextDialogue = 80200223,
          SpeakNpcId = 790054
        },
        [80200223] = {
          Content = "扶、扶疏？是你吗？",
          DialogueId = 80200223,
          GUID = "C8C5D2DA",
          NextDialogue = 80200224,
          SpeakNpcId = 790008
        },
        [80200224] = {
          Content = "不是哦。我是扶疏的双胞胎姐姐，扶风。将我俩弄混的人，你不是第一个。",
          DialogueId = 80200224,
          GUID = "C8C5D304",
          NextDialogue = 80200225,
          SpeakNpcId = 790054
        },
        [80200225] = {
          Content = "你找扶疏？怪了，她素来不和人来往，是个小闷葫芦，原来也有熟人？",
          DialogueId = 80200225,
          GUID = "C8C5D32E",
          NextOptions = {
            [1] = 802002251,
            [2] = 802002252,
            [3] = 802002253
          },
          SpeakNpcId = 790054
        },
        [80200226] = {
          Content = "哇……你这个年纪的人，竟不觉得她闷，还这样夸奖她，不错不错，扶疏的朋友，就是我扶风的朋友！",
          DialogueId = 80200226,
          GUID = "C8C5D382",
          NextDialogue = 80200229,
          SpeakNpcId = 790054
        },
        [80200227] = {
          Content = "讹钱讹到我枯荣阁来了？！你去这十里八乡问问，这小闷葫芦的肚子里连点铜钱响都听不到，你要诬赖人，好歹也诬赖给我吧！",
          DialogueId = 80200227,
          GUID = "C8C5D3D6",
          NextDialogue = 80200229,
          SpeakNpcId = 790054
        },
        [80200228] = {
          Content = "噫，油嘴滑舌，要是没病没痛就回家自己玩儿吧，乖。",
          DialogueId = 80200228,
          GUID = "C8C5D42A",
          NextDialogue = 80200229,
          SpeakNpcId = 790054
        },
        [80200229] = {
          Content = "所以，你造访枯荣阁所为何事？",
          DialogueId = 80200229,
          GUID = "C8C5D454",
          NextDialogue = 80200230,
          SpeakNpcId = 790054
        },
        [80200230] = {
          Content = "我误食了音容草，头脑发昏，还看见奇奇怪怪的东西，我想扶疏一定能治，就寻医问药来了。",
          DialogueId = 80200230,
          GUID = "C8C5D47E",
          NextDialogue = 80200231,
          SpeakNpcId = 790008
        },
        [80200231] = {
          Content = "你来得不巧，扶疏正生着闷气呢，还是别在这时候打扰她了。不过我是一名医师，让我看病也是一样的。",
          DialogueId = 80200231,
          GUID = "C8C5D4A8",
          NextDialogue = 80200232,
          SpeakNpcId = 790054
        },
        [80200232] = {
          Content = "让我仔细看看……",
          DialogueId = 80200232,
          GUID = "C8C5D4D2",
          NextDialogue = 80200233,
          SpeakNpcId = 790054
        },
        [80200233] = {
          Content = "嗯……步履还算稳健，双目也有焦点，口齿利索，舌头不打架，误食的量应该不大。大约是半片左右？",
          DialogueId = 80200233,
          GUID = "C8C5D4FC",
          NextDialogue = 80200234,
          SpeakNpcId = 790054
        },
        [80200234] = {
          Content = "你病得不重，没等解药熬完，就全好了。再耐心等等吧，很快就会清醒的，别怕。",
          DialogueId = 80200234,
          GUID = "C8C5D526",
          NextDialogue = 80200235,
          SpeakNpcId = 790054
        },
        [80200235] = {
          Content = "要是实在难受，我随身带了些橘枳丸，你嚼两个，会好些。",
          DialogueId = 80200235,
          GUID = "C8C5D550",
          NextDialogue = 80200236,
          SpeakNpcId = 790054
        },
        [80200236] = {
          Content = "我猜，你还有少眠多梦的毛病，于是你想去找怀梦草医治，但却不小心误食了极其类似的音容草。",
          DialogueId = 80200236,
          GUID = "C8C5D57A",
          NextDialogue = 80200237,
          SpeakNpcId = 790054
        },
        [80200237] = {
          Content = "不过想治这个毛病，还是匍地枝与隙中花一同煎来服下更合适，怀梦草虽能助眠，但会在梦中看到难以忘怀之事，徒惹伤怀。",
          DialogueId = 80200237,
          GUID = "C8C5D5A4",
          NextDialogue = 80200238,
          SpeakNpcId = 790054
        },
        [80200238] = {
          Content = "……不提外貌，你和扶疏确实相像。",
          DialogueId = 80200238,
          GUID = "C8C5D5CE",
          NextDialogue = 80200239,
          SpeakNpcId = 790008
        },
        [80200239] = {
          Content = "这话倒是鲜少听到，我和扶疏虽是双生胎，但都说我性格跳脱，颇有“离经叛道”的嫌疑，与大风九章第九条很不相宜。",
          DialogueId = 80200239,
          GUID = "C8C5D5F8",
          NextDialogue = 80200240,
          SpeakNpcId = 790054
        },
        [80200240] = {
          Content = "扶疏瞧着冷淡疏离，你瞧着风风火火，但只要涉及问诊的时候，那份一本正经，温和耐心简直如出一辙。",
          DialogueId = 80200240,
          GUID = "C8C5D622",
          NextDialogue = 80200241,
          SpeakNpcId = 790008
        },
        [80200241] = {
          Content = "你这人……现在我相信你和扶疏很熟了。",
          DialogueId = 80200241,
          GUID = "C8C5D64C",
          NextDialogue = 80200242,
          SpeakNpcId = 790054
        },
        [80200242] = {
          Content = "那孩子性格执拗，许多话憋在心里不肯说，一张嘴也不怎么灵巧，有时明明是这个意思，说出来却离题万里。",
          DialogueId = 80200242,
          GUID = "C8C5D676",
          NextDialogue = 80200243,
          SpeakNpcId = 790054
        },
        [80200243] = {
          Content = "大概……只有你这样细心的人才能和她玩到一起吧！",
          DialogueId = 80200243,
          GUID = "C8C5D6A0",
          NextDialogue = 80200244,
          SpeakNpcId = 790054
        },
        [80200244] = {
          Content = "我这个做姐姐的惯爱嘴欠，先甘拜下风啦。",
          DialogueId = 80200244,
          GUID = "C8C5D6CA",
          NextDialogue = 80200245,
          SpeakNpcId = 790054
        },
        [80200245] = {
          Content = "那么，扶疏的熟人！姐姐有件事情拜托，看在扶疏的面子上，你一定会答应我的吧！",
          DialogueId = 80200245,
          GUID = "C8C5D6F4",
          NextDialogue = 80200246,
          SpeakNpcId = 790054
        },
        [80200246] = {
          Content = "愿闻其详。",
          DialogueId = 80200246,
          GUID = "C8C5D71E",
          NextDialogue = 80200247,
          SpeakNpcId = 790008
        },
        [80200247] = {
          Content = "可不可以帮我找一下送给扶疏的道歉礼物？",
          DialogueId = 80200247,
          GUID = "C8C5D748",
          NextDialogue = 80200248,
          SpeakNpcId = 790054
        },
        [80200248] = {
          Content = "离这里不远的水域中，常有寿星乌贼出没，帮我钓些来，不难的吧！",
          DialogueId = 80200248,
          GUID = "C8C5D772",
          SpeakNpcId = 790054
        },
        [80200301] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          Content = "哇……真的钓到了，好厉害。全能如我，坐在那里一天也未必能钓上来一条……",
          DialogueId = 80200301,
          GUID = "C8C5E5E2",
          NextDialogue = 80200302,
          SpeakNpcId = 790054
        },
        [80200302] = {
          Content = "并非全能。",
          DialogueId = 80200302,
          GUID = "C8C5E60C",
          NextDialogue = 80200303,
          SpeakNpcId = 790008
        },
        [80200303] = {
          Content = "扶疏给我看过你的画，很抽象。",
          DialogueId = 80200303,
          GUID = "C8C5E636",
          NextDialogue = 80200304,
          SpeakNpcId = 790008
        },
        [80200304] = {
          Content = "……你们是不是有点太熟了，她怎么把此等家丑也告诉你？",
          DialogueId = 80200304,
          GUID = "C8C5E660",
          NextDialogue = 80200305,
          SpeakNpcId = 790054
        },
        [80200305] = {
          Content = "咳……但我从来不知道扶疏喜欢寿星乌贼。",
          DialogueId = 80200305,
          GUID = "C8C5E68A",
          NextDialogue = 80200306,
          SpeakNpcId = 790008
        },
        [80200306] = {
          Content = "并非喜欢。",
          DialogueId = 80200306,
          GUID = "C8C5E6B4",
          NextDialogue = 80200307,
          SpeakNpcId = 790054
        },
        [80200307] = {
          Content = "扶疏最讨厌寿星乌贼，小时候被吓哭过呢！",
          DialogueId = 80200307,
          GUID = "C8C5E6DE",
          NextOptions = {
            [1] = 802003071,
            [2] = 802003072,
            [3] = 802003073
          },
          SpeakNpcId = 790054
        },
        [80200311] = {
          Content = "其实我最近已经和她吵架好几次了，你应该知道我们吵架的缘由吧？",
          DialogueId = 80200311,
          GUID = "C8C5E786",
          NextDialogue = 80200312,
          SpeakNpcId = 790054
        },
        [80200312] = {
          Content = "无非就是我想要钻研新的治病救人的办法，而她认为要坚守枯荣之术。",
          DialogueId = 80200312,
          GUID = "C8C5E7B0",
          NextDialogue = 80200313,
          SpeakNpcId = 790054
        },
        [80200313] = {
          Content = "老实说，她有她的道理，我的方法一是前途未卜，不知成效，二是背离了大风九章……",
          DialogueId = 80200313,
          GUID = "C8C5E7DA",
          NextDialogue = 80200314,
          SpeakNpcId = 790054
        },
        [80200314] = {
          Content = "我与我的研究最后究竟是怎样的结局，谁也不知道。",
          DialogueId = 80200314,
          GUID = "C8C5E804",
          NextDialogue = 80200315,
          SpeakNpcId = 790054
        },
        [80200315] = {
          Content = "但有一件事我可以确定，那就是滥用枯荣之术，扶疏妹妹一定会英年早逝吧。",
          DialogueId = 80200315,
          GUID = "C8C5E82E",
          NextDialogue = 80200316,
          SpeakNpcId = 790054
        },
        [80200316] = {
          Content = "而我……不想看到这个局面，所以我绝不会让步，我们的架也只能一直吵下去了。",
          DialogueId = 80200316,
          GUID = "C8C5E858",
          NextDialogue = 80200317,
          SpeakNpcId = 790054
        },
        [80200317] = {
          Content = "唉，摊上这么一个不知姐姐苦心的妹妹，就算是得由我来道歉，我也不会让她好过的！",
          DialogueId = 80200317,
          GUID = "C8C5E882",
          NextDialogue = 80200318,
          SpeakNpcId = 790054
        },
        [80200318] = {
          Content = "但我已经不被允许靠近她了，这些小可爱就交由你来转赠吧！她那么信任你，肯定毫无防备，说不定还会像小时候一样被吓哭哦。",
          DialogueId = 80200318,
          GUID = "C8C5E8AC",
          NextOptions = {
            [1] = 80200319
          },
          SpeakNpcId = 790054
        },
        [80200319] = {
          Content = "寿星乌贼……",
          DialogueId = 80200319,
          GUID = "C8C5E8D6",
          NextDialogue = 80200320
        },
        [80200320] = {
          Content = "你只是想拐弯抹角地告诉她，“希望你能长命百岁”吧？",
          DialogueId = 80200320,
          GUID = "C8C5E900",
          NextDialogue = 80200321,
          SpeakNpcId = 790008
        },
        [80200321] = {
          Content = "呃……看破不说破嘛，这种小心思说出来就没劲儿了。我还想看扶疏生气的样子呢！",
          DialogueId = 80200321,
          GUID = "C8C5E92A",
          NextDialogue = 80200322,
          SpeakNpcId = 790054
        },
        [80200322] = {
          Content = "快去！快去！",
          DialogueId = 80200322,
          GUID = "C8C5E954",
          SpeakNpcId = 790054
        },
        [80200323] = {
          Content = "出幻境，回到采药任务点1，和扶疏站桩。",
          DialogueId = 80200323,
          GUID = "C8C5E97E"
        },
        [80200324] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          Content = "你醒了！",
          DialogueId = 80200324,
          GUID = "C8C5E9A8",
          NextDialogue = 80200325,
          SpeakNpcId = 790053
        },
        [80200325] = {
          Content = "才过去三四分钟，但实在牵肠挂肚……我都怀疑是否记错了书上的内容，莫非毒性比我想象中大？",
          DialogueId = 80200325,
          GUID = "C8C5E9D2",
          NextDialogue = 80200326,
          SpeakNpcId = 790053
        },
        [80200326] = {
          Content = "我想给你用枯荣之术，但又怕没等我施术完毕，你就又好了……",
          DialogueId = 80200326,
          GUID = "C8C5E9FC",
          NextDialogue = 80200327,
          SpeakNpcId = 790053
        },
        [80200327] = {
          Content = "噗嗤……你们姐妹俩还真是像……",
          DialogueId = 80200327,
          GUID = "C8C5EA26",
          NextDialogue = 80200328,
          SpeakNpcId = 790008
        },
        [80200328] = {
          Content = "你也……见到家姐了？",
          DialogueId = 80200328,
          GUID = "C8C5EA50",
          NextDialogue = 80200329,
          SpeakNpcId = 790053
        },
        [80200329] = {
          Content = "没错，你记得吗，她同你吵架，送了你最讨厌的寿星乌贼做道歉礼物。",
          DialogueId = 80200329,
          GUID = "C8C5EA7A",
          NextDialogue = 80200330,
          SpeakNpcId = 790008
        },
        [80200330] = {
          Content = "……我都已经忘记了。那真是，很久很久之前的往事了。",
          DialogueId = 80200330,
          GUID = "C8C5EAA4",
          NextDialogue = 80200331,
          SpeakNpcId = 790053
        },
        [80200331] = {
          Content = "你接受她的道歉了吗？",
          DialogueId = 80200331,
          GUID = "C8C5EACE",
          NextDialogue = 80200332,
          SpeakNpcId = 790008
        },
        [80200332] = {
          Content = "呵呵……没有，我和她又吵了一架。我虽然不后悔……",
          DialogueId = 80200332,
          GUID = "C8C5EAF8",
          NextDialogue = 80200333,
          SpeakNpcId = 790053
        },
        [80200333] = {
          Content = "但或许，现在的我会愿意接受那条寿星乌贼。",
          DialogueId = 80200333,
          GUID = "C8C5EB22",
          NextDialogue = 80200334,
          SpeakNpcId = 790053
        },
        [80200334] = {
          Content = "……但也只是或许，我不喜欢多足生物，这点千真万确。",
          DialogueId = 80200334,
          GUID = "C8C5EB4C",
          NextDialogue = 80200335,
          SpeakNpcId = 790053
        },
        [80200335] = {
          Content = "其实……不应该让你看到这些往事，过去的人都已经作古，看到这些徒惹伤怀，也是无益。",
          DialogueId = 80200335,
          GUID = "C8C5EB76",
          NextDialogue = 80200336,
          SpeakNpcId = 790053
        },
        [80200336] = {
          Content = "只是这枯荣阁是我们从小生长的地方，恐怕所有的音容草里，都存放着我们的过往。",
          DialogueId = 80200336,
          GUID = "C8C5EBA0",
          NextDialogue = 80200337,
          SpeakNpcId = 790053
        },
        [80200337] = {
          Content = "所以下一次，还是由我来尝试吧，好吗？",
          DialogueId = 80200337,
          GUID = "C8C5EBCA",
          NextOptions = {
            [1] = 802003371,
            [2] = 802003372
          },
          SpeakNpcId = 790053
        },
        [80200339] = {
          Content = "谢谢。",
          DialogueId = 80200339,
          GUID = "C8C5EC1E",
          NextDialogue = 80200342,
          SpeakNpcId = 790054
        },
        [80200341] = {
          Content = "呵呵，下次相约之时，我再讲给你听吧。",
          DialogueId = 80200341,
          GUID = "C8C5EC72",
          NextDialogue = 80200342,
          SpeakNpcId = 790054
        },
        [80200342] = {
          Content = "好，拿去寻找下一个地方吧。",
          DialogueId = 80200342,
          GUID = "C8C5EC9C",
          SpeakNpcId = 790053
        },
        [80200343] = {
          Content = "转场，枯荣阁野外",
          DialogueId = 80200343,
          GUID = "C8C5ECC6"
        },
        [80200344] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          Content = "找到了。",
          DialogueId = 80200344,
          GUID = "C8C5ECF0",
          NextDialogue = 80200345,
          SpeakNpcId = 790053
        },
        [80200345] = {
          Content = "要不要猜一猜，这是音容草，还是怀梦草呢？",
          DialogueId = 80200345,
          GUID = "C8C5ED1A",
          NextOptions = {
            [1] = 802003451,
            [2] = 802003452
          },
          SpeakNpcId = 790053
        },
        [80200348] = {
          Content = "看着没什么殊异之处，但摸在手里，确实有些极其微妙的差别……我猜这就是我们要找的怀梦草。",
          DialogueId = 80200348,
          GUID = "C8C5ED98",
          NextDialogue = 80200349,
          SpeakNpcId = 790053
        },
        [80200349] = {
          Content = "如果不是连续失败两次，我恐怕永远不会有这样的发现。",
          DialogueId = 80200349,
          GUID = "C8C5EDC2",
          NextDialogue = 80200350,
          SpeakNpcId = 790053
        },
        [80200350] = {
          Content = "第一个发现这两种植物的人是怎么做到的？难道她也像我们一样，一点一点试出来的？",
          DialogueId = 80200350,
          GUID = "C8C5EDEC",
          NextDialogue = 80200351,
          SpeakNpcId = 790008
        },
        [80200351] = {
          Content = "呵……是呀，她是怎么做到的呢？",
          DialogueId = 80200351,
          GUID = "C8C5EE16",
          NextDialogue = 80200352,
          SpeakNpcId = 790053
        },
        [80200352] = {
          Content = "想必，一定经过无数次危险，与无数次不眠不休的钻研吧，即使不被理解，即使历经伤痛，她也从来没有放弃过。",
          DialogueId = 80200352,
          GUID = "C8C5EE40",
          NextDialogue = 80200353,
          SpeakNpcId = 790053
        },
        [80200353] = {
          Content = "一切都是为了从无数个一百年前，一直流传到今天的那个悬壶济世的理想。",
          DialogueId = 80200353,
          GUID = "C8C5EE6A",
          NextDialogue = 80200354,
          SpeakNpcId = 790053
        },
        [80200354] = {
          Content = "其实，还有一件事忘了告诉你。我刚才遇见的扶风说，匍地枝与隙中花更合适治疗多梦少眠。",
          DialogueId = 80200354,
          GUID = "C8C5EE94",
          NextDialogue = 80200355,
          SpeakNpcId = 790008
        },
        [80200355] = {
          Content = "怀梦草虽能助眠，但会在梦中看到无法忘怀之事。",
          DialogueId = 80200355,
          GUID = "C8C5EEBE",
          NextDialogue = 80200356,
          SpeakNpcId = 790008
        },
        [80200356] = {
          Content = "也就是说，我不需要怀梦草了，但即使如此，你也要尝试吗？",
          DialogueId = 80200356,
          GUID = "C8C5EEE8",
          NextDialogue = 80200357,
          SpeakNpcId = 790008
        },
        [80200357] = {
          Content = "扶疏没有说话，只是照旧将那叶尖放入口中。这一次，没有不安与责难，你听到了均匀的呼吸声，以及一句浅浅的梦呓——",
          DialogueId = 80200357,
          GUID = "C8C5EF12",
          IsBlack = 1,
          NextDialogue = 80200358
        },
        [80200358] = {
          Content = "唉……下一次，换个道歉礼物吧。",
          DialogueId = 80200358,
          GUID = "C8C5EF3C",
          SpeakNpcId = 790053
        },
        [88888801] = {
          DialogueId = 88888801,
          DialoguePanelType = "None",
          Duration = 5,
          GUID = "DE8616EA",
          Scripts = "SEQ{SetRotation{SetRotationDescription{\"888888:n(0)\"}},PlayAnimation{ActorId{0},AnimationId{\"Cat_Interactive01\"}}}",
          SpeakNpcId = 888888,
          bAllowClickSkipScript = false
        },
        [90000001] = {
          Content = "年轻人，你之前记挂着的那个好东西，老朽瞧着材料已经齐全了。",
          DialogueId = 90000001,
          Duration = 3,
          GUID = "E14E392A",
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Tiejiang"
        },
        [90000011] = {
          Content = "强大的刻印！",
          DialogueId = 90000011,
          GUID = "E14E3ACE"
        },
        [90000012] = {
          Content = "强大的宝物！",
          DialogueId = 90000012,
          GUID = "E14E3AF8"
        },
        [90000013] = {
          Content = "我全都要！",
          DialogueId = 90000013,
          GUID = "E14E3B22"
        },
        [90000021] = {
          Content = "选择一个中稀有度的刻印",
          DialogueId = 90000021,
          GUID = "E14E3C72"
        },
        [90000022] = {
          Content = "随机获得一个高稀有度的刻印",
          DialogueId = 90000022,
          GUID = "E14E3C9C"
        },
        [90000031] = {
          Content = "随机获得两个低稀有度的宝物",
          DialogueId = 90000031,
          GUID = "E14E3E16"
        },
        [90000032] = {
          Content = "随机获得一个任意稀有度的宝物",
          DialogueId = 90000032,
          GUID = "E14E3E40"
        },
        [90000041] = {
          Content = "你什么也没有得到",
          DialogueId = 90000041,
          GUID = "E14E3FBA"
        },
        [90000051] = {
          Content = "伟大的刻印赠礼人啊，我需要至高无上的您的帮助！",
          DialogueId = 90000051,
          GUID = "E14E415E"
        },
        [90000052] = {
          Content = "选择一个低稀有度的刻印",
          DialogueId = 90000052,
          GUID = "E14E4188"
        },
        [90000053] = {
          Content = "随机获得一个中稀有度的刻印",
          DialogueId = 90000053,
          GUID = "E14E41B2"
        },
        [90000061] = {
          Content = "伟大的宝物赠礼人啊，我需要至高无上的您的帮助！",
          DialogueId = 90000061,
          GUID = "E14E4302"
        },
        [90000062] = {
          Content = "随机获得一个低稀有度的宝物",
          DialogueId = 90000062,
          GUID = "E14E432C"
        },
        [90010101] = {
          Content = "嘿咻、嘿咻……",
          DialogueId = 90010101,
          Duration = 3,
          GUID = "E154B232",
          SpeakNpcId = 900001,
          VoiceName = "voice/$Locale$/char/Bai/vo_forge_05"
        },
        [90010201] = {
          Camera = "192.657425,-208.698975,78.959908,0.000142,-5.798523,129.981186,35.0,250.0,false,DoNotOverride,2.8",
          Content = "最近有没有找到什么好东西？给老朽看看，说不定能锻造出一把很特别的武器！",
          DialogueId = 90010201,
          GUID = "E154C29A",
          SpeakNpcId = 900001,
          VoiceName = "voice/$Locale$/char/Bai/vo_forge_02"
        },
        [90010301] = {
          Camera = "192.657425,-208.698975,78.959908,0.000142,-5.798523,129.981186,35.0,250.0,false,DoNotOverride,2.8",
          Content = "是老朽的好友，虽然看起来个子小，但是力气可不小，老朽便让它帮忙给炉火鼓风。",
          DialogueId = 90010301,
          GUID = "E154D302",
          SpeakNpcId = 900001
        },
        [90020101] = {
          Content = "早上好……",
          DialogueId = 90020101,
          Duration = 3,
          GUID = "E15B1AD2",
          SpeakNpcId = 900002,
          VoiceName = "voice/$Locale$/char/Bai/vo_shop_03"
        },
        [90020201] = {
          Content = "啊！我、我才没有偷懒……咳！有什么想买的吗？",
          DialogueId = 90020201,
          GUID = "E15B2B3A",
          SpeakNpcId = 900002,
          TalkActionId = {
            [1] = "900002:Shangdian_Write_Start"
          },
          VoiceName = "voice/$Locale$/char/Bai/vo_shop_01"
        },
        [90020301] = {
          Content = "聊点别的",
          DialogueId = 90020301,
          GUID = "E15B3BA2"
        },
        [90020302] = {
          Content = "再见",
          DialogueId = 90020302,
          GUID = "E15B3BCC"
        },
        [90030000] = {
          Content = "{性别：他|她}从来都不是一只甘愿困在笼中的鸟。我知道的，总有一天{性别：他|她}会离开那座岛，飞向更远的天空。但我不知道的是，这对我们来说究竟是幸运还是不幸。",
          DialogueId = 90030000,
          GUID = "E15B3BCB",
          SpeakNpcId = 81101,
          VoiceName = "voice/$Locale$/char/Heitao/vo_idle"
        },
        [90030001] = {
          Content = "你回来了。今天打算做什么？还是在家休息？",
          DialogueId = 90030001,
          GUID = "E161730A",
          LookAt = {
            [1] = "81101:n(0)",
            [2] = "0:n(81101)"
          },
          NextOptions = {
            [1] = 900300011,
            [2] = 900300013,
            [3] = 900300014,
            [4] = 900300015,
            [5] = 900300016,
            [6] = 900300018
          },
          RandomOptionNum = 3,
          SpeakNpcId = 81101,
          TalkActionId = {
            [1] = "81101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_welcome",
          bForbidSkipOptions = true
        },
        [90030002] = {
          Content = "聊点别的",
          DialogueId = 90030002,
          GUID = "90030002.0",
          NextDialogue = 90030001
        },
        [90030003] = {
          Content = "再见",
          DialogueId = 90030003,
          GUID = "90030003.0"
        },
        [90030101] = {
          Content = "愿望？我……没有什么特别的愿望。每个早上都看见你笑着，就足够了。",
          DialogueId = 90030101,
          GUID = "E1618372",
          LookAt = {
            [1] = "81101:n(0)",
            [2] = "0:n(81101)"
          },
          NextDialogue = 90030103,
          SpeakNpcId = 81101,
          TalkActionId = {
            [1] = "81101:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_02_1"
        },
        [90030103] = {
          Content = "好，我会做到。",
          DialogueId = 90030103,
          GUID = "E16183C6",
          NextDialogue = 90030104,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "81101:Explain02_End"
          }
        },
        [90030104] = {
          Content = "也不用勉强自己。如果你觉得不开心，就来靠着我说会儿话吧。或者，如果你不想说的话，我们就一起安静地待一会儿。",
          DialogueId = 90030104,
          GUID = "E16183F0",
          NextOptions = {
            [1] = 90030002,
            [2] = 90030003
          },
          SpeakNpcId = 81101,
          TalkActionId = {
            [1] = "81101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90030301] = {
          Content = "和净界岛不一样，这座城的每一天都在下雪。不过，还好你有这么一个温暖的住处。和我们在净界岛上的破房子相比，这个地方算得上奢侈了。",
          DialogueId = 90030301,
          GUID = "E161A442",
          LookAt = {
            [1] = "81101:n(0)",
            [2] = "0:n(81101)"
          },
          NextDialogue = 90030303,
          SpeakNpcId = 81101,
          TalkActionId = {
            [1] = "81101:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_03_1"
        },
        [90030303] = {
          Content = "可我还是觉得有点冷。",
          DialogueId = 90030303,
          GUID = "E161A443",
          NextDialogue = 90030304,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "81101:Think_End"
          }
        },
        [90030304] = {
          Content = "以前每到冬天，你的手都会变得很凉……来，手给我，我帮你暖一暖。",
          DialogueId = 90030304,
          GUID = "E161A46C",
          NextOptions = {
            [1] = 90030002,
            [2] = 90030003
          },
          SpeakNpcId = 81101,
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90030401] = {
          Content = "为什么呢……我也不知道。不妨就认为这是一个美好的梦吧——就当作我还在你身边，像从前一样。",
          DialogueId = 90030401,
          GUID = "E161B4AA",
          LookAt = {
            [1] = "81101:n(0)",
            [2] = "0:n(81101)"
          },
          NextDialogue = 90030403,
          SpeakNpcId = 81101,
          TalkActionId = {
            [1] = "81101:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_01_1"
        },
        [90030403] = {
          Content = "我想再次见到你。",
          DialogueId = 90030403,
          GUID = "E161B4FE",
          NextDialogue = 90030404,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "81101:Talk02_End"
          }
        },
        [90030404] = {
          Content = "嗯，我也想，非常想……但愿有一天，我们能够真正重逢。",
          DialogueId = 90030404,
          GUID = "E161B528",
          NextOptions = {
            [1] = 90030002,
            [2] = 90030003
          },
          SpeakNpcId = 81101,
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_01_2",
          bForbidSkipOptions = true
        },
        [90030501] = {
          Content = "应该怎么说呢，那个地方像一座钢铁做的城市……不对，应该说更像牢狱吧。很小的时候，我是在那儿度过的。",
          DialogueId = 90030501,
          GUID = "E161C512",
          LookAt = {
            [1] = "81101:n(0)",
            [2] = "0:n(81101)"
          },
          NextDialogue = 90030503,
          SpeakNpcId = 81101,
          TalkActionId = {
            [1] = "81101:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_04_1"
        },
        [90030503] = {
          Content = "后来一个人带着我逃走了。被她一同带到净界岛的，还有你。只是关于她的事，我不能说更多了……抱歉。我答应过她不说。",
          DialogueId = 90030503,
          GUID = "E161C566",
          NextDialogue = 90030504,
          SpeakNpcId = 81101,
          TalkActionId = {
            [1] = "81101:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_04_2"
        },
        [90030504] = {
          Content = "……在净界岛的日子是那么平静，我差点以为我们会一辈子这样生活下去。但那天，他们再次出现的时候，我才发觉我从未真正逃离那个牢狱。",
          DialogueId = 90030504,
          GUID = "E161C590",
          NextOptions = {
            [1] = 90030002,
            [2] = 90030003
          },
          SpeakNpcId = 81101,
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90030601] = {
          Content = "是有些吵闹，不过，我并不讨厌。你结识了许多新的朋友，这是好事，我为你高兴。",
          DialogueId = 90030601,
          GUID = "E161D57A",
          LookAt = {
            [1] = "81101:n(0)",
            [2] = "0:n(81101)"
          },
          NextDialogue = 90030603,
          SpeakNpcId = 81101,
          TalkActionId = {
            [1] = "81101:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_05_1"
        },
        [90030603] = {
          Content = "这样一来，就算我不在你身边，你也不会觉得孤单了。",
          DialogueId = 90030603,
          GUID = "E161D5A4",
          NextOptions = {
            [1] = 90030002,
            [2] = 90030003
          },
          SpeakNpcId = 81101,
          TalkActionId = {
            [1] = "81101:Sigh_End"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_05_2",
          bForbidSkipOptions = true
        },
        [90030801] = {
          Content = "那就枕在我身上歇息一会儿吧，像从前那样。",
          DialogueId = 90030801,
          GUID = "E161F64A",
          LookAt = {
            [1] = "81101:n(0)",
            [2] = "0:n(81101)"
          },
          NextOptions = {
            [1] = 90030002,
            [2] = 90030003
          },
          SpeakNpcId = 81101,
          TalkActionId = {
            [1] = "81101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_06_1",
          bForbidSkipOptions = true
        },
        [90030901] = {
          Content = "这些年来，我有好好照顾{性别：他/她}，也有好好保重自己，就像我答应你的……你可以像我小时候那样，摸摸我的头，夸夸我吗？还有，这一次，再也不要离开我们了……好吗？",
          DialogueId = 90030901,
          GUID = "E16206B2",
          SpeakNpcId = 81101,
          VoiceName = "voice/$Locale$/char/Heitao/vo_companio_01"
        },
        [90031001] = {
          Content = "松露小姐，你的……猪，我可以摸一摸吗？摸一下就好。请你帮我按住它，我怕它跑远了，小动物看到我总会跑得远远的。",
          DialogueId = 90031001,
          GUID = "E162171A",
          NextDialogue = 90031002,
          SpeakNpcId = 81101,
          VoiceName = "voice/$Locale$/char/Heitao/vo_companio_02_1"
        },
        [90031002] = {
          Content = "谢谢你……啊，暖暖的，毛茸茸的，真好啊……",
          DialogueId = 90031002,
          GUID = "E1621744",
          SpeakNpcId = 81101,
          VoiceName = "voice/$Locale$/char/Heitao/vo_companio_02_2"
        },
        [90031101] = {
          Content = "我不是军团的“零号”，更不是你手中随意拨弄的玩具。你可以离开，或者带着我的尸骸回去。",
          DialogueId = 90031101,
          GUID = "E1622782",
          SpeakNpcId = 81101,
          VoiceName = "voice/$Locale$/char/Heitao/vo_companio_03"
        },
        [90031201] = {
          Content = "听说你是位优秀的美食家，可以给我看看你的食谱吗？{nickname}总说你做的饭很好吃，听起来不像客套话，而是发自内心的夸奖。",
          DialogueId = 90031201,
          GUID = "E16237EA",
          NextDialogue = 90031202,
          SpeakNpcId = 81101,
          VoiceName = "voice/$Locale$/char/Heitao/vo_companio_04_1"
        },
        [90031202] = {
          Content = "……你用的食材，也只是最普通不过的食物而已？那为什么……",
          DialogueId = 90031202,
          GUID = "E1623814",
          SpeakNpcId = 81101,
          VoiceName = "voice/$Locale$/char/Heitao/vo_companio_04_2"
        },
        [90040000] = {
          Content = "你留在这里，是为了和我一起度过一段缱绻的二人时光吗……呵呵，我已经开始期待了。",
          DialogueId = 90040000,
          GUID = "E167DBA9",
          SpeakNpcId = 82101,
          VoiceName = "voice/$Locale$/char/Shuimu/vo_idle"
        },
        [90040001] = {
          Content = "我从睡醒就一直在这里等着，体内的毒液都快干涸了……不过还好你来了，现在它们又开始因为兴奋而跳动。你……可以再靠近一些吗？",
          DialogueId = 90040001,
          GUID = "E167DBAA",
          LookAt = {
            [1] = "82101:n(0)",
            [2] = "0:n(82101)"
          },
          NextOptions = {
            [1] = 900400011,
            [2] = 900400012,
            [3] = 900400013,
            [4] = 900400014,
            [5] = 900400015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 82101,
          TalkActionId = {
            [1] = "82101:Give"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_welcome",
          bForbidSkipOptions = true
        },
        [90040002] = {
          Content = "聊点别的",
          DialogueId = 90040002,
          GUID = "90040002.0",
          NextDialogue = 90040001
        },
        [90040003] = {
          Content = "再见",
          DialogueId = 90040003,
          GUID = "90040003.0"
        },
        [90040101] = {
          Content = "是的，我喜欢雨天，我读了许多遍的小说里，爱的邂逅总是在下雨天自然发生。",
          DialogueId = 90040101,
          GUID = "E167EC12",
          LookAt = {
            [1] = "82101:n(0)",
            [2] = "0:n(82101)"
          },
          NextDialogue = 90040103,
          SpeakNpcId = 82101,
          TalkActionId = {
            [1] = "82101:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_01_1"
        },
        [90040103] = {
          Content = "下雨天应该更适合家里睡觉吧，为什么会有邂逅？",
          DialogueId = 90040103,
          GUID = "E167EC13",
          NextDialogue = 90040104,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "82101:Explain02_End"
          }
        },
        [90040104] = {
          Content = "你留心观察过那些躲雨的人吗？他们在屋檐下不期而遇，潮湿的气息让草木的芳香更加馥郁，小心的试探使爱意缓缓流动……",
          DialogueId = 90040104,
          GUID = "E167EC3C",
          NextDialogue = 90040105,
          SpeakNpcId = 82101,
          TalkActionId = {
            [1] = "82101:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_01_2"
        },
        [90040105] = {
          Content = "呵呵……等到下个雨天，您同我一起出去瞧瞧，就会明白的。",
          DialogueId = 90040105,
          GUID = "E167EC3B",
          NextOptions = {
            [1] = 90040002,
            [2] = 90040003
          },
          SpeakNpcId = 82101,
          TalkActionId = {
            [1] = "82101:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_01_3",
          bForbidSkipOptions = true
        },
        [90040201] = {
          Content = "啊呀，难得你居然会和我主动谈论“爱”。",
          DialogueId = 90040201,
          GUID = "E167FC7A",
          LookAt = {
            [1] = "82101:n(0)",
            [2] = "0:n(82101)"
          },
          NextDialogue = 90040203,
          SpeakNpcId = 82101,
          TalkActionId = {
            [1] = "82101:Shock_Start"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_02_1"
        },
        [90040203] = {
          Content = "应该如何描述呢……嗯，就像这香薰中的水：亲吻拥抱每一剂原料，吞噬汲取它们的气味，并最终在长久的馥郁中合为一体。",
          DialogueId = 90040203,
          GUID = "E167FCA4",
          NextDialogue = 90040204,
          SpeakNpcId = 82101,
          TalkActionId = {
            [1] = "82101:Shock_End"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_02_2"
        },
        [90040204] = {
          Content = "听起来是两个人每天腻在一起？",
          DialogueId = 90040204,
          GUID = "E167FCA5",
          NextDialogue = 90040205,
          SpeakNpcId = 100001
        },
        [90040205] = {
          Content = "不止哦。我想要的爱情，是彻底的交融，没有彼此之分……即使一方生命终结了，也会成为香料园中的花泥；从中绽放的花朵将变成香薰，永远萦绕着另一个。",
          DialogueId = 90040205,
          GUID = "E167FCA6",
          NextOptions = {
            [1] = 90040002,
            [2] = 90040003
          },
          SpeakNpcId = 82101,
          TalkActionId = {
            [1] = "82101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_02_3",
          bForbidSkipOptions = true
        },
        [90040301] = {
          Content = "特别？啊，是的……从小到大，身边可有不少人视我为“怪物”呢。",
          DialogueId = 90040301,
          GUID = "E1680CE2",
          LookAt = {
            [1] = "82101:n(0)",
            [2] = "0:n(82101)"
          },
          NextDialogue = 90040303,
          SpeakNpcId = 82101,
          TalkActionId = {
            [1] = "82101:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_03_1"
        },
        [90040303] = {
