          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextDialogue = 90060302,
          SpeakNpcId = 83201,
          TalkActionId = {
            [1] = "83201:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_03_1"
        },
        [90060302] = {
          Content = "每休息一分，都会让正义迟到一分——而当正义迟迟不来时，混乱与弱肉强食就会代替法条成为新的规则。",
          DialogueId = 90060302,
          GUID = "E174DE23",
          NextDialogue = 90060303,
          SpeakNpcId = 83201,
          TalkActionId = {
            [1] = "83201:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_03_2"
        },
        [90060303] = {
          Content = "如果监狱里的犯人越来越少，你会不会轻松一点。",
          DialogueId = 90060303,
          GUID = "E174DE24",
          NextDialogue = 90060304,
          SpeakNpcId = 100001
        },
        [90060304] = {
          Content = "确实有学者设想过没有罪犯的世界。如果真的有那天，我也将不复存在，因为正是罪恶造就了典狱长。但是在那之前，我会尽力维护好现存的秩序。",
          DialogueId = 90060304,
          GUID = "E174DE25",
          NextOptions = {
            [1] = 90060002,
            [2] = 90060003
          },
          SpeakNpcId = 83201,
          TalkActionId = {
            [1] = "83201:Agree"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_03_3",
          bForbidSkipOptions = true
        },
        [90060401] = {
          Content = "正义？正义就是权力约束欲望，力量桎梏罪孽，强者鞭挞恶徒。",
          DialogueId = 90060401,
          GUID = "E174EE8A",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextDialogue = 90060402,
          SpeakNpcId = 83201,
          TalkActionId = {
            [1] = "83201:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_04_1"
        },
        [90060402] = {
          Content = "这样的规则也太绝对了吧。",
          DialogueId = 90060402,
          GUID = "E174EE8B",
          NextDialogue = 90060403,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "83201:Explain01_End"
          }
        },
        [90060403] = {
          Content = "哼，绝对？不然呢，天真的小朋友，难道指望人人都手拉手过家家？绝对的力量、绝对的秩序，这就是我的正义！",
          DialogueId = 90060403,
          GUID = "E174EE8C",
          NextOptions = {
            [1] = 90060002,
            [2] = 90060003
          },
          SpeakNpcId = 83201,
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90060501] = {
          Content = "帝国的罪犯还在满大街地跑，身为典狱长哪有什么闲暇时间。只能在忙里偷闲的时候，喝几杯烈酒。",
          DialogueId = 90060501,
          GUID = "E174FEF2",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextDialogue = 90060502,
          SpeakNpcId = 83201,
          TalkActionId = {
            [1] = "83201:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_05_1"
        },
        [90060502] = {
          Content = "什么！你会喝酒？",
          DialogueId = 90060502,
          GUID = "E174FF1C",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextDialogue = 90060503,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "83201:Talk01_End"
          }
        },
        [90060503] = {
          Content = "怎么，很惊讶？消遣而已：审讯时总会听到各种酒的名字，就开始好奇，这到底是什么邪恶药水，总是和犯罪沾边，于是偶尔会来上一些。",
          DialogueId = 90060503,
          GUID = "E174FF1D",
          NextDialogue = 90060504,
          SpeakNpcId = 83201,
          TalkActionId = {
            [1] = "83201:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_05_2"
        },
        [90060504] = {
          Content = "喝得越多，我越是确信，邪恶的并不是酒。",
          DialogueId = 90060504,
          GUID = "E174FF1E",
          NextOptions = {
            [1] = 90060002,
            [2] = 90060003
          },
          SpeakNpcId = 83201,
          TalkActionId = {
            [1] = "83201:Talk03_End"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_05_3",
          bForbidSkipOptions = true
        },
        [90060601] = {
          Content = "典狱长和军团长，都是帝国“黑暗”秩序的维护者。我们心狠手辣、声名狼藉——但是为了海伯利亚，这点恶名又算得上什么？！",
          DialogueId = 90060601,
          GUID = "E1750F5A",
          SpeakNpcId = 83201,
          VoiceName = "voice/$Locale$/char/Haier/vo_companio_01"
        },
        [90060701] = {
          Content = "又是你。",
          DialogueId = 90060701,
          GUID = "E1751FC2",
          SpeakNpcId = 83201,
          VoiceName = "voice/$Locale$/char/Haier/vo_companio_02"
        },
        [90060801] = {
          Content = "啧，西比尔的副官……那个总被指责不尽职的家伙，对吧？可惜，你那些隐藏实力的拙劣技巧瞒不过我的眼睛！藏匿锋芒混迹在军团长身边，你到底有什么居心？！",
          DialogueId = 90060801,
          GUID = "E175302A",
          SpeakNpcId = 83201,
          VoiceName = "voice/$Locale$/char/Haier/vo_companio_03"
        },
        [90070000] = {
          Content = "无事，便是好事。",
          DialogueId = 90070000,
          GUID = "E17B1589",
          SpeakNpcId = 84201,
          VoiceName = "voice/$Locale$/char/Yuming/vo_idle"
        },
        [90070001] = {
          Content = "趁着你还没有被各种律法束缚，想做什么事情，就去做吧。",
          DialogueId = 90070001,
          GUID = "E17B158A",
          LookAt = {
            [1] = "84201:n(0)",
            [2] = "0:n(84201)"
          },
          NextOptions = {
            [1] = 900700011,
            [2] = 900700012,
            [3] = 900700013,
            [4] = 900700014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 84201,
          TalkActionId = {
            [1] = "84201:Agree"
          },
          VoiceName = "voice/$Locale$/char/Yuming/vo_welcome",
          bForbidSkipOptions = true
        },
        [90070002] = {
          Content = "聊点别的",
          DialogueId = 90070002,
          GUID = "90070002.0",
          NextDialogue = 90070001
        },
        [90070003] = {
          Content = "再见",
          DialogueId = 90070003,
          GUID = "90070003.0"
        },
        [90070101] = {
          Content = "……这等闲聊，有更适合的人选吧。找那些贩卖货物的织星客吧，或者看看书也好。",
          DialogueId = 90070101,
          GUID = "E17B25F2",
          LookAt = {
            [1] = "84201:n(0)",
            [2] = "0:n(84201)"
          },
          NextDialogue = 90070102,
          SpeakNpcId = 84201,
          TalkActionId = {
            [1] = "84201:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_01_1"
        },
        [90070102] = {
          Content = "每个人眼中的世界各不相同，我是在问你的看法。",
          DialogueId = 90070102,
          GUID = "E17B25F3",
          NextDialogue = 90070103,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "84201:Talk03_End"
          }
        },
        [90070103] = {
          Content = "我平素繁忙，所以眼见多有偏狭。你若是真的好奇，与其假他人言语，不如亲自踏足那里，如何？",
          DialogueId = 90070103,
          GUID = "E17B25F4",
          NextOptions = {
            [1] = 90070002,
            [2] = 90070003
          },
          SpeakNpcId = 84201,
          TalkActionId = {
            [1] = "84201:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_01_2",
          bForbidSkipOptions = true
        },
        [90070201] = {
          Content = "《大风九章》是华胥的律法，谁都不能违抗。但倘若真要有人倒反天命，那自然要有人去收拾乱局。",
          DialogueId = 90070201,
          GUID = "E17B365A",
          LookAt = {
            [1] = "84201:n(0)",
            [2] = "0:n(84201)"
          },
          NextDialogue = 90070202,
          SpeakNpcId = 84201,
          TalkActionId = {
            [1] = "84201:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_02_1"
        },
        [90070202] = {
          Content = "那么你一定很受崇敬吧。",
          DialogueId = 90070202,
          GUID = "E17B365B",
          NextDialogue = 90070203,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "84201:Explain01_End"
          }
        },
        [90070203] = {
          Content = "……也许吧，我不常与人们闲谈，毕竟但凡需要我出手的地方，总有伤逝。大部华胥之民，是并不乐见我的。",
          DialogueId = 90070203,
          GUID = "E17B365C",
          NextOptions = {
            [1] = 90070002,
            [2] = 90070003
          },
          SpeakNpcId = 84201,
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90070301] = {
          Content = "无事可乐，自然如此。",
          DialogueId = 90070301,
          GUID = "E17B46C2",
          LookAt = {
            [1] = "84201:n(0)",
            [2] = "0:n(84201)"
          },
          NextDialogue = 90070302,
          SpeakNpcId = 84201,
          TalkActionId = {
            [1] = "84201:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_03_1"
        },
        [90070302] = {
          Content = "也许我可以分享你的烦恼。",
          DialogueId = 90070302,
          GUID = "E17B46C3",
          NextDialogue = 90070303,
          SpeakNpcId = 100001
        },
        [90070303] = {
          Content = "谢了，但是说与你听，也不过是徒然让这世上又多了一个烦恼之人，何必。",
          DialogueId = 90070303,
          GUID = "E17B46C4",
          NextOptions = {
            [1] = 90070002,
            [2] = 90070003
          },
          SpeakNpcId = 84201,
          TalkActionId = {
            [1] = "84201:Agree"
          },
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90070401] = {
          Content = "是啊，月亮很好，很好。无论前一天发生过什么，杯盘狼籍还是血溅五步，月光都能洗净一切。不管过去多久，天边的一角总是会为你留下一弯月亮。",
          DialogueId = 90070401,
          GUID = "E17B572A",
          LookAt = {
            [1] = "84201:n(0)",
            [2] = "0:n(84201)"
          },
          NextDialogue = 90070402,
          SpeakNpcId = 84201,
          TalkActionId = {
            [1] = "84201:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_04_1"
        },
        [90070402] = {
          Content = "你在想过去的事？",
          DialogueId = 90070402,
          GUID = "E17B572B",
          NextDialogue = 90070403,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "84201:Talk02_End"
          }
        },
        [90070403] = {
          Content = "不，我是与过去诀别之人，没有过去，只是今天多喝了半杯酒而已。",
          DialogueId = 90070403,
          GUID = "E17B572C",
          NextOptions = {
            [1] = 90070002,
            [2] = 90070003
          },
          SpeakNpcId = 84201,
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90070501] = {
          Content = "虽然不知道你告别了怎样的过去，但我们气息相似，保持距离吧：我并不喜欢同类。",
          DialogueId = 90070501,
          GUID = "E17B6792",
          SpeakNpcId = 84201,
          VoiceName = "voice/$Locale$/char/Yuming/vo_companio_01"
        },
        [90070601] = {
          Content = "我早已不是你的故知。世人萍水相逢本就如风过耳，放下吧。",
          DialogueId = 90070601,
          GUID = "E17B77FA",
          SpeakNpcId = 84201,
          VoiceName = "voice/$Locale$/char/Yuming/vo_companio_02"
        },
        [90070701] = {
          Content = "我羡慕你的意志与同样坚固的法条，不知道你可有过什么时刻，曾自我怀疑过。",
          DialogueId = 90070701,
          GUID = "E17B8862",
          SpeakNpcId = 84201,
          VoiceName = "voice/$Locale$/char/Yuming/vo_companio_03"
        },
        [90080000] = {
          Content = "嗯……这个自动绕后的折叠枪可以升级成连发的……火力也可以再猛一些……嗯，不错不错，下次出任务就可以更快地解决敌人，然后回家休息了。",
          DialogueId = 90080000,
          GUID = "E1817E29",
          SpeakNpcId = 84202,
          VoiceName = "voice/$Locale$/char/Landi/vo_idle"
        },
        [90080001] = {
          Content = "呼~刚睡醒的感觉好舒爽啊，你呀，也不要每天太紧绷了，任务是永远也做不完的，要懂得休息。",
          DialogueId = 90080001,
          GUID = "E1817E2A",
          LookAt = {
            [1] = "84202:n(0)",
            [2] = "0:n(84202)"
          },
          NextOptions = {
            [1] = 900800011,
            [2] = 900800012,
            [3] = 900800013,
            [4] = 900800014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 84202,
          VoiceName = "voice/$Locale$/char/Landi/vo_welcome",
          bForbidSkipOptions = true
        },
        [90080002] = {
          Content = "聊点别的",
          DialogueId = 90080002,
          GUID = "90080002.0",
          NextDialogue = 90080001
        },
        [90080003] = {
          Content = "再见",
          DialogueId = 90080003,
          GUID = "90080003.0"
        },
        [90080101] = {
          Content = "家里人？我爸妈都好多年没管过我了，也就两位姐姐偶尔会对我指手画脚，不过啊我现在进了军团，她们进不来。",
          DialogueId = 90080101,
          GUID = "E1818E92",
          LookAt = {
            [1] = "84202:n(0)",
            [2] = "0:n(84202)"
          },
          NextDialogue = 90080103,
          SpeakNpcId = 84202,
          TalkActionId = {
            [1] = "84202:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_01_1"
        },
        [90080103] = {
          Content = "听起来你的姐姐们很凶。",
          DialogueId = 90080103,
          GUID = "E1818EE6",
          NextDialogue = 90080104,
          SpeakNpcId = 100001
        },
        [90080104] = {
          Content = "不，不是的，她们都是泼可爱动人聪明贤惠温柔乐观善良积极天真烂漫落落大方的美人！不过，如果能端庄一点就更好了……",
          DialogueId = 90080104,
          GUID = "E1818F10",
          NextOptions = {
            [1] = 90080002,
            [2] = 90080003
          },
          SpeakNpcId = 84202,
          TalkActionId = {
            [1] = "84202:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_01_2",
          bForbidSkipOptions = true
        },
        [90080201] = {
          Content = "呵，你们这些不懂休息好的人有难了！听我说：床是抚慰心灵的港湾，屋顶是洗涤灵魂的圣地，午后的花园是光明降临的方向，小憩的时刻是甜蜜的交响诗……",
          DialogueId = 90080201,
          GUID = "E1819EFA",
          LookAt = {
            [1] = "84202:n(0)",
            [2] = "0:n(84202)"
          },
          NextDialogue = 90080203,
          SpeakNpcId = 84202,
          TalkActionId = {
            [1] = "84202:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_02_1"
        },
        [90080203] = {
          Content = "（转身离开。）",
          DialogueId = 90080203,
          GUID = "E1819F4E",
          NextDialogue = 90080204,
          SpeakNpcId = 100001
        },
        [90080204] = {
          Content = "……诶！你等我念完啊！",
          DialogueId = 90080204,
          GUID = "E1819F78",
          NextOptions = {
            [1] = 90080002,
            [2] = 90080003
          },
          SpeakNpcId = 84202,
          TalkActionId = {
            [1] = "84202:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90080301] = {
          Content = "她可太能使唤人了，一个人劈三份都不够用……咳，我是说，西比尔大人作为长官，对下属一向严格。",
          DialogueId = 90080301,
          GUID = "E181AF62",
          LookAt = {
            [1] = "84202:n(0)",
            [2] = "0:n(84202)"
          },
          NextDialogue = 90080303,
          SpeakNpcId = 84202,
          TalkActionId = {
            [1] = "84202:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_03_1"
        },
        [90080303] = {
          Content = "改口也没用，我已经听到了。",
          DialogueId = 90080303,
          GUID = "E181AFB6",
          NextDialogue = 90080304,
          SpeakNpcId = 100001
        },
        [90080304] = {
          Content = "哎呀，这可怎么办才好呢……要不，我请你一份下午茶，你就当什么都没有听见，怎么样？别担心，里面没有下药。",
          DialogueId = 90080304,
          GUID = "E181AFE0",
          NextOptions = {
            [1] = 90080002,
            [2] = 90080003
          },
          SpeakNpcId = 84202,
          TalkActionId = {
            [1] = "84202:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90080401] = {
          Content = "我给你设计了一个好东西，一个小型机器人偶！战斗的时候它可以跟在你后面一边摇小旗，一边大喊“加油！”“你揍人的样子真的很酷！”",
          DialogueId = 90080401,
          GUID = "E181BFCA",
          LookAt = {
            [1] = "84202:n(0)",
            [2] = "0:n(84202)"
          },
          NextDialogue = 90080403,
          SpeakNpcId = 84202,
          TalkActionId = {
            [1] = "84202:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_04_1"
        },
        [90080403] = {
          Content = "怎么样，是不是感觉浑身充满力量？等我把它做出来……",
          DialogueId = 90080403,
          GUID = "E181BFF4",
          NextDialogue = 90080404,
          SpeakNpcId = 84202,
          TalkActionId = {
            [1] = "84202:Talk01_End"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_04_2"
        },
        [90080404] = {
          Content = "（转身离开。）",
          DialogueId = 90080404,
          GUID = "E181BFF5",
          NextDialogue = 90080405,
          SpeakNpcId = 100001
        },
        [90080405] = {
          Content = "喂喂，别走啊，图纸可是我瞒着西比尔长官，用宝贵的休息时间画的——",
          DialogueId = 90080405,
          GUID = "E181BFF6",
          NextOptions = {
            [1] = 90080002,
            [2] = 90080003
          },
          SpeakNpcId = 84202,
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90080501] = {
          Content = "报告军团长，今日的工作已经安排完毕，您如果有其他的需要，可以随时下达指示。不过今日的工作已经很饱和了，您还是要注意歇息，不要再给自己增添额外的负担了。",
          DialogueId = 90080501,
          GUID = "E181D032",
          SpeakNpcId = 84202,
          VoiceName = "voice/$Locale$/char/Landi/vo_companio_01"
        },
        [90080601] = {
          Content = "上次的任务真是辛苦你了，不过我接到了一些投诉，说是你在执行任务中损坏公物，唉，你是知道我的，我这么羞涩内向，还要替你去赔不是，这也太难为我了。所以……这几个紧急任务就麻烦你代劳了，相信美丽善良和蔼可亲的琳恩小姐一定不会拒绝的吧！",
          DialogueId = 90080601,
          GUID = "E181E09A",
          SpeakNpcId = 84202,
          VoiceName = "voice/$Locale$/char/Landi/vo_companio_02"
        },
        [90080701] = {
          Content = "嗯，你怎么会……？哎呀，看来我还是休息太少，竟然都出现幻觉，能看见不存在的人了！之后向长官打个工伤报告，再休两天病假好了。",
          DialogueId = 90080701,
          GUID = "E181F102",
          SpeakNpcId = 84202,
          VoiceName = "voice/$Locale$/char/Landi/vo_companio_03"
        },
        [90090000] = {
          Content = "居然把后背轻易暴露给自己的敌人……，该说你天真还是愚蠢？",
          DialogueId = 90090000,
          GUID = "E187E6C9",
          SpeakNpcId = 84301,
          VoiceName = "voice/$Locale$/char/Xibi/vo_idle"
        },
        [90090001] = {
          Content = "看到你日复一日这样奔波努力，我就忍不住开始想象，想象你再次挑战我的那一天，让人期待。",
          DialogueId = 90090001,
          GUID = "E187E6CA",
          LookAt = {
            [1] = "84301:n(0)",
            [2] = "0:n(84301)"
          },
          NextOptions = {
            [1] = 900900011,
            [2] = 900900012,
            [3] = 900900013,
            [4] = 900900014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 84301,
          TalkActionId = {
            [1] = "84301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_welcome",
          bForbidSkipOptions = true
        },
        [90090002] = {
          Content = "聊点别的",
          DialogueId = 90090002,
          GUID = "90090002.0",
          NextDialogue = 90090001
        },
        [90090003] = {
          Content = "再见",
          DialogueId = 90090003,
          GUID = "90090003.0"
        },
        [90090101] = {
          Content = "直属于皇帝的特殊军团，执行机密的任务，以及作为战场上随时击出的铁锤。",
          DialogueId = 90090101,
          GUID = "E187F732",
          LookAt = {
            [1] = "84301:n(0)",
            [2] = "0:n(84301)"
          },
          NextDialogue = 90090103,
          SpeakNpcId = 84301,
          TalkActionId = {
            [1] = "84301:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_01_1"
        },
        [90090103] = {
          Content = "有皇帝在背后支持，难怪这么蛮横。",
          DialogueId = 90090103,
          GUID = "E187F786",
          NextDialogue = 90090104,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "84301:Talk03_End"
          }
        },
        [90090104] = {
          Content = "你误会了。没有皇帝，军团依旧是军团，但没有军团，皇冠可就要落地了。",
          DialogueId = 90090104,
          GUID = "E187F7B0",
          NextDialogue = 90090105,
          SpeakNpcId = 84301,
          TalkActionId = {
            [1] = "84301:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_01_2"
        },
        [90090105] = {
          Content = "凭这句话，我是不是可以检举你打算谋反？",
          DialogueId = 90090105,
          GUID = "E187F7DA",
          NextDialogue = 90090106,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "84301:Confident_Start"
          }
        },
        [90090106] = {
          Content = "你大可以这么做，毕竟谋逆可是重罪，然后你的状告书会立刻被逐级上报，最后呈到我的书桌上。",
          DialogueId = 90090106,
          GUID = "E187F804",
          NextOptions = {
            [1] = 90090002,
            [2] = 90090003
          },
          SpeakNpcId = 84301,
          TalkActionId = {
            [1] = "84301:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_01_3",
          bForbidSkipOptions = true
        },
        [90090201] = {
          Content = "呵，我并非忠于帝国，只是忠于理想罢了。曾有一个人为了这个理想付出了他的一切，而我要铭记与践行他的意志。",
          DialogueId = 90090201,
          GUID = "E188079A",
          LookAt = {
            [1] = "84301:n(0)",
            [2] = "0:n(84301)"
          },
          NextDialogue = 90090203,
          SpeakNpcId = 84301,
          TalkActionId = {
            [1] = "84301:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_02_1"
        },
        [90090203] = {
          Content = "你在诡辩。不管原因为何，你的所作所为就是为虎作伥。",
          DialogueId = 90090203,
          GUID = "E18807EE",
          NextDialogue = 90090204,
          SpeakNpcId = 100001
        },
        [90090204] = {
          Content = "我不否认，不过为了我想要的，我会抓紧能利用的一切，不择手段地往上爬。但我每爬一步，都离我的理想更近一步。而你，又走到了哪一步呢？",
          DialogueId = 90090204,
          GUID = "E1880818",
          NextOptions = {
            [1] = 90090002,
            [2] = 90090003
          },
          SpeakNpcId = 84301,
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90090301] = {
          Content = "没关系，我的家人很早就不在了。",
          DialogueId = 90090301,
          GUID = "E1881802",
          LookAt = {
            [1] = "84301:n(0)",
            [2] = "0:n(84301)"
          },
          NextDialogue = 90090303,
          SpeakNpcId = 84301,
          TalkActionId = {
            [1] = "84301:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_03_1"
        },
        [90090303] = {
          Content = "…………",
          DialogueId = 90090303,
          GUID = "E1881856",
          NextDialogue = 90090304,
          SpeakNpcId = 100001
        },
        [90090304] = {
          Content = "我甚至为此庆幸，这样一来我就没有了后顾之忧，只需要专心和正面与背面的敌人们厮杀。",
          DialogueId = 90090304,
          GUID = "E1881880",
          NextDialogue = 90090305,
          SpeakNpcId = 84301,
          TalkActionId = {
            [1] = "84301:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_03_2"
        },
        [90090305] = {
          Content = "情感，对于每一个踏入军团的人来说，都是破绽罢了。",
          DialogueId = 90090305,
          GUID = "E18818AA",
          NextOptions = {
            [1] = 90090002,
            [2] = 90090003
          },
          SpeakNpcId = 84301,
          TalkActionId = {
            [1] = "84301:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_03_3",
          bForbidSkipOptions = true
        },
        [90090401] = {
          Content = "当然，当面的咒骂和揶揄我已经听过不少，阴沟里的硕鼠们的抱怨只会更多。",
          DialogueId = 90090401,
          GUID = "E188286A",
          LookAt = {
            [1] = "84301:n(0)",
            [2] = "0:n(84301)"
          },
          NextDialogue = 90090403,
          SpeakNpcId = 84301,
          TalkActionId = {
            [1] = "84301:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_04_1"
        },
        [90090403] = {
          Content = "所幸，尽管这个世界有万般不公，但只要坐拥众人之上的力量，就能获得最起码的善意。",
          DialogueId = 90090403,
          GUID = "E18828BE",
          NextDialogue = 90090404,
          SpeakNpcId = 84301,
          TalkActionId = {
            [1] = "84301:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_04_2"
        },
        [90090404] = {
          Content = "那么如果你失去了力量，他们一定会落井下石。",
          DialogueId = 90090404,
          GUID = "E18828E8",
          NextDialogue = 90090405,
          SpeakNpcId = 100001
        },
        [90090405] = {
          Content = "那是自然，所以我永远不会对他们卑躬屈膝，否则，他们会立刻变成闻到血腥味的狼群。",
          DialogueId = 90090405,
          GUID = "E1882912",
          NextOptions = {
            [1] = 90090002,
            [2] = 90090003
          },
          SpeakNpcId = 84301,
          TalkActionId = {
            [1] = "84301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90090501] = {
          Content = "……你与我，是时候做个了断了。",
          DialogueId = 90090501,
          GUID = "E18838D2",
          SpeakNpcId = 84301,
          VoiceName = "voice/$Locale$/char/Xibi/vo_companio_01"
        },
        [90090601] = {
          Content = "你和我踏上的道路完全相反，曾经我也自我怀疑过，是否你是对的。可惜，你的名字只能作为败者而流传。",
          DialogueId = 90090601,
          GUID = "E188493A",
          SpeakNpcId = 84301,
          VoiceName = "voice/$Locale$/char/Xibi/vo_companio_02"
        },
        [90090701] = {
          Content = "如果您不是他的继承者……我手中的剑，早就已经贯穿了您的心脏。",
          DialogueId = 90090701,
          GUID = "E18859A2",
          SpeakNpcId = 84301,
          VoiceName = "voice/$Locale$/char/Xibi/vo_companio_03"
        },
        [90090801] = {
          Content = "你的伪装越是完美，就说明你的獠牙在暗地里打磨地越发锋锐，我等着你脱缰的那一天，亲手敲断你的大牙。",
          DialogueId = 90090801,
          GUID = "E1886A0A",
          SpeakNpcId = 84301,
          VoiceName = "voice/$Locale$/char/Xibi/vo_companio_04"
        },
        [90091001] = {
          Content = "近期的任务说明、作战计划、后勤运输、损失条目都整理好了吗。\n好，那今天再和我把对外宣传标语、对内案例分析、对皇帝的定期报告以及佩剑炼金院新武器的测试数据做完。工作，可不能叫额外的负担。",
          DialogueId = 90091001,
          GUID = "E1888ADA",
          SpeakNpcId = 84301,
          VoiceName = "voice/$Locale$/char/Xibi/vo_companio_05"
        },
        [90100000] = {
          Content = "什么都不做，只是就这样看着大家，就感觉过得好快好快……真希望时间能走慢一点儿呀。",
          DialogueId = 90100000,
          GUID = "E18E4F69",
          SpeakNpcId = 85301,
          VoiceName = "voice/$Locale$/char/Saiqi/vo_idle"
        },
        [90100001] = {
          Content = "太好了，今天我还在这儿。而且，你也在这儿……",
          DialogueId = 90100001,
          GUID = "E18E4F6A",
          LookAt = {
            [1] = "85301:n(0)",
            [2] = "0:n(85301)"
          },
          NextOptions = {
            [1] = 901000011,
            [2] = 901000012,
            [3] = 901000013,
            [4] = 901000014,
            [5] = 901000015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_welcome",
          bForbidSkipOptions = true
        },
        [90100002] = {
          Content = "聊点别的",
          DialogueId = 90100002,
          GUID = "90100002.0",
          NextDialogue = 90100001
        },
        [90100003] = {
          Content = "再见",
          DialogueId = 90100003,
          GUID = "90100003.0"
        },
        [90100101] = {
          Content = "谢谢，着凉的话不用担心啦，卡戎之民是不怎么怕冷的，正好也不用再去买又厚又贵的大衣。",
          DialogueId = 90100101,
          GUID = "E18E5FD2",
          LookAt = {
            [1] = "85301:n(0)",
            [2] = "0:n(85301)"
          },
          NextDialogue = 90100103,
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_01_1"
        },
        [90100103] = {
          Content = "现在的衣服是妈妈帮我裁的，不过颜色是我自己选的，嫩绿色，这些蝴蝶形状的装饰也是我自己挑的，如果在暖和的南方的话，这一身应该就不奇怪了。",
          DialogueId = 90100103,
          GUID = "E18E6026",
          NextDialogue = 90100104,
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_01_2"
        },
        [90100104] = {
          Content = "原来是这样，蝴蝶装饰确实很适合你。",
          DialogueId = 90100104,
          GUID = "E18E6050",
          NextDialogue = 90100105,
          SpeakNpcId = 100001
        },
        [90100105] = {
          Content = "真的吗？太好了。其实我只见过冰湖城附近的蝴蝶，都是蓝色的。要是能去其他地方，看一看不同颜色的蝴蝶就好了。",
          DialogueId = 90100105,
          GUID = "E18E607A",
          NextOptions = {
            [1] = 90100002,
            [2] = 90100003
          },
          SpeakNpcId = 85301,
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_01_3",
          bForbidSkipOptions = true
        },
        [90100201] = {
          Content = "是的，据说几百年来一直都是这个样子。人们看到我们总像看到老鼠一样，我自己也被人追着骂过很难听的话。",
          DialogueId = 90100201,
          GUID = "E18E703A",
          LookAt = {
            [1] = "85301:n(0)",
            [2] = "0:n(85301)"
          },
          NextDialogue = 90100203,
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_02_1"
        },
        [90100203] = {
          Content = "因为索拉畏惧卡戎的力量？",
          DialogueId = 90100203,
          GUID = "E18E708E",
          NextDialogue = 90100204,
          SpeakNpcId = 100001
        },
        [90100204] = {
          Content = "或许吧。“魔法是最邪恶的东西”，大家总是这么说。历史书上也写着，卡戎之民的先祖在一千多年前，曾经凭借魔法支配索拉之民，做出了很多恶事。",
          DialogueId = 90100204,
          GUID = "E18E70B8",
          NextDialogue = 90100205,
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_02_2"
        },
        [90100205] = {
          Content = "说实话我有点难想象……因为我看到的卡戎们都很害怕索拉之民，不太敢和他们说话，在他们面前总是小心翼翼的，更不敢使用魔法。",
          DialogueId = 90100205,
          GUID = "E18E70E2",
          NextDialogue = 90100206,
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_02_3"
        },
        [90100206] = {
          Content = "而且其实大多数卡戎魔法都很寻常，也就是能用来点点壁炉，冰冻一下食物之类的。",
          DialogueId = 90100206,
          GUID = "E18E710C",
          NextDialogue = 90100207,
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_02_4"
        },
        [90100207] = {
          Content = "你会想回到那个时代吗——卡戎之民支配索拉之民的时代？",
          DialogueId = 90100207,
          GUID = "E18E7136",
          NextDialogue = 90100208,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "85301:Talk01_End"
          }
        },
        [90100208] = {
          Content = "不，一点也不。为什么卡戎之民和索拉之民之间，一定要一个支配另一个，一个畏惧另一个呢？",
          DialogueId = 90100208,
          GUID = "E18E7160",
          NextDialogue = 90100209,
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_02_5"
        },
        [90100209] = {
          Content = "我希望的只是……到了春天，所有人都能一起肩并着肩，一起去原野上看各种各样的花。只要这样就够了。",
          DialogueId = 90100209,
          GUID = "E18E718A",
          NextOptions = {
            [1] = 90100002,
            [2] = 90100003
          },
          SpeakNpcId = 85301,
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_02_6",
          bForbidSkipOptions = true
        },
        [90100301] = {
          Content = "啊，大概是因为我在试着培育新的花朵。修普诺斯之家前面的庭院只有几棵树，总觉得有点儿光秃秃的。所以，我想在那里种满白色的花……",
          DialogueId = 90100301,
          GUID = "E18E80A2",
          LookAt = {
            [1] = "85301:n(0)",
            [2] = "0:n(85301)"
          },
          NextDialogue = 90100303,
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_03_1"
        },
        [90100303] = {
          Content = "在这里也种一点吧，铃兰，银莲，仙女木……哪种更合适呢？",
          DialogueId = 90100303,
          GUID = "E18E80F6",
          NextDialogue = 90100304,
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_03_2"
        },
        [90100304] = {
          Content = "也许可以问问大家的意见。",
          DialogueId = 90100304,
          GUID = "E18E8120",
          NextDialogue = 90100305,
          SpeakNpcId = 100001
        },
        [90100305] = {
          Content = "你说得对，应该让大家一起决定……我会去问问看的！啊，对了，这些花里有你喜欢的品种吗？等花开了，我摘一些送给你吧。",
          DialogueId = 90100305,
          GUID = "E18E814A",
          NextOptions = {
            [1] = 90100002,
            [2] = 90100003
          },
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_03_3",
          bForbidSkipOptions = true
        },
        [90100401] = {
          Content = "嗯，我从出生起就一直住在这里，虽然每天都能听到列车的声音，但从来没去过其他地方。如果有机会的话，真想去外面看一看。",
          DialogueId = 90100401,
          GUID = "E18E80CC",
          LookAt = {
            [1] = "85301:n(0)",
            [2] = "0:n(85301)"
          },
          NextDialogue = 90100403,
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_04_1"
        },
        [90100403] = {
          Content = "想去哪些地方呢？",
          DialogueId = 90100403,
          GUID = "E18E80CB",
          NextDialogue = 90100404,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "85301:Explain02_End"
          }
        },
        [90100404] = {
          Content = "唔，我想想，皇都总是要去的，恩里克叔叔说过红溪城的落日也很好看。对了，还想去你说的净界岛，在南方的海岛上，闻一闻海风是不是真的是咸的！",
          DialogueId = 90100404,
          GUID = "E18E910A",
          NextOptions = {
            [1] = 90100002,
            [2] = 90100003
          },
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90100501] = {
          Content = "没什么，我只是想……再多看几眼，这样我就可以把你们的样子记得更清楚了。",
          DialogueId = 90100501,
          GUID = "E18EA172",
          NextDialogue = 90100502,
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_05_1"
        },
        [90100502] = {
          Content = "如果可以，你可以也多看我几眼吗？我也想让你记住我的样子……我现在的样子。",
          DialogueId = 90100502,
          GUID = "E18EA19C",
          NextOptions = {
            [1] = 90100002,
            [2] = 90100003
          },
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_05_2",
          bForbidSkipOptions = true
        },
        [90100601] = {
          Content = "我听说奥特赛德先生为菲娜的生日精心准备了很久。虽然嘴上不饶人，但你其实是个很体贴的人吧？下一次菲娜生日，我可以和你们一起为她准备惊喜吗？",
          DialogueId = 90100601,
          GUID = "E18EB1DA",
          SpeakNpcId = 85301,
          VoiceName = "voice/$Locale$/char/Saiqi/vo_companio_01"
        },
        [90100701] = {
          Content = "看见卡米拉女士总会让我想起那间吵闹却温馨的酒馆……这些年能够认识大家，真是太好了。",
          DialogueId = 90100701,
          GUID = "E18EC242",
          SpeakNpcId = 85301,
          VoiceName = "voice/$Locale$/char/Saiqi/vo_companio_02"
        },
        [90100801] = {
          Content = "你要讲艾利西安的故事给我听吗？太感谢了！唔……作为回礼，我应该送你什么花好呢……\n咦，你最喜欢好吃的花？",
          DialogueId = 90100801,
          GUID = "E18ED2AA",
          SpeakNpcId = 85301,
          VoiceName = "voice/$Locale$/char/Saiqi/vo_companio_03"
        },
        [90110000] = {
          Content = "晨间打扫后通风，午后四处喷洒烈酒，薄暮时再点几支香驱散蚊虫，只有这样才能保持室内洁净。",
          DialogueId = 90110000,
          GUID = "E194B809",
          SpeakNpcId = 82401,
          VoiceName = "voice/$Locale$/char/Baiheng/vo_idle"
        },
        [90110001] = {
          Content = "居移气，养移体，不妨趁天气晴朗出去走走，想必对身体会有所裨益。",
          DialogueId = 90110001,
          GUID = "E194B80A",
          LookAt = {
            [1] = "82401:n(0)",
            [2] = "0:n(82401)"
          },
          NextOptions = {
            [1] = 901100011,
            [2] = 901100012,
            [3] = 901100013,
            [4] = 901100014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 82401,
          VoiceName = "voice/$Locale$/char/Baiheng/vo_welcome",
          bForbidSkipOptions = true
        },
        [90110002] = {
          Content = "聊点别的",
          DialogueId = 90110002,
          GUID = "90110002.0",
          NextDialogue = 90110001
        },
        [90110003] = {
          Content = "再见",
          DialogueId = 90110003,
          GUID = "90110003.0"
        },
        [90110101] = {
          Content = "确然。只是书中的内容晦涩难懂，药石之间的差异，在我看来也难以辨别。或许，我在此道上确实没什么天赋。",
          DialogueId = 90110101,
          GUID = "E194C872",
          LookAt = {
            [1] = "82401:n(0)",
            [2] = "0:n(82401)"
          },
          NextDialogue = 90110103,
          SpeakNpcId = 82401,
          TalkActionId = {
            [1] = "82401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_01_1"
        },
        [90110103] = {
          Content = "咦？我还以为对医师来说，这些都信手拈来呢。",
          DialogueId = 90110103,
          GUID = "E194C8C6",
          NextDialogue = 90110104,
          SpeakNpcId = 100001
        },
        [90110104] = {
          Content = "在我的时代……药物并不是医治疾病的主流方式，人们通常依靠一种名为“祝由术”的奇迹驱退病魔。",
          DialogueId = 90110104,
          GUID = "E194C8F0",
          NextDialogue = 90110105,
          SpeakNpcId = 82401,
          TalkActionId = {
            [1] = "82401:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_01_2"
        },
        [90110105] = {
          Content = "然而，这种治疗方式虽然会带来“治愈”与“平安”，但也代表着“交换”与“牺牲”。从没有寿终正寝的医者，透支生命直至亡故才是我们唯一的选择。",
          DialogueId = 90110105,
          GUID = "E194C8F1",
          NextDialogue = 90110106,
          SpeakNpcId = 82401,
          TalkActionId = {
            [1] = "82401:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_01_3"
        },
        [90110106] = {
          Content = "……真是沉重的使命啊。",
          DialogueId = 90110106,
          GUID = "E194C8F2",
          NextDialogue = 90110107,
          SpeakNpcId = 100001
        },
        [90110107] = {
          Content = "枯荣阁虽然已是岁月的一件遗物，但在救病治人的道路上，永远不缺后继者。即便使命沉重，总有人会肩负起这份责任，矢志不渝地走下去。",
          DialogueId = 90110107,
          GUID = "E194C8F3",
          NextOptions = {
            [1] = 90110002,
            [2] = 90110003
          },
          SpeakNpcId = 82401,
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_01_4",
          bForbidSkipOptions = true
        },
        [90110201] = {
          Content = "愿世间再无“无药可医”的顽疾。",
          DialogueId = 90110201,
          GUID = "E194D8DA",
          LookAt = {
            [1] = "82401:n(0)",
            [2] = "0:n(82401)"
          },
          NextDialogue = 90110203,
          SpeakNpcId = 82401,
          TalkActionId = {
            [1] = "82401:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_04_1"
        },
        [90110203] = {
          Content = "好宏大的梦想……",
          DialogueId = 90110203,
          GUID = "E194D92E",
          NextDialogue = 90110204,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "82401:Explain02_End"
          }
        },
        [90110204] = {
          Content = "听起来与空想无异吧？但即使没有术法带来的奇迹，医师所要做的事也从未改变。（轻笑）这样的话由我这个医书都未读通的人说出口，实在贻笑大方。",
          DialogueId = 90110204,
          GUID = "E194D958",
          NextDialogue = 90110205,
          SpeakNpcId = 82401,
          TalkActionId = {
            [1] = "82401:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_04_2"
        },
        [90110205] = {
          Content = "但……我会继续在这条路上走下去，不止是为了黎民百姓，为了枯荣阁，也是为了我自己。",
          DialogueId = 90110205,
          GUID = "E194D982",
          NextOptions = {
            [1] = 90110002,
            [2] = 90110003
          },
          SpeakNpcId = 82401,
          TalkActionId = {
            [1] = "82401:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90110301] = {
          Content = "一个治病救人的地方。",
          DialogueId = 90110301,
          GUID = "E194E942",
          LookAt = {
            [1] = "82401:n(0)",
            [2] = "0:n(82401)"
          },
          NextDialogue = 90110303,
          SpeakNpcId = 82401,
          TalkActionId = {
            [1] = "82401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_03_1"
        },
        [90110303] = {
          Content = "还有别的吗？",
          DialogueId = 90110303,
          GUID = "E194E944",
          NextDialogue = 90110304,
          SpeakNpcId = 100001
        },
        [90110304] = {
          Content = "枯荣阁的使命，仅此而已。若说其他……每位入枯荣阁修行的医师，都要手植杏树一株，只是岁月流逝，风雨摧折，留存至今的已不足半数。",
          DialogueId = 90110304,
          GUID = "E194E943",
          NextDialogue = 90110305,
          SpeakNpcId = 82401,
          TalkActionId = {
            [1] = "82401:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_03_2"
        },
        [90110305] = {
          Content = "从长眠中苏醒后，我也曾去寻找回忆里那株属于我的杏树，但天不垂怜，花树已成枯木，今春虽暖，也未曾发出新芽来。",
          DialogueId = 90110305,
          GUID = "E194E945",
          NextDialogue = 90110306,
          SpeakNpcId = 82401,
          TalkActionId = {
            [1] = "82401:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_03_3"
        },
        [90110306] = {
          Content = "叹隙中驹，石中火，梦中身，几时归去，空作闲人。过去的已无法挽留，就算想要弥补，也再无可能了。",
          DialogueId = 90110306,
          GUID = "E194E946",
          NextOptions = {
            [1] = 90110002,
            [2] = 90110003
          },
          SpeakNpcId = 82401,
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_03_4",
          bForbidSkipOptions = true
        },
        [90110401] = {
          Content = "人死如灯灭，一切痕迹湮没，一切声息断绝。那种与世隔绝的寂静会吞没一切希望与可能，如果可以，我不希望任何一个病人落入那种境地。",
          DialogueId = 90110401,
          GUID = "E194F9AA",
          LookAt = {
            [1] = "82401:n(0)",
            [2] = "0:n(82401)"
          },
          NextDialogue = 90110403,
          SpeakNpcId = 82401,
          TalkActionId = {
            [1] = "82401:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_02_1"
        },
        [90110403] = {
          Content = "听起来，就像扶疏亲身体验过一样。",
          DialogueId = 90110403,
          GUID = "E194F9FE",
          NextDialogue = 90110404,
          SpeakNpcId = 100001
        },
        [90110404] = {
          Content = "的确如你所说，我……曾经从一场重病中逃出生天。假使让我再次面对这样的考验，我也不知道自己是否还会坚持当初的选择。",
          DialogueId = 90110404,
          GUID = "E194FA28",
          NextOptions = {
            [1] = 90110002,
            [2] = 90110003
          },
          SpeakNpcId = 82401,
          TalkActionId = {
            [1] = "82401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90110501] = {
          Content = "兰迪先生，依我看来，懒惰散漫也是身患疾病的一种表现，如今虽一时无恙，但毕竟也是个隐患。不如我来陪你过上两招，活动活动筋骨，可好？",
          DialogueId = 90110501,
          GUID = "E1950A12",
          SpeakNpcId = 82401,
          VoiceName = "voice/$Locale$/char/Baiheng/vo_companio_01"
        },
        [90110601] = {
          Content = "医者疗疾，却终究无法逆天改命。我可以为您开一贴缓解心热的药方，但病因却无法根除，但愿您能顺天应时，自渡为好……",
          DialogueId = 90110601,
          GUID = "E1951A7A",
          SpeakNpcId = 82401,
          VoiceName = "voice/$Locale$/char/Baiheng/vo_companio_02"
        },
        [90110701] = {
          Content = "有时会听到另一个人在说话？只有你能听见吗？近日睡眠如何？是否心有郁结？最怕心病难医，即使用上祝由术也无能为力，但身为医者，我必定竭尽全力。",
          DialogueId = 90110701,
          GUID = "E1952AE2",
          SpeakNpcId = 82401,
          VoiceName = "voice/$Locale$/char/Baiheng/vo_companio_03"
        },
        [90120000] = {
          Content = "休息一会儿吧，榛子，吃点小麦，吃点坚果。再来上几朵花当零食，要是吃不完的话，我就先插在帽子上。",
          DialogueId = 90120000,
          GUID = "E19B20A9",
          SpeakNpcId = 85101,
          VoiceName = "voice/$Locale$/char/Songlu/vo_idle"
        },
        [90120001] = {
          Content = "太阳热气腾腾，云朵松软蓬蓬，早起的鸟儿吃个饱饱。你的肚子有没有像鸟儿一样咕咕叫呢？",
          DialogueId = 90120001,
          GUID = "E19B20AA",
          LookAt = {
            [1] = "85101:n(0)",
            [2] = "0:n(85101)"
          },
          NextOptions = {
            [1] = 901200011,
            [2] = 901200012,
            [3] = 901200013,
            [4] = 901200014,
            [5] = 901200015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 85101,
          TalkActionId = {
            [1] = "85101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_welcome",
          bForbidSkipOptions = true
        },
        [90120002] = {
          Content = "聊点别的",
          DialogueId = 90120002,
          GUID = "90120002.0",
          NextDialogue = 90120001
        },
        [90120003] = {
          Content = "再见",
          DialogueId = 90120003,
          GUID = "90120003.0"
        },
        [90120101] = {
          Content = "咦？你不知道吗？粮秣专员就是负责填饱大家肚子的人哦，每天都要和各种食物打交道。",
          DialogueId = 90120101,
          GUID = "E19B3112",
          LookAt = {
            [1] = "85101:n(0)",
            [2] = "0:n(85101)"
          },
          NextDialogue = 90120103,
          SpeakNpcId = 85101,
          TalkActionId = {
            [1] = "85101:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_01_1"
        },
        [90120103] = {
          Content = "比如我的话，就会去野外收集各种各样的食物，让榛子驮回城里，然后再去委托面包店的胡子叔叔做成吃的，分给大家。",
          DialogueId = 90120103,
          GUID = "E19B3166",
          NextDialogue = 90120104,
          SpeakNpcId = 85101,
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_01_2"
        },
        [90120104] = {
          Content = "顺带一说，和那位胡子叔叔讨价还价，也是我的工作！哼哼。",
          DialogueId = 90120104,
          GUID = "E19B3190",
          NextDialogue = 90120105,
          SpeakNpcId = 85101,
          TalkActionId = {
            [1] = "85101:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_01_3"
        },
        [90120105] = {
          Content = "哇！听起来很厉害，不过所有的粮秣专员的工作都是这样的吗？",
          DialogueId = 90120105,
          GUID = "E19B31BA",
          NextDialogue = 90120106,
          SpeakNpcId = 100001
        },
        [90120106] = {
          Content = "那当然不是啦，其他的粮秣官好像都是一些脑子很好的家伙，写什么手续呀文书呀申请呀，然后就会有火车头拖着小山一样的吃的过来。",
          DialogueId = 90120106,
          GUID = "E19B31E4",
          NextDialogue = 90120107,
          SpeakNpcId = 85101,
          TalkActionId = {
            [1] = "85101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_01_4"
        },
        [90120107] = {
          Content = "不过，我住的镇子上人不是很多，有我和榛子就够啦！否则可能我就也得去学怎么写那些什么申请书之类的，唉，谁懂那些啊。",
          DialogueId = 90120107,
          GUID = "E19B320E",
          NextOptions = {
            [1] = 90120002,
            [2] = 90120003
          },
          SpeakNpcId = 85101,
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_01_5",
          bForbidSkipOptions = true
        },
        [90120201] = {
          Content = "诶？会吧……没太想过，不过反正榛子撞飞的一定都是那些喜欢哇哇乱叫，打来打去的坏家伙！是他们活该！",
          DialogueId = 90120201,
          GUID = "E19B417A",
          LookAt = {
            [1] = "85101:n(0)",
            [2] = "0:n(85101)"
          },
          NextDialogue = 90120203,
          SpeakNpcId = 85101,
          TalkActionId = {
            [1] = "85101:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_02_1"
        },
        [90120203] = {
          Content = "这些家伙，打打杀杀后又会叫饿连天。有挥武器的劲头不如多垦一会儿地啦，这样才会有更多人吃饱。",
          DialogueId = 90120203,
          GUID = "E19B41CE",
          NextDialogue = 90120204,
          SpeakNpcId = 85101,
          TalkActionId = {
            [1] = "85101:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_02_2"
        },
        [90120204] = {
          Content = "所以你也很讨厌战争喽？",
          DialogueId = 90120204,
          GUID = "E19B41F8",
          NextDialogue = 90120205,
          SpeakNpcId = 100001
        },
        [90120205] = {
          Content = "那是当然！战斗是饥饿之母，是坏家伙！听说一旦遇到战争，那么大家都会饿肚子，非常讨厌！希望我不要遇上就是了。",
          DialogueId = 90120205,
          GUID = "E19B4222",
          NextDialogue = 90120206,
          SpeakNpcId = 85101,
          TalkActionId = {
            [1] = "85101:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_02_3"
        },
        [90120206] = {
          Content = "真要遇到战争，就骑上榛子，撞飞开战的坏人。",
          DialogueId = 90120206,
          GUID = "E19B424C",
          NextDialogue = 90120207,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "85101:Confident_End"
          }
        },
        [90120207] = {
          Content = "没错，谁让人饿肚子，谁就迟早会被榛子撞飞！",
          DialogueId = 90120207,
          GUID = "E19B4276",
          NextOptions = {
            [1] = 90120002,
            [2] = 90120003
          },
          SpeakNpcId = 85101,
          TalkActionId = {
            [1] = "85101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_02_4",
          bForbidSkipOptions = true
        },
        [90120301] = {
          Content = "是不少啦，不过其实不用特别为她准备吃的，她会自己找的。哪怕隔着几条小溪，榛子也能闻到熟透浆果的味道，然后驮着我飞奔过去，可能干啦。",
          DialogueId = 90120301,
          GUID = "E19B51E2",
          LookAt = {
            [1] = "85101:n(0)",
            [2] = "0:n(85101)"
          },
          NextDialogue = 90120303,
          SpeakNpcId = 85101,
          TalkActionId = {
            [1] = "85101:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_03_1"
        },
        [90120303] = {
          Content = "那还好，不用担心破产了。",
          DialogueId = 90120303,
          GUID = "E19B5236",
          NextDialogue = 90120304,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "85101:Talk02_End"
          }
        },
        [90120304] = {
          Content = "别担心别担心，榛子只会带来食物，不会吃垮这里的！所以，一定一定不要拿榛子开玩笑哦，她听到的话会伤心的，我也会。",
          DialogueId = 90120304,
          GUID = "E19B5260",
          NextOptions = {
            [1] = 90120002,
