          TalkActionId = {
            [1] = "85101:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_05_2"
        },
        [90120505] = {
          Content = "唉，修士们的话我总是听得半懂不懂的，比如他们总是说贪吃是非常非常严重的罪过……可是好像越是大吃大喝的人，地位就越高哦。",
          DialogueId = 90120505,
          GUID = "E19B735A",
          NextOptions = {
            [1] = 90120002,
            [2] = 90120003
          },
          SpeakNpcId = 85101,
          TalkActionId = {
            [1] = "85101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_05_3",
          bForbidSkipOptions = true
        },
        [90120601] = {
          Content = "你在垃圾桶里翻到了发了芽的土豆？不要扔不要扔，我们把它种起来，松松土、浇浇水，就会有好多好多土豆可以吃啦！",
