          VoiceName = "voice/$Locale$/char/Xier/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90140501] = {
          Content = "嗯？在……在哪里？按照今天的行程她现在应该不在这里才是……",
          DialogueId = 90140501,
          GUID = "E1A843F2",
          LookAt = {
            [1] = "83102:n(0)",
            [2] = "0:n(83102)"
          },
          NextDialogue = 90140503,
          SpeakNpcId = 83102,
          TalkActionId = {
            [1] = "83102:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_05_1"
        },
        [90140503] = {
          Content = "你骗我。",
          DialogueId = 90140503,
          GUID = "E1A84446",
          NextDialogue = 90140504,
          SpeakNpcId = 83102,
          TalkActionId = {
            [1] = "83102:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_05_2"
        },
        [90140504] = {
          Content = "你是不是有点反应过度了？",
          DialogueId = 90140504,
          GUID = "E1A84470",
          NextDialogue = 90140505,
          SpeakNpcId = 100001
        },
        [90140505] = {
          Content = "并没有，她很重要。僭越地说，芙罗拉小姐对我而言，除了主人以外，尚有其他身份，所以……",
          DialogueId = 90140505,
          GUID = "E1A8449A",
          NextDialogue = 90140506,
          SpeakNpcId = 83102,
          TalkActionId = {
            [1] = "83102:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_05_3"
        },
        [90140506] = {
          Content = "可惜我并不是吟游诗人，无法找到一个词汇，能够兼有朋友与亲人的含义。",
          DialogueId = 90140506,
          GUID = "E1A844C4",
          NextDialogue = 90140507,
          SpeakNpcId = 83102,
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_05_4"
        },
        [90140507] = {
          Content = "我相信有些情感不需要语言也能传达。",
          DialogueId = 90140507,
          GUID = "E1A844EE",
          NextDialogue = 90140508,
          SpeakNpcId = 100001
        },
        [90140508] = {
          Content = "我无意让芙罗拉小姐知晓——清理主人前路的杂物是女仆的天职，我为此荣幸不已。",
          DialogueId = 90140508,
          GUID = "E1A84518",
          NextOptions = {
            [1] = 90140002,
            [2] = 90140003
          },
          SpeakNpcId = 83102,
          TalkActionId = {
            [1] = "83102:Agree"
          },
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_05_5",
          bForbidSkipOptions = true
        },
        [90140601] = {
          Content = "我最喜欢的花，生长在恒温的穹顶下。只需一片花瓣就可以制成安神的晚茶，而十片花瓣，又可以萃出一滴让人长眠的毒液。偶尔在梦里我还会修剪那片花圃，而醒来后，我会庆幸不用再照料它们。",
          DialogueId = 90140601,
          GUID = "E1A8545A",
          SpeakNpcId = 83102,
          VoiceName = "voice/$Locale$/char/Xier/vo_companio_01"
        },
        [90140701] = {
          Content = "真厉害，我由内心深处涌出敬意，您每天都在思考一些重大的事情。不像我这样的女仆，只会关心眼前的琐事。",
          DialogueId = 90140701,
          GUID = "E1A864C2",
          SpeakNpcId = 83102,
          VoiceName = "voice/$Locale$/char/Xier/vo_companio_02"
        },
        [90140801] = {
          Content = "这些堆积的无用杂物令我头痛了许久，如果您想带走它们当然乐意至极。不过在您进入房间前，请务必允许我为您提供清洁服务，您无权拒绝，不许挣扎。",
          DialogueId = 90140801,
          GUID = "E1A8752A",
          SpeakNpcId = 83102,
          VoiceName = "voice/$Locale$/char/Xier/vo_companio_03"
        },
        [90150000] = {
          Content = "我的小小的、小小的家……藏在树梢的新绿里，藏在金色的河流间……温暖的壁炉呀，小火苗噼啪噼啪……握着爸爸刚修好的锡兵，听妈妈唱起摇篮曲……睡吧……",
          DialogueId = 90150000,
          GUID = "E1AE5A8B",
          SpeakNpcId = 81801,
          VoiceName = "voice/$Locale$/char/Feina/vo_idle"
        },
        [90150001] = {
          Content = "……唔……是你。你好，你好呀。",
          DialogueId = 90150001,
          GUID = "E1AE5A8A",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextOptions = {
            [1] = 901500011,
            [2] = 901500012,
            [3] = 901500013,
            [4] = 901500014,
            [5] = 901500015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 81801,
          VoiceName = "voice/$Locale$/char/Feina/vo_welcome",
          bForbidSkipOptions = true
        },
        [90150002] = {
          Content = "聊点别的",
          DialogueId = 90150002,
          GUID = "90150002.0",
          NextDialogue = 90150001
        },
        [90150003] = {
          Content = "再见",
          DialogueId = 90150003,
          GUID = "90150003.0"
        },
        [90150101] = {
          Content = "唔，我想吃掉可以让人变得很大很大的糖果……",
          DialogueId = 90150101,
          GUID = "E1AE6AF2",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextDialogue = 90150103,
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_01_1"
        },
        [90150103] = {
          Content = "吃下那样的糖果，我就会长得比云还高，可以摸一摸天上的星星了吧？",
          DialogueId = 90150103,
          GUID = "E1AE6B46",
          NextDialogue = 90150104,
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_01_2"
        },
        [90150104] = {
          Content = "会不会一不留神一脚把我踩扁了……",
          DialogueId = 90150104,
          GUID = "E1AE6B70",
          NextDialogue = 90150105,
          SpeakNpcId = 100001
        },
        [90150105] = {
          Content = "不会的，我会很小心的！嗯……如果你实在害怕的话，就坐在我的手心里，我带你出去兜风，怎么样？",
          DialogueId = 90150105,
          GUID = "E1AE6B9A",
          NextOptions = {
            [1] = 90150002,
            [2] = 90150003
          },
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_01_3",
          bForbidSkipOptions = true
        },
        [90150201] = {
          Content = "我有一个很大很大的玻璃盒子，盒子里面装着窗户外软绵绵的雪，装着雪一样白白的棉花糖。我还想装进去棉花糖一样轻飘飘的云朵，云朵一样暖乎乎的风……",
          DialogueId = 90150201,
          GUID = "E1AE7B5A",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextDialogue = 90150203,
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_02_1"
        },
        [90150203] = {
          Content = "连同你们的笑声一起，全～都装进盒子。",
          DialogueId = 90150203,
          GUID = "E1AE7BAE",
          NextDialogue = 90150204,
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_02_2"
        },
        [90150204] = {
          Content = "真好啊，想钻进去。",
          DialogueId = 90150204,
          GUID = "E1AE7BD8",
          NextDialogue = 90150205,
          SpeakNpcId = 100001
        },
        [90150205] = {
          Content = "嗯……如果你能吃下让人变得很小很小的糖果，就可以进去玩啦。不过，这个盒子里到处都是白色的，你要小心，别在里面迷路哦。",
          DialogueId = 90150205,
          GUID = "E1AE7C02",
          NextDialogue = 90150206,
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Agree"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_02_3"
        },
        [90150206] = {
          Content = "如果我迷路了，菲娜会来救我吗？",
          DialogueId = 90150206,
          GUID = "E1AE7C2C",
          NextDialogue = 90150207,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "81801:Think_Start"
          }
        },
        [90150207] = {
          Content = "让我想想……如果你迷路了，菲娜就把面包掰成一小块一小块，连成一条路……这样，你只要沿着面包屑向前走，就能找到出口啦！",
          DialogueId = 90150207,
          GUID = "E1AE7C56",
          NextOptions = {
            [1] = 90150002,
            [2] = 90150003
          },
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_02_4",
          bForbidSkipOptions = true
        },
        [90150301] = {
          Content = "嗯……！在梦里，我看到了一只纯白羽毛的夜莺，它一会儿落在我的手上，一会儿绕着屋子和我捉迷藏……唔……到底是我梦见了它，还是它梦见了我呢……",
          DialogueId = 90150301,
          GUID = "E1AE8BC2",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextDialogue = 90150303,
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Agree"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_03_1"
        },
        [90150303] = {
          Content = "也许是你们做了同一个梦呢？",
          DialogueId = 90150303,
          GUID = "E1AE8C16",
          NextDialogue = 90150304,
          SpeakNpcId = 100001
        },
        [90150304] = {
          Content = "你说得对！也许那是一个仙境，所有睡着的孩子和小动物都可以在那里一起玩。嗯……下次的梦里会遇到谁呢？猫头鹰爷爷、金丝雀小姐，还是白兔先生？",
          DialogueId = 90150304,
          GUID = "E1AE8C40",
          NextOptions = {
            [1] = 90150002,
            [2] = 90150003
          },
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Agree"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90150401] = {
          Content = "菲娜曾经有一个妈妈，两个爸爸。不过，他们都不在了……",
          DialogueId = 90150401,
          GUID = "E1AE9C2A",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextDialogue = 90150402,
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_04_1"
        },
        [90150402] = {
          Content = "第一个爸爸，和妈妈一起，去了很远很远的国度。第二个爸爸，也去了很远很远的国度……是我带他去的哦。",
          DialogueId = 90150402,
          GUID = "E1AE9C54",
          NextOptions = {
            [1] = 90150002,
            [2] = 90150003
          },
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90150501] = {
          Content = "他是最伟大的魔法师，是说话最好听的人，是全世界最温柔最温柔的人……",
          DialogueId = 90150501,
          GUID = "E1AEAC92",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextDialogue = 90150503,
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_05_1"
        },
        [90150503] = {
          Content = "？",
          DialogueId = 90150503,
          GUID = "E1AEACE6",
          NextDialogue = 90150504,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "81801:Explain02_End"
          }
        },
        [90150504] = {
          Content = "唔，你看起来有很多很多问题，我哪里说的不对吗？",
          DialogueId = 90150504,
          GUID = "E1AEAD10",
          NextDialogue = 90150505,
          SpeakNpcId = 81801,
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_05_2"
        },
        [90150505] = {
          Content = "和我认识的奥特赛德完全是两个人吧！",
          DialogueId = 90150505,
          GUID = "E1AEAD3A",
          NextDialogue = 90150506,
          SpeakNpcId = 100001
        },
        [90150506] = {
          Content = "咦……？他对你说话不好听、不温柔吗？真对不起……我会敲敲他的脑袋，要他改正的！",
          DialogueId = 90150506,
          GUID = "E1AEAD64",
          NextOptions = {
            [1] = 90150002,
            [2] = 90150003
          },
          SpeakNpcId = 81801,
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_05_3",
          bForbidSkipOptions = true
        },
        [90150601] = {
          Content = "答应菲娜，再也再也再也……不要去那些有很多很多坏巫师的危险地方了，好吗？",
          DialogueId = 90150601,
          GUID = "E1AEBCFA",
          SpeakNpcId = 81801,
          VoiceName = "voice/$Locale$/char/Feina/vo_companio_01"
        },
        [90150701] = {
          Content = "那是什么？仓鼠小姐饲养的精灵吗？不可思议……它一定可以载着你飞过所有城堡的围墙！",
          DialogueId = 90150701,
          GUID = "E1AECD62",
          SpeakNpcId = 81801,
          VoiceName = "voice/$Locale$/char/Feina/vo_companio_02"
        },
        [90150801] = {
          Content = "狮子小姐，你想要唤醒沉睡在巨剑中的仙女吗？也许你需要吟诵很多很多咒语，比如——“唤醒圣剑萨麦尔之人啊，必将成为艾利西安之王！”",
          DialogueId = 90150801,
          GUID = "E1AEDDCA",
          SpeakNpcId = 81801,
          VoiceName = "voice/$Locale$/char/Feina/vo_companio_03"
        },
        [90150901] = {
          Content = "南国来的海马先生，我好像在哪儿见过你……唔……我想起来了！很久很久之前，爸爸在家里的墙上，挂了一张你的肖像。",
          DialogueId = 90150901,
          GUID = "E1AEEE32",
          SpeakNpcId = 81801,
          VoiceName = "voice/$Locale$/char/Feina/vo_companio_04"
        },
        [90160000] = {
          Content = "现在这种安心的感觉也不错，甚至让我在过了那么多年后，还能对一个地方产生一丝归属感。",
          DialogueId = 90160000,
          GUID = "E1B4C329",
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_idle"
        },
        [90160001] = {
          Content = "你可来了，我把之前剩下的杂活清了一下，钱没赚多少还差点把自己累死，唉，为了这个家我真是付出了太多啊。",
          DialogueId = 90160001,
          GUID = "E1B4C32A",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextOptions = {
            [1] = 901600011,
            [2] = 901600012,
            [3] = 901600013,
            [4] = 901600014,
            [5] = 901600015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 85102,
          TalkActionId = {
            [1] = "85102:Agree"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_welcome",
          bForbidSkipOptions = true
        },
        [90160002] = {
          Content = "聊点别的",
          DialogueId = 90160002,
          GUID = "90160002.0",
          NextDialogue = 90160001
        },
        [90160003] = {
          Content = "再见",
          DialogueId = 90160003,
          GUID = "90160003.0"
        },
        [90160101] = {
          Content = "手册？没有，干这行的可大部分没看书的耐性，但是口诀倒是不少，比如我自创的打人口诀：“两下腰子一下头，皇帝看了说没救”。",
          DialogueId = 90160101,
          GUID = "E1B4D392",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextDialogue = 90160103,
          SpeakNpcId = 85102,
          TalkActionId = {
            [1] = "85102:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_01_1"
        },
        [90160103] = {
          Content = "有意思，再来上几句？",
          DialogueId = 90160103,
          GUID = "E1B4D3E6",
          NextDialogue = 90160104,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "85102:Confident_Start"
          }
        },
        [90160104] = {
          Content = "别贪多，饭一口一口吃，干这行的，最大的敌人永远是贪婪，有时候来自别人，但更多时候来自自己。",
          DialogueId = 90160104,
          GUID = "E1B4D410",
          NextOptions = {
            [1] = 90160002,
            [2] = 90160003
          },
          SpeakNpcId = 85102,
          TalkActionId = {
            [1] = "85102:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_01_2",
          bForbidSkipOptions = true
        },
        [90160201] = {
          Content = "他们是一团未熄灭的野火，稍不留神就会烧成满山烈焰。为你个人考虑，还是少与他们接触为好……",
          DialogueId = 90160201,
          GUID = "E1B4E3FA",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextDialogue = 90160203,
          SpeakNpcId = 85102,
          TalkActionId = {
            [1] = "85102:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_02_1"
        },
        [90160203] = {
          Content = "这么严肃，为什么？",
          DialogueId = 90160203,
          GUID = "E1B4E44E",
          NextDialogue = 90160204,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "85102:Talk03_End"
          }
        },
        [90160204] = {
          Content = "那当然是因为……有过一些小过节，要是哪天你和他们打上交道，可千万记得别报我名字。",
          DialogueId = 90160204,
          GUID = "E1B4E478",
          NextOptions = {
            [1] = 90160002,
            [2] = 90160003
          },
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90160301] = {
          Content = "嗯，能帮我拿一下那边的纱布吗？可不能被菲娜发现，不然又她又要唠叨了。",
          DialogueId = 90160301,
          GUID = "E1B4F462",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextDialogue = 90160303,
          SpeakNpcId = 85102,
          TalkActionId = {
            [1] = "85102:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_03_1"
        },
        [90160303] = {
          Content = "她那是在关心你。",
          DialogueId = 90160303,
          GUID = "E1B4F4B6",
          NextDialogue = 90160304,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "85102:Explain02_End"
          }
        },
        [90160304] = {
          Content = "我知道，但干咱们这一行总免不了受点伤，我也不想让她一直担心嘛。她要是真的问起来，你记得帮我打个圆场啊，回头请你吃饭。",
          DialogueId = 90160304,
          GUID = "E1B4F4E0",
          NextOptions = {
            [1] = 90160002,
            [2] = 90160003
          },
          SpeakNpcId = 85102,
          TalkActionId = {
            [1] = "85102:Agree"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90160401] = {
          Content = "噢，你要不要也试试这些小家伙？别看它们长得丑，去掉头就跟小饼干一样脆脆的，甚至能在嘴巴里留下一丝肉类的回甘……",
          DialogueId = 90160401,
          GUID = "E1B504CA",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextDialogue = 90160403,
          SpeakNpcId = 85102,
          TalkActionId = {
            [1] = "85102:Give"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_04_1"
        },
        [90160403] = {
          Content = "（转身逃跑。）",
          DialogueId = 90160403,
          GUID = "E1B5051E",
          NextDialogue = 90160404,
          SpeakNpcId = 100001
        },
        [90160404] = {
          Content = "你别跑啊，这可是很有用的生存智慧……等你迷失在野外，干粮吃完的时候，它们就是最宝贵的能量来源。",
          DialogueId = 90160404,
          GUID = "E1B50548",
          NextOptions = {
            [1] = 90160002,
            [2] = 90160003
          },
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90160501] = {
          Content = "嗯……等等，你手上怎么才这么几个钱，是不是又把你那份报酬随便分给其他人了？",
          DialogueId = 90160501,
          GUID = "E1B51532",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextDialogue = 90160503,
          SpeakNpcId = 85102,
          TalkActionId = {
            [1] = "85102:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_05_1"
        },
        [90160503] = {
          Content = "他们比我更需要那些钱。",
          DialogueId = 90160503,
          GUID = "E1B51586",
          NextDialogue = 90160504,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "85102:Confident_End"
          }
        },
        [90160504] = {
          Content = "你……哎，算了，这大概就是你的优点吧。手头紧的时候记得跟我说。",
          DialogueId = 90160504,
          GUID = "E1B515B0",
          NextDialogue = 90160505,
          SpeakNpcId = 85102,
          TalkActionId = {
            [1] = "85102:Agree"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_05_2"
        },
        [90160505] = {
          Content = "好，那我现在手头紧了！",
          DialogueId = 90160505,
          GUID = "E1B515DA",
          NextDialogue = 90160506,
          SpeakNpcId = 100001
        },
        [90160506] = {
          Content = "……我这是身为朋友在关心你，你别得寸进尺耍无赖啊！",
          DialogueId = 90160506,
          GUID = "E1B51604",
          NextOptions = {
            [1] = 90160002,
            [2] = 90160003
          },
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_05_3",
          bForbidSkipOptions = true
        },
        [90160601] = {
          Content = "你怎么也在这儿？身体不要紧吗，病没问题吗，饭吃过了吗？哎……有什么想要的给我说就好，没事还是不要瞎跑了。",
          DialogueId = 90160601,
          GUID = "E1B5259A",
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_companio_01"
        },
        [90160701] = {
          Content = "你是跟{nickname}关系很好的那个女孩子吧……听说你身体不太好，就坐下好好休息一会儿吧。",
          DialogueId = 90160701,
          GUID = "E1B53602",
          NextDialogue = 90160702,
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_companio_02_1"
        },
        [90160702] = {
          Content = "不用跟我客气，我家里也有个体弱多病的妹妹，早就习惯照顾人了……要是饿了、渴了，尽管跟我说，{nickname}的朋友就是我的朋友。",
          DialogueId = 90160702,
          GUID = "E1B5362C",
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_companio_02_2"
        },
        [90160801] = {
          Content = "哟，老板娘，你怎么也在这儿……难不成是有什么紧急的委托？{nickname}这段时间已经累坏了，暂时就让我们歇歇吧……",
          DialogueId = 90160801,
          GUID = "E1B5466A",
          NextDialogue = 90160802,
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_companio_03_1"
        },
        [90160802] = {
          Content = "噢，不过，如果报酬够高的话，还是说来听听吧。",
          DialogueId = 90160802,
          GUID = "E1B54694",
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_companio_03_2"
        },
        [90160901] = {
          Content = "还记得我小时候吗？你对我来说是位温柔的姐姐，也是位严苛的父亲……呃，没有说你又老又暴力的意思，只是想说……谢谢你在那时给了我一个归属。",
          DialogueId = 90160901,
          GUID = "E1B556D2",
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_companio_04"
        },
        [90170000] = {
          Content = "嗯~天气不错，正适合去采一些花，熏得身上香香的！{nickname}，想一起出门逛逛吗？",
          DialogueId = 90170000,
          GUID = "E1BB2BC9",
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_idle"
        },
        [90170001] = {
          Content = "我来的时候顺手把你家门口的雪给铲了！是不是特别感动，特别想请我喝一杯热可可呀~",
          DialogueId = 90170001,
          GUID = "E1BB2BCA",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextOptions = {
            [1] = 901700011,
            [2] = 901700012,
            [3] = 901700013,
            [4] = 901700014,
            [5] = 901700015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_welcome",
          bForbidSkipOptions = true
        },
        [90170002] = {
          Content = "聊点别的",
          DialogueId = 90170002,
          GUID = "90170002.0",
          NextDialogue = 90170001
        },
        [90170003] = {
          Content = "再见",
          DialogueId = 90170003,
          GUID = "90170003.0"
        },
        [90170101] = {
          Content = "嗯……大概是为那些被舍弃的物品找到合适的主人的营生，唔，也能让那些遭受物资匮乏之苦的人，得到更好的生活。",
          DialogueId = 90170101,
          GUID = "E1BB3C32",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextDialogue = 90170103,
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_01_1"
        },
        [90170103] = {
          Content = "具体要怎么做？",
          DialogueId = 90170103,
          GUID = "E1BB3C86",
          NextDialogue = 90170104,
          SpeakNpcId = 100001
        },
        [90170104] = {
          Content = "比如，把贵族老爷淘汰下来的丝绒窗帘换成冬衣，让老人们暖暖过冬；把被丢弃的玩偶小人带给那些只能抛石头玩的孩子，他们能高兴很久。",
          DialogueId = 90170104,
          GUID = "E1BB3CB0",
          NextDialogue = 90170105,
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_01_2"
        },
        [90170105] = {
          Content = "还有一次，我把不知道哪家丢掉的破烂书架搬了回来，累得半死，但没过多久，就有一群猫妈妈猫小孩过来上蹿下跳，从太阳上山玩到月亮落山。",
          DialogueId = 90170105,
          GUID = "E1BB3CDA",
          NextDialogue = 90170106,
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_01_3"
        },
        [90170106] = {
          Content = "拾荒者的工作就是这样啦！大多是一些鸡毛蒜皮的小事，但永远不会无聊，怎么样，想不想加入我们！",
          DialogueId = 90170106,
          GUID = "E1BB3D04",
          NextOptions = {
            [1] = 90170002,
            [2] = 90170003
          },
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_01_4",
          bForbidSkipOptions = true
        },
        [90170201] = {
          Content = "嘘嘘嘘，这可是拾荒者的最高机密！要不是你帮我抓过贼，才不会轻易透露给你呢！",
          DialogueId = 90170201,
          GUID = "E1BB4C9A",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextDialogue = 90170203,
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_02_1"
        },
        [90170203] = {
          Content = "这张图标明了冰湖城所有垃圾桶的位置，我在上面标了好东西最多的几个，不仅把那边的垃圾桶换成了大号，就连什么时候去进货都经过我严密的计算！",
          DialogueId = 90170203,
          GUID = "E1BB4CEE",
          NextDialogue = 90170204,
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Give"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_02_2"
        },
        [90170204] = {
          Content = "不过我们这行旱涝不保收，能有多少进账，大部分时候还得靠运气……",
          DialogueId = 90170204,
          GUID = "E1BB4D18",
          NextDialogue = 90170205,
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_02_3"
        },
        [90170205] = {
          Content = "捡垃圾也真不容易……",
          DialogueId = 90170205,
          GUID = "E1BB4D42",
          NextDialogue = 90170206,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "83301:Sigh_End"
          }
        },
        [90170206] = {
          Content = "可不是嘛，嘿，我就说你是个明眼人！",
          DialogueId = 90170206,
          GUID = "E1BB4D6C",
          NextOptions = {
            [1] = 90170002,
            [2] = 90170003
          },
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_02_4",
          bForbidSkipOptions = true
        },
        [90170301] = {
          Content = "不，你说反啦！我非常喜欢冰湖城。只是我常常回想起和爸爸一起在雪原上流浪的日子，我的整个童年都是在那里度过的。",
          DialogueId = 90170301,
          GUID = "E1BB5D02",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextDialogue = 90170303,
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_03_1"
        },
        [90170303] = {
          Content = "你怎么看待那些时光呢？",
          DialogueId = 90170303,
          GUID = "E1BB5D56",
          NextDialogue = 90170304,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "83301:Agree"
          }
        },
        [90170304] = {
          Content = "从这里看向雪原，美得像童话里的冰国雪国。可一步一步走进去，又会觉得自己好小好小。在齐膝的雪地里迈着腿，不管走了多久，看到的景色都不会改变。",
          DialogueId = 90170304,
          GUID = "E1BB5D80",
          NextDialogue = 90170305,
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_03_2"
        },
        [90170305] = {
          Content = "我不讨厌那段时光，但我最喜欢的，果然还是热热闹闹，充满烟火味的冰湖城！",
          DialogueId = 90170305,
          GUID = "E1BB5DAA",
          NextOptions = {
            [1] = 90170002,
            [2] = 90170003
          },
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_03_3",
          bForbidSkipOptions = true
        },
        [90170401] = {
          Content = "是小时候和我在雪原上一起流浪的大猫！它叫“胖尾巴”，平时得用肉干贿赂才愿意给我摸摸，但那个手感——嘿嘿嘿嘿，一个字，绝啦！",
          DialogueId = 90170401,
          GUID = "E1BB6D6A",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextDialogue = 90170403,
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_04_1"
        },
        [90170403] = {
          Content = "雪原大猫怎么叫？像猫还是像老虎？",
          DialogueId = 90170403,
          GUID = "E1BB6DBE",
          NextDialogue = 90170404,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "83301:Explain02_End"
          }
        },
        [90170404] = {
          Content = "嗯……反正不是喵喵喵，大概是，嗷呜——嗷呜——嗷呜——的声音！",
          DialogueId = 90170404,
          GUID = "E1BB6DE8",
          NextDialogue = 90170405,
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_04_2"
        },
        [90170405] = {
          Content = "现在还能见到它吗？",
          DialogueId = 90170405,
          GUID = "E1BB6E12",
          NextDialogue = 90170406,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "83301:Think_End"
          }
        },
        [90170406] = {
          Content = "胖尾巴毕竟是生活在雪原的野兽，它不愿意靠近城市，等待我们的只有分道扬镳。但它会一直留在我的记忆里，和那片雪原一起。",
          DialogueId = 90170406,
          GUID = "E1BB6E3C",
          NextOptions = {
            [1] = 90170002,
            [2] = 90170003
          },
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90170501] = {
          Content = "我没有，我不是，别瞎说！我都这么大了，怎么还用这种哄小孩的称呼！算我求你了，别再提这个了！",
          DialogueId = 90170501,
          GUID = "E1BB7DD2",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextDialogue = 90170503,
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_05_1"
        },
        [90170503] = {
          Content = "那玛尔洁希望被人们怎样称呼呢？",
          DialogueId = 90170503,
          GUID = "E1BB7E26",
          NextDialogue = 90170504,
          SpeakNpcId = 100001
        },
        [90170504] = {
          Content = "那当然是——咳咳，于城市背面孤独行走，缄默的侦探——玛尔洁小姐！今天，也为你揭示冰湖城不为人知的隐秘！",
          DialogueId = 90170504,
          GUID = "E1BB7E50",
          NextDialogue = 90170505,
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_05_2"
        },
        [90170505] = {
          Content = "嘿嘿，这才是与我相称的外号嘛~",
          DialogueId = 90170505,
          GUID = "E1BB7E7A",
          NextOptions = {
            [1] = 90170002,
            [2] = 90170003
          },
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_05_3",
          bForbidSkipOptions = true
        },
        [90170601] = {
          Content = "这个布料，这个徽章，这个皮革！希尔妲大姐，你是我的神吗？！要是还有这种不法之徒的东西需要“妥善处理”，找我就对了，保准给您处理得安全无忧！",
          DialogueId = 90170601,
          GUID = "E1BB8E3A",
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_companio_01"
        },
        [90170701] = {
          Content = "小菲娜！好久不见啦~想听《雪猫游侠与橘猫侦探》的后续？好！等我搬个小板凳，坐下来慢慢给你讲！",
          DialogueId = 90170701,
          GUID = "E1BB9EA2",
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_companio_02"
        },
        [90170801] = {
          Content = "典狱长大人，我可是彻头彻尾的良民！一没偷二没抢，只是从垃圾桶里拿一点点残羹剩饭果腹罢了，您再敬业，也管不到垃圾头上吧？",
          DialogueId = 90170801,
          GUID = "E1BBAF0A",
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_companio_03"
        },
        [90170901] = {
          Content = "你这日子过得也太紧巴巴了吧！好、好惨……你要不要来和我一起捡垃圾，说不定日子还能过得宽裕一点？",
          DialogueId = 90170901,
          GUID = "E1BBBF72",
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_companio_04"
        },
        [90171001] = {
          Content = "最最最善良美丽的卡米拉姐，我这里有一点小小小小的麻烦，得拜托你帮个忙——这回绝对是最后一次！呃，本月的最后一次！你一定会答应我的，对吧？",
          DialogueId = 90171001,
          GUID = "E1BBCFDA",
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_companio_05"
        },
        [90180000] = {
          Content = "红鲤鱼，有头小绿、绿，绿鲤，绿驴，绿缕鱼…….",
          DialogueId = 90180000,
          GUID = "E1C19467",
          NextDialogue = 90180002,
          SpeakNpcId = 83103,
          VoiceName = "voice/$Locale$/char/Yeer/vo_idle_1"
        },
        [90180001] = {
          Content = "你来啦……天气真好……很适合做爆炸实验……唔，天气真好。",
          DialogueId = 90180001,
          GUID = "E1C1946A",
          LookAt = {
            [1] = "83103:n(0)",
            [2] = "0:n(83103)"
          },
          NextOptions = {
            [1] = 901800011,
            [2] = 901800012,
            [3] = 901800013,
            [4] = 901800014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Agree"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_welcome",
          bForbidSkipOptions = true
        },
        [90180002] = {
          Content = "是“红鲤鱼有头小绿驴，绿鲤鱼有头小红驴！”笨蛋耶尔，快跟我念！",
          DialogueId = 90180002,
          GUID = "E1C19468",
          NextDialogue = 90180003,
          SpeakNpcId = 83103,
          VoiceName = "voice/$Locale$/char/Yeer/vo_idle_2"
        },
        [90180003] = {
          Content = "好、好的！红、红鲤鱼……",
          DialogueId = 90180003,
          GUID = "E1C19469",
          SpeakNpcId = 83103,
          VoiceName = "voice/$Locale$/char/Yeer/vo_idle_3"
        },
        [90180004] = {
          Content = "聊点别的",
          DialogueId = 90180004,
          GUID = "90180004.0",
          NextDialogue = 90180001
        },
        [90180005] = {
          Content = "再见",
          DialogueId = 90180005,
          GUID = "90180005.0"
        },
        [90180101] = {
          Content = "奥利弗不是会说话的炸弹……可能听起来有些不可思议，但……他其实是……",
          DialogueId = 90180101,
          GUID = "E1C1A4D2",
          LookAt = {
            [1] = "83103:n(0)",
            [2] = "0:n(83103)"
          },
          NextDialogue = 90180103,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_01_1"
        },
        [90180103] = {
          Content = "闭嘴，被你急死了！我就是耶尔，耶尔就是我。听明白了吗？不明白也无所谓，也没指望你木屑一样的脑子能搞懂。",
          DialogueId = 90180103,
          GUID = "E1C1A526",
          NextDialogue = 90180104,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_01_2"
        },
        [90180104] = {
          Content = "好没礼貌的炸弹，扔了算了。",
          DialogueId = 90180104,
          GUID = "E1C1A550",
          NextDialogue = 90180105,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "83103:Angry01_End"
          }
        },
        [90180105] = {
          Content = "奥利弗他、他他是个好孩子！虽然看看上去脾气不好，说话有点凶，还总总总是突然冒出来，但……",
          DialogueId = 90180105,
          GUID = "E1C1A57A",
          NextDialogue = 90180106,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_01_3"
        },
        [90180106] = {
          Content = "喂，有你这么夸奖人的吗？",
          DialogueId = 90180106,
          GUID = "E1C1A5A4",
          NextOptions = {
            [1] = 90180004,
            [2] = 90180005
          },
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_01_4",
          bForbidSkipOptions = true
        },
        [90180201] = {
          Content = "我……可能派不上什么用场。唯一擅长的……可能就只有制作“小可爱”了吧？",
          DialogueId = 90180201,
          GUID = "E1C1B53A",
          LookAt = {
            [1] = "83103:n(0)",
            [2] = "0:n(83103)"
          },
          NextDialogue = 90180203,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_02_1"
        },
        [90180203] = {
          Content = "嗯？“小可爱”是什么？",
          DialogueId = 90180203,
          GUID = "E1C1B58E",
          NextDialogue = 90180204,
          SpeakNpcId = 100001
        },
        [90180204] = {
          Content = "“小可爱”……是“劈里啪啦”玩具店中……最受欢迎的商品，制作它们，要花费不少时间。",
          DialogueId = 90180204,
          GUID = "E1C1B5B8",
          NextDialogue = 90180205,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_02_2"
        },
        [90180205] = {
          Content = "但，不是因为我的技艺……有多好，只是因为，奥利弗他很熟悉。",
          DialogueId = 90180205,
          GUID = "E1C1B5E2",
          NextOptions = {
            [1] = 90180004,
            [2] = 90180005
          },
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_02_3",
          bForbidSkipOptions = true
        },
        [90180301] = {
          Content = "啊，抱歉！但、但是要是说得快了，我的舌头就就就容易打结。",
          DialogueId = 90180301,
          GUID = "E1C1C5A2",
          LookAt = {
            [1] = "83103:n(0)",
            [2] = "0:n(83103)"
          },
          NextDialogue = 90180303,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_03_1"
        },
        [90180303] = {
          Content = "那和别人交流起来应该还挺不容易的。",
          DialogueId = 90180303,
          GUID = "E1C1C5F6",
          NextDialogue = 90180304,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "83103:Sigh_End"
          }
        },
        [90180304] = {
          Content = "还、还好，有时候奥利弗会帮我说......而且，旁边没有人的时候，奥利弗总会把我想说的话听完的。",
          DialogueId = 90180304,
          GUID = "E1C1C620",
          NextOptions = {
            [1] = 90180004,
            [2] = 90180005
          },
          SpeakNpcId = 83103,
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90180401] = {
          Content = "我没有“小时候”……我从记事的时候，就在这个大孩子的身体里了。奥利弗也许有吧。",
          DialogueId = 90180401,
          GUID = "E1C1D60A",
          LookAt = {
            [1] = "83103:n(0)",
            [2] = "0:n(83103)"
          },
          NextDialogue = 90180403,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_04_1"
        },
        [90180403] = {
          Content = "少了很多回忆，有点遗憾。",
          DialogueId = 90180403,
          GUID = "E1C1D65E",
          NextDialogue = 90180404,
          SpeakNpcId = 100001
        },
        [90180404] = {
          Content = "我也想过如果能有“童年”，应该会是……怎样的呢？每晚睡觉前……琼斯先生会不会像普通的爸爸一样，坐在我的床头……给我讲故事……",
          DialogueId = 90180404,
          GUID = "E1C1D688",
          NextDialogue = 90180405,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_04_2"
        },
        [90180405] = {
          Content = "琼斯那混蛋讲故事？你脑子进胶水了吗？",
          DialogueId = 90180405,
          GUID = "E1C1D6B2",
          NextDialogue = 90180406,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_04_3"
        },
        [90180406] = {
          Content = "对对对不起！我我知道的，他只关心实验，不会做这些……",
          DialogueId = 90180406,
          GUID = "E1C1D6DC",
          NextOptions = {
            [1] = 90180004,
            [2] = 90180005
          },
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_04_4",
          bForbidSkipOptions = true
        },
        [90180501] = {
          Content = "您，您好……您的歌声，真的很、很动听。",
          DialogueId = 90180501,
          GUID = "E1C1E672",
          NextDialogue = 90180502,
          SpeakNpcId = 83103,
          VoiceName = "voice/$Locale$/char/Yeer/vo_companio_01_1"
        },
        [90180502] = {
          Content = "哼，又一只可怜虫。",
          DialogueId = 90180502,
          GUID = "E1C1E69C",
          SpeakNpcId = 83103,
          VoiceName = "voice/$Locale$/char/Yeer/vo_companio_01_2"
        },
        [90180601] = {
          Content = "榛子……是你的朋友吗？我也有很好的朋友，他像榛、榛子一样可靠。",
          DialogueId = 90180601,
          GUID = "E1C1F6DA",
          NextDialogue = 90180602,
          SpeakNpcId = 83103,
          VoiceName = "voice/$Locale$/char/Yeer/vo_companio_02_1"
        },
        [90180602] = {
          Content = "你骂谁呢？",
          DialogueId = 90180602,
          GUID = "E1C1F704",
          SpeakNpcId = 83103,
          VoiceName = "voice/$Locale$/char/Yeer/vo_companio_02_2"
        },
        [90180701] = {
          Content = "唔啊……你、你不要生气，我的炸弹实验都是符！符符符符合安全规定的……",
          DialogueId = 90180701,
          GUID = "E1C20742",
          SpeakNpcId = 83103,
          VoiceName = "voice/$Locale$/char/Yeer/vo_companio_03"
        },
        [90190000] = {
          Content = "难得有这么悠闲的时光，没有伤患的呼救，也没有紧急的战报。嗯……泡杯咖啡，把那本小说看完吧。公主最后到底和谁在一起了呢……",
          DialogueId = 90190000,
          GUID = "E1C7FD09",
          SpeakNpcId = 85401,
          VoiceName = "voice/$Locale$/char/Dafu/vo_idle"
        },
        [90190001] = {
          Content = "很高兴看到您今天健康平安。请多加珍重……为了终有一天会到来的和平。",
          DialogueId = 90190001,
          GUID = "E1C7FD0A",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextOptions = {
            [1] = 901900011,
            [2] = 901900012,
            [3] = 901900013,
            [4] = 901900014,
            [5] = 901900015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_welcome",
          bForbidSkipOptions = true
        },
        [90190002] = {
          Content = "聊点别的",
          DialogueId = 90190002,
          GUID = "90190002.0",
          NextDialogue = 90190001
        },
        [90190003] = {
          Content = "再见",
          DialogueId = 90190003,
          GUID = "90190003.0"
        },
        [90190101] = {
          Content = "我……没有什么特别的爱好。也许读书算一个吧？",
          DialogueId = 90190101,
          GUID = "E1C80D72",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextDialogue = 90190102,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_1"
        },
        [90190102] = {
          Content = "虽然妈妈总是唠叨，说我一直自己关在家里，错过了那些舞会和沙龙，会失去很多跻身更上一层的机会……",
          DialogueId = 90190102,
          GUID = "E1C80D9C",
          NextDialogue = 90190103,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_2"
        },
        [90190103] = {
          Content = "但我还是觉得，这样就很好。",
          DialogueId = 90190103,
          GUID = "E1C80DC6",
          NextDialogue = 90190104,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_3"
        },
        [90190104] = {
          Content = "那你最近在看什么书？",
          DialogueId = 90190104,
          GUID = "E1C80DF0",
          NextDialogue = 90190105,
          SpeakNpcId = 100001
        },
        [90190105] = {
          Content = "主要是战伤救治相关的书籍，《战地应急救援策略》、《常规外伤处理》、《野战医院的临时搭建》……",
          DialogueId = 90190105,
          GUID = "E1C80E1A",
          NextDialogue = 90190106,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_4"
        },
        [90190106] = {
          Content = "您也许知道，我过去学习的方向并非救护相关，尽管我已经获得了军团随行医务员的资格，但仍然时常感到沉重与惶恐。",
          DialogueId = 90190106,
          GUID = "E1C80E44",
          NextDialogue = 90190107,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_5"
        },
        [90190107] = {
          Content = "你也要适当放松一下，不要让自己太紧绷了。",
          DialogueId = 90190107,
          GUID = "E1C80E6E",
          NextDialogue = 90190108,
          SpeakNpcId = 100001
        },
        [90190108] = {
          Content = "嗯，最近我也在看一本叫做《玻璃鞋》的书。是关于……呃，公主和骑士……我、我并不是非常喜欢看浪漫小说！只是，随便……翻一下……",
          DialogueId = 90190108,
          GUID = "E1C80E98",
          NextOptions = {
            [1] = 90190002,
            [2] = 90190003
          },
          SpeakNpcId = 85401,
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_6",
          bForbidSkipOptions = true
        },
        [90190201] = {
          Content = "嗯，当然可以！它是海伯利亚的基石，是学者们口中“原初的奇迹”！",
          DialogueId = 90190201,
          GUID = "E1C81DDA",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextDialogue = 90190202,
          SpeakNpcId = 85401,
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_1"
        },
        [90190202] = {
          Content = "最一开始，人们试图从月石中分离出黄金，但后来，人们发现这枚小小的石头还有更多用途——转动机械的齿轮，释放电的火花……它就是索拉之民的“魔法”。",
          DialogueId = 90190202,
          GUID = "E1C81E04",
          NextDialogue = 90190203,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_2"
        },
        [90190203] = {
          Content = "……只是后来，炼金院……",
          DialogueId = 90190203,
          GUID = "E1C81E2E",
          NextDialogue = 90190204,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_3"
        },
        [90190204] = {
          Content = "你好像在炼金院待过？",
          DialogueId = 90190204,
          GUID = "E1C81E58",
          NextDialogue = 90190205,
          SpeakNpcId = 100001
        },
        [90190205] = {
          Content = "……是的。不过，那已经是过去的事了。",
          DialogueId = 90190205,
          GUID = "E1C81E82",
          NextDialogue = 90190206,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_4"
        },
        [90190206] = {
          Content = "你为什么要离开炼金院？",
          DialogueId = 90190206,
          GUID = "E1C81EAC",
          NextDialogue = 90190207,
          SpeakNpcId = 100001
        },
        [90190207] = {
          Content = "因为后来的佩剑炼金院偏离了轨道，走在了一条错误的路上。它是海伯利亚这座战车最炽热的炉芯，但燃料却是太多人的痛苦和不幸。",
          DialogueId = 90190207,
          GUID = "E1C81ED6",
          NextDialogue = 90190208,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_5"
        },
        [90190208] = {
          Content = "我想，我远比自己想象中更软弱。我无法说服自己接受它，也没有勇气和力量阻止它。所以，我只能选择逃避它。",
          DialogueId = 90190208,
          GUID = "E1C81F00",
          NextOptions = {
            [1] = 90190002,
            [2] = 90190003
          },
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_6",
          bForbidSkipOptions = true
        },
        [90190301] = {
          Content = "一些应急的器械和药品。绷带，消毒剂，麻醉剂，还有处理外伤的刀片和缝线。",
          DialogueId = 90190301,
          GUID = "E1C82E42",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextDialogue = 90190302,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_03_1"
        },
        [90190302] = {
          Content = "此外，还有一张手帕和一把梳子。",
          DialogueId = 90190302,
          GUID = "E1C82E6C",
          NextDialogue = 90190303,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_03_2"
        },
        [90190303] = {
          Content = "战场上也要梳妆么？达芙涅很爱美呢。",
          DialogueId = 90190303,
          GUID = "E1C82E96",
          NextDialogue = 90190304,
          SpeakNpcId = 100001
        },
        [90190304] = {
          Content = "啊，这个……不是我自己用的。如果救护的伤员不幸离世，我会帮他们简单整理一下仪容。",
          DialogueId = 90190304,
          GUID = "E1C82EC0",
          NextDialogue = 90190305,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_03_3"
        },
        [90190305] = {
          Content = "伤痛是很残忍的东西，它从人们那里夺走的，除了生命，还有生而为人的全部尊严。",
          DialogueId = 90190305,
          GUID = "E1C82EEA",
          NextDialogue = 90190306,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_03_4"
        },
        [90190306] = {
          Content = "我希望……他们的家人看到的他们，可以干净一些、安详一些……久别重逢，父母应该看到孩子们安然睡去的脸，而不是被疼痛扭曲五官的凄惨面容。",
          DialogueId = 90190306,
          GUID = "E1C82F14",
          NextOptions = {
            [1] = 90190002,
            [2] = 90190003
          },
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_03_5",
          bForbidSkipOptions = true
        },
        [90190401] = {
          Content = "我没关系，不辛苦的！……呃，其实还是有点……急救和护理知识的学习还好，但体能测试确实令人苦恼。",
          DialogueId = 90190401,
          GUID = "E1C83EAA",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextDialogue = 90190402,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_04_1"
        },
        [90190402] = {
          Content = "就算每天比大家起得更早独自加练，还是只能拿勉强及格的分数……唉，不要笑话我，锻炼体力真是比读书难太多了。",
          DialogueId = 90190402,
          GUID = "E1C83ED4",
          NextDialogue = 90190403,
          SpeakNpcId = 85401,
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_04_2"
        },
        [90190403] = {
          Content = "早起加练，听起来好累啊。",
          DialogueId = 90190403,
          GUID = "E1C83EFE",
          NextDialogue = 90190404,
          SpeakNpcId = 100001
        },
        [90190404] = {
          Content = "嗯，的确很累。不过当我把注意力从脚下移开，去看城郊的麦田，地平线尽头的小屋，去听风车的每一声转动和牧牛人的每一声哨笛，就觉得平静许多。",
          DialogueId = 90190404,
          GUID = "E1C83F28",
          NextDialogue = 90190405,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_04_3"
        },
        [90190405] = {
          Content = "因为……也许我奔跑在这条路上，就是为了保护这些最普通、最寻常的东西不被毁掉吧。",
          DialogueId = 90190405,
          GUID = "E1C83F52",
          NextOptions = {
            [1] = 90190002,
            [2] = 90190003
          },
          SpeakNpcId = 85401,
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_04_4",
          bForbidSkipOptions = true
        },
        [90190501] = {
          Content = "……我最后一次和爸爸说话，就是在对讲机里。那时还在龙莎要塞危机四伏的战场，他却对我说，“你放心。”",
          DialogueId = 90190501,
          GUID = "E1C84F12",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextDialogue = 90190502,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_05_1"
        },
        [90190502] = {
          Content = "后来我还是会常常在深夜打开自己的对讲机，调到爸爸的频段，按下呼叫按钮，期待着他的声音从对讲机那头传来……",
          DialogueId = 90190502,
          GUID = "E1C84F3C",
          NextDialogue = 90190503,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_05_2"
        },
        [90190503] = {
          Content = "直到我对着听筒等了十几分钟，我才突然发现，他是真的回不来了。",
          DialogueId = 90190503,
          GUID = "E1C84F66",
          NextDialogue = 90190504,
          SpeakNpcId = 85401,
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_05_3"
        },
        [90190504] = {
          Content = "请你节哀……",
          DialogueId = 90190504,
          GUID = "E1C84F90",
          NextDialogue = 90190505,
          SpeakNpcId = 100001
        },
        [90190505] = {
          Content = "谢谢，我明白的。我会好好活下去，在为父亲、为龙莎战役的死难者洗刷冤屈之前，我不会停下脚步。",
          DialogueId = 90190505,
          GUID = "E1C84FBA",
          NextOptions = {
            [1] = 90190002,
            [2] = 90190003
          },
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_05_4",
          bForbidSkipOptions = true
        },
        [90190601] = {
          Content = "我曾在皇都的图书馆中阅读过华胥的医书，虽然与海伯利亚的医理不太相同，但应用于救治却十分有效。这本书中我仍有一些问题，方便向您请教吗？",
          DialogueId = 90190601,
          GUID = "E1C85F7A",
          SpeakNpcId = 85401,
          VoiceName = "voice/$Locale$/char/Dafu/vo_companio_01"
        },
        [90190701] = {
          Content = "典狱长女士，迟来的正义真的还是正义吗？",
          DialogueId = 90190701,
          GUID = "E1C86FE2",
          SpeakNpcId = 85401,
          VoiceName = "voice/$Locale$/char/Dafu/vo_companio_02"
        }
      }
    end
  },
  {
