            [1] = "81103:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_01_4"
        },
        [90200106] = {
          Content = "所以，你被他吸引，和他成为了朋友。",
          DialogueId = 90200106,
          GUID = "E1CE76E4",
          NextDialogue = 90200107,
          SpeakNpcId = 100001
        },
        [90200107] = {
          Content = "……呵，也许吧。",
