          DisableMouth = 1,
          ExStoryInfo = "Player",
          GUID = "200008091",
          ImprPlusId = 1004,
          NextDialogue = 20000810,
          SpeakNpcId = 100001
        },
        [200008092] = {
          Content = "（留意到她刚才在照看的花——她刚才似乎就是对着这些花叹气。）",
