        [510012043] = {
          Content = "（向面前这位矿工赞扬技术发展能让人类社会更高效地运转。）",
          DialogueId = 510012043,
          GUID = "510012043.0",
          ImprPlusId = 1001,
          NextDialogue = 51001207,
          Subtitle = "(Commend the progress in technology for enhancing the efficiency of human society.)"
        },
        [510013011] = {
          Content = "你不能这样侮辱一位受尊敬的女士。",
          DialogueId = 510013011,
          GUID = "510013011.0",
          ImprPlusId = 1002,
          NextDialogue = 51001302,
          Subtitle = "Oi! You can't insult a respected lady at the doorstep of The Asphodel!"
        },
        [510013012] = {
          Content = "（上去就是一拳）",
          DialogueId = 510013012,
          GUID = "510013012.0",
          ImprPlusId = 1005,
          NextDialogue = 51001303,
          Subtitle = "(Throw a punch at his face)"
        },
        [510013013] = {
          Content = "给她点面子就敢蹬鼻子上脸，还说什么看不上老子的酒，老子早晚让她吃不了兜着走！",
          DialogueId = 510013013,
          GUID = "510013013",
          NextOptions = {
            [1] = 510013011,
            [2] = 510013012
          },
          SpeakNpcId = 700014,
          bForbidSkipOptions = true
        },
        [510013041] = {
          Content = "不，卡米拉是一位值得信赖的朋友，她帮过我忙。",
          DialogueId = 510013041,
          FailDialogue = 51001305,
          GUID = "510013041.0",
          ImprCheckId = 1008,
          NextDialogue = 51001306,
          Subtitle = "I'd rather see Camilla as a reliable and strong ally. She's been our saviour on numerous occasions. Not just us — at least half the city is in her debt."
        },
        [510013042] = {
          Content = "你不用多费唇舌，卡米拉为人怎么样，我相信自己的判断。",
          DialogueId = 510013042,
          FailDialogue = 51001305,
          GUID = "510013042.0",
          ImprCheckId = 1009,
          NextDialogue = 51001306,
          Subtitle = "That doesn't give you the right to spout nonsense here. Camilla's integrity is not up for debate, and it's certainly not to be smeared by your baseless accusations."
        },
        [510013043] = {
          Content = "所以你是向卡米拉推销酒水不成，着急了。",
          DialogueId = 510013043,
          FailDialogue = 51001305,
          GUID = "510013043.0",
          ImprCheckId = 1010,
          NextDialogue = 51001306,
          Subtitle = "I've seen Camilla's discernment in action. She has an eye for both people and liquor. It seems to me that you're the one who can't recognise good stuff."
        },
        [510013061] = {
          Content = "嗯，咳，听口音你不是本地人吧。我猜，自从来到冰湖城，你就没去水仙平原之外的地方喝过吧？",
          DialogueId = 510013061,
          GUID = "510013061.0",
          SpeakNpcId = 700014
        },
        [510013062] = {
          Content = "那又如何？",
          DialogueId = 510013062,
          GUID = "510013062",
          Subtitle = "So what?"
        },
        [510013091] = {
          Content = "好吧，来一桶。",
          DialogueId = 510013091,
          GUID = "510013091.0",
          NextDialogue = 51001310,
          Subtitle = "Fine, I'll take a can."
        },
        [510013092] = {
          Content = "便宜没好货。",
          DialogueId = 510013092,
          GUID = "510013092.0",
          NextDialogue = 51001313,
          Subtitle = "You get what you pay for."
        },
        [510013231] = {
          Content = "抢生意也就算了，万一假酒把人喝出毛病怎么办？",
          DialogueId = 510013231,
          GUID = "510013231.0",
          ImprPlusId = 1002,
          NextDialogue = 51001324
        },
        [510013232] = {
          Content = "就是！还怕她一张嘴！兄弟你喝一桶看看实力！",
          DialogueId = 510013232,
          GUID = "510013232.0",
          ImprPlusId = 1005,
          NextDialogue = 51001326
        },
        [510013281] = {
          Content = "假货害人啊……",
          DialogueId = 510013281,
          GUID = "510013281.0",
          NextDialogue = 51001329
        },
        [510014021] = {
          Content = "孩子本就是天生通透的诗人。",
          DialogueId = 510014021,
          GUID = "510014021.0",
          ImprPlusId = 1004,
          NextDialogue = 51001403,
          Subtitle = "Children are natural poets seeing through life's essence, aren't they?"
        },
        [510014022] = {
          Content = "你看起来非常为他们自豪。",
          DialogueId = 510014022,
          GUID = "510014022.0",
          ImprPlusId = 1003,
          NextDialogue = 51001403,
          Subtitle = "You seem to be very proud of them."
        },
        [510014023] = {
          Content = "可恶，原来我输在了起跑线上。",
          DialogueId = 510014023,
          GUID = "510014023.0",
          ImprPlusId = 1005,
          NextDialogue = 51001403,
          Subtitle = "Darn it, it seems I was behind right from the start."
        },
        [510014061] = {
          Content = "才不是呢，你教会了孩子可贵的纯真与浪漫。",
          DialogueId = 510014061,
          FailDialogue = 51001407,
          GUID = "510014061.0",
          ImprCheckId = 1011,
          NextDialogue = 51001409,
          Subtitle = "Not at all. You've preserved the children's precious innocence and sense of wonder."
        },
        [510014901] = {
          Content = "你看起来在和孩子们的相处中收获了很多。",
          DialogueId = 510014901,
          GUID = "510014901.0",
          ImprPlusId = 1003,
          NextDialogue = 51001412,
          Subtitle = "It seems you've gained a lot from your time with the children."
        },
        [510014902] = {
          Content = "为这些孩子们做出牺牲，真的是值得的吗？",
          DialogueId = 510014902,
          GUID = "510014902.0",
          ImprPlusId = 1001,
          NextDialogue = 51001412,
          Subtitle = "Is it really worth it?"
        },
        [510015021] = {
          Content = "用清洁剂泡一泡再擦？",
          DialogueId = 510015021,
          GUID = "510015021.0",
          ImprPlusId = 1003,
          NextDialogue = 51001503,
          Subtitle = "Maybe try soaking it in detergent first?"
        },
        [510015022] = {
          Content = "你付钱给我，我给你擦。",
          DialogueId = 510015022,
          GUID = "510015022.0",
          ImprPlusId = 1001,
          NextDialogue = 51001503,
          Subtitle = "You got cash? I can clean it for you."
        },
        [510015023] = {
          Content = "挨打挨骂是好事，有助于锻炼精神。",
          DialogueId = 510015023,
          GUID = "510015023.0",
          ImprPlusId = 1005,
          NextDialogue = 51001503,
          Subtitle = "Getting beaten up is good for character building, isn't it?"
        },
        [510015071] = {
          Content = "你不觉得说这种话太冷漠了吗？",
          DialogueId = 510015071,
          GUID = "510015071.0",
          ImprCheckId = 1012,
          NextDialogue = 51001509,
          Subtitle = "What a heartless thing to say!"
        },
        [510016021] = {
          Content = "（此人脾气有点暴躁，摸一摸他的恶魔角安抚下吧。）",
          DialogueId = 510016021,
          GUID = "510016021.0",
          ImprPlusId = 1005,
          NextDialogue = 51001603,
          Subtitle = "(He seems temperamental. Maybe touching his horns will calm him down.)"
        },
        [510016022] = {
          Content = "卡戎和索拉是平等的。你不该心存偏见。",
          DialogueId = 510016022,
          GUID = "510016022.0",
          ImprPlusId = 1002,
          NextDialogue = 51001605,
          Subtitle = "Charons and humans are equals. Prejudice is not cool."
        },
        [510016023] = {
          Content = "可是你也是个卡戎啊……？",
          DialogueId = 510016023,
          GUID = "510016023.0",
          ImprPlusId = 1003,
          NextDialogue = 51001607,
          Subtitle = "But you're a Charon too... aren't you?"
        },
        [510016121] = {
          Content = "我可以看看您的“桂冠卡戎”奖章吗？",
          DialogueId = 510016121,
          FailDialogue = 51001690,
          GUID = "510016121.0",
          ImprCheckId = 1013,
          NextDialogue = 51001613,
          Subtitle = "May I have the honour to take a peek at your \"Laurelled Charon\" medal?"
        },
        [510017031] = {
          Content = "（真诚建议他注意个人卫生问题）",
          DialogueId = 510017031,
          GUID = "510017031.0",
          ImprPlusId = 1003,
          NextDialogue = 51001704,
          Subtitle = "(Sincerely suggest he looks into personal hygiene.)"
        },
        [510017032] = {
          Content = "（为自己刚才失礼的动作道歉）",
          DialogueId = 510017032,
          GUID = "510017032.0",
          ImprPlusId = 1004,
          NextDialogue = 51001704,
          Subtitle = "(Apologise for your rather impolite reaction just now.)"
        },
        [510017033] = {
          Content = "（指责他的味道过于腥臭有恶劣影响）",
          DialogueId = 510017033,
          GUID = "510017033.0",
          ImprPlusId = 1002,
          NextDialogue = 51001704,
          Subtitle = "(Complain that his stench is unbearable and affects those around him.)"
        },
        [510017081] = {
          Content = "一个本该救死扶伤的人不应该来修理下水道。",
          DialogueId = 510017081,
          FailDialogue = 51001709,
          GUID = "510017081.0",
          ImprCheckId = 1014,
          NextDialogue = 51001711,
          Subtitle = "A life-saver like you shouldn't be stuck mending sewers."
        },
        [510017161] = {
          Content = "如果再给你的人生重来一次的机会，你还会救他吗？",
          DialogueId = 510017161,
          GUID = "510017161.0",
          NextDialogue = 51001717,
          Subtitle = "If you had a chance to do it all over, would you make the same choice to save him?"
        },
        [510018011] = {
          Content = "（接受）",
          DialogueId = 510018011,
          GUID = "510018011.0",
          NextDialogue = 51001802,
          Subtitle = "(Accept)"
        },
        [510018012] = {
          Content = "（拒绝）",
          DialogueId = 510018012,
          GUID = "510018012.0",
          Scripts = "SetOutport{FinishType{\"Fail\"}}",
          Subtitle = "(Refuse)"
        },
        [510019231] = {
          Content = "这裂纹的形状……原来如此，它替威尔斯先生挡下了胸口的致命伤啊。",
          DialogueId = 510019231,
          GUID = "510019231.0",
          ImprPlusId = 1003,
          NextDialogue = 51001924,
          Subtitle = "The shape of these cracks... I see. It protected you from a fatal blow to the chest."
        },
        [510019232] = {
          Content = "……威尔斯先生就算过得再怎么惨，也不该去偷别人的怀表吧。",
          DialogueId = 510019232,
          GUID = "510019232.0",
          ImprPlusId = 1005,
          NextDialogue = 51001924,
          Subtitle = "...Mr. Wells, no matter how hard life is, you shouldn't steal someone else's watch."
        },
        [510019911] = {
          Content = "威尔斯先生没你说的不堪，别太过分了。",
          DialogueId = 510019911,
          FailDialogue = 51001916,
          GUID = "510019911.0",
          ImprCheckId = 1015,
          NextDialogue = 51001918,
          Subtitle = "Mr. Wells isn't as bad as you say. You're pushing things too far."
        },
        [510019912] = {
          Content = "桂冠卡戎对我们没有任何吸引力，别拿你浅薄的认知定义所有人。",
          DialogueId = 510019912,
          FailDialogue = 51001916,
          GUID = "510019912.0",
          ImprCheckId = 1016,
          NextDialogue = 51001918,
          Subtitle = "We have no interest in becoming laurelled Charon. Don't try to put everyone into a box with your shallow understanding."
        },
        [510019913] = {
          Content = "嘴巴放干净点。不然今天像狗一样被打一顿的，就是另一个“威尔斯先生”了。",
          DialogueId = 510019913,
          FailDialogue = 51001916,
          GUID = "510019913.0",
          ImprCheckId = 1017,
          NextDialogue = 51001918,
          Subtitle = "Watch your mouth. Otherwise, another \"Mr. Wells\" might end up getting beaten up like a dog today."
        },
        [510020031] = {
          Content = "为什么你不自己去寻宝呢？",
          DialogueId = 510020031,
          GUID = "510020031.0",
          ImprPlusId = 1003,
          NextDialogue = 51002004,
          Subtitle = "Why don't you go treasure hunting yourself?"
        },
        [510020032] = {
          Content = "稍微介绍一下这个宝藏？",
          DialogueId = 510020032,
          GUID = "510020032.0",
          ImprPlusId = 1001,
          NextDialogue = 51002006,
          Subtitle = "Could you briefly describe this treasure?"
        },
        [510020033] = {
          Content = "你是不是在骗人啊……",
          DialogueId = 510020033,
          GUID = "510020033.0",
          ImprPlusId = 1002,
          NextDialogue = 51002008,
          Subtitle = "You are not trying to defraud, are you?"
        },
        [510020131] = {
          Content = "我总觉得你说的这个南方海岛很耳熟。",
          DialogueId = 510020131,
          FailDialogue = 51002014,
          GUID = "510020131.0",
          ImprCheckId = 1018,
          NextDialogue = 51002016,
          Subtitle = "I feel like I've heard of this southern island before."
        },
        [510023011] = {
          Content = "哈默尔·狄金森……我好像看到过这个名字……",
          DialogueId = 510023011,
          GUID = "510023011.0",
          NextDialogue = 51002302
        },
        [510023041] = {
          Content = "（交出在矿坑中得到的日记）",
          DialogueId = 510023041,
          GUID = "510023041.0",
          ImprPlusId = 1002,
          NextDialogue = 51002305,
          Scripts = "SetOutport{FinishType{2},OptionIdx{1}}"
        },
        [510023042] = {
