        [800202021] = {
          Content = "那么，你先去休息？",
          DialogueId = 800202021,
          GUID = "800202021.0",
          NextDialogue = 80020203
        },
        [800202022] = {
          Content = "有这么夸张吗？",
          DialogueId = 800202022,
          GUID = "800202022.0",
          NextDialogue = 80020204
        },
        [800202091] = {
          Content = "你真的只是一名女仆吗？",
          DialogueId = 800202091,
          GUID = "800202091.0",
          NextDialogue = 80020210
        },
        [800202092] = {
          Content = "太危险了。",
          DialogueId = 800202092,
          GUID = "800202092.0",
          NextDialogue = 80020211
        },
        [800202161] = {
          Content = "听起来有些浪漫。",
          DialogueId = 800202161,
          GUID = "800202161.0",
          NextDialogue = 80020217
        },
        [800202162] = {
          Content = "听起来很辛苦。",
          DialogueId = 800202162,
          GUID = "800202162.0",
          NextDialogue = 80020218
        },
        [800203021] = {
          Content = "我可以一起吗？",
          DialogueId = 800203021,
          GUID = "800203021.0",
          NextDialogue = 80020303
        },
        [800203022] = {
          Content = "你也会逛街吗？",
          DialogueId = 800203022,
          GUID = "800203022.0",
          NextDialogue = 80020304
        },
        [800203121] = {
          Content = "真的这么神奇？",
          DialogueId = 800203121,
          GUID = "800203121.0",
          NextDialogue = 80020313
        },
        [800203122] = {
          Content = "听上去确实会很好看。",
          DialogueId = 800203122,
          GUID = "800203122.0",
          NextDialogue = 80020314
        },
        [800203161] = {
          Content = "王子？",
          DialogueId = 800203161,
          GUID = "800203161.0",
          NextDialogue = 80020317
        },
        [800204021] = {
          Content = "听起来心情不错？",
          DialogueId = 800204021,
          GUID = "800204021.0",
          NextDialogue = 80020403
        },
        [800204022] = {
          Content = "这才更像是女仆的工作啊。",
          DialogueId = 800204022,
          GUID = "800204022.0",
          NextDialogue = 80020404
        },
        [800204091] = {
          Content = "那么你是遇到了什么烦心事？",
          DialogueId = 800204091,
          GUID = "800204091.0",
          NextDialogue = 80020410
        },
        [800204092] = {
          Content = "展开讲讲你的前同僚们？",
          DialogueId = 800204092,
          GUID = "800204092.0",
          NextDialogue = 80020411
        },
        [800204171] = {
          Content = "好奇的话，不如直接去见她？",
          DialogueId = 800204171,
          GUID = "800204171.0",
          NextDialogue = 80020418
        },
        [800205011] = {
          Content = "啊？只是巧合而已。",
          DialogueId = 800205011,
          GUID = "800205011.0",
          NextDialogue = 80020503
        },
        [800205012] = {
          Content = "你的头发那么显眼，很难不注意到。",
          DialogueId = 800205012,
          GUID = "800205012.0",
          NextDialogue = 80020503
        },
        [800205071] = {
          Content = "听起来像是解开了心结？",
          DialogueId = 800205071,
          GUID = "800205071.0",
          NextDialogue = 80020508
        },
        [800205072] = {
          Content = "不会觉得可惜吗？",
          DialogueId = 800205072,
          GUID = "800205072.0",
          NextDialogue = 80020509
        },
        [800205121] = {
          Content = "当我尚在犹豫之时，她毫不迟疑地想要去完成任务——甚至把我也视为必要时可以除去的阻碍。",
          DialogueId = 800205121,
          GUID = "C852AD41",
          NextDialogue = 80020513,
          SpeakNpcId = 93102,
          TalkActionId = {
            [1] = "93102:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD41"
        },
        [800205141] = {
          Content = "你还恨着她吗？",
          DialogueId = 800205141,
          GUID = "C852AD6C",
          NextDialogue = 800205143
        },
        [800205142] = {
          Content = "你还爱着她吗？",
          DialogueId = 800205142,
          GUID = "C852AD6D",
          NextDialogue = 800205143
        },
        [800205143] = {
          Content = "坦白说，我不知道。我对她只是有些气恼，有些委屈，还有些想念。对于两个密探来说，你提到的爱和恨，都太奢侈了。",
          DialogueId = 800205143,
          FacialId = {
            [1] = "93102:Unhappy01"
          },
          GUID = "C852AD94",
          NextDialogue = 80020515,
          SpeakNpcId = 93102,
          TalkActionId = {
            [1] = "93102:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD94"
        },
        [800205181] = {
          Content = "嗯？你刚才说了“谢谢”吧？",
          DialogueId = 800205181,
          GUID = "800205181.0",
          NextDialogue = 80020522
        },
        [800205182] = {
          Content = "没听清，再说一遍。",
          DialogueId = 800205182,
          GUID = "800205182.0",
          NextDialogue = 80020522
        },
        [800301051] = {
          Content = "兰迪在这些方面可真有原则啊。",
          DialogueId = 800301051,
          GUID = "800301051.0",
          NextDialogue = 80030106
        },
        [800301052] = {
          Content = "兰迪总是偷懒呢。",
          DialogueId = 800301052,
          GUID = "800301052.0",
          NextDialogue = 80030107
        },
        [800302051] = {
          Content = "为了休假编谎，这也能叫绅士？",
          DialogueId = 800302051,
          GUID = "800302051.0",
          NextDialogue = 80030206
        },
        [800302052] = {
          Content = "嗯，对对，风度翩翩，绅士极了。",
          DialogueId = 800302052,
          GUID = "800302052.0",
          NextDialogue = 80030207
        },
        [800302091] = {
          Content = "姐姐们？听起来应该也都是淑女。",
          DialogueId = 800302091,
          GUID = "800302091.0",
          NextDialogue = 80030210
        },
        [800302092] = {
          Content = "无法想象你还是小男孩的时候。",
          DialogueId = 800302092,
          GUID = "800302092.0",
          NextDialogue = 80030211
        },
        [800302131] = {
          Content = "“关爱”？听上去并不坏啊。",
          DialogueId = 800302131,
          GUID = "800302131.0",
          NextDialogue = 80030214
        },
        [800302132] = {
          Content = "“关爱”？听起来和“绅士”是差不多的用法，辛苦你了。",
          DialogueId = 800302132,
          GUID = "800302132.0",
          NextDialogue = 80030215
        },
        [800304031] = {
          Content = "是不是遇到什么烦心事了？你平时不这样。",
          DialogueId = 800304031,
          GUID = "800304031.0",
          NextDialogue = 80030404
        },
        [800304032] = {
          Content = "这么急着走，是被人约了跳舞吗？",
          DialogueId = 800304032,
          GUID = "800304032.0",
          NextDialogue = 80030406
        },
        [800304071] = {
          Content = "噩梦？",
          DialogueId = 800304071,
          GUID = "800304071.0",
          NextDialogue = 80030408
        },
        [800304081] = {
          Content = "兰迪的父亲？头一次听你提到他。",
          DialogueId = 800304081,
          GUID = "800304081.0",
          NextDialogue = 80030409
        },
        [800304321] = {
          Content = "真的是这样吗？",
          DialogueId = 800304321,
          GUID = "800304321.0",
          NextDialogue = 80030433
        },
        [800304351] = {
          Content = "他要是现在醒来的话，一定会为你骄傲的。",
          DialogueId = 800304351,
          GUID = "800304351.0",
          NextDialogue = 80030436
        },
        [800304352] = {
          Content = "我再给你调一杯。",
          DialogueId = 800304352,
          GUID = "800304352.0",
          NextDialogue = 80030437
        },
        [800305011] = {
          Content = "谢谢，看上去心情不错？",
          DialogueId = 800305011,
          GUID = "C8790EF4",
          NextDialogue = 80030502
        },
        [800305012] = {
          Content = "你是不是有什么企图？",
          DialogueId = 800305012,
          GUID = "C8790F48",
          NextDialogue = 80030503
        },
        [800305081] = {
          Content = "一位女士？那找我干什么？",
          DialogueId = 800305081,
          GUID = "C879106E",
          NextDialogue = 80030509,
          TriggerCondition = {
            IsBoy = {}
          }
        },
        [800305082] = {
          Content = "所以你是为了这个才邀请我……",
          DialogueId = 800305082,
          GUID = "800305082.0",
          NextDialogue = 80030526,
          TriggerCondition = {
            IsGirl = {}
          }
        },
        [800305091] = {
          Content = "你自己怎么不扮？",
          DialogueId = 800305091,
          GUID = "800305091.0",
          NextDialogue = 80030510
        },
        [800305092] = {
          Content = "？",
          DialogueId = 800305092,
          GUID = "800305092.0",
          NextDialogue = 80030511
        },
        [800305141] = {
          Content = "？？？什么情况，兄弟。",
          DialogueId = 800305141,
          GUID = "800305141.0",
          NextDialogue = 80030515
        },
        [800305142] = {
          Content = "其实根本就是你想自己穿吧。",
          DialogueId = 800305142,
          GUID = "800305142.0",
          NextDialogue = 80030515
        },
        [800305161] = {
          Content = "后面两个是什么奇怪的东西……",
          DialogueId = 800305161,
          GUID = "800305161.0",
          NextDialogue = 80030517
        },
        [800305171] = {
          Content = "那我就勉为其难地答应了。",
          DialogueId = 800305171,
          GUID = "80030571",
          NextDialogue = 80030518
        },
        [800305172] = {
          Content = "让我再想想。",
          DialogueId = 800305172,
          GUID = "800305172",
          NextDialogue = 80030523
        },
        [800305261] = {
          Content = "你是不是想要在舞会上活捉我？",
          DialogueId = 800305261,
          GUID = "C87910C2",
          NextDialogue = 80030527
        },
        [800305311] = {
          Content = "当然是开玩笑。",
          DialogueId = 800305311,
          GUID = "C87911BE",
          NextDialogue = 80030532
        },
        [800305312] = {
          Content = "这两者并不矛盾啊！",
          DialogueId = 800305312,
          GUID = "C8791212",
          NextDialogue = 80030533
        },
        [800305351] = {
          Content = "抱歉，因为觉得你惊慌的样子一定会很有趣，没忍住……",
          DialogueId = 800305351,
          GUID = "C87912BA",
          NextDialogue = 80030536
        },
        [800305352] = {
          Content = "不，我是真的很担心会被你抓走！",
          DialogueId = 800305352,
          GUID = "C8791362",
          NextDialogue = 80030539
        },
        [800305431] = {
          Content = "那，好吧，我答应你。",
          DialogueId = 800305431,
          GUID = "C879145E",
          NextDialogue = 80030544
        },
        [800701271] = {
          DialogueId = 800701271,
          GUID = "800701271.0",
          IsBlack = 1,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/invite/gun_kill\"},PlayAs2D{true}}"
        },
        [801001021] = {
          Content = "薄情？我做了什么了？",
          DialogueId = 801001021,
          GUID = "801001021.0",
          NextDialogue = 80100103
        },
        [801001022] = {
          Content = "没错，我就是无情的人，你要干什么？",
          DialogueId = 801001022,
          GUID = "801001022.0",
          NextDialogue = 80100104
        },
        [801001041] = {
          Content = "恋情？谁和谁的？",
          DialogueId = 801001041,
          GUID = "801001041.0",
          NextDialogue = 80100105
        },
        [801001091] = {
          Content = "你冷静一点，我们才认识没多久。",
          DialogueId = 801001091,
          GUID = "801001091.0",
          NextDialogue = 80100110
        },
        [801001092] = {
          Content = "我知道了，你在练习舞台剧，所以才会一直念诗。",
          DialogueId = 801001092,
          GUID = "801001092.0",
          NextDialogue = 80100111
        },
        [801002011] = {
          Content = "“那一面”？",
          DialogueId = 801002011,
          GUID = "801002011.0",
          NextDialogue = 80100202
        },
        [801002071] = {
          Content = "原来你也有过这样的梦想啊。",
          DialogueId = 801002071,
          GUID = "801002071.0",
          NextDialogue = 80100208
        },
        [801002072] = {
          Content = "曾经……也就是说现在已经习惯了？",
          DialogueId = 801002072,
          GUID = "801002072.0",
          NextDialogue = 80100209
        },
        [801002151] = {
          Content = "太危险了，我拒绝。",
          DialogueId = 801002151,
          GUID = "801002151.0",
          NextDialogue = 80100216
        },
        [801002152] = {
          Content = "你可以试一试。",
          DialogueId = 801002152,
          GUID = "801002152.0",
          NextDialogue = 80100217
        },
        [801002191] = {
          Content = "我不会给你这样的机会。",
          DialogueId = 801002191,
          GUID = "801002191.0",
          NextDialogue = 80100220
        },
        [801003021] = {
          Content = "我讨厌揣测别人的想法。",
          DialogueId = 801003021,
          GUID = "801003021.0",
          NextDialogue = 80100303
        },
        [801003022] = {
          Content = "有关你过去的故事？",
          DialogueId = 801003022,
          GUID = "801003022.0",
          NextDialogue = 80100305
        },
        [801003091] = {
          Content = "她在追捕你？",
          DialogueId = 801003091,
          GUID = "801003091.0",
          NextDialogue = 80100310
        },
        [801003141] = {
          Content = "我本来就被帝国通缉，罪多不压身。",
          DialogueId = 801003141,
          GUID = "801003141.0",
          NextDialogue = 80100315
        },
        [801003142] = {
          Content = "看来，我应该和你保持适当的距离。",
          DialogueId = 801003142,
          GUID = "801003142.0",
          NextDialogue = 80100327
        },
        [801003191] = {
          Content = "命定之人？",
          DialogueId = 801003191,
          GUID = "801003191.0",
          NextDialogue = 80100320
        },
        [801003221] = {
          Content = "已经听到了。",
          DialogueId = 801003221,
          GUID = "801003221.0",
          NextDialogue = 80100323
        },
        [801003222] = {
          Content = "是谁啊，要不我帮你传个信呗？",
          DialogueId = 801003222,
          GUID = "801003222.0",
          NextDialogue = 80100323
        },
        [801003321] = {
          Content = "我怎么感觉你乐在其中？",
          DialogueId = 801003321,
          GUID = "801003321.0",
          NextDialogue = 80100333
        },
        [801003331] = {
          Content = "命定之人？",
          DialogueId = 801003331,
          GUID = "801003331.0",
          NextDialogue = 80100334
        },
        [801004011] = {
          Content = "是遇到了什么烦心事吗？",
          DialogueId = 801004011,
          GUID = "801004011.0",
          NextDialogue = 80100402
        },
        [801004012] = {
          Content = "看来我邀请你的时间不合时宜。",
          DialogueId = 801004012,
          GUID = "801004012.0",
          NextDialogue = 80100403
        },
        [801004121] = {
          Content = "你在逃避真实的自己。",
          DialogueId = 801004121,
          GUID = "801004121.0",
          NextDialogue = 80100413
        },
        [801004122] = {
          Content = "演技真差！",
          DialogueId = 801004122,
          GUID = "801004122.0",
          NextDialogue = 80100415
        },
        [801101021] = {
          Content = "看来还是军团好吃好喝的太多了。",
          DialogueId = 801101021,
          GUID = "801101021.0",
          NextDialogue = 80110103
        },
        [801101051] = {
          Content = "我听说军团好像得到了一个叫“零号”的宝贝……",
          DialogueId = 801101051,
          GUID = "801101051.0",
          NextDialogue = 80110106
        },
        [801101052] = {
          Content = "你想太多了，就是单纯请你喝杯酒而已。",
          DialogueId = 801101052,
          GUID = "801101052.0",
          NextDialogue = 80110112
        },
        [801101141] = {
          Content = "原来你也做过狩月人。",
          DialogueId = 801101141,
          GUID = "801101141.0",
          NextDialogue = 80110115
        },
        [801101142] = {
          Content = "原来你是冰湖城本地人。",
          DialogueId = 801101142,
          GUID = "801101142.0",
          NextDialogue = 80110115
        },
        [801101161] = {
          Content = "你好像很害怕说错话？",
          DialogueId = 801101161,
          GUID = "801101161.0",
          NextDialogue = 80110117
        },
        [801101201] = {
          Content = "那你在军团不会觉得很拘束吗？",
          DialogueId = 801101201,
          GUID = "801101201.0",
          NextDialogue = 80110121
        },
        [801101202] = {
          Content = "看不出来，我看你还挺威风的。",
          DialogueId = 801101202,
          GUID = "801101202.0",
          NextDialogue = 80110122
        },
        [801101261] = {
          Content = "这是我可以听的吗？",
          DialogueId = 801101261,
          GUID = "801101261.0",
          NextDialogue = 80110127
        },
        [801101301] = {
          Content = "我就开个玩笑！",
          DialogueId = 801101301,
          GUID = "801101301.0",
          NextDialogue = 80110131
        },
        [801101361] = {
          Content = "这……也是我可以听的吗？",
          DialogueId = 801101361,
          GUID = "801101361.0",
          NextDialogue = 80110137
        },
        [801102021] = {
          Content = "是的。在卡米拉女士那里。",
          DialogueId = 801102021,
          GUID = "801102021.0",
          NextDialogue = 80110203
        },
        [801102031] = {
          Content = "还有杀人越货的委托？！",
          DialogueId = 801102031,
          GUID = "801102031.0",
          NextDialogue = 80110204
        },
        [801102051] = {
          Content = "不，她挺和善的。",
          DialogueId = 801102051,
          GUID = "801102051.0",
          NextDialogue = 80110206
        },
        [801102052] = {
